(1562, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 7, 'OT', 'וַתֹּ֣אמֶר אֲחֹתוֹ֮ אֶל בַּת פַּרְעֹה֒ הַאֵלֵ֗ךְ וְקָרָ֤אתִי לָךְ֙ אִשָּׁ֣ה מֵינֶ֔קֶת מִ֖ן הָעִבְרִיֹּ֑ת וְתֵינִ֥ק לָ֖ךְ אֶת הַיָּֽלֶד'),
(1563, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 8, 'OT', 'וַתֹּֽאמֶר לָ֥הּ בַּת פַּרְעֹ֖ה לֵ֑כִי וַתֵּ֨לֶךְ֙ הָֽעַלְמָ֔ה וַתִּקְרָ֖א אֶת אֵ֥ם הַיָּֽלֶד'),
(1564, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 9, 'OT', 'וַתֹּ֧אמֶר לָ֣הּ בַּת פַּרְעֹ֗ה הֵילִ֜יכִי אֶת הַיֶּ֤לֶד הַזֶּה֙ וְהֵינִקִ֣הוּ לִ֔י וַאֲנִ֖י אֶתֵּ֣ן אֶת שְׂכָרֵ֑ךְ וַתִּקַּ֧ח הָאִשָּׁ֛ה הַיֶּ֖לֶד וַתְּנִיקֵֽהוּ'),
(1565, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 10, 'OT', 'וַיִגְדַּ֣ל הַיֶּ֗לֶד וַתְּבִאֵ֨הוּ֙ לְבַת פַּרְעֹ֔ה וַֽיְהִי לָ֖הּ לְבֵ֑ן וַתִּקְרָ֤א שְׁמוֹ֙ מֹשֶׁ֔ה וַתֹּ֕אמֶר כִּ֥י מִן הַמַּ֖יִם מְשִׁיתִֽהוּ'),
(1566, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 11, 'OT', 'וַיְהִ֣י בַּיָּמִ֣ים הָהֵ֗ם וַיִּגְדַּ֤ל מֹשֶׁה֙ וַיֵּצֵ֣א אֶל אֶחָ֔יו וַיַּ֖רְא בְּסִבְלֹתָ֑ם וַיַּרְא֙ אִ֣ישׁ מִצְרִ֔י מַכֶּ֥ה אִישׁ עִבְרִ֖י מֵאֶחָֽיו'),
(1567, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 12, 'OT', 'וַיִּ֤פֶן כֹּה֙ וָכֹ֔ה וַיַּ֖רְא כִּ֣י אֵ֣ין אִ֑ישׁ וַיַּךְ֙ אֶת הַמִּצְרִ֔י וַֽיִּטְמְנֵ֖הוּ בַּחֽוֹל'),
(1568, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 13, 'OT', 'וַיֵּצֵא֙ בַּיּ֣וֹם הַשֵּׁנִ֔י וְהִנֵּ֛ה שְׁנֵֽי אֲנָשִׁ֥ים עִבְרִ֖ים נִצִּ֑ים וַיֹּ֨אמֶר֙ לָֽרָשָׁ֔ע לָ֥מָּה תַכֶּ֖ה רֵעֶֽךָ'),
(1569, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 14, 'OT', 'וַ֠יֹּאמֶר מִ֣י שָֽׂמְךָ֞ לְאִ֨ישׁ שַׂ֤ר וְשֹׁפֵט֙ עָלֵ֔ינוּ הַלְהָרְגֵ֨נִי֙ אַתָּ֣ה אֹמֵ֔ר כַּאֲשֶׁ֥ר הָרַ֖גְתָּ אֶת הַמִּצְרִ֑י וַיִּירָ֤א מֹשֶׁה֙ וַיֹּאמַ֔ר אָכֵ֖ן נוֹדַ֥ע הַדָּבָֽר'),
(1570, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 15, 'OT', 'וַיִּשְׁמַ֤ע פַּרְעֹה֙ אֶת הַדָּבָ֣ר הַזֶּ֔ה וַיְבַקֵּ֖שׁ לַהֲרֹ֣ג אֶת מֹשֶׁ֑ה וַיִּבְרַ֤ח מֹשֶׁה֙ מִפְּנֵ֣י פַרְעֹ֔ה וַיֵּ֥שֶׁב בְּאֶֽרֶץ מִדְיָ֖ן וַיֵּ֥שֶׁב עַֽל הַבְּאֵֽר'),
(1571, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 16, 'OT', 'וּלְכֹהֵ֥ן מִדְיָ֖ן שֶׁ֣בַע בָּנ֑וֹת וַתָּבֹ֣אנָה וַתִּדְלֶ֗נָה וַתְּמַלֶּ֨אנָה֙ אֶת הָ֣רְהָטִ֔ים לְהַשְׁק֖וֹת צֹ֥אן אֲבִיהֶֽן'),
(1572, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 17, 'OT', 'וַיָּבֹ֥אוּ הָרֹעִ֖ים וַיְגָרְשׁ֑וּם וַיָּ֤קָם מֹשֶׁה֙ וַיּ֣וֹשִׁעָ֔ן וַיַּ֖שְׁקְ אֶת צֹאנָֽם'),
(1573, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 18, 'OT', 'וַתָּבֹ֕אנָה אֶל רְעוּאֵ֖ל אֲבִיהֶ֑ן וַיֹּ֕אמֶר מַדּ֛וּעַ מִהַרְתֶּ֥ן בֹּ֖א הַיּֽוֹם'),
(1574, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 19, 'OT', 'וַתֹּאמַ֕רְןָ אִ֣ישׁ מִצְרִ֔י הִצִּילָ֖נוּ מִיַּ֣ד הָרֹעִ֑ים וְגַם דָּלֹ֤ה דָלָה֙ לָ֔נוּ וַיַּ֖שְׁקְ אֶת הַצֹּֽאן'),
(1575, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 20, 'OT', 'וַיֹּ֥אמֶר אֶל בְּנֹתָ֖יו וְאַיּ֑וֹ לָ֤מָּה זֶּה֙ עֲזַבְתֶּ֣ן אֶת הָאִ֔ישׁ קִרְאֶ֥ן ל֖וֹ וְיֹ֥אכַל לָֽחֶם'),
(1576, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 21, 'OT', 'וַיּ֥וֹאֶל מֹשֶׁ֖ה לָשֶׁ֣בֶת אֶת הָאִ֑ישׁ וַיִּתֵּ֛ן אֶת צִפֹּרָ֥ה בִתּ֖וֹ לְמֹשֶֽׁה'),
(1577, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 22, 'OT', 'וַתֵּ֣לֶד בֵּ֔ן וַיִּקְרָ֥א אֶת שְׁמ֖וֹ גֵּרְשֹׁ֑ם כִּ֣י אָמַ֔ר גֵּ֣ר הָיִ֔יתִי בְּאֶ֖רֶץ נָכְרִיָּֽה'),
(1578, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 23, 'OT', 'וַיְהִי֩ בַיָּמִ֨ים הָֽרַבִּ֜ים הָהֵ֗ם וַיָּ֨מָת֙ מֶ֣לֶךְ מִצְרַ֔יִם וַיֵּאָנְח֧וּ בְנֵֽי יִשְׂרָאֵ֛ל מִן הָעֲבֹדָ֖ה וַיִּזְעָ֑קוּ וַתַּ֧עַל שַׁוְעָתָ֛ם אֶל הָאֱלֹהִ֖ים מִן הָעֲבֹדָֽה'),
(1579, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 24, 'OT', 'וַיִּשְׁמַ֥ע אֱלֹהִ֖ים אֶת נַאֲקָתָ֑ם וַיִּזְכֹּ֤ר אֱלֹהִים֙ אֶת בְּרִית֔וֹ אֶת אַבְרָהָ֖ם אֶת יִצְחָ֥ק וְאֶֽת יַעֲקֹֽב'),
(1580, 2, 'WLC', 'WLC', 'he', 'EXO', 2, 25, 'OT', 'וַיַּ֥רְא אֱלֹהִ֖ים אֶת בְּנֵ֣י יִשְׂרָאֵ֑ל וַיֵּ֖דַע אֱלֹהִֽים'),
(1581, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 1, 'OT', 'וּמֹשֶׁ֗ה הָיָ֥ה רֹעֶ֛ה אֶת צֹ֛אן יִתְר֥וֹ חֹתְנ֖וֹ כֹּהֵ֣ן מִדְיָ֑ן וַיִּנְהַ֤ג אֶת הַצֹּאן֙ אַחַ֣ר הַמִּדְבָּ֔ר וַיָּבֹ֛א אֶל הַ֥ר הָאֱלֹהִ֖ים חֹרֵֽבָה'),
(1582, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 2, 'OT', 'וַ֠יֵּרָא מַלְאַ֨ךְ יְהֹוָ֥ה אֵלָ֛יו בְּלַבַּת אֵ֖שׁ מִתּ֣וֹךְ הַסְּנֶ֑ה וַיַּ֗רְא וְהִנֵּ֤ה הַסְּנֶה֙ בֹּעֵ֣ר בָּאֵ֔שׁ וְהַסְּנֶ֖ה אֵינֶ֥נּוּ אֻכָּֽל'),
(1583, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 3, 'OT', 'וַיֹּ֣אמֶר מֹשֶׁ֔ה אָסֻֽרָה נָּ֣א וְאֶרְאֶ֔ה אֶת הַמַּרְאֶ֥ה הַגָּדֹ֖ל הַזֶּ֑ה מַדּ֖וּעַ לֹא יִבְעַ֥ר הַסְּנֶֽה'),
(1584, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 4, 'OT', 'וַיַּ֥רְא יְהוָ֖ה כִּ֣י סָ֣ר לִרְא֑וֹת וַיִּקְרָא֩ אֵלָ֨יו אֱלֹהִ֜ים מִתּ֣וֹךְ הַסְּנֶ֗ה וַיֹּ֛אמֶר מֹשֶׁ֥ה מֹשֶׁ֖ה וַיֹּ֥אמֶר הִנֵּֽנִי'),
(1585, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 5, 'OT', 'וַיֹּ֖אמֶר אַל תִּקְרַ֣ב הֲלֹ֑ם שַׁל נְעָלֶ֨יךָ֙ מֵעַ֣ל רַגְלֶ֔יךָ כִּ֣י הַמָּק֗וֹם אֲשֶׁ֤ר אַתָּה֙ עוֹמֵ֣ד עָלָ֔יו אַדְמַת קֹ֖דֶשׁ הֽוּא'),
(1586, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 6, 'OT', 'וַיֹּ֗אמֶר אָנֹכִי֙ אֱלֹהֵ֣י אָבִ֔יךָ אֱלֹהֵ֧י אַבְרָהָ֛ם אֱלֹהֵ֥י יִצְחָ֖ק וֵאלֹהֵ֣י יַעֲקֹ֑ב וַיַּסְתֵּ֤ר מֹשֶׁה֙ פָּנָ֔יו כִּ֣י יָרֵ֔א מֵהַבִּ֖יט אֶל הָאֱלֹהִֽים'),
(1587, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 7, 'OT', 'וַיֹּ֣אמֶר יְהוָ֔ה רָאֹ֥ה רָאִ֛יתִי אֶת עֳנִ֥י עַמִּ֖י אֲשֶׁ֣ר בְּמִצְרָ֑יִם וְאֶת צַעֲקָתָ֤ם שָׁמַ֨עְתִּי֙ מִפְּנֵ֣י נֹֽגְשָׂ֔יו כִּ֥י יָדַ֖עְתִּי אֶת מַכְאֹבָֽיו'),
(1588, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 8, 'OT', 'וָאֵרֵ֞ד לְהַצִּיל֣וֹ מִיַּ֣ד מִצְרַ֗יִם וּֽלְהַעֲלֹתוֹ֮ מִן הָאָ֣רֶץ הַהִוא֒ אֶל אֶ֤רֶץ טוֹבָה֙ וּרְחָבָ֔ה אֶל אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּדְבָ֑שׁ אֶל מְק֤וֹם הַֽכְּנַעֲנִי֙ וְהַ֣חִתִּ֔י וְהָֽאֱמֹרִי֙ וְהַפְּרִזִּ֔י וְהַחִוִּ֖י וְהַיְבוּסִֽי'),
(1589, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 9, 'OT', 'וְעַתָּ֕ה הִנֵּ֛ה צַעֲקַ֥ת בְּנֵי יִשְׂרָאֵ֖ל בָּ֣אָה אֵלָ֑י וְגַם רָאִ֨יתִי֙ אֶת הַלַּ֔חַץ אֲשֶׁ֥ר מִצְרַ֖יִם לֹחֲצִ֥ים אֹתָֽם'),
(1590, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 10, 'OT', 'וְעַתָּ֣ה לְכָ֔ה וְאֶֽשְׁלָחֲךָ֖ אֶל פַּרְעֹ֑ה וְהוֹצֵ֛א אֶת עַמִּ֥י בְנֵֽי יִשְׂרָאֵ֖ל מִמִּצְרָֽיִם'),
(1591, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 11, 'OT', 'וַיֹּ֤אמֶר מֹשֶׁה֙ אֶל הָ֣אֱלֹהִ֔ים מִ֣י אָנֹ֔כִי כִּ֥י אֵלֵ֖ךְ אֶל פַּרְעֹ֑ה וְכִ֥י אוֹצִ֛יא אֶת בְּנֵ֥י יִשְׂרָאֵ֖ל מִמִּצְרָֽיִם'),
(1592, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 12, 'OT', 'וַיֹּ֨אמֶר֙ כִּֽי אֶֽהְיֶ֣ה עִמָּ֔ךְ וְזֶה לְּךָ֣ הָא֔וֹת כִּ֥י אָנֹכִ֖י שְׁלַחְתִּ֑יךָ בְּהוֹצִֽיאֲךָ֤ אֶת הָעָם֙ מִמִּצְרַ֔יִם תַּֽעַבְדוּן֙ אֶת הָ֣אֱלֹהִ֔ים עַ֖ל הָהָ֥ר הַזֶּֽה'),
(1593, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 13, 'OT', 'וַיֹּ֨אמֶר מֹשֶׁ֜ה אֶל הָֽאֱלֹהִ֗ים הִנֵּ֨ה אָנֹכִ֣י בָא֮ אֶל בְּנֵ֣י יִשְׂרָאֵל֒ וְאָמַרְתִּ֣י לָהֶ֔ם אֱלֹהֵ֥י אֲבוֹתֵיכֶ֖ם שְׁלָחַ֣נִי אֲלֵיכֶ֑ם וְאָֽמְרוּ לִ֣י מַה שְּׁמ֔וֹ מָ֥ה אֹמַ֖ר אֲלֵהֶֽם'),
(1594, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 14, 'OT', 'וַיֹּ֤אמֶר אֱלֹהִים֙ אֶל מֹשֶׁ֔ה אֶֽהְיֶ֖ה אֲשֶׁ֣ר אֶֽהְיֶ֑ה וַיֹּ֗אמֶר כֹּ֤ה תֹאמַר֙ לִבְנֵ֣י יִשְׂרָאֵ֔ל אֶֽהְיֶ֖ה שְׁלָחַ֥נִי אֲלֵיכֶֽם'),
(1595, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 15, 'OT', 'וַיֹּאמֶר֩ ע֨וֹד אֱלֹהִ֜ים אֶל מֹשֶׁ֗ה כֹּֽה תֹאמַר֮ אֶל בְּנֵ֣י יִשְׂרָאֵל֒ יְהוָ֞ה אֱלֹהֵ֣י אֲבֹתֵיכֶ֗ם אֱלֹהֵ֨י אַבְרָהָ֜ם אֱלֹהֵ֥י יִצְחָ֛ק וֵאלֹהֵ֥י יַעֲקֹ֖ב שְׁלָחַ֣נִי אֲלֵיכֶ֑ם זֶה שְּׁמִ֣י לְעֹלָ֔ם וְזֶ֥ה זִכְרִ֖י לְדֹ֥ר דֹּֽר'),
(1596, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 16, 'OT', 'לֵ֣ךְ וְאָֽסַפְתָּ֞ אֶת זִקְנֵ֣י יִשְׂרָאֵ֗ל וְאָמַרְתָּ֤ אֲלֵהֶם֙ יְהוָ֞ה אֱלֹהֵ֤י אֲבֹֽתֵיכֶם֙ נִרְאָ֣ה אֵלַ֔י אֱלֹהֵ֧י אַבְרָהָ֛ם יִצְחָ֥ק וְיַעֲקֹ֖ב לֵאמֹ֑ר פָּקֹ֤ד פָּקַ֨דְתִּי֙ אֶתְכֶ֔ם וְאֶת הֶעָשׂ֥וּי לָכֶ֖ם בְּמִצְרָֽיִם'),
(1597, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 17, 'OT', 'וָאֹמַ֗ר אַעֲלֶ֣ה אֶתְכֶם֮ מֵעֳנִ֣י מִצְרַיִם֒ אֶל אֶ֤רֶץ הַֽכְּנַעֲנִי֙ וְהַ֣חִתִּ֔י וְהָֽאֱמֹרִי֙ וְהַפְּרִזִּ֔י וְהַחִוִּ֖י וְהַיְבוּסִ֑י אֶל אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּדְבָֽשׁ'),
(1598, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 18, 'OT', 'וְשָׁמְע֖וּ לְקֹלֶ֑ךָ וּבָאתָ֡ אַתָּה֩ וְזִקְנֵ֨י יִשְׂרָאֵ֜ל אֶל מֶ֣לֶךְ מִצְרַ֗יִם וַאֲמַרְתֶּ֤ם אֵלָיו֙ יְהוָ֞ה אֱלֹהֵ֤י הָֽעִבְרִיִּים֙ נִקְרָ֣ה עָלֵ֔ינוּ וְעַתָּ֗ה נֵֽלֲכָה נָּ֞א דֶּ֣רֶךְ שְׁלֹ֤שֶׁת יָמִים֙ בַּמִּדְבָּ֔ר וְנִזְבְּחָ֖ה לַֽיהוָ֥ה אֱלֹהֵֽינוּ'),
(1599, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 19, 'OT', 'וַאֲנִ֣י יָדַ֔עְתִּי כִּ֠י לֹֽא יִתֵּ֥ן אֶתְכֶ֛ם מֶ֥לֶךְ מִצְרַ֖יִם לַהֲלֹ֑ךְ וְלֹ֖א בְּיָ֥ד חֲזָקָֽה'),
(1600, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 20, 'OT', 'וְשָׁלַחְתִּ֤י אֶת יָדִי֙ וְהִכֵּיתִ֣י אֶת מִצְרַ֔יִם בְּכֹל֙ נִפְלְאֹתַ֔י אֲשֶׁ֥ר אֶֽעֱשֶׂ֖ה בְּקִרְבּ֑וֹ וְאַחֲרֵי כֵ֖ן יְשַׁלַּ֥ח אֶתְכֶֽם'),
(1601, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 21, 'OT', 'וְנָתַתִּ֛י אֶת חֵ֥ן הָֽעָם הַזֶּ֖ה בְּעֵינֵ֣י מִצְרָ֑יִם וְהָיָה֙ כִּ֣י תֵֽלֵכ֔וּן לֹ֥א תֵלְכ֖וּ רֵיקָֽם'),
(1602, 2, 'WLC', 'WLC', 'he', 'EXO', 3, 22, 'OT', 'וְשָׁאֲלָ֨ה אִשָּׁ֤ה מִשְּׁכֶנְתָּהּ֙ וּמִגָּרַ֣ת בֵּיתָ֔הּ כְּלֵי כֶ֛סֶף וּכְלֵ֥י זָהָ֖ב וּשְׂמָלֹ֑ת וְשַׂמְתֶּ֗ם עַל בְּנֵיכֶם֙ וְעַל בְּנֹ֣תֵיכֶ֔ם וְנִצַּלְתֶּ֖ם אֶת מִצְרָֽיִם'),
(1603, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 1, 'OT', 'וַיַּ֤עַן מֹשֶׁה֙ וַיֹּ֔אמֶר וְהֵן֙ לֹֽא יַאֲמִ֣ינוּ לִ֔י וְלֹ֥א יִשְׁמְע֖וּ בְּקֹלִ֑י כִּ֣י יֹֽאמְר֔וּ לֹֽא נִרְאָ֥ה אֵלֶ֖יךָ יְהוָֽה'),
(1604, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 2, 'OT', 'וַיֹּ֧אמֶר אֵלָ֛יו יְהוָ֖ה מזה בְיָדֶ֑ךָ וַיֹּ֖אמֶר מַטֶּֽה'),
(1605, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 3, 'OT', 'וַיֹּ֨אמֶר֙ הַשְׁלִיכֵ֣הוּ אַ֔רְצָה וַיַּשְׁלִיכֵ֥הוּ אַ֖רְצָה וַיְהִ֣י לְנָחָ֑שׁ וַיָּ֥נָס מֹשֶׁ֖ה מִפָּנָֽיו'),
(1606, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 4, 'OT', 'וַיֹּ֤אמֶר יְהוָה֙ אֶל מֹשֶׁ֔ה שְׁלַח֙ יָֽדְךָ֔ וֶאֱחֹ֖ז בִּזְנָב֑וֹ וַיִּשְׁלַ֤ח יָדוֹ֙ וַיַּ֣חֲזֶק בּ֔וֹ וַיְהִ֥י לְמַטֶּ֖ה בְּכַפּֽוֹ'),
(1607, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 5, 'OT', 'לְמַ֣עַן יַאֲמִ֔ינוּ כִּֽי נִרְאָ֥ה אֵלֶ֛יךָ יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתָ֑ם אֱלֹהֵ֧י אַבְרָהָ֛ם אֱלֹהֵ֥י יִצְחָ֖ק וֵאלֹהֵ֥י יַעֲקֹֽב'),
(1608, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 6, 'OT', 'וַיֹּאמֶר֩ יְהוָ֨ה ל֜וֹ ע֗וֹד הָֽבֵא נָ֤א יָֽדְךָ֙ בְּחֵיקֶ֔ךָ וַיָּבֵ֥א יָד֖וֹ בְּחֵיק֑וֹ וַיּ֣וֹצִאָ֔הּ וְהִנֵּ֥ה יָד֖וֹ מְצֹרַ֥עַת כַּשָּֽׁלֶג'),
(1609, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 7, 'OT', 'וַיֹּ֗אמֶר הָשֵׁ֤ב יָֽדְךָ֙ אֶל חֵיקֶ֔ךָ וַיָּ֥שֶׁב יָד֖וֹ אֶל חֵיק֑וֹ וַיּֽוֹצִאָהּ֙ מֵֽחֵיק֔וֹ וְהִנֵּה שָׁ֖בָה כִּבְשָׂרֽוֹ'),
(1610, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 8, 'OT', 'וְהָיָה֙ אִם לֹ֣א יַאֲמִ֣ינוּ לָ֔ךְ וְלֹ֣א יִשְׁמְע֔וּ לְקֹ֖ל הָאֹ֣ת הָרִאשׁ֑וֹן וְהֶֽאֱמִ֔ינוּ לְקֹ֖ל הָאֹ֥ת הָאַחֲרֽוֹן'),
(1611, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 9, 'OT', 'וְהָיָ֡ה אִם לֹ֣א יַאֲמִ֡ינוּ גַּם֩ לִשְׁנֵ֨י הָאֹת֜וֹת הָאֵ֗לֶּה וְלֹ֤א יִשְׁמְעוּן֙ לְקֹלֶ֔ךָ וְלָקַחְתָּ֙ מִמֵּימֵ֣י הַיְאֹ֔ר וְשָׁפַכְתָּ֖ הַיַּבָּשָׁ֑ה וְהָי֤וּ הַמַּ֨יִם֙ אֲשֶׁ֣ר תִּקַּ֣ח מִן הַיְאֹ֔ר וְהָי֥וּ לְדָ֖ם בַּיַּבָּֽשֶׁת'),
(1612, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 10, 'OT', 'וַיֹּ֨אמֶר מֹשֶׁ֣ה אֶל יְהוָה֮ בִּ֣י אֲדֹנָי֒ לֹא֩ אִ֨ישׁ דְּבָרִ֜ים אָנֹ֗כִי גַּ֤ם מִתְּמוֹל֙ גַּ֣ם מִשִּׁלְשֹׁ֔ם גַּ֛ם מֵאָ֥ז דַּבֶּרְךָ אֶל עַבְדֶּ֑ךָ כִּ֧י כְבַד פֶּ֛ה וּכְבַ֥ד לָשׁ֖וֹן אָנֹֽכִי'),
(1613, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 11, 'OT', 'וַיֹּ֨אמֶר יְהוָ֜ה אֵלָ֗יו מִ֣י שָׂ֣ם פֶּה֮ לָֽאָדָם֒ א֚וֹ מִֽי יָשׂ֣וּם אִלֵּ֔ם א֣וֹ חֵרֵ֔שׁ א֥וֹ פִקֵּ֖חַ א֣וֹ עִוֵּ֑ר הֲלֹ֥א אָנֹכִ֖י יְהוָֽה'),
(1614, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 12, 'OT', 'וְעַתָּ֖ה לֵ֑ךְ וְאָנֹכִי֙ אֶֽהְיֶ֣ה עִם פִּ֔יךָ וְהוֹרֵיתִ֖יךָ אֲשֶׁ֥ר תְּדַבֵּֽר'),
(1615, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 13, 'OT', 'וַיֹּ֖אמֶר בִּ֣י אֲדֹנָ֑י שְֽׁלַֽח נָ֖א בְּיַד תִּשְׁלָֽח'),
(1616, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 14, 'OT', 'וַיִּֽחַר אַ֨ף יְהוָ֜ה בְּמֹשֶׁ֗ה וַיֹּ֨אמֶר֙ הֲלֹ֨א אַהֲרֹ֤ן אָחִ֨יךָ֙ הַלֵּוִ֔י יָדַ֕עְתִּי כִּֽי דַבֵּ֥ר יְדַבֵּ֖ר ה֑וּא וְגַ֤ם הִנֵּה הוּא֙ יֹצֵ֣א לִקְרָאתֶ֔ךָ וְרָאֲךָ֖ וְשָׂמַ֥ח בְּלִבּֽוֹ'),
(1617, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 15, 'OT', 'וְדִבַּרְתָּ֣ אֵלָ֔יו וְשַׂמְתָּ֥ אֶת הַדְּבָרִ֖ים בְּפִ֑יו וְאָנֹכִ֗י אֶֽהְיֶ֤ה עִם פִּ֨יךָ֙ וְעִם פִּ֔יהוּ וְהוֹרֵיתִ֣י אֶתְכֶ֔ם אֵ֖ת אֲשֶׁ֥ר תַּעֲשֽׂוּן'),
(1618, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 16, 'OT', 'וְדִבֶּר ה֥וּא לְךָ֖ אֶל הָעָ֑ם וְהָ֤יָה הוּא֙ יִֽהְיֶה לְּךָ֣ לְפֶ֔ה וְאַתָּ֖ה תִּֽהְיֶה לּ֥וֹ לֵֽאלֹהִֽים'),
(1619, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 17, 'OT', 'וְאֶת הַמַּטֶּ֥ה הַזֶּ֖ה תִּקַּ֣ח בְּיָדֶ֑ךָ אֲשֶׁ֥ר תַּעֲשֶׂה בּ֖וֹ אֶת הָאֹתֹֽת'),
(1620, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 18, 'OT', 'וַיֵּ֨לֶךְ מֹשֶׁ֜ה וַיָּ֣שָׁב אֶל יֶ֣תֶר חֹֽתְנ֗וֹ וַיֹּ֤אמֶר לוֹ֙ אֵ֣לֲכָה נָּ֗א וְאָשׁ֨וּבָה֙ אֶל אַחַ֣י אֲשֶׁר בְּמִצְרַ֔יִם וְאֶרְאֶ֖ה הַעוֹדָ֣ם חַיִּ֑ים וַיֹּ֧אמֶר יִתְר֛וֹ לְמֹשֶׁ֖ה לֵ֥ךְ לְשָׁלֽוֹם'),
(1621, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 19, 'OT', 'וַיֹּ֨אמֶר יְהוָ֤ה אֶל מֹשֶׁה֙ בְּמִדְיָ֔ן לֵ֖ךְ שֻׁ֣ב מִצְרָ֑יִם כִּי מֵ֨תוּ֙ כָּל הָ֣אֲנָשִׁ֔ים הַֽמְבַקְשִׁ֖ים אֶת נַפְשֶֽׁךָ'),
(1622, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 20, 'OT', 'וַיִּקַּ֨ח מֹשֶׁ֜ה אֶת אִשְׁתּ֣וֹ וְאֶת בָּנָ֗יו וַיַּרְכִּבֵם֙ עַֽל הַחֲמֹ֔ר וַיָּ֖שָׁב אַ֣רְצָה מִצְרָ֑יִם וַיִּקַּ֥ח מֹשֶׁ֛ה אֶת מַטֵּ֥ה הָאֱלֹהִ֖ים בְּיָדֽוֹ'),
(1623, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 21, 'OT', 'וַיֹּ֣אמֶר יְהוָה֮ אֶל מֹשֶׁה֒ בְּלֶכְתְּךָ֙ לָשׁ֣וּב מִצְרַ֔יְמָה רְאֵ֗ה כָּל הַמֹּֽפְתִים֙ אֲשֶׁר שַׂ֣מְתִּי בְיָדֶ֔ךָ וַעֲשִׂיתָ֖ם לִפְנֵ֣י פַרְעֹ֑ה וַאֲנִי֙ אֲחַזֵּ֣ק אֶת לִבּ֔וֹ וְלֹ֥א יְשַׁלַּ֖ח אֶת הָעָֽם'),
(1624, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 22, 'OT', 'וְאָמַרְתָּ֖ אֶל פַּרְעֹ֑ה כֹּ֚ה אָמַ֣ר יְהוָ֔ה בְּנִ֥י בְכֹרִ֖י יִשְׂרָאֵֽל'),
(1625, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 23, 'OT', 'וָאֹמַ֣ר אֵלֶ֗יךָ שַׁלַּ֤ח אֶת בְּנִי֙ וְיַֽעַבְדֵ֔נִי וַתְּמָאֵ֖ן לְשַׁלְּח֑וֹ הִנֵּה֙ אָנֹכִ֣י הֹרֵ֔ג אֶת בִּנְךָ֖ בְּכֹרֶֽךָ'),
(1626, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 24, 'OT', 'וַיְהִ֥י בַדֶּ֖רֶךְ בַּמָּל֑וֹן וַיִּפְגְּשֵׁ֣הוּ יְהוָ֔ה וַיְבַקֵּ֖שׁ הֲמִיתֽוֹ'),
(1627, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 25, 'OT', 'וַתִּקַּ֨ח צִפֹּרָ֜ה צֹ֗ר וַתִּכְרֹת֙ אֶת עָרְלַ֣ת בְּנָ֔הּ וַתַּגַּ֖ע לְרַגְלָ֑יו וַתֹּ֕אמֶר כִּ֧י חֲתַן דָּמִ֛ים אַתָּ֖ה לִֽי'),
(1628, 2, 'WLC', 'WLC', 'he', 'EXO', 4, 26, 'OT', 'וַיִּ֖רֶף מִמֶּ֑נּוּ אָ֚ז אָֽמְרָ֔ה חֲתַ֥ן דָּמִ֖ים לַמּוּלֹֽת'),
