(1772, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 29, 'OT', 'וַיֹּ֤אמֶר אֵלָיו֙ מֹשֶׁ֔ה כְּצֵאתִי֙ אֶת הָעִ֔יר אֶפְרֹ֥שׂ אֶת כַּפַּ֖י אֶל יְהוָ֑ה הַקֹּל֣וֹת יֶחְדָּל֗וּן וְהַבָּרָד֙ לֹ֣א יִֽהְיֶה ע֔וֹד לְמַ֣עַן תֵּדַ֔ע כִּ֥י לַיהוָ֖ה הָאָֽרֶץ'),
(1773, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 30, 'OT', 'וְאַתָּ֖ה וַעֲבָדֶ֑יךָ יָדַ֕עְתִּי כִּ֚י טֶ֣רֶם תִּֽירְא֔וּן מִפְּנֵ֖י יְהוָ֥ה אֱלֹהִֽים'),
(1774, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 31, 'OT', 'וְהַפִּשְׁתָּ֥ה וְהַשְּׂעֹרָ֖ה נֻכָּ֑תָה כִּ֤י הַשְּׂעֹרָה֙ אָבִ֔יב וְהַפִּשְׁתָּ֖ה גִּבְעֹֽל'),
(1775, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 32, 'OT', 'וְהַחִטָּ֥ה וְהַכֻּסֶּ֖מֶת לֹ֣א נֻכּ֑וּ כִּ֥י אֲפִילֹ֖ת הֵֽנָּה'),
(1776, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 33, 'OT', 'וַיֵּצֵ֨א מֹשֶׁ֜ה מֵעִ֤ם פַּרְעֹה֙ אֶת הָעִ֔יר וַיִּפְרֹ֥שׂ כַּפָּ֖יו אֶל יְהוָ֑ה וַֽיַּחְדְּל֤וּ הַקֹּלוֹת֙ וְהַבָּרָ֔ד וּמָטָ֖ר לֹא נִתַּ֥ךְ אָֽרְצָה'),
(1777, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 34, 'OT', 'וַיַּ֣רְא פַּרְעֹ֗ה כִּֽי חָדַ֨ל הַמָּטָ֧ר וְהַבָּרָ֛ד וְהַקֹּלֹ֖ת וַיֹּ֣סֶף לַחֲטֹ֑א וַיַּכְבֵּ֥ד לִבּ֖וֹ ה֥וּא וַעֲבָדָֽיו'),
(1778, 2, 'WLC', 'WLC', 'he', 'EXO', 9, 35, 'OT', 'וַֽיֶּחֱזַק֙ לֵ֣ב פַּרְעֹ֔ה וְלֹ֥א שִׁלַּ֖ח אֶת בְּנֵ֣י יִשְׂרָאֵ֑ל כַּאֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה בְּיַד מֹשֶֽׁה'),
(1779, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 1, 'OT', 'וַיֹּ֤אמֶר יְהוָה֙ אֶל מֹשֶׁ֔ה בֹּ֖א אֶל פַּרְעֹ֑ה כִּֽי אֲנִ֞י הִכְבַּ֤דְתִּי אֶת לִבּוֹ֙ וְאֶת לֵ֣ב עֲבָדָ֔יו לְמַ֗עַן שִׁתִ֛י אֹתֹתַ֥י אֵ֖לֶּה בְּקִרְבּֽוֹ'),
(1780, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 2, 'OT', 'וּלְמַ֡עַן תְּסַפֵּר֩ בְּאָזְנֵ֨י בִנְךָ֜ וּבֶן בִּנְךָ֗ אֵ֣ת אֲשֶׁ֤ר הִתְעַלַּ֨לְתִּי֙ בְּמִצְרַ֔יִם וְאֶת אֹתֹתַ֖י אֲשֶׁר שַׂ֣מְתִּי בָ֑ם וִֽידַעְתֶּ֖ם כִּי אֲנִ֥י יְהוָֽה'),
(1781, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 3, 'OT', 'וַיָּבֹ֨א מֹשֶׁ֣ה וְאַהֲרֹן֮ אֶל פַּרְעֹה֒ וַיֹּאמְר֣וּ אֵלָ֗יו כֹּֽה אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י הָֽעִבְרִ֔ים עַד מָתַ֣י מֵאַ֔נְתָּ לֵעָנֹ֖ת מִפָּנָ֑י שַׁלַּ֥ח עַמִּ֖י וְיַֽעַבְדֻֽנִי'),
(1782, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 4, 'OT', 'כִּ֛י אִם מָאֵ֥ן אַתָּ֖ה לְשַׁלֵּ֣חַ אֶת עַמִּ֑י הִנְנִ֨י מֵבִ֥יא מָחָ֛ר אַרְבֶּ֖ה בִּגְבֻלֶֽךָ'),
(1783, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 5, 'OT', 'וְכִסָּה֙ אֶת עֵ֣ין הָאָ֔רֶץ וְלֹ֥א יוּכַ֖ל לִרְאֹ֣ת אֶת הָאָ֑רֶץ וְאָכַ֣ל אֶת יֶ֣תֶר הַפְּלֵטָ֗ה הַנִּשְׁאֶ֤רֶת לָכֶם֙ מִן הַבָּרָ֔ד וְאָכַל֙ אֶת כָּל הָעֵ֔ץ הַצֹּמֵ֥חַ לָכֶ֖ם מִן הַשָּׂדֶֽה'),
(1784, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 6, 'OT', 'וּמָלְא֨וּ בָתֶּ֜יךָ וּבָתֵּ֣י כָל עֲבָדֶיךָ֮ וּבָתֵּ֣י כָל מִצְרַיִם֒ אֲשֶׁ֨ר לֹֽא רָא֤וּ אֲבֹתֶ֨יךָ֙ וַאֲב֣וֹת אֲבֹתֶ֔יךָ מִיּ֗וֹם הֱיוֹתָם֙ עַל הָ֣אֲדָמָ֔ה עַ֖ד הַיּ֣וֹם הַזֶּ֑ה וַיִּ֥פֶן וַיֵּצֵ֖א מֵעִ֥ם פַּרְעֹֽה'),
(1785, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 7, 'OT', 'וַיֹּאמְרוּ֩ עַבְדֵ֨י פַרְעֹ֜ה אֵלָ֗יו עַד מָתַי֙ יִהְיֶ֨ה זֶ֥ה לָ֨נוּ֙ לְמוֹקֵ֔שׁ שַׁלַּח֙ אֶת הָ֣אֲנָשִׁ֔ים וְיַֽעַבְד֖וּ אֶת יְהוָ֣ה אֱלֹהֵיהֶ֑ם הֲטֶ֣רֶם תֵּדַ֔ע כִּ֥י אָבְדָ֖ה מִצְרָֽיִם'),
(1786, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 8, 'OT', 'וַיּוּשַׁ֞ב אֶת מֹשֶׁ֤ה וְאֶֽת אַהֲרֹן֙ אֶל פַּרְעֹ֔ה וַיֹּ֣אמֶר אֲלֵהֶ֔ם לְכ֥וּ עִבְד֖וּ אֶת יְהוָ֣ה אֱלֹהֵיכֶ֑ם מִ֥י וָמִ֖י הַהֹלְכִֽים'),
(1787, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 9, 'OT', 'וַיֹּ֣אמֶר מֹשֶׁ֔ה בִּנְעָרֵ֥ינוּ וּבִזְקֵנֵ֖ינוּ נֵלֵ֑ךְ בְּבָנֵ֨ינוּ וּבִבְנוֹתֵ֜נוּ בְּצֹאנֵ֤נוּ וּבִבְקָרֵ֨נוּ֙ נֵלֵ֔ךְ כִּ֥י חַג יְהוָ֖ה לָֽנוּ'),
(1788, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 10, 'OT', 'וַיֹּ֣אמֶר אֲלֵהֶ֗ם יְהִ֨י כֵ֤ן יְהוָה֙ עִמָּכֶ֔ם כַּאֲשֶׁ֛ר אֲשַׁלַּ֥ח אֶתְכֶ֖ם וְאֶֽת טַפְּכֶ֑ם רְא֕וּ כִּ֥י רָעָ֖ה נֶ֥גֶד פְּנֵיכֶֽם'),
(1789, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 11, 'OT', 'לֹ֣א כֵ֗ן לְכֽוּ נָ֤א הַגְּבָרִים֙ וְעִבְד֣וּ אֶת יְהוָ֔ה כִּ֥י אֹתָ֖הּ אַתֶּ֣ם מְבַקְשִׁ֑ים וַיְגָ֣רֶשׁ אֹתָ֔ם מֵאֵ֖ת פְּנֵ֥י פַרְעֹֽה'),
(1790, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 12, 'OT', 'וַיֹּ֨אמֶר יְהוָ֜ה אֶל מֹשֶׁ֗ה נְטֵ֨ה יָדְךָ֜ עַל אֶ֤רֶץ מִצְרַ֨יִם֙ בָּֽאַרְבֶּ֔ה וְיַ֖עַל עַל אֶ֣רֶץ מִצְרָ֑יִם וְיֹאכַל֙ אֶת כָּל עֵ֣שֶׂב הָאָ֔רֶץ אֵ֛ת כָּל אֲשֶׁ֥ר הִשְׁאִ֖יר הַבָּרָֽד'),
(1791, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 13, 'OT', 'וַיֵּ֨ט מֹשֶׁ֣ה אֶת מַטֵּהוּ֮ עַל אֶ֣רֶץ מִצְרַיִם֒ וַֽיהוָ֗ה נִהַ֤ג ר֥וּחַ קָדִים֙ בָּאָ֔רֶץ כָּל הַיּ֥וֹם הַה֖וּא וְכָל הַלָּ֑יְלָה הַבֹּ֣קֶר הָיָ֔ה וְר֨וּחַ֙ הַקָּדִ֔ים נָשָׂ֖א אֶת הָאַרְבֶּֽה'),
(1792, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 14, 'OT', 'וַיַּ֣עַל הָֽאַרְבֶּ֗ה עַ֚ל כָּל אֶ֣רֶץ מִצְרַ֔יִם וַיָּ֕נַח בְּכֹ֖ל גְּב֣וּל מִצְרָ֑יִם כָּבֵ֣ד מְאֹ֔ד לְ֠פָנָיו לֹא הָ֨יָה כֵ֤ן אַרְבֶּה֙ כָּמֹ֔הוּ וְאַחֲרָ֖יו לֹ֥א יִֽהְיֶה כֵּֽן'),
(1793, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 15, 'OT', 'וַיְכַ֞ס אֶת עֵ֣ין כָּל הָאָרֶץ֮ וַתֶּחְשַׁ֣ךְ הָאָרֶץ֒ וַיֹּ֜אכַל אֶת כָּל עֵ֣שֶׂב הָאָ֗רֶץ וְאֵת֙ כָּל פְּרִ֣י הָעֵ֔ץ אֲשֶׁ֥ר הוֹתִ֖יר הַבָּרָ֑ד וְלֹא נוֹתַ֨ר כָּל יֶ֧רֶק בָּעֵ֛ץ וּבְעֵ֥שֶׂב הַשָּׂדֶ֖ה בְּכָל אֶ֥רֶץ מִצְרָֽיִם'),
(1794, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 16, 'OT', 'וַיְמַהֵ֣ר פַּרְעֹ֔ה לִקְרֹ֖א לְמֹשֶׁ֣ה וּֽלְאַהֲרֹ֑ן וַיֹּ֗אמֶר חָטָ֛אתִי לַיהוָ֥ה אֱלֹֽהֵיכֶ֖ם וְלָכֶֽם'),
(1795, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 17, 'OT', 'וְעַתָּ֗ה שָׂ֣א נָ֤א חַטָּאתִי֙ אַ֣ךְ הַפַּ֔עַם וְהַעְתִּ֖ירוּ לַיהוָ֣ה אֱלֹהֵיכֶ֑ם וְיָסֵר֙ מֵֽעָלַ֔י רַ֖ק אֶת הַמָּ֥וֶת הַזֶּֽה'),
(1796, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 18, 'OT', 'וַיֵּצֵ֖א מֵעִ֣ם פַּרְעֹ֑ה וַיֶּעְתַּ֖ר אֶל יְהוָֽה'),
(1797, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 19, 'OT', 'וַיַּהֲפֹ֨ךְ יְהוָ֤ה רֽוּחַ יָם֙ חָזָ֣ק מְאֹ֔ד וַיִּשָּׂא֙ אֶת הָ֣אַרְבֶּ֔ה וַיִּתְקָעֵ֖הוּ יָ֣מָּה סּ֑וּף לֹ֤א נִשְׁאַר֙ אַרְבֶּ֣ה אֶחָ֔ד בְּכֹ֖ל גְּב֥וּל מִצְרָֽיִם'),
(1798, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 20, 'OT', 'וַיְחַזֵּ֥ק יְהוָ֖ה אֶת לֵ֣ב פַּרְעֹ֑ה וְלֹ֥א שִׁלַּ֖ח אֶת בְּנֵ֥י יִשְׂרָאֵֽל'),
(1799, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 21, 'OT', 'וַיֹּ֨אמֶר יְהוָ֜ה אֶל מֹשֶׁ֗ה נְטֵ֤ה יָֽדְךָ֙ עַל הַשָּׁמַ֔יִם וִ֥יהִי חֹ֖שֶׁךְ עַל אֶ֣רֶץ מִצְרָ֑יִם וְיָמֵ֖שׁ חֹֽשֶׁךְ'),
(1800, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 22, 'OT', 'וַיֵּ֥ט מֹשֶׁ֛ה אֶת יָד֖וֹ עַל הַשָּׁמָ֑יִם וַיְהִ֧י חֹֽשֶׁךְ אֲפֵלָ֛ה בְּכָל אֶ֥רֶץ מִצְרַ֖יִם שְׁלֹ֥שֶׁת יָמִֽים'),
(1801, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 23, 'OT', 'לֹֽא רָא֞וּ אִ֣ישׁ אֶת אָחִ֗יו וְלֹא קָ֛מוּ אִ֥ישׁ מִתַּחְתָּ֖יו שְׁלֹ֣שֶׁת יָמִ֑ים וּֽלְכָל בְּנֵ֧י יִשְׂרָאֵ֛ל הָ֥יָה א֖וֹר בְּמוֹשְׁבֹתָֽם'),
(1802, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 24, 'OT', 'וַיִּקְרָ֨א פַרְעֹ֜ה אֶל מֹשֶׁ֗ה וַיֹּ֨אמֶר֙ לְכוּ֙ עִבְד֣וּ אֶת יְהוָ֔ה רַ֛ק צֹאנְכֶ֥ם וּבְקַרְכֶ֖ם יֻצָּ֑ג גַּֽם טַפְּכֶ֖ם יֵלֵ֥ךְ עִמָּכֶֽם'),
(1803, 2, 'WLC', 'WLC', 'he', 'EXO', 10, 25, 'OT', 'וַיֹּ֣אמֶר מֹשֶׁ֔ה גַּם אַתָּ֛ה תִּתֵּ֥ן בְּיָדֵ֖נוּ זְבָחִ֣ים וְעֹל֑וֹת וְעָשִׂ֖ינוּ לַיהוָ֥ה אֱלֹהֵֽינוּ'),
