(5171, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 13, 'OT', 'וַיֹּ֥אמֶר יְהוָ֖ה אֵלַ֣י לֵאמֹ֑ר רָאִ֨יתִי֙ אֶת הָעָ֣ם הַזֶּ֔ה וְהִנֵּ֥ה עַם קְשֵׁה עֹ֖רֶף הֽוּא'),
(5172, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 14, 'OT', 'הֶ֤רֶף מִמֶּ֨נִּי֙ וְאַשְׁמִידֵ֔ם וְאֶמְחֶ֣ה אֶת שְׁמָ֔ם מִתַּ֖חַת הַשָּׁמָ֑יִם וְאֶֽעֱשֶׂה֙ אֽוֹתְךָ֔ לְגוֹי עָצ֥וּם וָרָ֖ב מִמֶּֽנּוּ'),
(5173, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 15, 'OT', 'וָאֵ֗פֶן וָֽאֵרֵד֙ מִן הָהָ֔ר וְהָהָ֖ר בֹּעֵ֣ר בָּאֵ֑שׁ וּשְׁנֵי֙ לֻחֹ֣ת הַבְּרִ֔ית עַ֖ל שְׁתֵּ֥י יָדָֽי'),
(5174, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 16, 'OT', 'וָאֵ֗רֶא וְהִנֵּ֤ה חֲטָאתֶם֙ לַיהוָ֣ה אֱלֹֽהֵיכֶ֔ם עֲשִׂיתֶ֣ם לָכֶ֔ם עֵ֖גֶל מַסֵּכָ֑ה סַרְתֶּ֣ם מַהֵ֔ר מִן הַדֶּ֕רֶךְ אֲשֶׁר צִוָּ֥ה יְהוָ֖ה אֶתְכֶֽם'),
(5175, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 17, 'OT', 'וָאֶתְפֹּשׂ֙ בִּשְׁנֵ֣י הַלֻּחֹ֔ת וָֽאַשְׁלִכֵ֔ם מֵעַ֖ל שְׁתֵּ֣י יָדָ֑י וָאֲשַׁבְּרֵ֖ם לְעֵינֵיכֶֽם'),
(5176, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 18, 'OT', 'וָֽאֶתְנַפַּל֩ לִפְנֵ֨י יְהוָ֜ה כָּרִאשֹׁנָ֗ה אַרְבָּעִ֥ים יוֹם֙ וְאַרְבָּעִ֣ים לַ֔יְלָה לֶ֚חֶם לֹ֣א אָכַ֔לְתִּי וּמַ֖יִם לֹ֣א שָׁתִ֑יתִי עַ֤ל כָּל חַטַּאתְכֶם֙ אֲשֶׁ֣ר חֲטָאתֶ֔ם לַעֲשׂ֥וֹת הָרַ֛ע בְּעֵינֵ֥י יְהוָ֖ה לְהַכְעִיסֽוֹ'),
(5177, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 19, 'OT', 'כִּ֣י יָגֹ֗רְתִּי מִפְּנֵ֤י הָאַף֙ וְהַ֣חֵמָ֔ה אֲשֶׁ֨ר קָצַ֧ף יְהוָ֛ה עֲלֵיכֶ֖ם לְהַשְׁמִ֣יד אֶתְכֶ֑ם וַיִּשְׁמַ֤ע יְהוָה֙ אֵלַ֔י גַּ֖ם בַּפַּ֥עַם הַהִֽוא'),
(5178, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 20, 'OT', 'וּֽבְאַהֲרֹ֗ן הִתְאַנַּ֧ף יְהוָ֛ה מְאֹ֖ד לְהַשְׁמִיד֑וֹ וָֽאֶתְפַּלֵּ֛ל גַּם בְּעַ֥ד אַהֲרֹ֖ן בָּעֵ֥ת הַהִֽוא'),
(5179, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 21, 'OT', 'וְֽאֶת חַטַּאתְכֶ֞ם אֲשֶׁר עֲשִׂיתֶ֣ם אֶת הָעֵ֗גֶל לָקַחְתִּי֮ וָאֶשְׂרֹ֣ף אֹת֣וֹ בָּאֵשׁ֒ וָאֶכֹּ֨ת אֹת֤וֹ טָחוֹן֙ הֵיטֵ֔ב עַ֥ד אֲשֶׁר דַּ֖ק לְעָפָ֑ר וָֽאַשְׁלִךְ֙ אֶת עֲפָר֔וֹ אֶל הַנַּ֖חַל הַיֹּרֵ֥ד מִן הָהָֽר'),
(5180, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 22, 'OT', 'וּבְתַבְעֵרָה֙ וּבְמַסָּ֔ה וּבְקִבְרֹ֖ת הַֽתַּאֲוָ֑ה מַקְצִפִ֥ים הֱיִיתֶ֖ם אֶת יְהוָֽה'),
(5181, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 23, 'OT', 'וּבִשְׁלֹ֨חַ יְהוָ֜ה אֶתְכֶ֗ם מִקָּדֵ֤שׁ בַּרְנֵ֨עַ֙ לֵאמֹ֔ר עֲלוּ֙ וּרְשׁ֣וּ אֶת הָאָ֔רֶץ אֲשֶׁ֥ר נָתַ֖תִּי לָכֶ֑ם וַתַּמְר֗וּ אֶת פִּ֤י יְהוָה֙ אֱלֹ֣הֵיכֶ֔ם וְלֹ֤א הֶֽאֱמַנְתֶּם֙ ל֔וֹ וְלֹ֥א שְׁמַעְתֶּ֖ם בְּקֹלֽוֹ'),
(5182, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 24, 'OT', 'מַמְרִ֥ים הֱיִיתֶ֖ם עִם יְהוָ֑ה מִיּ֖וֹם דַּעְתִּ֥י אֶתְכֶֽם'),
(5183, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 25, 'OT', 'וָֽאֶתְנַפַּ֞ל לִפְנֵ֣י יְהוָ֗ה אֵ֣ת אַרְבָּעִ֥ים הַיּ֛וֹם וְאֶת אַרְבָּעִ֥ים הַלַּ֖יְלָה אֲשֶׁ֣ר הִתְנַפָּ֑לְתִּי כִּֽי אָמַ֥ר יְהוָ֖ה לְהַשְׁמִ֥יד אֶתְכֶֽם'),
(5184, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 26, 'OT', 'וָאֶתְפַּלֵּ֣ל אֶל יְהוָה֮ וָאֹמַר֒ אֲדֹנָ֣י יְהוִ֗ה אַל תַּשְׁחֵ֤ת עַמְּךָ֙ וְנַחֲלָ֣תְךָ֔ אֲשֶׁ֥ר פָּדִ֖יתָ בְּגָדְלֶ֑ךָ אֲשֶׁר הוֹצֵ֥אתָ מִמִּצְרַ֖יִם בְּיָ֥ד חֲזָקָֽה'),
(5185, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 27, 'OT', 'זְכֹר֙ לַעֲבָדֶ֔יךָ לְאַבְרָהָ֥ם לְיִצְחָ֖ק וּֽלְיַעֲקֹ֑ב אַל תֵּ֗פֶן אֶל קְשִׁי֙ הָעָ֣ם הַזֶּ֔ה וְאֶל רִשְׁע֖וֹ וְאֶל חַטָּאתֽוֹ'),
(5186, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 28, 'OT', 'פֶּן יֹאמְר֗וּ הָאָרֶץ֮ אֲשֶׁ֣ר הוֹצֵאתָ֣נוּ מִשָּׁם֒ מִבְּלִי֙ יְכֹ֣לֶת יְהוָ֔ה לַהֲבִיאָ֕ם אֶל הָאָ֖רֶץ אֲשֶׁר דִּבֶּ֣ר לָהֶ֑ם וּמִשִּׂנְאָת֣וֹ אוֹתָ֔ם הוֹצִיאָ֖ם לַהֲמִתָ֥ם בַּמִּדְבָּֽר'),
(5187, 5, 'WLC', 'WLC', 'he', 'DEU', 9, 29, 'OT', 'וְהֵ֥ם עַמְּךָ֖ וְנַחֲלָתֶ֑ךָ אֲשֶׁ֤ר הוֹצֵ֨אתָ֙ בְּכֹחֲךָ֣ הַגָּדֹ֔ל וּבִֽזְרֹעֲךָ֖ הַנְּטוּיָֽה'),
(5188, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 1, 'OT', 'בָּעֵ֨ת הַהִ֜וא אָמַ֧ר יְהוָ֣ה אֵלַ֗י פְּסָל לְךָ֞ שְׁנֵֽי לֻוחֹ֤ת אֲבָנִים֙ כָּרִ֣אשֹׁנִ֔ים וַעֲלֵ֥ה אֵלַ֖י הָהָ֑רָה וְעָשִׂ֥יתָ לְּךָ֖ אֲר֥וֹן עֵֽץ'),
(5189, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 2, 'OT', 'וְאֶכְתֹּב֙ עַל הַלֻּחֹ֔ת אֶת הַדְּבָרִ֔ים אֲשֶׁ֥ר הָי֛וּ עַל הַלֻּחֹ֥ת הָרִאשֹׁנִ֖ים אֲשֶׁ֣ר שִׁבַּ֑רְתָּ וְשַׂמְתָּ֖ם בָּאָרֽוֹן'),
(5190, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 3, 'OT', 'וָאַ֤עַשׂ אֲרוֹן֙ עֲצֵ֣י שִׁטִּ֔ים וָאֶפְסֹ֛ל שְׁנֵי לֻחֹ֥ת אֲבָנִ֖ים כָּרִאשֹׁנִ֑ים וָאַ֣עַל הָהָ֔רָה וּשְׁנֵ֥י הַלֻּחֹ֖ת בְּיָדִֽי'),
(5191, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 4, 'OT', 'וַיִּכְתֹּ֨ב עַֽל הַלֻּחֹ֜ת כַּמִּכְתָּ֣ב הָרִאשׁ֗וֹן אֵ֚ת עֲשֶׂ֣רֶת הַדְּבָרִ֔ים אֲשֶׁ֣ר דִּבֶּר֩ יְהוָ֨ה אֲלֵיכֶ֥ם בָּהָ֛ר מִתּ֥וֹךְ הָאֵ֖שׁ בְּי֣וֹם הַקָּהָ֑ל וַיִּתְּנֵ֥ם יְהוָ֖ה אֵלָֽי'),
(5192, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 5, 'OT', 'וָאֵ֗פֶן וָֽאֵרֵד֙ מִן הָהָ֔ר וָֽאָשִׂם֙ אֶת הַלֻּחֹ֔ת בָּאָר֖וֹן אֲשֶׁ֣ר עָשִׂ֑יתִי וַיִּ֣הְיוּ שָׁ֔ם כַּאֲשֶׁ֥ר צִוַּ֖נִי יְהוָֽה'),
(5193, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 6, 'OT', 'וּבְנֵ֣י יִשְׂרָאֵ֗ל נָֽסְע֛וּ מִבְּאֵרֹ֥ת בְּנֵי יַעֲקָ֖ן מוֹסֵרָ֑ה שָׁ֣ם מֵ֤ת אַהֲרֹן֙ וַיִּקָּבֵ֣ר שָׁ֔ם וַיְכַהֵ֛ן אֶלְעָזָ֥ר בְּנ֖וֹ תַּחְתָּֽיו'),
(5194, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 7, 'OT', 'מִשָּׁ֥ם נָסְע֖וּ הַגֻּדְגֹּ֑דָה וּמִן הַגֻּדְגֹּ֣דָה יָטְבָ֔תָה אֶ֖רֶץ נַ֥חֲלֵי מָֽיִם'),
(5195, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 8, 'OT', 'בָּעֵ֣ת הַהִ֗וא הִבְדִּ֤יל יְהוָה֙ אֶת שֵׁ֣בֶט הַלֵּוִ֔י לָשֵׂ֖את אֶת אֲר֣וֹן בְּרִית יְהוָ֑ה לַעֲמֹד֩ לִפְנֵ֨י יְהוָ֤ה לְשָֽׁרְתוֹ֙ וּלְבָרֵ֣ךְ בִּשְׁמ֔וֹ עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(5196, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 9, 'OT', 'עַל כֵּ֞ן לֹֽא הָיָ֧ה לְלֵוִ֛י חֵ֥לֶק וְנַחֲלָ֖ה עִם אֶחָ֑יו יְהוָה֙ ה֣וּא נַחֲלָת֔וֹ כַּאֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֶ֖יךָ לֽוֹ'),
(5197, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 10, 'OT', 'וְאָנֹכִ֞י עָמַ֣דְתִּי בָהָ֗ר כַּיָּמִים֙ הָרִ֣אשֹׁנִ֔ים אַרְבָּעִ֣ים י֔וֹם וְאַרְבָּעִ֖ים לָ֑יְלָה וַיִּשְׁמַ֨ע יְהוָ֜ה אֵלַ֗י גַּ֚ם בַּפַּ֣עַם הַהִ֔וא לֹא אָבָ֥ה יְהוָ֖ה הַשְׁחִיתֶֽךָ'),
(5198, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 11, 'OT', 'וַיֹּ֤אמֶר יְהוָה֙ אֵלַ֔י ק֛וּם לֵ֥ךְ לְמַסַּ֖ע לִפְנֵ֣י הָעָ֑ם וְיָבֹ֨אוּ֙ וְיִֽרְשׁ֣וּ אֶת הָאָ֔רֶץ אֲשֶׁר נִשְׁבַּ֥עְתִּי לַאֲבֹתָ֖ם לָתֵ֥ת לָהֶֽם'),
(5199, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 12, 'OT', 'וְעַתָּה֙ יִשְׂרָאֵ֔ל מָ֚ה יְהוָ֣ה אֱלֹהֶ֔יךָ שֹׁאֵ֖ל מֵעִמָּ֑ךְ כִּ֣י אִם לְ֠יִרְאָה אֶת יְהוָ֨ה אֱלֹהֶ֜יךָ לָלֶ֤כֶת בְּכָל דְּרָכָיו֙ וּלְאַהֲבָ֣ה אֹת֔וֹ וְלַֽעֲבֹד֙ אֶת יְהוָ֣ה אֱלֹהֶ֔יךָ בְּכָל לְבָבְךָ֖ וּבְכָל נַפְשֶֽׁךָ'),
(5200, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 13, 'OT', 'לִשְׁמֹ֞ר אֶת מִצְוֺ֤ת יְהוָה֙ וְאֶת חֻקֹּתָ֔יו אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּךָ֖ הַיּ֑וֹם לְט֖וֹב לָֽךְ'),
(5201, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 14, 'OT', 'הֵ֚ן לַיהוָ֣ה אֱלֹהֶ֔יךָ הַשָּׁמַ֖יִם וּשְׁמֵ֣י הַשָּׁמָ֑יִם הָאָ֖רֶץ וְכָל אֲשֶׁר בָּֽהּ'),
(5202, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 15, 'OT', 'רַ֧ק בַּאֲבֹתֶ֛יךָ חָשַׁ֥ק יְהוָ֖ה לְאַהֲבָ֣ה אוֹתָ֑ם וַיִּבְחַ֞ר בְּזַרְעָ֣ם אַחֲרֵיהֶ֗ם בָּכֶ֛ם מִכָּל הָעַמִּ֖ים כַּיּ֥וֹם הַזֶּה'),
(5203, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 16, 'OT', 'וּמַלְתֶּ֕ם אֵ֖ת עָרְלַ֣ת לְבַבְכֶ֑ם וְעָ֨רְפְּכֶ֔ם לֹ֥א תַקְשׁ֖וּ עֽוֹד'),
(5204, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 17, 'OT', 'כִּ֚י יְהוָ֣ה אֱלֹֽהֵיכֶ֔ם ה֚וּא אֱלֹהֵ֣י הָֽאֱלֹהִ֔ים וַאֲדֹנֵ֖י הָאֲדֹנִ֑ים הָאֵ֨ל הַגָּדֹ֤ל הַגִּבֹּר֙ וְהַנּוֹרָ֔א אֲשֶׁר֙ לֹא יִשָּׂ֣א פָנִ֔ים וְלֹ֥א יִקַּ֖ח שֹֽׁחַד'),
(5205, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 18, 'OT', 'עֹשֶׂ֛ה מִשְׁפַּ֥ט יָת֖וֹם וְאַלְמָנָ֑ה וְאֹהֵ֣ב גֵּ֔ר לָ֥תֶת ל֖וֹ לֶ֥חֶם וְשִׂמְלָֽה'),
(5206, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 19, 'OT', 'וַאֲהַבְתֶּ֖ם אֶת הַגֵּ֑ר כִּֽי גֵרִ֥ים הֱיִיתֶ֖ם בְּאֶ֥רֶץ מִצְרָֽיִם'),
(5207, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 20, 'OT', 'אֶת יְהוָ֧ה אֱלֹהֶ֛יךָ תִּירָ֖א אֹת֣וֹ תַעֲבֹ֑ד וּב֣וֹ תִדְבָּ֔ק וּבִשְׁמ֖וֹ תִּשָּׁבֵֽעַ'),
(5208, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 21, 'OT', 'ה֥וּא תְהִלָּתְךָ֖ וְה֣וּא אֱלֹהֶ֑יךָ אֲשֶׁר עָשָׂ֣ה אִתְּךָ֗ אֶת הַגְּדֹלֹ֤ת וְאֶת הַנּֽוֹרָאֹת֙ הָאֵ֔לֶּה אֲשֶׁ֥ר רָא֖וּ עֵינֶֽיךָ'),
(5209, 5, 'WLC', 'WLC', 'he', 'DEU', 10, 22, 'OT', 'בְּשִׁבְעִ֣ים נֶ֔פֶשׁ יָרְד֥וּ אֲבֹתֶ֖יךָ מִצְרָ֑יְמָהּ וְעַתָּ֗ה שָֽׂמְךָ֙ יְהוָ֣ה אֱלֹהֶ֔יךָ כְּכוֹכְבֵ֥י הַשָּׁמַ֖יִם לָרֹֽב'),
(5210, 5, 'WLC', 'WLC', 'he', 'DEU', 11, 1, 'OT', 'וְאָ֣הַבְתָּ֔ אֵ֖ת יְהוָ֣ה אֱלֹהֶ֑יךָ וְשָׁמַרְתָּ֣ מִשְׁמַרְתּ֗וֹ וְחֻקֹּתָ֧יו וּמִשְׁפָּטָ֛יו וּמִצְוֺתָ֖יו כָּל הַיָּמִֽים'),
