(5271, 5, 'WLC', 'WLC', 'he', 'DEU', 12, 30, 'OT', 'הִשָּׁ֣מֶר לְךָ֗ פֶּן תִּנָּקֵשׁ֙ אַחֲרֵיהֶ֔ם אַחֲרֵ֖י הִשָּׁמְדָ֣ם מִפָּנֶ֑יךָ וּפֶן תִּדְרֹ֨שׁ לֵֽאלֹהֵיהֶ֜ם לֵאמֹ֨ר אֵיכָ֨ה יַעַבְד֜וּ הַגּוֹיִ֤ם הָאֵ֨לֶּה֙ אֶת אֱלֹ֣הֵיהֶ֔ם וְאֶעֱשֶׂה כֵּ֖ן גַּם אָֽנִי'),
(5272, 5, 'WLC', 'WLC', 'he', 'DEU', 12, 31, 'OT', 'לֹא תַעֲשֶׂ֣ה כֵ֔ן לַיהוָ֖ה אֱלֹהֶ֑יךָ כִּי֩ כָּל תּוֹעֲבַ֨ת יְהוָ֜ה אֲשֶׁ֣ר שָׂנֵ֗א עָשׂוּ֙ לֵאלֹ֣הֵיהֶ֔ם כִּ֣י גַ֤ם אֶת בְּנֵיהֶם֙ וְאֶת בְּנֹ֣תֵיהֶ֔ם יִשְׂרְפ֥וּ בָאֵ֖שׁ לֵֽאלֹהֵיהֶֽם'),
(5273, 5, 'WLC', 'WLC', 'he', 'DEU', 12, 32, 'OT', 'אֵ֣ת כָּל הַדָּבָ֗ר אֲשֶׁ֤ר אָנֹכִי֙ מְצַוֶּ֣ה אֶתְכֶ֔ם אֹת֥וֹ תִשְׁמְר֖וּ לַעֲשׂ֑וֹת לֹא תֹסֵ֣ף עָלָ֔יו וְלֹ֥א תִגְרַ֖ע מִמֶּֽנּוּ'),
(5274, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 1, 'OT', 'כִּֽי יָק֤וּם בְּקִרְבְּךָ֙ נָבִ֔יא א֖וֹ חֹלֵ֣ם חֲל֑וֹם וְנָתַ֥ן אֵלֶ֛יךָ א֖וֹת א֥וֹ מוֹפֵֽת'),
(5275, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 2, 'OT', 'וּבָ֤א הָאוֹת֙ וְהַמּוֹפֵ֔ת אֲשֶׁר דִּבֶּ֥ר אֵלֶ֖יךָ לֵאמֹ֑ר נֵֽלְכָ֞ה אַחֲרֵ֨י אֱלֹהִ֧ים אֲחֵרִ֛ים אֲשֶׁ֥ר לֹֽא יְדַעְתָּ֖ם וְנָֽעָבְדֵֽם'),
(5276, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 3, 'OT', 'לֹ֣א תִשְׁמַ֗ע אֶל דִּבְרֵי֙ הַנָּבִ֣יא הַה֔וּא א֛וֹ אֶל חוֹלֵ֥ם הַחֲל֖וֹם הַה֑וּא כִּ֣י מְנַסֶּ֞ה יְהוָ֤ה אֱלֹֽהֵיכֶם֙ אֶתְכֶ֔ם לָדַ֗עַת הֲיִשְׁכֶ֤ם אֹֽהֲבִים֙ אֶת יְהוָ֣ה אֱלֹהֵיכֶ֔ם בְּכָל לְבַבְכֶ֖ם וּבְכָל נַפְשְׁכֶֽם'),
(5277, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 4, 'OT', 'אַחֲרֵ֨י יְהוָ֧ה אֱלֹהֵיכֶ֛ם תֵּלֵ֖כוּ וְאֹת֣וֹ תִירָ֑אוּ וְאֶת מִצְוֺתָ֤יו תִּשְׁמֹ֨רוּ֙ וּבְקֹל֣וֹ תִשְׁמָ֔עוּ וְאֹת֥וֹ תַעֲבֹ֖דוּ וּב֥וֹ תִדְבָּקֽוּן'),
(5278, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 5, 'OT', 'וְהַנָּבִ֣יא הַה֡וּא א֣וֹ חֹלֵם֩ הַחֲל֨וֹם הַה֜וּא יוּמָ֗ת כִּ֣י דִבֶּר סָ֠רָה עַל יְהוָ֨ה אֱלֹֽהֵיכֶ֜ם הַמּוֹצִ֥יא אֶתְכֶ֣ם מֵאֶ֣רֶץ מִצְרַ֗יִם וְהַפֹּֽדְךָ֙ מִבֵּ֣ית עֲבָדִ֔ים לְהַדִּֽיחֲךָ֙ מִן הַדֶּ֔רֶךְ אֲשֶׁ֧ר צִוְּךָ֛ יְהוָ֥ה אֱלֹהֶ֖יךָ לָלֶ֣כֶת בָּ֑הּ וּבִֽעַרְתָּ֥ הָרָ֖ע מִקִּרְבֶּֽךָ'),
(5279, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 6, 'OT', 'כִּ֣י יְסִֽיתְךָ֡ אָחִ֣יךָ בֶן אִ֠מֶּךָ אֽוֹ בִנְךָ֨ אֽוֹ בִתְּךָ֜ א֣וֹ אֵ֣שֶׁת חֵיקֶ֗ךָ א֧וֹ רֵֽעֲךָ֛ אֲשֶׁ֥ר כְּנַפְשְׁךָ֖ בַּסֵּ֣תֶר לֵאמֹ֑ר נֵֽלְכָ֗ה וְנַֽעַבְדָה֙ אֱלֹהִ֣ים אֲחֵרִ֔ים אֲשֶׁר֙ לֹ֣א יָדַ֔עְתָּ אַתָּ֖ה וַאֲבֹתֶֽיךָ'),
(5280, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 7, 'OT', 'מֵאֱלֹהֵ֣י הָֽעַמִּ֗ים אֲשֶׁר֙ סְבִיבֹ֣תֵיכֶ֔ם הַקְּרֹבִ֣ים אֵלֶ֔יךָ א֖וֹ הָרְחֹקִ֣ים מִמֶּ֑ךָּ מִקְצֵ֥ה הָאָ֖רֶץ וְעַד קְצֵ֥ה הָאָֽרֶץ'),
(5281, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 8, 'OT', 'לֹא תֹאבֶ֣ה ל֔וֹ וְלֹ֥א תִשְׁמַ֖ע אֵלָ֑יו וְלֹא תָח֤וֹס עֵֽינְךָ֙ עָלָ֔יו וְלֹֽא תַחְמֹ֥ל וְלֹֽא תְכַסֶּ֖ה עָלָֽיו'),
(5282, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 9, 'OT', 'כִּ֤י הָרֹג֙ תַּֽהַרְגֶ֔נּוּ יָֽדְךָ֛ תִּֽהְיֶה בּ֥וֹ בָרִֽאשׁוֹנָ֖ה לַהֲמִית֑וֹ וְיַ֥ד כָּל הָעָ֖ם בָּאַחֲרֹנָֽה'),
(5283, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 10, 'OT', 'וּסְקַלְתּ֥וֹ בָאֲבָנִ֖ים וָמֵ֑ת כִּ֣י בִקֵּ֗שׁ לְהַדִּֽיחֲךָ֙ מֵעַל֙ יְהוָ֣ה אֱלֹהֶ֔יךָ הַמּוֹצִיאֲךָ֛ מֵאֶ֥רֶץ מִצְרַ֖יִם מִבֵּ֥ית עֲבָדִֽים'),
(5284, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 11, 'OT', 'וְכָל יִשְׂרָאֵ֔ל יִשְׁמְע֖וּ וְיִֽרָא֑וּן וְלֹֽא יוֹסִ֣פוּ לַעֲשׂ֗וֹת כַּדָּבָ֥ר הָרָ֛ע הַזֶּ֖ה בְּקִרְבֶּֽךָ'),
(5285, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 12, 'OT', 'כִּֽי תִשְׁמַ֞ע בְּאַחַ֣ת עָרֶ֗יךָ אֲשֶׁר֩ יְהוָ֨ה אֱלֹהֶ֜יךָ נֹתֵ֥ן לְךָ֛ לָשֶׁ֥בֶת שָׁ֖ם לֵאמֹֽר'),
(5286, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 13, 'OT', 'יָצְא֞וּ אֲנָשִׁ֤ים בְּנֵֽי בְלִיַּ֨עַל֙ מִקִּרְבֶּ֔ךָ וַיַּדִּ֛יחוּ אֶת יֹשְׁבֵ֥י עִירָ֖ם לֵאמֹ֑ר נֵלְכָ֗ה וְנַעַבְדָ֛ה אֱלֹהִ֥ים אֲחֵרִ֖ים אֲשֶׁ֥ר לֹא יְדַעְתֶּֽם'),
(5287, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 14, 'OT', 'וְדָרַשְׁתָּ֧ וְחָקַרְתָּ֧ וְשָׁאַלְתָּ֖ הֵיטֵ֑ב וְהִנֵּ֤ה אֱמֶת֙ נָכ֣וֹן הַדָּבָ֔ר נֶעֶשְׂתָ֛ה הַתּוֹעֵבָ֥ה הַזֹּ֖את בְּקִרְבֶּֽךָ'),
(5288, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 15, 'OT', 'הַכֵּ֣ה תַכֶּ֗ה אֶת יֹֽשְׁבֵ֛י הָעִ֥יר ההוא לְפִי חָ֑רֶב הַחֲרֵ֨ם אֹתָ֧הּ וְאֶת כָּל אֲשֶׁר בָּ֛הּ וְאֶת בְּהֶמְתָּ֖הּ לְפִי חָֽרֶב'),
(5289, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 16, 'OT', 'וְאֶת כָּל שְׁלָלָ֗הּ תִּקְבֹּץ֮ אֶל תּ֣וֹךְ רְחֹבָהּ֒ וְשָׂרַפְתָּ֨ בָאֵ֜שׁ אֶת הָעִ֤יר וְאֶת כָּל שְׁלָלָהּ֙ כָּלִ֔יל לַיהוָ֖ה אֱלֹהֶ֑יךָ וְהָיְתָה֙ תֵּ֣ל עוֹלָ֔ם לֹ֥א תִבָּנֶ֖ה עֽוֹד'),
(5290, 5, 'WLC', 'WLC', 'he', 'DEU', 13, 17, 'OT', 'וְלֹֽא יִדְבַּ֧ק בְּיָדְךָ֛ מְא֖וּמָה מִן הַחֵ֑רֶם לְמַעַן֩ יָשׁ֨וּב יְהוָ֜ה מֵחֲר֣וֹן אַפּ֗וֹ וְנָֽתַן לְךָ֤ רַחֲמִים֙ וְרִֽחַמְךָ֣ וְהִרְבֶּ֔ךָ כַּאֲשֶׁ֥ר נִשְׁבַּ֖ע לַאֲבֹתֶֽיךָ'),
