(5364, 5, 'WLC', 'WLC', 'he', 'DEU', 16, 21, 'OT', 'לֹֽא תִטַּ֥ע לְךָ֛ אֲשֵׁרָ֖ה כָּל עֵ֑ץ אֵ֗צֶל מִזְבַּ֛ח יְהוָ֥ה אֱלֹהֶ֖יךָ אֲשֶׁ֥ר תַּעֲשֶׂה לָּֽךְ'),
(5365, 5, 'WLC', 'WLC', 'he', 'DEU', 16, 22, 'OT', 'וְלֹֽא תָקִ֥ים לְךָ֖ מַצֵּבָ֑ה אֲשֶׁ֥ר שָׂנֵ֖א יְהוָ֥ה אֱלֹהֶֽיךָ'),
(5366, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 1, 'OT', 'לֹא תִזְבַּח֩ לַיהוָ֨ה אֱלֹהֶ֜יךָ שׁ֣וֹר וָשֶׂ֗ה אֲשֶׁ֨ר יִהְיֶ֥ה בוֹ֙ מ֔וּם כֹּ֖ל דָּבָ֣ר רָ֑ע כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖יךָ הֽוּא'),
(5367, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 2, 'OT', 'כִּֽי יִמָּצֵ֤א בְקִרְבְּךָ֙ בְּאַחַ֣ד שְׁעָרֶ֔יךָ אֲשֶׁר יְהוָ֥ה אֱלֹהֶ֖יךָ נֹתֵ֣ן לָ֑ךְ אִ֣ישׁ אוֹ אִשָּׁ֗ה אֲשֶׁ֨ר יַעֲשֶׂ֧ה אֶת הָרַ֛ע בְּעֵינֵ֥י יְהוָֽה אֱלֹהֶ֖יךָ לַעֲבֹ֥ר בְּרִיתֽוֹ'),
(5368, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 3, 'OT', 'וַיֵּ֗לֶךְ וַֽיַּעֲבֹד֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַיִּשְׁתַּ֖חוּ לָהֶ֑ם וְלַשֶּׁ֣מֶשׁ א֣וֹ לַיָּרֵ֗חַ א֛וֹ לְכָל צְבָ֥א הַשָּׁמַ֖יִם אֲשֶׁ֥ר לֹא צִוִּֽיתִי'),
(5369, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 4, 'OT', 'וְהֻֽגַּד לְךָ֖ וְשָׁמָ֑עְתָּ וְדָרַשְׁתָּ֣ הֵיטֵ֔ב וְהִנֵּ֤ה אֱמֶת֙ נָכ֣וֹן הַדָּבָ֔ר נֶעֶשְׂתָ֛ה הַתּוֹעֵבָ֥ה הַזֹּ֖את בְּיִשְׂרָאֵֽל'),
(5370, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 5, 'OT', 'וְהֽוֹצֵאתָ֣ אֶת הָאִ֣ישׁ הַה֡וּא אוֹ֩ אֶת הָאִשָּׁ֨ה הַהִ֜וא אֲשֶׁ֣ר עָ֠שׂוּ אֶת הַדָּבָ֨ר הָרָ֤ע הַזֶּה֙ אֶל שְׁעָרֶ֔יךָ אֶת הָאִ֕ישׁ א֖וֹ אֶת הָאִשָּׁ֑ה וּסְקַלְתָּ֥ם בָּאֲבָנִ֖ים וָמֵֽתוּ'),
(5371, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 6, 'OT', 'עַל פִּ֣י שְׁנַ֣יִם עֵדִ֗ים א֛וֹ שְׁלֹשָׁ֥ה עֵדִ֖ים יוּמַ֣ת הַמֵּ֑ת לֹ֣א יוּמַ֔ת עַל פִּ֖י עֵ֥ד אֶחָֽד'),
(5372, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 7, 'OT', 'יַ֣ד הָעֵדִ֞ים תִּֽהְיֶה בּ֤וֹ בָרִאשֹׁנָה֙ לַהֲמִית֔וֹ וְיַ֥ד כָּל הָעָ֖ם בָּאַחֲרֹנָ֑ה וּבִֽעַרְתָּ֥ הָרָ֖ע מִקִּרְבֶּֽךָ'),
(5373, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 8, 'OT', 'כִּ֣י יִפָּלֵא֩ מִמְּךָ֨ דָבָ֜ר לַמִּשְׁפָּ֗ט בֵּֽין דָּ֨ם לְדָ֜ם בֵּֽין דִּ֣ין לְדִ֗ין וּבֵ֥ין נֶ֨גַע֙ לָנֶ֔גַע דִּבְרֵ֥י רִיבֹ֖ת בִּשְׁעָרֶ֑יךָ וְקַמְתָּ֣ וְעָלִ֔יתָ אֶל הַמָּק֔וֹם אֲשֶׁ֥ר יִבְחַ֛ר יְהוָ֥ה אֱלֹהֶ֖יךָ בּֽוֹ'),
(5374, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 9, 'OT', 'וּבָאתָ֗ אֶל הַכֹּהֲנִים֙ הַלְוִיִּ֔ם וְאֶל הַשֹּׁפֵ֔ט אֲשֶׁ֥ר יִהְיֶ֖ה בַּיָּמִ֣ים הָהֵ֑ם וְדָרַשְׁתָּ֙ וְהִגִּ֣ידוּ לְךָ֔ אֵ֖ת דְּבַ֥ר הַמִּשְׁפָּֽט'),
(5375, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 10, 'OT', 'וְעָשִׂ֗יתָ עַל פִּ֤י הַדָּבָר֙ אֲשֶׁ֣ר יַגִּ֣ידֽוּ לְךָ֔ מִן הַמָּק֣וֹם הַה֔וּא אֲשֶׁ֖ר יִבְחַ֣ר יְהוָ֑ה וְשָׁמַרְתָּ֣ לַעֲשׂ֔וֹת כְּכֹ֖ל אֲשֶׁ֥ר יוֹרֽוּךָ'),
(5376, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 11, 'OT', 'עַל פִּ֨י הַתּוֹרָ֜ה אֲשֶׁ֣ר יוֹר֗וּךָ וְעַל הַמִּשְׁפָּ֛ט אֲשֶׁר יֹאמְר֥וּ לְךָ֖ תַּעֲשֶׂ֑ה לֹ֣א תָס֗וּר מִן הַדָּבָ֛ר אֲשֶׁר יַגִּ֥ידֽוּ לְךָ֖ יָמִ֥ין וּשְׂמֹֽאל'),
(5377, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 12, 'OT', 'וְהָאִ֞ישׁ אֲשֶׁר יַעֲשֶׂ֣ה בְזָד֗וֹן לְבִלְתִּ֨י שְׁמֹ֤עַ אֶל הַכֹּהֵן֙ הָעֹמֵ֞ד לְשָׁ֤רֶת שָׁם֙ אֶת יְהוָ֣ה אֱלֹהֶ֔יךָ א֖וֹ אֶל הַשֹּׁפֵ֑ט וּמֵת֙ הָאִ֣ישׁ הַה֔וּא וּבִֽעַרְתָּ֥ הָרָ֖ע מִיִּשְׂרָאֵֽל'),
(5378, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 13, 'OT', 'וְכָל הָעָ֖ם יִשְׁמְע֣וּ וְיִרָ֑אוּ וְלֹ֥א יְזִיד֖וּן עֽוֹד'),
(5379, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 14, 'OT', 'כִּֽי תָבֹ֣א אֶל הָאָ֗רֶץ אֲשֶׁ֨ר יְהוָ֤ה אֱלֹהֶ֨יךָ֙ נֹתֵ֣ן לָ֔ךְ וִֽירִשְׁתָּ֖הּ וְיָשַׁ֣בְתָּה בָּ֑הּ וְאָמַרְתָּ֗ אָשִׂ֤ימָה עָלַי֙ מֶ֔לֶךְ כְּכָל הַגּוֹיִ֖ם אֲשֶׁ֥ר סְבִיבֹתָֽי'),
(5380, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 15, 'OT', 'שׂ֣וֹם תָּשִׂ֤ים עָלֶ֨יךָ֙ מֶ֔לֶךְ אֲשֶׁ֥ר יִבְחַ֛ר יְהוָ֥ה אֱלֹהֶ֖יךָ בּ֑וֹ מִקֶּ֣רֶב אַחֶ֗יךָ תָּשִׂ֤ים עָלֶ֨יךָ֙ מֶ֔לֶךְ לֹ֣א תוּכַ֗ל לָתֵ֤ת עָלֶ֨יךָ֙ אִ֣ישׁ נָכְרִ֔י אֲשֶׁ֥ר לֹֽא אָחִ֖יךָ הֽוּא'),
(5381, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 16, 'OT', 'רַק֮ לֹא יַרְבֶּה לּ֣וֹ סוּסִים֒ וְלֹֽא יָשִׁ֤יב אֶת הָעָם֙ מִצְרַ֔יְמָה לְמַ֖עַן הַרְבּ֣וֹת ס֑וּס וַֽיהוָה֙ אָמַ֣ר לָכֶ֔ם לֹ֣א תֹסִפ֗וּן לָשׁ֛וּב בַּדֶּ֥רֶךְ הַזֶּ֖ה עֽוֹד'),
(5382, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 17, 'OT', 'וְלֹ֤א יַרְבֶּה לּוֹ֙ נָשִׁ֔ים וְלֹ֥א יָס֖וּר לְבָב֑וֹ וְכֶ֣סֶף וְזָהָ֔ב לֹ֥א יַרְבֶּה לּ֖וֹ מְאֹֽד'),
(5383, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 18, 'OT', 'וְהָיָ֣ה כְשִׁבְתּ֔וֹ עַ֖ל כִּסֵּ֣א מַמְלַכְתּ֑וֹ וְכָ֨תַב ל֜וֹ אֶת מִשְׁנֵ֨ה הַתּוֹרָ֤ה הַזֹּאת֙ עַל סֵ֔פֶר מִלִּפְנֵ֥י הַכֹּהֲנִ֖ים הַלְוִיִּֽם'),
(5384, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 19, 'OT', 'וְהָיְתָ֣ה עִמּ֔וֹ וְקָ֥רָא ב֖וֹ כָּל יְמֵ֣י חַיָּ֑יו לְמַ֣עַן יִלְמַ֗ד לְיִרְאָה֙ אֶת יְהוָ֣ה אֱלֹהָ֔יו לִ֠שְׁמֹר אֶֽת כָּל דִּבְרֵ֞י הַתּוֹרָ֥ה הַזֹּ֛את וְאֶת הַחֻקִּ֥ים הָאֵ֖לֶּה לַעֲשֹׂתָֽם'),
(5385, 5, 'WLC', 'WLC', 'he', 'DEU', 17, 20, 'OT', 'לְבִלְתִּ֤י רוּם לְבָבוֹ֙ מֵֽאֶחָ֔יו וּלְבִלְתִּ֛י ס֥וּר מִן הַמִּצְוָ֖ה יָמִ֣ין וּשְׂמֹ֑אול לְמַעַן֩ יַאֲרִ֨יךְ יָמִ֧ים עַל מַמְלַכְתּ֛וֹ ה֥וּא וּבָנָ֖יו בְּקֶ֥רֶב יִשְׂרָאֵֽל'),
(5386, 5, 'WLC', 'WLC', 'he', 'DEU', 18, 1, 'OT', 'לֹֽא יִ֠הְיֶה לַכֹּהֲנִ֨ים הַלְוִיִּ֜ם כָּל שֵׁ֧בֶט לֵוִ֛י חֵ֥לֶק וְנַחֲלָ֖ה עִם יִשְׂרָאֵ֑ל אִשֵּׁ֧י יְהוָ֛ה וְנַחֲלָת֖וֹ יֹאכֵלֽוּן'),
