(5553, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 5, 'OT', 'כִּֽי יֵשְׁב֨וּ אַחִ֜ים יַחְדָּ֗ו וּמֵ֨ת אַחַ֤ד מֵהֶם֙ וּבֵ֣ן אֵֽין ל֔וֹ לֹֽא תִהְיֶ֧ה אֵֽשֶׁת הַמֵּ֛ת הַח֖וּצָה לְאִ֣ישׁ זָ֑ר יְבָמָהּ֙ יָבֹ֣א עָלֶ֔יהָ וּלְקָחָ֥הּ ל֛וֹ לְאִשָּׁ֖ה וְיִבְּמָֽהּ'),
(5554, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 6, 'OT', 'וְהָיָ֗ה הַבְּכוֹר֙ אֲשֶׁ֣ר תֵּלֵ֔ד יָק֕וּם עַל שֵׁ֥ם אָחִ֖יו הַמֵּ֑ת וְלֹֽא יִמָּחֶ֥ה שְׁמ֖וֹ מִיִּשְׂרָאֵֽל'),
(5555, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 7, 'OT', 'וְאִם לֹ֤א יַחְפֹּץ֙ הָאִ֔ישׁ לָקַ֖חַת אֶת יְבִמְתּ֑וֹ וְעָלְתָה֩ יְבִמְתּ֨וֹ הַשַּׁ֜עְרָה אֶל הַזְּקֵנִ֗ים וְאָֽמְרָה֙ מֵאֵ֨ין יְבָמִ֜י לְהָקִ֨ים לְאָחִ֥יו שֵׁם֙ בְּיִשְׂרָאֵ֔ל לֹ֥א אָבָ֖ה יַבְּמִֽי'),
(5556, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 8, 'OT', 'וְקָֽרְאוּ ל֥וֹ זִקְנֵי עִיר֖וֹ וְדִבְּר֣וּ אֵלָ֑יו וְעָמַ֣ד וְאָמַ֔ר לֹ֥א חָפַ֖צְתִּי לְקַחְתָּֽהּ'),
(5557, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 9, 'OT', 'וְנִגְּשָׁ֨ה יְבִמְתּ֣וֹ אֵלָיו֮ לְעֵינֵ֣י הַזְּקֵנִים֒ וְחָלְצָ֤ה נַעֲלוֹ֙ מֵעַ֣ל רַגְל֔וֹ וְיָרְקָ֖ה בְּפָנָ֑יו וְעָֽנְתָה֙ וְאָ֣מְרָ֔ה כָּ֚כָה יֵעָשֶׂ֣ה לָאִ֔ישׁ אֲשֶׁ֥ר לֹא יִבְנֶ֖ה אֶת בֵּ֥ית אָחִֽיו'),
(5558, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 10, 'OT', 'וְנִקְרָ֥א שְׁמ֖וֹ בְּיִשְׂרָאֵ֑ל בֵּ֖ית חֲל֥וּץ הַנָּֽעַל'),
(5559, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 11, 'OT', 'כִּֽי יִנָּצ֨וּ אֲנָשִׁ֤ים יַחְדָּו֙ אִ֣ישׁ וְאָחִ֔יו וְקָֽרְבָה֙ אֵ֣שֶׁת הָֽאֶחָ֔ד לְהַצִּ֥יל אֶת אִישָׁ֖הּ מִיַּ֣ד מַכֵּ֑הוּ וְשָׁלְחָ֣ה יָדָ֔הּ וְהֶחֱזִ֖יקָה בִּמְבֻשָֽׁיו'),
(5560, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 12, 'OT', 'וְקַצֹּתָ֖ה אֶת כַּפָּ֑הּ לֹ֥א תָח֖וֹס עֵינֶֽךָ'),
(5561, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 13, 'OT', 'לֹֽא יִהְיֶ֥ה לְךָ֛ בְּכִֽיסְךָ֖ אֶ֣בֶן וָאָ֑בֶן גְּדוֹלָ֖ה וּקְטַנָּֽה'),
(5562, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 14, 'OT', 'לֹא יִהְיֶ֥ה לְךָ֛ בְּבֵיתְךָ֖ אֵיפָ֣ה וְאֵיפָ֑ה גְּדוֹלָ֖ה וּקְטַנָּֽה'),
(5563, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 15, 'OT', 'אֶ֣בֶן שְׁלֵמָ֤ה וָצֶ֨דֶק֙ יִֽהְיֶה לָּ֔ךְ אֵיפָ֧ה שְׁלֵמָ֛ה וָצֶ֖דֶק יִֽהְיֶה לָּ֑ךְ לְמַ֨עַן֙ יַאֲרִ֣יכוּ יָמֶ֔יךָ עַ֚ל הָֽאֲדָמָ֔ה אֲשֶׁר יְהוָ֥ה אֱלֹהֶ֖יךָ נֹתֵ֥ן לָֽךְ'),
(5564, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 16, 'OT', 'כִּ֧י תוֹעֲבַ֛ת יְהוָ֥ה אֱלֹהֶ֖יךָ כָּל עֹ֣שֵׂה אֵ֑לֶּה כֹּ֖ל עֹ֥שֵׂה עָֽוֶל'),
(5565, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 17, 'OT', 'זָכ֕וֹר אֵ֛ת אֲשֶׁר עָשָׂ֥ה לְךָ֖ עֲמָלֵ֑ק בַּדֶּ֖רֶךְ בְּצֵאתְכֶ֥ם מִמִּצְרָֽיִם'),
(5566, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 18, 'OT', 'אֲשֶׁ֨ר קָֽרְךָ֜ בַּדֶּ֗רֶךְ וַיְזַנֵּ֤ב בְּךָ֙ כָּל הַנֶּחֱשָׁלִ֣ים אַֽחַרֶ֔יךָ וְאַתָּ֖ה עָיֵ֣ף וְיָגֵ֑עַ וְלֹ֥א יָרֵ֖א אֱלֹהִֽים'),
(5567, 5, 'WLC', 'WLC', 'he', 'DEU', 25, 19, 'OT', 'וְהָיָ֡ה בְּהָנִ֣יחַ יְהוָ֣ה אֱלֹהֶ֣יךָ לְ֠ךָ מִכָּל אֹ֨יְבֶ֜יךָ מִסָּבִ֗יב בָּאָ֨רֶץ֙ אֲשֶׁ֣ר יְהוָֽה אֱ֠לֹהֶיךָ נֹתֵ֨ן לְךָ֤ נַחֲלָה֙ לְרִשְׁתָּ֔הּ תִּמְחֶה֙ אֶת זֵ֣כֶר עֲמָלֵ֔ק מִתַּ֖חַת הַשָּׁמָ֑יִם לֹ֖א תִּשְׁכָּֽח'),
(5568, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 1, 'OT', 'וְהָיָה֙ כִּֽי תָב֣וֹא אֶל הָאָ֔רֶץ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔יךָ נֹתֵ֥ן לְךָ֖ נַחֲלָ֑ה וִֽירִשְׁתָּ֖הּ וְיָשַׁ֥בְתָּ בָּֽהּ'),
(5569, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 2, 'OT', 'וְלָקַחְתָּ֞ מֵרֵאשִׁ֣ית כָּל פְּרִ֣י הָאֲדָמָ֗ה אֲשֶׁ֨ר תָּבִ֧יא מֵֽאַרְצְךָ֛ אֲשֶׁ֨ר יְהוָ֧ה אֱלֹהֶ֛יךָ נֹתֵ֥ן לָ֖ךְ וְשַׂמְתָּ֣ בַטֶּ֑נֶא וְהָֽלַכְתָּ֙ אֶל הַמָּק֔וֹם אֲשֶׁ֤ר יִבְחַר֙ יְהוָ֣ה אֱלֹהֶ֔יךָ לְשַׁכֵּ֥ן שְׁמ֖וֹ שָֽׁם'),
(5570, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 3, 'OT', 'וּבָאתָ֙ אֶל הַכֹּהֵ֔ן אֲשֶׁ֥ר יִהְיֶ֖ה בַּיָּמִ֣ים הָהֵ֑ם וְאָמַרְתָּ֣ אֵלָ֗יו הִגַּ֤דְתִּי הַיּוֹם֙ לַיהוָ֣ה אֱלֹהֶ֔יךָ כִּי בָ֨אתִי֙ אֶל הָאָ֔רֶץ אֲשֶׁ֨ר נִשְׁבַּ֧ע יְהוָ֛ה לַאֲבֹתֵ֖ינוּ לָ֥תֶת לָֽנוּ'),
(5571, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 4, 'OT', 'וְלָקַ֧ח הַכֹּהֵ֛ן הַטֶּ֖נֶא מִיָּדֶ֑ךָ וְהִ֨נִּיח֔וֹ לִפְנֵ֕י מִזְבַּ֖ח יְהוָ֥ה אֱלֹהֶֽיךָ'),
(5572, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 5, 'OT', 'וְעָנִ֨יתָ וְאָמַרְתָּ֜ לִפְנֵ֣י יְהוָ֣ה אֱלֹהֶ֗יךָ אֲרַמִּי֙ אֹבֵ֣ד אָבִ֔י וַיֵּ֣רֶד מִצְרַ֔יְמָה וַיָּ֥גָר שָׁ֖ם בִּמְתֵ֣י מְעָ֑ט וַֽיְהִי שָׁ֕ם לְג֥וֹי גָּד֖וֹל עָצ֥וּם וָרָֽב'),
(5573, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 6, 'OT', 'וַיָּרֵ֧עוּ אֹתָ֛נוּ הַמִּצְרִ֖ים וַיְעַנּ֑וּנוּ וַיִּתְּנ֥וּ עָלֵ֖ינוּ עֲבֹדָ֥ה קָשָֽׁה'),
(5574, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 7, 'OT', 'וַנִּצְעַ֕ק אֶל יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתֵ֑ינוּ וַיִּשְׁמַ֤ע יְהוָה֙ אֶת קֹלֵ֔נוּ וַיַּ֧רְא אֶת עָנְיֵ֛נוּ וְאֶת עֲמָלֵ֖נוּ וְאֶת לַחֲצֵֽנוּ'),
(5575, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 8, 'OT', 'וַיּוֹצִאֵ֤נוּ יְהוָה֙ מִמִּצְרַ֔יִם בְּיָ֤ד חֲזָקָה֙ וּבִזְרֹ֣עַ נְטוּיָ֔ה וּבְמֹרָ֖א גָּדֹ֑ל וּבְאֹת֖וֹת וּבְמֹפְתִֽים'),
(5576, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 9, 'OT', 'וַיְבִאֵ֖נוּ אֶל הַמָּק֣וֹם הַזֶּ֑ה וַיִּתֶּן לָ֨נוּ֙ אֶת הָאָ֣רֶץ הַזֹּ֔את אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּדְבָֽשׁ'),
(5577, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 10, 'OT', 'וְעַתָּ֗ה הִנֵּ֤ה הֵבֵ֨אתִי֙ אֶת רֵאשִׁית֙ פְּרִ֣י הָאֲדָמָ֔ה אֲשֶׁר נָתַ֥תָּה לִּ֖י יְהוָ֑ה וְהִנַּחְתּ֗וֹ לִפְנֵי֙ יְהוָ֣ה אֱלֹהֶ֔יךָ וְהִֽשְׁתַּחֲוִ֔יתָ לִפְנֵ֖י יְהוָ֥ה אֱלֹהֶֽיךָ'),
(5578, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 11, 'OT', 'וְשָׂמַחְתָּ֣ בְכָל הַטּ֗וֹב אֲשֶׁ֧ר נָֽתַן לְךָ֛ יְהוָ֥ה אֱלֹהֶ֖יךָ וּלְבֵיתֶ֑ךָ אַתָּה֙ וְהַלֵּוִ֔י וְהַגֵּ֖ר אֲשֶׁ֥ר בְּקִרְבֶּֽךָ'),
(5579, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 12, 'OT', 'כִּ֣י תְכַלֶּ֞ה לַ֠עְשֵׂר אֶת כָּל מַעְשַׂ֧ר תְּבוּאָתְךָ֛ בַּשָּׁנָ֥ה הַשְּׁלִישִׁ֖ת שְׁנַ֣ת הַֽמַּעֲשֵׂ֑ר וְנָתַתָּ֣ה לַלֵּוִ֗י לַגֵּר֙ לַיָּת֣וֹם וְלָֽאַלְמָנָ֔ה וְאָכְל֥וּ בִשְׁעָרֶ֖יךָ וְשָׂבֵֽעוּ'),
(5580, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 13, 'OT', 'וְאָמַרְתָּ֡ לִפְנֵי֩ יְהוָ֨ה אֱלֹהֶ֜יךָ בִּעַ֧רְתִּי הַקֹּ֣דֶשׁ מִן הַבַּ֗יִת וְגַ֨ם נְתַתִּ֤יו לַלֵּוִי֙ וְלַגֵּר֙ לַיָּת֣וֹם וְלָאַלְמָנָ֔ה כְּכָל מִצְוָתְךָ֖ אֲשֶׁ֣ר צִוִּיתָ֑נִי לֹֽא עָבַ֥רְתִּי מִמִּצְוֺתֶ֖יךָ וְלֹ֥א שָׁכָֽחְתִּי'),
(5581, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 14, 'OT', 'לֹא אָכַ֨לְתִּי בְאֹנִ֜י מִמֶּ֗נּוּ וְלֹא בִעַ֤רְתִּי מִמֶּ֨נּוּ֙ בְּטָמֵ֔א וְלֹא נָתַ֥תִּי מִמֶּ֖נּוּ לְמֵ֑ת שָׁמַ֗עְתִּי בְּקוֹל֙ יְהוָ֣ה אֱלֹהָ֔י עָשִׂ֕יתִי כְּכֹ֖ל אֲשֶׁ֥ר צִוִּיתָֽנִי'),
(5582, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 15, 'OT', 'הַשְׁקִיפָה֩ מִמְּע֨וֹן קָדְשְׁךָ֜ מִן הַשָּׁמַ֗יִם וּבָרֵ֤ךְ אֶֽת עַמְּךָ֙ אֶת יִשְׂרָאֵ֔ל וְאֵת֙ הָאֲדָמָ֔ה אֲשֶׁ֥ר נָתַ֖תָּה לָ֑נוּ כַּאֲשֶׁ֤ר נִשְׁבַּ֨עְתָּ֙ לַאֲבֹתֵ֔ינוּ אֶ֛רֶץ זָבַ֥ת חָלָ֖ב וּדְבָֽשׁ'),
(5583, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 16, 'OT', 'הַיּ֣וֹם הַזֶּ֗ה יְהוָ֨ה אֱלֹהֶ֜יךָ מְצַוְּךָ֧ לַעֲשׂ֛וֹת אֶת הַחֻקִּ֥ים הָאֵ֖לֶּה וְאֶת הַמִּשְׁפָּטִ֑ים וְשָׁמַרְתָּ֤ וְעָשִׂ֨יתָ֙ אוֹתָ֔ם בְּכָל לְבָבְךָ֖ וּבְכָל נַפְשֶֽׁךָ'),
(5584, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 17, 'OT', 'אֶת יְהוָ֥ה הֶאֱמַ֖רְתָּ הַיּ֑וֹם לִהְיוֹת֩ לְךָ֨ לֵֽאלֹהִ֜ים וְלָלֶ֣כֶת בִּדְרָכָ֗יו וְלִשְׁמֹ֨ר חֻקָּ֧יו וּמִצְוֺתָ֛יו וּמִשְׁפָּטָ֖יו וְלִשְׁמֹ֥עַ בְּקֹלֽוֹ'),
(5585, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 18, 'OT', 'וַֽיהוָ֞ה הֶאֱמִֽירְךָ֣ הַיּ֗וֹם לִהְי֥וֹת לוֹ֙ לְעַ֣ם סְגֻלָּ֔ה כַּאֲשֶׁ֖ר דִּבֶּר לָ֑ךְ וְלִשְׁמֹ֖ר כָּל מִצְוֺתָֽיו'),
(5586, 5, 'WLC', 'WLC', 'he', 'DEU', 26, 19, 'OT', 'וּֽלְתִתְּךָ֣ עֶלְי֗וֹן עַ֤ל כָּל הַגּוֹיִם֙ אֲשֶׁ֣ר עָשָׂ֔ה לִתְהִלָּ֖ה וּלְשֵׁ֣ם וּלְתִפְאָ֑רֶת וְלִֽהְיֹתְךָ֧ עַם קָדֹ֛שׁ לַיהוָ֥ה אֱלֹהֶ֖יךָ כַּאֲשֶׁ֥ר דִּבֵּֽר'),
