(5661, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 49, 'OT', 'יִשָּׂ֣א יְהוָה֩ עָלֶ֨יךָ גּ֤וֹי מֵרָחוֹק֙ מִקְצֵ֣ה הָאָ֔רֶץ כַּאֲשֶׁ֥ר יִדְאֶ֖ה הַנָּ֑שֶׁר גּ֕וֹי אֲשֶׁ֥ר לֹא תִשְׁמַ֖ע לְשֹׁנֽוֹ'),
(5662, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 50, 'OT', 'גּ֖וֹי עַ֣ז פָּנִ֑ים אֲשֶׁ֨ר לֹא יִשָּׂ֤א פָנִים֙ לְזָקֵ֔ן וְנַ֖עַר לֹ֥א יָחֹֽן'),
(5663, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 51, 'OT', 'וְ֠אָכַל פְּרִ֨י בְהֶמְתְּךָ֥ וּפְרִֽי אַדְמָתְךָ֮ עַ֣ד הִשָּֽׁמְדָךְ֒ אֲשֶׁ֨ר לֹֽא יַשְׁאִ֜יר לְךָ֗ דָּגָן֙ תִּיר֣וֹשׁ וְיִצְהָ֔ר שְׁגַ֥ר אֲלָפֶ֖יךָ וְעַשְׁתְּרֹ֣ת צֹאנֶ֑ךָ עַ֥ד הַאֲבִיד֖וֹ אֹתָֽךְ'),
(5664, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 52, 'OT', 'וְהֵצַ֨ר לְךָ֜ בְּכָל שְׁעָרֶ֗יךָ עַ֣ד רֶ֤דֶת חֹמֹתֶ֨יךָ֙ הַגְּבֹה֣וֹת וְהַבְּצֻר֔וֹת אֲשֶׁ֥ר אַתָּ֛ה בֹּטֵ֥חַ בָּהֵ֖ן בְּכָל אַרְצֶ֑ךָ וְהֵצַ֤ר לְךָ֙ בְּכָל שְׁעָרֶ֔יךָ בְּכָ֨ל אַרְצְךָ֔ אֲשֶׁ֥ר נָתַ֛ן יְהוָ֥ה אֱלֹהֶ֖יךָ לָֽךְ'),
(5665, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 53, 'OT', 'וְאָכַלְתָּ֣ פְרִֽי בִטְנְךָ֗ בְּשַׂ֤ר בָּנֶ֨יךָ֙ וּבְנֹתֶ֔יךָ אֲשֶׁ֥ר נָֽתַן לְךָ֖ יְהוָ֣ה אֱלֹהֶ֑יךָ בְּמָצוֹר֙ וּבְמָצ֔וֹק אֲשֶׁר יָצִ֥יק לְךָ֖ אֹיְבֶֽךָ'),
(5666, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 54, 'OT', 'הָאִישׁ֙ הָרַ֣ךְ בְּךָ֔ וְהֶעָנֹ֖ג מְאֹ֑ד תֵּרַ֨ע עֵינ֤וֹ בְאָחִיו֙ וּבְאֵ֣שֶׁת חֵיק֔וֹ וּבְיֶ֥תֶר בָּנָ֖יו אֲשֶׁ֥ר יוֹתִֽיר'),
(5667, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 55, 'OT', 'מִתֵּ֣ת לְאַחַ֣ד מֵהֶ֗ם מִבְּשַׂ֤ר בָּנָיו֙ אֲשֶׁ֣ר יֹאכֵ֔ל מִבְּלִ֥י הִשְׁאִֽיר ל֖וֹ כֹּ֑ל בְּמָצוֹר֙ וּבְמָצ֔וֹק אֲשֶׁ֨ר יָצִ֥יק לְךָ֛ אֹיִבְךָ֖ בְּכָל שְׁעָרֶֽיךָ'),
(5668, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 56, 'OT', 'הָרַכָּ֨ה בְךָ֜ וְהָעֲנֻגָּ֗ה אֲשֶׁ֨ר לֹא נִסְּתָ֤ה כַף רַגְלָהּ֙ הַצֵּ֣ג עַל הָאָ֔רֶץ מֵהִתְעַנֵּ֖ג וּמֵרֹ֑ךְ תֵּרַ֤ע עֵינָהּ֙ בְּאִ֣ישׁ חֵיקָ֔הּ וּבִבְנָ֖הּ וּבְבִתָּֽהּ'),
(5669, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 57, 'OT', 'וּֽבְשִׁלְיָתָ֞הּ הַיּוֹצֵ֣ת מִבֵּ֣ין רַגְלֶ֗יהָ וּבְבָנֶ֨יהָ֙ אֲשֶׁ֣ר תֵּלֵ֔ד כִּֽי תֹאכְלֵ֥ם בְּחֹֽסֶר כֹּ֖ל בַּסָּ֑תֶר בְּמָצוֹר֙ וּבְמָצ֔וֹק אֲשֶׁ֨ר יָצִ֥יק לְךָ֛ אֹיִבְךָ֖ בִּשְׁעָרֶֽיךָ'),
(5670, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 58, 'OT', 'אִם לֹ֨א תִשְׁמֹ֜ר לַעֲשׂ֗וֹת אֶת כָּל דִּבְרֵי֙ הַתּוֹרָ֣ה הַזֹּ֔את הַכְּתוּבִ֖ים בַּסֵּ֣פֶר הַזֶּ֑ה לְ֠יִרְאָה אֶת הַשֵּׁ֞ם הַנִּכְבָּ֤ד וְהַנּוֹרָא֙ הַזֶּ֔ה אֵ֖ת יְהוָ֥ה אֱלֹהֶֽיךָ'),
(5671, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 59, 'OT', 'וְהִפְלָ֤א יְהוָה֙ אֶת מַכֹּ֣תְךָ֔ וְאֵ֖ת מַכּ֣וֹת זַרְעֶ֑ךָ מַכּ֤וֹת גְּדֹלוֹת֙ וְנֶ֣אֱמָנ֔וֹת וָחֳלָיִ֥ם רָעִ֖ים וְנֶאֱמָנִֽים'),
(5672, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 60, 'OT', 'וְהֵשִׁ֣יב בְּךָ֗ אֵ֚ת כָּל מַדְוֵ֣ה מִצְרַ֔יִם אֲשֶׁ֥ר יָגֹ֖רְתָּ מִפְּנֵיהֶ֑ם וְדָבְק֖וּ בָּֽךְ'),
(5673, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 61, 'OT', 'גַּ֤ם כָּל חֳלִי֙ וְכָל מַכָּ֔ה אֲשֶׁר֙ לֹ֣א כָת֔וּב בְּסֵ֖פֶר הַתּוֹרָ֣ה הַזֹּ֑את יַעְלֵ֤ם יְהוָה֙ עָלֶ֔יךָ עַ֖ד הִשָּׁמְדָֽךְ'),
(5674, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 62, 'OT', 'וְנִשְׁאַרְתֶּם֙ בִּמְתֵ֣י מְעָ֔ט תַּ֚חַת אֲשֶׁ֣ר הֱיִיתֶ֔ם כְּכוֹכְבֵ֥י הַשָּׁמַ֖יִם לָרֹ֑ב כִּי לֹ֣א שָׁמַ֔עְתָּ בְּק֖וֹל יְהוָ֥ה אֱלֹהֶֽיךָ'),
(5675, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 63, 'OT', 'וְ֠הָיָה כַּאֲשֶׁר שָׂ֨שׂ יְהוָ֜ה עֲלֵיכֶ֗ם לְהֵיטִ֣יב אֶתְכֶם֮ וּלְהַרְבּ֣וֹת אֶתְכֶם֒ כֵּ֣ן יָשִׂ֤ישׂ יְהוָה֙ עֲלֵיכֶ֔ם לְהַאֲבִ֥יד אֶתְכֶ֖ם וּלְהַשְׁמִ֣יד אֶתְכֶ֑ם וְנִסַּחְתֶּם֙ מֵעַ֣ל הָֽאֲדָמָ֔ה אֲשֶׁר אַתָּ֥ה בָא שָׁ֖מָּה לְרִשְׁתָּֽהּ'),
(5676, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 64, 'OT', 'וֶהֱפִֽיצְךָ֤ יְהוָה֙ בְּכָל הָ֣עַמִּ֔ים מִקְצֵ֥ה הָאָ֖רֶץ וְעַד קְצֵ֣ה הָאָ֑רֶץ וְעָבַ֨דְתָּ שָּׁ֜ם אֱלֹהִ֣ים אֲחֵרִ֗ים אֲשֶׁ֧ר לֹא יָדַ֛עְתָּ אַתָּ֥ה וַאֲבֹתֶ֖יךָ עֵ֥ץ וָאָֽבֶן'),
(5677, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 65, 'OT', 'וּבַגּוֹיִ֤ם הָהֵם֙ לֹ֣א תַרְגִּ֔יעַ וְלֹא יִהְיֶ֥ה מָנ֖וֹחַ לְכַף רַגְלֶ֑ךָ וְנָתַן֩ יְהוָ֨ה לְךָ֥ שָׁם֙ לֵ֣ב רַגָּ֔ז וְכִלְי֥וֹן עֵינַ֖יִם וְדַֽאֲב֥וֹן נָֽפֶשׁ'),
(5678, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 66, 'OT', 'וְהָי֣וּ חַיֶּ֔יךָ תְּלֻאִ֥ים לְךָ֖ מִנֶּ֑גֶד וּפָֽחַדְתָּ֙ לַ֣יְלָה וְיוֹמָ֔ם וְלֹ֥א תַאֲמִ֖ין בְּחַיֶּֽיךָ'),
(5679, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 67, 'OT', 'בַּבֹּ֤קֶר תֹּאמַר֙ מִֽי יִתֵּ֣ן עֶ֔רֶב וּבָעֶ֥רֶב תֹּאמַ֖ר מִֽי יִתֵּ֣ן בֹּ֑קֶר מִפַּ֤חַד לְבָֽבְךָ֙ אֲשֶׁ֣ר תִּפְחָ֔ד וּמִמַּרְאֵ֥ה עֵינֶ֖יךָ אֲשֶׁ֥ר תִּרְאֶֽה'),
(5680, 5, 'WLC', 'WLC', 'he', 'DEU', 28, 68, 'OT', 'וֶֽהֱשִֽׁיבְךָ֨ יְהוָ֥ה מִצְרַיִם֮ בָּאֳנִיּוֹת֒ בַּדֶּ֨רֶךְ֙ אֲשֶׁ֣ר אָמַ֣רְתִּֽי לְךָ֔ לֹא תֹסִ֥יף ע֖וֹד לִרְאֹתָ֑הּ וְהִתְמַכַּרְתֶּ֨ם שָׁ֧ם לְאֹיְבֶ֛יךָ לַעֲבָדִ֥ים וְלִשְׁפָח֖וֹת וְאֵ֥ין קֹנֶֽה'),
(5681, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 1, 'OT', 'אֵלֶּה֩ דִבְרֵ֨י הַבְּרִ֜ית אֲֽשֶׁר צִוָּ֧ה יְהוָ֣ה אֶת מֹשֶׁ֗ה לִכְרֹ֛ת אֶת בְּנֵ֥י יִשְׂרָאֵ֖ל בְּאֶ֣רֶץ מוֹאָ֑ב מִלְּבַ֣ד הַבְּרִ֔ית אֲשֶׁר כָּרַ֥ת אִתָּ֖ם בְּחֹרֵֽב'),
(5682, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 2, 'OT', 'וַיִּקְרָ֥א מֹשֶׁ֛ה אֶל כָּל יִשְׂרָאֵ֖ל וַיֹּ֣אמֶר אֲלֵהֶ֑ם אַתֶּ֣ם רְאִיתֶ֗ם אֵ֣ת כָּל אֲשֶׁר֩ עָשָׂ֨ה יְהוָ֤ה לְעֵֽינֵיכֶם֙ בְּאֶ֣רֶץ מִצְרַ֔יִם לְפַרְעֹ֥ה וּלְכָל עֲבָדָ֖יו וּלְכָל אַרְצֽוֹ'),
(5683, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 3, 'OT', 'הַמַּסּוֹת֙ הַגְּדֹלֹ֔ת אֲשֶׁ֥ר רָא֖וּ עֵינֶ֑יךָ הָאֹתֹ֧ת וְהַמֹּפְתִ֛ים הַגְּדֹלִ֖ים הָהֵֽם'),
(5684, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 4, 'OT', 'וְלֹֽא נָתַן֩ יְהוָ֨ה לָכֶ֥ם לֵב֙ לָדַ֔עַת וְעֵינַ֥יִם לִרְא֖וֹת וְאָזְנַ֣יִם לִשְׁמֹ֑עַ עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(5685, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 5, 'OT', 'וָאוֹלֵ֥ךְ אֶתְכֶ֛ם אַרְבָּעִ֥ים שָׁנָ֖ה בַּמִּדְבָּ֑ר לֹֽא בָל֤וּ שַׂלְמֹֽתֵיכֶם֙ מֵעֲלֵיכֶ֔ם וְנַֽעַלְךָ֥ לֹֽא בָלְתָ֖ה מֵעַ֥ל רַגְלֶֽךָ'),
(5686, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 6, 'OT', 'לֶ֚חֶם לֹ֣א אֲכַלְתֶּ֔ם וְיַ֥יִן וְשֵׁכָ֖ר לֹ֣א שְׁתִיתֶ֑ם לְמַ֨עַן֙ תֵּֽדְע֔וּ כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵיכֶֽם'),
(5687, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 7, 'OT', 'וַתָּבֹ֖אוּ אֶל הַמָּק֣וֹם הַזֶּ֑ה וַיֵּצֵ֣א סִיחֹ֣ן מֶֽלֶךְ חֶ֠שְׁבּוֹן וְע֨וֹג מֶֽלֶךְ הַבָּשָׁ֧ן לִקְרָאתֵ֛נוּ לַמִּלְחָמָ֖ה וַנַּכֵּֽם'),
(5688, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 8, 'OT', 'וַנִּקַּח֙ אֶת אַרְצָ֔ם וַנִּתְּנָ֣הּ לְנַחֲלָ֔ה לָרֽאוּבֵנִ֖י וְלַגָּדִ֑י וְלַחֲצִ֖י שֵׁ֥בֶט הַֽמְנַשִּֽׁי'),
(5689, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 9, 'OT', 'וּשְׁמַרְתֶּ֗ם אֶת דִּבְרֵי֙ הַבְּרִ֣ית הַזֹּ֔את וַעֲשִׂיתֶ֖ם אֹתָ֑ם לְמַ֣עַן תַּשְׂכִּ֔ילוּ אֵ֖ת כָּל אֲשֶׁ֥ר תַּעֲשֽׂוּן'),
(5690, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 10, 'OT', 'אַתֶּ֨ם נִצָּבִ֤ים הַיּוֹם֙ כֻּלְּכֶ֔ם לִפְנֵ֖י יְהוָ֣ה אֱלֹהֵיכֶ֑ם רָאשֵׁיכֶ֣ם שִׁבְטֵיכֶ֗ם זִקְנֵיכֶם֙ וְשֹׁ֣טְרֵיכֶ֔ם כֹּ֖ל אִ֥ישׁ יִשְׂרָאֵֽל'),
(5691, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 11, 'OT', 'טַפְּכֶ֣ם נְשֵׁיכֶ֔ם וְגֵ֣רְךָ֔ אֲשֶׁ֖ר בְּקֶ֣רֶב מַחֲנֶ֑יךָ מֵחֹטֵ֣ב עֵצֶ֔יךָ עַ֖ד שֹׁאֵ֥ב מֵימֶֽיךָ'),
(5692, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 12, 'OT', 'לְעָבְרְךָ֗ בִּבְרִ֛ית יְהוָ֥ה אֱלֹהֶ֖יךָ וּבְאָלָת֑וֹ אֲשֶׁר֙ יְהוָ֣ה אֱלֹהֶ֔יךָ כֹּרֵ֥ת עִמְּךָ֖ הַיּֽוֹם'),
(5693, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 13, 'OT', 'לְמַ֣עַן הָקִֽים אֹתְךָ֩ הַיּ֨וֹם ל֜וֹ לְעָ֗ם וְה֤וּא יִֽהְיֶה לְּךָ֙ לֵֽאלֹהִ֔ים כַּאֲשֶׁ֖ר דִּבֶּר לָ֑ךְ וְכַאֲשֶׁ֤ר נִשְׁבַּע֙ לַאֲבֹתֶ֔יךָ לְאַבְרָהָ֥ם לְיִצְחָ֖ק וּֽלְיַעֲקֹֽב'),
(5694, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 14, 'OT', 'וְלֹ֥א אִתְּכֶ֖ם לְבַדְּכֶ֑ם אָנֹכִ֗י כֹּרֵת֙ אֶת הַבְּרִ֣ית הַזֹּ֔את וְאֶת הָאָלָ֖ה הַזֹּֽאת'),
(5695, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 15, 'OT', 'כִּי֩ אֶת אֲשֶׁ֨ר יֶשְׁנ֜וֹ פֹּ֗ה עִמָּ֨נוּ֙ עֹמֵ֣ד הַיּ֔וֹם לִפְנֵ֖י יְהוָ֣ה אֱלֹהֵ֑ינוּ וְאֵ֨ת אֲשֶׁ֥ר אֵינֶ֛נּוּ פֹּ֖ה עִמָּ֥נוּ הַיּֽוֹם'),
(5696, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 16, 'OT', 'כִּֽי אַתֶּ֣ם יְדַעְתֶּ֔ם אֵ֥ת אֲשֶׁר יָשַׁ֖בְנוּ בְּאֶ֣רֶץ מִצְרָ֑יִם וְאֵ֧ת אֲשֶׁר עָבַ֛רְנוּ בְּקֶ֥רֶב הַגּוֹיִ֖ם אֲשֶׁ֥ר עֲבַרְתֶּֽם'),
(5697, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 17, 'OT', 'וַתִּרְאוּ֙ אֶת שִׁקּ֣וּצֵיהֶ֔ם וְאֵ֖ת גִּלֻּלֵיהֶ֑ם עֵ֣ץ וָאֶ֔בֶן כֶּ֥סֶף וְזָהָ֖ב אֲשֶׁ֥ר עִמָּהֶֽם'),
(5698, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 18, 'OT', 'פֶּן יֵ֣שׁ בָּ֠כֶם אִ֣ישׁ אוֹ אִשָּׁ֞ה א֧וֹ מִשְׁפָּחָ֣ה אוֹ שֵׁ֗בֶט אֲשֶׁר֩ לְבָב֨וֹ פֹנֶ֤ה הַיּוֹם֙ מֵעִם֙ יְהוָ֣ה אֱלֹהֵ֔ינוּ לָלֶ֣כֶת לַעֲבֹ֔ד אֶת אֱלֹהֵ֖י הַגּוֹיִ֣ם הָהֵ֑ם פֶּן יֵ֣שׁ בָּכֶ֗ם שֹׁ֛רֶשׁ פֹּרֶ֥ה רֹ֖אשׁ וְלַעֲנָֽה'),
(5699, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 19, 'OT', 'וְהָיָ֡ה בְּשָׁמְעוֹ֩ אֶת דִּבְרֵ֨י הָֽאָלָ֜ה הַזֹּ֗את וְהִתְבָּרֵ֨ךְ בִּלְבָב֤וֹ לֵאמֹר֙ שָׁל֣וֹם יִֽהְיֶה לִּ֔י כִּ֛י בִּשְׁרִר֥וּת לִבִּ֖י אֵלֵ֑ךְ לְמַ֛עַן סְפ֥וֹת הָרָוָ֖ה אֶת הַצְּמֵאָֽה'),
(5700, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 20, 'OT', 'לֹא יֹאבֶ֣ה יְהוָה֮ סְלֹ֣חַֽ לוֹ֒ כִּ֣י אָ֠ז יֶעְשַׁ֨ן אַף יְהוָ֤ה וְקִנְאָתוֹ֙ בָּאִ֣ישׁ הַה֔וּא וְרָ֤בְצָה בּוֹ֙ כָּל הָ֣אָלָ֔ה הַכְּתוּבָ֖ה בַּסֵּ֣פֶר הַזֶּ֑ה וּמָחָ֤ה יְהוָה֙ אֶת שְׁמ֔וֹ מִתַּ֖חַת הַשָּׁמָֽיִם'),
(5701, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 21, 'OT', 'וְהִבְדִּיל֤וֹ יְהוָה֙ לְרָעָ֔ה מִכֹּ֖ל שִׁבְטֵ֣י יִשְׂרָאֵ֑ל כְּכֹל֙ אָל֣וֹת הַבְּרִ֔ית הַכְּתוּבָ֕ה בְּסֵ֥פֶר הַתּוֹרָ֖ה הַזֶּֽה'),
(5702, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 22, 'OT', 'וְאָמַ֞ר הַדּ֣וֹר הָֽאַחֲר֗וֹן בְּנֵיכֶם֙ אֲשֶׁ֤ר יָק֨וּמוּ֙ מֵאַ֣חֲרֵיכֶ֔ם וְהַ֨נָּכְרִ֔י אֲשֶׁ֥ר יָבֹ֖א מֵאֶ֣רֶץ רְחוֹקָ֑ה וְ֠רָאוּ אֶת מַכּ֞וֹת הָאָ֤רֶץ הַהִוא֙ וְאֶת תַּ֣חֲלֻאֶ֔יהָ אֲשֶׁר חִלָּ֥ה יְהוָ֖ה בָּֽהּ'),
(5703, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 23, 'OT', 'גָּפְרִ֣ית וָמֶלַח֮ שְׂרֵפָ֣ה כָל אַרְצָהּ֒ לֹ֤א תִזָּרַע֙ וְלֹ֣א תַצְמִ֔חַ וְלֹֽא יַעֲלֶ֥ה בָ֖הּ כָּל עֵ֑שֶׂב כְּֽמַהְפֵּכַ֞ת סְדֹ֤ם וַעֲמֹרָה֙ אַדְמָ֣ה וצביים אֲשֶׁר֙ הָפַ֣ךְ יְהוָ֔ה בְּאַפּ֖וֹ וּבַחֲמָתֽוֹ'),
(5704, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 24, 'OT', 'וְאָֽמְרוּ֙ כָּל הַגּוֹיִ֔ם עַל מֶ֨ה עָשָׂ֧ה יְהוָ֛ה כָּ֖כָה לָאָ֣רֶץ הַזֹּ֑את מֶ֥ה חֳרִ֛י הָאַ֥ף הַגָּד֖וֹל הַזֶּֽה'),
(5705, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 25, 'OT', 'וְאָ֣מְר֔וּ עַ֚ל אֲשֶׁ֣ר עָֽזְב֔וּ אֶת בְּרִ֥ית יְהוָ֖ה אֱלֹהֵ֣י אֲבֹתָ֑ם אֲשֶׁר֙ כָּרַ֣ת עִמָּ֔ם בְּהוֹצִיא֥וֹ אֹתָ֖ם מֵאֶ֥רֶץ מִצְרָֽיִם'),
(5706, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 26, 'OT', 'וַיֵּלְכ֗וּ וַיַּֽעַבְדוּ֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וַיִּֽשְׁתַּחֲוּ֖וּ לָהֶ֑ם אֱלֹהִים֙ אֲשֶׁ֣ר לֹֽא יְדָע֔וּם וְלֹ֥א חָלַ֖ק לָהֶֽם'),
(5707, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 27, 'OT', 'וַיִּֽחַר אַ֥ף יְהוָ֖ה בָּאָ֣רֶץ הַהִ֑וא לְהָבִ֤יא עָלֶ֨יהָ֙ אֶת כָּל הַקְּלָלָ֔ה הַכְּתוּבָ֖ה בַּסֵּ֥פֶר הַזֶּֽה'),
(5708, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 28, 'OT', 'וַיִּתְּשֵׁ֤ם יְהוָה֙ מֵעַ֣ל אַדְמָתָ֔ם בְּאַ֥ף וּבְחֵמָ֖ה וּבְקֶ֣צֶף גָּד֑וֹל וַיַּשְׁלִכֵ֛ם אֶל אֶ֥רֶץ אַחֶ֖רֶת כַּיּ֥וֹם הַזֶּֽה'),
(5709, 5, 'WLC', 'WLC', 'he', 'DEU', 29, 29, 'OT', 'הַ֨נִּסְתָּרֹ֔ת לַיהוָ֖ה אֱלֹהֵ֑ינוּ וְהַנִּגְלֹ֞ת לָ֤ׄנׄוּׄ וּׄלְׄבָׄנֵׄ֨יׄנׄוּׄ֙ עַד עוֹלָ֔ם לַעֲשׂ֕וֹת אֶת כָּל דִּבְרֵ֖י הַתּוֹרָ֥ה הַזֹּֽאת'),
(5710, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 1, 'OT', 'וְהָיָה֩ כִֽי יָבֹ֨אוּ עָלֶ֜יךָ כָּל הַדְּבָרִ֣ים הָאֵ֗לֶּה הַבְּרָכָה֙ וְהַקְּלָלָ֔ה אֲשֶׁ֥ר נָתַ֖תִּי לְפָנֶ֑יךָ וַהֲשֵׁבֹתָ֙ אֶל לְבָבֶ֔ךָ בְּכָל הַגּוֹיִ֔ם אֲשֶׁ֧ר הִדִּיחֲךָ֛ יְהוָ֥ה אֱלֹהֶ֖יךָ שָֽׁמָּה'),
(5711, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 2, 'OT', 'וְשַׁבְתָּ֞ עַד יְהוָ֤ה אֱלֹהֶ֨יךָ֙ וְשָׁמַעְתָּ֣ בְקֹל֔וֹ כְּכֹ֛ל אֲשֶׁר אָנֹכִ֥י מְצַוְּךָ֖ הַיּ֑וֹם אַתָּ֣ה וּבָנֶ֔יךָ בְּכָל לְבָבְךָ֖ וּבְכָל נַפְשֶֽׁךָ'),
(5712, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 3, 'OT', 'וְשָׁ֨ב יְהוָ֧ה אֱלֹהֶ֛יךָ אֶת שְׁבוּתְךָ֖ וְרִחֲמֶ֑ךָ וְשָׁ֗ב וְקִבֶּצְךָ֙ מִכָּל הָ֣עַמִּ֔ים אֲשֶׁ֧ר הֱפִֽיצְךָ֛ יְהוָ֥ה אֱלֹהֶ֖יךָ שָֽׁמָּה'),
