(5718, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 9, 'OT', 'וְהוֹתִֽירְךָ֩ יְהוָ֨ה אֱלֹהֶ֜יךָ בְּכֹ֣ל מַעֲשֵׂ֣ה יָדֶ֗ךָ בִּפְרִ֨י בִטְנְךָ֜ וּבִפְרִ֧י בְהֶמְתְּךָ֛ וּבִפְרִ֥י אַדְמָתְךָ֖ לְטוֹבָ֑ה כִּ֣י יָשׁ֣וּב יְהוָ֗ה לָשׂ֤וּשׂ עָלֶ֨יךָ֙ לְט֔וֹב כַּאֲשֶׁר שָׂ֖שׂ עַל אֲבֹתֶֽיךָ'),
(5719, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 10, 'OT', 'כִּ֣י תִשְׁמַ֗ע בְּקוֹל֙ יְהוָ֣ה אֱלֹהֶ֔יךָ לִשְׁמֹ֤ר מִצְוֺתָיו֙ וְחֻקֹּתָ֔יו הַכְּתוּבָ֕ה בְּסֵ֥פֶר הַתּוֹרָ֖ה הַזֶּ֑ה כִּ֤י תָשׁוּב֙ אֶל יְהוָ֣ה אֱלֹהֶ֔יךָ בְּכָל לְבָבְךָ֖ וּבְכָל נַפְשֶֽׁךָ'),
(5720, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 11, 'OT', 'כִּ֚י הַמִּצְוָ֣ה הַזֹּ֔את אֲשֶׁ֛ר אָנֹכִ֥י מְצַוְּךָ֖ הַיּ֑וֹם לֹֽא נִפְלֵ֥את הִוא֙ מִמְּךָ֔ וְלֹ֥א רְחֹקָ֖ה הִֽוא'),
(5721, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 12, 'OT', 'לֹ֥א בַשָּׁמַ֖יִם הִ֑וא לֵאמֹ֗ר מִ֣י יַעֲלֶה לָּ֤נוּ הַשָּׁמַ֨יְמָה֙ וְיִקָּחֶ֣הָ לָּ֔נוּ וְיַשְׁמִעֵ֥נוּ אֹתָ֖הּ וְנַעֲשֶֽׂנָּה'),
(5722, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 13, 'OT', 'וְלֹֽא מֵעֵ֥בֶר לַיָּ֖ם הִ֑וא לֵאמֹ֗ר מִ֣י יַעֲבָר לָ֜נוּ אֶל עֵ֤בֶר הַיָּם֙ וְיִקָּחֶ֣הָ לָּ֔נוּ וְיַשְׁמִעֵ֥נוּ אֹתָ֖הּ וְנַעֲשֶֽׂנָּה'),
(5723, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 14, 'OT', 'כִּֽי קָר֥וֹב אֵלֶ֛יךָ הַדָּבָ֖ר מְאֹ֑ד בְּפִ֥יךָ וּבִֽלְבָבְךָ֖ לַעֲשֹׂתֽוֹ'),
(5724, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 15, 'OT', 'רְאֵ֨ה נָתַ֤תִּי לְפָנֶ֨יךָ֙ הַיּ֔וֹם אֶת הַֽחַיִּ֖ים וְאֶת הַטּ֑וֹב וְאֶת הַמָּ֖וֶת וְאֶת הָרָֽע'),
(5725, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 16, 'OT', 'אֲשֶׁ֨ר אָנֹכִ֣י מְצַוְּךָ֮ הַיּוֹם֒ לְאַהֲבָ֞ה אֶת יְהוָ֤ה אֱלֹהֶ֨יךָ֙ לָלֶ֣כֶת בִּדְרָכָ֔יו וְלִשְׁמֹ֛ר מִצְוֺתָ֥יו וְחֻקֹּתָ֖יו וּמִשְׁפָּטָ֑יו וְחָיִ֣יתָ וְרָבִ֔יתָ וּבֵֽרַכְךָ֙ יְהוָ֣ה אֱלֹהֶ֔יךָ בָּאָ֕רֶץ אֲשֶׁר אַתָּ֥ה בָא שָׁ֖מָּה לְרִשְׁתָּֽהּ'),
(5726, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 17, 'OT', 'וְאִם יִפְנֶ֥ה לְבָבְךָ֖ וְלֹ֣א תִשְׁמָ֑ע וְנִדַּחְתָּ֗ וְהִֽשְׁתַּחֲוִ֛יתָ לֵאלֹהִ֥ים אֲחֵרִ֖ים וַעֲבַדְתָּֽם'),
(5727, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 18, 'OT', 'הִגַּ֤דְתִּי לָכֶם֙ הַיּ֔וֹם כִּ֥י אָבֹ֖ד תֹּאבֵד֑וּן לֹא תַאֲרִיכֻ֤ן יָמִים֙ עַל הָ֣אֲדָמָ֔ה אֲשֶׁ֨ר אַתָּ֤ה עֹבֵר֙ אֶת הַיַּרְדֵּ֔ן לָבֹ֥א שָׁ֖מָּה לְרִשְׁתָּֽהּ'),
(5728, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 19, 'OT', 'הַעִידֹ֨תִי בָכֶ֣ם הַיּוֹם֮ אֶת הַשָּׁמַ֣יִם וְאֶת הָאָרֶץ֒ הַחַיִּ֤ים וְהַמָּ֨וֶת֙ נָתַ֣תִּי לְפָנֶ֔יךָ הַבְּרָכָ֖ה וְהַקְּלָלָ֑ה וּבָֽחַרְתָּ֙ בַּֽחַיִּ֔ים לְמַ֥עַן תִּחְיֶ֖ה אַתָּ֥ה וְזַרְעֶֽךָ'),
(5729, 5, 'WLC', 'WLC', 'he', 'DEU', 30, 20, 'OT', 'לְאַֽהֲבָה֙ אֶת יְהוָ֣ה אֱלֹהֶ֔יךָ לִשְׁמֹ֥עַ בְּקֹל֖וֹ וּלְדָבְקָה ב֑וֹ כִּ֣י ה֤וּא חַיֶּ֨יךָ֙ וְאֹ֣רֶךְ יָמֶ֔יךָ לָשֶׁ֣בֶת עַל הָאֲדָמָ֗ה אֲשֶׁר֩ נִשְׁבַּ֨ע יְהוָ֧ה לַאֲבֹתֶ֛יךָ לְאַבְרָהָ֛ם לְיִצְחָ֥ק וּֽלְיַעֲקֹ֖ב לָתֵ֥ת לָהֶֽם'),
(5730, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 1, 'OT', 'וַיֵּ֖לֶךְ מֹשֶׁ֑ה וַיְדַבֵּ֛ר אֶת הַדְּבָרִ֥ים הָאֵ֖לֶּה אֶל כָּל יִשְׂרָאֵֽל'),
(5731, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 2, 'OT', 'וַיֹּ֣אמֶר אֲלֵהֶ֗ם בֶּן מֵאָה֩ וְעֶשְׂרִ֨ים שָׁנָ֤ה אָנֹכִי֙ הַיּ֔וֹם לֹא אוּכַ֥ל ע֖וֹד לָצֵ֣את וְלָב֑וֹא וַֽיהוָה֙ אָמַ֣ר אֵלַ֔י לֹ֥א תַעֲבֹ֖ר אֶת הַיַּרְדֵּ֥ן הַזֶּֽה'),
(5732, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 3, 'OT', 'יְהוָ֨ה אֱלֹהֶ֜יךָ ה֣וּא עֹבֵ֣ר לְפָנֶ֗יךָ הֽוּא יַשְׁמִ֞יד אֶת הַגּוֹיִ֥ם הָאֵ֛לֶּה מִלְּפָנֶ֖יךָ וִֽירִשְׁתָּ֑ם יְהוֹשֻׁ֗עַ ה֚וּא עֹבֵ֣ר לְפָנֶ֔יךָ כַּאֲשֶׁ֖ר דִּבֶּ֥ר יְהוָֽה'),
(5733, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 4, 'OT', 'וְעָשָׂ֤ה יְהוָה֙ לָהֶ֔ם כַּאֲשֶׁ֣ר עָשָׂ֗ה לְסִיח֥וֹן וּלְע֛וֹג מַלְכֵ֥י הָאֱמֹרִ֖י וּלְאַרְצָ֑ם אֲשֶׁ֥ר הִשְׁמִ֖יד אֹתָֽם'),
(5734, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 5, 'OT', 'וּנְתָנָ֥ם יְהוָ֖ה לִפְנֵיכֶ֑ם וַעֲשִׂיתֶ֣ם לָהֶ֔ם כְּכָל הַמִּצְוָ֔ה אֲשֶׁ֥ר צִוִּ֖יתִי אֶתְכֶֽם'),
(5735, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 6, 'OT', 'חִזְק֣וּ וְאִמְצ֔וּ אַל תִּֽירְא֥וּ וְאַל תַּעַרְצ֖וּ מִפְּנֵיהֶ֑ם כִּ֣י יְהוָ֣ה אֱלֹהֶ֗יךָ ה֚וּא הַהֹלֵ֣ךְ עִמָּ֔ךְ לֹ֥א יַרְפְּךָ֖ וְלֹ֥א יַעַזְבֶֽךָּ'),
(5736, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 7, 'OT', 'וַיִּקְרָ֨א מֹשֶׁ֜ה לִֽיהוֹשֻׁ֗עַ וַיֹּ֨אמֶר אֵלָ֜יו לְעֵינֵ֣י כָל יִשְׂרָאֵ֘ל חֲזַ֣ק וֶאֱמָץ֒ כִּ֣י אַתָּ֗ה תָּבוֹא֙ אֶת הָעָ֣ם הַזֶּ֔ה אֶל הָאָ֕רֶץ אֲשֶׁ֨ר נִשְׁבַּ֧ע יְהוָ֛ה לַאֲבֹתָ֖ם לָתֵ֣ת לָהֶ֑ם וְאַתָּ֖ה תַּנְחִילֶ֥נָּה אוֹתָֽם'),
(5737, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 8, 'OT', 'וַֽיהוָ֞ה ה֣וּא הַהֹלֵ֣ךְ לְפָנֶ֗יךָ ה֚וּא יִהְיֶ֣ה עִמָּ֔ךְ לֹ֥א יַרְפְּךָ֖ וְלֹ֣א יַֽעַזְבֶ֑ךָּ לֹ֥א תִירָ֖א וְלֹ֥א תֵחָֽת'),
(5738, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 9, 'OT', 'וַיִּכְתֹּ֣ב מֹשֶׁה֮ אֶת הַתּוֹרָ֣ה הַזֹּאת֒ וַֽיִּתְּנָ֗הּ אֶל הַכֹּהֲנִים֙ בְּנֵ֣י לֵוִ֔י הַנֹּ֣שְׂאִ֔ים אֶת אֲר֖וֹן בְּרִ֣ית יְהוָ֑ה וְאֶל כָּל זִקְנֵ֖י יִשְׂרָאֵֽל'),
(5739, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 10, 'OT', 'וַיְצַ֥ו מֹשֶׁ֖ה אוֹתָ֣ם לֵאמֹ֑ר מִקֵּ֣ץ שֶׁ֣בַע שָׁנִ֗ים בְּמֹעֵ֛ד שְׁנַ֥ת הַשְּׁמִטָּ֖ה בְּחַ֥ג הַסֻּכּֽוֹת'),
(5740, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 11, 'OT', 'בְּב֣וֹא כָל יִשְׂרָאֵ֗ל לֵרָאוֹת֙ אֶת פְּנֵי֙ יְהוָ֣ה אֱלֹהֶ֔יךָ בַּמָּק֖וֹם אֲשֶׁ֣ר יִבְחָ֑ר תִּקְרָ֞א אֶת הַתּוֹרָ֥ה הַזֹּ֛את נֶ֥גֶד כָּל יִשְׂרָאֵ֖ל בְּאָזְנֵיהֶֽם'),
(5741, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 12, 'OT', 'הַקְהֵ֣ל אֶת הָעָ֗ם הָֽאֲנָשִׁ֤ים וְהַנָּשִׁים֙ וְהַטַּ֔ף וְגֵרְךָ֖ אֲשֶׁ֣ר בִּשְׁעָרֶ֑יךָ לְמַ֨עַן יִשְׁמְע֜וּ וּלְמַ֣עַן יִלְמְד֗וּ וְיָֽרְאוּ֙ אֶת יְהוָ֣ה אֱלֹֽהֵיכֶ֔ם וְשָֽׁמְר֣וּ לַעֲשׂ֔וֹת אֶת כָּל דִּבְרֵ֖י הַתּוֹרָ֥ה הַזֹּֽאת'),
(5742, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 13, 'OT', 'וּבְנֵיהֶ֞ם אֲשֶׁ֣ר לֹֽא יָדְע֗וּ יִשְׁמְעוּ֙ וְלָ֣מְד֔וּ לְיִרְאָ֖ה אֶת יְהוָ֣ה אֱלֹהֵיכֶ֑ם כָּל הַיָּמִ֗ים אֲשֶׁ֨ר אַתֶּ֤ם חַיִּים֙ עַל הָ֣אֲדָמָ֔ה אֲשֶׁ֨ר אַתֶּ֜ם עֹבְרִ֧ים אֶת הַיַּרְדֵּ֛ן שָׁ֖מָּה לְרִשְׁתָּֽהּ'),
(5743, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 14, 'OT', 'וַיֹּ֨אמֶר יְהוָ֜ה אֶל מֹשֶׁ֗ה הֵ֣ן קָרְב֣וּ יָמֶיךָ֮ לָמוּת֒ קְרָ֣א אֶת יְהוֹשֻׁ֗עַ וְהִֽתְיַצְּב֛וּ בְּאֹ֥הֶל מוֹעֵ֖ד וַאֲצַוֶּ֑נּוּ וַיֵּ֤לֶךְ מֹשֶׁה֙ וִֽיהוֹשֻׁ֔עַ וַיִּֽתְיַצְּב֖וּ בְּאֹ֥הֶל מוֹעֵֽד'),
(5744, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 15, 'OT', 'וַיֵּרָ֧א יְהוָ֛ה בָּאֹ֖הֶל בְּעַמּ֣וּד עָנָ֑ן וַיַּעֲמֹ֛ד עַמּ֥וּד הֶעָנָ֖ן עַל פֶּ֥תַח הָאֹֽהֶל'),
(5745, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 16, 'OT', 'וַיֹּ֤אמֶר יְהוָה֙ אֶל מֹשֶׁ֔ה הִנְּךָ֥ שֹׁכֵ֖ב עִם אֲבֹתֶ֑יךָ וְקָם֩ הָעָ֨ם הַזֶּ֜ה וְזָנָ֣ה אַחֲרֵ֣י אֱלֹהֵ֣י נֵֽכַר הָאָ֗רֶץ אֲשֶׁ֨ר ה֤וּא בָא שָׁ֨מָּה֙ בְּקִרְבּ֔וֹ וַעֲזָבַ֕נִי וְהֵפֵר֙ אֶת בְּרִיתִ֔י אֲשֶׁ֥ר כָּרַ֖תִּי אִתּֽוֹ'),
(5746, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 17, 'OT', 'וְחָרָ֣ה אַפִּ֣י ב֣וֹ בַיּוֹם הַ֠הוּא וַעֲזַבְתִּ֞ים וְהִסְתַּרְתִּ֨י פָנַ֤י מֵהֶם֙ וְהָיָ֣ה לֶֽאֱכֹ֔ל וּמְצָאֻ֛הוּ רָע֥וֹת רַבּ֖וֹת וְצָר֑וֹת וְאָמַר֙ בַּיּ֣וֹם הַה֔וּא הֲלֹ֗א עַ֣ל כִּֽי אֵ֤ין אֱלֹהַי֙ בְּקִרְבִּ֔י מְצָא֖וּנִי הָרָע֥וֹת הָאֵֽלֶּה'),
(5747, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 18, 'OT', 'וְאָנֹכִ֗י הַסְתֵּ֨ר אַסְתִּ֤יר פָּנַי֙ בַּיּ֣וֹם הַה֔וּא עַ֥ל כָּל הָרָעָ֖ה אֲשֶׁ֣ר עָשָׂ֑ה כִּ֣י פָנָ֔ה אֶל אֱלֹהִ֖ים אֲחֵרִֽים'),
(5748, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 19, 'OT', 'וְעַתָּ֗ה כִּתְב֤וּ לָכֶם֙ אֶת הַשִּׁירָ֣ה הַזֹּ֔את וְלַמְּדָ֥הּ אֶת בְּנֵי יִשְׂרָאֵ֖ל שִׂימָ֣הּ בְּפִיהֶ֑ם לְמַ֨עַן תִּהְיֶה לִּ֜י הַשִּׁירָ֥ה הַזֹּ֛את לְעֵ֖ד בִּבְנֵ֥י יִשְׂרָאֵֽל'),
(5749, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 20, 'OT', 'כִּֽי אֲבִיאֶ֜נּוּ אֶֽל הָאֲדָמָ֣ה אֲשֶׁר נִשְׁבַּ֣עְתִּי לַאֲבֹתָ֗יו זָבַ֤ת חָלָב֙ וּדְבַ֔שׁ וְאָכַ֥ל וְשָׂבַ֖ע וְדָשֵׁ֑ן וּפָנָ֞ה אֶל אֱלֹהִ֤ים אֲחֵרִים֙ וַעֲבָד֔וּם וְנִ֣אֲצ֔וּנִי וְהֵפֵ֖ר אֶת בְּרִיתִֽי'),
(5750, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 21, 'OT', 'וְ֠הָיָה כִּֽי תִמְצֶ֨אןָ אֹת֜וֹ רָע֣וֹת רַבּוֹת֮ וְצָרוֹת֒ וְ֠עָנְתָה הַשִּׁירָ֨ה הַזֹּ֤את לְפָנָיו֙ לְעֵ֔ד כִּ֛י לֹ֥א תִשָּׁכַ֖ח מִפִּ֣י זַרְע֑וֹ כִּ֧י יָדַ֣עְתִּי אֶת יִצְר֗וֹ אֲשֶׁ֨ר ה֤וּא עֹשֶׂה֙ הַיּ֔וֹם בְּטֶ֣רֶם אֲבִיאֶ֔נּוּ אֶל הָאָ֖רֶץ אֲשֶׁ֥ר נִשְׁבָּֽעְתִּי'),
(5751, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 22, 'OT', 'וַיִּכְתֹּ֥ב מֹשֶׁ֛ה אֶת הַשִּׁירָ֥ה הַזֹּ֖את בַּיּ֣וֹם הַה֑וּא וַֽיְלַמְּדָ֖הּ אֶת בְּנֵ֥י יִשְׂרָאֵֽל'),
(5752, 5, 'WLC', 'WLC', 'he', 'DEU', 31, 23, 'OT', 'וַיְצַ֞ו אֶת יְהוֹשֻׁ֣עַ בִּן נ֗וּן וַיֹּאמֶר֮ חֲזַ֣ק וֶֽאֱמָץ֒ כִּ֣י אַתָּ֗ה תָּבִיא֙ אֶת בְּנֵ֣י יִשְׂרָאֵ֔ל אֶל הָאָ֖רֶץ אֲשֶׁר נִשְׁבַּ֣עְתִּי לָהֶ֑ם וְאָנֹכִ֖י אֶֽהְיֶ֥ה עִמָּֽךְ'),
