(5871, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 1, 'OT', 'וַיִּשְׁלַ֣ח יְהוֹשֻׁ֣עַ בִּן נ֠וּן מִֽן הַשִּׁטִּ֞ים שְׁנַֽיִם אֲנָשִׁ֤ים מְרַגְּלִים֙ חֶ֣רֶשׁ לֵאמֹ֔ר לְכ֛וּ רְא֥וּ אֶת הָאָ֖רֶץ וְאֶת יְרִיח֑וֹ וַיֵּ֨לְכ֜וּ וַ֠יָּבֹאוּ בֵּית אִשָּׁ֥ה זוֹנָ֛ה וּשְׁמָ֥הּ רָחָ֖ב וַיִּשְׁכְּבוּ שָֽׁמָּה'),
(5872, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 2, 'OT', 'וַיֵּ֣אָמַ֔ר לְמֶ֥לֶךְ יְרִיח֖וֹ לֵאמֹ֑ר הִנֵּ֣ה אֲ֠נָשִׁים בָּ֣אוּ הֵ֧נָּה הַלַּ֛יְלָה מִבְּנֵ֥י יִשְׂרָאֵ֖ל לַחְפֹּ֥ר אֶת הָאָֽרֶץ'),
(5873, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 3, 'OT', 'וַיִּשְׁלַח֙ מֶ֣לֶךְ יְרִיח֔וֹ אֶל רָחָ֖ב לֵאמֹ֑ר ה֠וֹצִיאִי הָאֲנָשִׁ֨ים הַבָּאִ֤ים אֵלַ֨יִךְ֙ אֲשֶׁר בָּ֣אוּ לְבֵיתֵ֔ךְ כִּ֛י לַחְפֹּ֥ר אֶת כָּל הָאָ֖רֶץ בָּֽאוּ'),
(5874, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 4, 'OT', 'וַתִּקַּ֧ח הָֽאִשָּׁ֛ה אֶת שְׁנֵ֥י הָאֲנָשִׁ֖ים וַֽתִּצְפְּנ֑וֹ וַתֹּ֣אמֶר כֵּ֗ן בָּ֤אוּ אֵלַי֙ הָֽאֲנָשִׁ֔ים וְלֹ֥א יָדַ֖עְתִּי מֵאַ֥יִן הֵֽמָּה'),
(5875, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 5, 'OT', 'וַיְהִ֨י הַשַּׁ֜עַר לִסְגּ֗וֹר בַּחֹ֨שֶׁךְ֙ וְהָאֲנָשִׁ֣ים יָצָ֔אוּ לֹ֣א יָדַ֔עְתִּי אָ֥נָה הָלְכ֖וּ הָֽאֲנָשִׁ֑ים רִדְפ֥וּ מַהֵ֛ר אַחֲרֵיהֶ֖ם כִּ֥י תַשִּׂיגֽוּם'),
(5876, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 6, 'OT', 'וְהִ֖יא הֶעֱלָ֣תַם הַגָּ֑גָה וַֽתִּטְמְנֵם֙ בְּפִשְׁתֵּ֣י הָעֵ֔ץ הָעֲרֻכ֥וֹת לָ֖הּ עַל הַגָּֽג'),
(5877, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 7, 'OT', 'וְהָאֲנָשִׁ֗ים רָדְפ֤וּ אַֽחֲרֵיהֶם֙ דֶּ֣רֶךְ הַיַּרְדֵּ֔ן עַ֖ל הַֽמַּעְבְּר֑וֹת וְהַשַּׁ֣עַר סָגָ֔רוּ אַחֲרֵ֕י כַּאֲשֶׁ֛ר יָצְא֥וּ הָרֹדְפִ֖ים אַחֲרֵיהֶֽם'),
(5878, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 8, 'OT', 'וְהֵ֖מָּה טֶ֣רֶם יִשְׁכָּב֑וּן וְהִ֛יא עָלְתָ֥ה עֲלֵיהֶ֖ם עַל הַגָּֽג'),
(5879, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 9, 'OT', 'וַתֹּ֨אמֶר֙ אֶל הָ֣אֲנָשִׁ֔ים יָדַ֕עְתִּי כִּֽי נָתַ֧ן יְהוָ֛ה לָכֶ֖ם אֶת הָאָ֑רֶץ וְכִֽי נָפְלָ֤ה אֵֽימַתְכֶם֙ עָלֵ֔ינוּ וְכִ֥י נָמֹ֛גוּ כָּל יֹשְׁבֵ֥י הָאָ֖רֶץ מִפְּנֵיכֶֽם'),
(5880, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 10, 'OT', 'כִּ֣י שָׁמַ֗עְנוּ אֵ֠ת אֲשֶׁר הוֹבִ֨ישׁ יְהוָ֜ה אֶת מֵ֤י יַם סוּף֙ מִפְּנֵיכֶ֔ם בְּצֵאתְכֶ֖ם מִמִּצְרָ֑יִם וַאֲשֶׁ֣ר עֲשִׂיתֶ֡ם לִשְׁנֵי֩ מַלְכֵ֨י הָאֱמֹרִ֜י אֲשֶׁ֨ר בְּעֵ֤בֶר הַיַּרְדֵּן֙ לְסִיחֹ֣ן וּלְע֔וֹג אֲשֶׁ֥ר הֶחֱרַמְתֶּ֖ם אוֹתָֽם'),
(5881, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 11, 'OT', 'וַנִּשְׁמַע֙ וַיִּמַּ֣ס לְבָבֵ֔נוּ וְלֹא קָ֨מָה ע֥וֹד ר֛וּחַ בְּאִ֖ישׁ מִפְּנֵיכֶ֑ם כִּ֚י יְהוָ֣ה אֱלֹֽהֵיכֶ֔ם ה֤וּא אֱלֹהִים֙ בַּשָּׁמַ֣יִם מִמַּ֔עַל וְעַל הָאָ֖רֶץ מִתָּֽחַת'),
(5882, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 12, 'OT', 'וְעַתָּ֗ה הִשָּֽׁבְעוּ נָ֥א לִי֙ בַּֽיהוָ֔ה כִּי עָשִׂ֥יתִי עִמָּכֶ֖ם חָ֑סֶד וַעֲשִׂיתֶ֨ם גַּם אַתֶּ֜ם עִם בֵּ֤ית אָבִי֙ חֶ֔סֶד וּנְתַתֶּ֥ם לִ֖י א֥וֹת אֱמֶֽת'),
(5883, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 13, 'OT', 'וְהַחֲיִתֶ֞ם אֶת אָבִ֣י וְאֶת אִמִּ֗י וְאֶת אַחַי֙ וְאֶת אחותי וְאֵ֖ת כָּל אֲשֶׁ֣ר לָהֶ֑ם וְהִצַּלְתֶּ֥ם אֶת נַפְשֹׁתֵ֖ינוּ מִמָּֽוֶת'),
(5884, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 14, 'OT', 'וַיֹּ֧אמְרוּ לָ֣הּ הָאֲנָשִׁ֗ים נַפְשֵׁ֤נוּ תַחְתֵּיכֶם֙ לָמ֔וּת אִ֚ם לֹ֣א תַגִּ֔ידוּ אֶת דְּבָרֵ֖נוּ זֶ֑ה וְהָיָ֗ה בְּתֵת יְהוָ֥ה לָ֨נוּ֙ אֶת הָאָ֔רֶץ וְעָשִׂ֥ינוּ עִמָּ֖ךְ חֶ֥סֶד וֶאֱמֶֽת'),
(5885, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 15, 'OT', 'וַתּוֹרִדֵ֥ם בַּחֶ֖בֶל בְּעַ֣ד הַֽחַלּ֑וֹן כִּ֤י בֵיתָהּ֙ בְּקִ֣יר הַֽחוֹמָ֔ה וּבַֽחוֹמָ֖ה הִ֥יא יוֹשָֽׁבֶת'),
(5886, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 16, 'OT', 'וַתֹּ֤אמֶר לָהֶם֙ הָהָ֣רָה לֵּ֔כוּ פֶּֽן יִפְגְּע֥וּ בָכֶ֖ם הָרֹדְפִ֑ים וְנַחְבֵּתֶ֨ם שָׁ֜מָּה שְׁלֹ֣שֶׁת יָמִ֗ים עַ֚ד שׁ֣וֹב הָרֹֽדְפִ֔ים וְאַחַ֖ר תֵּלְכ֥וּ לְדַרְכְּכֶֽם'),
(5887, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 17, 'OT', 'וַיֹּאמְר֥וּ אֵלֶ֖יהָ הָאֲנָשִׁ֑ים נְקִיִּ֣ם אֲנַ֔חְנוּ מִשְּׁבֻעָתֵ֥ךְ הַזֶּ֖ה אֲשֶׁ֥ר הִשְׁבַּעְתָּֽנוּ'),
(5888, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 18, 'OT', 'הִנֵּ֛ה אֲנַ֥חְנוּ בָאִ֖ים בָּאָ֑רֶץ אֶת תִּקְוַ֡ת חוּט֩ הַשָּׁנִ֨י הַזֶּ֜ה תִּקְשְׁרִ֗י בַּֽחַלּוֹן֙ אֲשֶׁ֣ר הוֹרַדְתֵּ֣נוּ ב֔וֹ וְאֶת אָבִ֨יךְ וְאֶת אִמֵּ֜ךְ וְאֶת אַחַ֗יִךְ וְאֵת֙ כָּל בֵּ֣ית אָבִ֔יךְ תַּאַסְפִ֥י אֵלַ֖יִךְ הַבָּֽיְתָה'),
(5889, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 19, 'OT', 'וְהָיָ֡ה כֹּ֣ל אֲשֶׁר יֵצֵא֩ מִדַּלְתֵ֨י בֵיתֵ֧ךְ הַח֛וּצָה דָּמ֥וֹ בְרֹאשׁ֖וֹ וַאֲנַ֣חְנוּ נְקִיִּ֑ם וְ֠כֹל אֲשֶׁ֨ר יִֽהְיֶ֤ה אִתָּךְ֙ בַּבַּ֔יִת דָּמ֣וֹ בְרֹאשֵׁ֔נוּ אִם יָ֖ד תִּֽהְיֶה בּֽוֹ'),
(5890, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 20, 'OT', 'וְאִם תַּגִּ֖ידִי אֶת דְּבָרֵ֣נוּ זֶ֑ה וְהָיִ֣ינוּ נְקִיִּ֔ם מִשְּׁבֻעָתֵ֖ךְ אֲשֶׁ֥ר הִשְׁבַּעְתָּֽנוּ'),
(5891, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 21, 'OT', 'וַתֹּ֨אמֶר֙ כְּדִבְרֵיכֶ֣ם כֶּן ה֔וּא וַֽתְּשַׁלְּחֵ֖ם וַיֵּלֵ֑כוּ וַתִּקְשֹׁ֛ר אֶת תִּקְוַ֥ת הַשָּׁנִ֖י בַּחַלּֽוֹן'),
(5892, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 22, 'OT', 'וַיֵּלְכוּ֙ וַיָּבֹ֣אוּ הָהָ֔רָה וַיֵּ֤שְׁבוּ שָׁם֙ שְׁלֹ֣שֶׁת יָמִ֔ים עַד שָׁ֖בוּ הָרֹדְפִ֑ים וַיְבַקְשׁ֧וּ הָרֹדְפִ֛ים בְּכָל הַדֶּ֖רֶךְ וְלֹ֥א מָצָֽאוּ'),
(5893, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 23, 'OT', 'וַיָּשֻׁ֜בוּ שְׁנֵ֤י הָֽאֲנָשִׁים֙ וַיֵּרְד֣וּ מֵֽהָהָ֔ר וַיַּעַבְרוּ֙ וַיָּבֹ֔אוּ אֶל יְהוֹשֻׁ֖עַ בִּן נ֑וּן וַיְסַ֨פְּרוּ ל֔וֹ אֵ֥ת כָּל הַמֹּצְא֖וֹת אוֹתָֽם'),
(5894, 6, 'WLC', 'WLC', 'he', 'JOS', 2, 24, 'OT', 'וַיֹּאמְרוּ֙ אֶל יְהוֹשֻׁ֔עַ כִּֽי נָתַ֧ן יְהוָ֛ה בְּיָדֵ֖נוּ אֶת כָּל הָאָ֑רֶץ וְגַם נָמֹ֛גוּ כָּל יֹשְׁבֵ֥י הָאָ֖רֶץ מִפָּנֵֽינוּ'),
(5895, 6, 'WLC', 'WLC', 'he', 'JOS', 3, 1, 'OT', 'וַיַּשְׁכֵּם֩ יְהוֹשֻׁ֨עַ בַּבֹּ֜קֶר וַיִּסְע֣וּ מֵֽהַשִּׁטִּ֗ים וַיָּבֹ֨אוּ֙ עַד הַיַּרְדֵּ֔ן ה֖וּא וְכָל בְּנֵ֣י יִשְׂרָאֵ֑ל וַיָּלִ֥נוּ שָׁ֖ם טֶ֥רֶם יַעֲבֹֽרוּ'),
(5896, 6, 'WLC', 'WLC', 'he', 'JOS', 3, 2, 'OT', 'וַיְהִ֕י מִקְצֵ֖ה שְׁלֹ֣שֶׁת יָמִ֑ים וַיַּעַבְר֥וּ הַשֹּׁטְרִ֖ים בְּקֶ֥רֶב הַֽמַּחֲנֶֽה'),
(5897, 6, 'WLC', 'WLC', 'he', 'JOS', 3, 3, 'OT', 'וַיְצַוּוּ֮ אֶת הָעָ֣ם לֵאמֹר֒ כִּרְאֽוֹתְכֶ֗ם אֵ֣ת אֲר֤וֹן בְּרִית יְהוָה֙ אֱלֹ֣הֵיכֶ֔ם וְהַכֹּֽהֲנִים֙ הַלְוִיִּ֔ם נֹשְׂאִ֖ים אֹת֑וֹ וְאַתֶּ֗ם תִּסְעוּ֙ מִמְּק֣וֹמְכֶ֔ם וַהֲלַכְתֶּ֖ם אַחֲרָֽיו'),
(5898, 6, 'WLC', 'WLC', 'he', 'JOS', 3, 4, 'OT', 'אַ֣ךְ רָח֣וֹק יִהְיֶ֗ה בֵּֽינֵיכֶם֙ ובינו כְּאַלְפַּ֥יִם אַמָּ֖ה בַּמִּדָּ֑ה אַֽל תִּקְרְב֣וּ אֵלָ֗יו לְמַ֤עַן אֲשֶׁר תֵּֽדְעוּ֙ אֶת הַדֶּ֨רֶךְ֙ אֲשֶׁ֣ר תֵּֽלְכוּ בָ֔הּ כִּ֣י לֹ֧א עֲבַרְתֶּ֛ם בַּדֶּ֖רֶךְ מִתְּמ֥וֹל שִׁלְשֽׁוֹם'),
(5899, 6, 'WLC', 'WLC', 'he', 'JOS', 3, 5, 'OT', 'וַיֹּ֧אמֶר יְהוֹשֻׁ֛עַ אֶל הָעָ֖ם הִתְקַדָּ֑שׁוּ כִּ֣י מָחָ֗ר יַעֲשֶׂ֧ה יְהוָ֛ה בְּקִרְבְּכֶ֖ם נִפְלָאֽוֹת'),
