(5961, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 11, 'OT', 'וַיַּסֵּ֤ב אֲרוֹן יְהוָה֙ אֶת הָעִ֔יר הַקֵּ֖ף פַּ֣עַם אֶחָ֑ת וַיָּבֹ֨אוּ֙ הַֽמַּחֲנֶ֔ה וַיָּלִ֖ינוּ בַּֽמַּחֲנֶֽה'),
(5962, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 12, 'OT', 'וַיַּשְׁכֵּ֥ם יְהוֹשֻׁ֖עַ בַּבֹּ֑קֶר וַיִּשְׂא֥וּ הַכֹּהֲנִ֖ים אֶת אֲר֥וֹן יְהוָֽה'),
(5963, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 13, 'OT', 'וְשִׁבְעָ֣ה הַכֹּהֲנִ֡ים נֹשְׂאִים֩ שִׁבְעָ֨ה שׁוֹפְר֜וֹת הַיֹּבְלִ֗ים לִפְנֵי֙ אֲר֣וֹן יְהוָ֔ה הֹלְכִ֣ים הָל֔וֹךְ וְתָקְע֖וּ בַּשּׁוֹפָר֑וֹת וְהֶחָלוּץ֙ הֹלֵ֣ךְ לִפְנֵיהֶ֔ם וְהַֽמְאַסֵּ֗ף הֹלֵךְ֙ אַֽחֲרֵי֙ אֲר֣וֹן יְהוָ֔ה הולך וְתָק֥וֹעַ בַּשּׁוֹפָרֽוֹת'),
(5964, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 14, 'OT', 'וַיָּסֹ֨בּוּ אֶת הָעִ֜יר בַּיּ֤וֹם הַשֵּׁנִי֙ פַּ֣עַם אַחַ֔ת וַיָּשֻׁ֖בוּ הַֽמַּחֲנֶ֑ה כֹּ֥ה עָשׂ֖וּ שֵׁ֥שֶׁת יָמִֽים'),
(5965, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 15, 'OT', 'וַיְהִ֣י בַּיּ֣וֹם הַשְּׁבִיעִ֗י וַיַּשְׁכִּ֨מוּ֙ כַּעֲל֣וֹת הַשַּׁ֔חַר וַיָּסֹ֧בּוּ אֶת הָעִ֛יר כַּמִּשְׁפָּ֥ט הַזֶּ֖ה שֶׁ֣בַע פְּעָמִ֑ים רַ֚ק בַּיּ֣וֹם הַה֔וּא סָבְב֥וּ אֶת הָעִ֖יר שֶׁ֥בַע פְּעָמִֽים'),
(5966, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 16, 'OT', 'וַיְהִי֙ בַּפַּ֣עַם הַשְּׁבִיעִ֔ית תָּקְע֥וּ הַכֹּהֲנִ֖ים בַּשּׁוֹפָר֑וֹת וַיֹּ֨אמֶר יְהוֹשֻׁ֤עַ אֶל הָעָם֙ הָרִ֔יעוּ כִּֽי נָתַ֧ן יְהוָ֛ה לָכֶ֖ם אֶת הָעִֽיר'),
(5967, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 17, 'OT', 'וְהָיְתָ֨ה הָעִ֥יר חֵ֛רֶם הִ֥יא וְכָל אֲשֶׁר בָּ֖הּ לַֽיהוָ֑ה רַק֩ רָחָ֨ב הַזּוֹנָ֜ה תִּֽחְיֶ֗ה הִ֚יא וְכָל אֲשֶׁ֣ר אִתָּ֣הּ בַּבַּ֔יִת כִּ֣י הֶחְבְּאַ֔תָה אֶת הַמַּלְאָכִ֖ים אֲשֶׁ֥ר שָׁלָֽחְנוּ'),
(5968, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 18, 'OT', 'וְרַק אַתֶּם֙ שִׁמְר֣וּ מִן הַחֵ֔רֶם פֶּֽן תַּחֲרִ֖ימוּ וּלְקַחְתֶּ֣ם מִן הַחֵ֑רֶם וְשַׂמְתֶּ֞ם אֶת מַחֲנֵ֤ה יִשְׂרָאֵל֙ לְחֵ֔רֶם וַעֲכַרְתֶּ֖ם אוֹתֽוֹ'),
(5969, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 19, 'OT', 'וְכֹ֣ל כֶּ֣סֶף וְזָהָ֗ב וּכְלֵ֤י נְחֹ֨שֶׁת֙ וּבַרְזֶ֔ל קֹ֥דֶשׁ ה֖וּא לַֽיהוָ֑ה אוֹצַ֥ר יְהוָ֖ה יָבֽוֹא'),
(5970, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 20, 'OT', 'וַיָּ֣רַע הָעָ֔ם וַֽיִּתְקְע֖וּ בַּשֹּֽׁפָר֑וֹת וַיְהִי֩ כִשְׁמֹ֨עַ הָעָ֜ם אֶת ק֣וֹל הַשּׁוֹפָ֗ר וַיָּרִ֤יעוּ הָעָם֙ תְּרוּעָ֣ה גְדוֹלָ֔ה וַתִּפֹּ֨ל הַֽחוֹמָ֜ה תַּחְתֶּ֗יהָ וַיַּ֨עַל הָעָ֤ם הָעִ֨ירָה֙ אִ֣ישׁ נֶגְדּ֔וֹ וַֽיִּלְכְּד֖וּ אֶת הָעִֽיר'),
(5971, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 21, 'OT', 'וַֽיַּחֲרִ֨ימוּ֙ אֶת כָּל אֲשֶׁ֣ר בָּעִ֔יר מֵאִישׁ֙ וְעַד אִשָּׁ֔ה מִנַּ֖עַר וְעַד זָקֵ֑ן וְעַ֨ד שׁ֥וֹר וָשֶׂ֛ה וַחֲמ֖וֹר לְפִי חָֽרֶב'),
(5972, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 22, 'OT', 'וְלִשְׁנַ֨יִם הָאֲנָשִׁ֜ים הַֽמְרַגְּלִ֤ים אֶת הָאָ֨רֶץ֙ אָמַ֣ר יְהוֹשֻׁ֔עַ בֹּ֖אוּ בֵּית הָאִשָּׁ֣ה הַזּוֹנָ֑ה וְהוֹצִ֨יאוּ מִשָּׁ֤ם אֶת הָֽאִשָּׁה֙ וְאֶת כָּל אֲשֶׁר לָ֔הּ כַּאֲשֶׁ֥ר נִשְׁבַּעְתֶּ֖ם לָֽהּ'),
(5973, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 23, 'OT', 'וַיָּבֹ֜אוּ הַנְּעָרִ֣ים הַֽמְרַגְּלִ֗ים וַיֹּצִ֡יאוּ אֶת רָ֠חָב וְאֶת אָבִ֨יהָ וְאֶת אִמָּ֤הּ וְאֶת אַחֶ֨יהָ֙ וְאֶת כָּל אֲשֶׁר לָ֔הּ וְאֵ֥ת כָּל מִשְׁפְּחוֹתֶ֖יהָ הוֹצִ֑יאוּ וַיַּ֨נִּיח֔וּם מִח֖וּץ לְמַחֲנֵ֥ה יִשְׂרָאֵֽל'),
(5974, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 24, 'OT', 'וְהָעִ֛יר שָׂרְפ֥וּ בָאֵ֖שׁ וְכָל אֲשֶׁר בָּ֑הּ רַ֣ק הַכֶּ֣סֶף וְהַזָּהָ֗ב וּכְלֵ֤י הַנְּחֹ֨שֶׁת֙ וְהַבַּרְזֶ֔ל נָתְנ֖וּ אוֹצַ֥ר בֵּית יְהוָֽה'),
(5975, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 25, 'OT', 'וְֽאֶת רָחָ֣ב הַ֠זּוֹנָה וְאֶת בֵּ֨ית אָבִ֤יהָ וְאֶת כָּל אֲשֶׁר לָהּ֙ הֶחֱיָ֣ה יְהוֹשֻׁ֔עַ וַתֵּ֨שֶׁב֙ בְּקֶ֣רֶב יִשְׂרָאֵ֔ל עַ֖ד הַיּ֣וֹם הַזֶּ֑ה כִּ֤י הֶחְבִּ֨יאָה֙ אֶת הַמַּלְאָכִ֔ים אֲשֶׁר שָׁלַ֥ח יְהוֹשֻׁ֖עַ לְרַגֵּ֥ל אֶת יְרִיחֽוֹ'),
(5976, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 26, 'OT', 'וַיַּשְׁבַּ֣ע יְהוֹשֻׁ֔עַ בָּעֵ֥ת הַהִ֖יא לֵאמֹ֑ר אָר֨וּר הָאִ֜ישׁ לִפְנֵ֣י יְהוָ֗ה אֲשֶׁ֤ר יָקוּם֙ וּבָנָ֞ה אֶת הָעִ֤יר הַזֹּאת֙ אֶת יְרִיח֔וֹ בִּבְכֹר֣וֹ יְיַסְּדֶ֔נָּה וּבִצְעִיר֖וֹ יַצִּ֥יב דְּלָתֶֽיהָ'),
(5977, 6, 'WLC', 'WLC', 'he', 'JOS', 6, 27, 'OT', 'וַיְהִ֥י יְהוָ֖ה אֶת יְהוֹשֻׁ֑עַ וַיְהִ֥י שָׁמְע֖וֹ בְּכָל הָאָֽרֶץ'),
(5978, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 1, 'OT', 'וַיִּמְעֲל֧וּ בְנֵֽי יִשְׂרָאֵ֛ל מַ֖עַל בַּחֵ֑רֶם וַיִּקַּ֡ח עָכָ֣ן בֶּן כַּרְמִי֩ בֶן זַבְדִּ֨י בֶן זֶ֜רַח לְמַטֵּ֤ה יְהוּדָה֙ מִן הַחֵ֔רֶם וַיִּֽחַר אַ֥ף יְהוָ֖ה בִּבְנֵ֥י יִשְׂרָאֵֽל'),
(5979, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 2, 'OT', 'וַיִּשְׁלַח֩ יְהוֹשֻׁ֨עַ אֲנָשִׁ֜ים מִֽירִיח֗וֹ הָעַ֞י אֲשֶׁ֨ר עִם בֵּ֥ית אָ֨וֶן֙ מִקֶּ֣דֶם לְבֵֽית אֵ֔ל וַיֹּ֤אמֶר אֲלֵיהֶם֙ לֵאמֹ֔ר עֲל֖וּ וְרַגְּל֣וּ אֶת הָאָ֑רֶץ וַֽיַּעֲלוּ֙ הָאֲנָשִׁ֔ים וַֽיְרַגְּל֖וּ אֶת הָעָֽי'),
(5980, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 3, 'OT', 'וַיָּשֻׁ֣בוּ אֶל יְהוֹשֻׁ֗עַ וַיֹּאמְר֣וּ אֵלָיו֮ אַל יַ֣עַל כָּל הָעָם֒ כְּאַלְפַּ֣יִם אִ֗ישׁ א֚וֹ כִּשְׁלֹ֣שֶׁת אֲלָפִ֣ים אִ֔ישׁ יַעֲל֖וּ וְיַכּ֣וּ אֶת הָעָ֑י אַל תְּיַגַּע שָׁ֨מָּה֙ אֶת כָּל הָעָ֔ם כִּ֥י מְעַ֖ט הֵֽמָּה'),
(5981, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 4, 'OT', 'וַיַּעֲל֤וּ מִן הָעָם֙ שָׁ֔מָּה כִּשְׁלֹ֥שֶׁת אֲלָפִ֖ים אִ֑ישׁ וַיָּנֻ֕סוּ לִפְנֵ֖י אַנְשֵׁ֥י הָעָֽי'),
(5982, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 5, 'OT', 'וַיַּכּ֨וּ מֵהֶ֜ם אַנְשֵׁ֣י הָעַ֗י כִּשְׁלֹשִׁ֤ים וְשִׁשָּׁה֙ אִ֔ישׁ וַֽיִּרְדְּפ֞וּם לִפְנֵ֤י הַשַּׁ֨עַר֙ עַד הַשְּׁבָרִ֔ים וַיַּכּ֖וּם בַּמּוֹרָ֑ד וַיִּמַּ֥ס לְבַב הָעָ֖ם וַיְהִ֥י לְמָֽיִם'),
(5983, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 6, 'OT', 'וַיִּקְרַ֨ע יְהוֹשֻׁ֜עַ שִׂמְלֹתָ֗יו וַיִּפֹּל֩ עַל פָּנָ֨יו אַ֜רְצָה לִפְנֵ֨י אֲר֤וֹן יְהוָה֙ עַד הָעֶ֔רֶב ה֖וּא וְזִקְנֵ֣י יִשְׂרָאֵ֑ל וַיַּעֲל֥וּ עָפָ֖ר עַל רֹאשָֽׁם'),
(5984, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 7, 'OT', 'וַיֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֲהָ֣הּ אֲדֹנָ֣י יְהוִ֗ה לָ֠מָה הֵעֲבַ֨רְתָּ הַעֲבִ֜יר אֶת הָעָ֤ם הַזֶּה֙ אֶת הַיַּרְדֵּ֔ן לָתֵ֥ת אֹתָ֛נוּ בְּיַ֥ד הָאֱמֹרִ֖י לְהַאֲבִידֵ֑נוּ וְלוּ֙ הוֹאַ֣לְנוּ וַנֵּ֔שֶׁב בְּעֵ֖בֶר הַיַּרְדֵּֽן'),
(5985, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 8, 'OT', 'בִּ֖י אֲדֹנָ֑י מָ֣ה אֹמַ֔ר אַ֠חֲרֵי אֲשֶׁ֨ר הָפַ֧ךְ יִשְׂרָאֵ֛ל עֹ֖רֶף לִפְנֵ֥י אֹיְבָֽיו'),
(5986, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 9, 'OT', 'וְיִשְׁמְע֣וּ הַֽכְּנַעֲנִ֗י וְכֹל֙ יֹשְׁבֵ֣י הָאָ֔רֶץ וְנָסַ֣בּוּ עָלֵ֔ינוּ וְהִכְרִ֥יתוּ אֶת שְׁמֵ֖נוּ מִן הָאָ֑רֶץ וּמַֽה תַּעֲשֵׂ֖ה לְשִׁמְךָ֥ הַגָּדֽוֹל'),
(5987, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 10, 'OT', 'וַיֹּ֧אמֶר יְהוָ֛ה אֶל יְהוֹשֻׁ֖עַ קֻ֣ם לָ֑ךְ לָ֣מָּה זֶּ֔ה אַתָּ֖ה נֹפֵ֥ל עַל פָּנֶֽיךָ'),
(5988, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 11, 'OT', 'חָטָא֙ יִשְׂרָאֵ֔ל וְגַם֙ עָבְר֣וּ אֶת בְּרִיתִ֔י אֲשֶׁ֥ר צִוִּ֖יתִי אוֹתָ֑ם וְגַ֤ם לָֽקְחוּ֙ מִן הַחֵ֔רֶם וְגַ֤ם גָּֽנְבוּ֙ וְגַ֣ם כִּֽחֲשׁ֔וּ וְגַ֖ם שָׂ֥מוּ בִכְלֵיהֶֽם'),
(5989, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 12, 'OT', 'וְלֹ֨א יֻכְל֜וּ בְּנֵ֣י יִשְׂרָאֵ֗ל לָקוּם֙ לִפְנֵ֣י אֹיְבֵיהֶ֔ם עֹ֗רֶף יִפְנוּ֙ לִפְנֵ֣י אֹֽיְבֵיהֶ֔ם כִּ֥י הָי֖וּ לְחֵ֑רֶם לֹ֤א אוֹסִיף֙ לִֽהְי֣וֹת עִמָּכֶ֔ם אִם לֹ֥א תַשְׁמִ֛ידוּ הַחֵ֖רֶם מִֽקִּרְבְּכֶֽם'),
(5990, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 13, 'OT', 'קֻ֚ם קַדֵּ֣שׁ אֶת הָעָ֔ם וְאָמַרְתָּ֖ הִתְקַדְּשׁ֣וּ לְמָחָ֑ר כִּ֣י כֹה֩ אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל חֵ֤רֶם בְּקִרְבְּךָ֙ יִשְׂרָאֵ֔ל לֹ֣א תוּכַ֗ל לָקוּם֙ לִפְנֵ֣י אֹיְבֶ֔יךָ עַד הֲסִירְכֶ֥ם הַחֵ֖רֶם מִֽקִּרְבְּכֶֽם'),
(5991, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 14, 'OT', 'וְנִקְרַבְתֶּ֥ם בַּבֹּ֖קֶר לְשִׁבְטֵיכֶ֑ם וְהָיָ֡ה הַשֵּׁבֶט֩ אֲשֶׁר יִלְכְּדֶ֨נּוּ יְהוָ֜ה יִקְרַ֣ב לַמִּשְׁפָּח֗וֹת וְהַמִּשְׁפָּחָ֞ה אֲשֶֽׁר יִלְכְּדֶ֤נָּה יְהוָה֙ תִּקְרַ֣ב לַבָּתִּ֔ים וְהַבַּ֨יִת֙ אֲשֶׁ֣ר יִלְכְּדֶ֣נּוּ יְהוָ֔ה יִקְרַ֖ב לַגְּבָרִֽים'),
(5992, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 15, 'OT', 'וְהָיָה֙ הַנִּלְכָּ֣ד בַּחֵ֔רֶם יִשָּׂרֵ֣ף בָּאֵ֔שׁ אֹת֖וֹ וְאֶת כָּל אֲשֶׁר ל֑וֹ כִּ֤י עָבַר֙ אֶת בְּרִ֣ית יְהוָ֔ה וְכִֽי עָשָׂ֥ה נְבָלָ֖ה בְּיִשְׂרָאֵֽל'),
(5993, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 16, 'OT', 'וַיַּשְׁכֵּ֤ם יְהוֹשֻׁ֨עַ֙ בַּבֹּ֔קֶר וַיַּקְרֵ֥ב אֶת יִשְׂרָאֵ֖ל לִשְׁבָטָ֑יו וַיִּלָּכֵ֖ד שֵׁ֥בֶט יְהוּדָֽה'),
(5994, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 17, 'OT', 'וַיַּקְרֵב֙ אֶת מִשְׁפַּ֣חַת יְהוּדָ֔ה וַיִּלְכֹּ֕ד אֵ֖ת מִשְׁפַּ֣חַת הַזַּרְחִ֑י וַיַּקְרֵ֞ב אֶת מִשְׁפַּ֤חַת הַזַּרְחִי֙ לַגְּבָרִ֔ים וַיִּלָּכֵ֖ד זַבְדִּֽי'),
(5995, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 18, 'OT', 'וַיַּקְרֵ֥ב אֶת בֵּית֖וֹ לַגְּבָרִ֑ים וַיִּלָּכֵ֗ד עָכָ֞ן בֶּן כַּרְמִ֧י בֶן זַבְדִּ֛י בֶּן זֶ֖רַח לְמַטֵּ֥ה יְהוּדָֽה'),
(5996, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 19, 'OT', 'וַיֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל עָכָ֗ן בְּנִי֙ שִֽׂים נָ֣א כָב֗וֹד לַֽיהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל וְתֶן ל֣וֹ תוֹדָ֑ה וְהַגֶּד נָ֥א לִי֙ מֶ֣ה עָשִׂ֔יתָ אַל תְּכַחֵ֖ד מִמֶּֽנִּי'),
(5997, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 20, 'OT', 'וַיַּ֧עַן עָכָ֛ן אֶת יְהוֹשֻׁ֖עַ וַיֹּאמַ֑ר אָמְנָ֗ה אָנֹכִ֤י חָטָ֨אתִי֙ לַֽיהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל וְכָזֹ֥את וְכָזֹ֖את עָשִֽׂיתִי'),
(5998, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 21, 'OT', 'ואראה בַשָּׁלָ֡ל אַדֶּ֣רֶת שִׁנְעָר֩ אַחַ֨ת טוֹבָ֜ה וּמָאתַ֧יִם שְׁקָלִ֣ים כֶּ֗סֶף וּלְשׁ֨וֹן זָהָ֤ב אֶחָד֙ חֲמִשִּׁ֤ים שְׁקָלִים֙ מִשְׁקָל֔וֹ וָֽאֶחְמְדֵ֖ם וָֽאֶקָּחֵ֑ם וְהִנָּ֨ם טְמוּנִ֥ים בָּאָ֛רֶץ בְּת֥וֹךְ הָאָֽהֳלִ֖י וְהַכֶּ֥סֶף תַּחְתֶּֽיהָ'),
(5999, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 22, 'OT', 'וַיִּשְׁלַ֤ח יְהוֹשֻׁ֨עַ֙ מַלְאָכִ֔ים וַיָּרֻ֖צוּ הָאֹ֑הֱלָה וְהִנֵּ֧ה טְמוּנָ֛ה בְּאָהֳל֖וֹ וְהַכֶּ֥סֶף תַּחְתֶּֽיהָ'),
(6000, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 23, 'OT', 'וַיִּקָּחוּם֙ מִתּ֣וֹךְ הָאֹ֔הֶל וַיְבִאוּם֙ אֶל יְהוֹשֻׁ֔עַ וְאֶ֖ל כָּל בְּנֵ֣י יִשְׂרָאֵ֑ל וַיַּצִּקֻ֖ם לִפְנֵ֥י יְהוָֽה'),
(6001, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 24, 'OT', 'וַיִּקַּ֣ח יְהוֹשֻׁ֣עַ אֶת עָכָ֣ן בֶּן זֶ֡רַח וְאֶת הַכֶּ֣סֶף וְאֶת הָאַדֶּ֣רֶת וְֽאֶת לְשׁ֣וֹן הַזָּהָ֡ב וְֽאֶת בָּנָ֡יו וְֽאֶת בְּנֹתָ֡יו וְאֶת שׁוֹרוֹ֩ וְאֶת חֲמֹר֨וֹ וְאֶת צֹאנ֤וֹ וְאֶֽת אָהֳלוֹ֙ וְאֶת כָּל אֲשֶׁר ל֔וֹ וְכָל יִשְׂרָאֵ֖ל עִמּ֑וֹ וַיַּעֲל֥וּ אֹתָ֖ם עֵ֥מֶק עָכֽוֹר'),
(6002, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 25, 'OT', 'וַיֹּ֤אמֶר יְהוֹשֻׁ֨עַ֙ מֶ֣ה עֲכַרְתָּ֔נוּ יַעְכֳּרְךָ֥ יְהוָ֖ה בַּיּ֣וֹם הַזֶּ֑ה וַיִּרְגְּמ֨וּ אֹת֤וֹ כָל יִשְׂרָאֵל֙ אֶ֔בֶן וַיִּשְׂרְפ֤וּ אֹתָם֙ בָּאֵ֔שׁ וַיִּסְקְל֥וּ אֹתָ֖ם בָּאֲבָנִֽים'),
(6003, 6, 'WLC', 'WLC', 'he', 'JOS', 7, 26, 'OT', 'וַיָּקִ֨ימוּ עָלָ֜יו גַּל אֲבָנִ֣ים גָּד֗וֹל עַ֚ד הַיּ֣וֹם הַזֶּ֔ה וַיָּ֥שָׁב יְהוָ֖ה מֵחֲר֣וֹן אַפּ֑וֹ עַל כֵּ֠ן קָרָ֞א שֵׁ֣ם הַמָּק֤וֹם הַהוּא֙ עֵ֣מֶק עָכ֔וֹר עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(6004, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 1, 'OT', 'וַיֹּ֨אמֶר יְהוָ֤ה אֶל יְהוֹשֻׁ֨עַ֙ אַל תִּירָ֣א וְאַל תֵּחָ֔ת קַ֣ח עִמְּךָ֗ אֵ֚ת כָּל עַ֣ם הַמִּלְחָמָ֔ה וְק֖וּם עֲלֵ֣ה הָעָ֑י רְאֵ֣ה נָתַ֣תִּי בְיָדְךָ֗ אֶת מֶ֤לֶךְ הָעַי֙ וְאֶת עַמּ֔וֹ וְאֶת עִיר֖וֹ וְאֶת אַרְצֽוֹ'),
(6005, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 2, 'OT', 'וְעָשִׂ֨יתָ לָעַ֜י וּלְמַלְכָּ֗הּ כַּאֲשֶׁ֨ר עָשִׂ֤יתָ לִֽירִיחוֹ֙ וּלְמַלְכָּ֔הּ רַק שְׁלָלָ֥הּ וּבְהֶמְתָּ֖הּ תָּבֹ֣זּוּ לָכֶ֑ם שִׂים לְךָ֥ אֹרֵ֛ב לָעִ֖יר מֵאַחֲרֶֽיהָ'),
(6006, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 3, 'OT', 'וַיָּ֧קָם יְהוֹשֻׁ֛עַ וְכָל עַ֥ם הַמִּלְחָמָ֖ה לַעֲל֣וֹת הָעָ֑י וַיִּבְחַ֣ר יְ֠הוֹשֻׁעַ שְׁלֹשִׁ֨ים אֶ֤לֶף אִישׁ֙ גִּבּוֹרֵ֣י הַחַ֔יִל וַיִּשְׁלָחֵ֖ם לָֽיְלָה'),
(6007, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 4, 'OT', 'וַיְצַ֨ו אֹתָ֜ם לֵאמֹ֗ר רְ֠אוּ אַתֶּ֞ם אֹרְבִ֤ים לָעִיר֙ מֵאַחֲרֵ֣י הָעִ֔יר אַל תַּרְחִ֥יקוּ מִן הָעִ֖יר מְאֹ֑ד וִהְיִיתֶ֥ם כֻּלְּכֶ֖ם נְכֹנִֽים'),
(6008, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 5, 'OT', 'וַאֲנִ֗י וְכָל הָעָם֙ אֲשֶׁ֣ר אִתִּ֔י נִקְרַ֖ב אֶל הָעִ֑יר וְהָיָ֗ה כִּֽי יֵצְא֤וּ לִקְרָאתֵ֨נוּ֙ כַּאֲשֶׁ֣ר בָּרִֽאשֹׁנָ֔ה וְנַ֖סְנוּ לִפְנֵיהֶֽם'),
(6009, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 6, 'OT', 'וְיָצְא֣וּ אַחֲרֵ֗ינוּ עַ֣ד הַתִּיקֵ֤נוּ אוֹתָם֙ מִן הָעִ֔יר כִּ֣י יֹֽאמְר֔וּ נָסִ֣ים לְפָנֵ֔ינוּ כַּאֲשֶׁ֖ר בָּרִֽאשֹׁנָ֑ה וְנַ֖סְנוּ לִפְנֵיהֶֽם'),
(6010, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 7, 'OT', 'וְאַתֶּ֗ם תָּקֻ֨מוּ֙ מֵהָ֣אוֹרֵ֔ב וְהוֹרַשְׁתֶּ֖ם אֶת הָעִ֑יר וּנְתָנָ֛הּ יְהוָ֥ה אֱלֹֽהֵיכֶ֖ם בְּיֶדְכֶֽם'),
(6011, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 8, 'OT', 'וְהָיָ֞ה כְּתָפְשְׂכֶ֣ם אֶת הָעִ֗יר תַּצִּ֤יתוּ אֶת הָעִיר֙ בָּאֵ֔שׁ כִּדְבַ֥ר יְהוָ֖ה תַּעֲשׂ֑וּ רְא֖וּ צִוִּ֥יתִי אֶתְכֶֽם'),
(6012, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 9, 'OT', 'וַיִּשְׁלָחֵ֣ם יְהוֹשֻׁ֗עַ וַיֵּֽלְכוּ֙ אֶל הַמַּאְרָ֔ב וַיֵּשְׁב֗וּ בֵּ֧ין בֵּֽית אֵ֛ל וּבֵ֥ין הָעַ֖י מִיָּ֣ם לָעָ֑י וַיָּ֧לֶן יְהוֹשֻׁ֛עַ בַּלַּ֥יְלָה הַה֖וּא בְּת֥וֹךְ הָעָֽם'),
(6013, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 10, 'OT', 'וַיַּשְׁכֵּ֤ם יְהוֹשֻׁ֨עַ֙ בַּבֹּ֔קֶר וַיִּפְקֹ֖ד אֶת הָעָ֑ם וַיַּ֨עַל ה֜וּא וְזִקְנֵ֧י יִשְׂרָאֵ֛ל לִפְנֵ֥י הָעָ֖ם הָעָֽי'),
(6014, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 11, 'OT', 'וְכָל הָעָ֨ם הַמִּלְחָמָ֜ה אֲשֶׁ֣ר אִתּ֗וֹ עָלוּ֙ וַֽיִּגְּשׁ֔וּ וַיָּבֹ֖אוּ נֶ֣גֶד הָעִ֑יר וַֽיַּחֲנוּ֙ מִצְּפ֣וֹן לָעַ֔י וְהַגַּ֖י בינו וּבֵין הָעָֽי'),
(6015, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 12, 'OT', 'וַיִּקַּ֕ח כַּחֲמֵ֥שֶׁת אֲלָפִ֖ים אִ֑ישׁ וַיָּ֨שֶׂם אוֹתָ֜ם אֹרֵ֗ב בֵּ֧ין בֵּֽית אֵ֛ל וּבֵ֥ין הָעַ֖י מִיָּ֥ם לָעִֽיר'),
(6016, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 13, 'OT', 'וַיָּשִׂ֨ימוּ הָעָ֜ם אֶת כָּל הַֽמַּחֲנֶ֗ה אֲשֶׁר֙ מִצְּפ֣וֹן לָעִ֔יר וְאֶת עֲקֵב֖וֹ מִיָּ֣ם לָעִ֑יר וַיֵּ֧לֶךְ יְהוֹשֻׁ֛עַ בַּלַּ֥יְלָה הַה֖וּא בְּת֥וֹךְ הָעֵֽמֶק'),
(6017, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 14, 'OT', 'וַיְהִ֞י כִּרְא֣וֹת מֶֽלֶךְ הָעַ֗י וַֽיְמַהֲר֡וּ וַיַּשְׁכִּ֡ימוּ וַיֵּצְא֣וּ אַנְשֵֽׁי הָעִ֣יר לִקְרַֽאת יִ֠שְׂרָאֵל לַֽמִּלְחָמָ֞ה ה֧וּא וְכָל עַמּ֛וֹ לַמּוֹעֵ֖ד לִפְנֵ֣י הָֽעֲרָבָ֑ה וְהוּא֙ לֹ֣א יָדַ֔ע כִּֽי אֹרֵ֥ב ל֖וֹ מֵאַחֲרֵ֥י הָעִֽיר'),
(6018, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 15, 'OT', 'וַיִּנָּֽגְע֛וּ יְהוֹשֻׁ֥עַ וְכָל יִשְׂרָאֵ֖ל לִפְנֵיהֶ֑ם וַיָּנֻ֖סוּ דֶּ֥רֶךְ הַמִּדְבָּֽר'),
(6019, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 16, 'OT', 'וַיִּזָּעֲק֗וּ כָּל הָעָם֙ אֲשֶׁ֣ר בעיר לִרְדֹּ֖ף אַחֲרֵיהֶ֑ם וַֽיִּרְדְּפוּ֙ אַחֲרֵ֣י יְהוֹשֻׁ֔עַ וַיִּנָּתְק֖וּ מִן הָעִֽיר'),
(6020, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 17, 'OT', 'וְלֹֽא נִשְׁאַ֣ר אִ֗ישׁ בָּעַי֙ וּבֵ֣ית אֵ֔ל אֲשֶׁ֥ר לֹֽא יָצְא֖וּ אַחֲרֵ֣י יִשְׂרָאֵ֑ל וַיַּעַזְב֤וּ אֶת הָעִיר֙ פְּתוּחָ֔ה וַֽיִּרְדְּפ֖וּ אַחֲרֵ֥י יִשְׂרָאֵֽל'),
(6021, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 18, 'OT', 'וַיֹּ֨אמֶר יְהוָ֜ה אֶל יְהוֹשֻׁ֗עַ נְ֠טֵה בַּכִּיד֤וֹן אֲשֶׁר בְּיָֽדְךָ֙ אֶל הָעַ֔י כִּ֥י בְיָדְךָ֖ אֶתְּנֶ֑נָּה וַיֵּ֧ט יְהוֹשֻׁ֛עַ בַּכִּיד֥וֹן אֲשֶׁר בְּיָד֖וֹ אֶל הָעִֽיר'),
(6022, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 19, 'OT', 'וְהָאוֹרֵ֡ב קָם֩ מְהֵרָ֨ה מִמְּקוֹמ֤וֹ וַיָּר֨וּצוּ֙ כִּנְט֣וֹת יָד֔וֹ וַיָּבֹ֥אוּ הָעִ֖יר וַֽיִּלְכְּד֑וּהָ וַֽיְמַהֲר֔וּ וַיַּצִּ֥יתוּ אֶת הָעִ֖יר בָּאֵֽשׁ'),
(6023, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 20, 'OT', 'וַיִּפְנ֣וּ אַנְשֵׁי֩ הָעַ֨י אַחֲרֵיהֶ֜ם וַיִּרְא֗וּ וְהִנֵּ֨ה עָלָ֜ה עֲשַׁ֤ן הָעִיר֙ הַשָּׁמַ֔יְמָה וְלֹא הָיָ֨ה בָהֶ֥ם יָדַ֛יִם לָנ֖וּס הֵ֣נָּה וָהֵ֑נָּה וְהָעָם֙ הַנָּ֣ס הַמִּדְבָּ֔ר נֶהְפַּ֖ךְ אֶל הָרוֹדֵֽף'),
(6024, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 21, 'OT', 'וִיהוֹשֻׁ֨עַ וְכָֽל יִשְׂרָאֵ֜ל רָא֗וּ כִּֽי לָכַ֤ד הָֽאֹרֵב֙ אֶת הָעִ֔יר וְכִ֥י עָלָ֖ה עֲשַׁ֣ן הָעִ֑יר וַיָּשֻׁ֕בוּ וַיַּכּ֖וּ אֶת אַנְשֵׁ֥י הָעָֽי'),
(6025, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 22, 'OT', 'וְאֵ֨לֶּה יָצְא֤וּ מִן הָעִיר֙ לִקְרָאתָ֔ם וַיִּֽהְי֤וּ לְיִשְׂרָאֵל֙ בַּתָּ֔וֶךְ אֵ֥לֶּה מִזֶּ֖ה וְאֵ֣לֶּה מִזֶּ֑ה וַיַּכּ֣וּ אוֹתָ֔ם עַד בִּלְתִּ֥י הִשְׁאִֽיר ל֖וֹ שָׂרִ֥יד וּפָלִֽיט'),
(6026, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 23, 'OT', 'וְאֶת מֶ֥לֶךְ הָעַ֖י תָּ֣פְשׂוּ חָ֑י וַיַּקְרִ֥בוּ אֹת֖וֹ אֶל יְהוֹשֻֽׁעַ'),
(6027, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 24, 'OT', 'וַיְהִ֣י כְּכַלּ֣וֹת יִשְׂרָאֵ֡ל לַהֲרֹג֩ אֶת כָּל יֹשְׁבֵ֨י הָעַ֜י בַּשָּׂדֶ֗ה בַּמִּדְבָּר֙ אֲשֶׁ֣ר רְדָפ֣וּם בּ֔וֹ וַֽיִּפְּל֥וּ כֻלָּ֛ם לְפִי חֶ֖רֶב עַד תֻּמָּ֑ם וַיָּשֻׁ֤בוּ כָל יִשְׂרָאֵל֙ הָעַ֔י וַיַּכּ֥וּ אֹתָ֖הּ לְפִי חָֽרֶב'),
(6028, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 25, 'OT', 'וַיְהִי֩ כָל הַנֹּ֨פְלִ֜ים בַּיּ֤וֹם הַהוּא֙ מֵאִ֣ישׁ וְעַד אִשָּׁ֔ה שְׁנֵ֥ים עָשָׂ֖ר אָ֑לֶף כֹּ֖ל אַנְשֵׁ֥י הָעָֽי'),
(6029, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 26, 'OT', 'וִיהוֹשֻׁ֨עַ֙ לֹֽא הֵשִׁ֣יב יָד֔וֹ אֲשֶׁ֥ר נָטָ֖ה בַּכִּיד֑וֹן עַ֚ד אֲשֶׁ֣ר הֶחֱרִ֔ים אֵ֖ת כָּל יֹשְׁבֵ֥י הָעָֽי'),
(6030, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 27, 'OT', 'רַ֣ק הַבְּהֵמָ֗ה וּשְׁלַל֙ הָעִ֣יר הַהִ֔יא בָּזְז֥וּ לָהֶ֖ם יִשְׂרָאֵ֑ל כִּדְבַ֣ר יְהוָ֔ה אֲשֶׁ֥ר צִוָּ֖ה אֶת יְהוֹשֻֽׁעַ'),
(6031, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 28, 'OT', 'וַיִּשְׂרֹ֥ף יְהוֹשֻׁ֖עַ אֶת הָעָ֑י וַיְשִׂימֶ֤הָ תֵּל עוֹלָם֙ שְׁמָמָ֔ה עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(6032, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 29, 'OT', 'וְאֶת מֶ֧לֶךְ הָעַ֛י תָּלָ֥ה עַל הָעֵ֖ץ עַד עֵ֣ת הָעָ֑רֶב וּכְב֣וֹא הַשֶּׁמֶשׁ֩ צִוָּ֨ה יְהוֹשֻׁ֜עַ וַיֹּרִ֧ידוּ אֶת נִבְלָת֣וֹ מִן הָעֵ֗ץ וַיַּשְׁלִ֤יכוּ אוֹתָהּ֙ אֶל פֶּ֨תַח֙ שַׁ֣עַר הָעִ֔יר וַיָּקִ֤ימוּ עָלָיו֙ גַּל אֲבָנִ֣ים גָּד֔וֹל עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(6033, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 30, 'OT', 'אָ֣ז יִבְנֶ֤ה יְהוֹשֻׁ֨עַ֙ מִזְבֵּ֔חַ לַֽיהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל בְּהַ֖ר עֵיבָֽל'),
(6034, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 31, 'OT', 'כַּאֲשֶׁ֣ר צִוָּה֩ מֹשֶׁ֨ה עֶֽבֶד יְהוָ֜ה אֶת בְּנֵ֣י יִשְׂרָאֵ֗ל כַּכָּתוּב֙ בְּסֵ֨פֶר֙ תּוֹרַ֣ת מֹשֶׁ֔ה מִזְבַּח֙ אֲבָנִ֣ים שְׁלֵמ֔וֹת אֲשֶׁ֛ר לֹֽא הֵנִ֥יף עֲלֵיהֶ֖ן בַּרְזֶ֑ל וַיַּעֲל֨וּ עָלָ֤יו עֹלוֹת֙ לַֽיהוָ֔ה וַֽיִּזְבְּח֖וּ שְׁלָמִֽים'),
(6035, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 32, 'OT', 'וַיִּכְתָּב שָׁ֖ם עַל הָאֲבָנִ֑ים אֵ֗ת מִשְׁנֵה֙ תּוֹרַ֣ת מֹשֶׁ֔ה אֲשֶׁ֣ר כָּתַ֔ב לִפְנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל'),
(6036, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 33, 'OT', 'וְכָל יִשְׂרָאֵ֡ל וּזְקֵנָ֡יו וְשֹׁטְרִ֣ים וְשֹׁפְטָ֡יו עֹמְדִ֣ים מִזֶּ֣ה וּמִזֶּ֣ה לָאָר֡וֹן נֶגֶד֩ הַכֹּהֲנִ֨ים הַלְוִיִּ֜ם נֹשְׂאֵ֣י אֲר֣וֹן בְּרִית יְהוָ֗ה כַּגֵּר֙ כָּֽאֶזְרָ֔ח חֶצְיוֹ֙ אֶל מ֣וּל הַר גְּרִזִ֔ים וְהַֽחֶצְי֖וֹ אֶל מ֣וּל הַר עֵיבָ֑ל כַּאֲשֶׁ֨ר צִוָּ֜ה מֹשֶׁ֣ה עֶֽבֶד יְהוָ֗ה לְבָרֵ֛ךְ אֶת הָעָ֥ם יִשְׂרָאֵ֖ל בָּרִאשֹׁנָֽה'),
(6037, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 34, 'OT', 'וְאַֽחֲרֵי כֵ֗ן קָרָא֙ אֶת כָּל דִּבְרֵ֣י הַתּוֹרָ֔ה הַבְּרָכָ֖ה וְהַקְּלָלָ֑ה כְּכָל הַכָּת֖וּב בְּסֵ֥פֶר הַתּוֹרָֽה'),
(6038, 6, 'WLC', 'WLC', 'he', 'JOS', 8, 35, 'OT', 'לֹֽא הָיָ֣ה דָבָ֔ר מִכֹּ֖ל אֲשֶׁר צִוָּ֣ה מֹשֶׁ֑ה אֲשֶׁ֨ר לֹֽא קָרָ֜א יְהוֹשֻׁ֗עַ נֶ֣גֶד כָּל קְהַ֤ל יִשְׂרָאֵל֙ וְהַנָּשִׁ֣ים וְהַטַּ֔ף וְהַגֵּ֖ר הַהֹלֵ֥ךְ בְּקִרְבָּֽם'),
(6039, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 1, 'OT', 'וַיְהִ֣י כִשְׁמֹ֣עַ כָּֽל הַמְּלָכִ֡ים אֲשֶׁר֩ בְּעֵ֨בֶר הַיַּרְדֵּ֜ן בָּהָ֣ר וּבַשְּׁפֵלָ֗ה וּבְכֹל֙ ח֚וֹף הַיָּ֣ם הַגָּד֔וֹל אֶל מ֖וּל הַלְּבָנ֑וֹן הַֽחִתִּי֙ וְהָ֣אֱמֹרִ֔י הַֽכְּנַעֲנִי֙ הַפְּרִזִּ֔י הַחִוִּ֖י וְהַיְבוּסִֽי'),
(6040, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 2, 'OT', 'וַיִּֽתְקַבְּצ֣וּ יַחְדָּ֔ו לְהִלָּחֵ֥ם עִם יְהוֹשֻׁ֖עַ וְעִם יִשְׂרָאֵ֑ל פֶּ֖ה אֶחָֽד'),
(6041, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 3, 'OT', 'וְיֹשְׁבֵ֨י גִבְע֜וֹן שָׁמְע֗וּ אֵת֩ אֲשֶׁ֨ר עָשָׂ֧ה יְהוֹשֻׁ֛עַ לִֽירִיח֖וֹ וְלָעָֽי'),
(6042, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 4, 'OT', 'וַיַּעֲשׂ֤וּ גַם הֵ֨מָּה֙ בְּעָרְמָ֔ה וַיֵּלְכ֖וּ וַיִּצְטַיָּ֑רוּ וַיִּקְח֞וּ שַׂקִּ֤ים בָּלִים֙ לַחֲמ֣וֹרֵיהֶ֔ם וְנֹאד֥וֹת יַ֨יִן֙ בָּלִ֔ים וּמְבֻקָּעִ֖ים וּמְצֹרָרִֽים'),
(6043, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 5, 'OT', 'וּנְעָל֨וֹת בָּל֤וֹת וּמְטֻלָּאוֹת֙ בְּרַגְלֵיהֶ֔ם וּשְׂלָמ֥וֹת בָּל֖וֹת עֲלֵיהֶ֑ם וְכֹל֙ לֶ֣חֶם צֵידָ֔ם יָבֵ֖שׁ הָיָ֥ה נִקֻּדִֽים'),
(6044, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 6, 'OT', 'וַיֵּלְכ֧וּ אֶל יְהוֹשֻׁ֛עַ אֶל הַֽמַּחֲנֶ֖ה הַגִּלְגָּ֑ל וַיֹּאמְר֨וּ אֵלָ֜יו וְאֶל אִ֣ישׁ יִשְׂרָאֵ֗ל מֵאֶ֤רֶץ רְחוֹקָה֙ בָּ֔אנוּ וְעַתָּ֖ה כִּרְתוּ לָ֥נוּ בְרִֽית'),
(6045, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 7, 'OT', 'ויאמרו אִֽישׁ יִשְׂרָאֵ֖ל אֶל הַחִוִּ֑י אוּלַ֗י בְּקִרְבִּי֙ אַתָּ֣ה יוֹשֵׁ֔ב וְאֵ֖יךְ אכרות לְךָ֥ בְרִֽית'),
(6046, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 8, 'OT', 'וַיֹּאמְר֥וּ אֶל יְהוֹשֻׁ֖עַ עֲבָדֶ֣יךָ אֲנָ֑חְנוּ וַיֹּ֨אמֶר אֲלֵהֶ֧ם יְהוֹשֻׁ֛עַ מִ֥י אַתֶּ֖ם וּמֵאַ֥יִן תָּבֹֽאוּ'),
(6047, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 9, 'OT', 'וַיֹּאמְר֣וּ אֵלָ֗יו מֵאֶ֨רֶץ רְחוֹקָ֤ה מְאֹד֙ בָּ֣אוּ עֲבָדֶ֔יךָ לְשֵׁ֖ם יְהוָ֣ה אֱלֹהֶ֑יךָ כִּֽי שָׁמַ֣עְנוּ שָׁמְע֔וֹ וְאֵ֛ת כָּל אֲשֶׁ֥ר עָשָׂ֖ה בְּמִצְרָֽיִם'),
(6048, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 10, 'OT', 'וְאֵ֣ת כָּל אֲשֶׁ֣ר עָשָׂ֗ה לִשְׁנֵי֙ מַלְכֵ֣י הָאֱמֹרִ֔י אֲשֶׁ֖ר בְּעֵ֣בֶר הַיַּרְדֵּ֑ן לְסִיחוֹן֙ מֶ֣לֶךְ חֶשְׁבּ֔וֹן וּלְע֥וֹג מֶֽלֶךְ הַבָּשָׁ֖ן אֲשֶׁ֥ר בְּעַשְׁתָּרֽוֹת'),
(6049, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 11, 'OT', 'וַיֹּאמְר֣וּ אֵלֵ֡ינוּ זְֽקֵינֵינוּ֩ וְכָל יֹשְׁבֵ֨י אַרְצֵ֜נוּ לֵאמֹ֗ר קְח֨וּ בְיֶדְכֶ֤ם צֵידָה֙ לַדֶּ֔רֶךְ וּלְכ֖וּ לִקְרָאתָ֑ם וַאֲמַרְתֶּ֤ם אֲלֵיהֶם֙ עַבְדֵיכֶ֣ם אֲנַ֔חְנוּ וְעַתָּ֖ה כִּרְתוּ לָ֥נוּ בְרִֽית'),
(6050, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 12, 'OT', 'זֶ֣ה לַחְמֵ֗נוּ חָ֞ם הִצְטַיַּ֤דְנוּ אֹתוֹ֙ מִבָּ֣תֵּ֔ינוּ בְּי֥וֹם צֵאתֵ֖נוּ לָלֶ֣כֶת אֲלֵיכֶ֑ם וְעַתָּה֙ הִנֵּ֣ה יָבֵ֔שׁ וְהָיָ֖ה נִקֻּדִֽים'),
(6051, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 13, 'OT', 'וְאֵ֨לֶּה נֹאד֤וֹת הַיַּ֨יִן֙ אֲשֶׁ֣ר מִלֵּ֣אנוּ חֲדָשִׁ֔ים וְהִנֵּ֖ה הִתְבַּקָּ֑עוּ וְאֵ֤לֶּה שַׂלְמוֹתֵ֨ינוּ֙ וּנְעָלֵ֔ינוּ בָּל֕וּ מֵרֹ֥ב הַדֶּ֖רֶךְ מְאֹֽד'),
(6052, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 14, 'OT', 'וַיִּקְח֥וּ הָֽאֲנָשִׁ֖ים מִצֵּידָ֑ם וְאֶת פִּ֥י יְהוָ֖ה לֹ֥א שָׁאָֽלוּ'),
(6053, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 15, 'OT', 'וַיַּ֨עַשׂ לָהֶ֤ם יְהוֹשֻׁ֨עַ֙ שָׁל֔וֹם וַיִּכְרֹ֥ת לָהֶ֛ם בְּרִ֖ית לְחַיּוֹתָ֑ם וַיִּשָּׁבְע֣וּ לָהֶ֔ם נְשִׂיאֵ֖י הָעֵדָֽה'),
(6054, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 16, 'OT', 'וַיְהִ֗י מִקְצֵה֙ שְׁלֹ֣שֶׁת יָמִ֔ים אַחֲרֵ֕י אֲשֶׁר כָּרְת֥וּ לָהֶ֖ם בְּרִ֑ית וַֽיִּשְׁמְע֗וּ כִּי קְרֹבִ֥ים הֵם֙ אֵלָ֔יו וּבְקִרְבּ֖וֹ הֵ֥ם יֹשְׁבִֽים'),
(6055, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 17, 'OT', 'וַיִּסְע֣וּ בְנֵֽי יִשְׂרָאֵ֗ל וַיָּבֹ֛אוּ אֶל עָרֵיהֶ֖ם בַּיּ֣וֹם הַשְּׁלִישִׁ֑י וְעָרֵיהֶם֙ גִּבְע֣וֹן וְהַכְּפִירָ֔ה וּבְאֵר֖וֹת וְקִרְיַ֥ת יְעָרִֽים'),
(6056, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 18, 'OT', 'וְלֹ֤א הִכּוּם֙ בְּנֵ֣י יִשְׂרָאֵ֔ל כִּֽי נִשְׁבְּע֤וּ לָהֶם֙ נְשִׂיאֵ֣י הָֽעֵדָ֔ה בַּֽיהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וַיִּלֹּ֥נוּ כָל הָעֵדָ֖ה עַל הַנְּשִׂיאִֽים'),
(6057, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 19, 'OT', 'וַיֹּאמְר֤וּ כָל הַנְּשִׂיאִים֙ אֶל כָּל הָ֣עֵדָ֔ה אֲנַ֨חְנוּ֙ נִשְׁבַּ֣עְנוּ לָהֶ֔ם בַּֽיהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְעַתָּ֕ה לֹ֥א נוּכַ֖ל לִנְגֹּ֥עַ בָּהֶֽם'),
(6058, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 20, 'OT', 'זֹ֛את נַעֲשֶׂ֥ה לָהֶ֖ם וְהַחֲיֵ֣ה אוֹתָ֑ם וְלֹֽא יִֽהְיֶ֤ה עָלֵ֨ינוּ֙ קֶ֔צֶף עַל הַשְּׁבוּעָ֖ה אֲשֶׁר נִשְׁבַּ֥עְנוּ לָהֶֽם'),
(6059, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 21, 'OT', 'וַיֹּאמְר֧וּ אֲלֵיהֶ֛ם הַנְּשִׂיאִ֖ים יִֽחְי֑וּ וַ֠יִּֽהְיוּ חֹטְבֵ֨י עֵצִ֤ים וְשֹֽׁאֲבֵי מַ֨יִם֙ לְכָל הָ֣עֵדָ֔ה כַּאֲשֶׁ֛ר דִּבְּר֥וּ לָהֶ֖ם הַנְּשִׂיאִֽים'),
(6060, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 22, 'OT', 'וַיִּקְרָ֤א לָהֶם֙ יְהוֹשֻׁ֔עַ וַיְדַבֵּ֥ר אֲלֵיהֶ֖ם לֵאמֹ֑ר לָמָּה֩ רִמִּיתֶ֨ם אֹתָ֜נוּ לֵאמֹ֗ר רְחוֹקִ֨ים אֲנַ֤חְנוּ מִכֶּם֙ מְאֹ֔ד וְאַתֶּ֖ם בְּקִרְבֵּ֥נוּ יֹשְׁבִֽים'),
(6061, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 23, 'OT', 'וְעַתָּ֖ה אֲרוּרִ֣ים אַתֶּ֑ם וְלֹֽא יִכָּרֵ֨ת מִכֶּ֜ם עֶ֗בֶד וְחֹטְבֵ֥י עֵצִ֛ים וְשֹֽׁאֲבֵי מַ֖יִם לְבֵ֥ית אֱלֹהָֽי'),
(6062, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 24, 'OT', 'וַיַּעֲנ֨וּ אֶת יְהוֹשֻׁ֜עַ וַיֹּאמְר֗וּ כִּי֩ הֻגֵּ֨ד הֻגַּ֤ד לַעֲבָדֶ֨יךָ֙ אֵת֩ אֲשֶׁ֨ר צִוָּ֜ה יְהוָ֤ה אֱלֹהֶ֨יךָ֙ אֶת מֹשֶׁ֣ה עַבְדּ֔וֹ לָתֵ֤ת לָכֶם֙ אֶת כָּל הָאָ֔רֶץ וּלְהַשְׁמִ֛יד אֶת כָּל יֹשְׁבֵ֥י הָאָ֖רֶץ מִפְּנֵיכֶ֑ם וַנִּירָ֨א מְאֹ֤ד לְנַפְשֹׁתֵ֨ינוּ֙ מִפְּנֵיכֶ֔ם וַֽנַּעֲשֵׂ֖ה אֶת הַדָּבָ֥ר הַזֶּֽה'),
(6063, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 25, 'OT', 'וְעַתָּ֖ה הִנְנ֣וּ בְיָדֶ֑ךָ כַּטּ֨וֹב וְכַיָּשָׁ֧ר בְּעֵינֶ֛יךָ לַעֲשׂ֥וֹת לָ֖נוּ עֲשֵֽׂה'),
(6064, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 26, 'OT', 'וַיַּ֥עַשׂ לָהֶ֖ם כֵּ֑ן וַיַּצֵּ֥ל אוֹתָ֛ם מִיַּ֥ד בְּנֵֽי יִשְׂרָאֵ֖ל וְלֹ֥א הֲרָגֽוּם'),
(6065, 6, 'WLC', 'WLC', 'he', 'JOS', 9, 27, 'OT', 'וַיִּתְּנֵ֨ם יְהוֹשֻׁ֜עַ בַּיּ֣וֹם הַה֗וּא חֹטְבֵ֥י עֵצִ֛ים וְשֹׁ֥אֲבֵי מַ֖יִם לָֽעֵדָ֑ה וּלְמִזְבַּ֤ח יְהוָה֙ עַד הַיּ֣וֹם הַזֶּ֔ה אֶל הַמָּק֖וֹם אֲשֶׁ֥ר יִבְחָֽר'),
(6066, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 1, 'OT', 'וַיְהִי֩ כִשְׁמֹ֨עַ אֲדֹֽנִי צֶ֜דֶק מֶ֣לֶךְ יְרוּשָׁלִַ֗ם כִּֽי לָכַ֨ד יְהוֹשֻׁ֣עַ אֶת הָעַי֮ וַיַּחֲרִימָהּ֒ כַּאֲשֶׁ֨ר עָשָׂ֤ה לִֽירִיחוֹ֙ וּלְמַלְכָּ֔הּ כֵּן עָשָׂ֥ה לָעַ֖י וּלְמַלְכָּ֑הּ וְכִ֨י הִשְׁלִ֜ימוּ יֹשְׁבֵ֤י גִבְעוֹן֙ אֶת יִשְׂרָאֵ֔ל וַיִּֽהְי֖וּ בְּקִרְבָּֽם'),
(6067, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 2, 'OT', 'וַיִּֽירְא֣וּ מְאֹ֔ד כִּ֣י עִ֤יר גְּדוֹלָה֙ גִּבְע֔וֹן כְּאַחַ֖ת עָרֵ֣י הַמַּמְלָכָ֑ה וְכִ֨י הִ֤יא גְדוֹלָה֙ מִן הָעַ֔י וְכָל אֲנָשֶׁ֖יהָ גִּבֹּרִֽים'),
(6068, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 3, 'OT', 'וַיִּשְׁלַ֨ח אֲדֹנִי צֶ֜דֶק מֶ֣לֶךְ יְרוּשָׁלִַ֗ם אֶל הוֹהָ֣ם מֶֽלֶךְ חֶ֠בְרוֹן וְאֶל פִּרְאָ֨ם מֶֽלֶךְ יַרְמ֜וּת וְאֶל יָפִ֧יעַ מֶֽלֶךְ לָכִ֛ישׁ וְאֶל דְּבִ֥יר מֶֽלֶךְ עֶגְל֖וֹן לֵאמֹֽר'),
(6069, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 4, 'OT', 'עֲלֽוּ אֵלַ֣י וְעִזְרֻ֔נִי וְנַכֶּ֖ה אֶת גִּבְע֑וֹן כִּֽי הִשְׁלִ֥ימָה אֶת יְהוֹשֻׁ֖עַ וְאֶת בְּנֵ֥י יִשְׂרָאֵֽל'),
(6070, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 5, 'OT', 'וַיֵּאָסְפ֨וּ וַֽיַּעֲל֜וּ חֲמֵ֣שֶׁת מַלְכֵ֣י הָאֱמֹרִ֗י מֶ֣לֶךְ יְרוּשָׁלִַ֜ם מֶֽלֶךְ חֶבְר֤וֹן מֶֽלֶךְ יַרְמוּת֙ מֶֽלֶךְ לָכִ֣ישׁ מֶֽלֶךְ עֶגְל֔וֹן הֵ֖ם וְכָל מַֽחֲנֵיהֶ֑ם וַֽיַּחֲנוּ֙ עַל גִּבְע֔וֹן וַיִּֽלָּחֲמ֖וּ עָלֶֽיהָ'),
(6071, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 6, 'OT', 'וַיִּשְׁלְח֣וּ אַנְשֵׁי֩ גִבְע֨וֹן אֶל יְהוֹשֻׁ֤עַ אֶל הַֽמַּחֲנֶה֙ הַגִּלְגָּ֣לָה לֵאמֹ֔ר אַל תֶּ֥רֶף יָדֶ֖יךָ מֵֽעֲבָדֶ֑יךָ עֲלֵ֧ה אֵלֵ֣ינוּ מְהֵרָ֗ה וְהוֹשִׁ֤יעָה לָּ֨נוּ֙ וְעָזְרֵ֔נוּ כִּ֚י נִקְבְּצ֣וּ אֵלֵ֔ינוּ כָּל מַלְכֵ֥י הָאֱמֹרִ֖י יֹשְׁבֵ֥י הָהָֽר'),
(6072, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 7, 'OT', 'וַיַּ֨עַל יְהוֹשֻׁ֜עַ מִן הַגִּלְגָּ֗ל ה֚וּא וְכָל עַ֤ם הַמִּלְחָמָה֙ עִמּ֔וֹ וְכֹ֖ל גִּבּוֹרֵ֥י הֶחָֽיִל'),
(6073, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 8, 'OT', 'וַיֹּ֨אמֶר יְהוָ֤ה אֶל יְהוֹשֻׁ֨עַ֙ אַל תִּירָ֣א מֵהֶ֔ם כִּ֥י בְיָדְךָ֖ נְתַתִּ֑ים לֹֽא יַעֲמֹ֥ד אִ֛ישׁ מֵהֶ֖ם בְּפָנֶֽיךָ'),
(6074, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 9, 'OT', 'וַיָּבֹ֧א אֲלֵיהֶ֛ם יְהוֹשֻׁ֖עַ פִּתְאֹ֑ם כָּל הַלַּ֕יְלָה עָלָ֖ה מִן הַגִּלְגָּֽל'),
(6075, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 10, 'OT', 'וַיְהֻמֵּ֤ם יְהוָה֙ לִפְנֵ֣י יִשְׂרָאֵ֔ל וַיַּכֵּ֥ם מַכָּֽה גְדוֹלָ֖ה בְּגִבְע֑וֹן וַֽיִּרְדְּפֵ֗ם דֶּ֚רֶךְ מַעֲלֵ֣ה בֵית חוֹרֹ֔ן וַיַּכֵּ֥ם עַד עֲזֵקָ֖ה וְעַד מַקֵּדָֽה'),
(6076, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 11, 'OT', 'וַיְהִ֞י בְּנֻסָ֣ם מִפְּנֵ֣י יִשְׂרָאֵ֗ל הֵ֞ם בְּמוֹרַ֤ד בֵּית חוֹרֹן֙ וַֽיהוָ֡ה הִשְׁלִ֣יךְ עֲלֵיהֶם֩ אֲבָנִ֨ים גְּדֹל֧וֹת מִן הַשָּׁמַ֛יִם עַד עֲזֵקָ֖ה וַיָּמֻ֑תוּ רַבִּ֗ים אֲשֶׁר מֵ֨תוּ֙ בְּאַבְנֵ֣י הַבָּרָ֔ד מֵאֲשֶׁ֥ר הָרְג֛וּ בְּנֵ֥י יִשְׂרָאֵ֖ל בֶּחָֽרֶב'),
(6077, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 12, 'OT', 'אָ֣ז יְדַבֵּ֤ר יְהוֹשֻׁעַ֙ לַֽיהוָ֔ה בְּי֗וֹם תֵּ֤ת יְהוָה֙ אֶת הָ֣אֱמֹרִ֔י לִפְנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל וַיֹּ֣אמֶר לְעֵינֵ֣י יִשְׂרָאֵ֗ל שֶׁ֚מֶשׁ בְּגִבְע֣וֹן דּ֔וֹם וְיָרֵ֖חַ בְּעֵ֥מֶק אַיָּלֽוֹן'),
(6078, 6, 'WLC', 'WLC', 'he', 'JOS', 10, 13, 'OT', 'וַיִּדֹּ֨ם הַשֶּׁ֜מֶשׁ וְיָרֵ֣חַ עָמָ֗ד עַד יִקֹּ֥ם גּוֹי֙ אֹֽיְבָ֔יו הֲלֹא הִ֥יא כְתוּבָ֖ה עַל סֵ֣פֶר הַיָּשָׁ֑ר וַיַּעֲמֹ֤ד הַשֶּׁ֨מֶשׁ֙ בַּחֲצִ֣י הַשָּׁמַ֔יִם וְלֹא אָ֥ץ לָב֖וֹא כְּי֥וֹם תָּמִֽים'),
