(6446, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 19, 'OT', 'וְאַ֨ךְ אִם טְמֵאָ֜ה אֶ֣רֶץ אֲחֻזַּתְכֶ֗ם עִבְר֨וּ לָכֶ֜ם אֶל אֶ֨רֶץ אֲחֻזַּ֤ת יְהוָה֙ אֲשֶׁ֤ר שָֽׁכַן שָׁם֙ מִשְׁכַּ֣ן יְהוָ֔ה וְהֵאָחֲז֖וּ בְּתוֹכֵ֑נוּ וּבַֽיהוָ֣ה אַל תִּמְרֹ֗דוּ וְאֹתָ֨נוּ֙ אֶל תִּמְרֹ֔דוּ בִּבְנֹֽתְכֶ֤ם לָכֶם֙ מִזְבֵּ֔חַ מִֽבַּלְעֲדֵ֔י מִזְבַּ֖ח יְהוָ֥ה אֱלֹהֵֽינוּ'),
(6447, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 20, 'OT', 'הֲל֣וֹא עָכָ֣ן בֶּן זֶ֗רַח מָ֤עַל מַ֨עַל֙ בַּחֵ֔רֶם וְעַֽל כָּל עֲדַ֥ת יִשְׂרָאֵ֖ל הָ֣יָה קָ֑צֶף וְהוּא֙ אִ֣ישׁ אֶחָ֔ד לֹ֥א גָוַ֖ע בַּעֲוֺנֽוֹ'),
(6448, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 21, 'OT', 'וַֽיַּעֲנוּ֙ בְּנֵי רְאוּבֵ֣ן וּבְנֵי גָ֔ד וַחֲצִ֖י שֵׁ֣בֶט הַֽמְנַשֶּׁ֑ה וַֽיְדַבְּר֔וּ אֶת רָאשֵׁ֖י אַלְפֵ֥י יִשְׂרָאֵֽל'),
(6449, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 22, 'OT', 'אֵל֩ אֱלֹהִ֨ים יְהוָ֜ה אֵ֣ל אֱלֹהִ֤ים יְהוָה֙ ה֣וּא יֹדֵ֔עַ וְיִשְׂרָאֵ֖ל ה֣וּא יֵדָ֑ע אִם בְּמֶ֤רֶד וְאִם בְּמַ֨עַל֙ בַּֽיהוָ֔ה אַל תּוֹשִׁיעֵ֖נוּ הַיּ֥וֹם הַזֶּֽה'),
(6450, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 23, 'OT', 'לִבְנ֥וֹת לָ֨נוּ֙ מִזְבֵּ֔חַ לָשׁ֖וּב מֵאַחֲרֵ֣י יְהוָ֑ה וְאִם לְהַעֲל֨וֹת עָלָ֜יו עוֹלָ֣ה וּמִנְחָ֗ה וְאִם לַעֲשׂ֤וֹת עָלָיו֙ זִבְחֵ֣י שְׁלָמִ֔ים יְהוָ֖ה ה֥וּא יְבַקֵּֽשׁ'),
(6451, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 24, 'OT', 'וְאִם לֹ֤א מִדְּאָגָה֙ מִדָּבָ֔ר עָשִׂ֥ינוּ אֶת זֹ֖את לֵאמֹ֑ר מָחָ֗ר יֹאמְר֨וּ בְנֵיכֶ֤ם לְבָנֵ֨ינוּ֙ לֵאמֹ֔ר מַה לָּכֶ֕ם וְלַֽיהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל'),
(6452, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 25, 'OT', 'וּגְב֣וּל נָֽתַן יְ֠הוָה בֵּינֵ֨נוּ וּבֵינֵיכֶ֜ם בְּנֵי רְאוּבֵ֤ן וּבְנֵי גָד֙ אֶת הַיַּרְדֵּ֔ן אֵין לָכֶ֥ם חֵ֖לֶק בַּֽיהוָ֑ה וְהִשְׁבִּ֤יתוּ בְנֵיכֶם֙ אֶת בָּנֵ֔ינוּ לְבִלְתִּ֖י יְרֹ֥א אֶת יְהוָֽה'),
(6453, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 26, 'OT', 'וַנֹּ֕אמֶר נַעֲשֶׂה נָּ֣א לָ֔נוּ לִבְנ֖וֹת אֶת הַמִּזְבֵּ֑חַ לֹ֥א לְעוֹלָ֖ה וְלֹ֥א לְזָֽבַח'),
(6454, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 27, 'OT', 'כִּי֩ עֵ֨ד ה֜וּא בֵּינֵ֣ינוּ וּבֵינֵיכֶ֗ם וּבֵ֣ין דֹּרוֹתֵינוּ֮ אַחֲרֵינוּ֒ לַעֲבֹ֞ד אֶת עֲבֹדַ֤ת יְהוָה֙ לְפָנָ֔יו בְּעֹלוֹתֵ֥ינוּ וּבִזְבָחֵ֖ינוּ וּבִשְׁלָמֵ֑ינוּ וְלֹא יֹאמְר֨וּ בְנֵיכֶ֤ם מָחָר֙ לְבָנֵ֔ינוּ אֵין לָכֶ֥ם חֵ֖לֶק בַּיהוָֽה'),
(6455, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 28, 'OT', 'וַנֹּ֕אמֶר וְהָיָ֗ה כִּֽי יֹאמְר֥וּ אֵלֵ֛ינוּ וְאֶל דֹּרֹתֵ֖ינוּ מָחָ֑ר וְאָמַ֡רְנוּ רְא֣וּ אֶת תַּבְנִית֩ מִזְבַּ֨ח יְהוָ֜ה אֲשֶׁר עָשׂ֣וּ אֲבוֹתֵ֗ינוּ לֹ֤א לְעוֹלָה֙ וְלֹ֣א לְזֶ֔בַח כִּי עֵ֣ד ה֔וּא בֵּינֵ֖ינוּ וּבֵינֵיכֶֽם'),
(6456, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 29, 'OT', 'חָלִילָה֩ לָּ֨נוּ מִמֶּ֜נּוּ לִמְרֹ֣ד בַּֽיהוָ֗ה וְלָשׁ֤וּב הַיּוֹם֙ מֵאַחֲרֵ֣י יְהוָ֔ה לִבְנ֣וֹת מִזְבֵּ֔חַ לְעֹלָ֖ה לְמִנְחָ֣ה וּלְזָ֑בַח מִלְּבַ֗ד מִזְבַּח֙ יְהוָ֣ה אֱלֹהֵ֔ינוּ אֲשֶׁ֖ר לִפְנֵ֥י מִשְׁכָּנֽוֹ'),
(6457, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 30, 'OT', 'וַיִּשְׁמַ֞ע פִּֽינְחָ֣ס הַכֹּהֵ֗ן וּנְשִׂיאֵ֨י הָעֵדָ֜ה וְרָאשֵׁ֨י אַלְפֵ֤י יִשְׂרָאֵל֙ אֲשֶׁ֣ר אִתּ֔וֹ אֶת הַ֨דְּבָרִ֔ים אֲשֶׁ֧ר דִּבְּר֛וּ בְּנֵי רְאוּבֵ֥ן וּבְנֵי גָ֖ד וּבְנֵ֣י מְנַשֶּׁ֑ה וַיִּיטַ֖ב בְּעֵינֵיהֶֽם'),
(6458, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 31, 'OT', 'וַיֹּ֣אמֶר פִּֽינְחָ֣ס בֶּן אֶלְעָזָ֣ר הַכֹּהֵ֡ן אֶל בְּנֵי רְאוּבֵ֨ן וְאֶל בְּנֵי גָ֜ד וְאֶל בְּנֵ֣י מְנַשֶּׁ֗ה הַיּ֤וֹם יָדַ֨עְנוּ֙ כִּֽי בְתוֹכֵ֣נוּ יְהוָ֔ה אֲשֶׁ֛ר לֹֽא מְעַלְתֶּ֥ם בַּֽיהוָ֖ה הַמַּ֣עַל הַזֶּ֑ה אָ֗ז הִצַּלְתֶּ֛ם אֶת בְּנֵ֥י יִשְׂרָאֵ֖ל מִיַּ֥ד יְהוָֽה'),
(6459, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 32, 'OT', 'וַיָּ֣שָׁב פִּֽינְחָ֣ס בֶּן אֶלְעָזָ֣ר הַכֹּהֵ֣ן וְהַנְּשִׂיאִ֡ים מֵאֵ֣ת בְּנֵֽי רְאוּבֵן֩ וּמֵאֵ֨ת בְּנֵי גָ֜ד מֵאֶ֧רֶץ הַגִּלְעָ֛ד אֶל אֶ֥רֶץ כְּנַ֖עַן אֶל בְּנֵ֣י יִשְׂרָאֵ֑ל וַיָּשִׁ֥בוּ אוֹתָ֖ם דָּבָֽר'),
(6460, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 33, 'OT', 'וַיִּיטַ֣ב הַדָּבָ֗ר בְּעֵינֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַיְבָרֲכ֥וּ אֱלֹהִ֖ים בְּנֵ֣י יִשְׂרָאֵ֑ל וְלֹ֣א אָמְר֗וּ לַעֲל֤וֹת עֲלֵיהֶם֙ לַצָּבָ֔א לְשַׁחֵת֙ אֶת הָאָ֔רֶץ אֲשֶׁ֛ר בְּנֵי רְאוּבֵ֥ן וּבְנֵי גָ֖ד יֹשְׁבִ֥ים בָּֽהּ'),
(6461, 6, 'WLC', 'WLC', 'he', 'JOS', 22, 34, 'OT', 'וַֽיִּקְרְא֛וּ בְּנֵי רְאוּבֵ֥ן וּבְנֵי גָ֖ד לַמִּזְבֵּ֑חַ כִּ֣י עֵ֥ד הוּא֙ בֵּֽינֹתֵ֔ינוּ כִּ֥י יְהוָ֖ה הָאֱלֹהִֽים'),
(6462, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 1, 'OT', 'וַֽיְהִי֙ מִיָּמִ֣ים רַבִּ֔ים אַ֠חֲרֵי אֲשֶׁר הֵנִ֨יחַ יְהוָ֧ה לְיִשְׂרָאֵ֛ל מִכָּל אֹיְבֵיהֶ֖ם מִסָּבִ֑יב וִיהוֹשֻׁ֣עַ זָקֵ֔ן בָּ֖א בַּיָּמִֽים'),
(6463, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 2, 'OT', 'וַיִּקְרָ֤א יְהוֹשֻׁ֨עַ֙ לְכָל יִשְׂרָאֵ֔ל לִזְקֵנָיו֙ וּלְרָאשָׁ֔יו וּלְשֹׁפְטָ֖יו וּלְשֹֽׁטְרָ֑יו וַיֹּ֣אמֶר אֲלֵהֶ֔ם אֲנִ֣י זָקַ֔נְתִּי בָּ֖אתִי בַּיָּמִֽים'),
(6464, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 3, 'OT', 'וְאַתֶּ֣ם רְאִיתֶ֗ם אֵת֩ כָּל אֲשֶׁ֨ר עָשָׂ֜ה יְהוָ֧ה אֱלֹהֵיכֶ֛ם לְכָל הַגּוֹיִ֥ם הָאֵ֖לֶּה מִפְּנֵיכֶ֑ם כִּ֚י יְהוָ֣ה אֱלֹהֵיכֶ֔ם ה֖וּא הַנִּלְחָ֥ם לָכֶֽם'),
(6465, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 4, 'OT', 'רְאוּ֩ הִפַּ֨לְתִּי לָכֶ֜ם אֶֽת הַ֠גּוֹיִם הַנִּשְׁאָרִ֥ים הָאֵ֛לֶּה בְּנַחֲלָ֖ה לְשִׁבְטֵיכֶ֑ם מִן הַיַּרְדֵּ֗ן וְכָל הַגּוֹיִם֙ אֲשֶׁ֣ר הִכְרַ֔תִּי וְהַיָּ֥ם הַגָּד֖וֹל מְב֥וֹא הַשָּֽׁמֶשׁ'),
(6466, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 5, 'OT', 'וַיהוָ֣ה אֱלֹֽהֵיכֶ֗ם ה֚וּא יֶהְדֳּפֵ֣ם מִפְּנֵיכֶ֔ם וְהוֹרִ֥ישׁ אֹתָ֖ם מִלִּפְנֵיכֶ֑ם וִֽירִשְׁתֶּם֙ אֶת אַרְצָ֔ם כַּאֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֵיכֶ֖ם לָכֶֽם'),
(6467, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 6, 'OT', 'וַחֲזַקְתֶּ֣ם מְאֹ֔ד לִשְׁמֹ֣ר וְלַעֲשׂ֔וֹת אֵ֚ת כָּל הַכָּת֔וּב בְּסֵ֖פֶר תּוֹרַ֣ת מֹשֶׁ֑ה לְבִלְתִּ֥י סוּר מִמֶּ֖נּוּ יָמִ֥ין וּשְׂמֹֽאול'),
(6468, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 7, 'OT', 'לְבִלְתִּי בוֹא֙ בַּגּוֹיִ֣ם הָאֵ֔לֶּה הַנִּשְׁאָרִ֥ים הָאֵ֖לֶּה אִתְּכֶ֑ם וּבְשֵׁ֨ם אֱלֹהֵיהֶ֤ם לֹא תַזְכִּ֨ירוּ֙ וְלֹ֣א תַשְׁבִּ֔יעוּ וְלֹ֣א תַעַבְד֔וּם וְלֹ֥א תִֽשְׁתַּחֲו֖וּ לָהֶֽם'),
(6469, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 8, 'OT', 'כִּ֛י אִם בַּיהוָ֥ה אֱלֹהֵיכֶ֖ם תִּדְבָּ֑קוּ כַּאֲשֶׁ֣ר עֲשִׂיתֶ֔ם עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(6470, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 9, 'OT', 'וַיּ֤וֹרֶשׁ יְהוָה֙ מִפְּנֵיכֶ֔ם גּוֹיִ֖ם גְּדֹלִ֣ים וַעֲצוּמִ֑ים וְאַתֶּ֗ם לֹא עָ֤מַד אִישׁ֙ בִּפְנֵיכֶ֔ם עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(6471, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 10, 'OT', 'אִישׁ אֶחָ֥ד מִכֶּ֖ם יִרְדָּף אָ֑לֶף כִּ֣י יְהוָ֣ה אֱלֹהֵיכֶ֗ם ה֚וּא הַנִּלְחָ֣ם לָכֶ֔ם כַּאֲשֶׁ֖ר דִּבֶּ֥ר לָכֶֽם'),
(6472, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 11, 'OT', 'וְנִשְׁמַרְתֶּ֥ם מְאֹ֖ד לְנַפְשֹֽׁתֵיכֶ֑ם לְאַהֲבָ֖ה אֶת יְהוָ֥ה אֱלֹהֵיכֶֽם'),
(6473, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 12, 'OT', 'כִּ֣י אִם שׁ֣וֹב תָּשׁ֗וּבוּ וּדְבַקְתֶּם֙ בְּיֶ֨תֶר֙ הַגּוֹיִ֣ם הָאֵ֔לֶּה הַנִּשְׁאָרִ֥ים הָאֵ֖לֶּה אִתְּכֶ֑ם וְהִֽתְחַתַּנְתֶּ֥ם בָּהֶ֛ם וּבָאתֶ֥ם בָּהֶ֖ם וְהֵ֥ם בָּכֶֽם'),
(6474, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 13, 'OT', 'יָד֨וֹעַ֙ תֵּֽדְע֔וּ כִּי֩ לֹ֨א יוֹסִ֜יף יְהוָ֣ה אֱלֹהֵיכֶ֗ם לְהוֹרִ֛ישׁ אֶת הַגּוֹיִ֥ם הָאֵ֖לֶּה מִלִּפְנֵיכֶ֑ם וְהָי֨וּ לָכֶ֜ם לְפַ֣ח וּלְמוֹקֵ֗שׁ וּלְשֹׁטֵ֤ט בְּצִדֵּיכֶם֙ וְלִצְנִנִ֣ים בְּעֵינֵיכֶ֔ם עַד אֲבָדְכֶ֗ם מֵ֠עַל הָאֲדָמָ֤ה הַטּוֹבָה֙ הַזֹּ֔את אֲשֶׁר֙ נָתַ֣ן לָכֶ֔ם יְהוָ֖ה אֱלֹהֵיכֶֽם'),
(6475, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 14, 'OT', 'וְהִנֵּ֨ה אָנֹכִ֤י הוֹלֵךְ֙ הַיּ֔וֹם בְּדֶ֖רֶךְ כָּל הָאָ֑רֶץ וִידַעְתֶּ֞ם בְּכָל לְבַבְכֶ֣ם וּבְכָל נַפְשְׁכֶ֗ם כִּ֣י לֹֽא נָפַל֩ דָּבָ֨ר אֶחָ֜ד מִכֹּ֣ל הַדְּבָרִ֣ים הַטּוֹבִ֗ים אֲשֶׁ֨ר דִּבֶּ֜ר יְהוָ֤ה אֱלֹהֵיכֶם֙ עֲלֵיכֶ֔ם הַכֹּל֙ בָּ֣אוּ לָכֶ֔ם לֹֽא נָפַ֥ל מִמֶּ֖נּוּ דָּבָ֥ר אֶחָֽד'),
(6476, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 15, 'OT', 'וְהָיָ֗ה כַּאֲשֶׁר בָּ֤א עֲלֵיכֶם֙ כָּל הַדָּבָ֣ר הַטּ֔וֹב אֲשֶׁ֥ר דִּבֶּ֛ר יְהוָ֥ה אֱלֹהֵיכֶ֖ם אֲלֵיכֶ֑ם כֵּן֩ יָבִ֨יא יְהוָ֜ה עֲלֵיכֶ֗ם אֵ֚ת כָּל הַדָּבָ֣ר הָרָ֔ע עַד הַשְׁמִיד֣וֹ אוֹתְכֶ֗ם מֵ֠עַל הָאֲדָמָ֤ה הַטּוֹבָה֙ הַזֹּ֔את אֲשֶׁר֙ נָתַ֣ן לָכֶ֔ם יְהוָ֖ה אֱלֹהֵיכֶֽם'),
(6477, 6, 'WLC', 'WLC', 'he', 'JOS', 23, 16, 'OT', 'בְּ֠עָבְרְכֶם אֶת בְּרִ֨ית יְהוָ֥ה אֱלֹהֵיכֶם֮ אֲשֶׁ֣ר צִוָּ֣ה אֶתְכֶם֒ וַהֲלַכְתֶּ֗ם וַעֲבַדְתֶּם֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וְהִשְׁתַּחֲוִיתֶ֖ם לָהֶ֑ם וְחָרָ֤ה אַף יְהוָה֙ בָּכֶ֔ם וַאֲבַדְתֶּ֣ם מְהֵרָ֔ה מֵעַל֙ הָאָ֣רֶץ הַטּוֹבָ֔ה אֲשֶׁ֖ר נָתַ֥ן לָכֶֽם'),
(6478, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 1, 'OT', 'וַיֶּאֶסֹ֧ף יְהוֹשֻׁ֛עַ אֶת כָּל שִׁבְטֵ֥י יִשְׂרָאֵ֖ל שְׁכֶ֑מָה וַיִּקְרָא֩ לְזִקְנֵ֨י יִשְׂרָאֵ֜ל וּלְרָאשָׁ֗יו וּלְשֹֽׁפְטָיו֙ וּלְשֹׁ֣טְרָ֔יו וַיִּֽתְיַצְּב֖וּ לִפְנֵ֥י הָאֱלֹהִֽים'),
(6479, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 2, 'OT', 'וַיֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל כָּל הָעָ֗ם כֹּֽה אָמַ֣ר יְהוָה֮ אֱלֹהֵ֣י יִשְׂרָאֵל֒ בְּעֵ֣בֶר הַנָּהָ֗ר יָשְׁב֤וּ אֲבֽוֹתֵיכֶם֙ מֵֽעוֹלָ֔ם תֶּ֛רַח אֲבִ֥י אַבְרָהָ֖ם וַאֲבִ֣י נָח֑וֹר וַיַּעַבְד֖וּ אֱלֹהִ֥ים אֲחֵרִֽים'),
(6480, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 3, 'OT', 'וָ֠אֶקַּח אֶת אֲבִיכֶ֤ם אֶת אַבְרָהָם֙ מֵעֵ֣בֶר הַנָּהָ֔ר וָאוֹלֵ֥ךְ אוֹת֖וֹ בְּכָל אֶ֣רֶץ כְּנָ֑עַן וארב אֶת זַרְע֔וֹ וָֽאֶתֶּן ל֖וֹ אֶת יִצְחָֽק'),
(6481, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 4, 'OT', 'וָאֶתֵּ֣ן לְיִצְחָ֔ק אֶֽת יַעֲקֹ֖ב וְאֶת עֵשָׂ֑ו וָאֶתֵּ֨ן לְעֵשָׂ֜ו אֶת הַ֤ר שֵׂעִיר֙ לָרֶ֣שֶׁת אוֹת֔וֹ וְיַעֲקֹ֥ב וּבָנָ֖יו יָרְד֥וּ מִצְרָֽיִם'),
(6482, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 5, 'OT', 'וָאֶשְׁלַ֞ח אֶת מֹשֶׁ֤ה וְאֶֽת אַהֲרֹן֙ וָאֶגֹּ֣ף אֶת מִצְרַ֔יִם כַּאֲשֶׁ֥ר עָשִׂ֖יתִי בְּקִרְבּ֑וֹ וְאַחַ֖ר הוֹצֵ֥אתִי אֶתְכֶֽם'),
(6483, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 6, 'OT', 'וָֽאוֹצִ֤יא אֶת אֲבֽוֹתֵיכֶם֙ מִמִּצְרַ֔יִם וַתָּבֹ֖אוּ הַיָּ֑מָּה וַיִּרְדְּפ֨וּ מִצְרַ֜יִם אַחֲרֵ֧י אֲבוֹתֵיכֶ֛ם בְּרֶ֥כֶב וּבְפָרָשִׁ֖ים יַם סֽוּף'),
(6484, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 7, 'OT', 'וַיִּצְעֲק֣וּ אֶל יְהוָ֗ה וַיָּ֨שֶׂם מַֽאֲפֵ֜ל בֵּינֵיכֶ֣ם וּבֵ֣ין הַמִּצְרִ֗ים וַיָּבֵ֨א עָלָ֤יו אֶת הַיָּם֙ וַיְכַסֵּ֔הוּ וַתִּרְאֶ֨ינָה֙ עֵינֵיכֶ֔ם אֵ֥ת אֲשֶׁר עָשִׂ֖יתִי בְּמִצְרָ֑יִם וַתֵּשְׁב֥וּ בַמִּדְבָּ֖ר יָמִ֥ים רַבִּֽים'),
(6485, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 8, 'OT', 'ואבאה אֶתְכֶ֗ם אֶל אֶ֤רֶץ הָאֱמֹרִי֙ הַיּוֹשֵׁב֙ בְּעֵ֣בֶר הַיַּרְדֵּ֔ן וַיִּֽלָּחֲמ֖וּ אִתְּכֶ֑ם וָאֶתֵּ֨ן אוֹתָ֤ם בְּיֶדְכֶם֙ וַתִּֽירְשׁ֣וּ אֶת אַרְצָ֔ם וָאַשְׁמִידֵ֖ם מִפְּנֵיכֶֽם'),
(6486, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 9, 'OT', 'וַיָּ֨קָם בָּלָ֤ק בֶּן צִפּוֹר֙ מֶ֣לֶךְ מוֹאָ֔ב וַיִּלָּ֖חֶם בְּיִשְׂרָאֵ֑ל וַיִּשְׁלַ֗ח וַיִּקְרָ֛א לְבִלְעָ֥ם בֶּן בְּע֖וֹר לְקַלֵּ֥ל אֶתְכֶֽם'),
(6487, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 10, 'OT', 'וְלֹ֥א אָבִ֖יתִי לִשְׁמֹ֣עַ לְבִלְעָ֑ם וַיְבָ֤רֶךְ בָּרוֹךְ֙ אֶתְכֶ֔ם וָאַצִּ֥ל אֶתְכֶ֖ם מִיָּדֽוֹ'),
(6488, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 11, 'OT', 'וַתַּעַבְר֣וּ אֶת הַיַּרְדֵּן֮ וַתָּבֹ֣אוּ אֶל יְרִיחוֹ֒ וַיִּלָּחֲמ֣וּ בָכֶ֣ם בַּעֲלֵֽי יְ֠רִיחוֹ הָֽאֱמֹרִ֨י וְהַפְּרִזִּ֜י וְהַֽכְּנַעֲנִ֗י וְהַֽחִתִּי֙ וְהַגִּרְגָּשִׁ֔י הַֽחִוִּ֖י וְהַיְבוּסִ֑י וָאֶתֵּ֥ן אוֹתָ֖ם בְּיֶדְכֶֽם'),
(6489, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 12, 'OT', 'וָאֶשְׁלַ֤ח לִפְנֵיכֶם֙ אֶת הַצִּרְעָ֔ה וַתְּגָ֤רֶשׁ אוֹתָם֙ מִפְּנֵיכֶ֔ם שְׁנֵ֖י מַלְכֵ֣י הָאֱמֹרִ֑י לֹ֥א בְחַרְבְּךָ֖ וְלֹ֥א בְקַשְׁתֶּֽךָ'),
(6490, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 13, 'OT', 'וָאֶתֵּ֨ן לָכֶ֜ם אֶ֣רֶץ אֲשֶׁ֧ר לֹֽא יָגַ֣עְתָּ בָּ֗הּ וְעָרִים֙ אֲשֶׁ֣ר לֹא בְנִיתֶ֔ם וַתֵּשְׁב֖וּ בָּהֶ֑ם כְּרָמִ֤ים וְזֵיתִים֙ אֲשֶׁ֣ר לֹֽא נְטַעְתֶּ֔ם אַתֶּ֖ם אֹכְלִֽים'),
(6491, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 14, 'OT', 'וְעַתָּ֞ה יְר֧אוּ אֶת יְהוָ֛ה וְעִבְד֥וּ אֹת֖וֹ בְּתָמִ֣ים וּבֶֽאֱמֶ֑ת וְהָסִ֣ירוּ אֶת אֱלֹהִ֗ים אֲשֶׁר֩ עָבְד֨וּ אֲבוֹתֵיכֶ֜ם בְּעֵ֤בֶר הַנָּהָר֙ וּבְמִצְרַ֔יִם וְעִבְד֖וּ אֶת יְהוָֽה'),
(6492, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 15, 'OT', 'וְאִם֩ רַ֨ע בְּֽעֵינֵיכֶ֜ם לַעֲבֹ֣ד אֶת יְהוָ֗ה בַּחֲר֨וּ לָכֶ֣ם הַיּוֹם֮ אֶת מִ֣י תַעֲבֹדוּן֒ אִ֣ם אֶת אֱלֹהִ֞ים אֲשֶׁר עָבְד֣וּ אֲבוֹתֵיכֶ֗ם אֲשֶׁר֙ בעבר הַנָּהָ֔ר וְאִם֙ אֶת אֱלֹהֵ֣י הָאֱמֹרִ֔י אֲשֶׁ֥ר אַתֶּ֖ם יֹשְׁבִ֣ים בְּאַרְצָ֑ם וְאָנֹכִ֣י וּבֵיתִ֔י נַעֲבֹ֖ד אֶת יְהוָֽה'),
(6493, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 16, 'OT', 'וַיַּ֤עַן הָעָם֙ וַיֹּ֔אמֶר חָלִ֣ילָה לָּ֔נוּ מֵעֲזֹ֖ב אֶת יְהוָ֑ה לַעֲבֹ֖ד אֱלֹהִ֥ים אֲחֵרִֽים'),
(6494, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 17, 'OT', 'כִּ֚י יְהוָ֣ה אֱלֹהֵ֔ינוּ הוּא֩ הַמַּעֲלֶ֨ה אֹתָ֧נוּ וְאֶת אֲבוֹתֵ֛ינוּ מֵאֶ֥רֶץ מִצְרַ֖יִם מִבֵּ֣ית עֲבָדִ֑ים וַאֲשֶׁ֧ר עָשָׂ֣ה לְעֵינֵ֗ינוּ אֶת הָאֹת֤וֹת הַגְּדֹלוֹת֙ הָאֵ֔לֶּה וַֽיִּשְׁמְרֵ֗נוּ בְּכָל הַדֶּ֨רֶךְ֙ אֲשֶׁ֣ר הָלַ֣כְנוּ בָ֔הּ וּבְכֹל֙ הָֽעַמִּ֔ים אֲשֶׁ֥ר עָבַ֖רְנוּ בְּקִרְבָּֽם'),
(6495, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 18, 'OT', 'וַיְגָ֨רֶשׁ יְהוָ֜ה אֶת כָּל הָעַמִּ֗ים וְאֶת הָאֱמֹרִ֛י יֹשֵׁ֥ב הָאָ֖רֶץ מִפָּנֵ֑ינוּ גַּם אֲנַ֨חְנוּ֙ נַעֲבֹ֣ד אֶת יְהוָ֔ה כִּי ה֖וּא אֱלֹהֵֽינוּ'),
(6496, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 19, 'OT', 'וַיֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל הָעָ֗ם לֹ֤א תֽוּכְלוּ֙ לַעֲבֹ֣ד אֶת יְהוָ֔ה כִּֽי אֱלֹהִ֥ים קְדֹשִׁ֖ים ה֑וּא אֵֽל קַנּ֣וֹא ה֔וּא לֹֽא יִשָּׂ֥א לְפִשְׁעֲכֶ֖ם וּלְחַטֹּאותֵיכֶֽם'),
(6497, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 20, 'OT', 'כִּ֤י תַֽעַזְבוּ֙ אֶת יְהוָ֔ה וַעֲבַדְתֶּ֖ם אֱלֹהֵ֣י נֵכָ֑ר וְשָׁ֨ב וְהֵרַ֤ע לָכֶם֙ וְכִלָּ֣ה אֶתְכֶ֔ם אַחֲרֵ֖י אֲשֶׁר הֵיטִ֥יב לָכֶֽם'),
(6498, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 21, 'OT', 'וַיֹּ֥אמֶר הָעָ֖ם אֶל יְהוֹשֻׁ֑עַ לֹ֕א כִּ֥י אֶת יְהוָ֖ה נַעֲבֹֽד'),
(6499, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 22, 'OT', 'וַיֹּ֨אמֶר יְהוֹשֻׁ֜עַ אֶל הָעָ֗ם עֵדִ֤ים אַתֶּם֙ בָּכֶ֔ם כִּֽי אַתֶּ֞ם בְּחַרְתֶּ֥ם לָכֶ֛ם אֶת יְהוָ֖ה לַעֲבֹ֣ד אוֹת֑וֹ וַיֹּאמְר֖וּ עֵדִֽים'),
(6500, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 23, 'OT', 'וְעַתָּ֕ה הָסִ֛ירוּ אֶת אֱלֹהֵ֥י הַנֵּכָ֖ר אֲשֶׁ֣ר בְּקִרְבְּכֶ֑ם וְהַטּוּ֙ אֶת לְבַבְכֶ֔ם אֶל יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל'),
(6501, 6, 'WLC', 'WLC', 'he', 'JOS', 24, 24, 'OT', 'וַיֹּאמְר֥וּ הָעָ֖ם אֶל יְהוֹשֻׁ֑עַ אֶת יְהוָ֤ה אֱלֹהֵ֨ינוּ֙ נַעֲבֹ֔ד וּבְקוֹל֖וֹ נִשְׁמָֽע'),
