(6798, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 43, 'OT', 'וַיִּקַּ֣ח אֶת הָעָ֗ם וַֽיֶּחֱצֵם֙ לִשְׁלֹשָׁ֣ה רָאשִׁ֔ים וַיֶּאֱרֹ֖ב בַּשָּׂדֶ֑ה וַיַּ֗רְא וְהִנֵּ֤ה הָעָם֙ יֹצֵ֣א מִן הָעִ֔יר וַיָּ֥קָם עֲלֵיהֶ֖ם וַיַּכֵּֽם'),
(6799, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 44, 'OT', 'וַאֲבִימֶ֗לֶךְ וְהָרָאשִׁים֙ אֲשֶׁ֣ר עִמּ֔וֹ פָּשְׁט֕וּ וַיַּ֣עַמְד֔וּ פֶּ֖תַח שַׁ֣עַר הָעִ֑יר וּשְׁנֵ֣י הָֽרָאשִׁ֗ים פָּֽשְׁט֛וּ עַֽל כָּל אֲשֶׁ֥ר בַּשָּׂדֶ֖ה וַיַּכּֽוּם'),
(6800, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 45, 'OT', 'וַאֲבִימֶ֜לֶךְ נִלְחָ֣ם בָּעִ֗יר כֹּ֚ל הַיּ֣וֹם הַה֔וּא וַיִּלְכֹּד֙ אֶת הָעִ֔יר וְאֶת הָעָ֥ם אֲשֶׁר בָּ֖הּ הָרָ֑ג וַיִּתֹּץ֙ אֶת הָעִ֔יר וַיִּזְרָעֶ֖הָ מֶֽלַח'),
(6801, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 46, 'OT', 'וַֽיִּשְׁמְע֔וּ כָּֽל בַּעֲלֵ֖י מִֽגְדַּל שְׁכֶ֑ם וַיָּבֹ֣אוּ אֶל צְרִ֔יחַ בֵּ֖ית אֵ֥ל בְּרִֽית'),
(6802, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 47, 'OT', 'וַיֻּגַּ֖ד לַאֲבִימֶ֑לֶךְ כִּ֣י הִֽתְקַבְּצ֔וּ כָּֽל בַּעֲלֵ֖י מִֽגְדַּל שְׁכֶֽם'),
(6803, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 48, 'OT', 'וַיַּ֨עַל אֲבִימֶ֜לֶךְ הַר צַלְמ֗וֹן הוּא֮ וְכָל הָעָ֣ם אֲשֶׁר אִתּוֹ֒ וַיִּקַּח֩ אֲבִימֶ֨לֶךְ אֶת הַקַּרְדֻּמּ֜וֹת בְּיָד֗וֹ וַיִּכְרֹת֙ שׂוֹכַ֣ת עֵצִ֔ים וַיִּ֨שָּׂאֶ֔הָ וַיָּ֖שֶׂם עַל שִׁכְמ֑וֹ וַיֹּ֜אמֶר אֶל הָעָ֣ם אֲשֶׁר עִמּ֗וֹ מָ֤ה רְאִיתֶם֙ עָשִׂ֔יתִי מַהֲר֖וּ עֲשׂ֥וּ כָמֽוֹנִי'),
(6804, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 49, 'OT', 'וַיִּכְרְת֨וּ גַם כָּל הָעָ֜ם אִ֣ישׁ שׂוֹכֹ֗ה וַיֵּ֨לְכ֜וּ אַחֲרֵ֤י אֲבִימֶ֨לֶךְ֙ וַיָּשִׂ֣ימוּ עַֽל הַצְּרִ֔יחַ וַיַּצִּ֧יתוּ עֲלֵיהֶ֛ם אֶֽת הַצְּרִ֖יחַ בָּאֵ֑שׁ וַיָּמֻ֜תוּ גַּ֣ם כָּל אַנְשֵׁ֧י מִֽגְדַּל שְׁכֶ֛ם כְּאֶ֖לֶף אִ֥ישׁ וְאִשָּֽׁה'),
(6805, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 50, 'OT', 'וַיֵּ֥לֶךְ אֲבִימֶ֖לֶךְ אֶל תֵּבֵ֑ץ וַיִּ֥חַן בְּתֵבֵ֖ץ וַֽיִּלְכְּדָֽהּ'),
(6806, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 51, 'OT', 'וּמִגְדַּל עֹז֮ הָיָ֣ה בְתוֹךְ הָעִיר֒ וַיָּנֻ֨סוּ שָׁ֜מָּה כָּל הָאֲנָשִׁ֣ים וְהַנָּשִׁ֗ים וְכֹל֙ בַּעֲלֵ֣י הָעִ֔יר וַֽיִּסְגְּר֖וּ בַּעֲדָ֑ם וַֽיַּעֲל֖וּ עַל גַּ֥ג הַמִּגְדָּֽל'),
(6807, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 52, 'OT', 'וַיָּבֹ֤א אֲבִימֶ֨לֶךְ֙ עַד הַמִּגְדָּ֔ל וַיִּלָּ֖חֶם בּ֑וֹ וַיִּגַּ֛שׁ עַד פֶּ֥תַח הַמִּגְדָּ֖ל לְשָׂרְפ֥וֹ בָאֵֽשׁ'),
(6808, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 53, 'OT', 'וַתַּשְׁלֵ֞ךְ אִשָּׁ֥ה אַחַ֛ת פֶּ֥לַח רֶ֖כֶב עַל רֹ֣אשׁ אֲבִימֶ֑לֶךְ וַתָּ֖רִץ אֶת גֻּלְגָּלְתּֽוֹ'),
(6809, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 54, 'OT', 'וַיִּקְרָ֨א מְהֵרָ֜ה אֶל הַנַּ֣עַר נֹשֵׂ֣א כֵלָ֗יו וַיֹּ֤אמֶר לוֹ֙ שְׁלֹ֤ף חַרְבְּךָ֙ וּמ֣וֹתְתֵ֔נִי פֶּן יֹ֥אמְרוּ לִ֖י אִשָּׁ֣ה הֲרָגָ֑תְהוּ וַיִּדְקְרֵ֥הוּ נַעֲר֖וֹ וַיָּמֹֽת'),
(6810, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 55, 'OT', 'וַיִּרְא֥וּ אִֽישׁ יִשְׂרָאֵ֖ל כִּ֣י מֵ֣ת אֲבִימֶ֑לֶךְ וַיֵּלְכ֖וּ אִ֥ישׁ לִמְקֹמֽוֹ'),
(6811, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 56, 'OT', 'וַיָּ֣שֶׁב אֱלֹהִ֔ים אֵ֖ת רָעַ֣ת אֲבִימֶ֑לֶךְ אֲשֶׁ֤ר עָשָׂה֙ לְאָבִ֔יו לַהֲרֹ֖ג אֶת שִׁבְעִ֥ים אֶחָֽיו'),
(6812, 7, 'WLC', 'WLC', 'he', 'JDG', 9, 57, 'OT', 'וְאֵ֗ת כָּל רָעַת֙ אַנְשֵׁ֣י שְׁכֶ֔ם הֵשִׁ֥יב אֱלֹהִ֖ים בְּרֹאשָׁ֑ם וַתָּבֹ֣א אֲלֵיהֶ֔ם קִֽלֲלַ֖ת יוֹתָ֥ם בֶּן יְרֻבָּֽעַל'),
(6813, 7, 'WLC', 'WLC', 'he', 'JDG', 10, 1, 'OT', 'וַיָּקָם֩ אַחֲרֵ֨י אֲבִימֶ֜לֶךְ לְהוֹשִׁ֣יעַ אֶת יִשְׂרָאֵ֗ל תּוֹלָ֧ע בֶּן פּוּאָ֛ה בֶּן דּוֹד֖וֹ אִ֣ישׁ יִשָּׂשכָ֑ר וְהֽוּא יֹשֵׁ֥ב בְּשָׁמִ֖יר בְּהַ֥ר אֶפְרָֽיִם'),
