(7006, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 12, 'OT', 'וַֽיַּעֲל֗וּ וַֽיַּחֲנ֛וּ בְּקִרְיַ֥ת יְעָרִ֖ים בִּֽיהוּדָ֑ה עַל כֵּ֡ן קָרְאוּ֩ לַמָּק֨וֹם הַה֜וּא מַחֲנֵה דָ֗ן עַ֚ד הַיּ֣וֹם הַזֶּ֔ה הִנֵּ֕ה אַחֲרֵ֖י קִרְיַ֥ת יְעָרִֽים'),
(7007, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 13, 'OT', 'וַיַּעַבְר֥וּ מִשָּׁ֖ם הַר אֶפְרָ֑יִם וַיָּבֹ֖אוּ עַד בֵּ֥ית מִיכָֽה'),
(7008, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 14, 'OT', 'וַֽיַּעֲנ֞וּ חֲמֵ֣שֶׁת הָאֲנָשִׁ֗ים הַהֹלְכִים֮ לְרַגֵּל֮ אֶת הָאָ֣רֶץ לַיִשׁ֒ וַיֹּֽאמְרוּ֙ אֶל אֲחֵיהֶ֔ם הַיְדַעְתֶּ֗ם כִּ֠י יֵ֣שׁ בַּבָּתִּ֤ים הָאֵ֨לֶּה֙ אֵפ֣וֹד וּתְרָפִ֔ים וּפֶ֖סֶל וּמַסֵּכָ֑ה וְעַתָּ֖ה דְּע֥וּ מַֽה תַּעֲשֽׂוּ'),
(7009, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 15, 'OT', 'וַיָּס֣וּרוּ שָׁ֔מָּה וַיָּבֹ֛אוּ אֶל בֵּֽית הַנַּ֥עַר הַלֵּוִ֖י בֵּ֣ית מִיכָ֑ה וַיִּשְׁאֲלוּ ל֖וֹ לְשָׁלֽוֹם'),
(7010, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 16, 'OT', 'וְשֵׁשׁ מֵא֣וֹת אִ֗ישׁ חֲגוּרִים֙ כְּלֵ֣י מִלְחַמְתָּ֔ם נִצָּבִ֖ים פֶּ֣תַח הַשָּׁ֑עַר אֲשֶׁ֖ר מִבְּנֵי דָֽן'),
(7011, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 17, 'OT', 'וַֽיַּעֲל֞וּ חֲמֵ֣שֶׁת הָאֲנָשִׁ֗ים הַהֹלְכִים֮ לְרַגֵּ֣ל אֶת הָאָרֶץ֒ בָּ֣אוּ שָׁ֔מָּה לָקְח֗וּ אֶת הַפֶּ֨סֶל֙ וְאֶת הָ֣אֵפ֔וֹד וְאֶת הַתְּרָפִ֖ים וְאֶת הַמַּסֵּכָ֑ה וְהַכֹּהֵ֗ן נִצָּב֙ פֶּ֣תַח הַשַּׁ֔עַר וְשֵׁשׁ מֵא֣וֹת הָאִ֔ישׁ הֶחָג֖וּר כְּלֵ֥י הַמִּלְחָמָֽה'),
(7012, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 18, 'OT', 'וְאֵ֗לֶּה בָּ֚אוּ בֵּ֣ית מִיכָ֔ה וַיִּקְחוּ֙ אֶת פֶּ֣סֶל הָאֵפ֔וֹד וְאֶת הַתְּרָפִ֖ים וְאֶת הַמַּסֵּכָ֑ה וַיֹּ֤אמֶר אֲלֵיהֶם֙ הַכֹּהֵ֔ן מָ֥ה אַתֶּ֖ם עֹשִֽׂים'),
(7013, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 19, 'OT', 'וַיֹּאמְרוּ֩ ל֨וֹ הַחֲרֵ֜שׁ שִֽׂים יָדְךָ֤ עַל פִּ֨יךָ֙ וְלֵ֣ךְ עִמָּ֔נוּ וֶֽהְיֵה לָ֖נוּ לְאָ֣ב וּלְכֹהֵ֑ן הֲט֣וֹב הֱיוֹתְךָ֣ כֹהֵ֗ן לְבֵית֙ אִ֣ישׁ אֶחָ֔ד א֚וֹ הֱיוֹתְךָ֣ כֹהֵ֔ן לְשֵׁ֥בֶט וּלְמִשְׁפָּחָ֖ה בְּיִשְׂרָאֵֽל'),
(7014, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 20, 'OT', 'וַיִּיטַב֙ לֵ֣ב הַכֹּהֵ֔ן וַיִּקַּח֙ אֶת הָ֣אֵפ֔וֹד וְאֶת הַתְּרָפִ֖ים וְאֶת הַפָּ֑סֶל וַיָּבֹ֖א בְּקֶ֥רֶב הָעָֽם'),
(7015, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 21, 'OT', 'וַיִּפְנ֖וּ וַיֵּלֵ֑כוּ וַיָּשִׂ֨ימוּ אֶת הַטַּ֧ף וְאֶת הַמִּקְנֶ֛ה וְאֶת הַכְּבוּדָּ֖ה לִפְנֵיהֶֽם'),
(7016, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 22, 'OT', 'הֵ֥מָּה הִרְחִ֖יקוּ מִבֵּ֣ית מִיכָ֑ה וְהָאֲנָשִׁ֗ים אֲשֶׁ֤ר בַּבָּתִּים֙ אֲשֶׁר֙ עִם בֵּ֣ית מִיכָ֔ה נִֽזְעֲק֔וּ וַיַּדְבִּ֖יקוּ אֶת בְּנֵי דָֽן'),
(7017, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 23, 'OT', 'וַֽיִּקְרְאוּ֙ אֶל בְּנֵי דָ֔ן וַיַּסֵּ֖בּוּ פְּנֵיהֶ֑ם וַיֹּאמְר֣וּ לְמִיכָ֔ה מַה לְּךָ֖ כִּ֥י נִזְעָֽקְתָּ'),
(7018, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 24, 'OT', 'וַיֹּ֡אמֶר אֶת אֱלֹהַי֩ אֲשֶׁר עָשִׂ֨יתִי לְקַחְתֶּ֧ם וְֽאֶת הַכֹּהֵ֛ן וַתֵּלְכ֖וּ וּמַה לִּ֣י ע֑וֹד וּמַה זֶּ֛ה תֹּאמְר֥וּ אֵלַ֖י מַה לָּֽךְ'),
(7019, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 25, 'OT', 'וַיֹּאמְר֤וּ אֵלָיו֙ בְּנֵי דָ֔ן אַל תַּשְׁמַ֥ע קוֹלְךָ֖ עִמָּ֑נוּ פֶּֽן יִפְגְּע֣וּ בָכֶ֗ם אֲנָשִׁים֙ מָ֣רֵי נֶ֔פֶשׁ וְאָסַפְתָּ֥ה נַפְשְׁךָ֖ וְנֶ֥פֶשׁ בֵּיתֶֽךָ'),
(7020, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 26, 'OT', 'וַיֵּלְכ֥וּ בְנֵי דָ֖ן לְדַרְכָּ֑ם וַיַּ֣רְא מִיכָ֗ה כִּי חֲזָקִ֥ים הֵ֨מָּה֙ מִמֶּ֔נּוּ וַיִּ֖פֶן וַיָּ֥שָׁב אֶל בֵּיתֽוֹ'),
(7021, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 27, 'OT', 'וְהֵ֨מָּה לָקְח֜וּ אֵ֧ת אֲשֶׁר עָשָׂ֣ה מִיכָ֗ה וְֽאֶת הַכֹּהֵן֮ אֲשֶׁ֣ר הָיָה לוֹ֒ וַיָּבֹ֣אוּ עַל לַ֗יִשׁ עַל עַם֙ שֹׁקֵ֣ט וּבֹטֵ֔חַ וַיַּכּ֥וּ אוֹתָ֖ם לְפִי חָ֑רֶב וְאֶת הָעִ֖יר שָׂרְפ֥וּ בָאֵֽשׁ'),
(7022, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 28, 'OT', 'וְאֵ֨ין מַצִּ֜יל כִּ֧י רְֽחוֹקָה הִ֣יא מִצִּיד֗וֹן וְדָבָ֤ר אֵין לָהֶם֙ עִם אָדָ֔ם וְהִ֕יא בָּעֵ֖מֶק אֲשֶׁ֣ר לְבֵית רְח֑וֹב וַיִּבְנ֥וּ אֶת הָעִ֖יר וַיֵּ֥שְׁבוּ בָֽהּ'),
(7023, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 29, 'OT', 'וַיִּקְרְא֤וּ שֵׁם הָעִיר֙ דָּ֔ן בְּשֵׁם֙ דָּ֣ן אֲבִיהֶ֔ם אֲשֶׁ֥ר יוּלַּ֖ד לְיִשְׂרָאֵ֑ל וְאוּלָ֛ם לַ֥יִשׁ שֵׁם הָעִ֖יר לָרִאשֹׁנָֽה'),
(7024, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 30, 'OT', 'וַיָּקִ֧ימוּ לָהֶ֛ם בְּנֵי דָ֖ן אֶת הַפָּ֑סֶל וִ֠יהוֹנָתָן בֶּן גֵּרְשֹׁ֨ם בֶּן מְ ה֣וּא וּבָנָ֗יו הָי֤וּ כֹהֲנִים֙ לְשֵׁ֣בֶט הַדָּנִ֔י עַד י֖וֹם גְּל֥וֹת הָאָֽרֶץ'),
(7025, 7, 'WLC', 'WLC', 'he', 'JDG', 18, 31, 'OT', 'וַיָּשִׂ֣ימוּ לָהֶ֔ם אֶת פֶּ֥סֶל מִיכָ֖ה אֲשֶׁ֣ר עָשָׂ֑ה כָּל יְמֵ֛י הֱי֥וֹת בֵּית הָאֱלֹהִ֖ים בְּשִׁלֹֽה'),
(7026, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 1, 'OT', 'וַיְהִי֙ בַּיָּמִ֣ים הָהֵ֔ם וּמֶ֖לֶךְ אֵ֣ין בְּיִשְׂרָאֵ֑ל וַיְהִ֣י אִ֣ישׁ לֵוִ֗י גָּ֚ר בְּיַרְכְּתֵ֣י הַר אֶפְרַ֔יִם וַיִּֽקַּֽח לוֹ֙ אִשָּׁ֣ה פִילֶ֔גֶשׁ מִבֵּ֥ית לֶ֖חֶם יְהוּדָֽה'),
(7027, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 2, 'OT', 'וַתִּזְנֶ֤ה עָלָיו֙ פִּֽילַגְשׁ֔וֹ וַתֵּ֤לֶךְ מֵֽאִתּוֹ֙ אֶל בֵּ֣ית אָבִ֔יהָ אֶל בֵּ֥ית לֶ֖חֶם יְהוּדָ֑ה וַתְּהִי שָׁ֕ם יָמִ֖ים אַרְבָּעָ֥ה חֳדָשִֽׁים'),
(7028, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 3, 'OT', 'וַיָּ֨קָם אִישָׁ֜הּ וַיֵּ֣לֶךְ אַחֲרֶ֗יהָ לְדַבֵּ֤ר עַל לִבָּהּ֙ להשיבו וְנַעֲר֥וֹ עִמּ֖וֹ וְצֶ֣מֶד חֲמֹרִ֑ים וַתְּבִיאֵ֨הוּ֙ בֵּ֣ית אָבִ֔יהָ וַיִּרְאֵ֨הוּ֙ אֲבִ֣י הַֽנַּעֲרָ֔ה וַיִּשְׂמַ֖ח לִקְרָאתֽוֹ'),
(7029, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 4, 'OT', 'וַיֶּחֱזַק בּ֤וֹ חֹֽתְנוֹ֙ אֲבִ֣י הַֽנַּעֲרָ֔ה וַיֵּ֥שֶׁב אִתּ֖וֹ שְׁלֹ֣שֶׁת יָמִ֑ים וַיֹּאכְלוּ֙ וַיִּשְׁתּ֔וּ וַיָּלִ֖ינוּ שָֽׁם'),
(7030, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 5, 'OT', 'וַֽיְהִי֙ בַּיּ֣וֹם הָרְבִיעִ֔י וַיַּשְׁכִּ֥ימוּ בַבֹּ֖קֶר וַיָּ֣קָם לָלֶ֑כֶת וַיֹּאמֶר֩ אֲבִ֨י הַֽנַּעֲרָ֜ה אֶל חֲתָנ֗וֹ סְעָ֧ד לִבְּךָ֛ פַּת לֶ֖חֶם וְאַחַ֥ר תֵּלֵֽכוּ'),
(7031, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 6, 'OT', 'וַיֵּשְׁב֗וּ וַיֹּאכְל֧וּ שְׁנֵיהֶ֛ם יַחְדָּ֖ו וַיִּשְׁתּ֑וּ וַיֹּ֜אמֶר אֲבִ֤י הַֽנַּעֲרָה֙ אֶל הָאִ֔ישׁ הֽוֹאֶל נָ֥א וְלִ֖ין וְיִטַ֥ב לִבֶּֽךָ'),
(7032, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 7, 'OT', 'וַיָּ֥קָם הָאִ֖ישׁ לָלֶ֑כֶת וַיִּפְצַר בּוֹ֙ חֹתְנ֔וֹ וַיָּ֖שָׁב וַיָּ֥לֶן שָֽׁם'),
(7033, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 8, 'OT', 'וַיַּשְׁכֵּ֨ם בַּבֹּ֜קֶר בַּיּ֣וֹם הַחֲמִישִׁי֮ לָלֶכֶת֒ וַיֹּ֣אמֶר אֲבִ֣י הַֽנַּעֲרָ֗ה סְעָד נָא֙ לְבָ֣בְךָ֔ וְהִֽתְמַהְמְה֖וּ עַד נְט֣וֹת הַיּ֑וֹם וַיֹּאכְל֖וּ שְׁנֵיהֶֽם'),
(7034, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 9, 'OT', 'וַיָּ֤קָם הָאִישׁ֙ לָלֶ֔כֶת ה֥וּא וּפִילַגְשׁ֖וֹ וְנַעֲר֑וֹ וַיֹּ֣אמֶר ל֣וֹ חֹתְנ֣וֹ אֲבִ֣י הַֽנַּעֲרָ֡ה הִנֵּ֣ה נָא֩ רָפָ֨ה הַיּ֜וֹם לַעֲרֹ֗ב לִֽינוּ נָ֞א הִנֵּ֨ה חֲנ֤וֹת הַיּוֹם֙ לִ֥ין פֹּה֙ וְיִיטַ֣ב לְבָבֶ֔ךָ וְהִשְׁכַּמְתֶּ֤ם מָחָר֙ לְדַרְכְּכֶ֔ם וְהָלַכְתָּ֖ לְאֹהָלֶֽךָ'),
(7035, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 10, 'OT', 'וְלֹֽא אָבָ֤ה הָאִישׁ֙ לָל֔וּן וַיָּ֣קָם וַיֵּ֗לֶךְ וַיָּבֹא֙ עַד נֹ֣כַח יְב֔וּס הִ֖יא יְרוּשָׁלִָ֑ם וְעִמּ֗וֹ צֶ֤מֶד חֲמוֹרִים֙ חֲבוּשִׁ֔ים וּפִילַגְשׁ֖וֹ עִמּֽוֹ'),
(7036, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 11, 'OT', 'הֵ֣ם עִם יְב֔וּס וְהַיּ֖וֹם רַ֣ד מְאֹ֑ד וַיֹּ֨אמֶר הַנַּ֜עַר אֶל אֲדֹנָ֗יו לְכָה נָּ֛א וְנָס֛וּרָה אֶל עִֽיר הַיְבוּסִ֥י הַזֹּ֖את וְנָלִ֥ין בָּֽהּ'),
(7037, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 12, 'OT', 'וַיֹּ֤אמֶר אֵלָיו֙ אֲדֹנָ֔יו לֹ֤א נָסוּר֙ אֶל עִ֣יר נָכְרִ֔י אֲשֶׁ֛ר לֹֽא מִבְּנֵ֥י יִשְׂרָאֵ֖ל הֵ֑נָּה וְעָבַ֖רְנוּ עַד גִּבְעָֽה'),
(7038, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 13, 'OT', 'וַיֹּ֣אמֶר לְנַעֲר֔וֹ לְךָ֥ וְנִקְרְבָ֖ה בְּאַחַ֣ד הַמְּקֹמ֑וֹת וְלַ֥נּוּ בַגִּבְעָ֖ה א֥וֹ בָרָמָֽה'),
(7039, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 14, 'OT', 'וַיַּעַבְר֖וּ וַיֵּלֵ֑כוּ וַתָּבֹ֤א לָהֶם֙ הַשֶּׁ֔מֶשׁ אֵ֥צֶל הַגִּבְעָ֖ה אֲשֶׁ֥ר לְבִנְיָמִֽן'),
(7040, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 15, 'OT', 'וַיָּסֻ֣רוּ שָׁ֔ם לָב֖וֹא לָל֣וּן בַּגִּבְעָ֑ה וַיָּבֹ֗א וַיֵּ֨שֶׁב֙ בִּרְח֣וֹב הָעִ֔יר וְאֵ֥ין אִ֛ישׁ מְאַסֵּֽף אוֹתָ֥ם הַבַּ֖יְתָה לָלֽוּן'),
(7041, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 16, 'OT', 'וְהִנֵּ֣ה אִ֣ישׁ זָקֵ֗ן בָּ֣א מִֽן מַעֲשֵׂ֤הוּ מִן הַשָּׂדֶה֙ בָּעֶ֔רֶב וְהָאִישׁ֙ מֵהַ֣ר אֶפְרַ֔יִם וְהוּא גָ֖ר בַּגִּבְעָ֑ה וְאַנְשֵׁ֥י הַמָּק֖וֹם בְּנֵ֥י יְמִינִֽי'),
(7042, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 17, 'OT', 'וַיִּשָּׂ֣א עֵינָ֗יו וַיַּ֛רְא אֶת הָאִ֥ישׁ הָאֹרֵ֖חַ בִּרְחֹ֣ב הָעִ֑יר וַיֹּ֨אמֶר הָאִ֧ישׁ הַזָּקֵ֛ן אָ֥נָה תֵלֵ֖ךְ וּמֵאַ֥יִן תָּבֽוֹא'),
(7043, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 18, 'OT', 'וַיֹּ֣אמֶר אֵלָ֗יו עֹבְרִ֨ים אֲנַ֜חְנוּ מִבֵּֽית לֶ֣חֶם יְהוּדָה֮ עַד יַרְכְּתֵ֣י הַר אֶפְרַיִם֒ מִשָּׁ֣ם אָנֹ֔כִי וָאֵלֵ֕ךְ עַד בֵּ֥ית לֶ֖חֶם יְהוּדָ֑ה וְאֶת בֵּ֤ית יְהוָה֙ אֲנִ֣י הֹלֵ֔ךְ וְאֵ֣ין אִ֔ישׁ מְאַסֵּ֥ף אוֹתִ֖י הַבָּֽיְתָה'),
(7044, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 19, 'OT', 'וְגַם תֶּ֤בֶן גַּם מִסְפּוֹא֙ יֵ֣שׁ לַחֲמוֹרֵ֔ינוּ וְ֠גַם לֶ֣חֶם וָיַ֤יִן יֶשׁ לִי֙ וְלַֽאֲמָתֶ֔ךָ וְלַנַּ֖עַר עִם עֲבָדֶ֑יךָ אֵ֥ין מַחְס֖וֹר כָּל דָּבָֽר'),
(7045, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 20, 'OT', 'וַיֹּ֨אמֶר הָאִ֤ישׁ הַזָּקֵן֙ שָׁל֣וֹם לָ֔ךְ רַ֥ק כָּל מַחְסוֹרְךָ֖ עָלָ֑י רַ֥ק בָּרְח֖וֹב אַל תָּלַֽן'),
(7046, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 21, 'OT', 'וַיְבִיאֵ֣הוּ לְבֵית֔וֹ וַיָּ֖בָול לַחֲמוֹרִ֑ים וַֽיִּרְחֲצוּ֙ רַגְלֵיהֶ֔ם וַיֹּאכְל֖וּ וַיִּשְׁתּֽוּ'),
(7047, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 22, 'OT', 'הֵמָּה֮ מֵיטִיבִ֣ים אֶת לִבָּם֒ וְהִנֵּה֩ אַנְשֵׁ֨י הָעִ֜יר אַנְשֵׁ֣י בְנֵֽי בְלִיַּ֗עַל נָסַ֨בּוּ֙ אֶת הַבַּ֔יִת מִֽתְדַּפְּקִ֖ים עַל הַדָּ֑לֶת וַיֹּאמְר֗וּ אֶל הָ֠אִישׁ בַּ֣עַל הַבַּ֤יִת הַזָּקֵן֙ לֵאמֹ֔ר הוֹצֵ֗א אֶת הָאִ֛ישׁ אֲשֶׁר בָּ֥א אֶל בֵּיתְךָ֖ וְנֵדָעֶֽנּוּ'),
(7048, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 23, 'OT', 'וַיֵּצֵ֣א אֲלֵיהֶ֗ם הָאִישׁ֙ בַּ֣עַל הַבַּ֔יִת וַיֹּ֣אמֶר אֲלֵהֶ֔ם אַל אַחַ֖י אַל תָּרֵ֣עוּ נָ֑א אַ֠חֲרֵי אֲשֶׁר בָּ֞א הָאִ֤ישׁ הַזֶּה֙ אַל בֵּיתִ֔י אַֽל תַּעֲשׂ֖וּ אֶת הַנְּבָלָ֥ה הַזֹּֽאת'),
(7049, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 24, 'OT', 'הִנֵּה֩ בִתִּ֨י הַבְּתוּלָ֜ה וּפִֽילַגְשֵׁ֗הוּ אוֹצִֽיאָה נָּ֤א אוֹתָם֙ וְעַנּ֣וּ אוֹתָ֔ם וַעֲשׂ֣וּ לָהֶ֔ם הַטּ֖וֹב בְּעֵינֵיכֶ֑ם וְלָאִ֤ישׁ הַזֶּה֙ לֹ֣א תַעֲשׂ֔וּ דְּבַ֖ר הַנְּבָלָ֥ה הַזֹּֽאת'),
(7050, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 25, 'OT', 'וְלֹֽא אָב֤וּ הָאֲנָשִׁים֙ לִשְׁמֹ֣עַֽ ל֔וֹ וַיַּחֲזֵ֤ק הָאִישׁ֙ בְּפִ֣ילַגְשׁ֔וֹ וַיֹּצֵ֥א אֲלֵיהֶ֖ם הַח֑וּץ וַיֵּדְע֣וּ א֠וֹתָהּ וַיִּֽתְעַלְּלוּ בָ֤הּ כָּל הַלַּ֨יְלָה֙ עַד הַבֹּ֔קֶר וַֽיְשַׁלְּח֖וּהָ בעלות הַשָּֽׁחַר'),
(7051, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 26, 'OT', 'וַתָּבֹ֥א הָאִשָּׁ֖ה לִפְנ֣וֹת הַבֹּ֑קֶר וַתִּפֹּ֞ל פֶּ֧תַח בֵּית הָאִ֛ישׁ אֲשֶׁר אֲדוֹנֶ֥יהָ שָּׁ֖ם עַד הָאֽוֹר'),
(7052, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 27, 'OT', 'וַיָּ֨קָם אֲדֹנֶ֜יהָ בַּבֹּ֗קֶר וַיִּפְתַּח֙ דַּלְת֣וֹת הַבַּ֔יִת וַיֵּצֵ֖א לָלֶ֣כֶת לְדַרְכּ֑וֹ וְהִנֵּ֧ה הָאִשָּׁ֣ה פִֽילַגְשׁ֗וֹ נֹפֶ֨לֶת֙ פֶּ֣תַח הַבַּ֔יִת וְיָדֶ֖יהָ עַל הַסַּֽף'),
(7053, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 28, 'OT', 'וַיֹּ֧אמֶר אֵלֶ֛יהָ ק֥וּמִי וְנֵלֵ֖כָה וְאֵ֣ין עֹנֶ֑ה וַיִּקָּחֶ֨הָ֙ עַֽל הַחֲמ֔וֹר וַיָּ֣קָם הָאִ֔ישׁ וַיֵּ֖לֶךְ לִמְקֹמֽוֹ'),
(7054, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 29, 'OT', 'וַיָּבֹ֣א אֶל בֵּית֗וֹ וַיִּקַּ֤ח אֶת הַֽמַּאֲכֶ֨לֶת֙ וַיַּחֲזֵ֣ק בְּפִֽילַגְשׁ֔וֹ וַֽיְנַתְּחֶ֨הָ֙ לַעֲצָמֶ֔יהָ לִשְׁנֵ֥ים עָשָׂ֖ר נְתָחִ֑ים וַֽיְשַׁלְּחֶ֔הָ בְּכֹ֖ל גְּב֥וּל יִשְׂרָאֵֽל'),
(7055, 7, 'WLC', 'WLC', 'he', 'JDG', 19, 30, 'OT', 'וְהָיָ֣ה כָל הָרֹאֶ֗ה וְאָמַר֙ לֹֽא נִהְיְתָ֤ה וְלֹֽא נִרְאֲתָה֙ כָּזֹ֔את לְמִיּ֞וֹם עֲל֤וֹת בְּנֵֽי יִשְׂרָאֵל֙ מֵאֶ֣רֶץ מִצְרַ֔יִם עַ֖ד הַיּ֣וֹם הַזֶּ֑ה שִֽׂימוּ לָכֶ֥ם עָלֶ֖יהָ עֻ֥צוּ וְדַבֵּֽרוּ'),
(7056, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 1, 'OT', 'וַיֵּצְאוּ֮ כָּל בְּנֵ֣י יִשְׂרָאֵל֒ וַתִּקָּהֵ֨ל הָעֵדָ֜ה כְּאִ֣ישׁ אֶחָ֗ד לְמִדָּן֙ וְעַד בְּאֵ֣ר שֶׁ֔בַע וְאֶ֖רֶץ הַגִּלְעָ֑ד אֶל יְהוָ֖ה הַמִּצְפָּֽה'),
(7057, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 2, 'OT', 'וַיִּֽתְיַצְּב֞וּ פִּנּ֣וֹת כָּל הָעָ֗ם כֹּ֚ל שִׁבְטֵ֣י יִשְׂרָאֵ֔ל בִּקְהַ֖ל עַ֣ם הָאֱלֹהִ֑ים אַרְבַּ֨ע מֵא֥וֹת אֶ֛לֶף אִ֥ישׁ רַגְלִ֖י שֹׁ֥לֵֽף חָֽרֶב'),
(7058, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 3, 'OT', 'וַֽיִּשְׁמְעוּ֙ בְּנֵ֣י בִנְיָמִ֔ן כִּֽי עָל֥וּ בְנֵֽי יִשְׂרָאֵ֖ל הַמִּצְפָּ֑ה וַיֹּֽאמְרוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל דַּבְּר֕וּ אֵיכָ֥ה נִהְיְתָ֖ה הָרָעָ֥ה הַזֹּֽאת'),
(7059, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 4, 'OT', 'וַיַּ֜עַן הָאִ֣ישׁ הַלֵּוִ֗י אִ֛ישׁ הָאִשָּׁ֥ה הַנִּרְצָחָ֖ה וַיֹּאמַ֑ר הַגִּבְעָ֨תָה֙ אֲשֶׁ֣ר לְבִנְיָמִ֔ן בָּ֛אתִי אֲנִ֥י וּפִֽילַגְשִׁ֖י לָלֽוּן'),
(7060, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 5, 'OT', 'וַיָּקֻ֤מוּ עָלַי֙ בַּעֲלֵ֣י הַגִּבְעָ֔ה וַיָּסֹ֧בּוּ עָלַ֛י אֶת הַבַּ֖יִת לָ֑יְלָה אוֹתִי֙ דִּמּ֣וּ לַהֲרֹ֔ג וְאֶת פִּילַגְשִׁ֥י עִנּ֖וּ וַתָּמֹֽת'),
(7061, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 6, 'OT', 'וָֽאֹחֵ֤ז בְּפִֽילַגְשִׁי֙ וָֽאֲנַתְּחֶ֔הָ וָֽאֲשַׁלְּחֶ֔הָ בְּכָל שְׂדֵ֖ה נַחֲלַ֣ת יִשְׂרָאֵ֑ל כִּ֥י עָשׂ֛וּ זִמָּ֥ה וּנְבָלָ֖ה בְּיִשְׂרָאֵֽל'),
(7062, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 7, 'OT', 'הִנֵּ֥ה כֻלְּכֶ֖ם בְּנֵ֣י יִשְׂרָאֵ֑ל הָב֥וּ לָכֶ֛ם דָּבָ֥ר וְעֵצָ֖ה הֲלֹֽם'),
(7063, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 8, 'OT', 'וַיָּ֨קָם֙ כָּל הָעָ֔ם כְּאִ֥ישׁ אֶחָ֖ד לֵאמֹ֑ר לֹ֤א נֵלֵךְ֙ אִ֣ישׁ לְאָהֳל֔וֹ וְלֹ֥א נָס֖וּר אִ֥ישׁ לְבֵיתֽוֹ'),
(7064, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 9, 'OT', 'וְעַתָּ֕ה זֶ֣ה הַדָּבָ֔ר אֲשֶׁ֥ר נַעֲשֶׂ֖ה לַגִּבְעָ֑ה עָלֶ֖יהָ בְּגוֹרָֽל'),
(7065, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 10, 'OT', 'וְלָקַ֣חְנוּ עֲשָׂרָה֩ אֲנָשִׁ֨ים לַמֵּאָ֜ה לְכֹ֣ל שִׁבְטֵ֣י יִשְׂרָאֵ֗ל וּמֵאָ֤ה לָאֶ֨לֶף֙ וְאֶ֣לֶף לָרְבָבָ֔ה לָקַ֥חַת צֵדָ֖ה לָעָ֑ם לַעֲשׂ֗וֹת לְבוֹאָם֙ לְגֶ֣בַע בִּנְיָמִ֔ן כְּכָל הַ֨נְּבָלָ֔ה אֲשֶׁ֥ר עָשָׂ֖ה בְּיִשְׂרָאֵֽל'),
(7066, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 11, 'OT', 'וַיֵּֽאָסֵ֞ף כָּל אִ֤ישׁ יִשְׂרָאֵל֙ אֶל הָעִ֔יר כְּאִ֥ישׁ אֶחָ֖ד חֲבֵרִֽים'),
(7067, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 12, 'OT', 'וַֽיִּשְׁלְח֞וּ שִׁבְטֵ֤י יִשְׂרָאֵל֙ אֲנָשִׁ֔ים בְּכָל שִׁבְטֵ֥י בִנְיָמִ֖ן לֵאמֹ֑ר מָ֚ה הָרָעָ֣ה הַזֹּ֔את אֲשֶׁ֥ר נִהְיְתָ֖ה בָּכֶֽם'),
(7068, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 13, 'OT', 'וְעַתָּ֡ה תְּנוּ֩ אֶת הָאֲנָשִׁ֨ים בְּנֵֽי בְלִיַּ֜עַל אֲשֶׁ֤ר בַּגִּבְעָה֙ וּנְמִיתֵ֔ם וּנְבַעֲרָ֥ה רָעָ֖ה מִיִּשְׂרָאֵ֑ל וְלֹ֤א אָבוּ֙ בִּנְיָמִ֔ן לִשְׁמֹ֕עַ בְּק֖וֹל אֲחֵיהֶ֥ם בְּנֵֽי יִשְׂרָאֵֽל'),
(7069, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 14, 'OT', 'וַיֵּאָסְפ֧וּ בְנֵֽי בִנְיָמִ֛ן מִן הֶעָרִ֖ים הַגִּבְעָ֑תָה לָצֵ֥את לַמִּלְחָמָ֖ה עִם בְּנֵ֥י יִשְׂרָאֵֽל'),
(7070, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 15, 'OT', 'וַיִּתְפָּֽקְדוּ֩ בְנֵ֨י בִנְיָמִ֜ן בַּיּ֤וֹם הַהוּא֙ מֵהֶ֣עָרִ֔ים עֶשְׂרִ֨ים וְשִׁשָּׁ֥ה אֶ֛לֶף אִ֖ישׁ שֹׁ֣לֵֽף חָ֑רֶב לְ֠בַד מִיֹּשְׁבֵ֤י הַגִּבְעָה֙ הִתְפָּ֣קְד֔וּ שְׁבַ֥ע מֵא֖וֹת אִ֥ישׁ בָּחֽוּר'),
(7071, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 16, 'OT', 'מִכֹּ֣ל הָעָ֣ם הַזֶּ֗ה שְׁבַ֤ע מֵאוֹת֙ אִ֣ישׁ בָּח֔וּר אִטֵּ֖ר יַד יְמִינ֑וֹ כָּל זֶ֗ה קֹלֵ֧עַ בָּאֶ֛בֶן אֶל הַֽשַּׂעֲרָ֖ה וְלֹ֥א יַחֲטִֽא'),
(7072, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 17, 'OT', 'וְאִ֨ישׁ יִשְׂרָאֵ֜ל הִתְפָּֽקְד֗וּ לְבַד֙ מִבִּנְיָמִ֔ן אַרְבַּ֨ע מֵא֥וֹת אֶ֛לֶף אִ֖ישׁ שֹׁ֣לֵֽף חָ֑רֶב כָּל זֶ֖ה אִ֥ישׁ מִלְחָמָֽה'),
(7073, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 18, 'OT', 'וַיָּקֻ֜מוּ וַיַּעֲל֣וּ בֵֽית אֵל֮ וַיִּשְׁאֲל֣וּ בֵאלֹהִים֒ וַיֹּֽאמְרוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל מִ֚י יַעֲלֶה לָּ֣נוּ בַתְּחִלָּ֔ה לַמִּלְחָמָ֖ה עִם בְּנֵ֣י בִנְיָמִ֑ן וַיֹּ֥אמֶר יְהוָ֖ה יְהוּדָ֥ה בַתְּחִלָּֽה'),
(7074, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 19, 'OT', 'וַיָּק֥וּמוּ בְנֵֽי יִשְׂרָאֵ֖ל בַּבֹּ֑קֶר וַיַּֽחֲנ֖וּ עַל הַגִּבְעָֽה'),
(7075, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 20, 'OT', 'וַיֵּצֵא֙ אִ֣ישׁ יִשְׂרָאֵ֔ל לַמִּלְחָמָ֖ה עִם בִּנְיָמִ֑ן וַיַּעַרְכ֨וּ אִתָּ֧ם אִֽישׁ יִשְׂרָאֵ֛ל מִלְחָמָ֖ה אֶל הַגִּבְעָֽה'),
(7076, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 21, 'OT', 'וַיֵּצְא֥וּ בְנֵֽי בִנְיָמִ֖ן מִן הַגִּבְעָ֑ה וַיַּשְׁחִ֨יתוּ בְיִשְׂרָאֵ֜ל בַּיּ֣וֹם הַה֗וּא שְׁנַ֨יִם וְעֶשְׂרִ֥ים אֶ֛לֶף אִ֖ישׁ אָֽרְצָה'),
(7077, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 22, 'OT', 'וַיִּתְחַזֵּ֥ק הָעָ֖ם אִ֣ישׁ יִשְׂרָאֵ֑ל וַיֹּסִ֨פוּ֙ לַעֲרֹ֣ךְ מִלְחָמָ֔ה בַּמָּק֕וֹם אֲשֶׁר עָ֥רְכוּ שָׁ֖ם בַּיּ֥וֹם הָרִאשֽׁוֹן'),
(7078, 7, 'WLC', 'WLC', 'he', 'JDG', 20, 23, 'OT', 'וַיַּעֲל֣וּ בְנֵֽי יִשְׂרָאֵ֗ל וַיִּבְכּ֣וּ לִפְנֵֽי יְהוָה֮ עַד הָעֶרֶב֒ וַיִּשְׁאֲל֤וּ בַֽיהוָה֙ לֵאמֹ֔ר הַאוֹסִ֗יף לָגֶ֨שֶׁת֙ לַמִּלְחָמָ֔ה עִם בְּנֵ֥י בִנְיָמִ֖ן אָחִ֑י וַיֹּ֥אמֶר יְהוָ֖ה עֲל֥וּ אֵלָֽיו'),
