(7342, 9, 'WLC', 'WLC', 'he', '1SA', 6, 10, 'OT', 'וַיַּעֲשׂ֤וּ הָאֲנָשִׁים֙ כֵּ֔ן וַיִּקְח֗וּ שְׁתֵּ֤י פָרוֹת֙ עָל֔וֹת וַיַּאַסְר֖וּם בָּעֲגָלָ֑ה וְאֶת בְּנֵיהֶ֖ם כָּל֥וּ בַבָּֽיִת'),
(7343, 9, 'WLC', 'WLC', 'he', '1SA', 6, 11, 'OT', 'וַיָּשִׂ֛מוּ אֶת אֲר֥וֹן יְהוָ֖ה אֶל הָעֲגָלָ֑ה וְאֵ֣ת הָאַרְגַּ֗ז וְאֵת֙ עַכְבְּרֵ֣י הַזָּהָ֔ב וְאֵ֖ת צַלְמֵ֥י טְחֹרֵיהֶֽם'),
(7344, 9, 'WLC', 'WLC', 'he', '1SA', 6, 12, 'OT', 'וַיִשַּׁ֨רְנָה הַפָּר֜וֹת בַּדֶּ֗רֶךְ עַל דֶּ֨רֶךְ֙ בֵּ֣ית שֶׁ֔מֶשׁ בִּמְסִלָּ֣ה אַחַ֗ת הָלְכ֤וּ הָלֹךְ֙ וְגָע֔וֹ וְלֹא סָ֖רוּ יָמִ֣ין וּשְׂמֹ֑אול וְסַרְנֵ֤י פְלִשְׁתִּים֙ הֹלְכִ֣ים אַחֲרֵיהֶ֔ם עַד גְּב֖וּל בֵּ֥ית שָֽׁמֶשׁ'),
(7345, 9, 'WLC', 'WLC', 'he', '1SA', 6, 13, 'OT', 'וּבֵ֣ית שֶׁ֔מֶשׁ קֹצְרִ֥ים קְצִיר חִטִּ֖ים בָּעֵ֑מֶק וַיִּשְׂא֣וּ אֶת עֵינֵיהֶ֗ם וַיִּרְאוּ֙ אֶת הָ֣אָר֔וֹן וַֽיִּשְׂמְח֖וּ לִרְאֽוֹת'),
(7346, 9, 'WLC', 'WLC', 'he', '1SA', 6, 14, 'OT', 'וְהָעֲגָלָ֡ה בָּ֠אָה אֶל שְׂדֵ֨ה יְהוֹשֻׁ֤עַ בֵּֽית הַשִּׁמְשִׁי֙ וַתַּעֲמֹ֣ד שָׁ֔ם וְשָׁ֖ם אֶ֣בֶן גְּדוֹלָ֑ה וַֽיְבַקְּעוּ֙ אֶת עֲצֵ֣י הָעֲגָלָ֔ה וְאֶת הַ֨פָּר֔וֹת הֶעֱל֥וּ עֹלָ֖ה לַיהוָֽה'),
(7347, 9, 'WLC', 'WLC', 'he', '1SA', 6, 15, 'OT', 'וְהַלְוִיִּ֞ם הוֹרִ֣ידוּ אֶת אֲר֣וֹן יְהוָ֗ה וְאֶת הָאַרְגַּ֤ז אֲשֶׁר אִתּוֹ֙ אֲשֶׁר בּ֣וֹ כְלֵֽי זָהָ֔ב וַיָּשִׂ֖מוּ אֶל הָאֶ֣בֶן הַגְּדוֹלָ֑ה וְאַנְשֵׁ֣י בֵֽית שֶׁ֗מֶשׁ הֶעֱל֨וּ עֹל֜וֹת וַֽיִּזְבְּח֧וּ זְבָחִ֛ים בַּיּ֥וֹם הַה֖וּא לַֽיהוָֽה'),
(7348, 9, 'WLC', 'WLC', 'he', '1SA', 6, 16, 'OT', 'וַחֲמִשָּׁ֥ה סַרְנֵֽי פְלִשְׁתִּ֖ים רָא֑וּ וַיָּשֻׁ֥בוּ עֶקְר֖וֹן בַּיּ֥וֹם הַהֽוּא'),
(7349, 9, 'WLC', 'WLC', 'he', '1SA', 6, 17, 'OT', 'וְאֵ֨לֶּה֙ טְחֹרֵ֣י הַזָּהָ֔ב אֲשֶׁ֨ר הֵשִׁ֧יבוּ פְלִשְׁתִּ֛ים אָשָׁ֖ם לַֽיהוָ֑ה לְאַשְׁדּ֨וֹד אֶחָ֜ד לְעַזָּ֤ה אֶחָד֙ לְאַשְׁקְל֣וֹן אֶחָ֔ד לְגַ֥ת אֶחָ֖ד לְעֶקְר֥וֹן אֶחָֽד'),
(7350, 9, 'WLC', 'WLC', 'he', '1SA', 6, 18, 'OT', 'וְעַכְבְּרֵ֣י הַזָּהָ֗ב מִסְפַּ֞ר כָּל עָרֵ֤י פְלִשְׁתִּים֙ לַחֲמֵ֣שֶׁת הַסְּרָנִ֔ים מֵעִ֣יר מִבְצָ֔ר וְעַ֖ד כֹּ֣פֶר הַפְּרָזִ֑י וְעַ֣ד אָבֵ֣ל הַגְּדוֹלָ֗ה אֲשֶׁ֨ר הִנִּ֤יחוּ עָלֶ֨יהָ֙ אֵ֚ת אֲר֣וֹן יְהוָ֔ה עַ֚ד הַיּ֣וֹם הַזֶּ֔ה בִּשְׂדֵ֥ה יְהוֹשֻׁ֖עַ בֵּֽית הַשִּׁמְשִֽׁי'),
(7351, 9, 'WLC', 'WLC', 'he', '1SA', 6, 19, 'OT', 'וַיַּ֞ךְ בְּאַנְשֵׁ֣י בֵֽית שֶׁ֗מֶשׁ כִּ֤י רָאוּ֙ בַּאֲר֣וֹן יְהוָ֔ה וַיַּ֤ךְ בָּעָם֙ שִׁבְעִ֣ים אִ֔ישׁ חֲמִשִּׁ֥ים אֶ֖לֶף אִ֑ישׁ וַיִּֽתְאַבְּל֣וּ הָעָ֔ם כִּֽי הִכָּ֧ה יְהוָ֛ה בָּעָ֖ם מַכָּ֥ה גְדוֹלָֽה'),
(7352, 9, 'WLC', 'WLC', 'he', '1SA', 6, 20, 'OT', 'וַיֹּֽאמְרוּ֙ אַנְשֵׁ֣י בֵֽית שֶׁ֔מֶשׁ מִ֚י יוּכַ֣ל לַעֲמֹ֔ד לִפְנֵ֨י יְהוָ֧ה הָאֱלֹהִ֛ים הַקָּד֖וֹשׁ הַזֶּ֑ה וְאֶל מִ֖י יַעֲלֶ֥ה מֵעָלֵֽינוּ'),
(7353, 9, 'WLC', 'WLC', 'he', '1SA', 6, 21, 'OT', 'וַֽיִּשְׁלְחוּ֙ מַלְאָכִ֔ים אֶל יוֹשְׁבֵ֥י קִרְיַת יְעָרִ֖ים לֵאמֹ֑ר הֵשִׁ֤בוּ פְלִשְׁתִּים֙ אֶת אֲר֣וֹן יְהוָ֔ה רְד֕וּ הַעֲל֥וּ אֹת֖וֹ אֲלֵיכֶֽם'),
(7354, 9, 'WLC', 'WLC', 'he', '1SA', 7, 1, 'OT', 'וַיָּבֹ֜אוּ אַנְשֵׁ֣י קִרְיַ֣ת יְעָרִ֗ים וַֽיַּעֲלוּ֙ אֶת אֲר֣וֹן יְהוָ֔ה וַיָּבִ֣אוּ אֹת֔וֹ אֶל בֵּ֥ית אֲבִינָדָ֖ב בַּגִּבְעָ֑ה וְאֶת אֶלְעָזָ֤ר בְּנוֹ֙ קִדְּשׁ֔וּ לִשְׁמֹ֖ר אֶת אֲר֥וֹן יְהוָֽה'),
(7355, 9, 'WLC', 'WLC', 'he', '1SA', 7, 2, 'OT', 'וַיְהִ֗י מִיּ֞וֹם שֶׁ֤בֶת הָֽאָרוֹן֙ בְּקִרְיַ֣ת יְעָרִ֔ים וַיִּרְבּוּ֙ הַיָּמִ֔ים וַיִּֽהְי֖וּ עֶשְׂרִ֣ים שָׁנָ֑ה וַיִּנָּה֛וּ כָּל בֵּ֥ית יִשְׂרָאֵ֖ל אַחֲרֵ֥י יְהוָֽה'),
(7356, 9, 'WLC', 'WLC', 'he', '1SA', 7, 3, 'OT', 'וַיֹּ֣אמֶר שְׁמוּאֵ֗ל אֶל כָּל בֵּ֣ית יִשְׂרָאֵל֮ לֵאמֹר֒ אִם בְּכָל לְבַבְכֶ֗ם אַתֶּ֤ם שָׁבִים֙ אֶל יְהוָ֔ה הָסִ֜ירוּ אֶת אֱלֹהֵ֧י הַנֵּכָ֛ר מִתּוֹכְכֶ֖ם וְהָעַשְׁתָּר֑וֹת וְהָכִ֨ינוּ לְבַבְכֶ֤ם אֶל יְהוָה֙ וְעִבְדֻ֣הוּ לְבַדּ֔וֹ וְיַצֵּ֥ל אֶתְכֶ֖ם מִיַּ֥ד פְּלִשְׁתִּֽים'),
(7357, 9, 'WLC', 'WLC', 'he', '1SA', 7, 4, 'OT', 'וַיָּסִ֨ירוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶת הַבְּעָלִ֖ים וְאֶת הָעַשְׁתָּרֹ֑ת וַיַּעַבְד֥וּ אֶת יְהוָ֖ה לְבַדּֽוֹ'),
(7358, 9, 'WLC', 'WLC', 'he', '1SA', 7, 5, 'OT', 'וַיֹּ֣אמֶר שְׁמוּאֵ֔ל קִבְצ֥וּ אֶת כָּל יִשְׂרָאֵ֖ל הַמִּצְפָּ֑תָה וְאֶתְפַּלֵּ֥ל בַּעַדְכֶ֖ם אֶל יְהוָֽה'),
(7359, 9, 'WLC', 'WLC', 'he', '1SA', 7, 6, 'OT', 'וַיִּקָּבְצ֣וּ הַ֠מִּצְפָּתָה וַיִּֽשְׁאֲבוּ מַ֜יִם וַֽיִּשְׁפְּכ֣וּ לִפְנֵ֣י יְהוָ֗ה וַיָּצ֨וּמוּ֙ בַּיּ֣וֹם הַה֔וּא וַיֹּ֣אמְרוּ שָׁ֔ם חָטָ֖אנוּ לַיהוָ֑ה וַיִּשְׁפֹּ֧ט שְׁמוּאֵ֛ל אֶת בְּנֵ֥י יִשְׂרָאֵ֖ל בַּמִּצְפָּֽה'),
(7360, 9, 'WLC', 'WLC', 'he', '1SA', 7, 7, 'OT', 'וַיִּשְׁמְע֣וּ פְלִשְׁתִּ֗ים כִּֽי הִתְקַבְּצ֤וּ בְנֵֽי יִשְׂרָאֵל֙ הַמִּצְפָּ֔תָה וַיַּעֲל֥וּ סַרְנֵֽי פְלִשְׁתִּ֖ים אֶל יִשְׂרָאֵ֑ל וַֽיִּשְׁמְעוּ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל וַיִּֽרְא֖וּ מִפְּנֵ֥י פְלִשְׁתִּֽים'),
(7361, 9, 'WLC', 'WLC', 'he', '1SA', 7, 8, 'OT', 'וַיֹּאמְר֤וּ בְנֵֽי יִשְׂרָאֵל֙ אֶל שְׁמוּאֵ֔ל אַל תַּחֲרֵ֣שׁ מִמֶּ֔נּוּ מִזְּעֹ֖ק אֶל יְהוָ֣ה אֱלֹהֵ֑ינוּ וְיֹשִׁעֵ֖נוּ מִיַּ֥ד פְּלִשְׁתִּֽים'),
(7362, 9, 'WLC', 'WLC', 'he', '1SA', 7, 9, 'OT', 'וַיִּקַּ֣ח שְׁמוּאֵ֗ל טְלֵ֤ה חָלָב֙ אֶחָ֔ד ויעלה עוֹלָ֛ה כָּלִ֖יל לַֽיהוָ֑ה וַיִּזְעַ֨ק שְׁמוּאֵ֤ל אֶל יְהוָה֙ בְּעַ֣ד יִשְׂרָאֵ֔ל וַֽיַּעֲנֵ֖הוּ יְהוָֽה'),
(7363, 9, 'WLC', 'WLC', 'he', '1SA', 7, 10, 'OT', 'וַיְהִ֤י שְׁמוּאֵל֙ מַעֲלֶ֣ה הָעוֹלָ֔ה וּפְלִשְׁתִּ֣ים נִגְּשׁ֔וּ לַמִּלְחָמָ֖ה בְּיִשְׂרָאֵ֑ל וַיַּרְעֵ֣ם יְהוָ֣ה בְּקוֹל גָּ֠דוֹל בַּיּ֨וֹם הַה֤וּא עַל פְּלִשְׁתִּים֙ וַיְהֻמֵּ֔ם וַיִּנָּגְפ֖וּ לִפְנֵ֥י יִשְׂרָאֵֽל'),
(7364, 9, 'WLC', 'WLC', 'he', '1SA', 7, 11, 'OT', 'וַיֵּ֨צְא֜וּ אַנְשֵׁ֤י יִשְׂרָאֵל֙ מִן הַמִּצְפָּ֔ה וַֽיִּרְדְּפ֖וּ אֶת פְּלִשְׁתִּ֑ים וַיַּכּ֕וּם עַד מִתַּ֖חַת לְבֵ֥ית כָּֽר'),
(7365, 9, 'WLC', 'WLC', 'he', '1SA', 7, 12, 'OT', 'וַיִּקַּ֨ח שְׁמוּאֵ֜ל אֶ֣בֶן אַחַ֗ת וַיָּ֤שֶׂם בֵּֽין הַמִּצְפָּה֙ וּבֵ֣ין הַשֵּׁ֔ן וַיִּקְרָ֥א אֶת שְׁמָ֖הּ אֶ֣בֶן הָעָ֑זֶר וַיֹּאמַ֕ר עַד הֵ֖נָּה עֲזָרָ֥נוּ יְהוָֽה'),
(7366, 9, 'WLC', 'WLC', 'he', '1SA', 7, 13, 'OT', 'וַיִּכָּֽנְעוּ֙ הַפְּלִשְׁתִּ֔ים וְלֹא יָסְפ֣וּ ע֔וֹד לָב֖וֹא בִּגְב֣וּל יִשְׂרָאֵ֑ל וַתְּהִ֤י יַד יְהוָה֙ בַּפְּלִשְׁתִּ֔ים כֹּ֖ל יְמֵ֥י שְׁמוּאֵֽל'),
(7367, 9, 'WLC', 'WLC', 'he', '1SA', 7, 14, 'OT', 'וַתָּשֹׁ֣בְנָה הֶעָרִ֡ים אֲשֶׁ֣ר לָֽקְחוּ פְלִשְׁתִּים֩ מֵאֵ֨ת יִשְׂרָאֵ֤ל לְיִשְׂרָאֵל֙ מֵעֶקְר֣וֹן וְעַד גַּ֔ת וְאֶ֨ת גְּבוּלָ֔ן הִצִּ֥יל יִשְׂרָאֵ֖ל מִיַּ֣ד פְּלִשְׁתִּ֑ים וַיְהִ֣י שָׁל֔וֹם בֵּ֥ין יִשְׂרָאֵ֖ל וּבֵ֥ין הָאֱמֹרִֽי'),
(7368, 9, 'WLC', 'WLC', 'he', '1SA', 7, 15, 'OT', 'וַיִּשְׁפֹּ֤ט שְׁמוּאֵל֙ אֶת יִשְׂרָאֵ֔ל כֹּ֖ל יְמֵ֥י חַיָּֽיו'),
(7369, 9, 'WLC', 'WLC', 'he', '1SA', 7, 16, 'OT', 'וְהָלַ֗ךְ מִדֵּ֤י שָׁנָה֙ בְּשָׁנָ֔ה וְסָבַב֙ בֵּֽית אֵ֔ל וְהַגִּלְגָּ֖ל וְהַמִּצְפָּ֑ה וְשָׁפַט֙ אֶת יִשְׂרָאֵ֔ל אֵ֥ת כָּל הַמְּקוֹמ֖וֹת הָאֵֽלֶּה'),
(7370, 9, 'WLC', 'WLC', 'he', '1SA', 7, 17, 'OT', 'וּתְשֻׁבָת֤וֹ הָרָמָ֨תָה֙ כִּֽי שָׁ֣ם בֵּית֔וֹ וְשָׁ֖ם שָׁפָ֣ט אֶת יִשְׂרָאֵ֑ל וַיִּֽבֶן שָׁ֥ם מִזְבֵּ֖חַ לַֽיהוָֽה'),
(7371, 9, 'WLC', 'WLC', 'he', '1SA', 8, 1, 'OT', 'וַיְהִ֕י כַּאֲשֶׁ֥ר זָקֵ֖ן שְׁמוּאֵ֑ל וַיָּ֧שֶׂם אֶת בָּנָ֛יו שֹׁפְטִ֖ים לְיִשְׂרָאֵֽל'),
(7372, 9, 'WLC', 'WLC', 'he', '1SA', 8, 2, 'OT', 'וַיְהִ֞י שֶׁם בְּנ֤וֹ הַבְּכוֹר֙ יוֹאֵ֔ל וְשֵׁ֥ם מִשְׁנֵ֖הוּ אֲבִיָּ֑ה שֹׁפְטִ֖ים בִּבְאֵ֥ר שָֽׁבַע'),
