(7395, 9, 'WLC', 'WLC', 'he', '1SA', 9, 3, 'OT', 'וַתֹּאבַ֨דְנָה֙ הָאֲתֹנ֔וֹת לְקִ֖ישׁ אֲבִ֣י שָׁא֑וּל וַיֹּ֨אמֶר קִ֜ישׁ אֶל שָׁא֣וּל בְּנ֗וֹ קַח נָ֤א אִתְּךָ֙ אֶת אַחַ֣ד מֵֽהַנְּעָרִ֔ים וְק֣וּם לֵ֔ךְ בַּקֵּ֖שׁ אֶת הָאֲתֹנֹֽת'),
(7396, 9, 'WLC', 'WLC', 'he', '1SA', 9, 4, 'OT', 'וַיַּעֲבֹ֧ר בְּהַר אֶפְרַ֛יִם וַיַּעֲבֹ֥ר בְּאֶֽרֶץ שָׁלִ֖שָׁה וְלֹ֣א מָצָ֑אוּ וַיַּעַבְר֤וּ בְאֶֽרֶץ שַׁעֲלִים֙ וָאַ֔יִן וַיַּעֲבֹ֥ר בְּאֶֽרֶץ יְמִינִ֖י וְלֹ֥א מָצָֽאוּ'),
(7397, 9, 'WLC', 'WLC', 'he', '1SA', 9, 5, 'OT', 'הֵ֗מָּה בָּ֚אוּ בְּאֶ֣רֶץ צ֔וּף וְשָׁא֥וּל אָמַ֛ר לְנַעֲר֥וֹ אֲשֶׁר עִמּ֖וֹ לְכָ֣ה וְנָשׁ֑וּבָה פֶּן יֶחְדַּ֥ל אָבִ֛י מִן הָאֲתֹנ֖וֹת וְדָ֥אַג לָֽנוּ'),
(7398, 9, 'WLC', 'WLC', 'he', '1SA', 9, 6, 'OT', 'וַיֹּ֣אמֶר ל֗וֹ הִנֵּה נָ֤א אִישׁ אֱלֹהִים֙ בָּעִ֣יר הַזֹּ֔את וְהָאִ֣ישׁ נִכְבָּ֔ד כֹּ֥ל אֲשֶׁר יְדַבֵּ֖ר בּ֣וֹא יָב֑וֹא עַתָּה֙ נֵ֣לֲכָה שָּׁ֔ם אוּלַי֙ יַגִּ֣יד לָ֔נוּ אֶת דַּרְכֵּ֖נוּ אֲשֶׁר הָלַ֥כְנוּ עָלֶֽיהָ'),
(7399, 9, 'WLC', 'WLC', 'he', '1SA', 9, 7, 'OT', 'וַיֹּ֨אמֶר שָׁא֜וּל לְנַעֲר֗וֹ וְהִנֵּ֣ה נֵלֵךְ֮ וּמַה נָּבִ֣יא לָאִישׁ֒ כִּ֤י הַלֶּ֨חֶם֙ אָזַ֣ל מִכֵּלֵ֔ינוּ וּתְשׁוּרָ֥ה אֵין לְהָבִ֖יא לְאִ֣ישׁ הָאֱלֹהִ֑ים מָ֖ה אִתָּֽנוּ'),
(7400, 9, 'WLC', 'WLC', 'he', '1SA', 9, 8, 'OT', 'וַיֹּ֤סֶף הַנַּ֨עַר֙ לַעֲנ֣וֹת אֶת שָׁא֔וּל וַיֹּ֕אמֶר הִנֵּה֙ נִמְצָ֣א בְיָדִ֔י רֶ֖בַע שֶׁ֣קֶל כָּ֑סֶף וְנָֽתַתִּי֙ לְאִ֣ישׁ הָאֱלֹהִ֔ים וְהִגִּ֥יד לָ֖נוּ אֶת דַּרְכֵּֽנוּ'),
(7401, 9, 'WLC', 'WLC', 'he', '1SA', 9, 9, 'OT', 'לְפָנִ֣ים בְּיִשְׂרָאֵ֗ל כֹּֽה אָמַ֤ר הָאִישׁ֙ בְּלֶכְתּוֹ֙ לִדְר֣וֹשׁ אֱלֹהִ֔ים לְכ֥וּ וְנֵלְכָ֖ה עַד הָרֹאֶ֑ה כִּ֤י לַנָּבִיא֙ הַיּ֔וֹם יִקָּרֵ֥א לְפָנִ֖ים הָרֹאֶֽה'),
(7402, 9, 'WLC', 'WLC', 'he', '1SA', 9, 10, 'OT', 'וַיֹּ֨אמֶר שָׁא֧וּל לְנַעֲר֛וֹ ט֥וֹב דְּבָרְךָ֖ לְכָ֣ה נֵלֵ֑כָה וַיֵּֽלְכוּ֙ אֶל הָעִ֔יר אֲשֶׁר שָׁ֖ם אִ֥ישׁ הָאֱלֹהִֽים'),
(7403, 9, 'WLC', 'WLC', 'he', '1SA', 9, 11, 'OT', 'הֵ֗מָּה עֹלִים֙ בְּמַעֲלֵ֣ה הָעִ֔יר וְהֵ֨מָּה֙ מָצְא֣וּ נְעָר֔וֹת יֹצְא֖וֹת לִשְׁאֹ֣ב מָ֑יִם וַיֹּאמְר֣וּ לָהֶ֔ן הֲיֵ֥שׁ בָּזֶ֖ה הָרֹאֶֽה'),
(7404, 9, 'WLC', 'WLC', 'he', '1SA', 9, 12, 'OT', 'וַתַּעֲנֶ֧ינָה אוֹתָ֛ם וַתֹּאמַ֥רְנָה יֵּ֖שׁ הִנֵּ֣ה לְפָנֶ֑יךָ מַהֵ֣ר עַתָּ֗ה כִּ֤י הַיּוֹם֙ בָּ֣א לָעִ֔יר כִּ֣י זֶ֧בַח הַיּ֛וֹם לָעָ֖ם בַּבָּמָֽה'),
(7405, 9, 'WLC', 'WLC', 'he', '1SA', 9, 13, 'OT', 'כְּבֹאֲכֶ֣ם הָעִ֣יר כֵּ֣ן תִּמְצְא֣וּן אֹת֡וֹ בְּטֶרֶם֩ יַעֲלֶ֨ה הַבָּמָ֜תָה לֶאֱכֹ֗ל כִּ֠י לֹֽא יֹאכַ֤ל הָעָם֙ עַד בֹּא֔וֹ כִּֽי הוּא֙ יְבָרֵ֣ךְ הַזֶּ֔בַח אַחֲרֵי כֵ֖ן יֹאכְל֣וּ הַקְּרֻאִ֑ים וְעַתָּ֣ה עֲל֔וּ כִּֽי אֹת֥וֹ כְהַיּ֖וֹם תִּמְצְא֥וּן אֹתֽוֹ'),
(7406, 9, 'WLC', 'WLC', 'he', '1SA', 9, 14, 'OT', 'וַֽיַּעֲל֖וּ הָעִ֑יר הֵ֗מָּה בָּאִים֙ בְּת֣וֹךְ הָעִ֔יר וְהִנֵּ֤ה שְׁמוּאֵל֙ יֹצֵ֣א לִקְרָאתָ֔ם לַעֲל֖וֹת הַבָּמָֽה'),
(7407, 9, 'WLC', 'WLC', 'he', '1SA', 9, 15, 'OT', 'וַֽיהוָ֔ה גָּלָ֖ה אֶת אֹ֣זֶן שְׁמוּאֵ֑ל י֣וֹם אֶחָ֔ד לִפְנֵ֥י בֽוֹא שָׁא֖וּל לֵאמֹֽר'),
(7408, 9, 'WLC', 'WLC', 'he', '1SA', 9, 16, 'OT', 'כָּעֵ֣ת מָחָ֡ר אֶשְׁלַח֩ אֵלֶ֨יךָ אִ֜ישׁ מֵאֶ֣רֶץ בִּנְיָמִ֗ן וּמְשַׁחְתּ֤וֹ לְנָגִיד֙ עַל עַמִּ֣י יִשְׂרָאֵ֔ל וְהוֹשִׁ֥יעַ אֶת עַמִּ֖י מִיַּ֣ד פְּלִשְׁתִּ֑ים כִּ֤י רָאִ֨יתִי֙ אֶת עַמִּ֔י כִּ֛י בָּ֥אָה צַעֲקָת֖וֹ אֵלָֽי'),
(7409, 9, 'WLC', 'WLC', 'he', '1SA', 9, 17, 'OT', 'וּשְׁמוּאֵ֖ל רָאָ֣ה אֶת שָׁא֑וּל וַיהוָ֣ה עָנָ֔הוּ הִנֵּ֤ה הָאִישׁ֙ אֲשֶׁ֣ר אָמַ֣רְתִּי אֵלֶ֔יךָ זֶ֖ה יַעְצֹ֥ר בְּעַמִּֽי'),
(7410, 9, 'WLC', 'WLC', 'he', '1SA', 9, 18, 'OT', 'וַיִּגַּ֥שׁ שָׁא֛וּל אֶת שְׁמוּאֵ֖ל בְּת֣וֹךְ הַשָּׁ֑עַר וַיֹּ֨אמֶר֙ הַגִּֽידָה נָּ֣א לִ֔י אֵי זֶ֖ה בֵּ֥ית הָרֹאֶֽה'),
(7411, 9, 'WLC', 'WLC', 'he', '1SA', 9, 19, 'OT', 'וַיַּ֨עַן שְׁמוּאֵ֜ל אֶת שָׁא֗וּל וַיֹּ֨אמֶר֙ אָנֹכִ֣י הָרֹאֶ֔ה עֲלֵ֤ה לְפָנַי֙ הַבָּמָ֔ה וַאֲכַלְתֶּ֥ם עִמִּ֖י הַיּ֑וֹם וְשִׁלַּחְתִּ֣יךָ בַבֹּ֔קֶר וְכֹ֛ל אֲשֶׁ֥ר בִּֽלְבָבְךָ֖ אַגִּ֥יד לָֽךְ'),
(7412, 9, 'WLC', 'WLC', 'he', '1SA', 9, 20, 'OT', 'וְלָאֲתֹנ֞וֹת הָאֹבְד֣וֹת לְךָ֗ הַיּוֹם֙ שְׁלֹ֣שֶׁת הַיָּמִ֔ים אַל תָּ֧שֶׂם אֶֽת לִבְּךָ֛ לָהֶ֖ם כִּ֣י נִמְצָ֑אוּ וּלְמִי֙ כָּל חֶמְדַּ֣ת יִשְׂרָאֵ֔ל הֲל֣וֹא לְךָ֔ וּלְכֹ֖ל בֵּ֥ית אָבִֽיךָ'),
(7413, 9, 'WLC', 'WLC', 'he', '1SA', 9, 21, 'OT', 'וַיַּ֨עַן שָׁא֜וּל וַיֹּ֗אמֶר הֲל֨וֹא בֶן יְמִינִ֤י אָ֨נֹכִי֙ מִקַּטַנֵּי֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל וּמִשְׁפַּחְתִּי֙ הַצְּעִרָ֔ה מִכָּֽל מִשְׁפְּח֖וֹת שִׁבְטֵ֣י בִנְיָמִ֑ן וְלָ֨מָּה֙ דִּבַּ֣רְתָּ אֵלַ֔י כַּדָּבָ֖ר הַזֶּֽה'),
(7414, 9, 'WLC', 'WLC', 'he', '1SA', 9, 22, 'OT', 'וַיִּקַּ֤ח שְׁמוּאֵל֙ אֶת שָׁא֣וּל וְאֶֽת נַעֲר֔וֹ וַיְבִיאֵ֖ם לִשְׁכָּ֑תָה וַיִּתֵּ֨ן לָהֶ֤ם מָקוֹם֙ בְּרֹ֣אשׁ הַקְּרוּאִ֔ים וְהֵ֖מָּה כִּשְׁלֹשִׁ֥ים אִֽישׁ'),
(7415, 9, 'WLC', 'WLC', 'he', '1SA', 9, 23, 'OT', 'וַיֹּ֤אמֶר שְׁמוּאֵל֙ לַטַּבָּ֔ח תְּנָה֙ אֶת הַמָּנָ֔ה אֲשֶׁ֥ר נָתַ֖תִּי לָ֑ךְ אֲשֶׁר֙ אָמַ֣רְתִּי אֵלֶ֔יךָ שִׂ֥ים אֹתָ֖הּ עִמָּֽךְ'),
(7416, 9, 'WLC', 'WLC', 'he', '1SA', 9, 24, 'OT', 'וַיָּ֣רֶם הַ֠טַּבָּח אֶת הַשּׁ֨וֹק וְהֶעָלֶ֜יהָ וַיָּ֣שֶׂם לִפְנֵ֣י שָׁא֗וּל וַיֹּ֨אמֶר֙ הִנֵּ֤ה הַנִּשְׁאָר֙ שִׂים לְפָנֶ֣יךָ אֱכֹ֔ל כִּ֧י לַמּוֹעֵ֛ד שָֽׁמוּר לְךָ֥ לֵאמֹ֖ר הָעָ֣ם קָרָ֑אתִי וַיֹּ֧אכַל שָׁא֛וּל עִם שְׁמוּאֵ֖ל בַּיּ֥וֹם הַהֽוּא'),
(7417, 9, 'WLC', 'WLC', 'he', '1SA', 9, 25, 'OT', 'וַיֵּרְד֥וּ מֵהַבָּמָ֖ה הָעִ֑יר וַיְדַבֵּ֥ר עִם שָׁא֖וּל עַל הַגָּֽג'),
(7418, 9, 'WLC', 'WLC', 'he', '1SA', 9, 26, 'OT', 'וַיַּשְׁכִּ֗מוּ וַיְהִ֞י כַּעֲל֤וֹת הַשַּׁ֨חַר֙ וַיִּקְרָ֨א שְׁמוּאֵ֤ל אֶל שָׁאוּל֙ הגג לֵאמֹ֔ר ק֖וּמָה וַאֲשַׁלְּחֶ֑ךָּ וַיָּ֣קָם שָׁא֗וּל וַיֵּצְא֧וּ שְׁנֵיהֶ֛ם ה֥וּא וּשְׁמוּאֵ֖ל הַחֽוּצָה'),
(7419, 9, 'WLC', 'WLC', 'he', '1SA', 9, 27, 'OT', 'הֵ֗מָּה יֽוֹרְדִים֙ בִּקְצֵ֣ה הָעִ֔יר וּשְׁמוּאֵ֞ל אָמַ֣ר אֶל שָׁא֗וּל אֱמֹ֥ר לַנַּ֛עַר וְיַעֲבֹ֥ר לְפָנֵ֖ינוּ וַֽיַּעֲבֹ֑ר וְאַתָּה֙ עֲמֹ֣ד כַּיּ֔וֹם וְאַשְׁמִיעֲךָ֖ אֶת דְּבַ֥ר אֱלֹהִֽים'),
(7420, 9, 'WLC', 'WLC', 'he', '1SA', 10, 1, 'OT', 'וַיִּקַּ֨ח שְׁמוּאֵ֜ל אֶת פַּ֥ךְ הַשֶּׁ֛מֶן וַיִּצֹ֥ק עַל רֹאשׁ֖וֹ וַיִּשָּׁקֵ֑הוּ וַיֹּ֕אמֶר הֲל֗וֹא כִּֽי מְשָׁחֲךָ֧ יְהוָ֛ה עַל נַחֲלָת֖וֹ לְנָגִֽיד'),
(7421, 9, 'WLC', 'WLC', 'he', '1SA', 10, 2, 'OT', 'בְּלֶכְתְּךָ֤ הַיּוֹם֙ מֵעִמָּדִ֔י וּמָצָאתָ֩ שְׁנֵ֨י אֲנָשִׁ֜ים עִם קְבֻרַ֥ת רָחֵ֛ל בִּגְב֥וּל בִּנְיָמִ֖ן בְּצֶלְצַ֑ח וְאָמְר֣וּ אֵלֶ֗יךָ נִמְצְא֤וּ הָאֲתֹנוֹת֙ אֲשֶׁ֣ר הָלַ֣כְתָּ לְבַקֵּ֔שׁ וְהִנֵּ֨ה נָטַ֤שׁ אָבִ֨יךָ֙ אֶת דִּבְרֵ֣י הָאֲתֹנ֔וֹת וְדָאַ֤ג לָכֶם֙ לֵאמֹ֔ר מָ֥ה אֶעֱשֶׂ֖ה לִבְנִֽי'),
(7422, 9, 'WLC', 'WLC', 'he', '1SA', 10, 3, 'OT', 'וְחָלַפְתָּ֨ מִשָּׁ֜ם וָהָ֗לְאָה וּבָ֨אתָ֙ עַד אֵל֣וֹן תָּב֔וֹר וּמְצָא֤וּךָ שָּׁם֙ שְׁלֹשָׁ֣ה אֲנָשִׁ֔ים עֹלִ֥ים אֶל הָאֱלֹהִ֖ים בֵּֽית אֵ֑ל אֶחָ֞ד נֹשֵׂ֣א שְׁלֹשָׁ֣ה גְדָיִ֗ים וְאֶחָד֙ נֹשֵׂ֗א שְׁלֹ֨שֶׁת֙ כִּכְּר֣וֹת לֶ֔חֶם וְאֶחָ֥ד נֹשֵׂ֖א נֵֽבֶל יָֽיִן'),
(7423, 9, 'WLC', 'WLC', 'he', '1SA', 10, 4, 'OT', 'וְשָׁאֲל֥וּ לְךָ֖ לְשָׁל֑וֹם וְנָתְנ֤וּ לְךָ֙ שְׁתֵּי לֶ֔חֶם וְלָקַחְתָּ֖ מִיָּדָֽם'),
(7424, 9, 'WLC', 'WLC', 'he', '1SA', 10, 5, 'OT', 'אַ֣חַר כֵּ֗ן תָּבוֹא֙ גִּבְעַ֣ת הָאֱלֹהִ֔ים אֲשֶׁר שָׁ֖ם נְצִבֵ֣י פְלִשְׁתִּ֑ים וִיהִי֩ כְבֹאֲךָ֨ שָׁ֜ם הָעִ֗יר וּפָגַעְתָּ֞ חֶ֤בֶל נְבִיאִים֙ יֹרְדִ֣ים מֵֽהַבָּמָ֔ה וְלִפְנֵיהֶ֞ם נֵ֤בֶל וְתֹף֙ וְחָלִ֣יל וְכִנּ֔וֹר וְהֵ֖מָּה מִֽתְנַבְּאִֽים'),
(7425, 9, 'WLC', 'WLC', 'he', '1SA', 10, 6, 'OT', 'וְצָלְחָ֤ה עָלֶ֨יךָ֙ ר֣וּחַ יְהוָ֔ה וְהִתְנַבִּ֖יתָ עִמָּ֑ם וְנֶהְפַּכְתָּ֖ לְאִ֥ישׁ אַחֵֽר'),
(7426, 9, 'WLC', 'WLC', 'he', '1SA', 10, 7, 'OT', 'וְהָיָ֗ה כִּ֥י תבאינה הָאֹת֥וֹת הָאֵ֖לֶּה לָ֑ךְ עֲשֵׂ֤ה לְךָ֙ אֲשֶׁ֣ר תִּמְצָ֣א יָדֶ֔ךָ כִּ֥י הָאֱלֹהִ֖ים עִמָּֽךְ'),
(7427, 9, 'WLC', 'WLC', 'he', '1SA', 10, 8, 'OT', 'וְיָרַדְתָּ֣ לְפָנַי֮ הַגִּלְגָּל֒ וְהִנֵּ֤ה אָֽנֹכִי֙ יֹרֵ֣ד אֵלֶ֔יךָ לְהַעֲל֣וֹת עֹל֔וֹת לִזְבֹּ֖חַ זִבְחֵ֣י שְׁלָמִ֑ים שִׁבְעַ֨ת יָמִ֤ים תּוֹחֵל֙ עַד בּוֹאִ֣י אֵלֶ֔יךָ וְהוֹדַעְתִּ֣י לְךָ֔ אֵ֖ת אֲשֶׁ֥ר תַּעֲשֶֽׂה'),
(7428, 9, 'WLC', 'WLC', 'he', '1SA', 10, 9, 'OT', 'וְהָיָ֗ה כְּהַפְנֹת֤וֹ שִׁכְמוֹ֙ לָלֶ֨כֶת֙ מֵעִ֣ם שְׁמוּאֵ֔ל וַיַּהֲפָךְ ל֥וֹ אֱלֹהִ֖ים לֵ֣ב אַחֵ֑ר וַיָּבֹ֛אוּ כָּל הָאֹת֥וֹת הָאֵ֖לֶּה בַּיּ֥וֹם הַהֽוּא'),
(7429, 9, 'WLC', 'WLC', 'he', '1SA', 10, 10, 'OT', 'וַיָּבֹ֤אוּ שָׁם֙ הַגִּבְעָ֔תָה וְהִנֵּ֥ה חֶֽבֶל נְבִאִ֖ים לִקְרָאת֑וֹ וַתִּצְלַ֤ח עָלָיו֙ ר֣וּחַ אֱלֹהִ֔ים וַיִּתְנַבֵּ֖א בְּתוֹכָֽם'),
(7430, 9, 'WLC', 'WLC', 'he', '1SA', 10, 11, 'OT', 'וַיְהִ֗י כָּל יֽוֹדְעוֹ֙ מֵאִתְּמ֣וֹל שִׁלְשׁ֔וֹם וַיִּרְא֕וּ וְהִנֵּ֥ה עִם נְבִאִ֖ים נִבָּ֑א וַיֹּ֨אמֶר הָעָ֜ם אִ֣ישׁ אֶל רֵעֵ֗הוּ מַה זֶּה֙ הָיָ֣ה לְבֶן קִ֔ישׁ הֲגַ֥ם שָׁא֖וּל בַּנְּבִיאִֽים'),
(7431, 9, 'WLC', 'WLC', 'he', '1SA', 10, 12, 'OT', 'וַיַּ֨עַן אִ֥ישׁ מִשָּׁ֛ם וַיֹּ֖אמֶר וּמִ֣י אֲבִיהֶ֑ם עַל כֵּן֙ הָיְתָ֣ה לְמָשָׁ֔ל הֲגַ֥ם שָׁא֖וּל בַּנְּבִאִֽים'),
(7432, 9, 'WLC', 'WLC', 'he', '1SA', 10, 13, 'OT', 'וַיְכַל֙ מֵֽהִתְנַבּ֔וֹת וַיָּבֹ֖א הַבָּמָֽה'),
(7433, 9, 'WLC', 'WLC', 'he', '1SA', 10, 14, 'OT', 'וַיֹּאמֶר֩ דּ֨וֹד שָׁא֥וּל אֵלָ֛יו וְאֶֽל נַעֲר֖וֹ אָ֣ן הֲלַכְתֶּ֑ם וַיֹּ֕אמֶר לְבַקֵּשׁ֙ אֶת הָ֣אֲתֹנ֔וֹת וַנִּרְאֶ֣ה כִי אַ֔יִן וַנָּב֖וֹא אֶל שְׁמוּאֵֽל'),
(7434, 9, 'WLC', 'WLC', 'he', '1SA', 10, 15, 'OT', 'וַיֹּ֖אמֶר דּ֣וֹד שָׁא֑וּל הַגִּֽידָה נָּ֣א לִ֔י מָֽה אָמַ֥ר לָכֶ֖ם שְׁמוּאֵֽל'),
(7435, 9, 'WLC', 'WLC', 'he', '1SA', 10, 16, 'OT', 'וַיֹּ֤אמֶר שָׁאוּל֙ אֶל דּוֹד֔וֹ הַגֵּ֤ד הִגִּיד֙ לָ֔נוּ כִּ֥י נִמְצְא֖וּ הָאֲתֹנ֑וֹת וְאֶת דְּבַ֤ר הַמְּלוּכָה֙ לֹֽא הִגִּ֣יד ל֔וֹ אֲשֶׁ֖ר אָמַ֥ר שְׁמוּאֵֽל'),
(7436, 9, 'WLC', 'WLC', 'he', '1SA', 10, 17, 'OT', 'וַיַּצְעֵ֤ק שְׁמוּאֵל֙ אֶת הָעָ֔ם אֶל יְהוָ֖ה הַמִּצְפָּֽה'),
(7437, 9, 'WLC', 'WLC', 'he', '1SA', 10, 18, 'OT', 'וַיֹּ֣אמֶר אֶל בְּנֵ֣י יִשְׂרָאֵ֗ל כֹּֽה אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אָנֹכִ֛י הֶעֱלֵ֥יתִי אֶת יִשְׂרָאֵ֖ל מִמִּצְרָ֑יִם וָאַצִּ֤יל אֶתְכֶם֙ מִיַּ֣ד מִצְרַ֔יִם וּמִיַּד֙ כָּל הַמַּמְלָכ֔וֹת הַלֹּחֲצִ֖ים אֶתְכֶֽם'),
(7438, 9, 'WLC', 'WLC', 'he', '1SA', 10, 19, 'OT', 'וְאַתֶּ֨ם הַיּ֜וֹם מְאַסְתֶּ֣ם אֶת אֱלֹהֵיכֶ֗ם אֲשֶׁר ה֣וּא מוֹשִׁ֣יעַ לָכֶם֮ מִכָּל רָעוֹתֵיכֶ֣ם וְצָרֹֽתֵיכֶם֒ וַתֹּ֣אמְרוּ ל֔וֹ כִּי מֶ֖לֶךְ תָּשִׂ֣ים עָלֵ֑ינוּ וְעַתָּ֗ה הִֽתְיַצְּבוּ֙ לִפְנֵ֣י יְהוָ֔ה לְשִׁבְטֵיכֶ֖ם וּלְאַלְפֵיכֶֽם'),
(7439, 9, 'WLC', 'WLC', 'he', '1SA', 10, 20, 'OT', 'וַיַּקְרֵ֣ב שְׁמוּאֵ֔ל אֵ֖ת כָּל שִׁבְטֵ֣י יִשְׂרָאֵ֑ל וַיִּלָּכֵ֖ד שֵׁ֥בֶט בִּנְיָמִֽן'),
(7440, 9, 'WLC', 'WLC', 'he', '1SA', 10, 21, 'OT', 'וַיַּקְרֵ֞ב אֶת שֵׁ֤בֶט בִּנְיָמִן֙ למשפחתו וַתִּלָּכֵ֖ד מִשְׁפַּ֣חַת הַמַּטְרִ֑י וַיִּלָּכֵד֙ שָׁא֣וּל בֶּן קִ֔ישׁ וַיְבַקְשֻׁ֖הוּ וְלֹ֥א נִמְצָֽא'),
(7441, 9, 'WLC', 'WLC', 'he', '1SA', 10, 22, 'OT', 'וַיִּשְׁאֲלוּ עוֹד֙ בַּֽיהוָ֔ה הֲבָ֥א ע֖וֹד הֲלֹ֣ם אִ֑ישׁ וַיֹּ֣אמֶר יְהוָ֔ה הִנֵּה ה֥וּא נֶחְבָּ֖א אֶל הַכֵּלִֽים'),
(7442, 9, 'WLC', 'WLC', 'he', '1SA', 10, 23, 'OT', 'וַיָּרֻ֨צוּ֙ וַיִּקָּחֻ֣הוּ מִשָּׁ֔ם וַיִּתְיַצֵּ֖ב בְּת֣וֹךְ הָעָ֑ם וַיִּגְבַּהּ֙ מִכָּל הָעָ֔ם מִשִּׁכְמ֖וֹ וָמָֽעְלָה'),
(7443, 9, 'WLC', 'WLC', 'he', '1SA', 10, 24, 'OT', 'וַיֹּ֨אמֶר שְׁמוּאֵ֜ל אֶל כָּל הָעָ֗ם הַרְּאִיתֶם֙ אֲשֶׁ֣ר בָּֽחַר בּ֣וֹ יְהוָ֔ה כִּ֛י אֵ֥ין כָּמֹ֖הוּ בְּכָל הָעָ֑ם וַיָּרִ֧עוּ כָל הָעָ֛ם וַיֹּאמְר֖וּ יְחִ֥י הַמֶּֽלֶךְ'),
(7444, 9, 'WLC', 'WLC', 'he', '1SA', 10, 25, 'OT', 'וַיְדַבֵּ֨ר שְׁמוּאֵ֜ל אֶל הָעָ֗ם אֵ֚ת מִשְׁפַּ֣ט הַמְּלֻכָ֔ה וַיִּכְתֹּ֣ב בַּסֵּ֔פֶר וַיַּנַּ֖ח לִפְנֵ֣י יְהוָ֑ה וַיְשַׁלַּ֧ח שְׁמוּאֵ֛ל אֶת כָּל הָעָ֖ם אִ֥ישׁ לְבֵיתֽוֹ'),
(7445, 9, 'WLC', 'WLC', 'he', '1SA', 10, 26, 'OT', 'וְגַ֨ם שָׁא֔וּל הָלַ֥ךְ לְבֵית֖וֹ גִּבְעָ֑תָה וַיֵּלְכ֣וּ עִמּ֔וֹ הַחַ֕יִל אֲשֶׁר נָגַ֥ע אֱלֹהִ֖ים בְּלִבָּֽם'),
(7446, 9, 'WLC', 'WLC', 'he', '1SA', 10, 27, 'OT', 'וּבְנֵ֧י בְלִיַּ֣עַל אָמְר֗וּ מַה יֹּשִׁעֵ֨נוּ֙ זֶ֔ה וַיִּבְזֻ֕הוּ וְלֹֽא הֵבִ֥יאוּ ל֖וֹ מִנְחָ֑ה וַיְהִ֖י כְּמַחֲרִֽישׁ'),
(7447, 9, 'WLC', 'WLC', 'he', '1SA', 11, 1, 'OT', 'וַיַּ֗עַל נָחָשׁ֙ הָֽעַמּוֹנִ֔י וַיִּ֖חַן עַל יָבֵ֣שׁ גִּלְעָ֑ד וַיֹּ֨אמְר֜וּ כָּל אַנְשֵׁ֤י יָבֵישׁ֙ אֶל נָחָ֔שׁ כְּרָת לָ֥נוּ בְרִ֖ית וְנַעַבְדֶֽךָּ'),
(7448, 9, 'WLC', 'WLC', 'he', '1SA', 11, 2, 'OT', 'וַיֹּ֣אמֶר אֲלֵיהֶ֗ם נָחָשׁ֙ הָעַמּוֹנִ֔י בְּזֹאת֙ אֶכְרֹ֣ת לָכֶ֔ם בִּנְק֥וֹר לָכֶ֖ם כָּל עֵ֣ין יָמִ֑ין וְשַׂמְתִּ֥יהָ חֶרְפָּ֖ה עַל כָּל יִשְׂרָאֵֽל'),
(7449, 9, 'WLC', 'WLC', 'he', '1SA', 11, 3, 'OT', 'וַיֹּאמְר֨וּ אֵלָ֜יו זִקְנֵ֣י יָבֵ֗ישׁ הֶ֤רֶף לָ֨נוּ֙ שִׁבְעַ֣ת יָמִ֔ים וְנִשְׁלְחָה֙ מַלְאָכִ֔ים בְּכֹ֖ל גְּב֣וּל יִשְׂרָאֵ֑ל וְאִם אֵ֥ין מוֹשִׁ֛יעַ אֹתָ֖נוּ וְיָצָ֥אנוּ אֵלֶֽיךָ'),
(7450, 9, 'WLC', 'WLC', 'he', '1SA', 11, 4, 'OT', 'וַיָּבֹ֤אוּ הַמַּלְאָכִים֙ גִּבְעַ֣ת שָׁא֔וּל וַיְדַבְּר֥וּ הַדְּבָרִ֖ים בְּאָזְנֵ֣י הָעָ֑ם וַיִּשְׂא֧וּ כָל הָעָ֛ם אֶת קוֹלָ֖ם וַיִּבְכּֽוּ'),
(7451, 9, 'WLC', 'WLC', 'he', '1SA', 11, 5, 'OT', 'וְהִנֵּ֣ה שָׁא֗וּל בָּ֣א אַחֲרֵ֤י הַבָּקָר֙ מִן הַשָּׂדֶ֔ה וַיֹּ֣אמֶר שָׁא֔וּל מַה לָּעָ֖ם כִּ֣י יִבְכּ֑וּ וַיְסַ֨פְּרוּ ל֔וֹ אֶת דִּבְרֵ֖י אַנְשֵׁ֥י יָבֵֽישׁ'),
(7452, 9, 'WLC', 'WLC', 'he', '1SA', 11, 6, 'OT', 'וַתִּצְלַ֤ח רֽוּחַ אֱלֹהִים֙ עַל שָׁא֔וּל בשמעו אֶת הַדְּבָרִ֣ים הָאֵ֑לֶּה וַיִּ֥חַר אַפּ֖וֹ מְאֹֽד'),
(7453, 9, 'WLC', 'WLC', 'he', '1SA', 11, 7, 'OT', 'וַיִּקַּח֩ צֶ֨מֶד בָּקָ֜ר וַֽיְנַתְּחֵ֗הוּ וַיְשַׁלַּ֞ח בְּכָל גְּב֣וּל יִשְׂרָאֵל֮ בְּיַ֣ד הַמַּלְאָכִ֣ים לֵאמֹר֒ אֲשֶׁר֩ אֵינֶ֨נּוּ יֹצֵ֜א אַחֲרֵ֤י שָׁאוּל֙ וְאַחַ֣ר שְׁמוּאֵ֔ל כֹּ֥ה יֵעָשֶׂ֖ה לִבְקָר֑וֹ וַיִּפֹּ֤ל פַּֽחַד יְהוָה֙ עַל הָעָ֔ם וַיֵּצְא֖וּ כְּאִ֥ישׁ אֶחָֽד'),
(7454, 9, 'WLC', 'WLC', 'he', '1SA', 11, 8, 'OT', 'וַֽיִּפְקְדֵ֖ם בְּבָ֑זֶק וַיִּהְי֤וּ בְנֵֽי יִשְׂרָאֵל֙ שְׁלֹ֣שׁ מֵא֣וֹת אֶ֔לֶף וְאִ֥ישׁ יְהוּדָ֖ה שְׁלֹשִׁ֥ים אָֽלֶף'),
(7455, 9, 'WLC', 'WLC', 'he', '1SA', 11, 9, 'OT', 'וַיֹּאמְר֞וּ לַמַּלְאָכִ֣ים הַבָּאִ֗ים כֹּ֤ה תֹֽאמְרוּן֙ לְאִישׁ֙ יָבֵ֣ישׁ גִּלְעָ֔ד מָחָ֛ר תִּהְיֶֽה לָכֶ֥ם תְּשׁוּעָ֖ה בחם הַשָּׁ֑מֶשׁ וַיָּבֹ֣אוּ הַמַּלְאָכִ֗ים וַיַּגִּ֛ידוּ לְאַנְשֵׁ֥י יָבֵ֖ישׁ וַיִּשְׂמָֽחוּ'),
(7456, 9, 'WLC', 'WLC', 'he', '1SA', 11, 10, 'OT', 'וַֽיֹּאמְרוּ֙ אַנְשֵׁ֣י יָבֵ֔ישׁ מָחָ֖ר נֵצֵ֣א אֲלֵיכֶ֑ם וַעֲשִׂיתֶ֣ם לָּ֔נוּ כְּכָל הַטּ֖וֹב בְּעֵינֵיכֶֽם'),
(7457, 9, 'WLC', 'WLC', 'he', '1SA', 11, 11, 'OT', 'וַיְהִ֣י מִֽמָּחֳרָ֗ת וַיָּ֨שֶׂם שָׁא֣וּל אֶת הָעָם֮ שְׁלֹשָׁ֣ה רָאשִׁים֒ וַיָּבֹ֤אוּ בְתוֹךְ הַֽמַּחֲנֶה֙ בְּאַשְׁמֹ֣רֶת הַבֹּ֔קֶר וַיַּכּ֥וּ אֶת עַמּ֖וֹן עַד חֹ֣ם הַיּ֑וֹם וַיְהִ֤י הַנִּשְׁאָרִים֙ וַיָּפֻ֔צוּ וְלֹ֥א נִשְׁאֲרוּ בָ֖ם שְׁנַ֥יִם יָֽחַד'),
(7458, 9, 'WLC', 'WLC', 'he', '1SA', 11, 12, 'OT', 'וַיֹּ֤אמֶר הָעָם֙ אֶל שְׁמוּאֵ֔ל מִ֣י הָאֹמֵ֔ר שָׁא֖וּל יִמְלֹ֣ךְ עָלֵ֑ינוּ תְּנ֥וּ הָאֲנָשִׁ֖ים וּנְמִיתֵֽם'),
(7459, 9, 'WLC', 'WLC', 'he', '1SA', 11, 13, 'OT', 'וַיֹּ֣אמֶר שָׁא֔וּל לֹֽא יוּמַ֥ת אִ֖ישׁ בַּיּ֣וֹם הַזֶּ֑ה כִּ֥י הַיּ֛וֹם עָשָֽׂה יְהוָ֥ה תְּשׁוּעָ֖ה בְּיִשְׂרָאֵֽל'),
(7460, 9, 'WLC', 'WLC', 'he', '1SA', 11, 14, 'OT', 'וַיֹּ֤אמֶר שְׁמוּאֵל֙ אֶל הָעָ֔ם לְכ֖וּ וְנֵלְכָ֣ה הַגִּלְגָּ֑ל וּנְחַדֵּ֥שׁ שָׁ֖ם הַמְּלוּכָֽה'),
(7461, 9, 'WLC', 'WLC', 'he', '1SA', 11, 15, 'OT', 'וַיֵּלְכ֨וּ כָל הָעָ֜ם הַגִּלְגָּ֗ל וַיַּמְלִכוּ֩ שָׁ֨ם אֶת שָׁא֜וּל לִפְנֵ֤י יְהוָה֙ בַּגִּלְגָּ֔ל וַיִּזְבְּחוּ שָׁ֛ם זְבָחִ֥ים שְׁלָמִ֖ים לִפְנֵ֣י יְהוָ֑ה וַיִּשְׂמַ֨ח שָׁ֥ם שָׁא֛וּל וְכָל אַנְשֵׁ֥י יִשְׂרָאֵ֖ל עַד מְאֹֽד'),
(7462, 9, 'WLC', 'WLC', 'he', '1SA', 12, 1, 'OT', 'וַיֹּ֤אמֶר שְׁמוּאֵל֙ אֶל כָּל יִשְׂרָאֵ֔ל הִנֵּה֙ שָׁמַ֣עְתִּי בְקֹֽלְכֶ֔ם לְכֹ֥ל אֲשֶׁר אֲמַרְתֶּ֖ם לִ֑י וָאַמְלִ֥יךְ עֲלֵיכֶ֖ם מֶֽלֶךְ'),
(7463, 9, 'WLC', 'WLC', 'he', '1SA', 12, 2, 'OT', 'וְעַתָּ֞ה הִנֵּ֥ה הַמֶּ֣לֶךְ מִתְהַלֵּ֣ךְ לִפְנֵיכֶ֗ם וַאֲנִי֙ זָקַ֣נְתִּי וָשַׂ֔בְתִּי וּבָנַ֖י הִנָּ֣ם אִתְּכֶ֑ם וַאֲנִי֙ הִתְהַלַּ֣כְתִּי לִפְנֵיכֶ֔ם מִנְּעֻרַ֖י עַד הַיּ֥וֹם הַזֶּֽה'),
(7464, 9, 'WLC', 'WLC', 'he', '1SA', 12, 3, 'OT', 'הִנְנִ֣י עֲנ֣וּ בִי֩ נֶ֨גֶד יְהוָ֜ה וְנֶ֣גֶד מְשִׁיח֗וֹ אֶת שׁוֹר֩ מִ֨י לָקַ֜חְתִּי וַחֲמ֧וֹר מִ֣י לָקַ֗חְתִּי וְאֶת מִ֤י עָשַׁ֨קְתִּי֙ אֶת מִ֣י רַצּ֔וֹתִי וּמִיַּד מִי֙ לָקַ֣חְתִּי כֹ֔פֶר וְאַעְלִ֥ים עֵינַ֖י בּ֑וֹ וְאָשִׁ֖יב לָכֶֽם'),
(7465, 9, 'WLC', 'WLC', 'he', '1SA', 12, 4, 'OT', 'וַיֹּ֣אמְר֔וּ לֹ֥א עֲשַׁקְתָּ֖נוּ וְלֹ֣א רַצּוֹתָ֑נוּ וְלֹֽא לָקַ֥חְתָּ מִיַּד אִ֖ישׁ מְאֽוּמָה'),
(7466, 9, 'WLC', 'WLC', 'he', '1SA', 12, 5, 'OT', 'וַיֹּ֨אמֶר אֲלֵיהֶ֜ם עֵ֧ד יְהוָ֣ה בָּכֶ֗ם וְעֵ֤ד מְשִׁיחוֹ֙ הַיּ֣וֹם הַזֶּ֔ה כִּ֣י לֹ֧א מְצָאתֶ֛ם בְּיָדִ֖י מְא֑וּמָה וַיֹּ֖אמֶר עֵֽד'),
(7467, 9, 'WLC', 'WLC', 'he', '1SA', 12, 6, 'OT', 'וַיֹּ֥אמֶר שְׁמוּאֵ֖ל אֶל הָעָ֑ם יְהוָ֗ה אֲשֶׁ֤ר עָשָׂה֙ אֶת מֹשֶׁ֣ה וְאֶֽת אַהֲרֹ֔ן וַאֲשֶׁ֧ר הֶעֱלָ֛ה אֶת אֲבֹתֵיכֶ֖ם מֵאֶ֥רֶץ מִצְרָֽיִם'),
(7468, 9, 'WLC', 'WLC', 'he', '1SA', 12, 7, 'OT', 'וְעַתָּ֗ה הִֽתְיַצְּב֛וּ וְאִשָּׁפְטָ֥ה אִתְּכֶ֖ם לִפְנֵ֣י יְהוָ֑ה אֵ֚ת כָּל צִדְק֣וֹת יְהוָ֔ה אֲשֶׁר עָשָׂ֥ה אִתְּכֶ֖ם וְאֶת אֲבוֹתֵיכֶֽם'),
(7469, 9, 'WLC', 'WLC', 'he', '1SA', 12, 8, 'OT', 'כַּֽאֲשֶׁר בָּ֥א יַעֲקֹ֖ב מִצְרָ֑יִם וַיִּזְעֲק֤וּ אֲבֽוֹתֵיכֶם֙ אֶל יְהוָ֔ה וַיִּשְׁלַ֨ח יְהוָ֜ה אֶת מֹשֶׁ֣ה וְאֶֽת אַהֲרֹ֗ן וַיּוֹצִ֤יאוּ אֶת אֲבֹֽתֵיכֶם֙ מִמִּצְרַ֔יִם וַיֹּשִׁב֖וּם בַּמָּק֥וֹם הַזֶּֽה'),
(7470, 9, 'WLC', 'WLC', 'he', '1SA', 12, 9, 'OT', 'וַֽיִּשְׁכְּח֖וּ אֶת יְהוָ֣ה אֱלֹהֵיהֶ֑ם וַיִּמְכֹּ֣ר אֹתָ֡ם בְּיַ֣ד סִֽיסְרָא֩ שַׂר צְבָ֨א חָצ֜וֹר וּבְיַד פְּלִשְׁתִּ֗ים וּבְיַד֙ מֶ֣לֶךְ מוֹאָ֔ב וַיִּֽלָּחֲמ֖וּ בָּֽם'),
(7471, 9, 'WLC', 'WLC', 'he', '1SA', 12, 10, 'OT', 'וַיִּזְעֲק֤וּ אֶל יְהוָה֙ ויאמר חָטָ֔אנוּ כִּ֤י עָזַ֨בְנוּ֙ אֶת יְהוָ֔ה וַנַּעֲבֹ֥ד אֶת הַבְּעָלִ֖ים וְאֶת הָעַשְׁתָּר֑וֹת וְעַתָּ֗ה הַצִּילֵ֛נוּ מִיַּ֥ד אֹיְבֵ֖ינוּ וְנַעַבְדֶֽךָּ'),
(7472, 9, 'WLC', 'WLC', 'he', '1SA', 12, 11, 'OT', 'וַיִּשְׁלַ֤ח יְהוָה֙ אֶת יְרֻבַּ֣עַל וְאֶת בְּדָ֔ן וְאֶת יִפְתָּ֖ח וְאֶת שְׁמוּאֵ֑ל וַיַּצֵּ֨ל אֶתְכֶ֜ם מִיַּ֤ד אֹֽיְבֵיכֶם֙ מִסָּבִ֔יב וַתֵּשְׁב֖וּ בֶּֽטַח'),
(7473, 9, 'WLC', 'WLC', 'he', '1SA', 12, 12, 'OT', 'וַתִּרְא֗וּ כִּֽי נָחָ֞שׁ מֶ֣לֶךְ בְּנֵֽי עַמּוֹן֮ בָּ֣א עֲלֵיכֶם֒ וַתֹּ֣אמְרוּ לִ֔י לֹ֕א כִּי מֶ֖לֶךְ יִמְלֹ֣ךְ עָלֵ֑ינוּ וַיהוָ֥ה אֱלֹהֵיכֶ֖ם מַלְכְּכֶֽם'),
(7474, 9, 'WLC', 'WLC', 'he', '1SA', 12, 13, 'OT', 'וְעַתָּ֗ה הִנֵּ֥ה הַמֶּ֛לֶךְ אֲשֶׁ֥ר בְּחַרְתֶּ֖ם אֲשֶׁ֣ר שְׁאֶלְתֶּ֑ם וְהִנֵּ֨ה נָתַ֧ן יְהוָ֛ה עֲלֵיכֶ֖ם מֶֽלֶךְ'),
(7475, 9, 'WLC', 'WLC', 'he', '1SA', 12, 14, 'OT', 'אִם תִּֽירְא֣וּ אֶת יְהוָ֗ה וַעֲבַדְתֶּ֤ם אֹתוֹ֙ וּשְׁמַעְתֶּ֣ם בְּקֹל֔וֹ וְלֹ֥א תַמְר֖וּ אֶת פִּ֣י יְהוָ֑ה וִהְיִתֶ֣ם גַּם אַתֶּ֗ם וְגַם הַמֶּ֨לֶךְ֙ אֲשֶׁ֣ר מָלַ֣ךְ עֲלֵיכֶ֔ם אַחַ֖ר יְהוָ֥ה אֱלֹהֵיכֶֽם'),
(7476, 9, 'WLC', 'WLC', 'he', '1SA', 12, 15, 'OT', 'וְאִם לֹ֤א תִשְׁמְעוּ֙ בְּק֣וֹל יְהוָ֔ה וּמְרִיתֶ֖ם אֶת פִּ֣י יְהוָ֑ה וְהָיְתָ֧ה יַד יְהוָ֛ה בָּכֶ֖ם וּבַאֲבֹתֵיכֶֽם'),
(7477, 9, 'WLC', 'WLC', 'he', '1SA', 12, 16, 'OT', 'גַּם עַתָּה֙ הִתְיַצְּב֣וּ וּרְא֔וּ אֶת הַדָּבָ֥ר הַגָּד֖וֹל הַזֶּ֑ה אֲשֶׁ֣ר יְהוָ֔ה עֹשֶׂ֖ה לְעֵינֵיכֶֽם'),
(7478, 9, 'WLC', 'WLC', 'he', '1SA', 12, 17, 'OT', 'הֲל֤וֹא קְצִיר חִטִּים֙ הַיּ֔וֹם אֶקְרָא֙ אֶל יְהוָ֔ה וְיִתֵּ֥ן קֹל֖וֹת וּמָטָ֑ר וּדְע֣וּ וּרְא֗וּ כִּֽי רָעַתְכֶ֤ם רַבָּה֙ אֲשֶׁ֤ר עֲשִׂיתֶם֙ בְּעֵינֵ֣י יְהוָ֔ה לִשְׁא֥וֹל לָכֶ֖ם מֶֽלֶךְ'),
(7479, 9, 'WLC', 'WLC', 'he', '1SA', 12, 18, 'OT', 'וַיִּקְרָ֤א שְׁמוּאֵל֙ אֶל יְהוָ֔ה וַיִּתֵּ֧ן יְהוָ֛ה קֹלֹ֥ת וּמָטָ֖ר בַּיּ֣וֹם הַה֑וּא וַיִּירָ֨א כָל הָעָ֥ם מְאֹ֛ד אֶת יְהוָ֖ה וְאֶת שְׁמוּאֵֽל'),
(7480, 9, 'WLC', 'WLC', 'he', '1SA', 12, 19, 'OT', 'וַיֹּאמְר֨וּ כָל הָעָ֜ם אֶל שְׁמוּאֵ֗ל הִתְפַּלֵּ֧ל בְּעַד עֲבָדֶ֛יךָ אֶל יְהוָ֥ה אֱלֹהֶ֖יךָ וְאַל נָמ֑וּת כִּֽי יָסַ֤פְנוּ עַל כָּל חַטֹּאתֵ֨ינוּ֙ רָעָ֔ה לִשְׁאֹ֥ל לָ֖נוּ מֶֽלֶךְ'),
(7481, 9, 'WLC', 'WLC', 'he', '1SA', 12, 20, 'OT', 'וַיֹּ֨אמֶר שְׁמוּאֵ֤ל אֶל הָעָם֙ אַל תִּירָ֔אוּ אַתֶּ֣ם עֲשִׂיתֶ֔ם אֵ֥ת כָּל הָרָעָ֖ה הַזֹּ֑את אַ֗ךְ אַל תָּס֨וּרוּ֙ מֵאַחֲרֵ֣י יְהוָ֔ה וַעֲבַדְתֶּ֥ם אֶת יְהוָ֖ה בְּכָל לְבַבְכֶֽם'),
