(7695, 9, 'WLC', 'WLC', 'he', '1SA', 18, 18, 'OT', 'וַיֹּ֨אמֶר דָּוִ֜ד אֶל שָׁא֗וּל מִ֤י אָֽנֹכִי֙ וּמִ֣י חַיַּ֔י מִשְׁפַּ֥חַת אָבִ֖י בְּיִשְׂרָאֵ֑ל כִּֽי אֶהְיֶ֥ה חָתָ֖ן לַמֶּֽלֶךְ'),
(7696, 9, 'WLC', 'WLC', 'he', '1SA', 18, 19, 'OT', 'וַיְהִ֗י בְּעֵ֥ת תֵּ֛ת אֶת מֵרַ֥ב בַּת שָׁא֖וּל לְדָוִ֑ד וְהִ֧יא נִתְּנָ֛ה לְעַדְרִיאֵ֥ל הַמְּחֹלָתִ֖י לְאִשָּֽׁה'),
(7697, 9, 'WLC', 'WLC', 'he', '1SA', 18, 20, 'OT', 'וַתֶּאֱהַ֛ב מִיכַ֥ל בַּת שָׁא֖וּל אֶת דָּוִ֑ד וַיַּגִּ֣דוּ לְשָׁא֔וּל וַיִּשַׁ֥ר הַדָּבָ֖ר בְּעֵינָֽיו'),
(7698, 9, 'WLC', 'WLC', 'he', '1SA', 18, 21, 'OT', 'וַיֹּ֨אמֶר שָׁא֜וּל אֶתְּנֶ֤נָּה לּוֹ֙ וּתְהִי ל֣וֹ לְמוֹקֵ֔שׁ וּתְהִי ב֖וֹ יַד פְּלִשְׁתִּ֑ים וַיֹּ֤אמֶר שָׁאוּל֙ אֶל דָּוִ֔ד בִּשְׁתַּ֛יִם תִּתְחַתֵּ֥ן בִּ֖י הַיּֽוֹם'),
(7699, 9, 'WLC', 'WLC', 'he', '1SA', 18, 22, 'OT', 'וַיְצַ֨ו שָׁא֜וּל אֶת עֲבָדָ֗ו דַּבְּר֨וּ אֶל דָּוִ֤ד בַּלָּט֙ לֵאמֹ֔ר הִנֵּ֨ה חָפֵ֤ץ בְּךָ֙ הַמֶּ֔לֶךְ וְכָל עֲבָדָ֖יו אֲהֵב֑וּךָ וְעַתָּ֖ה הִתְחַתֵּ֥ן בַּמֶּֽלֶךְ'),
(7700, 9, 'WLC', 'WLC', 'he', '1SA', 18, 23, 'OT', 'וַֽיְדַבְּר֞וּ עַבְדֵ֤י שָׁאוּל֙ בְּאָזְנֵ֣י דָוִ֔ד אֶת הַדְּבָרִ֖ים הָאֵ֑לֶּה וַיֹּ֣אמֶר דָּוִ֗ד הַֽנְקַלָּ֤ה בְעֵֽינֵיכֶם֙ הִתְחַתֵּ֣ן בַּמֶּ֔לֶךְ וְאָנֹכִ֖י אִֽישׁ רָ֥שׁ וְנִקְלֶֽה'),
(7701, 9, 'WLC', 'WLC', 'he', '1SA', 18, 24, 'OT', 'וַיַּגִּ֜דוּ עַבְדֵ֥י שָׁא֛וּל ל֖וֹ לֵאמֹ֑ר כַּדְּבָרִ֥ים הָאֵ֖לֶּה דִּבֶּ֥ר דָּוִֽד'),
(7702, 9, 'WLC', 'WLC', 'he', '1SA', 18, 25, 'OT', 'וַיֹּ֨אמֶר שָׁא֜וּל כֹּֽה תֹאמְר֣וּ לְדָוִ֗ד אֵֽין חֵ֤פֶץ לַמֶּ֨לֶךְ֙ בְּמֹ֔הַר כִּ֗י בְּמֵאָה֙ עָרְל֣וֹת פְּלִשְׁתִּ֔ים לְהִנָּקֵ֖ם בְּאֹיְבֵ֣י הַמֶּ֑לֶךְ וְשָׁא֣וּל חָשַׁ֔ב לְהַפִּ֥יל אֶת דָּוִ֖ד בְּיַד פְּלִשְׁתִּֽים'),
(7703, 9, 'WLC', 'WLC', 'he', '1SA', 18, 26, 'OT', 'וַיַּגִּ֨דוּ עֲבָדָ֤יו לְדָוִד֙ אֶת הַדְּבָרִ֣ים הָאֵ֔לֶּה וַיִּשַׁ֤ר הַדָּבָר֙ בְּעֵינֵ֣י דָוִ֔ד לְהִתְחַתֵּ֖ן בַּמֶּ֑לֶךְ וְלֹ֥א מָלְא֖וּ הַיָּמִֽים'),
(7704, 9, 'WLC', 'WLC', 'he', '1SA', 18, 27, 'OT', 'וַיָּ֨קָם דָּוִ֜ד וַיֵּ֣לֶךְ ה֣וּא וַאֲנָשָׁ֗יו וַיַּ֣ךְ בַּפְּלִשְׁתִּים֮ מָאתַ֣יִם אִישׁ֒ וַיָּבֵ֤א דָוִד֙ אֶת עָרְלֹ֣תֵיהֶ֔ם וַיְמַלְא֣וּם לַמֶּ֔לֶךְ לְהִתְחַתֵּ֖ן בַּמֶּ֑לֶךְ וַיִּתֶּן ל֥וֹ שָׁא֛וּל אֶת מִיכַ֥ל בִּתּ֖וֹ לְאִשָּֽׁה'),
(7705, 9, 'WLC', 'WLC', 'he', '1SA', 18, 28, 'OT', 'וַיַּ֤רְא שָׁאוּל֙ וַיֵּ֔דַע כִּ֥י יְהוָ֖ה עִם דָּוִ֑ד וּמִיכַ֥ל בַּת שָׁא֖וּל אֲהֵבַֽתְהוּ'),
(7706, 9, 'WLC', 'WLC', 'he', '1SA', 18, 29, 'OT', 'וַיֹּ֣אסֶף שָׁא֗וּל לֵרֹ֛א מִפְּנֵ֥י דָוִ֖ד ע֑וֹד וַיְהִ֥י שָׁא֛וּל אֹיֵ֥ב אֶת דָּוִ֖ד כָּל הַיָּמִֽים'),
(7707, 9, 'WLC', 'WLC', 'he', '1SA', 18, 30, 'OT', 'וַיֵּצְא֖וּ שָׂרֵ֣י פְלִשְׁתִּ֑ים וַיְהִ֣י מִדֵּ֣י צֵאתָ֗ם שָׂכַ֤ל דָּוִד֙ מִכֹּל֙ עַבְדֵ֣י שָׁא֔וּל וַיִּיקַ֥ר שְׁמ֖וֹ מְאֹֽד'),
(7708, 9, 'WLC', 'WLC', 'he', '1SA', 19, 1, 'OT', 'וַיְדַבֵּ֣ר שָׁא֗וּל אֶל יוֹנָתָ֤ן בְּנוֹ֙ וְאֶל כָּל עֲבָדָ֔יו לְהָמִ֖ית אֶת דָּוִ֑ד וִיהֽוֹנָתָן֙ בֶּן שָׁא֔וּל חָפֵ֥ץ בְּדָוִ֖ד מְאֹֽד'),
(7709, 9, 'WLC', 'WLC', 'he', '1SA', 19, 2, 'OT', 'וַיַּגֵּ֤ד יְהוֹנָתָן֙ לְדָוִ֣ד לֵאמֹ֔ר מְבַקֵּ֛שׁ שָׁא֥וּל אָבִ֖י לַהֲמִיתֶ֑ךָ וְעַתָּה֙ הִשָּֽׁמֶר נָ֣א בַבֹּ֔קֶר וְיָשַׁבְתָּ֥ בַסֵּ֖תֶר וְנַחְבֵּֽאתָ'),
(7710, 9, 'WLC', 'WLC', 'he', '1SA', 19, 3, 'OT', 'וַאֲנִ֨י אֵצֵ֜א וְעָמַדְתִּ֣י לְיַד אָבִ֗י בַּשָּׂדֶה֙ אֲשֶׁ֣ר אַתָּ֣ה שָׁ֔ם וַאֲנִ֕י אֲדַבֵּ֥ר בְּךָ֖ אֶל אָבִ֑י וְרָאִ֥יתִי מָ֖ה וְהִגַּ֥דְתִּי לָֽךְ'),
(7711, 9, 'WLC', 'WLC', 'he', '1SA', 19, 4, 'OT', 'וַיְדַבֵּ֨ר יְהוֹנָתָ֤ן בְּדָוִד֙ ט֔וֹב אֶל שָׁא֖וּל אָבִ֑יו וַיֹּ֣אמֶר אֵ֠לָיו אַל יֶחֱטָ֨א הַמֶּ֜לֶךְ בְּעַבְדּ֣וֹ בְדָוִ֗ד כִּ֣י ל֤וֹא חָטָא֙ לָ֔ךְ וְכִ֥י מַעֲשָׂ֖יו טוֹב לְךָ֥ מְאֹֽד'),
(7712, 9, 'WLC', 'WLC', 'he', '1SA', 19, 5, 'OT', 'וַיָּשֶׂם֩ אֶת נַפְשׁ֨וֹ בְכַפּ֜וֹ וַיַּ֣ךְ אֶת הַפְּלִשְׁתִּ֗י וַיַּ֨עַשׂ יְהוָ֜ה תְּשׁוּעָ֤ה גְדוֹלָה֙ לְכָל יִשְׂרָאֵ֔ל רָאִ֖יתָ וַתִּשְׂמָ֑ח וְלָ֤מָּה תֶֽחֱטָא֙ בְּדָ֣ם נָקִ֔י לְהָמִ֥ית אֶת דָּוִ֖ד חִנָּֽם'),
(7713, 9, 'WLC', 'WLC', 'he', '1SA', 19, 6, 'OT', 'וַיִּשְׁמַ֥ע שָׁא֖וּל בְּק֣וֹל יְהוֹנָתָ֑ן וַיִּשָּׁבַ֣ע שָׁא֔וּל חַי יְהוָ֖ה אִם יוּמָֽת'),
(7714, 9, 'WLC', 'WLC', 'he', '1SA', 19, 7, 'OT', 'וַיִּקְרָ֤א יְהוֹנָתָן֙ לְדָוִ֔ד וַיַּגֶּד לוֹ֙ יְה֣וֹנָתָ֔ן אֵ֥ת כָּל הַדְּבָרִ֖ים הָאֵ֑לֶּה וַיָּבֵ֨א יְהוֹנָתָ֤ן אֶת דָּוִד֙ אֶל שָׁא֔וּל וַיְהִ֥י לְפָנָ֖יו כְּאֶתְמ֥וֹל שִׁלְשֽׁוֹם'),
(7715, 9, 'WLC', 'WLC', 'he', '1SA', 19, 8, 'OT', 'וַתּ֥וֹסֶף הַמִּלְחָמָ֖ה לִֽהְי֑וֹת וַיֵּצֵ֨א דָוִ֜ד וַיִּלָּ֣חֶם בַּפְּלִשְׁתִּ֗ים וַיַּ֤ךְ בָּהֶם֙ מַכָּ֣ה גְדוֹלָ֔ה וַיָּנֻ֖סוּ מִפָּנָֽיו'),
(7716, 9, 'WLC', 'WLC', 'he', '1SA', 19, 9, 'OT', 'וַתְּהִי֩ ר֨וּחַ יְהוָ֤ה רָעָה֙ אֶל שָׁא֔וּל וְהוּא֙ בְּבֵית֣וֹ יוֹשֵׁ֔ב וַחֲנִית֖וֹ בְּיָד֑וֹ וְדָוִ֖ד מְנַגֵּ֥ן בְּיָֽד'),
(7717, 9, 'WLC', 'WLC', 'he', '1SA', 19, 10, 'OT', 'וַיְבַקֵּ֨שׁ שָׁא֜וּל לְהַכּ֤וֹת בַּֽחֲנִית֙ בְּדָוִ֣ד וּבַקִּ֔יר וַיִּפְטַר֙ מִפְּנֵ֣י שָׁא֔וּל וַיַּ֥ךְ אֶֽת הַחֲנִ֖ית בַּקִּ֑יר וְדָוִ֛ד נָ֥ס וַיִּמָּלֵ֖ט בַּלַּ֥יְלָה הֽוּא'),
(7718, 9, 'WLC', 'WLC', 'he', '1SA', 19, 11, 'OT', 'וַיִּשְׁלַח֩ שָׁא֨וּל מַלְאָכִ֜ים אֶל בֵּ֤ית דָּוִד֙ לְשָׁמְר֔וֹ וְלַהֲמִית֖וֹ בַּבֹּ֑קֶר וַתַּגֵּ֣ד לְדָוִ֗ד מִיכַ֤ל אִשְׁתּוֹ֙ לֵאמֹ֔ר אִם אֵ֨ינְךָ֜ מְמַלֵּ֤ט אֶֽת נַפְשְׁךָ֙ הַלַּ֔יְלָה מָחָ֖ר אַתָּ֥ה מוּמָֽת'),
(7719, 9, 'WLC', 'WLC', 'he', '1SA', 19, 12, 'OT', 'וַתֹּ֧רֶד מִיכַ֛ל אֶת דָּוִ֖ד בְּעַ֣ד הַחַלּ֑וֹן וַיֵּ֥לֶךְ וַיִּבְרַ֖ח וַיִּמָּלֵֽט'),
(7720, 9, 'WLC', 'WLC', 'he', '1SA', 19, 13, 'OT', 'וַתִּקַּ֨ח מִיכַ֜ל אֶת הַתְּרָפִ֗ים וַתָּ֨שֶׂם֙ אֶל הַמִּטָּ֔ה וְאֵת֙ כְּבִ֣יר הָֽעִזִּ֔ים שָׂ֖מָה מְרַֽאֲשֹׁתָ֑יו וַתְּכַ֖ס בַּבָּֽגֶד'),
(7721, 9, 'WLC', 'WLC', 'he', '1SA', 19, 14, 'OT', 'וַיִּשְׁלַ֥ח שָׁא֛וּל מַלְאָכִ֖ים לָקַ֣חַת אֶת דָּוִ֑ד וַתֹּ֖אמֶר חֹלֶ֥ה הֽוּא'),
(7722, 9, 'WLC', 'WLC', 'he', '1SA', 19, 15, 'OT', 'וַיִּשְׁלַ֤ח שָׁאוּל֙ אֶת הַמַּלְאָכִ֔ים לִרְא֥וֹת אֶת דָּוִ֖ד לֵאמֹ֑ר הַעֲל֨וּ אֹת֧וֹ בַמִּטָּ֛ה אֵלַ֖י לַהֲמִתֽוֹ'),
(7723, 9, 'WLC', 'WLC', 'he', '1SA', 19, 16, 'OT', 'וַיָּבֹ֨אוּ֙ הַמַּלְאָכִ֔ים וְהִנֵּ֥ה הַתְּרָפִ֖ים אֶל הַמִּטָּ֑ה וּכְבִ֥יר הָעִזִּ֖ים מְרַאֲשֹׁתָֽיו'),
(7724, 9, 'WLC', 'WLC', 'he', '1SA', 19, 17, 'OT', 'וַיֹּ֨אמֶר שָׁא֜וּל אֶל מִיכַ֗ל לָ֤מָּה כָּ֨כָה֙ רִמִּיתִ֔נִי וַתְּשַׁלְּחִ֥י אֶת אֹיְבִ֖י וַיִּמָּלֵ֑ט וַתֹּ֤אמֶר מִיכַל֙ אֶל שָׁא֔וּל הוּא אָמַ֥ר אֵלַ֛י שַׁלְּחִ֖נִי לָמָ֥ה אֲמִיתֵֽךְ'),
(7725, 9, 'WLC', 'WLC', 'he', '1SA', 19, 18, 'OT', 'וְדָוִ֨ד בָּרַ֜ח וַיִּמָּלֵ֗ט וַיָּבֹ֤א אֶל שְׁמוּאֵל֙ הָרָמָ֔תָה וַיַּ֨גֶּד ל֔וֹ אֵ֛ת כָּל אֲשֶׁ֥ר עָֽשָׂה ל֖וֹ שָׁא֑וּל וַיֵּ֤לֶךְ הוּא֙ וּשְׁמוּאֵ֔ל וַיֵּשְׁב֖וּ בנוית'),
(7726, 9, 'WLC', 'WLC', 'he', '1SA', 19, 19, 'OT', 'וַיֻּגַּ֥ד לְשָׁא֖וּל לֵאמֹ֑ר הִנֵּ֣ה דָוִ֔ד בנוית בָּרָמָֽה'),
(7727, 9, 'WLC', 'WLC', 'he', '1SA', 19, 20, 'OT', 'וַיִּשְׁלַ֨ח שָׁא֣וּל מַלְאָכִים֮ לָקַ֣חַת אֶת דָּוִד֒ וַיַּ֗רְא אֶֽת לַהֲקַ֤ת הַנְּבִיאִים֙ נִבְּאִ֔ים וּשְׁמוּאֵ֕ל עֹמֵ֥ד נִצָּ֖ב עֲלֵיהֶ֑ם וַתְּהִ֞י עַֽל מַלְאֲכֵ֤י שָׁאוּל֙ ר֣וּחַ אֱלֹהִ֔ים וַיִּֽתְנַבְּא֖וּ גַּם הֵֽמָּה'),
(7728, 9, 'WLC', 'WLC', 'he', '1SA', 19, 21, 'OT', 'וַיַּגִּ֣דוּ לְשָׁא֗וּל וַיִּשְׁלַח֙ מַלְאָכִ֣ים אֲחֵרִ֔ים וַיִּֽתְנַבְּא֖וּ גַּם הֵ֑מָּה וַיֹּ֣סֶף שָׁא֗וּל וַיִּשְׁלַח֙ מַלְאָכִ֣ים שְׁלִשִׁ֔ים וַיִּֽתְנַבְּא֖וּ גַּם הֵֽמָּה'),
(7729, 9, 'WLC', 'WLC', 'he', '1SA', 19, 22, 'OT', 'וַיֵּ֨לֶךְ גַּם ה֜וּא הָרָמָ֗תָה וַיָּבֹא֙ עַד בּ֤וֹר הַגָּדוֹל֙ אֲשֶׁ֣ר בַּשֶּׂ֔כוּ וַיִּשְׁאַ֣ל וַיֹּ֔אמֶר אֵיפֹ֥ה שְׁמוּאֵ֖ל וְדָוִ֑ד וַיֹּ֕אמֶר הִנֵּ֖ה בנוית בָּרָמָֽה'),
(7730, 9, 'WLC', 'WLC', 'he', '1SA', 19, 23, 'OT', 'וַיֵּ֣לֶךְ שָׁ֔ם אֶל נוית בָּרָמָ֑ה וַתְּהִי֩ עָלָ֨יו גַּם ה֜וּא ר֣וּחַ אֱלֹהִ֗ים וַיֵּ֤לֶךְ הָלוֹךְ֙ וַיִּתְנַבֵּ֔א עַד בֹּא֖וֹ בנוית בָּרָמָֽה'),
(7731, 9, 'WLC', 'WLC', 'he', '1SA', 19, 24, 'OT', 'וַיִּפְשַׁ֨ט גַּם ה֜וּא בְּגָדָ֗יו וַיִּתְנַבֵּ֤א גַם הוּא֙ לִפְנֵ֣י שְׁמוּאֵ֔ל וַיִּפֹּ֣ל עָרֹ֔ם כָּל הַיּ֥וֹם הַה֖וּא וְכָל הַלָּ֑יְלָה עַל כֵּן֙ יֹֽאמְר֔וּ הֲגַ֥ם שָׁא֖וּל בַּנְּבִיאִֽם'),
(7732, 9, 'WLC', 'WLC', 'he', '1SA', 20, 1, 'OT', 'וַיִּבְרַ֣ח דָּוִ֔ד מנוות בָּרָמָ֑ה וַיָּבֹ֞א וַיֹּ֣אמֶר לִפְנֵ֣י יְהוֹנָתָ֗ן מֶ֤ה עָשִׂ֨יתִי֙ מֶֽה עֲוֺנִ֤י וּמֶֽה חַטָּאתִי֙ לִפְנֵ֣י אָבִ֔יךָ כִּ֥י מְבַקֵּ֖שׁ אֶת נַפְשִֽׁי'),
(7733, 9, 'WLC', 'WLC', 'he', '1SA', 20, 2, 'OT', 'וַיֹּ֨אמֶר ל֣וֹ חָלִילָה֮ לֹ֣א תָמוּת֒ הִנֵּ֡ה לו עשה אָבִ֜י דָּבָ֣ר גָּד֗וֹל א֚וֹ דָּבָ֣ר קָטֹ֔ן וְלֹ֥א יִגְלֶ֖ה אֶת אָזְנִ֑י וּמַדּוּעַ֩ יַסְתִּ֨יר אָבִ֥י מִמֶּ֛נִּי אֶת הַדָּבָ֥ר הַזֶּ֖ה אֵ֥ין זֹֽאת'),
(7734, 9, 'WLC', 'WLC', 'he', '1SA', 20, 3, 'OT', 'וַיִּשָּׁבַ֨ע ע֜וֹד דָּוִ֗ד וַיֹּ֨אמֶר֙ יָדֹ֨עַ יָדַ֜ע אָבִ֗יךָ כִּֽי מָצָ֤אתִי חֵן֙ בְּעֵינֶ֔יךָ וַיֹּ֛אמֶר אַל יֵֽדַע זֹ֥את יְהוֹנָתָ֖ן פֶּן יֵֽעָצֵ֑ב וְאוּלָ֗ם חַי יְהוָה֙ וְחֵ֣י נַפְשֶׁ֔ךָ כִּ֣י כְפֶ֔שַׂע בֵּינִ֖י וּבֵ֥ין הַמָּֽוֶת'),
(7735, 9, 'WLC', 'WLC', 'he', '1SA', 20, 4, 'OT', 'וַיֹּ֥אמֶר יְהוֹנָתָ֖ן אֶל דָּוִ֑ד מַה תֹּאמַ֥ר נַפְשְׁךָ֖ וְאֶֽעֱשֶׂה לָּֽךְ'),
(7736, 9, 'WLC', 'WLC', 'he', '1SA', 20, 5, 'OT', 'וַיֹּ֨אמֶר דָּוִ֜ד אֶל יְהוֹנָתָ֗ן הִֽנֵּה חֹ֨דֶשׁ֙ מָחָ֔ר וְאָנֹכִ֛י יָשֹׁב אֵשֵׁ֥ב עִם הַמֶּ֖לֶךְ לֶאֱכ֑וֹל וְשִׁלַּחְתַּ֨נִי֙ וְנִסְתַּרְתִּ֣י בַשָּׂדֶ֔ה עַ֖ד הָעֶ֥רֶב הַשְּׁלִשִֽׁית'),
(7737, 9, 'WLC', 'WLC', 'he', '1SA', 20, 6, 'OT', 'אִם פָּקֹ֥ד יִפְקְדֵ֖נִי אָבִ֑יךָ וְאָמַרְתָּ֗ נִשְׁאֹל֩ נִשְׁאַ֨ל מִמֶּ֤נִּי דָוִד֙ לָרוּץ֙ בֵּֽית לֶ֣חֶם עִיר֔וֹ כִּ֣י זֶ֧בַח הַיָּמִ֛ים שָׁ֖ם לְכָל הַמִּשְׁפָּחָֽה'),
(7738, 9, 'WLC', 'WLC', 'he', '1SA', 20, 7, 'OT', 'אִם כֹּ֥ה יֹאמַ֛ר ט֖וֹב שָׁל֣וֹם לְעַבְדֶּ֑ךָ וְאִם חָרֹ֤ה יֶֽחֱרֶה֙ ל֔וֹ דַּ֕ע כִּֽי כָלְתָ֥ה הָרָעָ֖ה מֵעִמּֽוֹ'),
(7739, 9, 'WLC', 'WLC', 'he', '1SA', 20, 8, 'OT', 'וְעָשִׂ֤יתָ חֶ֨סֶד֙ עַל עַבְדֶּ֔ךָ כִּ֚י בִּבְרִ֣ית יְהוָ֔ה הֵבֵ֥אתָ אֶֽת עַבְדְּךָ֖ עִמָּ֑ךְ וְאִם יֶשׁ בִּ֤י עָוֺן֙ הֲמִיתֵ֣נִי אַ֔תָּה וְעַד אָבִ֖יךָ לָמָּה זֶּ֥ה תְבִיאֵֽנִי'),
(7740, 9, 'WLC', 'WLC', 'he', '1SA', 20, 9, 'OT', 'וַיֹּ֥אמֶר יְהוֹנָתָ֖ן חָלִ֣ילָה לָּ֑ךְ כִּ֣י אִם יָדֹ֣עַ אֵדַ֗ע כִּֽי כָלְתָ֨ה הָרָעָ֜ה מֵעִ֤ם אָבִי֙ לָב֣וֹא עָלֶ֔יךָ וְלֹ֥א אֹתָ֖הּ אַגִּ֥יד לָֽךְ'),
(7741, 9, 'WLC', 'WLC', 'he', '1SA', 20, 10, 'OT', 'וַיֹּ֤אמֶר דָּוִד֙ אֶל יְה֣וֹנָתָ֔ן מִ֖י יַגִּ֣יד לִ֑י א֛וֹ מַה יַּעַנְךָ֥ אָבִ֖יךָ קָשָֽׁה'),
(7742, 9, 'WLC', 'WLC', 'he', '1SA', 20, 11, 'OT', 'וַיֹּ֤אמֶר יְהֽוֹנָתָן֙ אֶל דָּוִ֔ד לְכָ֖ה וְנֵצֵ֣א הַשָּׂדֶ֑ה וַיֵּצְא֥וּ שְׁנֵיהֶ֖ם הַשָּׂדֶֽה'),
(7743, 9, 'WLC', 'WLC', 'he', '1SA', 20, 12, 'OT', 'וַיֹּ֨אמֶר יְהוֹנָתָ֜ן אֶל דָּוִ֗ד יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ כִּֽי אֶחְקֹ֣ר אֶת אָבִ֗י כָּעֵ֤ת מָחָר֙ הַשְּׁלִשִׁ֔ית וְהִנֵּה ט֖וֹב אֶל דָּוִ֑ד וְלֹֽא אָז֙ אֶשְׁלַ֣ח אֵלֶ֔יךָ וְגָלִ֖יתִי אֶת אָזְנֶֽךָ'),
(7744, 9, 'WLC', 'WLC', 'he', '1SA', 20, 13, 'OT', 'כֹּֽה יַעֲשֶׂה֩ יְהוָ֨ה לִֽיהוֹנָתָ֜ן וְכֹ֣ה יֹסִ֗יף כִּֽי יֵיטִ֨ב אֶל אָבִ֤י אֶת הָֽרָעָה֙ עָלֶ֔יךָ וְגָלִ֨יתִי֙ אֶת אָזְנֶ֔ךָ וְשִׁלַּחְתִּ֖יךָ וְהָלַכְתָּ֣ לְשָׁל֑וֹם וִיהִ֤י יְהוָה֙ עִמָּ֔ךְ כַּאֲשֶׁ֥ר הָיָ֖ה עִם אָבִֽי'),
(7745, 9, 'WLC', 'WLC', 'he', '1SA', 20, 14, 'OT', 'וְלֹ֖א אִם עוֹדֶ֣נִּי חָ֑י וְלֹֽא תַעֲשֶׂ֧ה עִמָּדִ֛י חֶ֥סֶד יְהוָ֖ה וְלֹ֥א אָמֽוּת'),
(7746, 9, 'WLC', 'WLC', 'he', '1SA', 20, 15, 'OT', 'וְלֹֽא תַכְרִ֧ת אֶֽת חַסְדְּךָ֛ מֵעִ֥ם בֵּיתִ֖י עַד עוֹלָ֑ם וְלֹ֗א בְּהַכְרִ֤ת יְהוָה֙ אֶת אֹיְבֵ֣י דָוִ֔ד אִ֕ישׁ מֵעַ֖ל פְּנֵ֥י הָאֲדָמָֽה'),
(7747, 9, 'WLC', 'WLC', 'he', '1SA', 20, 16, 'OT', 'וַיִּכְרֹ֥ת יְהוֹנָתָ֖ן עִם בֵּ֣ית דָּוִ֑ד וּבִקֵּ֣שׁ יְהוָ֔ה מִיַּ֖ד אֹיְבֵ֥י דָוִֽד'),
(7748, 9, 'WLC', 'WLC', 'he', '1SA', 20, 17, 'OT', 'וַיּ֤וֹסֶף יְהֽוֹנָתָן֙ לְהַשְׁבִּ֣יעַ אֶת דָּוִ֔ד בְּאַהֲבָת֖וֹ אֹת֑וֹ כִּֽי אַהֲבַ֥ת נַפְשׁ֖וֹ אֲהֵבֽוֹ'),
(7749, 9, 'WLC', 'WLC', 'he', '1SA', 20, 18, 'OT', 'וַיֹּֽאמֶר ל֥וֹ יְהוֹנָתָ֖ן מָחָ֣ר חֹ֑דֶשׁ וְנִפְקַ֕דְתָּ כִּ֥י יִפָּקֵ֖ד מוֹשָׁבֶֽךָ'),
(7750, 9, 'WLC', 'WLC', 'he', '1SA', 20, 19, 'OT', 'וְשִׁלַּשְׁתָּ֙ תֵּרֵ֣ד מְאֹ֔ד וּבָאתָ֙ אֶל הַמָּק֔וֹם אֲשֶׁר נִסְתַּ֥רְתָּ שָּׁ֖ם בְּי֣וֹם הַֽמַּעֲשֶׂ֑ה וְיָ֣שַׁבְתָּ֔ אֵ֖צֶל הָאֶ֥בֶן הָאָֽזֶל'),
(7751, 9, 'WLC', 'WLC', 'he', '1SA', 20, 20, 'OT', 'וַאֲנִ֕י שְׁלֹ֥שֶׁת הַחִצִּ֖ים צִדָּ֣ה אוֹרֶ֑ה לְשַֽׁלַּֽח לִ֖י לְמַטָּרָֽה'),
(7752, 9, 'WLC', 'WLC', 'he', '1SA', 20, 21, 'OT', 'וְהִנֵּה֙ אֶשְׁלַ֣ח אֶת הַנַּ֔עַר לֵ֖ךְ מְצָ֣א אֶת הַחִצִּ֑ים אִם אָמֹר֩ אֹמַ֨ר לַנַּ֜עַר הִנֵּ֥ה הַחִצִּ֣ים מִמְּךָ֣ וָהֵ֗נָּה קָחֶ֧נּוּ וָבֹ֛אָה כִּֽי שָׁל֥וֹם לְךָ֛ וְאֵ֥ין דָּבָ֖ר חַי יְהוָֽה'),
(7753, 9, 'WLC', 'WLC', 'he', '1SA', 20, 22, 'OT', 'וְאִם כֹּ֤ה אֹמַר֙ לָעֶ֔לֶם הִנֵּ֥ה הַחִצִּ֖ים מִמְּךָ֣ וָהָ֑לְאָה לֵ֕ךְ כִּ֥י שִֽׁלַּחֲךָ֖ יְהוָֽה'),
(7754, 9, 'WLC', 'WLC', 'he', '1SA', 20, 23, 'OT', 'וְהַ֨דָּבָ֔ר אֲשֶׁ֥ר דִּבַּ֖רְנוּ אֲנִ֣י וָאָ֑תָּה הִנֵּ֧ה יְהוָ֛ה בֵּינִ֥י וּבֵינְךָ֖ עַד עוֹלָֽם'),
(7755, 9, 'WLC', 'WLC', 'he', '1SA', 20, 24, 'OT', 'וַיִּסָּתֵ֥ר דָּוִ֖ד בַּשָּׂדֶ֑ה וַיְהִ֣י הַחֹ֔דֶשׁ וַיֵּ֧שֶׁב הַמֶּ֛לֶךְ על הַלֶּ֖חֶם לֶאֱכֽוֹל'),
(7756, 9, 'WLC', 'WLC', 'he', '1SA', 20, 25, 'OT', 'וַיֵּ֣שֶׁב הַ֠מֶּלֶךְ עַל מ֨וֹשָׁב֜וֹ כְּפַ֣עַם בְּפַ֗עַם אֶל מוֹשַׁב֙ הַקִּ֔יר וַיָּ֨קָם֙ יְה֣וֹנָתָ֔ן וַיֵּ֥שֶׁב אַבְנֵ֖ר מִצַּ֣ד שָׁא֑וּל וַיִּפָּקֵ֖ד מְק֥וֹם דָּוִֽד'),
(7757, 9, 'WLC', 'WLC', 'he', '1SA', 20, 26, 'OT', 'וְלֹֽא דִבֶּ֥ר שָׁא֛וּל מְא֖וּמָה בַּיּ֣וֹם הַה֑וּא כִּ֤י אָמַר֙ מִקְרֶ֣ה ה֔וּא בִּלְתִּ֥י טָה֛וֹר ה֖וּא כִּֽי לֹ֥א טָהֽוֹר'),
(7758, 9, 'WLC', 'WLC', 'he', '1SA', 20, 27, 'OT', 'וַיְהִ֗י מִֽמָּחֳרַ֤ת הַחֹ֨דֶשׁ֙ הַשֵּׁנִ֔י וַיִּפָּקֵ֖ד מְק֣וֹם דָּוִ֑ד וַיֹּ֤אמֶר שָׁאוּל֙ אֶל יְהוֹנָתָ֣ן בְּנ֔וֹ מַדּ֜וּעַ לֹא בָ֧א בֶן יִשַׁ֛י גַּם תְּמ֥וֹל גַּם הַיּ֖וֹם אֶל הַלָּֽחֶם'),
(7759, 9, 'WLC', 'WLC', 'he', '1SA', 20, 28, 'OT', 'וַיַּ֥עַן יְהוֹנָתָ֖ן אֶת שָׁא֑וּל נִשְׁאֹ֨ל נִשְׁאַ֥ל דָּוִ֛ד מֵעִמָּדִ֖י עַד בֵּ֥ית לָֽחֶם'),
(7760, 9, 'WLC', 'WLC', 'he', '1SA', 20, 29, 'OT', 'וַיֹּ֡אמֶר שַׁלְּחֵ֣נִי נָ֡א כִּ֣י זֶבַח֩ מִשְׁפָּחָ֨ה לָ֜נוּ בָּעִ֗יר וְה֤וּא צִוָּֽה לִי֙ אָחִ֔י וְעַתָּ֗ה אִם מָצָ֤אתִי חֵן֙ בְּעֵינֶ֔יךָ אִמָּ֥לְטָה נָּ֖א וְאֶרְאֶ֣ה אֶת אֶחָ֑י עַל כֵּ֣ן לֹא בָ֔א אֶל שֻׁלְחַ֖ן הַמֶּֽלֶךְ'),
