(7970, 9, 'WLC', 'WLC', 'he', '1SA', 29, 2, 'OT', 'וְסַרְנֵ֤י פְלִשְׁתִּים֙ עֹֽבְרִ֔ים לְמֵא֖וֹת וְלַאֲלָפִ֑ים וְדָוִ֣ד וַאֲנָשָׁ֗יו עֹֽבְרִ֛ים בָּאַחֲרֹנָ֖ה עִם אָכִֽישׁ'),
(7971, 9, 'WLC', 'WLC', 'he', '1SA', 29, 3, 'OT', 'וַיֹּֽאמְרוּ֙ שָׂרֵ֣י פְלִשְׁתִּ֔ים מָ֖ה הָעִבְרִ֣ים הָאֵ֑לֶּה וַיֹּ֨אמֶר אָכִ֜ישׁ אֶל שָׂרֵ֣י פְלִשְׁתִּ֗ים הֲלֽוֹא זֶ֨ה דָוִ֜ד עֶ֣בֶד שָׁא֣וּל מֶֽלֶךְ יִשְׂרָאֵ֗ל אֲשֶׁ֨ר הָיָ֤ה אִתִּי֙ זֶ֤ה יָמִים֙ אוֹ זֶ֣ה שָׁנִ֔ים וְלֹֽא מָצָ֤אתִי בוֹ֙ מְא֔וּמָה מִיּ֥וֹם נָפְל֖וֹ עַד הַיּ֥וֹם הַזֶּֽה'),
(7972, 9, 'WLC', 'WLC', 'he', '1SA', 29, 4, 'OT', 'וַיִּקְצְפ֨וּ עָלָ֜יו שָׂרֵ֣י פְלִשְׁתִּ֗ים וַיֹּ֣אמְרוּ לוֹ֩ שָׂרֵ֨י פְלִשְׁתִּ֜ים הָשֵׁ֣ב אֶת הָאִ֗ישׁ וְיָשֹׁב֙ אֶל מְקוֹמוֹ֙ אֲשֶׁ֣ר הִפְקַדְתּ֣וֹ שָׁ֔ם וְלֹֽא יֵרֵ֤ד עִמָּ֨נוּ֙ בַּמִּלְחָמָ֔ה וְלֹא יִֽהְיֶה לָּ֥נוּ לְשָׂטָ֖ן בַּמִּלְחָמָ֑ה וּבַמֶּ֗ה יִתְרַצֶּ֥ה זֶה֙ אֶל אֲדֹנָ֔יו הֲל֕וֹא בְּרָאשֵׁ֖י הָאֲנָשִׁ֥ים הָהֵֽם'),
(7973, 9, 'WLC', 'WLC', 'he', '1SA', 29, 5, 'OT', 'הֲלוֹא זֶ֣ה דָוִ֔ד אֲשֶׁ֧ר יַעֲנוּ ל֛וֹ בַּמְּחֹל֖וֹת לֵאמֹ֑ר הִכָּ֤ה שָׁאוּל֙ בַּֽאֲלָפָ֔יו וְדָוִ֖ד ברבבתו'),
(7974, 9, 'WLC', 'WLC', 'he', '1SA', 29, 6, 'OT', 'וַיִּקְרָ֨א אָכִ֜ישׁ אֶל דָּוִ֗ד וַיֹּ֣אמֶר אֵ֠לָיו חַי יְהוָ֞ה כִּי יָשָׁ֣ר אַתָּ֗ה וְט֣וֹב בְּ֠עֵינַי צֵאתְךָ֨ וּבֹאֲךָ֤ אִתִּי֙ בַּֽמַּחֲנֶ֔ה כִּ֠י לֹֽא מָצָ֤אתִֽי בְךָ֙ רָעָ֔ה מִיּ֛וֹם בֹּאֲךָ֥ אֵלַ֖י עַד הַיּ֣וֹם הַזֶּ֑ה וּבְעֵינֵ֥י הַסְּרָנִ֖ים לֹֽא ט֥וֹב אָֽתָּה'),
(7975, 9, 'WLC', 'WLC', 'he', '1SA', 29, 7, 'OT', 'וְעַתָּ֥ה שׁ֖וּב וְלֵ֣ךְ בְּשָׁל֑וֹם וְלֹֽא תַעֲשֶׂ֣ה רָ֔ע בְּעֵינֵ֖י סַרְנֵ֥י פְלִשְׁתִּֽים'),
(7976, 9, 'WLC', 'WLC', 'he', '1SA', 29, 8, 'OT', 'וַיֹּ֨אמֶר דָּוִ֜ד אֶל אָכִ֗ישׁ כִּ֣י מֶ֤ה עָשִׂ֨יתִי֙ וּמַה מָּצָ֣אתָ בְעַבְדְּךָ֔ מִיּוֹם֙ אֲשֶׁ֣ר הָיִ֣יתִי לְפָנֶ֔יךָ עַ֖ד הַיּ֣וֹם הַזֶּ֑ה כִּ֣י לֹ֤א אָבוֹא֙ וְנִלְחַ֔מְתִּי בְּאֹיְבֵ֖י אֲדֹנִ֥י הַמֶּֽלֶךְ'),
(7977, 9, 'WLC', 'WLC', 'he', '1SA', 29, 9, 'OT', 'וַיַּ֣עַן אָכִישׁ֮ וַיֹּ֣אמֶר אֶל דָּוִד֒ יָדַ֕עְתִּי כִּ֣י ט֥וֹב אַתָּ֛ה בְּעֵינַ֖י כְּמַלְאַ֣ךְ אֱלֹהִ֑ים אַ֣ךְ שָׂרֵ֤י פְלִשְׁתִּים֙ אָֽמְר֔וּ לֹֽא יַעֲלֶ֥ה עִמָּ֖נוּ בַּמִּלְחָמָֽה'),
(7978, 9, 'WLC', 'WLC', 'he', '1SA', 29, 10, 'OT', 'וְעַתָּה֙ הַשְׁכֵּ֣ם בַּבֹּ֔קֶר וְעַבְדֵ֥י אֲדֹנֶ֖יךָ אֲשֶׁר בָּ֣אוּ אִתָּ֑ךְ וְהִשְׁכַּמְתֶּ֣ם בַּבֹּ֔קֶר וְא֥וֹר לָכֶ֖ם וָלֵֽכוּ'),
(7979, 9, 'WLC', 'WLC', 'he', '1SA', 29, 11, 'OT', 'וַיַּשְׁכֵּ֨ם דָּוִ֜ד ה֤וּא וַֽאֲנָשָׁיו֙ לָלֶ֣כֶת בַּבֹּ֔קֶר לָשׁ֖וּב אֶל אֶ֣רֶץ פְּלִשְׁתִּ֑ים וּפְלִשְׁתִּ֖ים עָל֥וּ יִזְרְעֶֽאל'),
(7980, 9, 'WLC', 'WLC', 'he', '1SA', 30, 1, 'OT', 'וַיְהִ֞י בְּבֹ֨א דָוִ֧ד וַאֲנָשָׁ֛יו צִֽקְלַ֖ג בַּיּ֣וֹם הַשְּׁלִישִׁ֑י וַעֲמָלֵקִ֣י פָֽשְׁט֗וּ אֶל נֶ֨גֶב֙ וְאֶל צִ֣קְלַ֔ג וַיַּכּוּ֙ אֶת צִ֣קְלַ֔ג וַיִּשְׂרְפ֥וּ אֹתָ֖הּ בָּאֵֽשׁ'),
(7981, 9, 'WLC', 'WLC', 'he', '1SA', 30, 2, 'OT', 'וַיִּשְׁבּ֨וּ אֶת הַנָּשִׁ֤ים אֲשֶׁר בָּהּ֙ מִקָּטֹ֣ן וְעַד גָּד֔וֹל לֹ֥א הֵמִ֖יתוּ אִ֑ישׁ וַיִּֽנְהֲג֔וּ וַיֵּלְכ֖וּ לְדַרְכָּֽם'),
(7982, 9, 'WLC', 'WLC', 'he', '1SA', 30, 3, 'OT', 'וַיָּבֹ֨א דָוִ֤ד וַֽאֲנָשָׁיו֙ אֶל הָעִ֔יר וְהִנֵּ֥ה שְׂרוּפָ֖ה בָּאֵ֑שׁ וּנְשֵׁיהֶ֛ם וּבְנֵיהֶ֥ם וּבְנֹתֵיהֶ֖ם נִשְׁבּֽוּ'),
(7983, 9, 'WLC', 'WLC', 'he', '1SA', 30, 4, 'OT', 'וַיִּשָּׂ֨א דָוִ֜ד וְהָעָ֧ם אֲשֶׁר אִתּ֛וֹ אֶת קוֹלָ֖ם וַיִּבְכּ֑וּ עַ֣ד אֲשֶׁ֧ר אֵין בָּהֶ֛ם כֹּ֖חַ לִבְכּֽוֹת'),
(7984, 9, 'WLC', 'WLC', 'he', '1SA', 30, 5, 'OT', 'וּשְׁתֵּ֥י נְשֵֽׁי דָוִ֖ד נִשְׁבּ֑וּ אֲחִינֹ֨עַם֙ הַיִּזְרְעֵלִ֔ית וַאֲבִיגַ֕יִל אֵ֖שֶׁת נָבָ֥ל הַֽכַּרְמְלִֽי'),
(7985, 9, 'WLC', 'WLC', 'he', '1SA', 30, 6, 'OT', 'וַתֵּ֨צֶר לְדָוִ֜ד מְאֹ֗ד כִּֽי אָמְר֤וּ הָעָם֙ לְסָקְל֔וֹ כִּֽי מָ֨רָה֙ נֶ֣פֶשׁ כָּל הָעָ֔ם אִ֖ישׁ עַל בנו וְעַל בְּנֹתָ֑יו וַיִּתְחַזֵּ֣ק דָּוִ֔ד בַּיהוָ֖ה אֱלֹהָֽיו'),
(7986, 9, 'WLC', 'WLC', 'he', '1SA', 30, 7, 'OT', 'וַיֹּ֣אמֶר דָּוִ֗ד אֶל אֶבְיָתָ֤ר הַכֹּהֵן֙ בֶּן אֲחִימֶ֔לֶךְ הַגִּֽישָׁה נָּ֥א לִ֖י הָאֵפֹ֑ד וַיַּגֵּ֧שׁ אֶבְיָתָ֛ר אֶת הָאֵפֹ֖ד אֶל דָּוִֽד'),
(7987, 9, 'WLC', 'WLC', 'he', '1SA', 30, 8, 'OT', 'וַיִּשְׁאַ֨ל דָּוִ֤ד בַּֽיהוָה֙ לֵאמֹ֔ר אֶרְדֹּ֛ף אַחֲרֵ֥י הַגְּדוּד הַזֶּ֖ה הַֽאַשִּׂגֶ֑נּוּ וַיֹּ֤אמֶר לוֹ֙ רְדֹ֔ף כִּֽי הַשֵּׂ֥ג תַּשִּׂ֖יג וְהַצֵּ֥ל תַּצִּֽיל'),
(7988, 9, 'WLC', 'WLC', 'he', '1SA', 30, 9, 'OT', 'וַיֵּ֣לֶךְ דָּוִ֗ד ה֚וּא וְשֵׁשׁ מֵא֥וֹת אִישׁ֙ אֲשֶׁ֣ר אִתּ֔וֹ וַיָּבֹ֖אוּ עַד נַ֣חַל הַבְּשׂ֑וֹר וְהַנּֽוֹתָרִ֖ים עָמָֽדוּ'),
(7989, 9, 'WLC', 'WLC', 'he', '1SA', 30, 10, 'OT', 'וַיִּרְדֹּ֣ף דָּוִ֔ד ה֖וּא וְאַרְבַּע מֵא֣וֹת אִ֑ישׁ וַיַּֽעַמְדוּ֙ מָאתַ֣יִם אִ֔ישׁ אֲשֶׁ֣ר פִּגְּר֔וּ מֵעֲבֹ֖ר אֶת נַ֥חַל הַבְּשֽׂוֹר'),
(7990, 9, 'WLC', 'WLC', 'he', '1SA', 30, 11, 'OT', 'וַֽיִּמְצְא֤וּ אִישׁ מִצְרִי֙ בַּשָּׂדֶ֔ה וַיִּקְח֥וּ אֹת֖וֹ אֶל דָּוִ֑ד וַיִּתְּנוּ ל֥וֹ לֶ֨חֶם֙ וַיֹּ֔אכַל וַיַּשְׁקֻ֖הוּ מָֽיִם'),
(7991, 9, 'WLC', 'WLC', 'he', '1SA', 30, 12, 'OT', 'וַיִּתְּנוּ לוֹ֩ פֶ֨לַח דְּבֵלָ֜ה וּשְׁנֵ֤י צִמֻּקִים֙ וַיֹּ֔אכַל וַתָּ֥שָׁב רוּח֖וֹ אֵלָ֑יו כִּ֠י לֹֽא אָ֤כַל לֶ֨חֶם֙ וְלֹא שָׁ֣תָה מַ֔יִם שְׁלֹשָׁ֥ה יָמִ֖ים וּשְׁלֹשָׁ֥ה לֵילֽוֹת'),
(7992, 9, 'WLC', 'WLC', 'he', '1SA', 30, 13, 'OT', 'וַיֹּ֨אמֶר ל֤וֹ דָוִד֙ לְֽמִי אַ֔תָּה וְאֵ֥י מִזֶּ֖ה אָ֑תָּה וַיֹּ֜אמֶר נַ֧עַר מִצְרִ֣י אָנֹ֗כִי עֶ֚בֶד לְאִ֣ישׁ עֲמָֽלֵקִ֔י וַיַּעַזְבֵ֧נִי אֲדֹנִ֛י כִּ֥י חָלִ֖יתִי הַיּ֥וֹם שְׁלֹשָֽׁה'),
(7993, 9, 'WLC', 'WLC', 'he', '1SA', 30, 14, 'OT', 'אֲנַ֡חְנוּ פָּשַׁ֜טְנוּ נֶ֧גֶב הַכְּרֵתִ֛י וְעַל אֲשֶׁ֥ר לִֽיהוּדָ֖ה וְעַל נֶ֣גֶב כָּלֵ֑ב וְאֶת צִקְלַ֖ג שָׂרַ֥פְנוּ בָאֵֽשׁ'),
(7994, 9, 'WLC', 'WLC', 'he', '1SA', 30, 15, 'OT', 'וַיֹּ֤אמֶר אֵלָיו֙ דָּוִ֔ד הֲתוֹרִדֵ֖נִי אֶל הַגְּד֣וּד הַזֶּ֑ה וַיֹּ֡אמֶר הִשָּׁבְעָה֩ לִּ֨י בֵֽאלֹהִ֜ים אִם תְּמִיתֵ֗נִי וְאִם תַּסְגִּרֵ֨נִי֙ בְּיַד אֲדֹנִ֔י וְאוֹרִֽדְךָ֖ אֶל הַגְּד֥וּד הַזֶּֽה'),
(7995, 9, 'WLC', 'WLC', 'he', '1SA', 30, 16, 'OT', 'וַיֹּ֣רִדֵ֔הוּ וְהִנֵּ֥ה נְטֻשִׁ֖ים עַל פְּנֵ֣י כָל הָאָ֑רֶץ אֹכְלִ֤ים וְשֹׁתִים֙ וְחֹ֣גְגִ֔ים בְּכֹל֙ הַשָּׁלָ֣ל הַגָּד֔וֹל אֲשֶׁ֥ר לָקְח֛וּ מֵאֶ֥רֶץ פְּלִשְׁתִּ֖ים וּמֵאֶ֥רֶץ יְהוּדָֽה'),
(7996, 9, 'WLC', 'WLC', 'he', '1SA', 30, 17, 'OT', 'וַיַּכֵּ֥ם דָּוִ֛ד מֵהַנֶּ֥שֶׁף וְעַד הָעֶ֖רֶב לְמָֽחֳרָתָ֑ם וְלֹֽא נִמְלַ֤ט מֵהֶם֙ אִ֔ישׁ כִּי֩ אִם אַרְבַּ֨ע מֵא֧וֹת אִֽישׁ נַ֛עַר אֲשֶׁר רָכְב֥וּ עַל הַגְּמַלִּ֖ים וַיָּנֻֽסוּ'),
(7997, 9, 'WLC', 'WLC', 'he', '1SA', 30, 18, 'OT', 'וַיַּצֵּ֣ל דָּוִ֔ד אֵ֛ת כָּל אֲשֶׁ֥ר לָקְח֖וּ עֲמָלֵ֑ק וְאֶת שְׁתֵּ֥י נָשָׁ֖יו הִצִּ֥יל דָּוִֽד'),
(7998, 9, 'WLC', 'WLC', 'he', '1SA', 30, 19, 'OT', 'וְלֹ֣א נֶעְדַּר לָ֠הֶם מִן הַקָּטֹ֨ן וְעַד הַגָּד֜וֹל וְעַד בָּנִ֤ים וּבָנוֹת֙ וּמִשָּׁלָ֔ל וְעַ֛ד כָּל אֲשֶׁ֥ר לָקְח֖וּ לָהֶ֑ם הַכֹּ֖ל הֵשִׁ֥יב דָּוִֽד'),
(7999, 9, 'WLC', 'WLC', 'he', '1SA', 30, 20, 'OT', 'וַיִּקַּ֣ח דָּוִ֔ד אֶת כָּל הַצֹּ֖אן וְהַבָּקָ֑ר נָהֲג֗וּ לִפְנֵי֙ הַמִּקְנֶ֣ה הַה֔וּא וַיֹּ֣אמְר֔וּ זֶ֖ה שְׁלַ֥ל דָּוִֽד'),
(8000, 9, 'WLC', 'WLC', 'he', '1SA', 30, 21, 'OT', 'וַיָּבֹ֣א דָוִ֗ד אֶל מָאתַ֨יִם הָאֲנָשִׁ֜ים אֲשֶֽׁר פִּגְּר֣וּ מִלֶּ֣כֶת אַחֲרֵ֣י דָוִ֗ד וַיֹּֽשִׁיבֻם֙ בְּנַ֣חַל הַבְּשׂ֔וֹר וַיֵּֽצְאוּ֙ לִקְרַ֣את דָּוִ֔ד וְלִקְרַ֖את הָעָ֣ם אֲשֶׁר אִתּ֑וֹ וַיִּגַּ֤שׁ דָּוִד֙ אֶת הָעָ֔ם וַיִּשְׁאַ֥ל לָהֶ֖ם לְשָׁלֽוֹם'),
(8001, 9, 'WLC', 'WLC', 'he', '1SA', 30, 22, 'OT', 'וַיַּ֜עַן כָּל אִֽישׁ רָ֣ע וּבְלִיַּ֗עַל מֵֽהָאֲנָשִׁים֮ אֲשֶׁ֣ר הָלְכ֣וּ עִם דָּוִד֒ וַיֹּאמְר֗וּ יַ֚עַן אֲשֶׁ֣ר לֹֽא הָלְכ֣וּ עִמִּ֔י לֹֽא נִתֵּ֣ן לָהֶ֔ם מֵהַשָּׁלָ֖ל אֲשֶׁ֣ר הִצַּ֑לְנוּ כִּֽי אִם אִ֤ישׁ אֶת אִשְׁתּוֹ֙ וְאֶת בָּנָ֔יו וְיִנְהֲג֖וּ וְיֵלֵֽכוּ'),
(8002, 9, 'WLC', 'WLC', 'he', '1SA', 30, 23, 'OT', 'וַיֹּ֣אמֶר דָּוִ֔ד לֹֽא תַעֲשׂ֥וּ כֵ֖ן אֶחָ֑י אֵ֠ת אֲשֶׁר נָתַ֨ן יְהוָ֥ה לָ֨נוּ֙ וַיִּשְׁמֹ֣ר אֹתָ֔נוּ וַיִּתֵּ֗ן אֶֽת הַגְּד֛וּד הַבָּ֥א עָלֵ֖ינוּ בְּיָדֵֽנוּ'),
(8003, 9, 'WLC', 'WLC', 'he', '1SA', 30, 24, 'OT', 'וּמִי֙ יִשְׁמַ֣ע לָכֶ֔ם לַדָּבָ֖ר הַזֶּ֑ה כִּ֞י כְּחֵ֣לֶק הַיֹּרֵ֣ד בַּמִּלְחָמָ֗ה וּֽכְחֵ֛לֶק הַיֹּשֵׁ֥ב עַל הַכֵּלִ֖ים יַחְדָּ֥ו יַחֲלֹֽקוּ'),
