(8237, 10, 'WLC', 'WLC', 'he', '2SA', 9, 9, 'OT', 'וַיִּקְרָ֣א הַמֶּ֗לֶךְ אֶל צִיבָ֛א נַ֥עַר שָׁא֖וּל וַיֹּ֣אמֶר אֵלָ֑יו כֹּל֩ אֲשֶׁ֨ר הָיָ֤ה לְשָׁאוּל֙ וּלְכָל בֵּית֔וֹ נָתַ֖תִּי לְבֶן אֲדֹנֶֽיךָ'),
(8238, 10, 'WLC', 'WLC', 'he', '2SA', 9, 10, 'OT', 'וְעָבַ֣דְתָּ לּ֣וֹ אֶֽת הָאֲדָמָ֡ה אַתָּה֩ וּבָנֶ֨יךָ וַעֲבָדֶ֜יךָ וְהֵבֵ֗אתָ וְהָיָ֨ה לְבֶן אֲדֹנֶ֤יךָ לֶּ֨חֶם֙ וַאֲכָל֔וֹ וּמְפִיבֹ֨שֶׁת֙ בֶּן אֲדֹנֶ֔יךָ יֹאכַ֥ל תָּמִ֛יד לֶ֖חֶם עַל שֻׁלְחָנִ֑י וּלְצִיבָ֗א חֲמִשָּׁ֥ה עָשָׂ֛ר בָּנִ֖ים וְעֶשְׂרִ֥ים עֲבָדִֽים'),
(8239, 10, 'WLC', 'WLC', 'he', '2SA', 9, 11, 'OT', 'וַיֹּ֤אמֶר צִיבָא֙ אֶל הַמֶּ֔לֶךְ כְּכֹל֩ אֲשֶׁ֨ר יְצַוֶּ֜ה אֲדֹנִ֤י הַמֶּ֨לֶךְ֙ אֶת עַבְדּ֔וֹ כֵּ֖ן יַעֲשֶׂ֣ה עַבְדֶּ֑ךָ וּמְפִיבֹ֗שֶׁת אֹכֵל֙ עַל שֻׁלְחָנִ֔י כְּאַחַ֖ד מִבְּנֵ֥י הַמֶּֽלֶךְ'),
(8240, 10, 'WLC', 'WLC', 'he', '2SA', 9, 12, 'OT', 'וְלִמְפִיבֹ֥שֶׁת בֵּן קָטָ֖ן וּשְׁמ֣וֹ מִיכָ֑א וְכֹל֙ מוֹשַׁ֣ב בֵּית צִיבָ֔א עֲבָדִ֖ים לִמְפִיבֹֽשֶׁת'),
(8241, 10, 'WLC', 'WLC', 'he', '2SA', 9, 13, 'OT', 'וּמְפִיבֹ֗שֶׁת יֹשֵׁב֙ בִּיר֣וּשָׁלִַ֔ם כִּ֣י עַל שֻׁלְחַ֥ן הַמֶּ֛לֶךְ תָּמִ֖יד ה֣וּא אֹכֵ֑ל וְה֥וּא פִסֵּ֖חַ שְׁתֵּ֥י רַגְלָֽיו'),
(8242, 10, 'WLC', 'WLC', 'he', '2SA', 10, 1, 'OT', 'וַֽיְהִי֙ אַֽחֲרֵי כֵ֔ן וַיָּ֕מָת מֶ֖לֶךְ בְּנֵ֣י עַמּ֑וֹן וַיִּמְלֹ֛ךְ חָנ֥וּן בְּנ֖וֹ תַּחְתָּֽיו'),
(8243, 10, 'WLC', 'WLC', 'he', '2SA', 10, 2, 'OT', 'וַיֹּ֨אמֶר דָּוִ֜ד אֶעֱשֶׂה חֶ֣סֶד עִם חָנ֣וּן בֶּן נָחָ֗שׁ כַּאֲשֶׁר֩ עָשָׂ֨ה אָבִ֤יו עִמָּדִי֙ חֶ֔סֶד וַיִּשְׁלַ֨ח דָּוִ֧ד לְנַחֲמ֛וֹ בְּיַד עֲבָדָ֖יו אֶל אָבִ֑יו וַיָּבֹ֨אוּ֙ עַבְדֵ֣י דָוִ֔ד אֶ֖רֶץ בְּנֵ֥י עַמּֽוֹן'),
(8244, 10, 'WLC', 'WLC', 'he', '2SA', 10, 3, 'OT', 'וַיֹּאמְרוּ֩ שָׂרֵ֨י בְנֵֽי עַמּ֜וֹן אֶל חָנ֣וּן אֲדֹֽנֵיהֶ֗ם הַֽמְכַבֵּ֨ד דָּוִ֤ד אֶת אָבִ֨יךָ֙ בְּעֵינֶ֔יךָ כִּֽי שָׁלַ֥ח לְךָ֖ מְנַֽחֲמִ֑ים הֲ֠לוֹא בַּעֲב֞וּר חֲק֤וֹר אֶת הָעִיר֙ וּלְרַגְּלָ֣הּ וּלְהָפְכָ֔הּ שָׁלַ֥ח דָּוִ֛ד אֶת עֲבָדָ֖יו אֵלֶֽיךָ'),
(8245, 10, 'WLC', 'WLC', 'he', '2SA', 10, 4, 'OT', 'וַיִּקַּ֨ח חָנ֜וּן אֶת עַבְדֵ֣י דָוִ֗ד וַיְגַלַּח֙ אֶת חֲצִ֣י זְקָנָ֔ם וַיִּכְרֹ֧ת אֶת מַדְוֵיהֶ֛ם בַּחֵ֖צִי עַ֣ד שְׁתֽוֹתֵיהֶ֑ם וַֽיְשַׁלְּחֵֽם'),
(8246, 10, 'WLC', 'WLC', 'he', '2SA', 10, 5, 'OT', 'וַיַּגִּ֤דוּ לְדָוִד֙ וַיִּשְׁלַ֣ח לִקְרָאתָ֔ם כִּֽי הָי֥וּ הָאֲנָשִׁ֖ים נִכְלָמִ֣ים מְאֹ֑ד וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ שְׁב֣וּ בִֽירֵח֔וֹ עַד יְצַמַּ֥ח זְקַנְכֶ֖ם וְשַׁבְתֶּֽם'),
(8247, 10, 'WLC', 'WLC', 'he', '2SA', 10, 6, 'OT', 'וַיִּרְאוּ֙ בְּנֵ֣י עַמּ֔וֹן כִּ֥י נִבְאֲשׁ֖וּ בְּדָוִ֑ד וַיִּשְׁלְח֣וּ בְנֵֽי עַמּ֡וֹן וַיִּשְׂכְּרוּ֩ אֶת אֲרַ֨ם בֵּית רְח֜וֹב וְאֶת אֲרַ֣ם צוֹבָ֗א עֶשְׂרִ֥ים אֶ֨לֶף֙ רַגְלִ֔י וְאֶת מֶ֤לֶךְ מַֽעֲכָה֙ אֶ֣לֶף אִ֔ישׁ וְאִ֣ישׁ ט֔וֹב שְׁנֵים עָשָׂ֥ר אֶ֖לֶף אִֽישׁ'),
(8248, 10, 'WLC', 'WLC', 'he', '2SA', 10, 7, 'OT', 'וַיִּשְׁמַ֖ע דָּוִ֑ד וַיִּשְׁלַח֙ אֶת יוֹאָ֔ב וְאֵ֥ת כָּל הַצָּבָ֖א הַגִּבֹּרִֽים'),
(8249, 10, 'WLC', 'WLC', 'he', '2SA', 10, 8, 'OT', 'וַיֵּֽצְאוּ֙ בְּנֵ֣י עַמּ֔וֹן וַיַּעַרְכ֥וּ מִלְחָמָ֖ה פֶּ֣תַח הַשָּׁ֑עַר וַאֲרַ֨ם צוֹבָ֤א וּרְחוֹב֙ וְאִֽישׁ ט֣וֹב וּמַֽעֲכָ֔ה לְבַדָּ֖ם בַּשָּׂדֶֽה'),
(8250, 10, 'WLC', 'WLC', 'he', '2SA', 10, 9, 'OT', 'וַיַּ֣רְא יוֹאָ֗ב כִּֽי הָיְתָ֤ה אֵלָיו֙ פְּנֵ֣י הַמִּלְחָמָ֔ה מִפָּנִ֖ים וּמֵֽאָח֑וֹר וַיִּבְחַ֗ר מִכֹּל֙ בְּחוּרֵ֣י בישראל וַֽיַּעֲרֹ֖ךְ לִקְרַ֥את אֲרָֽם'),
(8251, 10, 'WLC', 'WLC', 'he', '2SA', 10, 10, 'OT', 'וְאֵת֙ יֶ֣תֶר הָעָ֔ם נָתַ֕ן בְּיַ֖ד אַבְשַׁ֣י אָחִ֑יו וַֽיַּעֲרֹ֕ךְ לִקְרַ֖את בְּנֵ֥י עַמּֽוֹן'),
(8252, 10, 'WLC', 'WLC', 'he', '2SA', 10, 11, 'OT', 'וַיֹּ֗אמֶר אִם תֶּחֱזַ֤ק אֲרָם֙ מִמֶּ֔נִּי וְהָיִ֥תָה לִּ֖י לִֽישׁוּעָ֑ה וְאִם בְּנֵ֤י עַמּוֹן֙ יֶחֱזְק֣וּ מִמְּךָ֔ וְהָלַכְתִּ֖י לְהוֹשִׁ֥יעַֽ לָֽךְ'),
(8253, 10, 'WLC', 'WLC', 'he', '2SA', 10, 12, 'OT', 'חֲזַ֤ק וְנִתְחַזַּק֙ בְּעַד עַמֵּ֔נוּ וּבְעַ֖ד עָרֵ֣י אֱלֹהֵ֑ינוּ וַֽיהוָ֔ה יַעֲשֶׂ֥ה הַטּ֖וֹב בְּעֵינָֽיו'),
(8254, 10, 'WLC', 'WLC', 'he', '2SA', 10, 13, 'OT', 'וַיִּגַּ֣שׁ יוֹאָ֗ב וְהָעָם֙ אֲשֶׁ֣ר עִמּ֔וֹ לַמִּלְחָמָ֖ה בַּֽאֲרָ֑ם וַיָּנֻ֖סוּ מִפָּנָֽיו'),
(8255, 10, 'WLC', 'WLC', 'he', '2SA', 10, 14, 'OT', 'וּבְנֵ֨י עַמּ֤וֹן רָאוּ֙ כִּי נָ֣ס אֲרָ֔ם וַיָּנֻ֨סוּ֙ מִפְּנֵ֣י אֲבִישַׁ֔י וַיָּבֹ֖אוּ הָעִ֑יר וַיָּ֣שָׁב יוֹאָ֗ב מֵעַל֙ בְּנֵ֣י עַמּ֔וֹן וַיָּבֹ֖א יְרוּשָׁלִָֽם'),
(8256, 10, 'WLC', 'WLC', 'he', '2SA', 10, 15, 'OT', 'וַיַּ֣רְא אֲרָ֔ם כִּ֥י נִגַּ֖ף לִפְנֵ֣י יִשְׂרָאֵ֑ל וַיֵּאָסְפ֖וּ יָֽחַד'),
(8257, 10, 'WLC', 'WLC', 'he', '2SA', 10, 16, 'OT', 'וַיִּשְׁלַ֣ח הֲדַדְעֶ֗זֶר וַיֹּצֵ֤א אֶת אֲרָם֙ אֲשֶׁר֙ מֵעֵ֣בֶר הַנָּהָ֔ר וַיָּבֹ֖אוּ חֵילָ֑ם וְשׁוֹבַ֛ךְ שַׂר צְבָ֥א הֲדַדְעֶ֖זֶר לִפְנֵיהֶֽם'),
(8258, 10, 'WLC', 'WLC', 'he', '2SA', 10, 17, 'OT', 'וַיֻּגַּ֣ד לְדָוִ֗ד וַיֶּאֱסֹ֤ף אֶת כָּל יִשְׂרָאֵל֙ וַיַּעֲבֹ֣ר אֶת הַיַּרְדֵּ֔ן וַיָּבֹ֖א חֵלָ֑אמָה וַיַּעַרְכ֤וּ אֲרָם֙ לִקְרַ֣את דָּוִ֔ד וַיִּלָּחֲמ֖וּ עִמּֽוֹ'),
(8259, 10, 'WLC', 'WLC', 'he', '2SA', 10, 18, 'OT', 'וַיָּ֣נָס אֲרָם֮ מִפְּנֵ֣י יִשְׂרָאֵל֒ וַיַּהֲרֹ֨ג דָּוִ֜ד מֵאֲרָ֗ם שְׁבַ֤ע מֵאוֹת֙ רֶ֔כֶב וְאַרְבָּעִ֥ים אֶ֖לֶף פָּרָשִׁ֑ים וְאֵ֨ת שׁוֹבַ֧ךְ שַׂר צְבָא֛וֹ הִכָּ֖ה וַיָּ֥מָת שָֽׁם'),
(8260, 10, 'WLC', 'WLC', 'he', '2SA', 10, 19, 'OT', 'וַיִּרְא֨וּ כָֽל הַמְּלָכִ֜ים עַבְדֵ֣י הֲדַדְעֶ֗זֶר כִּ֤י נִגְּפוּ֙ לִפְנֵ֣י יִשְׂרָאֵ֔ל וַיַּשְׁלִ֥מוּ אֶת יִשְׂרָאֵ֖ל וַיַּֽעַבְד֑וּם וַיִּֽרְא֣וּ אֲרָ֔ם לְהוֹשִׁ֥יעַ ע֖וֹד אֶת בְּנֵ֥י עַמּֽוֹן'),
(8261, 10, 'WLC', 'WLC', 'he', '2SA', 11, 1, 'OT', 'וַיְהִי֩ לִתְשׁוּבַ֨ת הַשָּׁנָ֜ה לְעֵ֣ת צֵ֣את הַמַּלְאֿכִ֗ים וַיִּשְׁלַ֣ח דָּוִ֡ד אֶת יוֹאָב֩ וְאֶת עֲבָדָ֨יו עִמּ֜וֹ וְאֶת כָּל יִשְׂרָאֵ֗ל וַיַּשְׁחִ֨תוּ֙ אֶת בְּנֵ֣י עַמּ֔וֹן וַיָּצֻ֖רוּ עַל רַבָּ֑ה וְדָוִ֖ד יוֹשֵׁ֥ב בִּירוּשָׁלִָֽם'),
(8262, 10, 'WLC', 'WLC', 'he', '2SA', 11, 2, 'OT', 'וַיְהִ֣י לְעֵ֣ת הָעֶ֗רֶב וַיָּ֨קָם דָּוִ֜ד מֵעַ֤ל מִשְׁכָּבוֹ֙ וַיִּתְהַלֵּךְ֙ עַל גַּ֣ג בֵּית הַמֶּ֔לֶךְ וַיַּ֥רְא אִשָּׁ֛ה רֹחֶ֖צֶת מֵעַ֣ל הַגָּ֑ג וְהָ֣אִשָּׁ֔ה טוֹבַ֥ת מַרְאֶ֖ה מְאֹֽד'),
(8263, 10, 'WLC', 'WLC', 'he', '2SA', 11, 3, 'OT', 'וַיִּשְׁלַ֣ח דָּוִ֔ד וַיִּדְרֹ֖שׁ לָֽאִשָּׁ֑ה וַיֹּ֗אמֶר הֲלוֹא זֹאת֙ בַּת שֶׁ֣בַע בַּת אֱלִיעָ֔ם אֵ֖שֶׁת אוּרִיָּ֥ה הַחִתִּֽי'),
(8264, 10, 'WLC', 'WLC', 'he', '2SA', 11, 4, 'OT', 'וַיִּשְׁלַח֩ דָּוִ֨ד מַלְאָכִ֜ים וַיִּקָּחֶ֗הָ וַתָּב֤וֹא אֵלָיו֙ וַיִּשְׁכַּ֣ב עִמָּ֔הּ וְהִ֥יא מִתְקַדֶּ֖שֶׁת מִטֻּמְאָתָ֑הּ וַתָּ֖שָׁב אֶל בֵּיתָֽהּ'),
(8265, 10, 'WLC', 'WLC', 'he', '2SA', 11, 5, 'OT', 'וַתַּ֖הַר הָֽאִשָּׁ֑ה וַתִּשְׁלַח֙ וַתַּגֵּ֣ד לְדָוִ֔ד וַתֹּ֖אמֶר הָרָ֥ה אָנֹֽכִי'),
(8266, 10, 'WLC', 'WLC', 'he', '2SA', 11, 6, 'OT', 'וַיִּשְׁלַ֤ח דָּוִד֙ אֶל יוֹאָ֔ב שְׁלַ֣ח אֵלַ֔י אֶת אֽוּרִיָּ֖ה הַחִתִּ֑י וַיִּשְׁלַ֥ח יוֹאָ֛ב אֶת אֽוּרִיָּ֖ה אֶל דָּוִֽד'),
(8267, 10, 'WLC', 'WLC', 'he', '2SA', 11, 7, 'OT', 'וַיָּבֹ֥א אוּרִיָּ֖ה אֵלָ֑יו וַיִּשְׁאַ֣ל דָּוִ֗ד לִשְׁל֤וֹם יוֹאָב֙ וְלִשְׁל֣וֹם הָעָ֔ם וְלִשְׁל֖וֹם הַמִּלְחָמָֽה'),
