(8362, 10, 'WLC', 'WLC', 'he', '2SA', 14, 5, 'OT', 'וַיֹּֽאמֶר לָ֥הּ הַמֶּ֖לֶךְ מַה לָּ֑ךְ וַתֹּ֗אמֶר אֲבָ֛ל אִשָּֽׁה אַלְמָנָ֥ה אָ֖נִי וַיָּ֥מָת אִישִֽׁי'),
(8363, 10, 'WLC', 'WLC', 'he', '2SA', 14, 6, 'OT', 'וּלְשִׁפְחָֽתְךָ֙ שְׁנֵ֣י בָנִ֔ים וַיִּנָּצ֤וּ שְׁנֵיהֶם֙ בַּשָּׂדֶ֔ה וְאֵ֥ין מַצִּ֖יל בֵּֽינֵיהֶ֑ם וַיַּכּ֧וֹ הָאֶחָ֛ד אֶת הָאֶחָ֖ד וַיָּ֥מֶת אֹתֽוֹ'),
(8364, 10, 'WLC', 'WLC', 'he', '2SA', 14, 7, 'OT', 'וְהִנֵּה֩ קָ֨מָה כָֽל הַמִּשְׁפָּחָ֜ה עַל שִׁפְחָתֶ֗ךָ וַיֹּֽאמְרוּ֙ תְּנִ֣י אֶת מַכֵּ֣ה אָחִ֗יו וּנְמִתֵ֨הוּ֙ בְּנֶ֤פֶשׁ אָחִיו֙ אֲשֶׁ֣ר הָרָ֔ג וְנַשְׁמִ֖ידָה גַּ֣ם אֶת הַיּוֹרֵ֑שׁ וְכִבּ֗וּ אֶת גַּֽחַלְתִּי֙ אֲשֶׁ֣ר נִשְׁאָ֔רָה לְבִלְתִּ֧י שום לְאִישִׁ֛י שֵׁ֥ם וּשְׁאֵרִ֖ית עַל פְּנֵ֥י הָאֲדָמָֽה'),
(8365, 10, 'WLC', 'WLC', 'he', '2SA', 14, 8, 'OT', 'וַיֹּ֧אמֶר הַמֶּ֛לֶךְ אֶל הָאִשָּׁ֖ה לְכִ֣י לְבֵיתֵ֑ךְ וַאֲנִ֖י אֲצַוֶּ֥ה עָלָֽיִךְ'),
(8366, 10, 'WLC', 'WLC', 'he', '2SA', 14, 9, 'OT', 'וַתֹּ֜אמֶר הָאִשָּׁ֤ה הַתְּקוֹעִית֙ אֶל הַמֶּ֔לֶךְ עָלַ֞י אֲדֹנִ֥י הַמֶּ֛לֶךְ הֶעָוֺ֖ן וְעַל בֵּ֣ית אָבִ֑י וְהַמֶּ֥לֶךְ וְכִסְא֖וֹ נָקִֽי'),
(8367, 10, 'WLC', 'WLC', 'he', '2SA', 14, 10, 'OT', 'וַיֹּ֖אמֶר הַמֶּ֑לֶךְ הַֽמְדַבֵּ֤ר אֵלַ֨יִךְ֙ וַֽהֲבֵאת֣וֹ אֵלַ֔י וְלֹֽא יֹסִ֥יף ע֖וֹד לָגַ֥עַת בָּֽךְ'),
(8368, 10, 'WLC', 'WLC', 'he', '2SA', 14, 11, 'OT', 'וַתֹּאמֶר֩ יִזְכָּר נָ֨א הַמֶּ֜לֶךְ אֶת יְהוָ֣ה אֱלֹהֶ֗יךָ מהרבית גֹּאֵ֤ל הַדָּם֙ לְשַׁחֵ֔ת וְלֹ֥א יַשְׁמִ֖ידוּ אֶת בְּנִ֑י וַיֹּ֨אמֶר֙ חַי יְהוָ֔ה אִם יִפֹּ֛ל מִשַּׂעֲרַ֥ת בְּנֵ֖ךְ אָֽרְצָה'),
(8369, 10, 'WLC', 'WLC', 'he', '2SA', 14, 12, 'OT', 'וַתֹּ֨אמֶר֙ הָֽאִשָּׁ֔ה תְּדַבֶּר נָ֧א שִׁפְחָתְךָ֛ אֶל אֲדֹנִ֥י הַמֶּ֖לֶךְ דָּבָ֑ר וַיֹּ֖אמֶר דַּבֵּֽרִי'),
(8370, 10, 'WLC', 'WLC', 'he', '2SA', 14, 13, 'OT', 'וַתֹּ֨אמֶר֙ הָֽאִשָּׁ֔ה וְלָ֧מָּה חָשַׁ֛בְתָּה כָּזֹ֖את עַל עַ֣ם אֱלֹהִ֑ים וּמִדַּבֵּ֨ר הַמֶּ֜לֶךְ הַדָּבָ֤ר הַזֶּה֙ כְּאָשֵׁ֔ם לְבִלְתִּ֛י הָשִׁ֥יב הַמֶּ֖לֶךְ אֶֽת נִדְּחֽוֹ'),
(8371, 10, 'WLC', 'WLC', 'he', '2SA', 14, 14, 'OT', 'כִּי מ֣וֹת נָמ֔וּת וְכַמַּ֨יִם֙ הַנִּגָּרִ֣ים אַ֔רְצָה אֲשֶׁ֖ר לֹ֣א יֵאָסֵ֑פוּ וְלֹֽא יִשָּׂ֤א אֱלֹהִים֙ נֶ֔פֶשׁ וְחָשַׁב֙ מַֽחֲשָׁב֔וֹת לְבִלְתִּ֛י יִדַּ֥ח מִמֶּ֖נּוּ נִדָּֽח'),
(8372, 10, 'WLC', 'WLC', 'he', '2SA', 14, 15, 'OT', 'וְ֠עַתָּה אֲשֶׁר בָּ֜אתִי לְדַבֵּ֨ר אֶל הַמֶּ֤לֶךְ אֲדֹנִי֙ אֶת הַדָּבָ֣ר הַזֶּ֔ה כִּ֥י יֵֽרְאֻ֖נִי הָעָ֑ם וַתֹּ֤אמֶר שִׁפְחָֽתְךָ֙ אֲדַבְּרָה נָּ֣א אֶל הַמֶּ֔לֶךְ אוּלַ֛י יַעֲשֶׂ֥ה הַמֶּ֖לֶךְ אֶת דְּבַ֥ר אֲמָתֽוֹ'),
(8373, 10, 'WLC', 'WLC', 'he', '2SA', 14, 16, 'OT', 'כִּ֚י יִשְׁמַ֣ע הַמֶּ֔לֶךְ לְהַצִּ֥יל אֶת אֲמָת֖וֹ מִכַּ֣ף הָאִ֑ישׁ לְהַשְׁמִ֨יד אֹתִ֤י וְאֶת בְּנִי֙ יַ֔חַד מִֽנַּחֲלַ֖ת אֱלֹהִֽים'),
(8374, 10, 'WLC', 'WLC', 'he', '2SA', 14, 17, 'OT', 'וַתֹּ֨אמֶר֙ שִׁפְחָ֣תְךָ֔ יִֽהְיֶה נָּ֛א דְּבַר אֲדֹנִ֥י הַמֶּ֖לֶךְ לִמְנוּחָ֑ה כִּ֣י כְּמַלְאַ֣ךְ הָאֱלֹהִ֗ים כֵּ֣ן אֲדֹנִ֤י הַמֶּ֨לֶךְ֙ לִשְׁמֹ֨עַ֙ הַטּ֣וֹב וְהָרָ֔ע וַֽיהוָ֥ה אֱלֹהֶ֖יךָ יְהִ֥י עִמָּֽךְ'),
(8375, 10, 'WLC', 'WLC', 'he', '2SA', 14, 18, 'OT', 'וַיַּ֣עַן הַמֶּ֗לֶךְ וַיֹּ֨אמֶר֙ אֶל הָ֣אִשָּׁ֔ה אַל נָ֨א תְכַחֲדִ֤י מִמֶּ֨נִּי֙ דָּבָ֔ר אֲשֶׁ֥ר אָנֹכִ֖י שֹׁאֵ֣ל אֹתָ֑ךְ וַתֹּ֨אמֶר֙ הָֽאִשָּׁ֔ה יְדַבֶּר נָ֖א אֲדֹנִ֥י הַמֶּֽלֶךְ'),
(8376, 10, 'WLC', 'WLC', 'he', '2SA', 14, 19, 'OT', 'וַיֹּ֣אמֶר הַמֶּ֔לֶךְ הֲיַ֥ד יוֹאָ֛ב אִתָּ֖ךְ בְּכָל זֹ֑את וַתַּ֣עַן הָאִשָּׁ֣ה וַתֹּ֡אמֶר חֵֽי נַפְשְׁךָ֩ אֲדֹנִ֨י הַמֶּ֜לֶךְ אִם אִ֣שׁ לְהֵמִ֣ין וּלְהַשְׂמִ֗יל מִכֹּ֤ל אֲשֶׁר דִּבֶּר֙ אֲדֹנִ֣י הַמֶּ֔לֶךְ כִּֽי עַבְדְּךָ֤ יוֹאָב֙ ה֣וּא צִוָּ֔נִי וְה֗וּא שָׂ֚ם בְּפִ֣י שִׁפְחָֽתְךָ֔ אֵ֥ת כָּל הַדְּבָרִ֖ים הָאֵֽלֶּה'),
(8377, 10, 'WLC', 'WLC', 'he', '2SA', 14, 20, 'OT', 'לְבַעֲב֤וּר סַבֵּב֙ אֶת פְּנֵ֣י הַדָּבָ֔ר עָשָׂ֛ה עַבְדְּךָ֥ יוֹאָ֖ב אֶת הַדָּבָ֣ר הַזֶּ֑ה וַאדֹנִ֣י חָכָ֗ם כְּחָכְמַת֙ מַלְאַ֣ךְ הָאֱלֹהִ֔ים לָדַ֖עַת אֶֽת כָּל אֲשֶׁ֥ר בָּאָֽרֶץ'),
(8378, 10, 'WLC', 'WLC', 'he', '2SA', 14, 21, 'OT', 'וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ אֶל יוֹאָ֔ב הִנֵּה נָ֥א עָשִׂ֖יתִי אֶת הַדָּבָ֣ר הַזֶּ֑ה וְלֵ֛ךְ הָשֵׁ֥ב אֶת הַנַּ֖עַר אֶת אַבְשָׁלֽוֹם'),
(8379, 10, 'WLC', 'WLC', 'he', '2SA', 14, 22, 'OT', 'וַיִּפֹּל֩ יוֹאָ֨ב אֶל פָּנָ֥יו אַ֛רְצָה וַיִּשְׁתַּ֖חוּ וַיְבָ֣רֶךְ אֶת הַמֶּ֑לֶךְ וַיֹּ֣אמֶר יוֹאָ֡ב הַיּוֹם֩ יָדַ֨ע עַבְדְּךָ֜ כִּי מָצָ֨אתִי חֵ֤ן בְּעֵינֶ֨יךָ֙ אֲדֹנִ֣י הַמֶּ֔לֶךְ אֲשֶׁר עָשָׂ֥ה הַמֶּ֖לֶךְ אֶת דְּבַ֥ר עבדו'),
(8380, 10, 'WLC', 'WLC', 'he', '2SA', 14, 23, 'OT', 'וַיָּ֥קָם יוֹאָ֖ב וַיֵּ֣לֶךְ גְּשׁ֑וּרָה וַיָּבֵ֥א אֶת אַבְשָׁל֖וֹם יְרוּשָׁלִָֽם'),
(8381, 10, 'WLC', 'WLC', 'he', '2SA', 14, 24, 'OT', 'וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ יִסֹּ֣ב אֶל בֵּית֔וֹ וּפָנַ֖י לֹ֣א יִרְאֶ֑ה וַיִּסֹּ֤ב אַבְשָׁלוֹם֙ אֶל בֵּית֔וֹ וּפְנֵ֥י הַמֶּ֖לֶךְ לֹ֥א רָאָֽה'),
(8382, 10, 'WLC', 'WLC', 'he', '2SA', 14, 25, 'OT', 'וּכְאַבְשָׁל֗וֹם לֹא הָיָ֧ה אִישׁ יָפֶ֛ה בְּכָל יִשְׂרָאֵ֖ל לְהַלֵּ֣ל מְאֹ֑ד מִכַּ֤ף רַגְלוֹ֙ וְעַ֣ד קָדְקֳד֔וֹ לֹא הָ֥יָה ב֖וֹ מֽוּם'),
(8383, 10, 'WLC', 'WLC', 'he', '2SA', 14, 26, 'OT', 'וּֽבְגַלְּחוֹ֮ אֶת רֹאשׁוֹ֒ וְֽ֠הָיָה מִקֵּ֨ץ יָמִ֤ים לַיָּמִים֙ אֲשֶׁ֣ר יְגַלֵּ֔חַ כִּֽי כָבֵ֥ד עָלָ֖יו וְגִלְּח֑וֹ וְשָׁקַל֙ אֶת שְׂעַ֣ר רֹאשׁ֔וֹ מָאתַ֥יִם שְׁקָלִ֖ים בְּאֶ֥בֶן הַמֶּֽלֶךְ'),
(8384, 10, 'WLC', 'WLC', 'he', '2SA', 14, 27, 'OT', 'וַיִּֽוָּלְד֤וּ לְאַבְשָׁלוֹם֙ שְׁלוֹשָׁ֣ה בָנִ֔ים וּבַ֥ת אַחַ֖ת וּשְׁמָ֣הּ תָּמָ֑ר הִ֣יא הָיְתָ֔ה אִשָּׁ֖ה יְפַ֥ת מַרְאֶֽה'),
(8385, 10, 'WLC', 'WLC', 'he', '2SA', 14, 28, 'OT', 'וַיֵּ֧שֶׁב אַבְשָׁל֛וֹם בִּירוּשָׁלִַ֖ם שְׁנָתַ֣יִם יָמִ֑ים וּפְנֵ֥י הַמֶּ֖לֶךְ לֹ֥א רָאָֽה'),
(8386, 10, 'WLC', 'WLC', 'he', '2SA', 14, 29, 'OT', 'וַיִּשְׁלַ֨ח אַבְשָׁל֜וֹם אֶל יוֹאָ֗ב לִשְׁלֹ֤חַ אֹתוֹ֙ אֶל הַמֶּ֔לֶךְ וְלֹ֥א אָבָ֖ה לָב֣וֹא אֵלָ֑יו וַיִּשְׁלַ֥ח עוֹד֙ שֵׁנִ֔ית וְלֹ֥א אָבָ֖ה לָבֽוֹא'),
(8387, 10, 'WLC', 'WLC', 'he', '2SA', 14, 30, 'OT', 'וַיֹּ֨אמֶר אֶל עֲבָדָ֜יו רְאוּ֩ חֶלְקַ֨ת יוֹאָ֤ב אֶל יָדִי֙ וְלוֹ שָׁ֣ם שְׂעֹרִ֔ים לְכ֖וּ והוצתיה בָאֵ֑שׁ וַיַּצִּ֜תוּ עַבְדֵ֧י אַבְשָׁל֛וֹם אֶת הַחֶלְקָ֖ה בָּאֵֽשׁ'),
(8388, 10, 'WLC', 'WLC', 'he', '2SA', 14, 31, 'OT', 'וַיָּ֣קָם יוֹאָ֔ב וַיָּבֹ֥א אֶל אַבְשָׁל֖וֹם הַבָּ֑יְתָה וַיֹּ֣אמֶר אֵלָ֔יו לָ֣מָּה הִצִּ֧יתוּ עֲבָדֶ֛ךָ אֶת הַחֶלְקָ֥ה אֲשֶׁר לִ֖י בָּאֵֽשׁ'),
(8389, 10, 'WLC', 'WLC', 'he', '2SA', 14, 32, 'OT', 'וַיֹּ֣אמֶר אַבְשָׁל֣וֹם אֶל יוֹאָ֡ב הִנֵּ֣ה שָׁלַ֣חְתִּי אֵלֶ֣יךָ לֵאמֹ֡ר בֹּ֣א הֵ֠נָּה וְאֶשְׁלְחָה֩ אֹתְךָ֨ אֶל הַמֶּ֜לֶךְ לֵאמֹ֗ר לָ֤מָּה בָּ֨אתִי֙ מִגְּשׁ֔וּר ט֥וֹב לִ֖י עֹ֣ד אֲנִי שָׁ֑ם וְעַתָּ֗ה אֶרְאֶה֙ פְּנֵ֣י הַמֶּ֔לֶךְ וְאִם יֶשׁ בִּ֥י עָוֺ֖ן וֶהֱמִתָֽנִי'),
(8390, 10, 'WLC', 'WLC', 'he', '2SA', 14, 33, 'OT', 'וַיָּבֹ֨א יוֹאָ֣ב אֶל הַמֶּלֶךְ֮ וַיַּגֶּד לוֹ֒ וַיִּקְרָ֤א אֶל אַבְשָׁלוֹם֙ וַיָּבֹ֣א אֶל הַמֶּ֔לֶךְ וַיִּשְׁתַּ֨חוּ ל֧וֹ עַל אַפָּ֛יו אַ֖רְצָה לִפְנֵ֣י הַמֶּ֑לֶךְ וַיִּשַּׁ֥ק הַמֶּ֖לֶךְ לְאַבְשָׁלֽוֹם'),
(8391, 10, 'WLC', 'WLC', 'he', '2SA', 15, 1, 'OT', 'וַֽיְהִי֙ מֵאַ֣חֲרֵי כֵ֔ן וַיַּ֤עַשׂ לוֹ֙ אַבְשָׁל֔וֹם מֶרְכָּבָ֖ה וְסֻסִ֑ים וַחֲמִשִּׁ֥ים אִ֖ישׁ רָצִ֥ים לְפָנָֽיו'),
(8392, 10, 'WLC', 'WLC', 'he', '2SA', 15, 2, 'OT', 'וְהִשְׁכִּים֙ אַבְשָׁל֔וֹם וְעָמַ֕ד עַל יַ֖ד דֶּ֣רֶךְ הַשָּׁ֑עַר וַיְהִ֡י כָּל הָאִ֣ישׁ אֲשֶֽׁר יִהְיֶה לּוֹ רִיב֩ לָב֨וֹא אֶל הַמֶּ֜לֶךְ לַמִּשְׁפָּ֗ט וַיִּקְרָ֨א אַבְשָׁל֤וֹם אֵלָיו֙ וַיֹּ֗אמֶר אֵֽי מִזֶּ֥ה עִיר֙ אַ֔תָּה וַיֹּ֕אמֶר מֵאַחַ֥ד שִׁבְטֵֽי יִשְׂרָאֵ֖ל עַבְדֶּֽךָ'),
