(8424, 10, 'WLC', 'WLC', 'he', '2SA', 15, 34, 'OT', 'וְאִם הָעִ֣יר תָּשׁ֗וּב וְאָמַרְתָּ֤ לְאַבְשָׁלוֹם֙ עַבְדְּךָ֨ אֲנִ֤י הַמֶּ֨לֶךְ֙ אֶֽהְיֶ֔ה עֶ֣בֶד אָבִ֤יךָ וַֽאֲנִי֙ מֵאָ֔ז וְעַתָּ֖ה וַאֲנִ֣י עַבְדֶּ֑ךָ וְהֵפַרְתָּ֣ה לִ֔י אֵ֖ת עֲצַ֥ת אֲחִיתֹֽפֶל'),
(8425, 10, 'WLC', 'WLC', 'he', '2SA', 15, 35, 'OT', 'וַהֲל֤וֹא עִמְּךָ֙ שָׁ֔ם צָד֥וֹק וְאֶבְיָתָ֖ר הַכֹּהֲנִ֑ים וְהָיָ֗ה כָּל הַדָּבָר֙ אֲשֶׁ֤ר תִּשְׁמַע֙ מִבֵּ֣ית הַמֶּ֔לֶךְ תַּגִּ֕יד לְצָד֥וֹק וּלְאֶבְיָתָ֖ר הַכֹּהֲנִֽים'),
(8426, 10, 'WLC', 'WLC', 'he', '2SA', 15, 36, 'OT', 'הִנֵּה שָׁ֤ם עִמָּם֙ שְׁנֵ֣י בְנֵיהֶ֔ם אֲחִימַ֣עַץ לְצָד֔וֹק וִיהוֹנָתָ֖ן לְאֶבְיָתָ֑ר וּשְׁלַחְתֶּ֤ם בְּיָדָם֙ אֵלַ֔י כָּל דָּבָ֖ר אֲשֶׁ֥ר תִּשְׁמָֽעוּ'),
(8427, 10, 'WLC', 'WLC', 'he', '2SA', 15, 37, 'OT', 'וַיָּבֹ֥א חוּשַׁ֛י רֵעֶ֥ה דָוִ֖ד הָעִ֑יר וְאַבְשָׁלֹ֔ם יָבֹ֖א יְרוּשָׁלִָֽם'),
(8428, 10, 'WLC', 'WLC', 'he', '2SA', 16, 1, 'OT', 'וְדָוִ֗ד עָבַ֤ר מְעַט֙ מֵֽהָרֹ֔אשׁ וְהִנֵּ֥ה צִיבָ֛א נַ֥עַר מְפִי בֹ֖שֶׁת לִקְרָאת֑וֹ וְצֶ֨מֶד חֲמֹרִ֜ים חֲבֻשִׁ֗ים וַעֲלֵיהֶם֩ מָאתַ֨יִם לֶ֜חֶם וּמֵאָ֧ה צִמּוּקִ֛ים וּמֵ֥אָה קַ֖יִץ וְנֵ֥בֶל יָֽיִן'),
(8429, 10, 'WLC', 'WLC', 'he', '2SA', 16, 2, 'OT', 'וַיֹּ֧אמֶר הַמֶּ֛לֶךְ אֶל צִיבָ֖א מָה אֵ֣לֶּה לָּ֑ךְ וַיֹּ֣אמֶר צִ֠יבָא הַחֲמוֹרִ֨ים לְבֵית הַמֶּ֜לֶךְ לִרְכֹּ֗ב ולהלחם וְהַקַּ֨יִץ֙ לֶאֱכ֣וֹל הַנְּעָרִ֔ים וְהַיַּ֕יִן לִשְׁתּ֥וֹת הַיָּעֵ֖ף בַּמִּדְבָּֽר'),
(8430, 10, 'WLC', 'WLC', 'he', '2SA', 16, 3, 'OT', 'וַיֹּ֣אמֶר הַמֶּ֔לֶךְ וְאַיֵּ֖ה בֶּן אֲדֹנֶ֑יךָ וַיֹּ֨אמֶר צִיבָ֜א אֶל הַמֶּ֗לֶךְ הִנֵּה֙ יוֹשֵׁ֣ב בִּירוּשָׁלִַ֔ם כִּ֣י אָמַ֔ר הַיּ֗וֹם יָשִׁ֤יבוּ לִי֙ בֵּ֣ית יִשְׂרָאֵ֔ל אֵ֖ת מַמְלְכ֥וּת אָבִֽי'),
(8431, 10, 'WLC', 'WLC', 'he', '2SA', 16, 4, 'OT', 'וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ לְצִבָ֔א הִנֵּ֣ה לְךָ֔ כֹּ֖ל אֲשֶׁ֣ר לִמְפִי בֹ֑שֶׁת וַיֹּ֤אמֶר צִיבָא֙ הִֽשְׁתַּחֲוֵ֔יתִי אֶמְצָא חֵ֥ן בְּעֵינֶ֖יךָ אֲדֹנִ֥י הַמֶּֽלֶךְ'),
(8432, 10, 'WLC', 'WLC', 'he', '2SA', 16, 5, 'OT', 'וּבָ֛א הַמֶּ֥לֶךְ דָּוִ֖ד עַד בַּֽחוּרִ֑ים וְהִנֵּ֣ה מִשָּׁם֩ אִ֨ישׁ יוֹצֵ֜א מִמִּשְׁפַּ֣חַת בֵּית שָׁא֗וּל וּשְׁמוֹ֙ שִׁמְעִ֣י בֶן גֵּרָ֔א יֹצֵ֥א יָצ֖וֹא וּמְקַלֵּֽל'),
(8433, 10, 'WLC', 'WLC', 'he', '2SA', 16, 6, 'OT', 'וַיְסַקֵּ֤ל בָּֽאֲבָנִים֙ אֶת דָּוִ֔ד וְאֶת כָּל עַבְדֵ֖י הַמֶּ֣לֶךְ דָּוִ֑ד וְכָל הָעָם֙ וְכָל הַגִּבֹּרִ֔ים מִימִינ֖וֹ וּמִשְּׂמֹאלֽוֹ'),
(8434, 10, 'WLC', 'WLC', 'he', '2SA', 16, 7, 'OT', 'וְכֹֽה אָמַ֥ר שִׁמְעִ֖י בְּקַֽלְל֑וֹ צֵ֥א צֵ֛א אִ֥ישׁ הַדָּמִ֖ים וְאִ֥ישׁ הַבְּלִיָּֽעַל'),
(8435, 10, 'WLC', 'WLC', 'he', '2SA', 16, 8, 'OT', 'הֵשִׁיב֩ עָלֶ֨יךָ יְהוָ֜ה כֹּ֣ל דְּמֵ֣י בֵית שָׁא֗וּל אֲשֶׁ֤ר מָלַ֨כְתָּ֙ תחתו וַיִּתֵּ֤ן יְהוָה֙ אֶת הַמְּלוּכָ֔ה בְּיַ֖ד אַבְשָׁל֣וֹם בְּנֶ֑ךָ וְהִנְּךָ֙ בְּרָ֣עָתֶ֔ךָ כִּ֛י אִ֥ישׁ דָּמִ֖ים אָֽתָּה'),
(8436, 10, 'WLC', 'WLC', 'he', '2SA', 16, 9, 'OT', 'וַיֹּ֨אמֶר אֲבִישַׁ֤י בֶּן צְרוּיָה֙ אֶל הַמֶּ֔לֶךְ לָ֣מָּה יְקַלֵּ֞ל הַכֶּ֤לֶב הַמֵּת֙ הַזֶּ֔ה אֶת אֲדֹנִ֖י הַמֶּ֑לֶךְ אֶעְבְּרָה נָּ֖א וְאָסִ֥ירָה אֶת רֹאשֽׁוֹ'),
