(8451, 10, 'WLC', 'WLC', 'he', '2SA', 17, 1, 'OT', 'וַיֹּ֥אמֶר אֲחִיתֹ֖פֶל אֶל אַבְשָׁלֹ֑ם אֶבְחֲרָ֣ה נָּ֗א שְׁנֵים עָשָׂ֥ר אֶ֨לֶף֙ אִ֔ישׁ וְאָק֛וּמָה וְאֶרְדְּפָ֥ה אַחֲרֵי דָוִ֖ד הַלָּֽיְלָה'),
(8452, 10, 'WLC', 'WLC', 'he', '2SA', 17, 2, 'OT', 'וְאָב֣וֹא עָלָ֗יו וְה֤וּא יָגֵ֨עַ֙ וּרְפֵ֣ה יָדַ֔יִם וְהַֽחֲרַדְתִּ֣י אֹת֔וֹ וְנָ֖ס כָּל הָעָ֣ם אֲשֶׁר אִתּ֑וֹ וְהִכֵּיתִ֥י אֶת הַמֶּ֖לֶךְ לְבַדּֽוֹ'),
(8453, 10, 'WLC', 'WLC', 'he', '2SA', 17, 3, 'OT', 'וְאָשִׁ֥יבָה כָל הָעָ֖ם אֵלֶ֑יךָ כְּשׁ֣וּב הַכֹּ֔ל הָאִישׁ֙ אֲשֶׁ֣ר אַתָּ֣ה מְבַקֵּ֔שׁ כָּל הָעָ֖ם יִהְיֶ֥ה שָׁלֽוֹם'),
(8454, 10, 'WLC', 'WLC', 'he', '2SA', 17, 4, 'OT', 'וַיִּישַׁ֥ר הַדָּבָ֖ר בְּעֵינֵ֣י אַבְשָׁלֹ֑ם וּבְעֵינֵ֖י כָּל זִקְנֵ֥י יִשְׂרָאֵֽל'),
(8455, 10, 'WLC', 'WLC', 'he', '2SA', 17, 5, 'OT', 'וַיֹּ֨אמֶר֙ אַבְשָׁל֔וֹם קְרָ֣א נָ֔א גַּ֖ם לְחוּשַׁ֣י הָאַרְכִּ֑י וְנִשְׁמְעָ֥ה מַה בְּפִ֖יו גַּם הֽוּא'),
(8456, 10, 'WLC', 'WLC', 'he', '2SA', 17, 6, 'OT', 'וַיָּבֹ֣א חוּשַׁי֮ אֶל אַבְשָׁלוֹם֒ וַיֹּאמֶר֩ אַבְשָׁל֨וֹם אֵלָ֜יו לֵאמֹ֗ר כַּדָּבָ֤ר הַזֶּה֙ דִּבֶּ֣ר אֲחִיתֹ֔פֶל הֲנַעֲשֶׂ֖ה אֶת דְּבָר֑וֹ אִם אַ֖יִן אַתָּ֥ה דַבֵּֽר'),
(8457, 10, 'WLC', 'WLC', 'he', '2SA', 17, 7, 'OT', 'וַיֹּ֥אמֶר חוּשַׁ֖י אֶל אַבְשָׁל֑וֹם לֹֽא טוֹבָ֧ה הָעֵצָ֛ה אֲשֶׁר יָעַ֥ץ אֲחִיתֹ֖פֶל בַּפַּ֥עַם הַזֹּֽאת'),
(8458, 10, 'WLC', 'WLC', 'he', '2SA', 17, 8, 'OT', 'וַיֹּ֣אמֶר חוּשַׁ֗י אַתָּ֣ה יָ֠דַעְתָּ אֶת אָבִ֨יךָ וְאֶת אֲנָשָׁ֜יו כִּ֧י גִבֹּרִ֣ים הֵ֗מָּה וּמָרֵ֥י נֶ֨פֶשׁ֙ הֵ֔מָּה כְּדֹ֥ב שַׁכּ֖וּל בַּשָּׂדֶ֑ה וְאָבִ֨יךָ֙ אִ֣ישׁ מִלְחָמָ֔ה וְלֹ֥א יָלִ֖ין אֶת הָעָֽם'),
(8459, 10, 'WLC', 'WLC', 'he', '2SA', 17, 9, 'OT', 'הִנֵּ֨ה עַתָּ֤ה הֽוּא נֶחְבָּא֙ בְּאַחַ֣ת הַפְּחָתִ֔ים א֖וֹ בְּאַחַ֣ד הַמְּקוֹמֹ֑ת וְהָיָ֗ה כִּנְפֹ֤ל בָּהֶם֙ בַּתְּחִלָּ֔ה וְשָׁמַ֤ע הַשֹּׁמֵ֨עַ֙ וְאָמַ֔ר הָֽיְתָה֙ מַגֵּפָ֔ה בָּעָ֕ם אֲשֶׁ֖ר אַחֲרֵ֥י אַבְשָׁלֹֽם'),
(8460, 10, 'WLC', 'WLC', 'he', '2SA', 17, 10, 'OT', 'וְה֣וּא גַם בֶּן חַ֗יִל אֲשֶׁ֥ר לִבּ֛וֹ כְּלֵ֥ב הָאַרְיֵ֖ה הִמֵּ֣ס יִמָּ֑ס כִּֽי יֹדֵ֤עַ כָּל יִשְׂרָאֵל֙ כִּי גִבּ֣וֹר אָבִ֔יךָ וּבְנֵי חַ֖יִל אֲשֶׁ֥ר אִתּֽוֹ'),
(8461, 10, 'WLC', 'WLC', 'he', '2SA', 17, 11, 'OT', 'כִּ֣י יָעַ֗צְתִּי הֵ֠אָסֹף יֵאָסֵ֨ף עָלֶ֤יךָ כָל יִשְׂרָאֵל֙ מִדָּן֙ וְעַד בְּאֵ֣ר שֶׁ֔בַע כַּח֥וֹל אֲשֶׁר עַל הַיָּ֖ם לָרֹ֑ב וּפָנֶ֥יךָ הֹלְכִ֖ים בַּקְרָֽב'),
(8462, 10, 'WLC', 'WLC', 'he', '2SA', 17, 12, 'OT', 'וּבָ֣אנוּ אֵלָ֗יו באחת הַמְּקוֹמֹת֙ אֲשֶׁ֣ר נִמְצָ֣א שָׁ֔ם וְנַ֣חְנוּ עָלָ֔יו כַּאֲשֶׁ֛ר יִפֹּ֥ל הַטַּ֖ל עַל הָאֲדָמָ֑ה וְלֹֽא נ֥וֹתַר בּ֛וֹ וּבְכָל הָאֲנָשִׁ֥ים אֲשֶׁר אִתּ֖וֹ גַּם אֶחָֽד'),
(8463, 10, 'WLC', 'WLC', 'he', '2SA', 17, 13, 'OT', 'וְאִם אֶל עִיר֙ יֵֽאָסֵ֔ף וְהִשִּׂ֧יאוּ כָֽל יִשְׂרָאֵ֛ל אֶל הָעִ֥יר הַהִ֖יא חֲבָלִ֑ים וְסָחַ֤בְנוּ אֹתוֹ֙ עַד הַנַּ֔חַל עַ֛ד אֲשֶֽׁר לֹא נִמְצָ֥א שָׁ֖ם גַּם צְרֽוֹר'),
(8464, 10, 'WLC', 'WLC', 'he', '2SA', 17, 14, 'OT', 'וַיֹּ֤אמֶר אַבְשָׁלוֹם֙ וְכָל אִ֣ישׁ יִשְׂרָאֵ֔ל טוֹבָ֗ה עֲצַת֙ חוּשַׁ֣י הָאַרְכִּ֔י מֵעֲצַ֖ת אֲחִיתֹ֑פֶל וַיהוָ֣ה צִוָּ֗ה לְהָפֵ֞ר אֶת עֲצַ֤ת אֲחִיתֹ֨פֶל֙ הַטּוֹבָ֔ה לְבַעֲב֗וּר הָבִ֧יא יְהוָ֛ה אֶל אַבְשָׁל֖וֹם אֶת הָרָעָֽה'),
(8465, 10, 'WLC', 'WLC', 'he', '2SA', 17, 15, 'OT', 'וַיֹּ֣אמֶר חוּשַׁ֗י אֶל צָד֤וֹק וְאֶל אֶבְיָתָר֙ הַכֹּ֣הֲנִ֔ים כָּזֹ֣את וְכָזֹ֗את יָעַ֤ץ אֲחִיתֹ֨פֶל֙ אֶת אַבְשָׁלֹ֔ם וְאֵ֖ת זִקְנֵ֣י יִשְׂרָאֵ֑ל וְכָזֹ֥את וְכָזֹ֖את יָעַ֥צְתִּי אָֽנִי'),
(8466, 10, 'WLC', 'WLC', 'he', '2SA', 17, 16, 'OT', 'וְעַתָּ֡ה שִׁלְח֣וּ מְהֵרָה֩ וְהַגִּ֨ידוּ לְדָוִ֜ד לֵאמֹ֗ר אַל תָּ֤לֶן הַלַּ֨יְלָה֙ בְּעַֽרְב֣וֹת הַמִּדְבָּ֔ר וְגַ֖ם עָב֣וֹר תַּעֲב֑וֹר פֶּ֚ן יְבֻלַּ֣ע לַמֶּ֔לֶךְ וּלְכָל הָעָ֖ם אֲשֶׁ֥ר אִתּֽוֹ'),
(8467, 10, 'WLC', 'WLC', 'he', '2SA', 17, 17, 'OT', 'וִיהוֹנָתָ֨ן וַאֲחִימַ֜עַץ עֹמְדִ֣ים בְּעֵין רֹגֵ֗ל וְהָלְכָ֤ה הַשִּׁפְחָה֙ וְהִגִּ֣ידָה לָהֶ֔ם וְהֵם֙ יֵֽלְכ֔וּ וְהִגִּ֖ידוּ לַמֶּ֣לֶךְ דָּוִ֑ד כִּ֣י לֹ֥א יוּכְל֛וּ לְהֵרָא֖וֹת לָב֥וֹא הָעִֽירָה'),
(8468, 10, 'WLC', 'WLC', 'he', '2SA', 17, 18, 'OT', 'וַיַּ֤רְא אֹתָם֙ נַ֔עַר וַיַּגֵּ֖ד לְאַבְשָׁלֹ֑ם וַיֵּלְכוּ֩ שְׁנֵיהֶ֨ם מְהֵרָ֜ה וַיָּבֹ֣אוּ אֶל בֵּֽית אִ֣ישׁ בְּבַחוּרִ֗ים וְל֥וֹ בְאֵ֛ר בַּחֲצֵר֖וֹ וַיֵּ֥רְדוּ שָֽׁם'),
(8469, 10, 'WLC', 'WLC', 'he', '2SA', 17, 19, 'OT', 'וַתִּקַּ֣ח הָאִשָּׁ֗ה וַתִּפְרֹ֤שׂ אֶת הַמָּסָךְ֙ עַל פְּנֵ֣י הַבְּאֵ֔ר וַתִּשְׁטַ֥ח עָלָ֖יו הָֽרִפ֑וֹת וְלֹ֥א נוֹדַ֖ע דָּבָֽר'),
(8470, 10, 'WLC', 'WLC', 'he', '2SA', 17, 20, 'OT', 'וַיָּבֹ֣אוּ עַבְדֵי֩ אַבְשָׁל֨וֹם אֶֽל הָאִשָּׁ֜ה הַבַּ֗יְתָה וַיֹּֽאמְרוּ֙ אַיֵּ֗ה אֲחִימַ֨עַץ֙ וִיה֣וֹנָתָ֔ן וַתֹּ֤אמֶר לָהֶם֙ הָֽאִשָּׁ֔ה עָבְר֖וּ מִיכַ֣ל הַמָּ֑יִם וַיְבַקְשׁוּ֙ וְלֹ֣א מָצָ֔אוּ וַיָּשֻׁ֖בוּ יְרוּשָׁלִָֽם'),
(8471, 10, 'WLC', 'WLC', 'he', '2SA', 17, 21, 'OT', 'וַיְהִ֣י אַחֲרֵ֣י לֶכְתָּ֗ם וַֽיַּעֲלוּ֙ מֵֽהַבְּאֵ֔ר וַיֵּ֣לְכ֔וּ וַיַּגִּ֖דוּ לַמֶּ֣לֶךְ דָּוִ֑ד וַיֹּאמְר֣וּ אֶל דָּוִ֗ד ק֣וּמוּ וְעִבְר֤וּ מְהֵרָה֙ אֶת הַמַּ֔יִם כִּי כָ֛כָה יָעַ֥ץ עֲלֵיכֶ֖ם אֲחִיתֹֽפֶל'),
(8472, 10, 'WLC', 'WLC', 'he', '2SA', 17, 22, 'OT', 'וַיָּ֣קָם דָּוִ֗ד וְכָל הָעָם֙ אֲשֶׁ֣ר אִתּ֔וֹ וַיַּעַבְר֖וּ אֶת הַיַּרְדֵּ֑ן עַד א֣וֹר הַבֹּ֗קֶר עַד אַחַד֙ לֹ֣א נֶעְדָּ֔ר אֲשֶׁ֥ר לֹא עָבַ֖ר אֶת הַיַּרְדֵּֽן'),
(8473, 10, 'WLC', 'WLC', 'he', '2SA', 17, 23, 'OT', 'וַאֲחִיתֹ֣פֶל רָאָ֗ה כִּ֣י לֹ֣א נֶעֶשְׂתָה֮ עֲצָתוֹ֒ וַיַּחֲבֹ֣שׁ אֶֽת הַחֲמ֗וֹר וַיָּ֜קָם וַיֵּ֤לֶךְ אֶל בֵּיתוֹ֙ אֶל עִיר֔וֹ וַיְצַ֥ו אֶל בֵּית֖וֹ וַיֵּחָנַ֑ק וַיָּ֕מָת וַיִּקָּבֵ֖ר בְּקֶ֥בֶר אָבִֽיו'),
(8474, 10, 'WLC', 'WLC', 'he', '2SA', 17, 24, 'OT', 'וְדָוִ֖ד בָּ֣א מַחֲנָ֑יְמָה וְאַבְשָׁלֹ֗ם עָבַר֙ אֶת הַיַּרְדֵּ֔ן ה֕וּא וְכָל אִ֥ישׁ יִשְׂרָאֵ֖ל עִמּֽוֹ'),
(8475, 10, 'WLC', 'WLC', 'he', '2SA', 17, 25, 'OT', 'וְאֶת עֲמָשָׂ֗א שָׂ֧ם אַבְשָׁלֹ֛ם תַּ֥חַת יוֹאָ֖ב עַל הַצָּבָ֑א וַעֲמָשָׂ֣א בֶן אִ֗ישׁ וּשְׁמוֹ֙ יִתְרָ֣א הַיִּשְׂרְאֵלִ֔י אֲשֶׁר בָּא֙ אֶל אֲבִיגַ֣ל בַּת נָחָ֔שׁ אֲח֥וֹת צְרוּיָ֖ה אֵ֥ם יוֹאָֽב'),
(8476, 10, 'WLC', 'WLC', 'he', '2SA', 17, 26, 'OT', 'וַיִּ֤חַן יִשְׂרָאֵל֙ וְאַבְשָׁלֹ֔ם אֶ֖רֶץ הַגִּלְעָֽד'),
(8477, 10, 'WLC', 'WLC', 'he', '2SA', 17, 27, 'OT', 'וַיְהִ֕י כְּב֥וֹא דָוִ֖ד מַחֲנָ֑יְמָה וְשֹׁבִ֨י בֶן נָחָ֜שׁ מֵרַבַּ֣ת בְּנֵֽי עַמּ֗וֹן וּמָכִ֤יר בֶּן עַמִּיאֵל֙ מִלֹּ֣א דְבָ֔ר וּבַרְזִלַּ֥י הַגִּלְעָדִ֖י מֵרֹגְלִֽים'),
(8478, 10, 'WLC', 'WLC', 'he', '2SA', 17, 28, 'OT', 'מִשְׁכָּ֤ב וְסַפּוֹת֙ וּכְלִ֣י יוֹצֵ֔ר וְחִטִּ֥ים וּשְׂעֹרִ֖ים וְקֶ֣מַח וְקָלִ֑י וּפ֥וֹל וַעֲדָשִׁ֖ים וְקָלִֽי'),
(8479, 10, 'WLC', 'WLC', 'he', '2SA', 17, 29, 'OT', 'וּדְבַ֣שׁ וְחֶמְאָ֗ה וְצֹאן֙ וּשְׁפ֣וֹת בָּקָ֔ר הִגִּ֧ישׁוּ לְדָוִ֛ד וְלָעָ֥ם אֲשֶׁר אִתּ֖וֹ לֶאֱכ֑וֹל כִּ֣י אָמְר֔וּ הָעָ֗ם רָעֵ֛ב וְעָיֵ֥ף וְצָמֵ֖א בַּמִּדְבָּֽר'),
(8480, 10, 'WLC', 'WLC', 'he', '2SA', 18, 1, 'OT', 'וַיִּפְקֹ֣ד דָּוִ֔ד אֶת הָעָ֖ם אֲשֶׁ֣ר אִתּ֑וֹ וַיָּ֣שֶׂם עֲלֵיהֶ֔ם שָׂרֵ֥י אֲלָפִ֖ים וְשָׂרֵ֥י מֵאֽוֹת'),
(8481, 10, 'WLC', 'WLC', 'he', '2SA', 18, 2, 'OT', 'וַיְשַׁלַּ֨ח דָּוִ֜ד אֶת הָעָ֗ם הַשְּׁלִשִׁ֤ית בְּיַד יוֹאָב֙ וְ֠הַשְּׁלִשִׁית בְּיַ֨ד אֲבִישַׁ֤י בֶּן צְרוּיָה֙ אֲחִ֣י יוֹאָ֔ב וְהַ֨שְּׁלִשִׁ֔ת בְּיַ֖ד אִתַּ֣י הַגִּתִּ֑י וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ אֶל הָעָ֔ם יָצֹ֥א אֵצֵ֛א גַּם אֲנִ֖י עִמָּכֶֽם'),
(8482, 10, 'WLC', 'WLC', 'he', '2SA', 18, 3, 'OT', 'וַיֹּ֨אמֶר הָעָ֜ם לֹ֣א תֵצֵ֗א כִּי֩ אִם נֹ֨ס נָנ֜וּס לֹא יָשִׂ֧ימוּ אֵלֵ֣ינוּ לֵ֗ב וְאִם יָמֻ֤תוּ חֶצְיֵ֨נוּ֙ לֹֽא יָשִׂ֤ימוּ אֵלֵ֨ינוּ֙ לֵ֔ב כִּֽי עַתָּ֥ה כָמֹ֖נוּ עֲשָׂרָ֣ה אֲלָפִ֑ים וְעַתָּ֣ה ט֔וֹב כִּי תִֽהְיֶה לָּ֥נוּ מֵעִ֖יר לעזיר'),
(8483, 10, 'WLC', 'WLC', 'he', '2SA', 18, 4, 'OT', 'וַיֹּ֤אמֶר אֲלֵיהֶם֙ הַמֶּ֔לֶךְ אֲשֶׁר יִיטַ֥ב בְּעֵינֵיכֶ֖ם אֶעֱשֶׂ֑ה וַיַּעֲמֹ֤ד הַמֶּ֨לֶךְ֙ אֶל יַ֣ד הַשַּׁ֔עַר וְכָל הָעָם֙ יָֽצְא֔וּ לְמֵא֖וֹת וְלַאֲלָפִֽים'),
(8484, 10, 'WLC', 'WLC', 'he', '2SA', 18, 5, 'OT', 'וַיְצַ֣ו הַמֶּ֡לֶךְ אֶת י֠וֹאָב וְאֶת אֲבִישַׁ֤י וְאֶת אִתַּי֙ לֵאמֹ֔ר לְאַט לִ֖י לַנַּ֣עַר לְאַבְשָׁל֑וֹם וְכָל הָעָ֣ם שָׁמְע֗וּ בְּצַוֺּ֥ת הַמֶּ֛לֶךְ אֶת כָּל הַשָּׂרִ֖ים עַל דְּבַ֥ר אַבְשָׁלֽוֹם'),
(8485, 10, 'WLC', 'WLC', 'he', '2SA', 18, 6, 'OT', 'וַיֵּצֵ֥א הָעָ֛ם הַשָּׂדֶ֖ה לִקְרַ֣את יִשְׂרָאֵ֑ל וַתְּהִ֥י הַמִּלְחָמָ֖ה בְּיַ֥עַר אֶפְרָֽיִם'),
(8486, 10, 'WLC', 'WLC', 'he', '2SA', 18, 7, 'OT', 'וַיִּנָּ֤גְפוּ שָׁם֙ עַ֣ם יִשְׂרָאֵ֔ל לִפְנֵ֖י עַבְדֵ֣י דָוִ֑ד וַתְּהִי שָׁ֞ם הַמַּגֵּפָ֧ה גְדוֹלָ֛ה בַּיּ֥וֹם הַה֖וּא עֶשְׂרִ֥ים אָֽלֶף'),
(8487, 10, 'WLC', 'WLC', 'he', '2SA', 18, 8, 'OT', 'וַתְּהִי שָׁ֧ם הַמִּלְחָמָ֛ה נפצית עַל פְּנֵ֣י כָל הָאָ֑רֶץ וַיֶּ֤רֶב הַיַּ֨עַר֙ לֶאֱכֹ֣ל בָּעָ֔ם מֵאֲשֶׁ֥ר אָכְלָ֛ה הַחֶ֖רֶב בַּיּ֥וֹם הַהֽוּא'),
(8488, 10, 'WLC', 'WLC', 'he', '2SA', 18, 9, 'OT', 'וַיִּקָּרֵא֙ אַבְשָׁל֔וֹם לִפְנֵ֖י עַבְדֵ֣י דָוִ֑ד וְאַבְשָׁל֞וֹם רֹכֵ֣ב עַל הַפֶּ֗רֶד וַיָּבֹ֣א הַפֶּ֡רֶד תַּ֣חַת שׂוֹבֶךְ֩ הָאֵלָ֨ה הַגְּדוֹלָ֜ה וַיֶּחֱזַ֧ק רֹאשׁ֣וֹ בָאֵלָ֗ה וַיֻּתַּן֙ בֵּ֤ין הַשָּׁמַ֨יִם֙ וּבֵ֣ין הָאָ֔רֶץ וְהַפֶּ֥רֶד אֲשֶׁר תַּחְתָּ֖יו עָבָֽר'),
(8489, 10, 'WLC', 'WLC', 'he', '2SA', 18, 10, 'OT', 'וַיַּרְא֙ אִ֣ישׁ אֶחָ֔ד וַיַּגֵּ֖ד לְיוֹאָ֑ב וַיֹּ֗אמֶר הִנֵּה֙ רָאִ֣יתִי אֶת אַבְשָׁלֹ֔ם תָּל֖וּי בָּאֵלָֽה'),
(8490, 10, 'WLC', 'WLC', 'he', '2SA', 18, 11, 'OT', 'וַיֹּ֣אמֶר יוֹאָ֗ב לָאִישׁ֙ הַמַּגִּ֣יד ל֔וֹ וְהִנֵּ֣ה רָאִ֔יתָ וּמַדּ֛וּעַ לֹֽא הִכִּית֥וֹ שָׁ֖ם אָ֑רְצָה וְעָלַ֗י לָ֤תֶת לְךָ֙ עֲשָׂ֣רָה כֶ֔סֶף וַחֲגֹרָ֖ה אֶחָֽת'),
(8491, 10, 'WLC', 'WLC', 'he', '2SA', 18, 12, 'OT', 'וַיֹּ֤אמֶר הָאִישׁ֙ אֶל יוֹאָ֔ב ולא אָנֹכִ֜י שֹׁקֵ֤ל עַל כַּפַּי֙ אֶ֣לֶף כֶּ֔סֶף לֹֽא אֶשְׁלַ֥ח יָדִ֖י אֶל בֶּן הַמֶּ֑לֶךְ כִּ֣י בְאָזְנֵ֜ינוּ צִוָּ֣ה הַמֶּ֗לֶךְ אֹ֠תְךָ וְאֶת אֲבִישַׁ֤י וְאֶת אִתַּי֙ לֵאמֹ֔ר שִׁמְרוּ מִ֕י בַּנַּ֖עַר בְּאַבְשָׁלֽוֹם'),
(8492, 10, 'WLC', 'WLC', 'he', '2SA', 18, 13, 'OT', 'אֽוֹ עָשִׂ֤יתִי בנפשו שֶׁ֔קֶר וְכָל דָּבָ֖ר לֹא יִכָּחֵ֣ד מִן הַמֶּ֑לֶךְ וְאַתָּ֖ה תִּתְיַצֵּ֥ב מִנֶּֽגֶד'),
(8493, 10, 'WLC', 'WLC', 'he', '2SA', 18, 14, 'OT', 'וַיֹּ֣אמֶר יוֹאָ֔ב לֹא כֵ֖ן אֹחִ֣ילָה לְפָנֶ֑יךָ וַיִּקַּח֩ שְׁלֹשָׁ֨ה שְׁבָטִ֜ים בְּכַפּ֗וֹ וַיִּתְקָעֵם֙ בְּלֵ֣ב אַבְשָׁל֔וֹם עוֹדֶ֥נּוּ חַ֖י בְּלֵ֥ב הָאֵלָֽה'),
(8494, 10, 'WLC', 'WLC', 'he', '2SA', 18, 15, 'OT', 'וַיָּסֹ֨בּוּ֙ עֲשָׂרָ֣ה נְעָרִ֔ים נֹשְׂאֵ֖י כְּלֵ֣י יוֹאָ֑ב וַיַּכּ֥וּ אֶת אַבְשָׁל֖וֹם וַיְמִיתֻֽהוּ'),
(8495, 10, 'WLC', 'WLC', 'he', '2SA', 18, 16, 'OT', 'וַיִּתְקַ֤ע יוֹאָב֙ בַּשֹּׁפָ֔ר וַיָּ֣שָׁב הָעָ֔ם מִרְדֹ֖ף אַחֲרֵ֣י יִשְׂרָאֵ֑ל כִּֽי חָשַׂ֥ךְ יוֹאָ֖ב אֶת הָעָֽם'),
(8496, 10, 'WLC', 'WLC', 'he', '2SA', 18, 17, 'OT', 'וַיִּקְח֣וּ אֶת אַבְשָׁל֗וֹם וַיַּשְׁלִ֨יכוּ אֹת֤וֹ בַיַּ֨עַר֙ אֶל הַפַּ֣חַת הַגָּד֔וֹל וַיַּצִּ֧בוּ עָלָ֛יו גַּל אֲבָנִ֖ים גָּד֣וֹל מְאֹ֑ד וְכָל יִשְׂרָאֵ֔ל נָ֖סוּ אִ֥ישׁ לאהלו'),
(8497, 10, 'WLC', 'WLC', 'he', '2SA', 18, 18, 'OT', 'וְאַבְשָׁלֹ֣ם לָקַ֗ח וַיַּצֶּב ל֤וֹ בחיו אֶת מַצֶּ֨בֶת֙ אֲשֶׁ֣ר בְּעֵֽמֶק הַמֶּ֔לֶךְ כִּ֤י אָמַר֙ אֵֽין לִ֣י בֵ֔ן בַּעֲב֖וּר הַזְכִּ֣יר שְׁמִ֑י וַיִּקְרָ֤א לַמַּצֶּ֨בֶת֙ עַל שְׁמ֔וֹ וַיִּקָּ֤רֵא לָהּ֙ יַ֣ד אַבְשָׁלֹ֔ם עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(8498, 10, 'WLC', 'WLC', 'he', '2SA', 18, 19, 'OT', 'וַאֲחִימַ֤עַץ בֶּן צָדוֹק֙ אָמַ֔ר אָר֣וּצָה נָּ֔א וַאֲבַשְּׂרָ֖ה אֶת הַמֶּ֑לֶךְ כִּי שְׁפָט֥וֹ יְהוָ֖ה מִיַּ֥ד אֹיְבָֽיו'),
(8499, 10, 'WLC', 'WLC', 'he', '2SA', 18, 20, 'OT', 'וַיֹּ֧אמֶר ל֣וֹ יוֹאָ֗ב לֹא֩ אִ֨ישׁ בְּשֹׂרָ֤ה אַתָּה֙ הַיּ֣וֹם הַזֶּ֔ה וּבִשַּׂרְתָּ֖ בְּי֣וֹם אַחֵ֑ר וְהַיּ֤וֹם הַזֶּה֙ לֹ֣א תְבַשֵּׂ֔ר כִּֽי על בֶּן הַמֶּ֖לֶךְ מֵֽת'),
(8500, 10, 'WLC', 'WLC', 'he', '2SA', 18, 21, 'OT', 'וַיֹּ֤אמֶר יוֹאָב֙ לַכּוּשִׁ֔י לֵ֛ךְ הַגֵּ֥ד לַמֶּ֖לֶךְ אֲשֶׁ֣ר רָאִ֑יתָה וַיִּשְׁתַּ֧חוּ כוּשִׁ֛י לְיוֹאָ֖ב וַיָּרֹֽץ'),
(8501, 10, 'WLC', 'WLC', 'he', '2SA', 18, 22, 'OT', 'וַיֹּ֨סֶף ע֜וֹד אֲחִימַ֤עַץ בֶּן צָדוֹק֙ וַיֹּ֣אמֶר אֶל יוֹאָ֔ב וִ֣יהִי מָ֔ה אָרֻֽצָה נָּ֥א גַם אָ֖נִי אַחֲרֵ֣י הַכּוּשִׁ֑י וַיֹּ֣אמֶר יוֹאָ֗ב לָֽמָּה זֶּ֞ה אַתָּ֥ה רָץ֙ בְּנִ֔י וּלְכָ֖ה אֵין בְּשׂוֹרָ֥ה מֹצֵֽאת'),
(8502, 10, 'WLC', 'WLC', 'he', '2SA', 18, 23, 'OT', 'וִיהִי מָ֣ה אָר֔וּץ וַיֹּ֥אמֶר ל֖וֹ ר֑וּץ וַיָּ֤רָץ אֲחִימַ֨עַץ֙ דֶּ֣רֶךְ הַכִּכָּ֔ר וַֽיַּעֲבֹ֖ר אֶת הַכּוּשִֽׁי'),
(8503, 10, 'WLC', 'WLC', 'he', '2SA', 18, 24, 'OT', 'וְדָוִ֥ד יוֹשֵׁ֖ב בֵּין שְׁנֵ֣י הַשְּׁעָרִ֑ים וַיֵּ֨לֶךְ הַצֹּפֶ֜ה אֶל גַּ֤ג הַשַּׁ֨עַר֙ אֶל הַ֣חוֹמָ֔ה וַיִּשָּׂ֤א אֶת עֵינָיו֙ וַיַּ֔רְא וְהִנֵּה אִ֖ישׁ רָ֥ץ לְבַדּֽוֹ'),
(8504, 10, 'WLC', 'WLC', 'he', '2SA', 18, 25, 'OT', 'וַיִּקְרָ֤א הַצֹּפֶה֙ וַיַּגֵּ֣ד לַמֶּ֔לֶךְ וַיֹּ֣אמֶר הַמֶּ֔לֶךְ אִם לְבַדּ֖וֹ בְּשׂוֹרָ֣ה בְּפִ֑יו וַיֵּ֥לֶךְ הָל֖וֹךְ וְקָרֵֽב'),
(8505, 10, 'WLC', 'WLC', 'he', '2SA', 18, 26, 'OT', 'וַיַּ֣רְא הַצֹּפֶה֮ אִישׁ אַחֵ֣ר רָץ֒ וַיִּקְרָ֤א הַצֹּפֶה֙ אֶל הַשֹּׁעֵ֔ר וַיֹּ֕אמֶר הִנֵּה אִ֖ישׁ רָ֣ץ לְבַדּ֑וֹ וַיֹּ֥אמֶר הַמֶּ֖לֶךְ גַּם זֶ֥ה מְבַשֵּֽׂר'),
(8506, 10, 'WLC', 'WLC', 'he', '2SA', 18, 27, 'OT', 'וַיֹּ֨אמֶר֙ הַצֹּפֶ֔ה אֲנִ֤י רֹאֶה֙ אֶת מְרוּצַ֣ת הָרִאשׁ֔וֹן כִּמְרֻצַ֖ת אֲחִימַ֣עַץ בֶּן צָד֑וֹק וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ אִֽישׁ ט֣וֹב זֶ֔ה וְאֶל בְּשׂוֹרָ֥ה טוֹבָ֖ה יָבֽוֹא'),
(8507, 10, 'WLC', 'WLC', 'he', '2SA', 18, 28, 'OT', 'וַיִּקְרָ֣א אֲחִימַ֗עַץ וַיֹּ֤אמֶר אֶל הַמֶּ֨לֶךְ֙ שָׁל֔וֹם וַיִּשְׁתַּ֧חוּ לַמֶּ֛לֶךְ לְאַפָּ֖יו אָ֑רְצָה וַיֹּ֗אמֶר בָּרוּךְ֙ יְהוָ֣ה אֱלֹהֶ֔יךָ אֲשֶׁ֤ר סִגַּר֙ אֶת הָ֣אֲנָשִׁ֔ים אֲשֶׁר נָשְׂא֥וּ אֶת יָדָ֖ם בַּֽאדֹנִ֥י הַמֶּֽלֶךְ'),
(8508, 10, 'WLC', 'WLC', 'he', '2SA', 18, 29, 'OT', 'וַיֹּ֣אמֶר הַמֶּ֔לֶךְ שָׁל֥וֹם לַנַּ֖עַר לְאַבְשָׁל֑וֹם וַיֹּ֣אמֶר אֲחִימַ֡עַץ רָאִיתִי֩ הֶהָמ֨וֹן הַגָּד֜וֹל לִ֠שְׁלֹחַ אֶת עֶ֨בֶד הַמֶּ֤לֶךְ יוֹאָב֙ וְאֶת עַבְדֶּ֔ךָ וְלֹ֥א יָדַ֖עְתִּי מָֽה'),
(8509, 10, 'WLC', 'WLC', 'he', '2SA', 18, 30, 'OT', 'וַיֹּ֣אמֶר הַמֶּ֔לֶךְ סֹ֖ב הִתְיַצֵּ֣ב כֹּ֑ה וַיִּסֹּ֖ב וַֽיַּעֲמֹֽד'),
(8510, 10, 'WLC', 'WLC', 'he', '2SA', 18, 31, 'OT', 'וְהִנֵּ֥ה הַכּוּשִׁ֖י בָּ֑א וַיֹּ֣אמֶר הַכּוּשִׁ֗י יִתְבַּשֵּׂר֙ אֲדֹנִ֣י הַמֶּ֔לֶךְ כִּֽי שְׁפָטְךָ֤ יְהוָה֙ הַיּ֔וֹם מִיַּ֖ד כָּל הַקָּמִ֥ים עָלֶֽיךָ'),
(8511, 10, 'WLC', 'WLC', 'he', '2SA', 18, 32, 'OT', 'וַיֹּ֤אמֶר הַמֶּ֨לֶךְ֙ אֶל הַכּוּשִׁ֔י הֲשָׁל֥וֹם לַנַּ֖עַר לְאַבְשָׁל֑וֹם וַיֹּ֣אמֶר הַכּוּשִׁ֗י יִהְי֤וּ כַנַּ֨עַר֙ אֹֽיְבֵי֙ אֲדֹנִ֣י הַמֶּ֔לֶךְ וְכֹ֛ל אֲשֶׁר קָ֥מוּ עָלֶ֖יךָ לְרָעָֽה'),
(8512, 10, 'WLC', 'WLC', 'he', '2SA', 18, 33, 'OT', 'וַיִּרְגַּ֣ז הַמֶּ֗לֶךְ וַיַּ֛עַל עַל עֲלִיַּ֥ת הַשַּׁ֖עַר וַיֵּ֑בְךְּ וְכֹ֣ה אָמַ֣ר בְּלֶכְתּ֗וֹ בְּנִ֤י אַבְשָׁלוֹם֙ בְּנִ֣י בְנִ֣י אַבְשָׁל֔וֹם מִֽי יִתֵּ֤ן מוּתִי֙ אֲנִ֣י תַחְתֶּ֔יךָ אַבְשָׁל֖וֹם בְּנִ֥י בְנִֽי'),
(8513, 10, 'WLC', 'WLC', 'he', '2SA', 19, 1, 'OT', 'וַיֻּגַּ֖ד לְיוֹאָ֑ב הִנֵּ֨ה הַמֶּ֧לֶךְ בֹּכֶ֛ה וַיִּתְאַבֵּ֖ל עַל אַבְשָׁלֹֽם'),
(8514, 10, 'WLC', 'WLC', 'he', '2SA', 19, 2, 'OT', 'וַתְּהִ֨י הַתְּשֻׁעָ֜ה בַּיּ֥וֹם הַה֛וּא לְאֵ֖בֶל לְכָל הָעָ֑ם כִּֽי שָׁמַ֣ע הָעָ֗ם בַּיּ֤וֹם הַהוּא֙ לֵאמֹ֔ר נֶעֱצַ֥ב הַמֶּ֖לֶךְ עַל בְּנֽוֹ'),
