(8547, 10, 'WLC', 'WLC', 'he', '2SA', 19, 35, 'OT', 'בֶּן שְׁמֹנִ֣ים שָׁנָה֩ אָנֹכִ֨י הַיּ֜וֹם הַאֵדַ֣ע בֵּין ט֣וֹב לְרָ֗ע אִם יִטְעַ֤ם עַבְדְּךָ֙ אֶת אֲשֶׁ֤ר אֹכַל֙ וְאֶת אֲשֶׁ֣ר אֶשְׁתֶּ֔ה אִם אֶשְׁמַ֣ע ע֔וֹד בְּק֖וֹל שָׁרִ֣ים וְשָׁר֑וֹת וְלָמָּה֩ יִֽהְיֶ֨ה עַבְדְּךָ֥ עוֹד֙ לְמַשָּׂ֔א אֶל אֲדֹנִ֖י הַמֶּֽלֶךְ'),
(8548, 10, 'WLC', 'WLC', 'he', '2SA', 19, 36, 'OT', 'כִּמְעַ֞ט יַעֲבֹ֧ר עַבְדְּךָ֛ אֶת הַיַּרְדֵּ֖ן אֶת הַמֶּ֑לֶךְ וְלָ֨מָּה֙ יִגְמְלֵ֣נִי הַמֶּ֔לֶךְ הַגְּמוּלָ֖ה הַזֹּֽאת'),
(8549, 10, 'WLC', 'WLC', 'he', '2SA', 19, 37, 'OT', 'יָֽשָׁב נָ֤א עַבְדְּךָ֙ וְאָמֻ֣ת בְּעִירִ֔י עִ֛ם קֶ֥בֶר אָבִ֖י וְאִמִּ֑י וְהִנֵּ֣ה עַבְדְּךָ֣ כִמְהָ֗ם יַֽעֲבֹר֙ עִם אֲדֹנִ֣י הַמֶּ֔לֶךְ וַעֲשֵׂה ל֕וֹ אֵ֥ת אֲשֶׁר ט֖וֹב בְּעֵינֶֽיךָ'),
(8550, 10, 'WLC', 'WLC', 'he', '2SA', 19, 38, 'OT', 'וַיֹּ֣אמֶר הַמֶּ֗לֶךְ אִתִּי֙ יַעֲבֹ֣ר כִּמְהָ֔ם וַאֲנִי֙ אֶעֱשֶׂה לּ֔וֹ אֶת הַטּ֖וֹב בְּעֵינֶ֑יךָ וְכֹ֛ל אֲשֶׁר תִּבְחַ֥ר עָלַ֖י אֶֽעֱשֶׂה לָּֽךְ'),
(8551, 10, 'WLC', 'WLC', 'he', '2SA', 19, 39, 'OT', 'וַיַּעֲבֹ֧ר כָּל הָעָ֛ם אֶת הַיַּרְדֵּ֖ן וְהַמֶּ֣לֶךְ עָבָ֑ר וַיִּשַּׁ֨ק הַמֶּ֤לֶךְ לְבַרְזִלַּי֙ וַיְבָ֣רֲכֵ֔הוּ וַיָּ֖שָׁב לִמְקֹמֽוֹ'),
(8552, 10, 'WLC', 'WLC', 'he', '2SA', 19, 40, 'OT', 'וַיַּעֲבֹ֤ר הַמֶּ֨לֶךְ֙ הַגִּלְגָּ֔לָה וְכִמְהָ֖ן עָבַ֣ר עִמּ֑וֹ וְכָל עַ֤ם יְהוּדָה֙ ויעברו אֶת הַמֶּ֔לֶךְ וְגַ֕ם חֲצִ֖י עַ֥ם יִשְׂרָאֵֽל'),
(8553, 10, 'WLC', 'WLC', 'he', '2SA', 19, 41, 'OT', 'וְהִנֵּ֛ה כָּל אִ֥ישׁ יִשְׂרָאֵ֖ל בָּאִ֣ים אֶל הַמֶּ֑לֶךְ וַיֹּאמְר֣וּ אֶל הַמֶּ֡לֶךְ מַדּוּעַ֩ גְּנָב֨וּךָ אַחֵ֜ינוּ אִ֣ישׁ יְהוּדָ֗ה וַיַּעֲבִ֨רוּ אֶת הַמֶּ֤לֶךְ וְאֶת בֵּיתוֹ֙ אֶת הַיַּרְדֵּ֔ן וְכָל אַנְשֵׁ֥י דָוִ֖ד עִמּֽוֹ'),
(8554, 10, 'WLC', 'WLC', 'he', '2SA', 19, 42, 'OT', 'וַיַּעַן֩ כָּל אִ֨ישׁ יְהוּדָ֜ה עַל אִ֣ישׁ יִשְׂרָאֵ֗ל כִּֽי קָר֤וֹב הַמֶּ֨לֶךְ֙ אֵלַ֔י וְלָ֤מָּה זֶּה֙ חָרָ֣ה לְךָ֔ עַל הַדָּבָ֖ר הַזֶּ֑ה הֶאָכ֤וֹל אָכַ֨לְנוּ֙ מִן הַמֶּ֔לֶךְ אִם נִשֵּׂ֥את נִשָּׂ֖א לָֽנוּ'),
(8555, 10, 'WLC', 'WLC', 'he', '2SA', 19, 43, 'OT', 'וַיַּ֣עַן אִֽישׁ יִשְׂרָאֵל֩ אֶת אִ֨ישׁ יְהוּדָ֜ה וַיֹּ֗אמֶר עֶֽשֶׂר יָד֨וֹת לִ֣י בַמֶּלֶךְ֮ וְגַם בְּדָוִד֮ אֲנִ֣י מִמְּךָ֒ וּמַדּ֨וּעַ֙ הֱקִלֹּתַ֔נִי וְלֹא הָיָ֨ה דְבָרִ֥י רִאשׁ֛וֹן לִ֖י לְהָשִׁ֣יב אֶת מַלְכִּ֑י וַיִּ֨קֶשׁ֙ דְּבַר אִ֣ישׁ יְהוּדָ֔ה מִדְּבַ֖ר אִ֥ישׁ יִשְׂרָאֵֽל'),
(8556, 10, 'WLC', 'WLC', 'he', '2SA', 20, 1, 'OT', 'וְשָׁ֨ם נִקְרָ֜א אִ֣ישׁ בְּלִיַּ֗עַל וּשְׁמ֛וֹ שֶׁ֥בַע בֶּן בִּכְרִ֖י אִ֣ישׁ יְמִינִ֑י וַיִּתְקַ֣ע בַּשֹּׁפָ֗ר וַ֠יֹּאמֶר אֵֽין לָ֨נוּ חֵ֜לֶק בְּדָוִ֗ד וְלֹ֤א נַֽחֲלָה לָ֨נוּ֙ בְּבֶן יִשַׁ֔י אִ֥ישׁ לְאֹהָלָ֖יו יִשְׂרָאֵֽל'),
