(9201, 11, 'WLC', 'WLC', 'he', '1KI', 13, 16, 'OT', 'וַיֹּ֗אמֶר לֹ֥א אוּכַ֛ל לָשׁ֥וּב אִתָּ֖ךְ וְלָב֣וֹא אִתָּ֑ךְ וְלֹֽא אֹ֣כַל לֶ֗חֶם וְלֹֽא אֶשְׁתֶּ֤ה אִתְּךָ֙ מַ֔יִם בַּמָּק֖וֹם הַזֶּֽה'),
(9202, 11, 'WLC', 'WLC', 'he', '1KI', 13, 17, 'OT', 'כִּֽי דָבָ֤ר אֵלַי֙ בִּדְבַ֣ר יְהוָ֔ה לֹֽא תֹאכַ֣ל לֶ֔חֶם וְלֹֽא תִשְׁתֶּ֥ה שָׁ֖ם מָ֑יִם לֹא תָשׁ֣וּב לָלֶ֔כֶת בַּדֶּ֖רֶךְ אֲשֶׁר הָלַ֥כְתָּ בָּֽהּ'),
(9203, 11, 'WLC', 'WLC', 'he', '1KI', 13, 18, 'OT', 'וַיֹּ֣אמֶר ל֗וֹ גַּם אֲנִ֣י נָבִיא֮ כָּמוֹךָ֒ וּמַלְאָ֡ךְ דִּבֶּ֣ר אֵלַי֩ בִּדְבַ֨ר יְהוָ֜ה לֵאמֹ֗ר הֲשִׁבֵ֤הוּ אִתְּךָ֙ אֶל בֵּיתֶ֔ךָ וְיֹ֥אכַל לֶ֖חֶם וְיֵ֣שְׁתְּ מָ֑יִם כִּחֵ֖שׁ לֽוֹ'),
(9204, 11, 'WLC', 'WLC', 'he', '1KI', 13, 19, 'OT', 'וַיָּ֣שָׁב אִתּ֗וֹ וַיֹּ֥אכַל לֶ֛חֶם בְּבֵית֖וֹ וַיֵּ֥שְׁתְּ מָֽיִם'),
(9205, 11, 'WLC', 'WLC', 'he', '1KI', 13, 20, 'OT', 'וַיְהִ֕י הֵ֥ם יֹשְׁבִ֖ים אֶל הַשֻּׁלְחָ֑ן וַֽיְהִי֙ דְּבַר יְהוָ֔ה אֶל הַנָּבִ֖יא אֲשֶׁ֥ר הֱשִׁיבֽוֹ'),
(9206, 11, 'WLC', 'WLC', 'he', '1KI', 13, 21, 'OT', 'וַיִּקְרָ֞א אֶל אִ֣ישׁ הָאֱלֹהִ֗ים אֲשֶׁר בָּ֤א מִֽיהוּדָה֙ לֵאמֹ֔ר כֹּ֖ה אָמַ֣ר יְהוָ֑ה יַ֗עַן כִּ֤י מָרִ֨יתָ֙ פִּ֣י יְהוָ֔ה וְלֹ֤א שָׁמַ֨רְתָּ֙ אֶת הַמִּצְוָ֔ה אֲשֶׁ֥ר צִוְּךָ֖ יְהוָ֥ה אֱלֹהֶֽיךָ'),
(9207, 11, 'WLC', 'WLC', 'he', '1KI', 13, 22, 'OT', 'וַתָּ֗שָׁב וַתֹּ֤אכַל לֶ֨חֶם֙ וַתֵּ֣שְׁתְּ מַ֔יִם בַּמָּקוֹם֙ אֲשֶׁ֣ר דִּבֶּ֣ר אֵלֶ֔יךָ אַל תֹּ֥אכַל לֶ֖חֶם וְאַל תֵּ֣שְׁתְּ מָ֑יִם לֹֽא תָב֥וֹא נִבְלָתְךָ֖ אֶל קֶ֥בֶר אֲבֹתֶֽיךָ'),
(9208, 11, 'WLC', 'WLC', 'he', '1KI', 13, 23, 'OT', 'וַיְהִ֗י אַחֲרֵ֛י אָכְל֥וֹ לֶ֖חֶם וְאַחֲרֵ֣י שְׁתוֹת֑וֹ וַיַּחֲבָשׁ ל֣וֹ הַחֲמ֔וֹר לַנָּבִ֖יא אֲשֶׁ֥ר הֱשִׁיבֽוֹ'),
(9209, 11, 'WLC', 'WLC', 'he', '1KI', 13, 24, 'OT', 'וַיֵּ֕לֶךְ וַיִּמְצָאֵ֧הוּ אַרְיֵ֛ה בַּדֶּ֖רֶךְ וַיְמִיתֵ֑הוּ וַתְּהִ֤י נִבְלָתוֹ֙ מֻשְׁלֶ֣כֶת בַּדֶּ֔רֶךְ וְהַחֲמוֹר֙ עֹמֵ֣ד אֶצְלָ֔הּ וְהָ֣אַרְיֵ֔ה עֹמֵ֖ד אֵ֥צֶל הַנְּבֵלָֽה'),
(9210, 11, 'WLC', 'WLC', 'he', '1KI', 13, 25, 'OT', 'וְהִנֵּ֧ה אֲנָשִׁ֣ים עֹבְרִ֗ים וַיִּרְא֤וּ אֶת הַנְּבֵלָה֙ מֻשְׁלֶ֣כֶת בַּדֶּ֔רֶךְ וְאֶת הָ֣אַרְיֵ֔ה עֹמֵ֖ד אֵ֣צֶל הַנְּבֵלָ֑ה וַיָּבֹ֨אוּ֙ וַיְדַבְּר֣וּ בָעִ֔יר אֲשֶׁ֛ר הַנָּבִ֥יא הַזָּקֵ֖ן יֹשֵׁ֥ב בָּֽהּ'),
(9211, 11, 'WLC', 'WLC', 'he', '1KI', 13, 26, 'OT', 'וַיִּשְׁמַ֣ע הַנָּבִיא֮ אֲשֶׁ֣ר הֱשִׁיב֣וֹ מִן הַדֶּרֶךְ֒ וַיֹּ֨אמֶר֙ אִ֣ישׁ הָאֱלֹהִ֣ים ה֔וּא אֲשֶׁ֥ר מָרָ֖ה אֶת פִּ֣י יְהוָ֑ה וַיִּתְּנֵ֨הוּ יְהוָ֜ה לָאַרְיֵ֗ה וַֽיִּשְׁבְּרֵ֨הוּ֙ וַיְמִתֵ֔הוּ כִּדְבַ֥ר יְהוָ֖ה אֲשֶׁ֥ר דִּבֶּר לֽוֹ'),
(9212, 11, 'WLC', 'WLC', 'he', '1KI', 13, 27, 'OT', 'וַיְדַבֵּ֤ר אֶל בָּנָיו֙ לֵאמֹ֔ר חִבְשׁוּ לִ֖י אֶֽת הַחֲמ֑וֹר וַֽיַּחֲבֹֽשׁוּ'),
