(9407, 11, 'WLC', 'WLC', 'he', '1KI', 19, 19, 'OT', 'וַיֵּ֣לֶךְ מִ֠שָּׁם וַיִּמְצָ֞א אֶת אֱלִישָׁ֤ע בֶּן שָׁפָט֙ וְה֣וּא חֹרֵ֔שׁ שְׁנֵים עָשָׂ֤ר צְמָדִים֙ לְפָנָ֔יו וְה֖וּא בִּשְׁנֵ֣ים הֶעָשָׂ֑ר וַיַּעֲבֹ֤ר אֵלִיָּ֨הוּ֙ אֵלָ֔יו וַיַּשְׁלֵ֥ךְ אַדַּרְתּ֖וֹ אֵלָֽיו'),
(9408, 11, 'WLC', 'WLC', 'he', '1KI', 19, 20, 'OT', 'וַיַּעֲזֹ֣ב אֶת הַבָּקָ֗ר וַיָּ֨רָץ֙ אַחֲרֵ֣י אֵֽלִיָּ֔הוּ וַיֹּ֗אמֶר אֶשְּׁקָה נָּא֙ לְאָבִ֣י וּלְאִמִּ֔י וְאֵלְכָ֖ה אַחֲרֶ֑יךָ וַיֹּ֤אמֶר לוֹ֙ לֵ֣ךְ שׁ֔וּב כִּ֥י מֶה עָשִׂ֖יתִי לָֽךְ'),
(9409, 11, 'WLC', 'WLC', 'he', '1KI', 19, 21, 'OT', 'וַיָּ֨שָׁב מֵאַחֲרָ֜יו וַיִּקַּ֣ח אֶת צֶ֧מֶד הַבָּקָ֣ר וַיִּזְבָּחֵ֗הוּ וּבִכְלִ֤י הַבָּקָר֙ בִּשְּׁלָ֣ם הַבָּשָׂ֔ר וַיִּתֵּ֥ן לָעָ֖ם וַיֹּאכֵ֑לוּ וַיָּ֗קָם וַיֵּ֛לֶךְ אַחֲרֵ֥י אֵלִיָּ֖הוּ וַיְשָׁרְתֵֽהוּ'),
(9410, 11, 'WLC', 'WLC', 'he', '1KI', 20, 1, 'OT', 'וּבֶן הֲדַ֣ד מֶֽלֶךְ אֲרָ֗ם קָבַץ֙ אֶת כָּל חֵיל֔וֹ וּשְׁלֹשִׁ֨ים וּשְׁנַ֥יִם מֶ֛לֶךְ אִתּ֖וֹ וְס֣וּס וָרָ֑כֶב וַיַּ֗עַל וַיָּ֨צַר֙ עַל שֹׁ֣מְר֔וֹן וַיִּלָּ֖חֶם בָּֽהּ'),
(9411, 11, 'WLC', 'WLC', 'he', '1KI', 20, 2, 'OT', 'וַיִּשְׁלַ֧ח מַלְאָכִ֛ים אֶל אַחְאָ֥ב מֶֽלֶךְ יִשְׂרָאֵ֖ל הָעִֽירָה'),
(9412, 11, 'WLC', 'WLC', 'he', '1KI', 20, 3, 'OT', 'וַיֹּ֣אמֶר ל֗וֹ כֹּ֚ה אָמַ֣ר בֶּן הֲדַ֔ד כַּסְפְּךָ֥ וּֽזְהָבְךָ֖ לִֽי ה֑וּא וְנָשֶׁ֧יךָ וּבָנֶ֛יךָ הַטּוֹבִ֖ים לִי הֵֽם'),
(9413, 11, 'WLC', 'WLC', 'he', '1KI', 20, 4, 'OT', 'וַיַּ֤עַן מֶֽלֶךְ יִשְׂרָאֵל֙ וַיֹּ֔אמֶר כִּדְבָרְךָ֖ אֲדֹנִ֣י הַמֶּ֑לֶךְ לְךָ֥ אֲנִ֖י וְכָל אֲשֶׁר לִֽי'),
(9414, 11, 'WLC', 'WLC', 'he', '1KI', 20, 5, 'OT', 'וַיָּשֻׁ֨בוּ֙ הַמַּלְאָכִ֔ים וַיֹּ֣אמְר֔וּ כֹּֽה אָמַ֥ר בֶּן הֲדַ֖ד לֵאמֹ֑ר כִּֽי שָׁלַ֤חְתִּי אֵלֶ֨יךָ֙ לֵאמֹ֔ר כַּסְפְּךָ֧ וּזְהָבְךָ֛ וְנָשֶׁ֥יךָ וּבָנֶ֖יךָ לִ֥י תִתֵּֽן'),
(9415, 11, 'WLC', 'WLC', 'he', '1KI', 20, 6, 'OT', 'כִּ֣י אִם כָּעֵ֣ת מָחָ֗ר אֶשְׁלַ֤ח אֶת עֲבָדַי֙ אֵלֶ֔יךָ וְחִפְּשׂוּ֙ אֶת בֵּ֣יתְךָ֔ וְאֵ֖ת בָּתֵּ֣י עֲבָדֶ֑יךָ וְהָיָה֙ כָּל מַחְמַ֣ד עֵינֶ֔יךָ יָשִׂ֥ימוּ בְיָדָ֖ם וְלָקָֽחוּ'),
(9416, 11, 'WLC', 'WLC', 'he', '1KI', 20, 7, 'OT', 'וַיִּקְרָ֤א מֶֽלֶךְ יִשְׂרָאֵל֙ לְכָל זִקְנֵ֣י הָאָ֔רֶץ וַיֹּ֨אמֶר֙ דְּעֽוּ נָ֣א וּרְא֔וּ כִּ֥י רָעָ֖ה זֶ֣ה מְבַקֵּ֑שׁ כִּֽי שָׁלַ֨ח אֵלַ֜י לְנָשַׁ֤י וּלְבָנַי֙ וּלְכַסְפִּ֣י וְלִזְהָבִ֔י וְלֹ֥א מָנַ֖עְתִּי מִמֶּֽנּוּ'),
(9417, 11, 'WLC', 'WLC', 'he', '1KI', 20, 8, 'OT', 'וַיֹּאמְר֥וּ אֵלָ֛יו כָּל הַזְּקֵנִ֖ים וְכָל הָעָ֑ם אַל תִּשְׁמַ֖ע וְל֥וֹא תֹאבֶֽה'),
(9418, 11, 'WLC', 'WLC', 'he', '1KI', 20, 9, 'OT', 'וַיֹּ֜אמֶר לְמַלְאֲכֵ֣י בֶן הֲדַ֗ד אִמְר֞וּ לַֽאדֹנִ֤י הַמֶּ֨לֶךְ֙ כֹּל֩ אֲשֶׁר שָׁלַ֨חְתָּ אֶל עַבְדְּךָ֤ בָרִֽאשֹׁנָה֙ אֶעֱשֶׂ֔ה וְהַדָּבָ֣ר הַזֶּ֔ה לֹ֥א אוּכַ֖ל לַעֲשׂ֑וֹת וַיֵּֽלְכוּ֙ הַמַּלְאָכִ֔ים וַיְשִׁבֻ֖הוּ דָּבָֽר'),
(9419, 11, 'WLC', 'WLC', 'he', '1KI', 20, 10, 'OT', 'וַיִּשְׁלַ֤ח אֵלָיו֙ בֶּן הֲדַ֔ד וַיֹּ֕אמֶר כֹּֽה יַעֲשׂ֥וּן לִ֛י אֱלֹהִ֖ים וְכֹ֣ה יוֹסִ֑פוּ אִם יִשְׂפֹּק֙ עֲפַ֣ר שֹׁמְר֔וֹן לִשְׁעָלִ֕ים לְכָל הָעָ֖ם אֲשֶׁ֥ר בְּרַגְלָֽי'),
(9420, 11, 'WLC', 'WLC', 'he', '1KI', 20, 11, 'OT', 'וַיַּ֤עַן מֶֽלֶךְ יִשְׂרָאֵל֙ וַיֹּ֣אמֶר דַּבְּר֔וּ אַל יִתְהַלֵּ֥ל חֹגֵ֖ר כִּמְפַתֵּֽחַ'),
(9421, 11, 'WLC', 'WLC', 'he', '1KI', 20, 12, 'OT', 'וַיְהִ֗י כִּשְׁמֹ֨עַ֙ אֶת הַדָּבָ֣ר הַזֶּ֔ה וְה֥וּא שֹׁתֶ֛ה ה֥וּא וְהַמְּלָכִ֖ים בַּסֻּכּ֑וֹת וַיֹּ֤אמֶר אֶל עֲבָדָיו֙ שִׂ֔ימוּ וַיָּשִׂ֖ימוּ עַל הָעִֽיר'),
(9422, 11, 'WLC', 'WLC', 'he', '1KI', 20, 13, 'OT', 'וְהִנֵּ֣ה נָבִ֣יא אֶחָ֗ד נִגַּשׁ֮ אֶל אַחְאָ֣ב מֶֽלֶךְ יִשְׂרָאֵל֒ וַיֹּ֗אמֶר כֹּ֚ה אָמַ֣ר יְהוָ֔ה הְֽרָאִ֔יתָ אֵ֛ת כָּל הֶהָמ֥וֹן הַגָּד֖וֹל הַזֶּ֑ה הִנְנִ֨י נֹתְנ֤וֹ בְיָֽדְךָ֙ הַיּ֔וֹם וְיָדַעְתָּ֖ כִּֽי אֲנִ֥י יְהוָֽה'),
(9423, 11, 'WLC', 'WLC', 'he', '1KI', 20, 14, 'OT', 'וַיֹּ֤אמֶר אַחְאָב֙ בְּמִ֔י וַיֹּ֨אמֶר֙ כֹּֽה אָמַ֣ר יְהוָ֔ה בְּנַעֲרֵ֖י שָׂרֵ֣י הַמְּדִינ֑וֹת וַיֹּ֛אמֶר מִֽי יֶאְסֹ֥ר הַמִּלְחָמָ֖ה וַיֹּ֥אמֶר אָֽתָּה'),
(9424, 11, 'WLC', 'WLC', 'he', '1KI', 20, 15, 'OT', 'וַיִּפְקֹ֗ד אֶֽת נַעֲרֵי֙ שָׂרֵ֣י הַמְּדִינ֔וֹת וַיִּהְי֕וּ מָאתַ֖יִם שְׁנַ֣יִם וּשְׁלֹשִׁ֑ים וְאַחֲרֵיהֶ֗ם פָּקַ֧ד אֶת כָּל הָעָ֛ם כָּל בְּנֵ֥י יִשְׂרָאֵ֖ל שִׁבְעַ֥ת אֲלָפִֽים'),
(9425, 11, 'WLC', 'WLC', 'he', '1KI', 20, 16, 'OT', 'וַיֵּצְא֖וּ בַּֽצָּהֳרָ֑יִם וּבֶן הֲדַד֩ שֹׁתֶ֨ה שִׁכּ֜וֹר בַּסֻּכּ֗וֹת ה֧וּא וְהַמְּלָכִ֛ים שְׁלֹשִֽׁים וּשְׁנַ֥יִם מֶ֖לֶךְ עֹזֵ֥ר אֹתֽוֹ'),
(9426, 11, 'WLC', 'WLC', 'he', '1KI', 20, 17, 'OT', 'וַיֵּצְא֗וּ נַעֲרֵ֛י שָׂרֵ֥י הַמְּדִינ֖וֹת בָּרִֽאשֹׁנָ֑ה וַיִּשְׁלַ֣ח בֶּן הֲדַ֗ד וַיַּגִּ֤ידוּ לוֹ֙ לֵאמֹ֔ר אֲנָשִׁ֕ים יָצְא֖וּ מִשֹּׁמְרֽוֹן'),
(9427, 11, 'WLC', 'WLC', 'he', '1KI', 20, 18, 'OT', 'וַיֹּ֛אמֶר אִם לְשָׁל֥וֹם יָצָ֖אוּ תִּפְשׂ֣וּם חַיִּ֑ים וְאִ֧ם לְמִלְחָמָ֛ה יָצָ֖אוּ חַיִּ֥ים תִּפְשֽׂוּם'),
(9428, 11, 'WLC', 'WLC', 'he', '1KI', 20, 19, 'OT', 'וְאֵ֨לֶּה֙ יָצְא֣וּ מִן הָעִ֔יר נַעֲרֵ֖י שָׂרֵ֣י הַמְּדִינ֑וֹת וְהַחַ֖יִל אֲשֶׁ֥ר אַחֲרֵיהֶֽם'),
(9429, 11, 'WLC', 'WLC', 'he', '1KI', 20, 20, 'OT', 'וַיַּכּוּ֙ אִ֣ישׁ אִישׁ֔וֹ וַיָּנֻ֣סוּ אֲרָ֔ם וַֽיִּרְדְּפֵ֖ם יִשְׂרָאֵ֑ל וַיִּמָּלֵ֗ט בֶּן הֲדַד֙ מֶ֣לֶךְ אֲרָ֔ם עַל ס֖וּס וּפָרָשִֽׁים'),
(9430, 11, 'WLC', 'WLC', 'he', '1KI', 20, 21, 'OT', 'וַיֵּצֵא֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַיַּ֥ךְ אֶת הַסּ֖וּס וְאֶת הָרָ֑כֶב וְהִכָּ֥ה בַאֲרָ֖ם מַכָּ֥ה גְדוֹלָֽה'),
(9431, 11, 'WLC', 'WLC', 'he', '1KI', 20, 22, 'OT', 'וַיִּגַּ֤שׁ הַנָּבִיא֙ אֶל מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַיֹּ֤אמֶר לוֹ֙ לֵ֣ךְ הִתְחַזַּ֔ק וְדַ֥ע וּרְאֵ֖ה אֵ֣ת אֲשֶֽׁר תַּעֲשֶׂ֑ה כִּ֚י לִתְשׁוּבַ֣ת הַשָּׁנָ֔ה מֶ֥לֶךְ אֲרָ֖ם עֹלֶ֥ה עָלֶֽיךָ'),
(9432, 11, 'WLC', 'WLC', 'he', '1KI', 20, 23, 'OT', 'וְעַבְדֵ֨י מֶֽלֶךְ אֲרָ֜ם אָמְר֣וּ אֵלָ֗יו אֱלֹהֵ֤י הָרִים֙ אֱלֹ֣הֵיהֶ֔ם עַל כֵּ֖ן חָזְק֣וּ מִמֶּ֑נּוּ וְאוּלָ֗ם נִלָּחֵ֤ם אִתָּם֙ בַּמִּישׁ֔וֹר אִם לֹ֥א נֶחֱזַ֖ק מֵהֶֽם'),
(9433, 11, 'WLC', 'WLC', 'he', '1KI', 20, 24, 'OT', 'וְאֶת הַדָּבָ֥ר הַזֶּ֖ה עֲשֵׂ֑ה הָסֵ֤ר הַמְּלָכִים֙ אִ֣ישׁ מִמְּקֹמ֔וֹ וְשִׂ֥ים פַּח֖וֹת תַּחְתֵּיהֶֽם'),
(9434, 11, 'WLC', 'WLC', 'he', '1KI', 20, 25, 'OT', 'וְאַתָּ֣ה תִֽמְנֶה לְךָ֣ חַ֡יִל כַּחַיִל֩ הַנֹּפֵ֨ל מֵאוֹתָ֜ךְ וְס֣וּס כַּסּ֣וּס וְרֶ֣כֶב כָּרֶ֗כֶב וְנִֽלָּחֲמָ֤ה אוֹתָם֙ בַּמִּישׁ֔וֹר אִם לֹ֥א נֶחֱזַ֖ק מֵהֶ֑ם וַיִּשְׁמַ֥ע לְקֹלָ֖ם וַיַּ֥עַשׂ כֵּֽן'),
(9435, 11, 'WLC', 'WLC', 'he', '1KI', 20, 26, 'OT', 'וַֽיְהִי֙ לִתְשׁוּבַ֣ת הַשָּׁנָ֔ה וַיִּפְקֹ֥ד בֶּן הֲדַ֖ד אֶת אֲרָ֑ם וַיַּ֣עַל אֲפֵ֔קָה לַמִּלְחָמָ֖ה עִם יִשְׂרָאֵֽל'),
(9436, 11, 'WLC', 'WLC', 'he', '1KI', 20, 27, 'OT', 'וּבְנֵ֣י יִשְׂרָאֵ֗ל הָתְפָּקְדוּ֙ וְכָלְכְּל֔וּ וַיֵּלְכ֖וּ לִקְרָאתָ֑ם וַיַּחֲנ֨וּ בְנֵֽי יִשְׂרָאֵ֜ל נֶגְדָּ֗ם כִּשְׁנֵי֙ חֲשִׂפֵ֣י עִזִּ֔ים וַאֲרָ֖ם מִלְא֥וּ אֶת הָאָֽרֶץ'),
(9437, 11, 'WLC', 'WLC', 'he', '1KI', 20, 28, 'OT', 'וַיִּגַּ֞שׁ אִ֣ישׁ הָאֱלֹהִ֗ים וַיֹּאמֶר֮ אֶל מֶ֣לֶךְ יִשְׂרָאֵל֒ וַיֹּ֜אמֶר כֹּֽה אָמַ֣ר יְהוָ֗ה יַ֠עַן אֲשֶׁ֨ר אָמְר֤וּ אֲרָם֙ אֱלֹהֵ֤י הָרִים֙ יְהוָ֔ה וְלֹֽא אֱלֹהֵ֥י עֲמָקִ֖ים ה֑וּא וְ֠נָתַתִּי אֶת כָּל הֶהָמ֨וֹן הַגָּ֤דוֹל הַזֶּה֙ בְּיָדֶ֔ךָ וִֽידַעְתֶּ֖ם כִּֽי אֲנִ֥י יְהוָֽה'),
(9438, 11, 'WLC', 'WLC', 'he', '1KI', 20, 29, 'OT', 'וַֽיַּחֲנ֧וּ אֵ֦לֶּה נֹ֥כַח אֵ֖לֶּה שִׁבְעַ֣ת יָמִ֑ים וַיְהִ֣י בַּיּ֣וֹם הַשְּׁבִיעִ֗י וַתִּקְרַב֙ הַמִּלְחָמָ֔ה וַיַּכּ֨וּ בְנֵֽי יִשְׂרָאֵ֧ל אֶת אֲרָ֛ם מֵאָה אֶ֥לֶף רַגְלִ֖י בְּי֥וֹם אֶחָֽד'),
(9439, 11, 'WLC', 'WLC', 'he', '1KI', 20, 30, 'OT', 'וַיָּנֻ֨סוּ הַנּוֹתָרִ֥ים אֲפֵקָה֮ אֶל הָעִיר֒ וַתִּפֹּל֙ הַחוֹמָ֔ה עַל עֶשְׂרִ֨ים וְשִׁבְעָ֥ה אֶ֛לֶף אִ֖ישׁ הַנּוֹתָרִ֑ים וּבֶן הֲדַ֣ד נָ֔ס וַיָּבֹ֥א אֶל הָעִ֖יר חֶ֥דֶר בְּחָֽדֶר'),
(9440, 11, 'WLC', 'WLC', 'he', '1KI', 20, 31, 'OT', 'וַיֹּאמְר֣וּ אֵלָיו֮ עֲבָדָיו֒ הִנֵּֽה נָ֣א שָׁמַ֔עְנוּ כִּ֗י מַלְכֵי֙ בֵּ֣ית יִשְׂרָאֵ֔ל כִּֽי מַלְכֵ֥י חֶ֖סֶד הֵ֑ם נָשִׂ֣ימָה נָּא֩ שַׂקִּ֨ים בְּמָתְנֵ֜ינוּ וַחֲבָלִ֣ים בְּרֹאשֵׁ֗נוּ וְנֵצֵא֙ אֶל מֶ֣לֶךְ יִשְׂרָאֵ֔ל אוּלַ֖י יְחַיֶּ֥ה אֶת נַפְשֶֽׁךָ'),
(9441, 11, 'WLC', 'WLC', 'he', '1KI', 20, 32, 'OT', 'וַיַּחְגְּרוּ֩ שַׂקִּ֨ים בְּמָתְנֵיהֶ֜ם וַחֲבָלִ֣ים בְּרָאשֵׁיהֶ֗ם וַיָּבֹ֨אוּ֙ אֶל מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַיֹּ֣אמְר֔וּ עַבְדְּךָ֧ בֶן הֲדַ֛ד אָמַ֖ר תְּחִֽי נָ֣א נַפְשִׁ֑י וַיֹּ֛אמֶר הַעוֹדֶ֥נּוּ חַ֖י אָחִ֥י הֽוּא'),
(9442, 11, 'WLC', 'WLC', 'he', '1KI', 20, 33, 'OT', 'וְהָאֲנָשִׁים֩ יְנַחֲשׁ֨וּ וַֽיְמַהֲר֜וּ וַיַּחְלְט֣וּ הֲמִמֶּ֗נּוּ וַיֹּֽאמְרוּ֙ אָחִ֣יךָ בֶן הֲדַ֔ד וַיֹּ֖אמֶר בֹּ֣אוּ קָחֻ֑הוּ וַיֵּצֵ֤א אֵלָיו֙ בֶּן הֲדַ֔ד וַֽיַּעֲלֵ֖הוּ עַל הַמֶּרְכָּבָֽה'),
(9443, 11, 'WLC', 'WLC', 'he', '1KI', 20, 34, 'OT', 'וַיֹּ֣אמֶר אֵלָ֡יו הֶעָרִ֣ים אֲשֶׁר לָֽקַח אָבִי֩ מֵאֵ֨ת אָבִ֜יךָ אָשִׁ֗יב וְ֠חוּצוֹת תָּשִׂ֨ים לְךָ֤ בְדַמֶּ֨שֶׂק֙ כַּאֲשֶׁר שָׂ֤ם אָבִי֙ בְּשֹׁ֣מְר֔וֹן וַאֲנִ֖י בַּבְּרִ֣ית אֲשַׁלְּחֶ֑ךָּ וַיִּכְרָת ל֥וֹ בְרִ֖ית וַֽיְשַׁלְּחֵֽהוּ'),
(9444, 11, 'WLC', 'WLC', 'he', '1KI', 20, 35, 'OT', 'וְאִ֨ישׁ אֶחָ֜ד מִבְּנֵ֣י הַנְּבִיאִ֗ים אָמַ֧ר אֶל רֵעֵ֛הוּ בִּדְבַ֥ר יְהוָ֖ה הַכֵּ֣ינִי נָ֑א וַיְמָאֵ֥ן הָאִ֖ישׁ לְהַכֹּתֽוֹ'),
(9445, 11, 'WLC', 'WLC', 'he', '1KI', 20, 36, 'OT', 'וַיֹּ֣אמֶר ל֗וֹ יַ֚עַן אֲשֶׁ֤ר לֹֽא שָׁמַ֨עְתָּ֙ בְּק֣וֹל יְהוָ֔ה הִנְּךָ֤ הוֹלֵךְ֙ מֵֽאִתִּ֔י וְהִכְּךָ֖ הָאַרְיֵ֑ה וַיֵּ֨לֶךְ֙ מֵֽאֶצְל֔וֹ וַיִּמְצָאֵ֥הוּ הָאַרְיֵ֖ה וַיַּכֵּֽהוּ'),
(9446, 11, 'WLC', 'WLC', 'he', '1KI', 20, 37, 'OT', 'וַיִּמְצָא֙ אִ֣ישׁ אַחֵ֔ר וַיֹּ֖אמֶר הַכֵּ֣ינִי נָ֑א וַיַּכֵּ֥הוּ הָאִ֖ישׁ הַכֵּ֥ה וּפָצֹֽעַ'),
(9447, 11, 'WLC', 'WLC', 'he', '1KI', 20, 38, 'OT', 'וַיֵּ֨לֶךְ֙ הַנָּבִ֔יא וַיַּעֲמֹ֥ד לַמֶּ֖לֶךְ עַל הַדָּ֑רֶךְ וַיִּתְחַפֵּ֥שׂ בָּאֲפֵ֖ר עַל עֵינָֽיו'),
(9448, 11, 'WLC', 'WLC', 'he', '1KI', 20, 39, 'OT', 'וַיְהִ֤י הַמֶּ֨לֶךְ֙ עֹבֵ֔ר וְה֖וּא צָעַ֣ק אֶל הַמֶּ֑לֶךְ וַיֹּ֜אמֶר עַבְדְּךָ֣ יָצָ֣א בְקֶֽרֶב הַמִּלְחָמָ֗ה וְהִנֵּֽה אִ֨ישׁ סָ֜ר וַיָּבֵ֧א אֵלַ֣י אִ֗ישׁ וַיֹּ֨אמֶר֙ שְׁמֹר֙ אֶת הָאִ֣ישׁ הַזֶּ֔ה אִם הִפָּקֵד֙ יִפָּקֵ֔ד וְהָיְתָ֤ה נַפְשְׁךָ֙ תַּ֣חַת נַפְשׁ֔וֹ א֥וֹ כִכַּר כֶּ֖סֶף תִּשְׁקֽוֹל'),
(9449, 11, 'WLC', 'WLC', 'he', '1KI', 20, 40, 'OT', 'וַיְהִ֣י עַבְדְּךָ֗ עֹשֵׂ֥ה הֵ֛נָּה וָהֵ֖נָּה וְה֣וּא אֵינֶ֑נּוּ וַיֹּ֨אמֶר אֵלָ֧יו מֶֽלֶךְ יִשְׂרָאֵ֛ל כֵּ֥ן מִשְׁפָּטֶ֖ךָ אַתָּ֥ה חָרָֽצְתָּ'),
(9450, 11, 'WLC', 'WLC', 'he', '1KI', 20, 41, 'OT', 'וַיְמַהֵ֕ר וַיָּ֨סַר֙ אֶת הָ֣אֲפֵ֔ר מעל עֵינָ֑יו וַיַּכֵּ֤ר אֹתוֹ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל כִּ֥י מֵֽהַנְּבִאִ֖ים הֽוּא'),
(9451, 11, 'WLC', 'WLC', 'he', '1KI', 20, 42, 'OT', 'וַיֹּ֣אמֶר אֵלָ֗יו כֹּ֚ה אָמַ֣ר יְהוָ֔ה יַ֛עַן שִׁלַּ֥חְתָּ אֶת אִישׁ חֶרְמִ֖י מִיָּ֑ד וְהָיְתָ֤ה נַפְשְׁךָ֙ תַּ֣חַת נַפְשׁ֔וֹ וְעַמְּךָ֖ תַּ֥חַת עַמּֽוֹ'),
(9452, 11, 'WLC', 'WLC', 'he', '1KI', 20, 43, 'OT', 'וַיֵּ֧לֶךְ מֶֽלֶךְ יִשְׂרָאֵ֛ל עַל בֵּית֖וֹ סַ֣ר וְזָעֵ֑ף וַיָּבֹ֖א שֹׁמְרֽוֹנָה'),
(9453, 11, 'WLC', 'WLC', 'he', '1KI', 21, 1, 'OT', 'וַיְהִ֗י אַחַר֙ הַדְּבָרִ֣ים הָאֵ֔לֶּה כֶּ֧רֶם הָיָ֛ה לְנָב֥וֹת הַיִּזְרְעֵאלִ֖י אֲשֶׁ֣ר בְּיִזְרְעֶ֑אל אֵ֚צֶל הֵיכַ֣ל אַחְאָ֔ב מֶ֖לֶךְ שֹׁמְרֽוֹן'),
(9454, 11, 'WLC', 'WLC', 'he', '1KI', 21, 2, 'OT', 'וַיְדַבֵּ֣ר אַחְאָ֣ב אֶל נָב֣וֹת לֵאמֹר֩ תְּנָה לִּ֨י אֶֽת כַּרְמְךָ֜ וִֽיהִי לִ֣י לְגַן יָרָ֗ק כִּ֣י ה֤וּא קָרוֹב֙ אֵ֣צֶל בֵּיתִ֔י וְאֶתְּנָ֤ה לְךָ֙ תַּחְתָּ֔יו כֶּ֖רֶם ט֣וֹב מִמֶּ֑נּוּ אִ֚ם ט֣וֹב בְּעֵינֶ֔יךָ אֶתְּנָה לְךָ֥ כֶ֖סֶף מְחִ֥יר זֶֽה'),
(9455, 11, 'WLC', 'WLC', 'he', '1KI', 21, 3, 'OT', 'וַיֹּ֥אמֶר נָב֖וֹת אֶל אַחְאָ֑ב חָלִ֤ילָה לִּי֙ מֵֽיהוָ֔ה מִתִּתִּ֛י אֶת נַחֲלַ֥ת אֲבֹתַ֖י לָֽךְ'),
(9456, 11, 'WLC', 'WLC', 'he', '1KI', 21, 4, 'OT', 'וַיָּבֹא֩ אַחְאָ֨ב אֶל בֵּית֜וֹ סַ֣ר וְזָעֵ֗ף עַל הַדָּבָר֙ אֲשֶׁר דִּבֶּ֣ר אֵלָ֗יו נָבוֹת֙ הַיִּזְרְעֵאלִ֔י וַיֹּ֕אמֶר לֹֽא אֶתֵּ֥ן לְךָ֖ אֶת נַחֲלַ֣ת אֲבוֹתָ֑י וַיִּשְׁכַּב֙ עַל מִטָּת֔וֹ וַיַּסֵּ֥ב אֶת פָּנָ֖יו וְלֹֽא אָ֥כַל לָֽחֶם'),
(9457, 11, 'WLC', 'WLC', 'he', '1KI', 21, 5, 'OT', 'וַתָּבֹ֥א אֵלָ֖יו אִיזֶ֣בֶל אִשְׁתּ֑וֹ וַתְּדַבֵּ֣ר אֵלָ֗יו מַה זֶּה֙ רוּחֲךָ֣ סָרָ֔ה וְאֵינְךָ֖ אֹכֵ֥ל לָֽחֶם'),
(9458, 11, 'WLC', 'WLC', 'he', '1KI', 21, 6, 'OT', 'וַיְדַבֵּ֣ר אֵלֶ֗יהָ כִּֽי אֲ֠דַבֵּר אֶל נָב֨וֹת הַיִּזְרְעֵאלִ֜י וָאֹ֣מַר ל֗וֹ תְּנָה לִּ֤י אֶֽת כַּרְמְךָ֙ בְּכֶ֔סֶף א֚וֹ אִם חָפֵ֣ץ אַתָּ֔ה אֶתְּנָה לְךָ֥ כֶ֖רֶם תַּחְתָּ֑יו וַיֹּ֕אמֶר לֹֽא אֶתֵּ֥ן לְךָ֖ אֶת כַּרְמִֽי'),
(9459, 11, 'WLC', 'WLC', 'he', '1KI', 21, 7, 'OT', 'וַתֹּ֤אמֶר אֵלָיו֙ אִיזֶ֣בֶל אִשְׁתּ֔וֹ אַתָּ֕ה עַתָּ֛ה תַּעֲשֶׂ֥ה מְלוּכָ֖ה עַל יִשְׂרָאֵ֑ל ק֤וּם אֱכָל לֶ֨חֶם֙ וְיִטַ֣ב לִבֶּ֔ךָ אֲנִי֙ אֶתֵּ֣ן לְךָ֔ אֶת כֶּ֖רֶם נָב֥וֹת הַיִּזְרְעֵאלִֽי'),
(9460, 11, 'WLC', 'WLC', 'he', '1KI', 21, 8, 'OT', 'וַתִּכְתֹּ֤ב סְפָרִים֙ בְּשֵׁ֣ם אַחְאָ֔ב וַתַּחְתֹּ֖ם בְּחֹתָמ֑וֹ וַתִּשְׁלַ֣ח הספרים אֶל הַזְקֵנִ֤ים וְאֶל הַֽחֹרִים֙ אֲשֶׁ֣ר בְּעִיר֔וֹ הַיֹּשְׁבִ֖ים אֶת נָבֽוֹת'),
(9461, 11, 'WLC', 'WLC', 'he', '1KI', 21, 9, 'OT', 'וַתִּכְתֹּ֥ב בַּסְּפָרִ֖ים לֵאמֹ֑ר קִֽרְאוּ צ֔וֹם וְהוֹשִׁ֥יבוּ אֶת נָב֖וֹת בְּרֹ֥אשׁ הָעָֽם'),
(9462, 11, 'WLC', 'WLC', 'he', '1KI', 21, 10, 'OT', 'וְ֠הוֹשִׁיבוּ שְׁנַ֨יִם אֲנָשִׁ֥ים בְּנֵֽי בְלִיַּעַל֮ נֶגְדּוֹ֒ וִיעִדֻ֣הוּ לֵאמֹ֔ר בֵּרַ֥כְתָּ אֱלֹהִ֖ים וָמֶ֑לֶךְ וְהוֹצִיאֻ֥הוּ וְסִקְלֻ֖הוּ וְיָמֹֽת'),
(9463, 11, 'WLC', 'WLC', 'he', '1KI', 21, 11, 'OT', 'וַיַּעֲשׂוּ֩ אַנְשֵׁ֨י עִיר֜וֹ הַזְּקֵנִ֣ים וְהַחֹרִ֗ים אֲשֶׁ֤ר הַיֹּֽשְׁבִים֙ בְּעִיר֔וֹ כַּאֲשֶׁ֛ר שָׁלְחָ֥ה אֲלֵיהֶ֖ם אִיזָ֑בֶל כַּאֲשֶׁ֤ר כָּתוּב֙ בַּסְּפָרִ֔ים אֲשֶׁ֥ר שָׁלְחָ֖ה אֲלֵיהֶֽם'),
(9464, 11, 'WLC', 'WLC', 'he', '1KI', 21, 12, 'OT', 'קָרְא֖וּ צ֑וֹם וְהֹשִׁ֥יבוּ אֶת נָב֖וֹת בְּרֹ֥אשׁ הָעָֽם'),
(9465, 11, 'WLC', 'WLC', 'he', '1KI', 21, 13, 'OT', 'וַ֠יָּבֹאוּ שְׁנֵ֨י הָאֲנָשִׁ֥ים בְּנֵֽי בְלִיַּעַל֮ וַיֵּשְׁב֣וּ נֶגְדּוֹ֒ וַיְעִדֻהוּ֩ אַנְשֵׁ֨י הַבְּלִיַּ֜עַל אֶת נָב֗וֹת נֶ֤גֶד הָעָם֙ לֵאמֹ֔ר בֵּרַ֥ךְ נָב֛וֹת אֱלֹהִ֖ים וָמֶ֑לֶךְ וַיֹּצִאֻ֨הוּ֙ מִח֣וּץ לָעִ֔יר וַיִּסְקְלֻ֥הוּ בָאֲבָנִ֖ים וַיָּמֹֽת'),
(9466, 11, 'WLC', 'WLC', 'he', '1KI', 21, 14, 'OT', 'וַֽיִּשְׁלְח֖וּ אֶל אִיזֶ֣בֶל לֵאמֹ֑ר סֻקַּ֥ל נָב֖וֹת וַיָּמֹֽת'),
