(9692, 12, 'WLC', 'WLC', 'he', '2KI', 6, 17, 'OT', 'וַיִּתְפַּלֵּ֤ל אֱלִישָׁע֙ וַיֹּאמַ֔ר יְהוָ֕ה פְּקַח נָ֥א אֶת עֵינָ֖יו וְיִרְאֶ֑ה וַיִּפְקַ֤ח יְהוָה֙ אֶת עֵינֵ֣י הַנַּ֔עַר וַיַּ֗רְא וְהִנֵּ֨ה הָהָ֜ר מָלֵ֨א סוּסִ֥ים וְרֶ֛כֶב אֵ֖שׁ סְבִיבֹ֥ת אֱלִישָֽׁע'),
(9693, 12, 'WLC', 'WLC', 'he', '2KI', 6, 18, 'OT', 'וַיֵּרְדוּ֮ אֵלָיו֒ וַיִּתְפַּלֵּ֨ל אֱלִישָׁ֤ע אֶל יְהוָה֙ וַיֹּאמַ֔ר הַךְ נָ֥א אֶת הַגּוֹי הַזֶּ֖ה בַּסַּנְוֵרִ֑ים וַיַּכֵּ֥ם בַּסַּנְוֵרִ֖ים כִּדְבַ֥ר אֱלִישָֽׁע'),
(9694, 12, 'WLC', 'WLC', 'he', '2KI', 6, 19, 'OT', 'וַיֹּ֨אמֶר אֲלֵהֶ֜ם אֱלִישָׁ֗ע לֹ֣א זֶ֣ה הַדֶּרֶךְ֮ וְלֹ֣א זֹ֣ה הָעִיר֒ לְכ֣וּ אַחֲרַ֔י וְאוֹלִ֣יכָה אֶתְכֶ֔ם אֶל הָאִ֖ישׁ אֲשֶׁ֣ר תְּבַקֵּשׁ֑וּן וַיֹּ֥לֶךְ אוֹתָ֖ם שֹׁמְרֽוֹנָה'),
(9695, 12, 'WLC', 'WLC', 'he', '2KI', 6, 20, 'OT', 'וַיְהִי֮ כְּבֹאָ֣ם שֹׁמְרוֹן֒ וַיֹּ֣אמֶר אֱלִישָׁ֔ע יְהוָ֕ה פְּקַ֥ח אֶת עֵינֵֽי אֵ֖לֶּה וְיִרְא֑וּ וַיִּפְקַ֤ח יְהוָה֙ אֶת עֵ֣ינֵיהֶ֔ם וַיִּרְא֕וּ וְהִנֵּ֖ה בְּת֥וֹךְ שֹׁמְרֽוֹן'),
(9696, 12, 'WLC', 'WLC', 'he', '2KI', 6, 21, 'OT', 'וַיֹּ֤אמֶר מֶֽלֶךְ יִשְׂרָאֵל֙ אֶל אֱלִישָׁ֔ע כִּרְאֹת֖וֹ אוֹתָ֑ם הַאַכֶּ֥ה אַכֶּ֖ה אָבִֽי'),
(9697, 12, 'WLC', 'WLC', 'he', '2KI', 6, 22, 'OT', 'וַיֹּ֨אמֶר֙ לֹ֣א תַכֶּ֔ה הַאֲשֶׁ֥ר שָׁבִ֛יתָ בְּחַרְבְּךָ֥ וּֽבְקַשְׁתְּךָ֖ אַתָּ֣ה מַכֶּ֑ה שִׂים֩ לֶ֨חֶם וָמַ֜יִם לִפְנֵיהֶ֗ם וְיֹֽאכְלוּ֙ וְיִשְׁתּ֔וּ וְיֵלְכ֖וּ אֶל אֲדֹנֵיהֶֽם'),
(9698, 12, 'WLC', 'WLC', 'he', '2KI', 6, 23, 'OT', 'וַיִּכְרֶ֨ה לָהֶ֜ם כֵּרָ֣ה גְדוֹלָ֗ה וַיֹּֽאכְלוּ֙ וַיִּשְׁתּ֔וּ וַֽיְשַׁלְּחֵ֔ם וַיֵּלְכ֖וּ אֶל אֲדֹֽנֵיהֶ֑ם וְלֹֽא יָ֤סְפוּ עוֹד֙ גְּדוּדֵ֣י אֲרָ֔ם לָב֖וֹא בְּאֶ֥רֶץ יִשְׂרָאֵֽל'),
(9699, 12, 'WLC', 'WLC', 'he', '2KI', 6, 24, 'OT', 'וַֽיְהִי֙ אַחֲרֵי כֵ֔ן וַיִּקְבֹּ֛ץ בֶּן הֲדַ֥ד מֶֽלֶךְ אֲרָ֖ם אֶת כָּל מַחֲנֵ֑הוּ וַיַּ֕עַל וַיָּ֖צַר עַל שֹׁמְרֽוֹן'),
(9700, 12, 'WLC', 'WLC', 'he', '2KI', 6, 25, 'OT', 'וַיְהִ֨י רָעָ֤ב גָּדוֹל֙ בְּשֹׁ֣מְר֔וֹן וְהִנֵּ֖ה צָרִ֣ים עָלֶ֑יהָ עַ֣ד הֱי֤וֹת רֹאשׁ חֲמוֹר֙ בִּשְׁמֹנִ֣ים כֶּ֔סֶף וְרֹ֛בַע הַקַּ֥ב חרי יונים בַּחֲמִשָּׁה כָֽסֶף'),
(9701, 12, 'WLC', 'WLC', 'he', '2KI', 6, 26, 'OT', 'וַֽיְהִי֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל עֹבֵ֖ר עַל הַחֹמָ֑ה וְאִשָּׁ֗ה צָעֲקָ֤ה אֵלָיו֙ לֵאמֹ֔ר הוֹשִׁ֖יעָה אֲדֹנִ֥י הַמֶּֽלֶךְ'),
(9702, 12, 'WLC', 'WLC', 'he', '2KI', 6, 27, 'OT', 'וַיֹּ֨אמֶר֙ אַל יוֹשִׁעֵ֣ךְ יְהוָ֔ה מֵאַ֖יִן אֽוֹשִׁיעֵ֑ךְ הֲמִן הַגֹּ֖רֶן א֥וֹ מִן הַיָּֽקֶב'),
(9703, 12, 'WLC', 'WLC', 'he', '2KI', 6, 28, 'OT', 'וַיֹּֽאמֶר לָ֥הּ הַמֶּ֖לֶךְ מַה לָּ֑ךְ וַתֹּ֗אמֶר הָאִשָּׁ֨ה הַזֹּ֜את אָמְרָ֣ה אֵלַ֗י תְּנִ֤י אֶת בְּנֵךְ֙ וְנֹאכְלֶ֣נּוּ הַיּ֔וֹם וְאֶת בְּנִ֖י נֹאכַ֥ל מָחָֽר'),
(9704, 12, 'WLC', 'WLC', 'he', '2KI', 6, 29, 'OT', 'וַנְּבַשֵּׁ֥ל אֶת בְּנִ֖י וַנֹּֽאכְלֵ֑הוּ וָאֹמַ֨ר אֵלֶ֜יהָ בַּיּ֣וֹם הָאַחֵ֗ר תְּנִ֤י אֶת בְּנֵךְ֙ וְנֹ֣אכְלֶ֔נּוּ וַתַּחְבִּ֖א אֶת בְּנָֽהּ'),
(9705, 12, 'WLC', 'WLC', 'he', '2KI', 6, 30, 'OT', 'וַיְהִי֩ כִשְׁמֹ֨עַ הַמֶּ֜לֶךְ אֶת דִּבְרֵ֤י הָֽאִשָּׁה֙ וַיִּקְרַ֣ע אֶת בְּגָדָ֔יו וְה֖וּא עֹבֵ֣ר עַל הַחֹמָ֑ה וַיַּ֣רְא הָעָ֔ם וְהִנֵּ֥ה הַשַּׂ֛ק עַל בְּשָׂר֖וֹ מִבָּֽיִת'),
(9706, 12, 'WLC', 'WLC', 'he', '2KI', 6, 31, 'OT', 'וַיֹּ֕אמֶר כֹּֽה יַעֲשֶׂה לִּ֥י אֱלֹהִ֖ים וְכֹ֣ה יוֹסִ֑ף אִֽם יַעֲמֹ֞ד רֹ֣אשׁ אֱלִישָׁ֧ע בֶּן שָׁפָ֛ט עָלָ֖יו הַיּֽוֹם'),
(9707, 12, 'WLC', 'WLC', 'he', '2KI', 6, 32, 'OT', 'וֶאֱלִישָׁע֙ יֹשֵׁ֣ב בְּבֵית֔וֹ וְהַזְּקֵנִ֖ים יֹשְׁבִ֣ים אִתּ֑וֹ וַיִּשְׁלַ֨ח אִ֜ישׁ מִלְּפָנָ֗יו בְּטֶ֣רֶם יָבֹא֩ הַמַּלְאָ֨ךְ אֵלָ֜יו וְה֣וּא אָמַ֣ר אֶל הַזְּקֵנִ֗ים הַרְּאִיתֶם֙ כִּֽי שָׁלַ֞ח בֶּן הַֽמְרַצֵּ֤חַ הַזֶּה֙ לְהָסִ֣יר אֶת רֹאשִׁ֔י רְא֣וּ כְּבֹ֣א הַמַּלְאָ֗ךְ סִגְר֤וּ הַדֶּ֨לֶת֙ וּלְחַצְתֶּ֤ם אֹתוֹ֙ בַּדֶּ֔לֶת הֲל֗וֹא ק֛וֹל רַגְלֵ֥י אֲדֹנָ֖יו אַחֲרָֽיו'),
(9708, 12, 'WLC', 'WLC', 'he', '2KI', 6, 33, 'OT', 'עוֹדֶ֨נּוּ֙ מְדַבֵּ֣ר עִמָּ֔ם וְהִנֵּ֥ה הַמַּלְאָ֖ךְ יֹרֵ֣ד אֵלָ֑יו וַיֹּ֗אמֶר הִנֵּֽה זֹ֤את הָֽרָעָה֙ מֵאֵ֣ת יְהוָ֔ה מָֽה אוֹחִ֥יל לַיהוָ֖ה עֽוֹד'),
(9709, 12, 'WLC', 'WLC', 'he', '2KI', 7, 1, 'OT', 'וַיֹּ֣אמֶר אֱלִישָׁ֔ע שִׁמְע֖וּ דְּבַר יְהוָ֑ה כֹּ֣ה אָמַ֣ר יְהוָ֗ה כָּעֵ֤ת מָחָר֙ סְאָֽה סֹ֣לֶת בְּשֶׁ֗קֶל וְסָאתַ֧יִם שְׂעֹרִ֛ים בְּשֶׁ֖קֶל בְּשַׁ֥עַר שֹׁמְרֽוֹן'),
(9710, 12, 'WLC', 'WLC', 'he', '2KI', 7, 2, 'OT', 'וַיַּ֣עַן הַשָּׁלִ֡ישׁ אֲשֶׁר לַמֶּלֶךְ֩ נִשְׁעָ֨ן עַל יָד֜וֹ אֶת אִ֣ישׁ הָאֱלֹהִים֮ וַיֹּאמַר֒ הִנֵּ֣ה יְהוָ֗ה עֹשֶׂ֤ה אֲרֻבּוֹת֙ בַּשָּׁמַ֔יִם הֲיִהְיֶ֖ה הַדָּבָ֣ר הַזֶּ֑ה וַיֹּ֗אמֶר הִנְּכָ֤ה רֹאֶה֙ בְּעֵינֶ֔יךָ וּמִשָּׁ֖ם לֹ֥א תֹאכֵֽל'),
(9711, 12, 'WLC', 'WLC', 'he', '2KI', 7, 3, 'OT', 'וְאַרְבָּעָ֧ה אֲנָשִׁ֛ים הָי֥וּ מְצֹרָעִ֖ים פֶּ֣תַח הַשָּׁ֑עַר וַיֹּֽאמְרוּ֙ אִ֣ישׁ אֶל רֵעֵ֔הוּ מָ֗ה אֲנַ֛חְנוּ יֹשְׁבִ֥ים פֹּ֖ה עַד מָֽתְנוּ'),
(9712, 12, 'WLC', 'WLC', 'he', '2KI', 7, 4, 'OT', 'אִם אָמַרְנוּ֩ נָב֨וֹא הָעִ֜יר וְהָרָעָ֤ב בָּעִיר֙ וָמַ֣תְנוּ שָׁ֔ם וְאִם יָשַׁ֥בְנוּ פֹ֖ה וָמָ֑תְנוּ וְעַתָּ֗ה לְכוּ֙ וְנִפְּלָה֙ אֶל מַחֲנֵ֣ה אֲרָ֔ם אִם יְחַיֻּ֣נוּ נִֽחְיֶ֔ה וְאִם יְמִיתֻ֖נוּ וָמָֽתְנוּ'),
(9713, 12, 'WLC', 'WLC', 'he', '2KI', 7, 5, 'OT', 'וַיָּק֣וּמוּ בַנֶּ֔שֶׁף לָב֖וֹא אֶל מַחֲנֵ֣ה אֲרָ֑ם וַיָּבֹ֗אוּ עַד קְצֵה֙ מַחֲנֵ֣ה אֲרָ֔ם וְהִנֵּ֥ה אֵֽין שָׁ֖ם אִֽישׁ'),
(9714, 12, 'WLC', 'WLC', 'he', '2KI', 7, 6, 'OT', 'וַאדֹנָ֞י הִשְׁמִ֣יעַ אֶת מַחֲנֵ֣ה אֲרָ֗ם ק֥וֹל רֶ֨כֶב֙ ק֣וֹל ס֔וּס ק֖וֹל חַ֣יִל גָּד֑וֹל וַיֹּאמְר֞וּ אִ֣ישׁ אֶל אָחִ֗יו הִנֵּ֣ה שָֽׂכַר עָלֵינוּ֩ מֶ֨לֶךְ יִשְׂרָאֵ֜ל אֶת מַלְכֵ֧י הַחִתִּ֛ים וְאֶת מַלְכֵ֥י מִצְרַ֖יִם לָב֥וֹא עָלֵֽינוּ'),
(9715, 12, 'WLC', 'WLC', 'he', '2KI', 7, 7, 'OT', 'וַיָּקוּמוּ֮ וַיָּנ֣וּסוּ בַנֶּשֶׁף֒ וַיַּעַזְב֣וּ אֶת אָהֳלֵיהֶ֗ם וְאֶת סֽוּסֵיהֶם֙ וְאֶת חֲמֹ֣רֵיהֶ֔ם הַֽמַּחֲנֶ֖ה כַּאֲשֶׁר הִ֑יא וַיָּנֻ֖סוּ אֶל נַפְשָֽׁם'),
(9716, 12, 'WLC', 'WLC', 'he', '2KI', 7, 8, 'OT', 'וַיָּבֹאוּ֩ הַֽמְצֹרָעִ֨ים הָאֵ֜לֶּה עַד קְצֵ֣ה הַֽמַּחֲנֶ֗ה וַיָּבֹ֜אוּ אֶל אֹ֤הֶל אֶחָד֙ וַיֹּאכְל֣וּ וַיִּשְׁתּ֔וּ וַיִּשְׂא֣וּ מִשָּׁ֗ם כֶּ֤סֶף וְזָהָב֙ וּבְגָדִ֔ים וַיֵּלְכ֖וּ וַיַּטְמִ֑נוּ וַיָּשֻׁ֗בוּ וַיָּבֹ֨אוּ֙ אֶל אֹ֣הֶל אַחֵ֔ר וַיִּשְׂא֣וּ מִשָּׁ֔ם וַיֵּלְכ֖וּ וַיַּטְמִֽנוּ'),
(9717, 12, 'WLC', 'WLC', 'he', '2KI', 7, 9, 'OT', 'וַיֹּאמְרוּ֩ אִ֨ישׁ אֶל רֵעֵ֜הוּ לֹֽא כֵ֣ן אֲנַ֣חְנוּ עֹשִׂ֗ים הַיּ֤וֹם הַזֶּה֙ יוֹם בְּשֹׂרָ֣ה ה֔וּא וַאֲנַ֣חְנוּ מַחְשִׁ֗ים וְחִכִּ֛ינוּ עַד א֥וֹר הַבֹּ֖קֶר וּמְצָאָ֣נוּ עָו֑וֹן וְעַתָּה֙ לְכ֣וּ וְנָבֹ֔אָה וְנַגִּ֖ידָה בֵּ֥ית הַמֶּֽלֶךְ'),
(9718, 12, 'WLC', 'WLC', 'he', '2KI', 7, 10, 'OT', 'וַיָּבֹ֗אוּ וַֽיִּקְרְאוּ֮ אֶל שֹׁעֵ֣ר הָעִיר֒ וַיַּגִּ֤ידוּ לָהֶם֙ לֵאמֹ֔ר בָּ֚אנוּ אֶל מַחֲנֵ֣ה אֲרָ֔ם וְהִנֵּ֥ה אֵֽין שָׁ֛ם אִ֖ישׁ וְק֣וֹל אָדָ֑ם כִּ֣י אִם הַסּ֤וּס אָסוּר֙ וְהַחֲמ֣וֹר אָס֔וּר וְאֹהָלִ֖ים כַּאֲשֶׁר הֵֽמָּה'),
(9719, 12, 'WLC', 'WLC', 'he', '2KI', 7, 11, 'OT', 'וַיִּקְרָ֖א הַשֹּֽׁעֲרִ֑ים וַיַּגִּ֕ידוּ בֵּ֥ית הַמֶּ֖לֶךְ פְּנִֽימָה'),
(9720, 12, 'WLC', 'WLC', 'he', '2KI', 7, 12, 'OT', 'וַיָּ֨קָם הַמֶּ֜לֶךְ לַ֗יְלָה וַיֹּ֨אמֶר֙ אֶל עֲבָדָ֔יו אַגִּֽידָה נָּ֣א לָכֶ֔ם אֵ֛ת אֲשֶׁר עָ֥שׂוּ לָ֖נוּ אֲרָ֑ם יָדְע֞וּ כִּי רְעֵבִ֣ים אֲנַ֗חְנוּ וַיֵּצְא֤וּ מִן הַֽמַּחֲנֶה֙ לְהֵחָבֵ֤ה בהשדה לֵאמֹ֔ר כִּֽי יֵצְא֤וּ מִן הָעִיר֙ וְנִתְפְּשֵׂ֣ם חַיִּ֔ים וְאֶל הָעִ֖יר נָבֹֽא'),
(9721, 12, 'WLC', 'WLC', 'he', '2KI', 7, 13, 'OT', 'וַיַּעַן֩ אֶחָ֨ד מֵעֲבָדָ֜יו וַיֹּ֗אמֶר וְיִקְחוּ נָ֞א חֲמִשָּׁ֣ה מִן הַסּוּסִים֮ הַֽנִּשְׁאָרִים֮ אֲשֶׁ֣ר נִשְׁאֲרוּ בָהּ֒ הִנָּ֗ם כְּכָל ההמון יִשְׂרָאֵל֙ אֲשֶׁ֣ר נִשְׁאֲרוּ בָ֔הּ הִנָּ֕ם כְּכָל הֲמ֥וֹן יִשְׂרָאֵ֖ל אֲשֶׁר תָּ֑מּוּ וְנִשְׁלְחָ֖ה וְנִרְאֶֽה'),
