(9798, 12, 'WLC', 'WLC', 'he', '2KI', 10, 4, 'OT', 'וַיִּֽרְאוּ֙ מְאֹ֣ד מְאֹ֔ד וַיֹּ֣אמְר֔וּ הִנֵּה֙ שְׁנֵ֣י הַמְּלָכִ֔ים לֹ֥א עָמְד֖וּ לְפָנָ֑יו וְאֵ֖יךְ נַעֲמֹ֥ד אֲנָֽחְנוּ'),
(9799, 12, 'WLC', 'WLC', 'he', '2KI', 10, 5, 'OT', 'וַיִּשְׁלַ֣ח אֲשֶׁר עַל הַבַּ֣יִת וַאֲשֶׁ֪ר עַל הָעִ֟יר וְהַזְּקֵנִים֩ וְהָאֹמְנִ֨ים אֶל יֵה֤וּא לֵאמֹר֙ עֲבָדֶ֣יךָ אֲנַ֔חְנוּ וְכֹ֛ל אֲשֶׁר תֹּאמַ֥ר אֵלֵ֖ינוּ נַעֲשֶׂ֑ה לֹֽא נַמְלִ֣יךְ אִ֔ישׁ הַטּ֥וֹב בְּעֵינֶ֖יךָ עֲשֵֽׂה'),
(9800, 12, 'WLC', 'WLC', 'he', '2KI', 10, 6, 'OT', 'וַיִּכְתֹּ֣ב אֲלֵיהֶם֩ סֵ֨פֶר שֵׁנִ֜ית לֵאמֹ֗ר אִם לִ֨י אַתֶּ֜ם וּלְקֹלִ֣י אַתֶּ֣ם שֹׁמְעִ֗ים קְחוּ֙ אֶת רָאשֵׁי֙ אַנְשֵׁ֣י בְנֵֽי אֲדֹנֵיכֶ֔ם וּבֹ֧אוּ אֵלַ֛י כָּעֵ֥ת מָחָ֖ר יִזְרְעֶ֑אלָה וּבְנֵ֤י הַמֶּ֨לֶךְ֙ שִׁבְעִ֣ים אִ֔ישׁ אֶת גְּדֹלֵ֥י הָעִ֖יר מְגַדְּלִ֥ים אוֹתָֽם'),
(9801, 12, 'WLC', 'WLC', 'he', '2KI', 10, 7, 'OT', 'וַיְהִ֗י כְּבֹ֤א הַסֵּ֨פֶר֙ אֲלֵיהֶ֔ם וַיִּקְחוּ֙ אֶת בְּנֵ֣י הַמֶּ֔לֶךְ וַֽיִּשְׁחֲט֖וּ שִׁבְעִ֣ים אִ֑ישׁ וַיָּשִׂ֤ימוּ אֶת רָֽאשֵׁיהֶם֙ בַּדּוּדִ֔ים וַיִּשְׁלְח֥וּ אֵלָ֖יו יִזְרְעֶֽאלָה'),
(9802, 12, 'WLC', 'WLC', 'he', '2KI', 10, 8, 'OT', 'וַיָּבֹ֤א הַמַּלְאָךְ֙ וַיַּגֶּד ל֣וֹ לֵאמֹ֔ר הֵבִ֖יאוּ רָאשֵׁ֣י בְנֵֽי הַמֶּ֑לֶךְ וַיֹּ֗אמֶר שִׂ֣ימוּ אֹתָ֞ם שְׁנֵ֧י צִבֻּרִ֛ים פֶּ֥תַח הַשַּׁ֖עַר עַד הַבֹּֽקֶר'),
(9803, 12, 'WLC', 'WLC', 'he', '2KI', 10, 9, 'OT', 'וַיְהִ֤י בַבֹּ֨קֶר֙ וַיֵּצֵ֣א וַֽיַּעֲמֹ֔ד וַיֹּ֨אמֶר֙ אֶל כָּל הָעָ֔ם צַדִּקִ֖ים אַתֶּ֑ם הִנֵּ֨ה אֲנִ֜י קָשַׁ֤רְתִּי עַל אֲדֹנִי֙ וָאֶהְרְגֵ֔הוּ וּמִ֥י הִכָּ֖ה אֶת כָּל אֵֽלֶּה'),
(9804, 12, 'WLC', 'WLC', 'he', '2KI', 10, 10, 'OT', 'דְּע֣וּ אֵפ֗וֹא כִּי֩ לֹ֨א יִפֹּ֜ל מִדְּבַ֤ר יְהוָה֙ אַ֔רְצָה אֲשֶׁר דִּבֶּ֥ר יְהוָ֖ה עַל בֵּ֣ית אַחְאָ֑ב וַיהוָ֣ה עָשָׂ֔ה אֵ֚ת אֲשֶׁ֣ר דִּבֶּ֔ר בְּיַ֖ד עַבְדּ֥וֹ אֵלִיָּֽהוּ'),
(9805, 12, 'WLC', 'WLC', 'he', '2KI', 10, 11, 'OT', 'וַיַּ֣ךְ יֵה֗וּא אֵ֣ת כָּל הַנִּשְׁאָרִ֤ים לְבֵית אַחְאָב֙ בְּיִזְרְעֶ֔אל וְכָל גְּדֹלָ֖יו וּמְיֻדָּעָ֣יו וְכֹהֲנָ֑יו עַד בִּלְתִּ֥י הִשְׁאִֽיר ל֖וֹ שָׂרִֽיד'),
(9806, 12, 'WLC', 'WLC', 'he', '2KI', 10, 12, 'OT', 'וַיָּ֨קָם֙ וַיָּבֹ֔א וַיֵּ֖לֶךְ שֹׁמְר֑וֹן ה֛וּא בֵּֽית עֵ֥קֶד הָרֹעִ֖ים בַּדָּֽרֶךְ'),
(9807, 12, 'WLC', 'WLC', 'he', '2KI', 10, 13, 'OT', 'וְיֵה֗וּא מָצָא֙ אֶת אֲחֵי֙ אֲחַזְיָ֣הוּ מֶֽלֶךְ יְהוּדָ֔ה וַיֹּ֖אמֶר מִ֣י אַתֶּ֑ם וַיֹּאמְר֗וּ אֲחֵ֤י אֲחַזְיָ֨הוּ֙ אֲנַ֔חְנוּ וַנֵּ֛רֶד לִשְׁל֥וֹם בְּנֵֽי הַמֶּ֖לֶךְ וּבְנֵ֥י הַגְּבִירָֽה'),
(9808, 12, 'WLC', 'WLC', 'he', '2KI', 10, 14, 'OT', 'וַיֹּ֨אמֶר֙ תִּפְשׂ֣וּם חַיִּ֔ים וַֽיִּתְפְּשׂ֖וּם חַיִּ֑ים וַֽיִּשְׁחָט֞וּם אֶל בּ֣וֹר בֵּֽית עֵ֗קֶד אַרְבָּעִ֤ים וּשְׁנַ֨יִם֙ אִ֔ישׁ וְלֹֽא הִשְׁאִ֥יר אִ֖ישׁ מֵהֶֽם'),
(9809, 12, 'WLC', 'WLC', 'he', '2KI', 10, 15, 'OT', 'וַיֵּ֣לֶךְ מִשָּׁ֡ם וַיִּמְצָ֣א אֶת יְהוֹנָדָב֩ בֶּן רֵכָ֨ב לִקְרָאת֜וֹ וַֽיְבָרְכֵ֗הוּ וַיֹּ֨אמֶר אֵלָ֜יו הֲיֵ֧שׁ אֶת לְבָבְךָ֣ יָשָׁ֗ר כַּאֲשֶׁ֤ר לְבָבִי֙ עִם לְבָבֶ֔ךָ וַיֹּ֨אמֶר יְהוֹנָדָ֥ב יֵ֛שׁ וָיֵ֖שׁ תְּנָ֣ה אֶת יָדֶ֑ךָ וַיִּתֵּ֣ן יָד֔וֹ וַיַּעֲלֵ֥הוּ אֵלָ֖יו אֶל הַמֶּרְכָּבָֽה'),
(9810, 12, 'WLC', 'WLC', 'he', '2KI', 10, 16, 'OT', 'וַיֹּ֨אמֶר֙ לְכָ֣ה אִתִּ֔י וּרְאֵ֖ה בְּקִנְאָתִ֣י לַיהוָ֑ה וַיַּרְכִּ֥בוּ אֹת֖וֹ בְּרִכְבּֽוֹ'),
