(9844, 12, 'WLC', 'WLC', 'he', '2KI', 11, 14, 'OT', 'וַתֵּ֡רֶא וְהִנֵּ֣ה הַמֶּלֶךְ֩ עֹמֵ֨ד עַֽל הָעַמּ֜וּד כַּמִּשְׁפָּ֗ט וְהַשָּׂרִ֤ים וְהַחֲצֹֽצְרוֹת֙ אֶל הַמֶּ֔לֶךְ וְכָל עַ֤ם הָאָ֨רֶץ֙ שָׂמֵ֔חַ וְתֹקֵ֖עַ בַּחֲצֹֽצְר֑וֹת וַתִּקְרַ֤ע עֲתַלְיָה֙ אֶת בְּגָדֶ֔יהָ וַתִּקְרָ֖א קֶ֥שֶׁר קָֽשֶׁר'),
(9845, 12, 'WLC', 'WLC', 'he', '2KI', 11, 15, 'OT', 'וַיְצַו֩ יְהוֹיָדָ֨ע הַכֹּהֵ֜ן אֶת שָׂרֵ֥י המיאות פְּקֻדֵ֣י הַחַ֗יִל וַיֹּ֤אמֶר אֲלֵיהֶם֙ הוֹצִ֤יאוּ אֹתָהּ֙ אֶל מִבֵּ֣ית לַשְּׂדֵרֹ֔ת וְהַבָּ֥א אַחֲרֶ֖יהָ הָמֵ֣ת בֶּחָ֑רֶב כִּ֚י אָמַ֣ר הַכֹּהֵ֔ן אַל תּוּמַ֖ת בֵּ֥ית יְהוָֽה'),
(9846, 12, 'WLC', 'WLC', 'he', '2KI', 11, 16, 'OT', 'וַיָּשִׂ֤מוּ לָהּ֙ יָדַ֔יִם וַתָּב֛וֹא דֶּֽרֶךְ מְב֥וֹא הַסּוּסִ֖ים בֵּ֣ית הַמֶּ֑לֶךְ וַתּוּמַ֖ת שָֽׁם'),
(9847, 12, 'WLC', 'WLC', 'he', '2KI', 11, 17, 'OT', 'וַיִּכְרֹ֨ת יְהוֹיָדָ֜ע אֶֽת הַבְּרִ֗ית בֵּ֤ין יְהוָה֙ וּבֵ֤ין הַמֶּ֨לֶךְ֙ וּבֵ֣ין הָעָ֔ם לִהְי֥וֹת לְעָ֖ם לַֽיהוָ֑ה וּבֵ֥ין הַמֶּ֖לֶךְ וּבֵ֥ין הָעָֽם'),
(9848, 12, 'WLC', 'WLC', 'he', '2KI', 11, 18, 'OT', 'וַיָּבֹ֣אוּ כָל עַם֩ הָאָ֨רֶץ בֵּית הַבַּ֜עַל וַֽיִּתְּצֻ֗הוּ אֶת מזבחתו וְאֶת צְלָמָיו֙ שִׁבְּר֣וּ הֵיטֵ֔ב וְאֵ֗ת מַתָּן֙ כֹּהֵ֣ן הַבַּ֔עַל הָרְג֖וּ לִפְנֵ֣י הַֽמִּזְבְּח֑וֹת וַיָּ֧שֶׂם הַכֹּהֵ֛ן פְּקֻדּ֖וֹת עַל בֵּ֥ית יְהוָֽה'),
(9849, 12, 'WLC', 'WLC', 'he', '2KI', 11, 19, 'OT', 'וַיִּקַּ֣ח אֶת שָׂרֵ֣י הַ֠מֵּאוֹת וְאֶת הַכָּרִ֨י וְאֶת הָרָצִ֜ים וְאֵ֣ת כָּל עַ֣ם הָאָ֗רֶץ וַיֹּרִ֤ידוּ אֶת הַמֶּ֨לֶךְ֙ מִבֵּ֣ית יְהוָ֔ה וַיָּב֛וֹאוּ דֶּֽרֶך שַׁ֥עַר הָרָצִ֖ים בֵּ֣ית הַמֶּ֑לֶךְ וַיֵּ֖שֶׁב עַל כִּסֵּ֥א הַמְּלָכִֽים'),
(9850, 12, 'WLC', 'WLC', 'he', '2KI', 11, 20, 'OT', 'וַיִּשְׂמַ֥ח כָּל עַם הָאָ֖רֶץ וְהָעִ֣יר שָׁקָ֑טָה וְאֶת עֲתַלְיָ֛הוּ הֵמִ֥יתוּ בַחֶ֖רֶב בֵּ֥ית מלך'),
(9851, 12, 'WLC', 'WLC', 'he', '2KI', 11, 21, 'OT', 'בֶּן שֶׁ֥בַע שָׁנִ֖ים יְהוֹאָ֥שׁ בְּמָלְכֽוֹ'),
