(9971, 12, 'WLC', 'WLC', 'he', '2KI', 16, 7, 'OT', 'וַיִּשְׁלַ֨ח אָחָ֜ז מַלְאָכִ֗ים אֶל תִּ֠גְלַת פְּלֶ֤סֶר מֶֽלֶךְ אַשּׁוּר֙ לֵאמֹ֔ר עַבְדְּךָ֥ וּבִנְךָ֖ אָ֑נִי עֲלֵ֨ה וְהוֹשִׁעֵ֜נִי מִכַּ֣ף מֶֽלֶךְ אֲרָ֗ם וּמִכַּף֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל הַקּוֹמִ֖ים עָלָֽי'),
(9972, 12, 'WLC', 'WLC', 'he', '2KI', 16, 8, 'OT', 'וַיִּקַּ֨ח אָחָ֜ז אֶת הַכֶּ֣סֶף וְאֶת הַזָּהָ֗ב הַנִּמְצָא֙ בֵּ֣ית יְהוָ֔ה וּבְאֹֽצְר֖וֹת בֵּ֣ית הַמֶּ֑לֶךְ וַיִּשְׁלַ֥ח לְמֶֽלֶךְ אַשּׁ֖וּר שֹֽׁחַד'),
(9973, 12, 'WLC', 'WLC', 'he', '2KI', 16, 9, 'OT', 'וַיִּשְׁמַ֤ע אֵלָיו֙ מֶ֣לֶךְ אַשּׁ֔וּר וַיַּעַל֩ מֶ֨לֶךְ אַשּׁ֤וּר אֶל דַּמֶּ֨שֶׂק֙ וַֽיִּתְפְּשֶׂ֔הָ וַיַּגְלֶ֖הָ קִ֑ירָה וְאֶת רְצִ֖ין הֵמִֽית'),
(9974, 12, 'WLC', 'WLC', 'he', '2KI', 16, 10, 'OT', 'וַיֵּ֣לֶךְ הַמֶּ֣לֶךְ אָחָ֡ז לִ֠קְרַאת תִּגְלַ֨ת פִּלְאֶ֤סֶר מֶֽלֶךְ אַשּׁוּר֙ דּוּמֶּ֔שֶׂק וַיַּ֥רְא אֶת הַמִּזְבֵּ֖חַ אֲשֶׁ֣ר בְּדַמָּ֑שֶׂק וַיִּשְׁלַח֩ הַמֶּ֨לֶךְ אָחָ֜ז אֶל אוּרִיָּ֣ה הַכֹּהֵ֗ן אֶת דְּמ֧וּת הַמִּזְבֵּ֛חַ וְאֶת תַּבְנִית֖וֹ לְכָֽל מַעֲשֵֽׂהוּ'),
(9975, 12, 'WLC', 'WLC', 'he', '2KI', 16, 11, 'OT', 'וַיִּ֛בֶן אוּרִיָּ֥ה הַכֹּהֵ֖ן אֶת הַמִּזְבֵּ֑חַ כְּכֹ֣ל אֲשֶׁר שָׁלַח֩ הַמֶּ֨לֶךְ אָחָ֜ז מִדַּמֶּ֗שֶׂק כֵּ֤ן עָשָׂה֙ אוּרִיָּ֣ה הַכֹּהֵ֔ן עַד בּ֥וֹא הַמֶּֽלֶךְ אָחָ֖ז מִדַּמָּֽשֶׂק'),
(9976, 12, 'WLC', 'WLC', 'he', '2KI', 16, 12, 'OT', 'וַיָּבֹ֤א הַמֶּ֨לֶךְ֙ מִדַּמֶּ֔שֶׂק וַיַּ֥רְא הַמֶּ֖לֶךְ אֶת הַמִּזְבֵּ֑חַ וַיִּקְרַ֥ב הַמֶּ֛לֶךְ עַל הַמִּזְבֵּ֖חַ וַיַּ֥עַל עָלָֽיו'),
(9977, 12, 'WLC', 'WLC', 'he', '2KI', 16, 13, 'OT', 'וַיַּקְטֵ֤ר אֶת עֹֽלָתוֹ֙ וְאֶת מִנְחָת֔וֹ וַיַּסֵּ֖ךְ אֶת נִסְכּ֑וֹ וַיִּזְרֹ֛ק אֶת דַּֽם הַשְּׁלָמִ֥ים אֲשֶׁר ל֖וֹ עַל הַמִּזְבֵּֽחַ'),
(9978, 12, 'WLC', 'WLC', 'he', '2KI', 16, 14, 'OT', 'וְאֵ֨ת הַמִּזְבַּ֣ח הַנְּחֹשֶׁת֮ אֲשֶׁ֣ר לִפְנֵ֣י יְהוָה֒ וַיַּקְרֵ֗ב מֵאֵת֙ פְּנֵ֣י הַבַּ֔יִת מִבֵּין֙ הַמִּזְבֵּ֔חַ וּמִבֵּ֖ין בֵּ֣ית יְהוָ֑ה וַיִּתֵּ֥ן אֹת֛וֹ עַל יֶ֥רֶךְ הַמִּזְבֵּ֖חַ צָפֽוֹנָה'),
(9979, 12, 'WLC', 'WLC', 'he', '2KI', 16, 15, 'OT', 'ויצוהו הַמֶּֽלֶךְ אָ֠חָז אֶת אוּרִיָּ֨ה הַכֹּהֵ֜ן לֵאמֹ֗ר עַ֣ל הַמִּזְבֵּ֣חַ הַגָּד֡וֹל הַקְטֵ֣ר אֶת עֹֽלַת הַבֹּקֶר֩ וְאֶת מִנְחַ֨ת הָעֶ֜רֶב וְֽאֶת עֹלַ֧ת הַמֶּ֣לֶךְ וְאֶת מִנְחָת֗וֹ וְ֠אֵת עֹלַ֞ת כָּל עַ֤ם הָאָ֨רֶץ֙ וּמִנְחָתָ֣ם וְנִסְכֵּיהֶ֔ם וְכָל דַּ֥ם עֹלָ֛ה וְכָל דַּם זֶ֖בַח עָלָ֣יו תִּזְרֹ֑ק וּמִזְבַּ֧ח הַנְּחֹ֛שֶׁת יִֽהְיֶה לִּ֖י לְבַקֵּֽר'),
(9980, 12, 'WLC', 'WLC', 'he', '2KI', 16, 16, 'OT', 'וַיַּ֖עַשׂ אוּרִיָּ֣ה הַכֹּהֵ֑ן כְּכֹ֥ל אֲשֶׁר צִוָּ֖ה הַמֶּ֥לֶךְ אָחָֽז'),
(9981, 12, 'WLC', 'WLC', 'he', '2KI', 16, 17, 'OT', 'וַיְקַצֵּץ֩ הַמֶּ֨לֶךְ אָחָ֜ז אֶת הַמִּסְגְּר֣וֹת הַמְּכֹנ֗וֹת וַיָּ֤סַר מֵֽעֲלֵיהֶם֙ ואת הַכִּיֹּ֔ר וְאֶת הַיָּ֣ם הוֹרִ֔ד מֵעַ֛ל הַבָּקָ֥ר הַנְּחֹ֖שֶׁת אֲשֶׁ֣ר תַּחְתֶּ֑יהָ וַיִּתֵּ֣ן אֹת֔וֹ עַ֖ל מַרְצֶ֥פֶת אֲבָנִֽים'),
(9982, 12, 'WLC', 'WLC', 'he', '2KI', 16, 18, 'OT', 'וְאֶת מיסך הַשַּׁבָּ֜ת אֲשֶׁר בָּנ֣וּ בַבַּ֗יִת וְאֶת מְב֤וֹא הַמֶּ֨לֶךְ֙ הַֽחִיצ֔וֹנָה הֵסֵ֖ב בֵּ֣ית יְהוָ֑ה מִפְּנֵ֖י מֶ֥לֶךְ אַשּֽׁוּר'),
(9983, 12, 'WLC', 'WLC', 'he', '2KI', 16, 19, 'OT', 'וְיֶ֛תֶר דִּבְרֵ֥י אָחָ֖ז אֲשֶׁ֣ר עָשָׂ֑ה הֲלֹא הֵ֣ם כְּתוּבִ֗ים עַל סֵ֛פֶר דִּבְרֵ֥י הַיָּמִ֖ים לְמַלְכֵ֥י יְהוּדָֽה'),
(9984, 12, 'WLC', 'WLC', 'he', '2KI', 16, 20, 'OT', 'וַיִּשְׁכַּ֤ב אָחָז֙ עִם אֲבֹתָ֔יו וַיִּקָּבֵ֥ר עִם אֲבֹתָ֖יו בְּעִ֣יר דָּוִ֑ד וַיִּמְלֹ֛ךְ חִזְקִיָּ֥הוּ בְנ֖וֹ תַּחְתָּֽיו'),
(9985, 12, 'WLC', 'WLC', 'he', '2KI', 17, 1, 'OT', 'בִּשְׁנַת֙ שְׁתֵּ֣ים עֶשְׂרֵ֔ה לְאָחָ֖ז מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ הוֹשֵׁ֨עַ בֶּן אֵלָ֧ה בְשֹׁמְר֛וֹן עַל יִשְׂרָאֵ֖ל תֵּ֥שַׁע שָׁנִֽים'),
