(9987, 12, 'WLC', 'WLC', 'he', '2KI', 17, 3, 'OT', 'עָלָ֣יו עָלָ֔ה שַׁלְמַנְאֶ֖סֶר מֶ֣לֶךְ אַשּׁ֑וּר וַֽיְהִי ל֤וֹ הוֹשֵׁ֨עַ֙ עֶ֔בֶד וַיָּ֥שֶׁב ל֖וֹ מִנְחָֽה'),
(9988, 12, 'WLC', 'WLC', 'he', '2KI', 17, 4, 'OT', 'וַיִּמְצָא֩ מֶֽלֶךְ אַשּׁ֨וּר בְּהוֹשֵׁ֜עַ קֶ֗שֶׁר אֲשֶׁ֨ר שָׁלַ֤ח מַלְאָכִים֙ אֶל ס֣וֹא מֶֽלֶךְ מִצְרַ֔יִם וְלֹא הֶעֱלָ֥ה מִנְחָ֛ה לְמֶ֥לֶךְ אַשּׁ֖וּר כְּשָׁנָ֣ה בְשָׁנָ֑ה וַֽיַּעַצְרֵ֨הוּ֙ מֶ֣לֶךְ אַשּׁ֔וּר וַיַּאַסְרֵ֖הוּ בֵּ֥ית כֶּֽלֶא'),
(9989, 12, 'WLC', 'WLC', 'he', '2KI', 17, 5, 'OT', 'וַיַּ֥עַל מֶֽלֶךְ אַשּׁ֖וּר בְּכָל הָאָ֑רֶץ וַיַּ֨עַל֙ שֹׁמְר֔וֹן וַיָּ֥צַר עָלֶ֖יהָ שָׁלֹ֥שׁ שָׁנִֽים'),
(9990, 12, 'WLC', 'WLC', 'he', '2KI', 17, 6, 'OT', 'בִּשְׁנַ֨ת הַתְּשִׁיעִ֜ית לְהוֹשֵׁ֗עַ לָכַ֤ד מֶֽלֶךְ אַשּׁוּר֙ אֶת שֹׁ֣מְר֔וֹן וַיֶּ֥גֶל אֶת יִשְׂרָאֵ֖ל אַשּׁ֑וּרָה וַיֹּ֨שֶׁב אֹתָ֜ם בַּחְלַ֧ח וּבְחָב֛וֹר נְהַ֥ר גּוֹזָ֖ן וְעָרֵ֥י מָדָֽי'),
(9991, 12, 'WLC', 'WLC', 'he', '2KI', 17, 7, 'OT', 'וַיְהִ֗י כִּֽי חָטְא֤וּ בְנֵֽי יִשְׂרָאֵל֙ לַיהוָ֣ה אֱלֹהֵיהֶ֔ם הַמַּעֲלֶ֤ה אֹתָם֙ מֵאֶ֣רֶץ מִצְרַ֔יִם מִתַּ֕חַת יַ֖ד פַּרְעֹ֣ה מֶֽלֶךְ מִצְרָ֑יִם וַיִּֽירְא֖וּ אֱלֹהִ֥ים אֲחֵרִֽים'),
(9992, 12, 'WLC', 'WLC', 'he', '2KI', 17, 8, 'OT', 'וַיֵּֽלְכוּ֙ בְּחֻקּ֣וֹת הַגּוֹיִ֔ם אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִפְּנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל וּמַלְכֵ֥י יִשְׂרָאֵ֖ל אֲשֶׁ֥ר עָשֽׂוּ'),
(9993, 12, 'WLC', 'WLC', 'he', '2KI', 17, 9, 'OT', 'וַיְחַפְּא֣וּ בְנֵֽי יִשְׂרָאֵ֗ל דְּבָרִים֙ אֲשֶׁ֣ר לֹא כֵ֔ן עַל יְהוָ֖ה אֱלֹהֵיהֶ֑ם וַיִּבְנ֨וּ לָהֶ֤ם בָּמוֹת֙ בְּכָל עָ֣רֵיהֶ֔ם מִמִּגְדַּ֥ל נוֹצְרִ֖ים עַד עִ֥יר מִבְצָֽר'),
(9994, 12, 'WLC', 'WLC', 'he', '2KI', 17, 10, 'OT', 'וַיַּצִּ֧בוּ לָהֶ֛ם מַצֵּב֖וֹת וַאֲשֵׁרִ֑ים עַ֚ל כָּל גִּבְעָ֣ה גְבֹהָ֔ה וְתַ֖חַת כָּל עֵ֥ץ רַעֲנָֽן'),
(9995, 12, 'WLC', 'WLC', 'he', '2KI', 17, 11, 'OT', 'וַיְקַטְּרוּ שָׁם֙ בְּכָל בָּמ֔וֹת כַּגּוֹיִ֕ם אֲשֶׁר הֶגְלָ֥ה יְהוָ֖ה מִפְּנֵיהֶ֑ם וַֽיַּעֲשׂוּ֙ דְּבָרִ֣ים רָעִ֔ים לְהַכְעִ֖יס אֶת יְהוָֽה'),
(9996, 12, 'WLC', 'WLC', 'he', '2KI', 17, 12, 'OT', 'וַיַּֽעַבְד֖וּ הַגִּלֻּלִ֑ים אֲשֶׁ֨ר אָמַ֤ר יְהוָה֙ לָהֶ֔ם לֹ֥א תַעֲשׂ֖וּ אֶת הַדָּבָ֥ר הַזֶּֽה'),
(9997, 12, 'WLC', 'WLC', 'he', '2KI', 17, 13, 'OT', 'וַיָּ֣עַד יְהוָ֡ה בְּיִשְׂרָאֵ֣ל וּבִיהוּדָ֡ה בְּיַד֩ כָּל נביאו כָל חֹזֶ֜ה לֵאמֹ֗ר שֻׁ֝֠בוּ מִדַּרְכֵיכֶ֤ם הָֽרָעִים֙ וְשִׁמְרוּ֙ מִצְוֺתַ֣י חֻקּוֹתַ֔י כְּכָ֨ל הַתּוֹרָ֔ה אֲשֶׁ֥ר צִוִּ֖יתִי אֶת אֲבֹֽתֵיכֶ֑ם וַֽאֲשֶׁר֙ שָׁלַ֣חְתִּי אֲלֵיכֶ֔ם בְּיַ֖ד עֲבָדַ֥י הַנְּבִיאִֽים'),
(9998, 12, 'WLC', 'WLC', 'he', '2KI', 17, 14, 'OT', 'וְלֹ֖א שָׁמֵ֑עוּ וַיַּקְשׁ֤וּ אֶת עָרְפָּם֙ כְּעֹ֣רֶף אֲבוֹתָ֔ם אֲשֶׁר֙ לֹ֣א הֶאֱמִ֔ינוּ בַּֽיהוָ֖ה אֱלֹהֵיהֶֽם'),
(9999, 12, 'WLC', 'WLC', 'he', '2KI', 17, 15, 'OT', 'וַיִּמְאֲס֣וּ אֶת חֻקָּ֗יו וְאֶת בְּרִיתוֹ֙ אֲשֶׁ֣ר כָּרַ֣ת אֶת אֲבוֹתָ֔ם וְאֵת֙ עֵֽדְוֺתָ֔יו אֲשֶׁ֥ר הֵעִ֖יד בָּ֑ם וַיֵּ֨לְכ֜וּ אַחֲרֵ֤י הַהֶ֨בֶל֙ וַיֶּהְבָּ֔לוּ וְאַחֲרֵ֤י הַגּוֹיִם֙ אֲשֶׁ֣ר סְבִֽיבֹתָ֔ם אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ אֹתָ֔ם לְבִלְתִּ֖י עֲשׂ֥וֹת כָּהֶֽם'),
(10000, 12, 'WLC', 'WLC', 'he', '2KI', 17, 16, 'OT', 'וַיַּעַזְב֗וּ אֶת כָּל מִצְוֺת֙ יְהוָ֣ה אֱלֹהֵיהֶ֔ם וַיַּעֲשׂ֥וּ לָהֶ֛ם מַסֵּכָ֖ה שנים עֲגָלִ֑ים וַיַּעֲשׂ֣וּ אֲשֵׁירָ֗ה וַיִּֽשְׁתַּחֲווּ֙ לְכָל צְבָ֣א הַשָּׁמַ֔יִם וַיַּעַבְד֖וּ אֶת הַבָּֽעַל'),
(10001, 12, 'WLC', 'WLC', 'he', '2KI', 17, 17, 'OT', 'וַֽ֠יַּעֲבִירוּ אֶת בְּנֵיהֶ֤ם וְאֶת בְּנֽוֹתֵיהֶם֙ בָּאֵ֔שׁ וַיִּקְסְמ֥וּ קְסָמִ֖ים וַיְנַחֵ֑שׁוּ וַיִּֽתְמַכְּר֗וּ לַעֲשׂ֥וֹת הָרַ֛ע בְּעֵינֵ֥י יְהוָ֖ה לְהַכְעִיסֽוֹ'),
