(10029, 12, 'WLC', 'WLC', 'he', '2KI', 18, 4, 'OT', 'ה֣וּא הֵסִ֣יר אֶת הַבָּמ֗וֹת וְשִׁבַּר֙ אֶת הַמַּצֵּבֹ֔ת וְכָרַ֖ת אֶת הָֽאֲשֵׁרָ֑ה וְכִתַּת֩ נְחַ֨שׁ הַנְּחֹ֜שֶׁת אֲשֶׁר עָשָׂ֣ה מֹשֶׁ֗ה כִּ֣י עַד הַיָּמִ֤ים הָהֵ֨מָּה֙ הָי֤וּ בְנֵֽי יִשְׂרָאֵל֙ מְקַטְּרִ֣ים ל֔וֹ וַיִּקְרָא ל֖וֹ נְחֻשְׁתָּֽן'),
(10030, 12, 'WLC', 'WLC', 'he', '2KI', 18, 5, 'OT', 'בַּיהוָ֥ה אֱלֹהֵֽי יִשְׂרָאֵ֖ל בָּטָ֑ח וְאַחֲרָ֞יו לֹא הָיָ֣ה כָמֹ֗הוּ בְּכֹל֙ מַלְכֵ֣י יְהוּדָ֔ה וַאֲשֶׁ֥ר הָי֖וּ לְפָנָֽיו'),
(10031, 12, 'WLC', 'WLC', 'he', '2KI', 18, 6, 'OT', 'וַיִּדְבַּק֙ בַּֽיהוָ֔ה לֹא סָ֖ר מֵאַֽחֲרָ֑יו וַיִּשְׁמֹר֙ מִצְוֺתָ֔יו אֲשֶׁר צִוָּ֥ה יְהוָ֖ה אֶת מֹשֶֽׁה'),
(10032, 12, 'WLC', 'WLC', 'he', '2KI', 18, 7, 'OT', 'וְהָיָ֤ה יְהוָה֙ עִמּ֔וֹ בְּכֹ֥ל אֲשֶׁר יֵצֵ֖א יַשְׂכִּ֑יל וַיִּמְרֹ֥ד בְּמֶֽלֶךְ אַשּׁ֖וּר וְלֹ֥א עֲבָדֽוֹ'),
(10033, 12, 'WLC', 'WLC', 'he', '2KI', 18, 8, 'OT', 'הֽוּא הִכָּ֧ה אֶת פְּלִשְׁתִּ֛ים עַד עַזָּ֖ה וְאֶת גְּבוּלֶ֑יהָ מִמִּגְדַּ֥ל נוֹצְרִ֖ים עַד עִ֥יר מִבְצָֽר'),
(10034, 12, 'WLC', 'WLC', 'he', '2KI', 18, 9, 'OT', 'וַֽיְהִ֞י בַּשָּׁנָ֤ה הָֽרְבִיעִית֙ לַמֶּ֣לֶךְ חִזְקִיָּ֔הוּ הִ֚יא הַשָּׁנָ֣ה הַשְּׁבִיעִ֔ית לְהוֹשֵׁ֥עַ בֶּן אֵלָ֖ה מֶ֣לֶךְ יִשְׂרָאֵ֑ל עָלָ֞ה שַׁלְמַנְאֶ֧סֶר מֶֽלֶךְ אַשּׁ֛וּר עַל שֹׁמְר֖וֹן וַיָּ֥צַר עָלֶֽיהָ'),
(10035, 12, 'WLC', 'WLC', 'he', '2KI', 18, 10, 'OT', 'וַֽיִּלְכְּדֻ֗הָ מִקְצֵה֙ שָׁלֹ֣שׁ שָׁנִ֔ים בִּשְׁנַת שֵׁ֖שׁ לְחִזְקִיָּ֑ה הִ֣יא שְׁנַת תֵּ֗שַׁע לְהוֹשֵׁ֨עַ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל נִלְכְּדָ֖ה שֹׁמְרֽוֹן'),
(10036, 12, 'WLC', 'WLC', 'he', '2KI', 18, 11, 'OT', 'וַיֶּ֧גֶל מֶֽלֶךְ אַשּׁ֛וּר אֶת יִשְׂרָאֵ֖ל אַשּׁ֑וּרָה וַיַּנְחֵ֞ם בַּחְלַ֧ח וּבְחָב֛וֹר נְהַ֥ר גּוֹזָ֖ן וְעָרֵ֥י מָדָֽי'),
(10037, 12, 'WLC', 'WLC', 'he', '2KI', 18, 12, 'OT', 'עַ֣ל אֲשֶׁ֣ר לֹֽא שָׁמְע֗וּ בְּקוֹל֙ יְהוָ֣ה אֱלֹהֵיהֶ֔ם וַיַּעַבְרוּ֙ אֶת בְּרִית֔וֹ אֵ֚ת כָּל אֲשֶׁ֣ר צִוָּ֔ה מֹשֶׁ֖ה עֶ֣בֶד יְהוָ֑ה וְלֹ֥א שָׁמְע֖וּ וְלֹ֥א עָשֽׂוּ'),
(10038, 12, 'WLC', 'WLC', 'he', '2KI', 18, 13, 'OT', 'וּבְאַרְבַּע֩ עֶשְׂרֵ֨ה שָׁנָ֜ה לַמֶּ֣לֶךְ חִזְקִיָּ֗ה עָלָ֞ה סַנְחֵרִ֤יב מֶֽלֶךְ אַשּׁוּר֙ עַ֣ל כָּל עָרֵ֧י יְהוּדָ֛ה הַבְּצֻר֖וֹת וַֽיִּתְפְּשֵֽׂם'),
(10039, 12, 'WLC', 'WLC', 'he', '2KI', 18, 14, 'OT', 'וַיִּשְׁלַ֣ח חִזְקִיָּ֣ה מֶֽלֶךְ יְהוּדָ֣ה אֶל מֶֽלֶךְ אַשּׁוּר֩ לָכִ֨ישָׁה לֵאמֹ֤ר חָטָ֨אתִי֙ שׁ֣וּב מֵֽעָלַ֔י אֵ֛ת אֲשֶׁר תִּתֵּ֥ן עָלַ֖י אֶשָּׂ֑א וַיָּ֨שֶׂם מֶֽלֶךְ אַשּׁ֜וּר עַל חִזְקִיָּ֣ה מֶֽלֶךְ יְהוּדָ֗ה שְׁלֹ֤שׁ מֵאוֹת֙ כִּכַּר כֶּ֔סֶף וּשְׁלֹשִׁ֖ים כִּכַּ֥ר זָהָֽב'),
(10040, 12, 'WLC', 'WLC', 'he', '2KI', 18, 15, 'OT', 'וַיִּתֵּן֙ חִזְקִיָּ֔ה אֶת כָּל הַכֶּ֖סֶף הַנִּמְצָ֣א בֵית יְהוָ֑ה וּבְאֹצְר֖וֹת בֵּ֥ית הַמֶּֽלֶךְ'),
(10041, 12, 'WLC', 'WLC', 'he', '2KI', 18, 16, 'OT', 'בָּעֵ֣ת הַהִ֗יא קִצַּ֨ץ חִזְקִיָּ֜ה אֶת דַּלְת֨וֹת הֵיכַ֤ל יְהוָה֙ וְאֶת הָאֹ֣מְנ֔וֹת אֲשֶׁ֣ר צִפָּ֔ה חִזְקִיָּ֖ה מֶ֣לֶךְ יְהוּדָ֑ה וַֽיִּתְּנֵ֖ם לְמֶ֥לֶךְ אַשּֽׁוּר'),
(10042, 12, 'WLC', 'WLC', 'he', '2KI', 18, 17, 'OT', 'וַיִּשְׁלַ֣ח מֶֽלֶךְ אַשּׁ֡וּר אֶת תַּרְתָּ֥ן וְאֶת רַב סָרִ֣יס וְאֶת רַב שָׁקֵ֨ה מִן לָכִ֜ישׁ אֶל הַמֶּ֧לֶךְ חִזְקִיָּ֛הוּ בְּחֵ֥יל כָּבֵ֖ד יְרוּשָׁלִָ֑ם וַֽיַּעֲלוּ֙ וַיָּבֹ֣אוּ יְרוּשָׁלִַ֔ם וַיַּעֲל֣וּ וַיָּבֹ֗אוּ וַיַּֽעַמְדוּ֙ בִּתְעָלַת֙ הַבְּרֵכָ֣ה הָֽעֶלְיוֹנָ֔ה אֲשֶׁ֕ר בִּמְסִלַּ֖ת שְׂדֵ֥ה כוֹבֵֽס'),
(10043, 12, 'WLC', 'WLC', 'he', '2KI', 18, 18, 'OT', 'וַֽיִּקְרְאוּ֙ אֶל הַמֶּ֔לֶךְ וַיֵּצֵ֧א אֲלֵהֶ֛ם אֶלְיָקִ֥ים בֶּן חִלְקִיָּ֖הוּ אֲשֶׁ֣ר עַל הַבָּ֑יִת וְשֶׁבְנָה֙ הַסֹּפֵ֔ר וְיוֹאָ֥ח בֶּן אָסָ֖ף הַמַּזְכִּֽיר'),
(10044, 12, 'WLC', 'WLC', 'he', '2KI', 18, 19, 'OT', 'וַיֹּ֤אמֶר אֲלֵהֶם֙ רַב שָׁקֵ֔ה אִמְרוּ נָ֖א אֶל חִזְקִיָּ֑הוּ כֹּֽה אָמַ֞ר הַמֶּ֤לֶךְ הַגָּדוֹל֙ מֶ֣לֶךְ אַשּׁ֔וּר מָ֧ה הַבִּטָּח֛וֹן הַזֶּ֖ה אֲשֶׁ֥ר בָּטָֽחְתָּ'),
(10045, 12, 'WLC', 'WLC', 'he', '2KI', 18, 20, 'OT', 'אָמַ֨רְתָּ֙ אַךְ דְּבַר שְׂפָתַ֔יִם עֵצָ֥ה וּגְבוּרָ֖ה לַמִּלְחָמָ֑ה עַתָּה֙ עַל מִ֣י בָטַ֔חְתָּ כִּ֥י מָרַ֖דְתָּ בִּֽי'),
(10046, 12, 'WLC', 'WLC', 'he', '2KI', 18, 21, 'OT', 'עַתָּ֡ה הִנֵּ֣ה בָטַ֣חְתָּ לְּךָ֡ עַל מִשְׁעֶנֶת֩ הַקָּנֶ֨ה הָרָצ֤וּץ הַזֶּה֙ עַל מִצְרַ֔יִם אֲשֶׁ֨ר יִסָּמֵ֥ךְ אִישׁ֙ עָלָ֔יו וּבָ֥א בְכַפּ֖וֹ וּנְקָבָ֑הּ כֵּ֚ן פַּרְעֹ֣ה מֶֽלֶךְ מִצְרַ֔יִם לְכָֽל הַבֹּטְחִ֖ים עָלָֽיו'),
(10047, 12, 'WLC', 'WLC', 'he', '2KI', 18, 22, 'OT', 'וְכִי תֹאמְר֣וּן אֵלַ֔י אֶל יְהוָ֥ה אֱלֹהֵ֖ינוּ בָּטָ֑חְנוּ הֲלוֹא ה֗וּא אֲשֶׁ֨ר הֵסִ֤יר חִזְקִיָּ֨הוּ֙ אֶת בָּמֹתָ֣יו וְאֶת מִזְבְּחֹתָ֔יו וַיֹּ֤אמֶר לִֽיהוּדָה֙ וְלִיר֣וּשָׁלִַ֔ם לִפְנֵי֙ הַמִּזְבֵּ֣חַ הַזֶּ֔ה תִּֽשְׁתַּחֲו֖וּ בִּירוּשָׁלִָֽם'),
(10048, 12, 'WLC', 'WLC', 'he', '2KI', 18, 23, 'OT', 'וְעַתָּה֙ הִתְעָ֣רֶב נָ֔א אֶת אֲדֹנִ֖י אֶת מֶ֣לֶךְ אַשּׁ֑וּר וְאֶתְּנָ֤ה לְךָ֙ אַלְפַּ֣יִם סוּסִ֔ים אִם תּוּכַ֕ל לָ֥תֶת לְךָ֖ רֹכְבִ֥ים עֲלֵיהֶֽם'),
(10049, 12, 'WLC', 'WLC', 'he', '2KI', 18, 24, 'OT', 'וְאֵ֣יךְ תָּשִׁ֗יב אֵ֠ת פְּנֵ֨י פַחַ֥ת אַחַ֛ד עַבְדֵ֥י אֲדֹנִ֖י הַקְּטַנִּ֑ים וַתִּבְטַ֤ח לְךָ֙ עַל מִצְרַ֔יִם לְרֶ֖כֶב וּלְפָרָשִֽׁים'),
(10050, 12, 'WLC', 'WLC', 'he', '2KI', 18, 25, 'OT', 'עַתָּה֙ הֲמִבַּלְעֲדֵ֣י יְהוָ֔ה עָלִ֛יתִי עַל הַמָּק֥וֹם הַזֶּ֖ה לְהַשְׁחִת֑וֹ יְהוָה֙ אָמַ֣ר אֵלַ֔י עֲלֵ֛ה עַל הָאָ֥רֶץ הַזֹּ֖את וְהַשְׁחִיתָֽהּ'),
(10051, 12, 'WLC', 'WLC', 'he', '2KI', 18, 26, 'OT', 'וַיֹּ֣אמֶר אֶלְיָקִ֣ים בֶּן חִ֠לְקִיָּהוּ וְשֶׁבְנָ֨ה וְיוֹאָ֜ח אֶל רַב שָׁקֵ֗ה דַּבֶּר נָ֤א אֶל עֲבָדֶ֨יךָ֙ אֲרָמִ֔ית כִּ֥י שֹׁמְעִ֖ים אֲנָ֑חְנוּ וְאַל תְּדַבֵּ֤ר עִמָּ֨נוּ֙ יְהוּדִ֔ית בְּאָזְנֵ֣י הָעָ֔ם אֲשֶׁ֖ר עַל הַחֹמָֽה'),
(10052, 12, 'WLC', 'WLC', 'he', '2KI', 18, 27, 'OT', 'וַיֹּ֨אמֶר אֲלֵיהֶ֜ם רַב שָׁקֵ֗ה הַעַ֨ל אֲדֹנֶ֤יךָ וְאֵלֶ֨יךָ֙ שְׁלָחַ֣נִי אֲדֹנִ֔י לְדַבֵּ֖ר אֶת הַדְּבָרִ֣ים הָאֵ֑לֶּה הֲלֹ֣א עַל הָאֲנָשִׁ֗ים הַיֹּֽשְׁבִים֙ עַל הַ֣חֹמָ֔ה לֶאֱכֹ֣ל אֶת חריהם וְלִשְׁתּ֛וֹת אֶת שיניהם עִמָּכֶֽם'),
(10053, 12, 'WLC', 'WLC', 'he', '2KI', 18, 28, 'OT', 'וַֽיַּעֲמֹד֙ רַב שָׁקֵ֔ה וַיִּקְרָ֥א בְקוֹל גָּד֖וֹל יְהוּדִ֑ית וַיְדַבֵּ֣ר וַיֹּ֔אמֶר שִׁמְע֛וּ דְּבַר הַמֶּ֥לֶךְ הַגָּד֖וֹל מֶ֥לֶךְ אַשּֽׁוּר'),
(10054, 12, 'WLC', 'WLC', 'he', '2KI', 18, 29, 'OT', 'כֹּ֚ה אָמַ֣ר הַמֶּ֔לֶךְ אַל יַשִּׁ֥יא לָכֶ֖ם חִזְקִיָּ֑הוּ כִּי לֹ֣א יוּכַ֔ל לְהַצִּ֥יל אֶתְכֶ֖ם מִיָּדֽוֹ'),
(10055, 12, 'WLC', 'WLC', 'he', '2KI', 18, 30, 'OT', 'וְאַל יַבְטַ֨ח אֶתְכֶ֤ם חִזְקִיָּ֨הוּ֙ אֶל יְהוָ֣ה לֵאמֹ֔ר הַצֵּ֥ל יַצִּילֵ֖נוּ יְהוָ֑ה וְלֹ֤א תִנָּתֵן֙ אֶת הָעִ֣יר הַזֹּ֔את בְּיַ֖ד מֶ֥לֶךְ אַשּֽׁוּר'),
(10056, 12, 'WLC', 'WLC', 'he', '2KI', 18, 31, 'OT', 'אַֽל תִּשְׁמְע֖וּ אֶל חִזְקִיָּ֑הוּ כִּי֩ כֹ֨ה אָמַ֜ר מֶ֣לֶךְ אַשּׁ֗וּר עֲשֽׂוּ אִתִּ֤י בְרָכָה֙ וּצְא֣וּ אֵלַ֔י וְאִכְל֤וּ אִישׁ גַּפְנוֹ֙ וְאִ֣ישׁ תְּאֵֽנָת֔וֹ וּשְׁת֖וּ אִ֥ישׁ מֵֽי בוֹרֽוֹ'),
(10057, 12, 'WLC', 'WLC', 'he', '2KI', 18, 32, 'OT', 'עַד בֹּאִי֩ וְלָקַחְתִּ֨י אֶתְכֶ֜ם אֶל אֶ֣רֶץ כְּאַרְצְכֶ֗ם אֶרֶץ֩ דָּגָ֨ן וְתִיר֜וֹשׁ אֶ֧רֶץ לֶ֣חֶם וּכְרָמִ֗ים אֶ֣רֶץ זֵ֤ית יִצְהָר֙ וּדְבַ֔שׁ וִֽחְי֖וּ וְלֹ֣א תָמֻ֑תוּ וְאַֽל תִּשְׁמְעוּ֙ אֶל חִזְקִיָּ֔הוּ כִּֽי יַסִּ֤ית אֶתְכֶם֙ לֵאמֹ֔ר יְהוָ֖ה יַצִּילֵֽנוּ'),
(10058, 12, 'WLC', 'WLC', 'he', '2KI', 18, 33, 'OT', 'הַהַצֵּ֥ל הִצִּ֛ילוּ אֱלֹהֵ֥י הַגּוֹיִ֖ם אִ֣ישׁ אֶת אַרְצ֑וֹ מִיַּ֖ד מֶ֥לֶךְ אַשּֽׁוּר'),
