(10154, 12, 'WLC', 'WLC', 'he', '2KI', 22, 8, 'OT', 'וַ֠יֹּאמֶר חִלְקִיָּ֜הוּ הַכֹּהֵ֤ן הַגָּדוֹל֙ עַל שָׁפָ֣ן הַסֹּפֵ֔ר סֵ֧פֶר הַתּוֹרָ֛ה מָצָ֖אתִי בְּבֵ֣ית יְהוָ֑ה וַיִּתֵּ֨ן חִלְקִיָּ֧ה אֶת הַסֵּ֛פֶר אֶל שָׁפָ֖ן וַיִּקְרָאֵֽהוּ'),
(10155, 12, 'WLC', 'WLC', 'he', '2KI', 22, 9, 'OT', 'וַיָּבֹ֞א שָׁפָ֤ן הַסֹּפֵר֙ אֶל הַמֶּ֔לֶךְ וַיָּ֥שֶׁב אֶת הַמֶּ֖לֶךְ דָּבָ֑ר וַיֹּ֗אמֶר הִתִּ֤יכוּ עֲבָדֶ֨יךָ֙ אֶת הַכֶּ֨סֶף֙ הַנִּמְצָ֣א בַבַּ֔יִת וַֽיִּתְּנֻ֗הוּ עַל יַד֙ עֹשֵׂ֣י הַמְּלָאכָ֔ה הַמֻּפְקָדִ֖ים בֵּ֥ית יְהוָֽה'),
(10156, 12, 'WLC', 'WLC', 'he', '2KI', 22, 10, 'OT', 'וַיַּגֵּ֞ד שָׁפָ֤ן הַסֹּפֵר֙ לַמֶּ֣לֶךְ לֵאמֹ֔ר סֵ֚פֶר נָ֣תַן לִ֔י חִלְקִיָּ֖ה הַכֹּהֵ֑ן וַיִּקְרָאֵ֥הוּ שָׁפָ֖ן לִפְנֵ֥י הַמֶּֽלֶךְ'),
(10157, 12, 'WLC', 'WLC', 'he', '2KI', 22, 11, 'OT', 'וַֽיְהִי֙ כִּשְׁמֹ֣עַ הַמֶּ֔לֶךְ אֶת דִּבְרֵ֖י סֵ֣פֶר הַתּוֹרָ֑ה וַיִּקְרַ֖ע אֶת בְּגָדָֽיו'),
(10158, 12, 'WLC', 'WLC', 'he', '2KI', 22, 12, 'OT', 'וַיְצַ֣ו הַמֶּ֡לֶךְ אֶת חִלְקִיָּ֣ה הַכֹּהֵ֡ן וְאֶת אֲחִיקָ֣ם בֶּן שָׁ֠פָן וְאֶת עַכְבּ֨וֹר בֶּן מִיכָיָ֜ה וְאֵ֣ת שָׁפָ֣ן הַסֹּפֵ֗ר וְאֵ֛ת עֲשָׂיָ֥ה עֶֽבֶד הַמֶּ֖לֶךְ לֵאמֹֽר'),
(10159, 12, 'WLC', 'WLC', 'he', '2KI', 22, 13, 'OT', 'לְכוּ֩ דִרְשׁ֨וּ אֶת יְהוָ֜ה בַּעֲדִ֣י וּבְעַד הָעָ֗ם וּבְעַד֙ כָּל יְהוּדָ֔ה עַל דִּבְרֵ֛י הַסֵּ֥פֶר הַנִּמְצָ֖א הַזֶּ֑ה כִּֽי גְדוֹלָ֞ה חֲמַ֣ת יְהוָ֗ה אֲשֶׁר הִיא֙ נִצְּתָ֣ה בָ֔נוּ עַל֩ אֲשֶׁ֨ר לֹֽא שָׁמְע֜וּ אֲבֹתֵ֗ינוּ עַל דִּבְרֵי֙ הַסֵּ֣פֶר הַזֶּ֔ה לַעֲשׂ֖וֹת כְּכָל הַכָּת֥וּב עָלֵֽינוּ'),
(10160, 12, 'WLC', 'WLC', 'he', '2KI', 22, 14, 'OT', 'וַיֵּ֣לֶךְ חִלְקִיָּ֣הוּ הַ֠כֹּהֵן וַאֲחִיקָ֨ם וְעַכְבּ֜וֹר וְשָׁפָ֣ן וַעֲשָׂיָ֗ה אֶל חֻלְדָּ֨ה הַנְּבִיאָ֜ה אֵ֣שֶׁת שַׁלֻּ֣ם בֶּן תִּקְוָ֗ה בֶּן חַרְחַס֙ שֹׁמֵ֣ר הַבְּגָדִ֔ים וְהִ֛יא יֹשֶׁ֥בֶת בִּירוּשָׁלִַ֖ם בַּמִּשְׁנֶ֑ה וַֽיְדַבְּר֖וּ אֵלֶֽיהָ'),
(10161, 12, 'WLC', 'WLC', 'he', '2KI', 22, 15, 'OT', 'וַתֹּ֣אמֶר אֲלֵיהֶ֔ם כֹּֽה אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אִמְר֣וּ לָאִ֔ישׁ אֲשֶׁר שָׁלַ֥ח אֶתְכֶ֖ם אֵלָֽי'),
(10162, 12, 'WLC', 'WLC', 'he', '2KI', 22, 16, 'OT', 'כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְנִ֨י מֵבִ֥יא רָעָ֛ה אֶל הַמָּק֥וֹם הַזֶּ֖ה וְעַל יֹֽשְׁבָ֑יו אֵ֚ת כָּל דִּבְרֵ֣י הַסֵּ֔פֶר אֲשֶׁ֥ר קָרָ֖א מֶ֥לֶךְ יְהוּדָֽה'),
(10163, 12, 'WLC', 'WLC', 'he', '2KI', 22, 17, 'OT', 'תַּ֣חַת אֲשֶׁ֣ר עֲזָב֗וּנִי וַֽיְקַטְּרוּ֙ לֵאלֹהִ֣ים אֲחֵרִ֔ים לְמַ֨עַן֙ הַכְעִיסֵ֔נִי בְּכֹ֖ל מַעֲשֵׂ֣ה יְדֵיהֶ֑ם וְנִצְּתָ֧ה חֲמָתִ֛י בַּמָּק֥וֹם הַזֶּ֖ה וְלֹ֥א תִכְבֶּֽה'),
(10164, 12, 'WLC', 'WLC', 'he', '2KI', 22, 18, 'OT', 'וְאֶל מֶ֣לֶךְ יְהוּדָ֗ה הַשֹּׁלֵ֤חַ אֶתְכֶם֙ לִדְרֹ֣שׁ אֶת יְהוָ֔ה כֹּ֥ה תֹאמְר֖וּ אֵלָ֑יו כֹּֽה אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הַדְּבָרִ֖ים אֲשֶׁ֥ר שָׁמָֽעְתָּ'),
(10165, 12, 'WLC', 'WLC', 'he', '2KI', 22, 19, 'OT', 'יַ֠עַן רַךְ לְבָ֨בְךָ֜ וַתִּכָּנַ֣ע מִפְּנֵ֣י יְהוָ֗ה בְּֽשָׁמְעֲךָ֡ אֲשֶׁ֣ר דִּבַּרְתִּי֩ עַל הַמָּק֨וֹם הַזֶּ֜ה וְעַל יֹשְׁבָ֗יו לִהְי֤וֹת לְשַׁמָּה֙ וְלִקְלָלָ֔ה וַתִּקְרַע֙ אֶת בְּגָדֶ֔יךָ וַתִּבְכֶּ֖ה לְפָנָ֑י וְגַ֧ם אָנֹכִ֛י שָׁמַ֖עְתִּי נְאֻם יְהוָֽה'),
(10166, 12, 'WLC', 'WLC', 'he', '2KI', 22, 20, 'OT', 'לָכֵן֩ הִנְנִ֨י אֹֽסִפְךָ֜ עַל אֲבֹתֶ֗יךָ וְנֶאֱסַפְתָּ֣ אֶל קִבְרֹתֶיךָ֮ בְּשָׁלוֹם֒ וְלֹא תִרְאֶ֣ינָה עֵינֶ֔יךָ בְּכֹל֙ הָֽרָעָ֔ה אֲשֶׁר אֲנִ֥י מֵבִ֖יא עַל הַמָּק֣וֹם הַזֶּ֑ה וַיָּשִׁ֥יבוּ אֶת הַמֶּ֖לֶךְ דָּבָֽר'),
(10167, 12, 'WLC', 'WLC', 'he', '2KI', 23, 1, 'OT', 'וַיִּשְׁלַ֖ח הַמֶּ֑לֶךְ וַיַּאַסְפ֣וּ אֵלָ֔יו כָּל זִקְנֵ֥י יְהוּדָ֖ה וִירוּשָׁלִָֽם'),
(10168, 12, 'WLC', 'WLC', 'he', '2KI', 23, 2, 'OT', 'וַיַּ֣עַל הַמֶּ֣לֶךְ בֵּית יְהוָ֡ה וְכָל אִ֣ישׁ יְהוּדָה֩ וְכָל יֹשְׁבֵ֨י יְרוּשָׁלִַ֜ם אִתּ֗וֹ וְהַכֹּֽהֲנִים֙ וְהַנְּבִיאִ֔ים וְכָל הָעָ֖ם לְמִקָּטֹ֣ן וְעַד גָּד֑וֹל וַיִּקְרָ֣א בְאָזְנֵיהֶ֗ם אֶת כָּל דִּבְרֵי֙ סֵ֣פֶר הַבְּרִ֔ית הַנִּמְצָ֖א בְּבֵ֥ית יְהוָֽה'),
(10169, 12, 'WLC', 'WLC', 'he', '2KI', 23, 3, 'OT', 'וַיַּעֲמֹ֣ד הַ֠מֶּלֶךְ עַֽל הָ֨עַמּ֜וּד וַיִּכְרֹ֥ת אֶֽת הַבְּרִ֣ית לִפְנֵ֣י יְהוָ֗ה לָלֶ֜כֶת אַחַ֤ר יְהוָה֙ וְלִשְׁמֹ֨ר מִצְוֺתָ֜יו וְאֶת עֵדְוֺתָ֤יו וְאֶת חֻקֹּתָיו֙ בְּכָל לֵ֣ב וּבְכָל נֶ֔פֶשׁ לְהָקִ֗ים אֶת דִּבְרֵי֙ הַבְּרִ֣ית הַזֹּ֔את הַכְּתֻבִ֖ים עַל הַסֵּ֣פֶר הַזֶּ֑ה וַיַּעֲמֹ֥ד כָּל הָעָ֖ם בַּבְּרִֽית'),
(10170, 12, 'WLC', 'WLC', 'he', '2KI', 23, 4, 'OT', 'וַיְצַ֣ו הַמֶּ֡לֶךְ אֶת חִלְקִיָּהוּ֩ הַכֹּהֵ֨ן הַגָּד֜וֹל וְאֶת כֹּהֲנֵ֣י הַמִּשְׁנֶה֮ וְאֶת שֹׁמְרֵ֣י הַסַּף֒ לְהוֹצִיא֙ מֵהֵיכַ֣ל יְהוָ֔ה אֵ֣ת כָּל הַכֵּלִ֗ים הָֽעֲשׂוּיִם֙ לַבַּ֣עַל וְלָֽאֲשֵׁרָ֔ה וּלְכֹ֖ל צְבָ֣א הַשָּׁמָ֑יִם וַֽיִּשְׂרְפֵ֞ם מִח֤וּץ לִירוּשָׁלִַ֨ם֙ בְּשַׁדְמ֣וֹת קִדְר֔וֹן וְנָשָׂ֥א אֶת עֲפָרָ֖ם בֵּֽית אֵֽל'),
(10171, 12, 'WLC', 'WLC', 'he', '2KI', 23, 5, 'OT', 'וְהִשְׁבִּ֣ית אֶת הַכְּמָרִ֗ים אֲשֶׁ֤ר נָֽתְנוּ֙ מַלְכֵ֣י יְהוּדָ֔ה וַיְקַטֵּ֤ר בַּבָּמוֹת֙ בְּעָרֵ֣י יְהוּדָ֔ה וּמְסִבֵּ֖י יְרוּשָׁלִָ֑ם וְאֶת הַֽמְקַטְּרִ֣ים לַבַּ֗עַל לַשֶּׁ֤מֶשׁ וְלַיָּרֵ֨חַ֙ וְלַמַּזָּל֔וֹת וּלְכֹ֖ל צְבָ֥א הַשָּׁמָֽיִם'),
(10172, 12, 'WLC', 'WLC', 'he', '2KI', 23, 6, 'OT', 'וַיֹּצֵ֣א אֶת הָאֲשֵׁרָה֩ מִבֵּ֨ית יְהוָ֜ה מִח֤וּץ לִירוּשָׁלִַ֨ם֙ אֶל נַ֣חַל קִדְר֔וֹן וַיִּשְׂרֹ֥ף אֹתָ֛הּ בְּנַ֥חַל קִדְר֖וֹן וַיָּ֣דֶק לְעָפָ֑ר וַיַּשְׁלֵךְ֙ אֶת עֲפָרָ֔הּ עַל קֶ֖בֶר בְּנֵ֥י הָעָֽם'),
(10173, 12, 'WLC', 'WLC', 'he', '2KI', 23, 7, 'OT', 'וַיִּתֹּץ֙ אֶת בָּתֵּ֣י הַקְּדֵשִׁ֔ים אֲשֶׁ֖ר בְּבֵ֣ית יְהוָ֑ה אֲשֶׁ֣ר הַנָּשִׁ֗ים אֹרְג֥וֹת שָׁ֛ם בָּתִּ֖ים לָאֲשֵׁרָֽה'),
(10174, 12, 'WLC', 'WLC', 'he', '2KI', 23, 8, 'OT', 'וַיָּבֵ֤א אֶת כָּל הַכֹּֽהֲנִים֙ מֵעָרֵ֣י יְהוּדָ֔ה וַיְטַמֵּ֣א אֶת הַבָּמ֗וֹת אֲשֶׁ֤ר קִטְּרוּ שָׁ֨מָּה֙ הַכֹּ֣הֲנִ֔ים מִגֶּ֖בַע עַד בְּאֵ֣ר שָׁ֑בַע וְנָתַ֞ץ אֶת בָּמ֣וֹת הַשְּׁעָרִ֗ים אֲשֶׁר פֶּ֜תַח שַׁ֤עַר יְהוֹשֻׁ֨עַ֙ שַׂר הָעִ֔יר אֲשֶֽׁר עַל שְׂמֹ֥אול אִ֖ישׁ בְּשַׁ֥עַר הָעִֽיר'),
