(10918, 13, 'WLC', 'WLC', 'he', '1CH', 19, 10, 'OT', 'וַיַּ֣רְא יוֹאָ֗ב כִּֽי הָיְתָ֧ה פְנֵי הַמִּלְחָמָ֛ה אֵלָ֖יו פָּנִ֣ים וְאָח֑וֹר וַיִּבְחַ֗ר מִכָּל בָּחוּר֙ בְּיִשְׂרָאֵ֔ל וַֽיַּעֲרֹ֖ךְ לִקְרַ֥את אֲרָֽם'),
(10919, 13, 'WLC', 'WLC', 'he', '1CH', 19, 11, 'OT', 'וְאֵת֙ יֶ֣תֶר הָעָ֔ם נָתַ֕ן בְּיַ֖ד אַבְשַׁ֣י אָחִ֑יו וַיַּ֣עַרְכ֔וּ לִקְרַ֖את בְּנֵ֥י עַמּֽוֹן'),
(10920, 13, 'WLC', 'WLC', 'he', '1CH', 19, 12, 'OT', 'וַיֹּ֗אמֶר אִם תֶּחֱזַ֤ק מִמֶּ֨נִּי֙ אֲרָ֔ם וְהָיִ֥יתָ לִּ֖י לִתְשׁוּעָ֑ה וְאִם בְּנֵ֥י עַמּ֛וֹן יֶֽחֶזְק֥וּ מִמְּךָ֖ וְהוֹשַׁעְתִּֽיךָ'),
(10921, 13, 'WLC', 'WLC', 'he', '1CH', 19, 13, 'OT', 'חֲזַ֤ק וְנִֽתְחַזְּקָה֙ בְּעַד עַמֵּ֔נוּ וּבְעַ֖ד עָרֵ֣י אֱלֹהֵ֑ינוּ וַֽיהוָ֔ה הַטּ֥וֹב בְּעֵינָ֖יו יַעֲשֶֽׂה'),
(10922, 13, 'WLC', 'WLC', 'he', '1CH', 19, 14, 'OT', 'וַיִּגַּ֨שׁ יוֹאָ֜ב וְהָעָ֧ם אֲשֶׁר עִמּ֛וֹ לִפְנֵ֥י אֲרָ֖ם לַמִּלְחָמָ֑ה וַיָּנ֖וּסוּ מִפָּנָֽיו'),
(10923, 13, 'WLC', 'WLC', 'he', '1CH', 19, 15, 'OT', 'וּבְנֵ֨י עַמּ֤וֹן רָאוּ֙ כִּי נָ֣ס אֲרָ֔ם וַיָּנ֣וּסוּ גַם הֵ֗ם מִפְּנֵי֙ אַבְשַׁ֣י אָחִ֔יו וַיָּבֹ֖אוּ הָעִ֑ירָה וַיָּבֹ֥א יוֹאָ֖ב יְרוּשָׁלִָֽם'),
(10924, 13, 'WLC', 'WLC', 'he', '1CH', 19, 16, 'OT', 'וַיַּ֣רְא אֲרָ֗ם כִּ֣י נִגְּפוּ֮ לִפְנֵ֣י יִשְׂרָאֵל֒ וַֽיִּשְׁלְחוּ֙ מַלְאָכִ֔ים וַיּוֹצִ֣יאוּ אֶת אֲרָ֔ם אֲשֶׁ֖ר מֵעֵ֣בֶר הַנָּהָ֑ר וְשׁוֹפַ֛ךְ שַׂר צְבָ֥א הֲדַדְעֶ֖זֶר לִפְנֵיהֶֽם'),
(10925, 13, 'WLC', 'WLC', 'he', '1CH', 19, 17, 'OT', 'וַיֻּגַּ֣ד לְדָוִ֗יד וַיֶּאֱסֹ֤ף אֶת כָּל יִשְׂרָאֵל֙ וַיַּעֲבֹ֣ר הַיַּרְדֵּ֔ן וַיָּבֹ֣א אֲלֵהֶ֔ם וַֽיַּעֲרֹ֖ךְ אֲלֵהֶ֑ם וַיַּעֲרֹ֨ךְ דָּוִ֜יד לִקְרַ֤את אֲרָם֙ מִלְחָמָ֔ה וַיִּֽלָּחֲמ֖וּ עִמּֽוֹ'),
(10926, 13, 'WLC', 'WLC', 'he', '1CH', 19, 18, 'OT', 'וַיָּ֣נָס אֲרָם֮ מִלִּפְנֵ֣י יִשְׂרָאֵל֒ וַיַּהֲרֹ֨ג דָּוִ֜יד מֵאֲרָ֗ם שִׁבְעַ֤ת אֲלָפִים֙ רֶ֔כֶב וְאַרְבָּעִ֥ים אֶ֖לֶף אִ֣ישׁ רַגְלִ֑י וְאֵ֛ת שׁוֹפַ֥ךְ שַֽׂר הַצָּבָ֖א הֵמִֽית'),
(10927, 13, 'WLC', 'WLC', 'he', '1CH', 19, 19, 'OT', 'וַיִּרְא֞וּ עַבְדֵ֣י הֲדַדְעֶ֗זֶר כִּ֤י נִגְּפוּ֙ לִפְנֵ֣י יִשְׂרָאֵ֔ל וַיַּשְׁלִ֥ימוּ עִם דָּוִ֖יד וַיַּֽעַבְדֻ֑הוּ וְלֹא אָבָ֣ה אֲרָ֔ם לְהוֹשִׁ֥יעַ אֶת בְּנֵי עַמּ֖וֹן עֽוֹד'),
