(11298, 14, 'WLC', 'WLC', 'he', '2CH', 6, 15, 'OT', 'אֲשֶׁ֣ר שָׁמַ֗רְתָּ לְעַבְדְּךָ֙ דָּוִ֣יד אָבִ֔י אֵ֥ת אֲשֶׁר דִּבַּ֖רְתָּ ל֑וֹ וַתְּדַבֵּ֥ר בְּפִ֛יךָ וּבְיָדְךָ֥ מִלֵּ֖אתָ כַּיּ֥וֹם הַזֶּֽה'),
(11299, 14, 'WLC', 'WLC', 'he', '2CH', 6, 16, 'OT', 'וְעַתָּ֞ה יְהוָ֣ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל שְׁ֠מֹר לְעַבְדְּךָ֨ דָוִ֤יד אָבִי֙ אֵת֩ אֲשֶׁ֨ר דִּבַּ֤רְתָּ לּוֹ֙ לֵאמֹ֔ר לֹא יִכָּרֵ֨ת לְךָ֥ אִישׁ֙ מִלְּפָנַ֔י יוֹשֵׁ֖ב עַל כִּסֵּ֣א יִשְׂרָאֵ֑ל רַ֠ק אִם יִשְׁמְר֨וּ בָנֶ֜יךָ אֶת דַּרְכָּ֗ם לָלֶ֨כֶת֙ בְּת֣וֹרָתִ֔י כַּאֲשֶׁ֥ר הָלַ֖כְתָּ לְפָנָֽי'),
(11300, 14, 'WLC', 'WLC', 'he', '2CH', 6, 17, 'OT', 'וְעַתָּ֕ה יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל יֵֽאָמֵן֙ דְּבָ֣רְךָ֔ אֲשֶׁ֥ר דִּבַּ֖רְתָּ לְעַבְדְּךָ֥ לְדָוִֽיד'),
(11301, 14, 'WLC', 'WLC', 'he', '2CH', 6, 18, 'OT', 'כִּ֚י הַֽאֻמְנָ֔ם יֵשֵׁ֧ב אֱלֹהִ֛ים אֶת הָאָדָ֖ם עַל הָאָ֑רֶץ הִ֠נֵּה שָׁמַ֜יִם וּשְׁמֵ֤י הַשָּׁמַ֨יִם֙ לֹ֣א יְכַלְכְּל֔וּךָ אַ֕ף כִּֽי הַבַּ֥יִת הַזֶּ֖ה אֲשֶׁ֥ר בָּנִֽיתִי'),
(11302, 14, 'WLC', 'WLC', 'he', '2CH', 6, 19, 'OT', 'וּפָנִ֜יתָ אֶל תְּפִלַּ֧ת עַבְדְּךָ֛ וְאֶל תְּחִנָּת֖וֹ יְהוָ֣ה אֱלֹהָ֑י לִשְׁמֹ֤עַ אֶל הָרִנָּה֙ וְאֶל הַתְּפִלָּ֔ה אֲשֶׁ֥ר עַבְדְּךָ֖ מִתְפַּלֵּ֥ל לְפָנֶֽיךָ'),
(11303, 14, 'WLC', 'WLC', 'he', '2CH', 6, 20, 'OT', 'לִהְיוֹת֩ עֵינֶ֨יךָ פְתֻח֜וֹת אֶל הַבַּ֤יִת הַזֶּה֙ יוֹמָ֣ם וָלַ֔יְלָה אֶל הַ֨מָּק֔וֹם אֲשֶׁ֣ר אָמַ֔רְתָּ לָשׂ֥וּם שִׁמְךָ֖ שָׁ֑ם לִשְׁמ֨וֹעַ֙ אֶל הַתְּפִלָּ֔ה אֲשֶׁ֣ר יִתְפַּלֵּ֣ל עַבְדְּךָ֔ אֶל הַמָּק֖וֹם הַזֶּֽה'),
(11304, 14, 'WLC', 'WLC', 'he', '2CH', 6, 21, 'OT', 'וְשָׁ֨מַעְתָּ֜ אֶל תַּחֲנוּנֵ֤י עַבְדְּךָ֙ וְעַמְּךָ֣ יִשְׂרָאֵ֔ל אֲשֶׁ֥ר יִֽתְפַּֽלְל֖וּ אֶל הַמָּק֣וֹם הַזֶּ֑ה וְ֠אַתָּה תִּשְׁמַ֞ע מִמְּק֤וֹם שִׁבְתְּךָ֙ מִן הַשָּׁמַ֔יִם וְשָׁמַעְתָּ֖ וְסָלָֽחְתָּ'),
(11305, 14, 'WLC', 'WLC', 'he', '2CH', 6, 22, 'OT', 'אִם יֶחֱטָ֥א אִישׁ֙ לְרֵעֵ֔הוּ וְנָֽשָׁא ב֥וֹ אָלָ֖ה לְהַֽאֲלֹת֑וֹ וּבָ֗א אָלָ֛ה לִפְנֵ֥י מִֽזְבַּחֲךָ֖ בַּבַּ֥יִת הַזֶּֽה'),
(11306, 14, 'WLC', 'WLC', 'he', '2CH', 6, 23, 'OT', 'וְאַתָּ֣ה תִּשְׁמַ֣ע מִן הַשָּׁמַ֗יִם וְעָשִׂ֨יתָ֙ וְשָׁפַטְתָּ֣ אֶת עֲבָדֶ֔יךָ לְהָשִׁ֣יב לְרָשָׁ֔ע לָתֵ֥ת דַּרְכּ֖וֹ בְּרֹאשׁ֑וֹ וּלְהַצְדִּ֣יק צַדִּ֔יק לָ֥תֶת ל֖וֹ כְּצִדְקָתֽוֹ'),
(11307, 14, 'WLC', 'WLC', 'he', '2CH', 6, 24, 'OT', 'וְֽאִם יִנָּגֵ֞ף עַמְּךָ֧ יִשְׂרָאֵ֛ל לִפְנֵ֥י אוֹיֵ֖ב כִּ֣י יֶֽחֶטְאוּ לָ֑ךְ וְשָׁ֨בוּ֙ וְהוֹד֣וּ אֶת שְׁמֶ֔ךָ וְהִתְפַּֽלְל֧וּ וְהִֽתְחַנְּנ֛וּ לְפָנֶ֖יךָ בַּבַּ֥יִת הַזֶּֽה'),
(11308, 14, 'WLC', 'WLC', 'he', '2CH', 6, 25, 'OT', 'וְאַתָּה֙ תִּשְׁמַ֣ע מִן הַשָּׁמַ֔יִם וְסָ֣לַחְתָּ֔ לְחַטַּ֖את עַמְּךָ֣ יִשְׂרָאֵ֑ל וַהֲשֵׁיבוֹתָם֙ אֶל הָ֣אֲדָמָ֔ה אֲשֶׁר נָתַ֥תָּה לָהֶ֖ם וְלַאֲבֹתֵיהֶֽם'),
(11309, 14, 'WLC', 'WLC', 'he', '2CH', 6, 26, 'OT', 'בְּהֵעָצֵ֧ר הַשָּׁמַ֛יִם וְלֹֽא יִהְיֶ֥ה מָטָ֖ר כִּ֣י יֶֽחֶטְאוּ לָ֑ךְ וְהִֽתְפַּלְל֞וּ אֶל הַמָּק֤וֹם הַזֶּה֙ וְהוֹד֣וּ אֶת שְׁמֶ֔ךָ מֵחַטָּאתָ֥ם יְשׁוּב֖וּן כִּ֥י תַעֲנֵֽם'),
(11310, 14, 'WLC', 'WLC', 'he', '2CH', 6, 27, 'OT', 'וְאַתָּ֣ה תִּשְׁמַ֣ע הַשָּׁמַ֗יִם וְסָ֨לַחְתָּ֜ לְחַטַּ֤את עֲבָדֶ֨יךָ֙ וְעַמְּךָ֣ יִשְׂרָאֵ֔ל כִּ֥י תוֹרֵ֛ם אֶל הַדֶּ֥רֶךְ הַטּוֹבָ֖ה אֲשֶׁ֣ר יֵֽלְכוּ בָ֑הּ וְנָתַתָּ֤ה מָטָר֙ עַֽל אַרְצְךָ֔ אֲשֶׁר נָתַ֥תָּה לְעַמְּךָ֖ לְנַחֲלָֽה'),
(11311, 14, 'WLC', 'WLC', 'he', '2CH', 6, 28, 'OT', 'רָעָ֞ב כִּֽי יִהְיֶ֣ה בָאָ֗רֶץ דֶּ֣בֶר כִּֽי יִֽ֠הְיֶה שִׁדָּפ֨וֹן וְיֵרָק֜וֹן אַרְבֶּ֤ה וְחָסִיל֙ כִּ֣י יִהְיֶ֔ה כִּ֧י יָֽצַר ל֛וֹ אוֹיְבָ֖יו בְּאֶ֣רֶץ שְׁעָרָ֑יו כָּל נֶ֖גַע וְכָֽל מַחֲלָֽה'),
(11312, 14, 'WLC', 'WLC', 'he', '2CH', 6, 29, 'OT', 'כָּל תְּפִלָּ֣ה כָל תְּחִנָּ֗ה אֲשֶׁ֤ר יִהְיֶה֙ לְכָל הָ֣אָדָ֔ם וּלְכֹ֖ל עַמְּךָ֣ יִשְׂרָאֵ֑ל אֲשֶׁ֣ר יֵדְע֗וּ אִ֤ישׁ נִגְעוֹ֙ וּמַכְאֹב֔וֹ וּפָרַ֥שׂ כַּפָּ֖יו אֶל הַבַּ֥יִת הַזֶּֽה'),
(11313, 14, 'WLC', 'WLC', 'he', '2CH', 6, 30, 'OT', 'וְ֠אַתָּה תִּשְׁמַ֨ע מִן הַשָּׁמַ֜יִם מְכ֤וֹן שִׁבְתֶּ֨ךָ֙ וְסָ֣לַחְתָּ֔ וְנָתַתָּ֤ה לָאִישׁ֙ כְּכָל דְּרָכָ֔יו אֲשֶׁ֥ר תֵּדַ֖ע אֶת לְבָב֑וֹ כִּ֤י אַתָּה֙ לְבַדְּךָ֣ יָדַ֔עְתָּ אֶת לְבַ֖ב בְּנֵ֥י הָאָדָֽם'),
(11314, 14, 'WLC', 'WLC', 'he', '2CH', 6, 31, 'OT', 'לְמַ֣עַן יִֽירָא֗וּךָ לָלֶ֨כֶת֙ בִּדְרָכֶ֔יךָ כָּל הַ֨יָּמִ֔ים אֲשֶׁר הֵ֥ם חַיִּ֖ים עַל פְּנֵ֣י הָאֲדָמָ֑ה אֲשֶׁ֥ר נָתַ֖תָּה לַאֲבֹתֵֽינוּ'),
(11315, 14, 'WLC', 'WLC', 'he', '2CH', 6, 32, 'OT', 'וְגַ֣ם אֶל הַנָּכְרִ֗י אֲ֠שֶׁר לֹ֥א מֵעַמְּךָ֣ יִשְׂרָאֵל֮ הוּא֒ וּבָ֣א מֵאֶ֣רֶץ רְחוֹקָ֗ה לְמַ֨עַן שִׁמְךָ֤ הַגָּדוֹל֙ וְיָדְךָ֣ הַחֲזָקָ֔ה וּֽזְרֽוֹעֲךָ֖ הַנְּטוּיָ֑ה וּבָ֥אוּ וְהִֽתְפַּלְל֖וּ אֶל הַבַּ֥יִת הַזֶּֽה'),
(11316, 14, 'WLC', 'WLC', 'he', '2CH', 6, 33, 'OT', 'וְאַתָּ֞ה תִּשְׁמַ֤ע מִן הַשָּׁמַ֨יִם֙ מִמְּכ֣וֹן שִׁבְתֶּ֔ךָ וְעָשִׂ֕יתָ כְּכֹ֛ל אֲשֶׁר יִקְרָ֥א אֵלֶ֖יךָ הַנָּכְרִ֑י לְמַ֣עַן יֵדְעוּ֩ כָל עַמֵּ֨י הָאָ֜רֶץ אֶת שְׁמֶ֗ךָ וּלְיִרְאָ֤ה אֹֽתְךָ֙ כְּעַמְּךָ֣ יִשְׂרָאֵ֔ל וְלָדַ֕עַת כִּֽי שִׁמְךָ֣ נִקְרָ֔א עַל הַבַּ֥יִת הַזֶּ֖ה אֲשֶׁ֥ר בָּנִֽיתִי'),
(11317, 14, 'WLC', 'WLC', 'he', '2CH', 6, 34, 'OT', 'כִּֽי יֵצֵ֨א עַמְּךָ֤ לַמִּלְחָמָה֙ עַל א֣וֹיְבָ֔יו בַּדֶּ֖רֶךְ אֲשֶׁ֣ר תִּשְׁלָחֵ֑ם וְהִתְפַּֽלְל֣וּ אֵלֶ֗יךָ דֶּ֣רֶךְ הָעִ֤יר הַזֹּאת֙ אֲשֶׁ֣ר בָּחַ֣רְתָּ בָּ֔הּ וְהַבַּ֖יִת אֲשֶׁר בָּנִ֥יתִי לִשְׁמֶֽךָ'),
(11318, 14, 'WLC', 'WLC', 'he', '2CH', 6, 35, 'OT', 'וְשָׁמַעְתָּ֙ מִן הַשָּׁמַ֔יִם אֶת תְּפִלָּתָ֖ם וְאֶת תְּחִנָּתָ֑ם וְעָשִׂ֖יתָ מִשְׁפָּטָֽם'),
(11319, 14, 'WLC', 'WLC', 'he', '2CH', 6, 36, 'OT', 'כִּ֣י יֶחֶטְאוּ לָ֗ךְ כִּ֣י אֵ֤ין אָדָם֙ אֲשֶׁ֣ר לֹא יֶחֱטָ֔א וְאָנַפְתָּ֣ בָ֔ם וּנְתַתָּ֖ם לִפְנֵ֣י אוֹיֵ֑ב וְשָׁב֧וּם שׁוֹבֵיהֶ֛ם אֶל אֶ֥רֶץ רְחוֹקָ֖ה א֥וֹ קְרוֹבָֽה'),
(11320, 14, 'WLC', 'WLC', 'he', '2CH', 6, 37, 'OT', 'וְהֵשִׁ֨יבוּ֙ אֶל לְבָבָ֔ם בָּאָ֖רֶץ אֲשֶׁ֣ר נִשְׁבּוּ שָׁ֑ם וְשָׁ֣בוּ וְהִֽתְחַנְּנ֣וּ אֵלֶ֗יךָ בְּאֶ֤רֶץ שִׁבְיָם֙ לֵאמֹ֔ר חָטָ֥אנוּ הֶעֱוִ֖ינוּ וְרָשָֽׁעְנוּ'),
(11321, 14, 'WLC', 'WLC', 'he', '2CH', 6, 38, 'OT', 'וְשָׁ֣בוּ אֵלֶ֗יךָ בְּכָל לִבָּם֙ וּבְכָל נַפְשָׁ֔ם בְּאֶ֥רֶץ שִׁבְיָ֖ם אֲשֶׁר שָׁב֣וּ אֹתָ֑ם וְהִֽתְפַּֽלְל֗וּ דֶּ֤רֶךְ אַרְצָם֙ אֲשֶׁ֣ר נָתַ֣תָּה לַאֲבוֹתָ֔ם וְהָעִיר֙ אֲשֶׁ֣ר בָּחַ֔רְתָּ וְלַבַּ֖יִת אֲשֶׁר בָּנִ֥יתִי לִשְׁמֶֽךָ'),
(11322, 14, 'WLC', 'WLC', 'he', '2CH', 6, 39, 'OT', 'וְשָׁמַעְתָּ֨ מִן הַשָּׁמַ֜יִם מִמְּכ֣וֹן שִׁבְתְּךָ֗ אֶת תְּפִלָּתָם֙ וְאֶת תְּחִנֹּ֣תֵיהֶ֔ם וְעָשִׂ֖יתָ מִשְׁפָּטָ֑ם וְסָלַחְתָּ֥ לְעַמְּךָ֖ אֲשֶׁ֥ר חָֽטְאוּ לָֽךְ'),
(11323, 14, 'WLC', 'WLC', 'he', '2CH', 6, 40, 'OT', 'עַתָּ֣ה אֱלֹהַ֗י יִֽהְיוּ נָ֤א עֵינֶ֨יךָ֙ פְּתֻח֔וֹת וְאָזְנֶ֖יךָ קַשֻּׁב֑וֹת לִתְפִלַּ֖ת הַמָּק֥וֹם הַזֶּֽה'),
(11324, 14, 'WLC', 'WLC', 'he', '2CH', 6, 41, 'OT', 'וְעַתָּ֗ה קוּמָ֞ה יְהוָ֤ה אֱלֹהִים֙ לְֽנוּחֶ֔ךָ אַתָּ֖ה וַאֲר֣וֹן עֻזֶּ֑ךָ כֹּהֲנֶ֜יךָ יְהוָ֤ה אֱלֹהִים֙ יִלְבְּשׁ֣וּ תְשׁוּעָ֔ה וַחֲסִידֶ֖יךָ יִשְׂמְח֥וּ בַטּֽוֹב'),
(11325, 14, 'WLC', 'WLC', 'he', '2CH', 6, 42, 'OT', 'יְהוָ֣ה אֱלֹהִ֔ים אַל תָּשֵׁ֖ב פְּנֵ֣י מְשִׁיחֶ֑יךָ זָכְרָ֕ה לְחַֽסְדֵ֖י דָּוִ֥יד עַבְדֶּֽךָ'),
(11326, 14, 'WLC', 'WLC', 'he', '2CH', 7, 1, 'OT', 'וּכְכַלּ֤וֹת שְׁלֹמֹה֙ לְהִתְפַּלֵּ֔ל וְהָאֵ֗שׁ יָֽרְדָה֙ מֵֽהַשָּׁמַ֔יִם וַתֹּ֥אכַל הָעֹלָ֖ה וְהַזְּבָחִ֑ים וּכְב֥וֹד יְהוָ֖ה מָלֵ֥א אֶת הַבָּֽיִת'),
(11327, 14, 'WLC', 'WLC', 'he', '2CH', 7, 2, 'OT', 'וְלֹ֤א יָֽכְלוּ֙ הַכֹּ֣הֲנִ֔ים לָב֖וֹא אֶל בֵּ֣ית יְהוָ֑ה כִּֽי מָלֵ֥א כְבוֹד יְהוָ֖ה אֶת בֵּ֥ית יְהוָֽה'),
(11328, 14, 'WLC', 'WLC', 'he', '2CH', 7, 3, 'OT', 'וְכֹ֣ל בְּנֵ֣י יִשְׂרָאֵ֗ל רֹאִים֙ בְּרֶ֣דֶת הָאֵ֔שׁ וּכְב֥וֹד יְהוָ֖ה עַל הַבָּ֑יִת וַיִּכְרְעוּ֩ אַפַּ֨יִם אַ֤רְצָה עַל הָרִֽצְפָה֙ וַיִּֽשְׁתַּֽחֲו֔וּ וְהוֹד֤וֹת לַיהוָה֙ כִּ֣י ט֔וֹב כִּ֥י לְעוֹלָ֖ם חַסְדּֽוֹ'),
(11329, 14, 'WLC', 'WLC', 'he', '2CH', 7, 4, 'OT', 'וְהַמֶּ֖לֶךְ וְכָל הָעָ֑ם זֹבְחִ֥ים זֶ֖בַח לִפְנֵ֥י יְהוָֽה'),
(11330, 14, 'WLC', 'WLC', 'he', '2CH', 7, 5, 'OT', 'וַיִּזְבַּ֞ח הַמֶּ֣לֶךְ שְׁלֹמֹה֮ אֶת זֶ֣בַח הַבָּקָ֗ר עֶשְׂרִ֤ים וּשְׁנַ֨יִם֙ אֶ֔לֶף וְצֹ֕אן מֵאָ֥ה וְעֶשְׂרִ֖ים אָ֑לֶף וַֽיַּחְנְכוּ֙ אֶת בֵּ֣ית הָֽאֱלֹהִ֔ים הַמֶּ֖לֶךְ וְכָל הָעָֽם'),
(11331, 14, 'WLC', 'WLC', 'he', '2CH', 7, 6, 'OT', 'וְהַכֹּהֲנִ֞ים עַל מִשְׁמְרוֹתָ֣ם עֹמְדִ֗ים וְהַלְוִיִּ֞ם בִּכְלֵי שִׁ֤יר יְהוָה֙ אֲשֶׁ֨ר עָשָׂ֜ה דָּוִ֣יד הַמֶּ֗לֶךְ לְהֹד֤וֹת לַיהוָה֙ כִּֽי לְעוֹלָ֣ם חַסְדּ֔וֹ בְּהַלֵּ֥ל דָּוִ֖יד בְּיָדָ֑ם וְהַכֹּהֲנִים֙ מחצצרים נֶגְדָּ֔ם וְכָל יִשְׂרָאֵ֖ל עֹמְדִֽים'),
(11332, 14, 'WLC', 'WLC', 'he', '2CH', 7, 7, 'OT', 'וַיְקַדֵּ֣שׁ שְׁלֹמֹ֗ה אֶת תּ֤וֹךְ הֶֽחָצֵר֙ אֲשֶׁר֙ לִפְנֵ֣י בֵית יְהוָ֔ה כִּֽי עָ֤שָׂה שָׁם֙ הָֽעֹל֔וֹת וְאֵ֖ת חֶלְבֵ֣י הַשְּׁלָמִ֑ים כִּֽי מִזְבַּ֤ח הַנְּחֹ֨שֶׁת֙ אֲשֶׁ֣ר עָשָׂ֣ה שְׁלֹמֹ֔ה לֹ֣א יָכ֗וֹל לְהָכִ֛יל אֶת הָעֹלָ֥ה וְאֶת הַמִּנְחָ֖ה וְאֶת הַחֲלָבִֽים'),
(11333, 14, 'WLC', 'WLC', 'he', '2CH', 7, 8, 'OT', 'וַיַּ֣עַשׂ שְׁלֹמֹ֣ה אֶת הֶ֠חָג בָּעֵ֨ת הַהִ֜יא שִׁבְעַ֤ת יָמִים֙ וְכָל יִשְׂרָאֵ֣ל עִמּ֔וֹ קָהָ֖ל גָּד֣וֹל מְאֹ֑ד מִלְּב֥וֹא חֲמָ֖ת עַד נַ֥חַל מִצְרָֽיִם'),
(11334, 14, 'WLC', 'WLC', 'he', '2CH', 7, 9, 'OT', 'וַֽיַּעֲשׂ֛וּ בַּיּ֥וֹם הַשְּׁמִינִ֖י עֲצָ֑רֶת כִּ֣י חֲנֻכַּ֣ת הַמִּזְבֵּ֗חַ עָשׂוּ֙ שִׁבְעַ֣ת יָמִ֔ים וְהֶחָ֖ג שִׁבְעַ֥ת יָמִֽים'),
(11335, 14, 'WLC', 'WLC', 'he', '2CH', 7, 10, 'OT', 'וּבְי֨וֹם עֶשְׂרִ֤ים וּשְׁלֹשָׁה֙ לַחֹ֣דֶשׁ הַשְּׁבִיעִ֔י שִׁלַּ֥ח אֶת הָעָ֖ם לְאָהֳלֵיהֶ֑ם שְׂמֵחִים֙ וְט֣וֹבֵי לֵ֔ב עַל הַטּוֹבָ֗ה אֲשֶׁ֨ר עָשָׂ֤ה יְהוָה֙ לְדָוִ֣יד וְלִשְׁלֹמֹ֔ה וּלְיִשְׂרָאֵ֖ל עַמּֽוֹ'),
(11336, 14, 'WLC', 'WLC', 'he', '2CH', 7, 11, 'OT', 'וַיְכַ֧ל שְׁלֹמֹ֛ה אֶת בֵּ֥ית יְהוָ֖ה וְאֶת בֵּ֣ית הַמֶּ֑לֶךְ וְאֵ֨ת כָּל הַבָּ֜א עַל לֵ֣ב שְׁלֹמֹ֗ה לַעֲשׂ֧וֹת בְּבֵית יְהוָ֛ה וּבְבֵית֖וֹ הִצְלִֽיחַ'),
(11337, 14, 'WLC', 'WLC', 'he', '2CH', 7, 12, 'OT', 'וַיֵּרָ֧א יְהוָ֛ה אֶל שְׁלֹמֹ֖ה בַּלָּ֑יְלָה וַיֹּ֣אמֶר ל֗וֹ שָׁמַ֨עְתִּי֙ אֶת תְּפִלָּתֶ֔ךָ וּבָחַ֜רְתִּי בַּמָּק֥וֹם הַזֶּ֛ה לִ֖י לְבֵ֥ית זָֽבַח'),
(11338, 14, 'WLC', 'WLC', 'he', '2CH', 7, 13, 'OT', 'הֵ֣ן אֶֽעֱצֹ֤ר הַשָּׁמַ֨יִם֙ וְלֹֽא יִהְיֶ֣ה מָטָ֔ר וְהֵן אֲצַוֶּ֥ה עַל חָגָ֖ב לֶאֱכ֣וֹל הָאָ֑רֶץ וְאִם אֲשַׁלַּ֥ח דֶּ֖בֶר בְּעַמִּֽי'),
(11339, 14, 'WLC', 'WLC', 'he', '2CH', 7, 14, 'OT', 'וְיִכָּנְע֨וּ עַמִּ֜י אֲשֶׁ֧ר נִֽקְרָא שְׁמִ֣י עֲלֵיהֶ֗ם וְיִֽתְפַּֽלְלוּ֙ וִֽיבַקְשׁ֣וּ פָנַ֔י וְיָשֻׁ֖בוּ מִדַּרְכֵיהֶ֣ם הָרָעִ֑ים וַאֲנִי֙ אֶשְׁמַ֣ע מִן הַשָּׁמַ֔יִם וְאֶסְלַח֙ לְחַטָּאתָ֔ם וְאֶרְפָּ֖א אֶת אַרְצָֽם'),
(11340, 14, 'WLC', 'WLC', 'he', '2CH', 7, 15, 'OT', 'עַתָּ֗ה עֵינַי֙ יִהְי֣וּ פְתֻח֔וֹת וְאָזְנַ֖י קַשֻּׁב֑וֹת לִתְפִלַּ֖ת הַמָּק֥וֹם הַזֶּֽה'),
(11341, 14, 'WLC', 'WLC', 'he', '2CH', 7, 16, 'OT', 'וְעַתָּ֗ה בָּחַ֤רְתִּי וְהִקְדַּ֨שְׁתִּי֙ אֶת הַבַּ֣יִת הַזֶּ֔ה לִהְיוֹת שְׁמִ֥י שָׁ֖ם עַד עוֹלָ֑ם וְהָי֨וּ עֵינַ֧י וְלִבִּ֛י שָׁ֖ם כָּל הַיָּמִֽים'),
(11342, 14, 'WLC', 'WLC', 'he', '2CH', 7, 17, 'OT', 'וְאַתָּ֞ה אִם תֵּלֵ֣ךְ לְפָנַ֗י כַּאֲשֶׁ֤ר הָלַךְ֙ דָּוִ֣יד אָבִ֔יךָ וְלַעֲשׂ֕וֹת כְּכֹ֖ל אֲשֶׁ֣ר צִוִּיתִ֑יךָ וְחֻקַּ֥י וּמִשְׁפָּטַ֖י תִּשְׁמֽוֹר'),
(11343, 14, 'WLC', 'WLC', 'he', '2CH', 7, 18, 'OT', 'וַהֲקִ֣ימוֹתִ֔י אֵ֖ת כִּסֵּ֣א מַלְכוּתֶ֑ךָ כַּאֲשֶׁ֣ר כָּרַ֗תִּי לְדָוִ֤יד אָבִ֨יךָ֙ לֵאמֹ֔ר לֹֽא יִכָּרֵ֤ת לְךָ֙ אִ֔ישׁ מוֹשֵׁ֖ל בְּיִשְׂרָאֵֽל'),
(11344, 14, 'WLC', 'WLC', 'he', '2CH', 7, 19, 'OT', 'וְאִם תְּשׁוּב֣וּן אַתֶּ֔ם וַעֲזַבְתֶּם֙ חֻקּוֹתַ֣י וּמִצְוֺתַ֔י אֲשֶׁ֥ר נָתַ֖תִּי לִפְנֵיכֶ֑ם וַהֲלַכְתֶּ֗ם וַעֲבַדְתֶּם֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וְהִשְׁתַּחֲוִיתֶ֖ם לָהֶֽם'),
(11345, 14, 'WLC', 'WLC', 'he', '2CH', 7, 20, 'OT', 'וּנְתַשְׁתִּ֗ים מֵעַ֤ל אַדְמָתִי֙ אֲשֶׁ֣ר נָתַ֣תִּי לָהֶ֔ם וְאֶת הַבַּ֤יִת הַזֶּה֙ אֲשֶׁ֣ר הִקְדַּ֣שְׁתִּי לִשְׁמִ֔י אַשְׁלִ֖יךְ מֵעַ֣ל פָּנָ֑י וְאֶתְּנֶ֛נּוּ לְמָשָׁ֥ל וְלִשְׁנִינָ֖ה בְּכָל הָעַמִּֽים'),
(11346, 14, 'WLC', 'WLC', 'he', '2CH', 7, 21, 'OT', 'וְהַבַּ֤יִת הַזֶּה֙ אֲשֶׁ֣ר הָיָ֣ה עֶלְי֔וֹן לְכָל עֹבֵ֥ר עָלָ֖יו יִשֹּׁ֑ם וְאָמַ֗ר בַּמֶּ֨ה עָשָׂ֤ה יְהוָה֙ כָּ֔כָה לָאָ֥רֶץ הַזֹּ֖את וְלַבַּ֥יִת הַזֶּֽה'),
(11347, 14, 'WLC', 'WLC', 'he', '2CH', 7, 22, 'OT', 'וְאָמְר֗וּ עַל֩ אֲשֶׁ֨ר עָֽזְב֜וּ אֶת יְהוָ֣ה אֱלֹהֵ֣י אֲבֹתֵיהֶ֗ם אֲשֶׁ֣ר הוֹצִיאָם֮ מֵאֶ֣רֶץ מִצְרַיִם֒ וַֽיַּחֲזִ֨יקוּ֙ בֵּאלֹהִ֣ים אֲחֵרִ֔ים וַיִּשְׁתַּחֲו֥וּ לָהֶ֖ם וַיַּֽעַבְד֑וּם עַל כֵּן֙ הֵבִ֣יא עֲלֵיהֶ֔ם אֵ֥ת כָּל הָרָעָ֖ה הַזֹּֽאת'),
(11348, 14, 'WLC', 'WLC', 'he', '2CH', 8, 1, 'OT', 'וַיְהִ֞י מִקֵּ֣ץ עֶשְׂרִ֣ים שָׁנָ֗ה אֲשֶׁ֨ר בָּנָ֧ה שְׁלֹמֹ֛ה אֶת בֵּ֥ית יְהוָ֖ה וְאֶת בֵּיתֽוֹ'),
(11349, 14, 'WLC', 'WLC', 'he', '2CH', 8, 2, 'OT', 'וְהֶעָרִ֗ים אֲשֶׁ֨ר נָתַ֤ן חוּרָם֙ לִשְׁלֹמֹ֔ה בָּנָ֥ה שְׁלֹמֹ֖ה אֹתָ֑ם וַיּ֥וֹשֶׁב שָׁ֖ם אֶת בְּנֵ֥י יִשְׂרָאֵֽל'),
(11350, 14, 'WLC', 'WLC', 'he', '2CH', 8, 3, 'OT', 'וַיֵּ֤לֶךְ שְׁלֹמֹה֙ חֲמָ֣ת צוֹבָ֔ה וַיֶּחֱזַ֖ק עָלֶֽיהָ'),
(11351, 14, 'WLC', 'WLC', 'he', '2CH', 8, 4, 'OT', 'וַיִּ֥בֶן אֶת תַּדְמֹ֖ר בַּמִּדְבָּ֑ר וְאֵת֙ כָּל עָרֵ֣י הַֽמִּסְכְּנ֔וֹת אֲשֶׁ֥ר בָּנָ֖ה בַּחֲמָֽת'),
(11352, 14, 'WLC', 'WLC', 'he', '2CH', 8, 5, 'OT', 'וַיִּ֜בֶן אֶת בֵּ֤ית חוֹרוֹן֙ הָֽעֶלְי֔וֹן וְאֶת בֵּ֥ית חוֹר֖וֹן הַתַּחְתּ֑וֹן עָרֵ֣י מָצ֔וֹר חוֹמ֖וֹת דְּלָתַ֥יִם וּבְרִֽיחַ'),
(11353, 14, 'WLC', 'WLC', 'he', '2CH', 8, 6, 'OT', 'וְאֶֽת בַּעֲלָ֗ת וְאֵ֨ת כָּל עָרֵ֤י הַֽמִּסְכְּנוֹת֙ אֲשֶׁ֣ר הָי֣וּ לִשְׁלֹמֹ֔ה וְאֵת֙ כָּל עָרֵ֣י הָרֶ֔כֶב וְאֵ֖ת עָרֵ֣י הַפָּרָשִׁ֑ים וְאֵ֣ת כָּל חֵ֣שֶׁק שְׁלֹמֹ֗ה אֲשֶׁ֤ר חָשַׁק֙ לִבְנ֤וֹת בִּירֽוּשָׁלִַ֨ם֙ וּבַלְּבָנ֔וֹן וּבְכֹ֖ל אֶ֥רֶץ מֶמְשַׁלְתּֽוֹ'),
(11354, 14, 'WLC', 'WLC', 'he', '2CH', 8, 7, 'OT', 'כָּל הָ֠עָם הַנּוֹתָ֨ר מִן הַחִתִּ֜י וְהָאֱמֹרִ֤י וְהַפְּרִזִּי֙ וְהַחִוִּ֣י וְהַיְבוּסִ֔י אֲשֶׁ֛ר לֹ֥א מִיִּשְׂרָאֵ֖ל הֵֽמָּה'),
(11355, 14, 'WLC', 'WLC', 'he', '2CH', 8, 8, 'OT', 'מִן בְּנֵיהֶ֗ם אֲשֶׁ֨ר נוֹתְר֤וּ אַחֲרֵיהֶם֙ בָּאָ֔רֶץ אֲשֶׁ֥ר לֹֽא כִלּ֖וּם בְּנֵ֣י יִשְׂרָאֵ֑ל וַיַּעֲלֵ֤ם שְׁלֹמֹה֙ לְמַ֔ס עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(11356, 14, 'WLC', 'WLC', 'he', '2CH', 8, 9, 'OT', 'וּמִן בְּנֵי֙ יִשְׂרָאֵ֔ל אֲ֠שֶׁר לֹא נָתַ֧ן שְׁלֹמֹ֛ה לַעֲבָדִ֖ים לִמְלַאכְתּ֑וֹ כִּי הֵ֜מָּה אַנְשֵׁ֤י מִלְחָמָה֙ וְשָׂרֵ֣י שָׁלִישָׁ֔יו וְשָׂרֵ֥י רִכְבּ֖וֹ וּפָרָשָֽׁיו'),
(11357, 14, 'WLC', 'WLC', 'he', '2CH', 8, 10, 'OT', 'וְאֵ֨לֶּה שָׂרֵ֤י הנציבים אֲשֶׁר לַמֶּ֥לֶךְ שְׁלֹמֹ֖ה חֲמִשִּׁ֣ים וּמָאתָ֑יִם הָרֹדִ֖ים בָּעָֽם'),
(11358, 14, 'WLC', 'WLC', 'he', '2CH', 8, 11, 'OT', 'וְאֶת בַּת פַּרְעֹ֗ה הֶעֱלָ֤ה שְׁלֹמֹה֙ מֵעִ֣יר דָּוִ֔יד לַבַּ֖יִת אֲשֶׁ֣ר בָּֽנָה לָ֑הּ כִּ֣י אָמַ֗ר לֹא תֵשֵׁ֨ב אִשָּׁ֥ה לִי֙ בְּבֵית֙ דָּוִ֣יד מֶֽלֶךְ יִשְׂרָאֵ֔ל כִּי קֹ֣דֶשׁ הֵ֔מָּה אֲשֶׁר בָּֽאָ֥ה אֲלֵיהֶ֖ם אֲר֥וֹן יְהוָֽה'),
(11359, 14, 'WLC', 'WLC', 'he', '2CH', 8, 12, 'OT', 'אָ֣ז הֶעֱלָ֧ה שְׁלֹמֹ֛ה עֹל֖וֹת לַיהוָ֑ה עַ֚ל מִזְבַּ֣ח יְהוָ֔ה אֲשֶׁ֥ר בָּנָ֖ה לִפְנֵ֥י הָאוּלָֽם'),
(11360, 14, 'WLC', 'WLC', 'he', '2CH', 8, 13, 'OT', 'וּבִדְבַר י֣וֹם בְּי֗וֹם לְהַעֲלוֹת֙ כְּמִצְוַ֣ת מֹשֶׁ֔ה לַשַּׁבָּתוֹת֙ וְלֶ֣חֳדָשִׁ֔ים וְלַמּ֣וֹעֲד֔וֹת שָׁל֥וֹשׁ פְּעָמִ֖ים בַּשָּׁנָ֑ה בְּחַ֧ג הַמַּצּ֛וֹת וּבְחַ֥ג הַשָּׁבֻע֖וֹת וּבְחַ֥ג הַסֻּכּֽוֹת'),
(11361, 14, 'WLC', 'WLC', 'he', '2CH', 8, 14, 'OT', 'וַיַּעֲמֵ֣ד כְּמִשְׁפַּ֣ט דָּֽוִיד אָ֠בִיו אֶת מַחְלְק֨וֹת הַכֹּהֲנִ֜ים עַל עֲבֹדָתָ֗ם וְהַלְוִיִּ֣ם עַל מִ֠שְׁמְרוֹתָם לְהַלֵּ֨ל וּלְשָׁרֵ֜ת נֶ֤גֶד הַכֹּֽהֲנִים֙ לִדְבַר י֣וֹם בְּיוֹמ֔וֹ וְהַשּׁוֹעֲרִ֥ים בְּמַחְלְקוֹתָ֖ם לְשַׁ֣עַר וָשָׁ֑עַר כִּ֣י כֵ֔ן מִצְוַ֖ת דָּוִ֥יד אִישׁ הָאֱלֹהִֽים'),
(11362, 14, 'WLC', 'WLC', 'he', '2CH', 8, 15, 'OT', 'וְלֹ֣א סָרוּ֩ מִצְוַ֨ת הַמֶּ֜לֶךְ עַל הַכֹּהֲנִ֧ים וְהַלְוִיִּ֛ם לְכָל דָּבָ֖ר וְלָאֹצָרֽוֹת'),
(11363, 14, 'WLC', 'WLC', 'he', '2CH', 8, 16, 'OT', 'וַתִּכֹּן֙ כָּל מְלֶ֣אכֶת שְׁלֹמֹ֔ה עַד הַיּ֛וֹם מוּסַ֥ד בֵּית יְהוָ֖ה וְעַד כְּלֹת֑וֹ שָׁלֵ֖ם בֵּ֥ית יְהוָֽה'),
(11364, 14, 'WLC', 'WLC', 'he', '2CH', 8, 17, 'OT', 'אָז֩ הָלַ֨ךְ שְׁלֹמֹ֜ה לְעֶצְיֽוֹן גֶּ֧בֶר וְאֶל אֵיל֛וֹת עַל שְׂפַ֥ת הַיָּ֖ם בְּאֶ֥רֶץ אֱדֽוֹם'),
(11365, 14, 'WLC', 'WLC', 'he', '2CH', 8, 18, 'OT', 'וַיִּֽשְׁלַֽח לוֹ֩ חוּרָ֨ם בְּיַד עֲבָדָ֜יו אוניות וַעֲבָדִים֮ י֣וֹדְעֵי יָם֒ וַיָּבֹ֜אוּ עִם עַבְדֵ֤י שְׁלֹמֹה֙ אוֹפִ֔ירָה וַיִּקְח֣וּ מִשָּׁ֔ם אַרְבַּע מֵא֥וֹת וַחֲמִשִּׁ֖ים כִּכַּ֣ר זָהָ֑ב וַיָּבִ֖יאוּ אֶל הַמֶּ֥לֶךְ שְׁלֹמֹֽה'),
(11366, 14, 'WLC', 'WLC', 'he', '2CH', 9, 1, 'OT', 'וּמַֽלְכַּת שְׁבָ֗א שָֽׁמְעָה֮ אֶת שֵׁ֣מַע שְׁלֹמֹה֒ וַתָּב֣וֹא לְנַסּוֹת֩ אֶת שְׁלֹמֹ֨ה בְחִיד֜וֹת בִּירֽוּשָׁלִַ֗ם בְּחַ֣יִל כָּבֵ֣ד מְאֹ֡ד וּ֠גְמַלִּים נֹשְׂאִ֨ים בְּשָׂמִ֧ים וְזָהָ֛ב לָרֹ֖ב וְאֶ֣בֶן יְקָרָ֑ה וַתָּבוֹא֙ אֶל שְׁלֹמֹ֔ה וַתְּדַבֵּ֣ר עִמּ֔וֹ אֵ֛ת כָּל אֲשֶׁ֥ר הָיָ֖ה עִם לְבָבָֽהּ'),
(11367, 14, 'WLC', 'WLC', 'he', '2CH', 9, 2, 'OT', 'וַיַּגֶּד לָ֥הּ שְׁלֹמֹ֖ה אֶת כָּל דְּבָרֶ֑יהָ וְלֹֽא נֶעְלַ֤ם דָּבָר֙ מִשְּׁלֹמֹ֔ה אֲשֶׁ֧ר לֹ֦א הִגִּ֖יד לָֽהּ'),
(11368, 14, 'WLC', 'WLC', 'he', '2CH', 9, 3, 'OT', 'וַתֵּ֨רֶא֙ מַֽלְכַּת שְׁבָ֔א אֵ֖ת חָכְמַ֣ת שְׁלֹמֹ֑ה וְהַבַּ֖יִת אֲשֶׁ֥ר בָּנָֽה'),
(11369, 14, 'WLC', 'WLC', 'he', '2CH', 9, 4, 'OT', 'וּמַאֲכַ֣ל שֻׁלְחָנ֡וֹ וּמוֹשַׁ֣ב עֲבָדָיו֩ וּמַעֲמַ֨ד מְשָׁרְתָ֜יו וּמַלְבּֽוּשֵׁיהֶ֗ם וּמַשְׁקָיו֙ וּמַלְבּ֣וּשֵׁיהֶ֔ם וַעֲלִיָּת֔וֹ אֲשֶׁ֥ר יַעֲלֶ֖ה בֵּ֣ית יְהוָ֑ה וְלֹא הָ֥יָה ע֛וֹד בָּ֖הּ רֽוּחַ'),
(11370, 14, 'WLC', 'WLC', 'he', '2CH', 9, 5, 'OT', 'וַתֹּ֨אמֶר֙ אֶל הַמֶּ֔לֶךְ אֱמֶת֙ הַדָּבָ֔ר אֲשֶׁ֥ר שָׁמַ֖עְתִּי בְּאַרְצִ֑י עַל דְּבָרֶ֖יךָ וְעַל חָכְמָתֶֽךָ'),
(11371, 14, 'WLC', 'WLC', 'he', '2CH', 9, 6, 'OT', 'וְלֹֽא הֶאֱמַ֣נְתִּי לְדִבְרֵיהֶ֗ם עַ֤ד אֲשֶׁר בָּ֨אתִי֙ וַתִּרְאֶ֣ינָה עֵינַ֔י וְהִנֵּה֙ לֹ֣א הֻגַּד לִ֔י חֲצִ֖י מַרְבִּ֣ית חָכְמָתֶ֑ךָ יָסַ֕פְתָּ עַל הַשְּׁמוּעָ֖ה אֲשֶׁ֥ר שָׁמָֽעְתִּי'),
(11372, 14, 'WLC', 'WLC', 'he', '2CH', 9, 7, 'OT', 'אַשְׁרֵ֣י אֲנָשֶׁ֔יךָ וְאַשְׁרֵ֖י עֲבָדֶ֣יךָ אֵ֑לֶּה הָעֹמְדִ֤ים לְפָנֶ֨יךָ֙ תָּמִ֔יד וְשֹׁמְעִ֖ים אֶת חָכְמָתֶֽךָ'),
(11373, 14, 'WLC', 'WLC', 'he', '2CH', 9, 8, 'OT', 'יְהִ֨י יְהוָ֤ה אֱלֹהֶ֨יךָ֙ בָּר֔וּךְ אֲשֶׁ֣ר חָפֵ֣ץ בְּךָ֗ לְתִתְּךָ֤ עַל כִּסְאוֹ֙ לְמֶ֔לֶךְ לַיהוָ֖ה אֱלֹהֶ֑יךָ בְּאַהֲבַ֨ת אֱלֹהֶ֤יךָ אֶת יִשְׂרָאֵל֙ לְהַעֲמִיד֣וֹ לְעוֹלָ֔ם וַיִּתֶּנְךָ֤ עֲלֵיהֶם֙ לְמֶ֔לֶךְ לַעֲשׂ֖וֹת מִשְׁפָּ֥ט וּצְדָקָֽה'),
(11374, 14, 'WLC', 'WLC', 'he', '2CH', 9, 9, 'OT', 'וַתִּתֵּ֨ן לַמֶּ֜לֶךְ מֵאָ֥ה וְעֶשְׂרִ֣ים כִּכַּ֣ר זָהָ֗ב וּבְשָׂמִ֛ים לָרֹ֥ב מְאֹ֖ד וְאֶ֣בֶן יְקָרָ֑ה וְלֹ֤א הָיָה֙ כַּבֹּ֣שֶׂם הַה֔וּא אֲשֶׁר נָתְנָ֥ה מַֽלְכַּת שְׁבָ֖א לַמֶּ֥לֶךְ שְׁלֹמֹֽה'),
(11375, 14, 'WLC', 'WLC', 'he', '2CH', 9, 10, 'OT', 'וְגַם עַבְדֵ֤י חירם וְעַבְדֵ֣י שְׁלֹמֹ֔ה אֲשֶׁר הֵבִ֥יאוּ זָהָ֖ב מֵאוֹפִ֑יר הֵבִ֛יאוּ עֲצֵ֥י אַלְגּוּמִּ֖ים וְאֶ֥בֶן יְקָרָֽה'),
(11376, 14, 'WLC', 'WLC', 'he', '2CH', 9, 11, 'OT', 'וַיַּ֣עַשׂ הַ֠מֶּלֶךְ אֶת עֲצֵ֨י הָֽאַלְגּוּמִּ֜ים מְסִלּ֤וֹת לְבֵית יְהוָה֙ וּלְבֵ֣ית הַמֶּ֔לֶךְ וְכִנֹּר֥וֹת וּנְבָלִ֖ים לַשָּׁרִ֑ים וְלֹא נִרְא֥וּ כָהֵ֛ם לְפָנִ֖ים בְּאֶ֥רֶץ יְהוּדָֽה'),
(11377, 14, 'WLC', 'WLC', 'he', '2CH', 9, 12, 'OT', 'וְהַמֶּ֨לֶךְ שְׁלֹמֹ֜ה נָתַ֣ן לְמַֽלְכַּת שְׁבָ֗א אֶת כָּל חֶפְצָהּ֙ אֲשֶׁ֣ר שָׁאָ֔לָה מִלְּבַ֖ד אֲשֶׁר הֵבִ֣יאָה אֶל הַמֶּ֑לֶךְ וַֽתַּהֲפֹ֛ךְ וַתֵּ֥לֶךְ לְאַרְצָ֖הּ הִ֥יא וַעֲבָדֶֽיהָ'),
(11378, 14, 'WLC', 'WLC', 'he', '2CH', 9, 13, 'OT', 'וַיְהִי֙ מִשְׁקַ֣ל הַזָּהָ֔ב אֲשֶׁר בָּ֥א לִשְׁלֹמֹ֖ה בְּשָׁנָ֣ה אֶחָ֑ת שֵׁ֥שׁ מֵא֛וֹת וְשִׁשִּׁ֥ים וָשֵׁ֖שׁ כִּכְּרֵ֥י זָהָֽב'),
(11379, 14, 'WLC', 'WLC', 'he', '2CH', 9, 14, 'OT', 'לְבַ֞ד מֵאַנְשֵׁ֧י הַתָּרִ֛ים וְהַסֹּחֲרִ֖ים מְבִיאִ֑ים וְכָל מַלְכֵ֤י עֲרַב֙ וּפַח֣וֹת הָאָ֔רֶץ מְבִיאִ֛ים זָהָ֥ב וָכֶ֖סֶף לִשְׁלֹמֹֽה'),
(11380, 14, 'WLC', 'WLC', 'he', '2CH', 9, 15, 'OT', 'וַיַּ֨עַשׂ הַמֶּ֧לֶךְ שְׁלֹמֹ֛ה מָאתַ֥יִם צִנָּ֖ה זָהָ֣ב שָׁח֑וּט שֵׁ֤שׁ מֵאוֹת֙ זָהָ֣ב שָׁח֔וּט יַעֲלֶ֖ה עַל הַצִּנָּ֥ה הָאֶחָֽת'),
(11381, 14, 'WLC', 'WLC', 'he', '2CH', 9, 16, 'OT', 'וּשְׁלֹשׁ מֵא֤וֹת מָֽגִנִּים֙ זָהָ֣ב שָׁח֔וּט שְׁלֹ֤שׁ מֵאוֹת֙ זָהָ֔ב יַעֲלֶ֖ה עַל הַמָּגֵ֣ן הָאֶחָ֑ת וַיִּתְּנֵ֣ם הַמֶּ֔לֶךְ בְּבֵ֖ית יַ֥עַר הַלְּבָנֽוֹן'),
(11382, 14, 'WLC', 'WLC', 'he', '2CH', 9, 17, 'OT', 'וַיַּ֧עַשׂ הַמֶּ֛לֶךְ כִּסֵּא שֵׁ֖ן גָּד֑וֹל וַיְצַפֵּ֖הוּ זָהָ֥ב טָהֽוֹר'),
(11383, 14, 'WLC', 'WLC', 'he', '2CH', 9, 18, 'OT', 'וְשֵׁ֣שׁ מַעֲל֣וֹת לַ֠כִּסֵּא וְכֶ֨בֶשׁ בַּזָּהָ֤ב לַכִּסֵּא֙ מָאֳחָזִ֔ים וְיָד֛וֹת מִזֶּ֥ה וּמִזֶּ֖ה עַל מְק֣וֹם הַשָּׁ֑בֶת וּשְׁנַ֣יִם אֲרָי֔וֹת עֹמְדִ֖ים אֵ֥צֶל הַיָּדֽוֹת'),
(11384, 14, 'WLC', 'WLC', 'he', '2CH', 9, 19, 'OT', 'וּשְׁנֵ֧ים עָשָׂ֣ר אֲרָי֗וֹת עֹמְדִ֥ים שָׁ֛ם עַל שֵׁ֥שׁ הַֽמַּעֲל֖וֹת מִזֶּ֣ה וּמִזֶּ֑ה לֹא נַעֲשָׂ֥ה כֵ֖ן לְכָל מַמְלָכָֽה'),
(11385, 14, 'WLC', 'WLC', 'he', '2CH', 9, 20, 'OT', 'וְ֠כֹל כְּלֵ֞י מַשְׁקֵ֨ה הַמֶּ֤לֶךְ שְׁלֹמֹה֙ זָהָ֔ב וְכֹ֗ל כְּלֵ֛י בֵּֽית יַ֥עַר הַלְּבָנ֖וֹן זָהָ֣ב סָג֑וּר אֵ֣ין כֶּ֗סֶף נֶחְשָׁ֛ב בִּימֵ֥י שְׁלֹמֹ֖ה לִמְאֽוּמָה'),
(11386, 14, 'WLC', 'WLC', 'he', '2CH', 9, 21, 'OT', 'כִּֽי אֳנִיּ֤וֹת לַמֶּ֨לֶךְ֙ הֹלְכ֣וֹת תַּרְשִׁ֔ישׁ עִ֖ם עַבְדֵ֣י חוּרָ֑ם אַחַת֩ לְשָׁל֨וֹשׁ שָׁנִ֜ים תָּב֣וֹאנָה אֳנִיּ֣וֹת תַּרְשִׁ֗ישׁ נֹֽשְׂאוֹת֙ זָהָ֣ב וָכֶ֔סֶף שֶׁנְהַבִּ֥ים וְקוֹפִ֖ים וְתוּכִּיִּֽים'),
