(11572, 14, 'WLC', 'WLC', 'he', '2CH', 18, 29, 'OT', 'וַיֹּאמֶר֩ מֶ֨לֶךְ יִשְׂרָאֵ֜ל אֶל יְהוֹשָׁפָ֗ט הִתְחַפֵּשׂ֙ וָב֣וֹא בַמִּלְחָמָ֔ה וְאַתָּ֖ה לְבַ֣שׁ בְּגָדֶ֑יךָ וַיִּתְחַפֵּשׂ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַיָּבֹ֖אוּ בַּמִּלְחָמָֽה'),
(11573, 14, 'WLC', 'WLC', 'he', '2CH', 18, 30, 'OT', 'וּמֶ֣לֶךְ אֲרָ֡ם צִוָּה֩ אֶת שָׂרֵ֨י הָרֶ֤כֶב אֲשֶׁר לוֹ֙ לֵאמֹ֔ר לֹ֚א תִּלָּ֣חֲמ֔וּ אֶת הַקָּטֹ֖ן אֶת הַגָּד֑וֹל כִּ֛י אִֽם אֶת מֶ֥לֶךְ יִשְׂרָאֵ֖ל לְבַדּֽוֹ'),
(11574, 14, 'WLC', 'WLC', 'he', '2CH', 18, 31, 'OT', 'וַיְהִ֡י כִּרְאוֹת֩ שָׂרֵ֨י הָרֶ֜כֶב אֶת יְהוֹשָׁפָ֗ט וְהֵ֤מָּה אָֽמְרוּ֙ מֶ֣לֶךְ יִשְׂרָאֵ֣ל ה֔וּא וַיָּסֹ֥בּוּ עָלָ֖יו לְהִלָּחֵ֑ם וַיִּזְעַ֤ק יְהֽוֹשָׁפָט֙ וַֽיהוָ֣ה עֲזָר֔וֹ וַיְסִיתֵ֥ם אֱלֹהִ֖ים מִמֶּֽנּוּ'),
(11575, 14, 'WLC', 'WLC', 'he', '2CH', 18, 32, 'OT', 'וַיְהִ֗י כִּרְאוֹת֙ שָׂרֵ֣י הָרֶ֔כֶב כִּ֥י לֹא הָיָ֖ה מֶ֣לֶךְ יִשְׂרָאֵ֑ל וַיָּשֻׁ֖בוּ מֵאַחֲרָֽיו'),
(11576, 14, 'WLC', 'WLC', 'he', '2CH', 18, 33, 'OT', 'וְאִ֗ישׁ מָשַׁ֤ךְ בַּקֶּ֨שֶׁת֙ לְתֻמּ֔וֹ וַיַּךְ֙ אֶת מֶ֣לֶךְ יִשְׂרָאֵ֔ל בֵּ֥ין הַדְּבָקִ֖ים וּבֵ֣ין הַשִּׁרְיָ֑ן וַיֹּ֣אמֶר לָֽרַכָּ֗ב הֲפֹ֧ךְ ידיך וְהוֹצֵאתַ֥נִי מִן הַֽמַּחֲנֶ֖ה כִּ֥י הָחֳלֵֽיתִי'),
(11577, 14, 'WLC', 'WLC', 'he', '2CH', 18, 34, 'OT', 'וַתַּ֤עַל הַמִּלְחָמָה֙ בַּיּ֣וֹם הַה֔וּא וּמֶ֣לֶךְ יִשְׂרָאֵ֗ל הָיָ֨ה מַעֲמִ֧יד בַּמֶּרְכָּבָ֛ה נֹ֥כַח אֲרָ֖ם עַד הָעָ֑רֶב וַיָּ֕מָת לְעֵ֖ת בּ֥וֹא הַשָּֽׁמֶשׁ'),
(11578, 14, 'WLC', 'WLC', 'he', '2CH', 19, 1, 'OT', 'וַ֠יָּשָׁב יְהוֹשָׁפָ֨ט מֶֽלֶךְ יְהוּדָ֧ה אֶל בֵּית֛וֹ בְּשָׁל֖וֹם לִֽירוּשָׁלִָֽם'),
(11579, 14, 'WLC', 'WLC', 'he', '2CH', 19, 2, 'OT', 'וַיֵּצֵ֣א אֶל פָּנָ֗יו יֵה֣וּא בֶן חֲנָ֘נִי֮ הַחֹזֶה֒ וַיֹּ֨אמֶר֙ אֶל הַמֶּ֣לֶךְ יְהוֹשָׁפָ֔ט הֲלָרָשָׁ֣ע לַעְזֹ֔ר וּלְשֹׂנְאֵ֥י יְהוָ֖ה תֶּאֱהָ֑ב וּבָזֹאת֙ עָלֶ֣יךָ קֶּ֔צֶף מִלִּפְנֵ֖י יְהוָֽה'),
(11580, 14, 'WLC', 'WLC', 'he', '2CH', 19, 3, 'OT', 'אֲבָ֕ל דְּבָרִ֥ים טוֹבִ֖ים נִמְצְא֣וּ עִמָּ֑ךְ כִּֽי בִעַ֤רְתָּ הָאֲשֵׁרוֹת֙ מִן הָאָ֔רֶץ וַהֲכִינ֥וֹתָ לְבָבְךָ֖ לִדְרֹ֥שׁ הָֽאֱלֹהִֽים'),
(11581, 14, 'WLC', 'WLC', 'he', '2CH', 19, 4, 'OT', 'וַיֵּ֥שֶׁב יְהוֹשָׁפָ֖ט בִּירוּשָׁלִָ֑ם וַיָּ֜שָׁב וַיֵּצֵ֣א בָעָ֗ם מִבְּאֵ֥ר שֶׁ֨בַע֙ עַד הַ֣ר אֶפְרַ֔יִם וַיְשִׁיבֵ֕ם אֶל יְהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵיהֶֽם'),
(11582, 14, 'WLC', 'WLC', 'he', '2CH', 19, 5, 'OT', 'וַיַּעֲמֵ֨ד שֹֽׁפְטִ֜ים בָּאָ֗רֶץ בְּכָל עָרֵ֧י יְהוּדָ֛ה הַבְּצֻר֖וֹת לְעִ֥יר וָעִֽיר'),
(11583, 14, 'WLC', 'WLC', 'he', '2CH', 19, 6, 'OT', 'וַיֹּ֣אמֶר אֶל הַשֹּֽׁפְטִ֗ים רְאוּ֙ מָֽה אַתֶּ֣ם עֹשִׂ֔ים כִּ֣י לֹ֧א לְאָדָ֛ם תִּשְׁפְּט֖וּ כִּ֣י לַיהוָ֑ה וְעִמָּכֶ֖ם בִּדְבַ֥ר מִשְׁפָּֽט'),
(11584, 14, 'WLC', 'WLC', 'he', '2CH', 19, 7, 'OT', 'וְעַתָּ֕ה יְהִ֥י פַֽחַד יְהוָ֖ה עֲלֵיכֶ֑ם שִׁמְר֣וּ וַעֲשׂ֔וּ כִּֽי אֵ֞ין עִם יְהוָ֣ה אֱלֹהֵ֗ינוּ עַוְלָ֛ה וּמַשֹּׂ֥א פָנִ֖ים וּמִקַּח שֹֽׁחַד'),
(11585, 14, 'WLC', 'WLC', 'he', '2CH', 19, 8, 'OT', 'וְגַ֣ם בִּ֠ירוּשָׁלִַם הֶעֱמִ֨יד יְהוֹשָׁפָ֜ט מִן הַלְוִיִּ֣ם וְהַכֹּהֲנִ֗ים וּמֵרָאשֵׁ֤י הָאָבוֹת֙ לְיִשְׂרָאֵ֔ל לְמִשְׁפַּ֥ט יְהוָ֖ה וְלָרִ֑יב וַיָּשֻׁ֖בוּ יְרוּשָׁלִָֽם'),
(11586, 14, 'WLC', 'WLC', 'he', '2CH', 19, 9, 'OT', 'וַיְצַ֥ו עֲלֵיהֶ֖ם לֵאמֹ֑ר כֹּ֤ה תַעֲשׂוּן֙ בְּיִרְאַ֣ת יְהוָ֔ה בֶּאֱמוּנָ֖ה וּבְלֵבָ֥ב שָׁלֵֽם'),
(11587, 14, 'WLC', 'WLC', 'he', '2CH', 19, 10, 'OT', 'וְכָל רִיב֩ אֲשֶׁר יָב֨וֹא עֲלֵיכֶ֜ם מֵאֲחֵיכֶ֣ם הַיֹּשְׁבִ֣ים בְּעָרֵיהֶ֗ם בֵּֽין דָּ֣ם לְדָם֮ בֵּין תּוֹרָ֣ה לְמִצְוָה֮ לְחֻקִּ֣ים וּלְמִשְׁפָּטִים֒ וְהִזְהַרְתֶּ֣ם אֹתָ֔ם וְלֹ֤א יֶאְשְׁמוּ֙ לַיהוָ֔ה וְהָֽיָה קֶ֥צֶף עֲלֵיכֶ֖ם וְעַל אֲחֵיכֶ֑ם כֹּ֥ה תַעֲשׂ֖וּן וְלֹ֥א תֶאְשָֽׁמוּ'),
(11588, 14, 'WLC', 'WLC', 'he', '2CH', 19, 11, 'OT', 'וְהִנֵּ֡ה אֲמַרְיָ֣הוּ כֹהֵן֩ הָרֹ֨אשׁ עֲלֵיכֶ֜ם לְכֹ֣ל דְּבַר יְהוָ֗ה וּזְבַדְיָ֨הוּ בֶן יִשְׁמָעֵ֜אל הַנָּגִ֤יד לְבֵית יְהוּדָה֙ לְכֹ֣ל דְּבַר הַמֶּ֔לֶךְ וְשֹׁטְרִ֥ים הַלְוִיִּ֖ם לִפְנֵיכֶ֑ם חִזְק֣וּ וַעֲשׂ֔וּ וִיהִ֥י יְהוָ֖ה עִם הַטּֽוֹב'),
(11589, 14, 'WLC', 'WLC', 'he', '2CH', 20, 1, 'OT', 'וַיְהִ֣י אַֽחֲרֵי כֵ֡ן בָּ֣אוּ בְנֵי מוֹאָב֩ וּבְנֵ֨י עַמּ֜וֹן וְעִמָּהֶ֧ם מֵֽהָעַמּוֹנִ֛ים עַל יְהוֹשָׁפָ֖ט לַמִּלְחָמָֽה'),
(11590, 14, 'WLC', 'WLC', 'he', '2CH', 20, 2, 'OT', 'וַיָּבֹ֗אוּ וַיַּגִּ֤ידוּ לִֽיהוֹשָׁפָט֙ לֵאמֹ֔ר בָּ֣א עָלֶ֜יךָ הָמ֥וֹן רָ֛ב מֵעֵ֥בֶר לַיָּ֖ם מֵאֲרָ֑ם וְהִנָּם֙ בְּחַֽצְצ֣וֹן תָּמָ֔ר הִ֖יא עֵ֥ין גֶּֽדִי'),
(11591, 14, 'WLC', 'WLC', 'he', '2CH', 20, 3, 'OT', 'וַיִּרָ֕א וַיִּתֵּ֧ן יְהוֹשָׁפָ֛ט אֶת פָּנָ֖יו לִדְר֣וֹשׁ לַיהוָ֑ה וַיִּקְרָא צ֖וֹם עַל כָּל יְהוּדָֽה'),
(11592, 14, 'WLC', 'WLC', 'he', '2CH', 20, 4, 'OT', 'וַיִּקָּבְצ֣וּ יְהוּדָ֔ה לְבַקֵּ֖שׁ מֵֽיְהוָ֑ה גַּ֚ם מִכָּל עָרֵ֣י יְהוּדָ֔ה בָּ֖אוּ לְבַקֵּ֥שׁ אֶת יְהוָֽה'),
(11593, 14, 'WLC', 'WLC', 'he', '2CH', 20, 5, 'OT', 'וַיַּעֲמֹ֣ד יְהוֹשָׁפָ֗ט בִּקְהַ֧ל יְהוּדָ֛ה וִירוּשָׁלִַ֖ם בְּבֵ֣ית יְהוָ֑ה לִפְנֵ֖י הֶחָצֵ֥ר הַחֲדָשָֽׁה'),
(11594, 14, 'WLC', 'WLC', 'he', '2CH', 20, 6, 'OT', 'וַיֹּאמַ֗ר יְהוָ֞ה אֱלֹהֵ֤י אֲבֹתֵ֨ינוּ֙ הֲלֹ֨א אַתָּֽה ה֤וּא אֱלֹהִים֙ בַּשָּׁמַ֔יִם וְאַתָּ֣ה מוֹשֵׁ֔ל בְּכֹ֖ל מַמְלְכ֣וֹת הַגּוֹיִ֑ם וּבְיָדְךָ֙ כֹּ֣חַ וּגְבוּרָ֔ה וְאֵ֥ין עִמְּךָ֖ לְהִתְיַצֵּֽב'),
(11595, 14, 'WLC', 'WLC', 'he', '2CH', 20, 7, 'OT', 'הֲלֹ֣א אַתָּ֣ה אֱלֹהֵ֗ינוּ הוֹרַ֨שְׁתָּ֙ אֶת יֹשְׁבֵי֙ הָאָ֣רֶץ הַזֹּ֔את מִלִּפְנֵ֖י עַמְּךָ֣ יִשְׂרָאֵ֑ל וַֽתִּתְּנָ֗הּ לְזֶ֛רַע אַבְרָהָ֥ם אֹֽהַבְךָ֖ לְעוֹלָֽם'),
(11596, 14, 'WLC', 'WLC', 'he', '2CH', 20, 8, 'OT', 'וַיֵּשְׁב֖וּ בָ֑הּ וַיִּבְנ֨וּ לְךָ֧ בָּ֛הּ מִקְדָּ֖שׁ לְשִׁמְךָ֥ לֵאמֹֽר'),
(11597, 14, 'WLC', 'WLC', 'he', '2CH', 20, 9, 'OT', 'אִם תָּב֨וֹא עָלֵ֜ינוּ רָעָ֗ה חֶרֶב֮ שְׁפוֹט֮ וְדֶ֣בֶר וְרָעָב֒ נַֽעַמְדָ֞ה לִפְנֵ֨י הַבַּ֤יִת הַזֶּה֙ וּלְפָנֶ֔יךָ כִּ֥י שִׁמְךָ֖ בַּבַּ֣יִת הַזֶּ֑ה וְנִזְעַ֥ק אֵלֶ֛יךָ מִצָּרָתֵ֖נוּ וְתִשְׁמַ֥ע וְתוֹשִֽׁיעַ'),
(11598, 14, 'WLC', 'WLC', 'he', '2CH', 20, 10, 'OT', 'וְעַתָּ֡ה הִנֵּה֩ בְנֵֽי עַמּ֨וֹן וּמוֹאָ֜ב וְהַר שֵׂעִ֗יר אֲ֠שֶׁר לֹֽא נָתַ֤תָּה לְיִשְׂרָאֵל֙ לָב֣וֹא בָהֶ֔ם בְּבֹאָ֖ם מֵאֶ֣רֶץ מִצְרָ֑יִם כִּ֛י סָ֥רוּ מֵעֲלֵיהֶ֖ם וְלֹ֥א הִשְׁמִידֽוּם'),
(11599, 14, 'WLC', 'WLC', 'he', '2CH', 20, 11, 'OT', 'וְהִ֨נֵּה הֵ֔ם גֹּמְלִ֖ים עָלֵ֑ינוּ לָבוֹא֙ לְגָ֣רְשֵׁ֔נוּ מִיְּרֻשָּׁתְךָ֖ אֲשֶׁ֥ר הֽוֹרַשְׁתָּֽנוּ'),
(11600, 14, 'WLC', 'WLC', 'he', '2CH', 20, 12, 'OT', 'אֱלֹהֵ֨ינוּ֙ הֲלֹ֣א תִשְׁפָּט בָּ֔ם כִּ֣י אֵ֥ין בָּ֨נוּ֙ כֹּ֔חַ לִ֠פְנֵי הֶהָמ֥וֹן הָרָ֛ב הַזֶּ֖ה הַבָּ֣א עָלֵ֑ינוּ וַאֲנַ֗חְנוּ לֹ֤א נֵדַע֙ מַֽה נַּעֲשֶׂ֔ה כִּ֥י עָלֶ֖יךָ עֵינֵֽינוּ'),
(11601, 14, 'WLC', 'WLC', 'he', '2CH', 20, 13, 'OT', 'וְכָ֨ל יְהוּדָ֔ה עֹמְדִ֖ים לִפְנֵ֣י יְהוָ֑ה גַּם טַפָּ֖ם נְשֵׁיהֶ֥ם וּבְנֵיהֶֽם'),
(11602, 14, 'WLC', 'WLC', 'he', '2CH', 20, 14, 'OT', 'וְיַחֲזִיאֵ֡ל בֶּן זְכַרְיָ֡הוּ בֶּן בְּ֠נָיָה בֶּן יְעִיאֵ֧ל בֶּן מַתַּנְיָ֛ה הַלֵּוִ֖י מִן בְּנֵ֣י אָסָ֑ף הָיְתָ֤ה עָלָיו֙ ר֣וּחַ יְהוָ֔ה בְּת֖וֹךְ הַקָּהָֽל'),
(11603, 14, 'WLC', 'WLC', 'he', '2CH', 20, 15, 'OT', 'וַיֹּ֗אמֶר הַקְשִׁ֤יבוּ כָל יְהוּדָה֙ וְיֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם וְהַמֶּ֖לֶךְ יְהוֹשָׁפָ֑ט כֹּֽה אָמַ֨ר יְהוָ֜ה לָכֶ֗ם אַ֠תֶּם אַל תִּֽירְא֤וּ וְאַל תֵּחַ֨תּוּ֙ מִפְּנֵ֨י הֶהָמ֤וֹן הָרָב֙ הַזֶּ֔ה כִּ֣י לֹ֥א לָכֶ֛ם הַמִּלְחָמָ֖ה כִּ֥י לֵאלֹהִֽים'),
(11604, 14, 'WLC', 'WLC', 'he', '2CH', 20, 16, 'OT', 'מָחָר֙ רְד֣וּ עֲלֵיהֶ֔ם הִנָּ֥ם עֹלִ֖ים בְּמַעֲלֵ֣ה הַצִּ֑יץ וּמְצָאתֶ֤ם אֹתָם֙ בְּס֣וֹף הַנַּ֔חַל פְּנֵ֖י מִדְבַּ֥ר יְרוּאֵֽל'),
(11605, 14, 'WLC', 'WLC', 'he', '2CH', 20, 17, 'OT', 'לֹ֥א לָכֶ֖ם לְהִלָּחֵ֣ם בָּזֹ֑את הִתְיַצְּב֣וּ עִמְד֡וּ וּרְא֣וּ אֶת יְשׁוּעַת֩ יְהוָ֨ה עִמָּכֶ֜ם יְהוּדָ֣ה וִֽירוּשָׁלִַ֗ם אַל תִּֽירְאוּ֙ וְאַל תֵּחַ֔תּוּ מָחָר֙ צְא֣וּ לִפְנֵיהֶ֔ם וַיהוָ֖ה עִמָּכֶֽם'),
(11606, 14, 'WLC', 'WLC', 'he', '2CH', 20, 18, 'OT', 'וַיִּקֹּ֧ד יְהוֹשָׁפָ֛ט אַפַּ֖יִם אָ֑רְצָה וְכָל יְהוּדָ֞ה וְיֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם נָֽפְלוּ֙ לִפְנֵ֣י יְהוָ֔ה לְהִֽשְׁתַּחֲוֺ֖ת לַיהוָֽה'),
(11607, 14, 'WLC', 'WLC', 'he', '2CH', 20, 19, 'OT', 'וַיָּקֻ֧מוּ הַלְוִיִּ֛ם מִן בְּנֵ֥י הַקְּהָתִ֖ים וּמִן בְּנֵ֣י הַקָּרְחִ֑ים לְהַלֵּ֗ל לַיהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל בְּק֥וֹל גָּד֖וֹל לְמָֽעְלָה'),
(11608, 14, 'WLC', 'WLC', 'he', '2CH', 20, 20, 'OT', 'וַיַּשְׁכִּ֣ימוּ בַבֹּ֔קֶר וַיֵּצְא֖וּ לְמִדְבַּ֣ר תְּק֑וֹעַ וּבְצֵאתָ֞ם עָמַ֣ד יְהוֹשָׁפָ֗ט וַיֹּ֨אמֶר֙ שְׁמָע֗וּנִי יְהוּדָה֙ וְיֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם הַאֲמִ֜ינוּ בַּיהוָ֤ה אֱלֹהֵיכֶם֙ וְתֵ֣אָמֵ֔נוּ הַאֲמִ֥ינוּ בִנְבִיאָ֖יו וְהַצְלִֽיחוּ'),
(11609, 14, 'WLC', 'WLC', 'he', '2CH', 20, 21, 'OT', 'וַיִּוָּעַץ֙ אֶל הָעָ֔ם וַיַּעֲמֵ֤ד מְשֹֽׁרֲרִים֙ לַיהוָ֔ה וּֽמְהַֽלְלִ֖ים לְהַדְרַת קֹ֑דֶשׁ בְּצֵאת֙ לִפְנֵ֣י הֶֽחָל֔וּץ וְאֹֽמְרִים֙ הוֹד֣וּ לַיהוָ֔ה כִּ֥י לְעוֹלָ֖ם חַסְדּֽוֹ'),
(11610, 14, 'WLC', 'WLC', 'he', '2CH', 20, 22, 'OT', 'וּבְעֵת֩ הֵחֵ֨לּוּ בְרִנָּ֜ה וּתְהִלָּ֗ה נָתַ֣ן יְהוָ֣ה מְ֠אָֽרְבִים עַל בְּנֵ֨י עַמּ֜וֹן מוֹאָ֧ב וְהַר שֵׂעִ֛יר הַבָּאִ֥ים לִֽיהוּדָ֖ה וַיִּנָּגֵֽפוּ'),
(11611, 14, 'WLC', 'WLC', 'he', '2CH', 20, 23, 'OT', 'וַ֠יַּֽעַמְדוּ בְּנֵ֨י עַמּ֧וֹן וּמוֹאָ֛ב עַל יֹשְׁבֵ֥י הַר שֵׂעִ֖יר לְהַחֲרִ֣ים וּלְהַשְׁמִ֑יד וּכְכַלּוֹתָם֙ בְּיוֹשְׁבֵ֣י שֵׂעִ֔יר עָזְר֥וּ אִישׁ בְּרֵעֵ֖הוּ לְמַשְׁחִֽית'),
(11612, 14, 'WLC', 'WLC', 'he', '2CH', 20, 24, 'OT', 'וִֽיהוּדָ֛ה בָּ֥א עַל הַמִּצְפֶּ֖ה לַמִּדְבָּ֑ר וַיִּפְנוּ֙ אֶל הֶ֣הָמ֔וֹן וְהִנָּ֧ם פְּגָרִ֛ים נֹפְלִ֥ים אַ֖רְצָה וְאֵ֥ין פְּלֵיטָֽה'),
(11613, 14, 'WLC', 'WLC', 'he', '2CH', 20, 25, 'OT', 'וַיָּבֹ֨א יְהוֹשָׁפָ֣ט וְעַמּוֹ֮ לָבֹ֣ז אֶת שְׁלָלָם֒ וַיִּמְצְאוּ֩ בָהֶ֨ם לָרֹ֜ב וּרְכ֤וּשׁ וּפְגָרִים֙ וּכְלֵ֣י חֲמֻד֔וֹת וַיְנַצְּל֥וּ לָהֶ֖ם לְאֵ֣ין מַשָּׂ֑א וַיִּֽהְי֞וּ יָמִ֧ים שְׁלוֹשָׁ֛ה בֹּזְזִ֥ים אֶת הַשָּׁלָ֖ל כִּ֥י רַב הֽוּא'),
(11614, 14, 'WLC', 'WLC', 'he', '2CH', 20, 26, 'OT', 'וּבַיּ֣וֹם הָרְבִעִ֗י נִקְהֲלוּ֙ לְעֵ֣מֶק בְּרָכָ֔ה כִּי שָׁ֖ם בֵּרֲכ֣וּ אֶת יְהוָ֑ה עַל כֵּ֡ן קָֽרְא֞וּ אֶת שֵׁ֨ם הַמָּק֥וֹם הַה֛וּא עֵ֥מֶק בְּרָכָ֖ה עַד הַיּֽוֹם'),
(11615, 14, 'WLC', 'WLC', 'he', '2CH', 20, 27, 'OT', 'וַ֠יָּשֻׁבוּ כָּל אִ֨ישׁ יְהוּדָ֤ה וִֽירוּשָׁלִַ֨ם֙ וִֽיהוֹשָׁפָ֣ט בְּרֹאשָׁ֔ם לָשׁ֥וּב אֶל יְרוּשָׁלִַ֖ם בְּשִׂמְחָ֑ה כִּֽי שִׂמְּחָ֥ם יְהוָ֖ה מֵֽאוֹיְבֵיהֶֽם'),
