(11647, 14, 'WLC', 'WLC', 'he', '2CH', 22, 2, 'OT', 'בֶּן אַרְבָּעִ֨ים וּשְׁתַּ֤יִם שָׁנָה֙ אֲחַזְיָ֣הוּ בְמָלְכ֔וֹ וְשָׁנָ֣ה אַחַ֔ת מָלַ֖ךְ בִּֽירוּשָׁלִָ֑ם וְשֵׁ֣ם אִמּ֔וֹ עֲתַלְיָ֖הוּ בַּת עָמְרִֽי'),
(11648, 14, 'WLC', 'WLC', 'he', '2CH', 22, 3, 'OT', 'גַּם ה֣וּא הָלַ֔ךְ בְּדַרְכֵ֖י בֵּ֣ית אַחְאָ֑ב כִּ֥י אִמּ֛וֹ הָיְתָ֥ה יֽוֹעַצְתּ֖וֹ לְהַרְשִֽׁיעַ'),
(11649, 14, 'WLC', 'WLC', 'he', '2CH', 22, 4, 'OT', 'וַיַּ֧עַשׂ הָרַ֛ע בְּעֵינֵ֥י יְהוָ֖ה כְּבֵ֣ית אַחְאָ֑ב כִּי הֵ֜מָּה הָֽיוּ ל֣וֹ יֽוֹעֲצִ֗ים אַחֲרֵ֛י מ֥וֹת אָבִ֖יו לְמַשְׁחִ֥ית לֽוֹ'),
(11650, 14, 'WLC', 'WLC', 'he', '2CH', 22, 5, 'OT', 'גַּ֣ם בַּעֲצָתָם֮ הָלַךְ֒ וַיֵּלֶךְ֩ אֶת יְהוֹרָ֨ם בֶּן אַחְאָ֜ב מֶ֣לֶךְ יִשְׂרָאֵ֗ל לַמִּלְחָמָ֛ה עַל חֲזָאֵ֥ל מֶֽלֶךְ אֲרָ֖ם בְּרָמ֣וֹת גִּלְעָ֑ד וַיַּכּ֥וּ הָֽרַמִּ֖ים אֶת יוֹרָֽם'),
(11651, 14, 'WLC', 'WLC', 'he', '2CH', 22, 6, 'OT', 'וַיָּ֜שָׁב לְהִתְרַפֵּ֣א בְיִזְרְעֶ֗אל כִּ֤י הַמַּכִּים֙ אֲשֶׁ֣ר הִכֻּ֣הוּ בָֽרָמָ֔ה בְּהִלָּ֣חֲמ֔וֹ אֶת חֲזָהאֵ֖ל מֶ֣לֶךְ אֲרָ֑ם וַעֲזַרְיָ֨הוּ בֶן יְהוֹרָ֜ם מֶ֣לֶךְ יְהוּדָ֗ה יָרַ֡ד לִרְא֞וֹת אֶת יְהוֹרָ֧ם בֶּן אַחְאָ֛ב בְּיִזְרְעֶ֖אל כִּי חֹלֶ֥ה הֽוּא'),
(11652, 14, 'WLC', 'WLC', 'he', '2CH', 22, 7, 'OT', 'וּמֵֽאֱלֹהִ֗ים הָיְתָה֙ תְּבוּסַ֣ת אֲחַזְיָ֔הוּ לָב֖וֹא אֶל יוֹרָ֑ם וּבְבֹא֗וֹ יָצָ֤א עִם יְהוֹרָם֙ אֶל יֵה֣וּא בֶן נִמְשִׁ֔י אֲשֶׁ֣ר מְשָׁח֣וֹ יְהוָ֔ה לְהַכְרִ֖ית אֶת בֵּ֥ית אַחְאָֽב'),
(11653, 14, 'WLC', 'WLC', 'he', '2CH', 22, 8, 'OT', 'וַיְהִ֕י כְּהִשָּׁפֵ֥ט יֵה֖וּא עִם בֵּ֣ית אַחְאָ֑ב וַיִּמְצָא֩ אֶת שָׂרֵ֨י יְהוּדָ֜ה וּבְנֵ֨י אֲחֵ֧י אֲחַזְיָ֛הוּ מְשָׁרְתִ֥ים לַאֲחַזְיָ֖הוּ וַיַּהַרְגֵֽם'),
(11654, 14, 'WLC', 'WLC', 'he', '2CH', 22, 9, 'OT', 'וַיְבַקֵּשׁ֩ אֶת אֲחַזְיָ֨הוּ וַֽיִּלְכְּדֻ֜הוּ וְה֧וּא מִתְחַבֵּ֣א בְשֹֽׁמְר֗וֹן וַיְבִאֻ֣הוּ אֶל יֵהוּא֮ וַיְמִתֻהוּ֒ וַֽיִּקְבְּרֻ֔הוּ כִּ֤י אָֽמְרוּ֙ בֶּן יְהוֹשָׁפָ֣ט ה֔וּא אֲשֶׁר דָּרַ֥שׁ אֶת יְהוָ֖ה בְּכָל לְבָב֑וֹ וְאֵין֙ לְבֵ֣ית אֲחַזְיָ֔הוּ לַעְצֹ֥ר כֹּ֖חַ לְמַמְלָכָֽה'),
(11655, 14, 'WLC', 'WLC', 'he', '2CH', 22, 10, 'OT', 'וַעֲתַלְיָ֨הוּ֙ אֵ֣ם אֲחַזְיָ֔הוּ רָאֲתָ֖ה כִּ֣י מֵ֣ת בְּנָ֑הּ וַתָּ֗קָם וַתְּדַבֵּ֛ר אֶת כָּל זֶ֥רַע הַמַּמְלָכָ֖ה לְבֵ֥ית יְהוּדָֽה'),
(11656, 14, 'WLC', 'WLC', 'he', '2CH', 22, 11, 'OT', 'וַתִּקַּח֩ יְהוֹשַׁבְעַ֨ת בַּת הַמֶּ֜לֶךְ אֶת יוֹאָ֣שׁ בֶּן אֲחַזְיָ֗הוּ וַתִּגְנֹ֤ב אֹתוֹ֙ מִתּ֤וֹךְ בְּנֵֽי הַמֶּ֨לֶךְ֙ הַמּ֣וּמָתִ֔ים וַתִּתֵּ֥ן אֹת֛וֹ וְאֶת מֵֽינִקְתּ֖וֹ בַּחֲדַ֣ר הַמִּטּ֑וֹת וַתַּסְתִּירֵ֡הוּ יְהוֹשַׁבְעַ֣ת בַּת הַמֶּ֣לֶךְ יְהוֹרָ֡ם אֵשֶׁת֩ יְהוֹיָדָ֨ע הַכֹּהֵ֜ן כִּ֣י הִיא֩ הָיְתָ֨ה אֲח֧וֹת אֲחַזְיָ֛הוּ מִפְּנֵ֥י עֲתַלְיָ֖הוּ וְלֹ֥א הֱמִיתָֽתְהוּ'),
(11657, 14, 'WLC', 'WLC', 'he', '2CH', 22, 12, 'OT', 'וַיְהִ֤י אִתָּם֙ בְּבֵ֣ית הָֽאֱלֹהִ֔ים מִתְחַבֵּ֖א שֵׁ֣שׁ שָׁנִ֖ים וַעֲתַלְיָ֖ה מֹלֶ֥כֶת עַל הָאָֽרֶץ'),
(11658, 14, 'WLC', 'WLC', 'he', '2CH', 23, 1, 'OT', 'וּבַשָּׁנָ֨ה הַשְּׁבִעִ֜ית הִתְחַזַּ֣ק יְהוֹיָדָ֗ע וַיִּקַּ֣ח אֶת שָׂרֵ֣י הַמֵּא֡וֹת לַעֲזַרְיָ֣הוּ בֶן יְרֹחָ֡ם וּלְיִשְׁמָעֵ֣אל בֶּן יְ֠הוֹחָנָן וְלַֽעֲזַרְיָ֨הוּ בֶן עוֹבֵ֜ד וְאֶת מַעֲשֵׂיָ֧הוּ בֶן עֲדָיָ֛הוּ וְאֶת אֱלִישָׁפָ֥ט בֶּן זִכְרִ֖י עִמּ֥וֹ בַבְּרִֽית'),
(11659, 14, 'WLC', 'WLC', 'he', '2CH', 23, 2, 'OT', 'וַיָּסֹ֨בּוּ֙ בִּֽיהוּדָ֔ה וַיִּקְבְּצ֤וּ אֶת הַלְוִיִּם֙ מִכָּל עָרֵ֣י יְהוּדָ֔ה וְרָאשֵׁ֥י הָאָב֖וֹת לְיִשְׂרָאֵ֑ל וַיָּבֹ֖אוּ אֶל יְרוּשָׁלִָֽם'),
(11660, 14, 'WLC', 'WLC', 'he', '2CH', 23, 3, 'OT', 'וַיִּכְרֹ֨ת כָּל הַקָּהָ֥ל בְּרִ֛ית בְּבֵ֥ית הָאֱלֹהִ֖ים עִם הַמֶּ֑לֶךְ וַיֹּ֣אמֶר לָהֶ֗ם הִנֵּ֤ה בֶן הַמֶּ֨לֶךְ֙ יִמְלֹ֔ךְ כַּאֲשֶׁ֛ר דִּבֶּ֥ר יְהוָ֖ה עַל בְּנֵ֥י דָוִֽיד'),
(11661, 14, 'WLC', 'WLC', 'he', '2CH', 23, 4, 'OT', 'זֶ֥ה הַדָּבָ֖ר אֲשֶׁ֣ר תַּעֲשׂ֑וּ הַשְּׁלִשִׁ֨ית מִכֶּ֜ם בָּאֵ֣י הַשַּׁבָּ֗ת לַכֹּֽהֲנִים֙ וְלַלְוִיִּ֔ם לְשֹֽׁעֲרֵ֖י הַסִּפִּֽים'),
(11662, 14, 'WLC', 'WLC', 'he', '2CH', 23, 5, 'OT', 'וְהַשְּׁלִשִׁית֙ בְּבֵ֣ית הַמֶּ֔לֶךְ וְהַשְּׁלִשִׁ֖ית בְּשַׁ֣עַר הַיְס֑וֹד וְכָל הָעָ֔ם בְּחַצְר֖וֹת בֵּ֥ית יְהוָֽה'),
(11663, 14, 'WLC', 'WLC', 'he', '2CH', 23, 6, 'OT', 'וְאַל יָב֣וֹא בֵית יְהוָ֗ה כִּ֤י אִם הַכֹּֽהֲנִים֙ וְהַמְשָׁרְתִ֣ים לַלְוִיִּ֔ם הֵ֥מָּה יָבֹ֖אוּ כִּי קֹ֣דֶשׁ הֵ֑מָּה וְכָל הָעָ֔ם יִשְׁמְר֖וּ מִשְׁמֶ֥רֶת יְהוָֽה'),
(11664, 14, 'WLC', 'WLC', 'he', '2CH', 23, 7, 'OT', 'וְהִקִּיפוּ֩ הַלְוִיִּ֨ם אֶת הַמֶּ֜לֶךְ סָבִ֗יב אִ֚ישׁ וְכֵלָ֣יו בְּיָד֔וֹ וְהַבָּ֥א אֶל הַבַּ֖יִת יוּמָ֑ת וִֽהְי֥וּ אֶת הַמֶּ֖לֶךְ בְּבֹא֥וֹ וּבְצֵאתֽוֹ'),
(11665, 14, 'WLC', 'WLC', 'he', '2CH', 23, 8, 'OT', 'וַיַּעֲשׂ֨וּ הַלְוִיִּ֜ם וְכָל יְהוּדָ֗ה כְּכֹ֣ל אֲשֶׁר צִוָּה֮ יְהוֹיָדָ֣ע הַכֹּהֵן֒ וַיִּקְחוּ֙ אִ֣ישׁ אֶת אֲנָשָׁ֔יו בָּאֵ֣י הַשַּׁבָּ֔ת עִ֖ם יוֹצְאֵ֣י הַשַּׁבָּ֑ת כִּ֣י לֹ֥א פָטַ֛ר יְהוֹיָדָ֥ע הַכֹּהֵ֖ן אֶת הַֽמַּחְלְקֽוֹת'),
(11666, 14, 'WLC', 'WLC', 'he', '2CH', 23, 9, 'OT', 'וַיִּתֵּן֩ יְהוֹיָדָ֨ע הַכֹּהֵ֜ן לְשָׂרֵ֣י הַמֵּא֗וֹת אֶת הַֽחֲנִיתִים֙ וְאֶת הַמָּגִנּוֹת֙ וְאֶת הַשְּׁלָטִ֔ים אֲשֶׁ֖ר לַמֶּ֣לֶךְ דָּוִ֑יד אֲשֶׁ֖ר בֵּ֥ית הָאֱלֹהִֽים'),
(11667, 14, 'WLC', 'WLC', 'he', '2CH', 23, 10, 'OT', 'וַיַּעֲמֵ֨ד אֶת כָּל הָעָ֜ם וְאִ֣ישׁ שִׁלְח֣וֹ בְיָד֗וֹ מִכֶּ֨תֶף הַבַּ֤יִת הַיְמָנִית֙ עַד כֶּ֤תֶף הַבַּ֨יִת֙ הַשְּׂמָאלִ֔ית לַמִּזְבֵּ֖חַ וְלַבָּ֑יִת עַל הַמֶּ֖לֶךְ סָבִֽיב'),
(11668, 14, 'WLC', 'WLC', 'he', '2CH', 23, 11, 'OT', 'וַיּוֹצִ֣יאוּ אֶת בֶּן הַמֶּ֗לֶךְ וַיִּתְּנ֤וּ עָלָיו֙ אֶת הַנֵּ֨זֶר֙ וְאֶת הָ֣עֵד֔וּת וַיַּמְלִ֖יכוּ אֹת֑וֹ וַיִּמְשָׁחֻ֨הוּ֙ יְהוֹיָדָ֣ע וּבָנָ֔יו וַיֹּאמְר֖וּ יְחִ֥י הַמֶּֽלֶךְ'),
(11669, 14, 'WLC', 'WLC', 'he', '2CH', 23, 12, 'OT', 'וַתִּשְׁמַ֣ע עֲתַלְיָ֗הוּ אֶת ק֤וֹל הָעָם֙ הָֽרָצִ֔ים וְהַֽמְהַֽלְלִ֖ים אֶת הַמֶּ֑לֶךְ וַתָּב֥וֹא אֶל הָעָ֖ם בֵּ֥ית יְהוָֽה'),
(11670, 14, 'WLC', 'WLC', 'he', '2CH', 23, 13, 'OT', 'וַתֵּ֡רֶא וְהִנֵּ֣ה הַמֶּלֶךְ֩ עוֹמֵ֨ד עַֽל עַמּוּד֜וֹ בַּמָּב֗וֹא וְהַשָּׂרִ֣ים וְהַחֲצֹצְרוֹת֮ עַל הַמֶּלֶךְ֒ וְכָל עַ֨ם הָאָ֜רֶץ שָׂמֵ֗חַ וְתוֹקֵ֨עַ֙ בַּחֲצֹ֣צְר֔וֹת וְהַמְשֽׁוֹרֲרִים֙ בִּכְלֵ֣י הַשִּׁ֔יר וּמוֹדִיעִ֖ים לְהַלֵּ֑ל וַתִּקְרַ֤ע עֲתַלְיָ֨הוּ֙ אֶת בְּגָדֶ֔יהָ וַתֹּ֖אמֶר קֶ֥שֶׁר קָֽשֶׁר'),
(11671, 14, 'WLC', 'WLC', 'he', '2CH', 23, 14, 'OT', 'וַיּוֹצֵא֩ יְהוֹיָדָ֨ע הַכֹּהֵ֜ן אֶת שָׂרֵ֥י הַמֵּא֣וֹת פְּקוּדֵ֣י הַחַ֗יִל וַיֹּ֤אמֶר אֲלֵהֶם֙ הֽוֹצִיא֨וּהָ֙ אֶל מִבֵּ֣ית הַשְּׂדֵר֔וֹת וְהַבָּ֥א אַחֲרֶ֖יהָ יוּמַ֣ת בֶּחָ֑רֶב כִּ֚י אָמַ֣ר הַכֹּהֵ֔ן לֹ֥א תְמִית֖וּהָ בֵּ֥ית יְהוָֽה'),
(11672, 14, 'WLC', 'WLC', 'he', '2CH', 23, 15, 'OT', 'וַיָּשִׂ֤ימוּ לָהּ֙ יָדַ֔יִם וַתָּב֛וֹא אֶל מְב֥וֹא שַֽׁעַר הַסּוּסִ֖ים בֵּ֣ית הַמֶּ֑לֶךְ וַיְמִית֖וּהָ שָֽׁם'),
(11673, 14, 'WLC', 'WLC', 'he', '2CH', 23, 16, 'OT', 'וַיִּכְרֹ֤ת יְהוֹיָדָע֙ בְּרִ֔ית בֵּינ֕וֹ וּבֵ֥ין כָּל הָעָ֖ם וּבֵ֣ין הַמֶּ֑לֶךְ לִהְי֥וֹת לְעָ֖ם לַיהוָֽה'),
(11674, 14, 'WLC', 'WLC', 'he', '2CH', 23, 17, 'OT', 'וַיָּבֹ֨אוּ כָל הָעָ֤ם בֵּית הַבַּ֨עַל֙ וַֽיִּתְּצֻ֔הוּ וְאֶת מִזְבְּחֹתָ֥יו וְאֶת צְלָמָ֖יו שִׁבֵּ֑רוּ וְאֵ֗ת מַתָּן֙ כֹּהֵ֣ן הַבַּ֔עַל הָרְג֖וּ לִפְנֵ֥י הַֽמִּזְבְּחֽוֹת'),
(11675, 14, 'WLC', 'WLC', 'he', '2CH', 23, 18, 'OT', 'וַיָּשֶׂם֩ יְהוֹיָדָ֨ע פְּקֻדֹּ֜ת בֵּ֣ית יְהוָ֗ה בְּיַ֨ד הַכֹּהֲנִ֣ים הַלְוִיִּם֮ אֲשֶׁ֣ר חָלַ֣ק דָּוִיד֮ עַל בֵּ֣ית יְהוָה֒ לְֽהַעֲל֞וֹת עֹל֣וֹת יְהוָ֗ה כַּכָּת֛וּב בְּתוֹרַ֥ת מֹשֶׁ֖ה בְּשִׂמְחָ֣ה וּבְשִׁ֑יר עַ֖ל יְדֵ֥י דָוִֽיד'),
(11676, 14, 'WLC', 'WLC', 'he', '2CH', 23, 19, 'OT', 'וַֽיַּעֲמֵד֙ הַשּׁ֣וֹעֲרִ֔ים עַֽל שַׁעֲרֵ֖י בֵּ֣ית יְהוָ֑ה וְלֹֽא יָבֹ֥א טָמֵ֖א לְכָל דָּבָֽר'),
(11677, 14, 'WLC', 'WLC', 'he', '2CH', 23, 20, 'OT', 'וַיִּקַּ֣ח אֶת שָׂרֵ֣י הַמֵּא֡וֹת וְאֶת הָֽאַדִּירִים֩ וְאֶת הַמּֽוֹשְׁלִ֨ים בָּעָ֜ם וְאֵ֣ת כָּל עַ֣ם הָאָ֗רֶץ וַיּ֤וֹרֶד אֶת הַמֶּ֨לֶךְ֙ מִבֵּ֣ית יְהוָ֔ה וַיָּבֹ֛אוּ בְּתֽוֹךְ שַׁ֥עַר הָֽעֶלְי֖וֹן בֵּ֣ית הַמֶּ֑לֶךְ וַיּוֹשִׁ֨יבוּ֙ אֶת הַמֶּ֔לֶךְ עַ֖ל כִּסֵּ֥א הַמַּמְלָכָֽה'),
(11678, 14, 'WLC', 'WLC', 'he', '2CH', 23, 21, 'OT', 'וַיִּשְׂמְח֥וּ כָל עַם הָאָ֖רֶץ וְהָעִ֣יר שָׁקָ֑טָה וְאֶת עֲתַלְיָ֖הוּ הֵמִ֥יתוּ בֶחָֽרֶב'),
(11679, 14, 'WLC', 'WLC', 'he', '2CH', 24, 1, 'OT', 'בֶּן שֶׁ֤בַע שָׁנִים֙ יֹאָ֣שׁ בְּמָלְכ֔וֹ וְאַרְבָּעִ֣ים שָׁנָ֔ה מָלַ֖ךְ בִּֽירוּשָׁלִָ֑ם וְשֵׁ֣ם אִמּ֔וֹ צִבְיָ֖ה מִבְּאֵ֥ר שָֽׁבַע'),
(11680, 14, 'WLC', 'WLC', 'he', '2CH', 24, 2, 'OT', 'וַיַּ֧עַשׂ יוֹאָ֛שׁ הַיָּשָׁ֖ר בְּעֵינֵ֣י יְהוָ֑ה כָּל יְמֵ֖י יְהוֹיָדָ֥ע הַכֹּהֵֽן'),
(11681, 14, 'WLC', 'WLC', 'he', '2CH', 24, 3, 'OT', 'וַיִּשָּׂא ל֥וֹ יְהוֹיָדָ֖ע נָשִׁ֣ים שְׁתָּ֑יִם וַיּ֖וֹלֶד בָּנִ֥ים וּבָנֽוֹת'),
(11682, 14, 'WLC', 'WLC', 'he', '2CH', 24, 4, 'OT', 'וַיְהִ֖י אַחֲרֵי כֵ֑ן הָיָה֙ עִם לֵ֣ב יוֹאָ֔שׁ לְחַדֵּ֖שׁ אֶת בֵּ֥ית יְהוָֽה'),
(11683, 14, 'WLC', 'WLC', 'he', '2CH', 24, 5, 'OT', 'וַיִּקְבֹּץ֮ אֶת הַכֹּהֲנִ֣ים וְהַלְוִיִּם֒ וַיֹּ֣אמֶר לָהֶ֡ם צְא֣וּ לְעָרֵ֪י יְהוּדָ֟ה וְקִבְצוּ֩ מִכָּל יִשְׂרָאֵ֨ל כֶּ֜סֶף לְחַזֵּ֣ק אֶת בֵּ֣ית אֱלֹֽהֵיכֶ֗ם מִדֵּ֤י שָׁנָה֙ בְּשָׁנָ֔ה וְאַתֶּ֖ם תְּמַהֲר֣וּ לַדָּבָ֑ר וְלֹ֥א מִֽהֲר֖וּ הַֽלְוִיִּֽם'),
(11684, 14, 'WLC', 'WLC', 'he', '2CH', 24, 6, 'OT', 'וַיִּקְרָ֣א הַמֶּלֶךְ֮ לִֽיהוֹיָדָ֣ע הָרֹאשׁ֒ וַיֹּ֣אמֶר ל֗וֹ מַדּ֨וּעַ֙ לֹֽא דָרַ֣שְׁתָּ עַל הַלְוִיִּ֔ם לְהָבִ֞יא מִֽיהוּדָ֣ה וּמִֽירוּשָׁלִַ֗ם אֶת מַשְׂאַת֙ מֹשֶׁ֣ה עֶֽבֶד יְהוָ֔ה וְהַקָּהָ֖ל לְיִשְׂרָאֵ֑ל לְאֹ֖הֶל הָעֵדֽוּת'),
(11685, 14, 'WLC', 'WLC', 'he', '2CH', 24, 7, 'OT', 'כִּ֤י עֲתַלְיָ֨הוּ֙ הַמִּרְשַׁ֔עַת בָּנֶ֥יהָ פָרְצ֖וּ אֶת בֵּ֣ית הָאֱלֹהִ֑ים וְגַם֙ כָּל קָדְשֵׁ֣י בֵית יְהוָ֔ה עָשׂ֖וּ לַבְּעָלִֽים'),
(11686, 14, 'WLC', 'WLC', 'he', '2CH', 24, 8, 'OT', 'וַיֹּ֣אמֶר הַמֶּ֔לֶךְ וַֽיַּעֲשׂ֖וּ אֲר֣וֹן אֶחָ֑ד וַֽיִּתְּנֻ֛הוּ בְּשַׁ֥עַר בֵּית יְהוָ֖ה חֽוּצָה'),
(11687, 14, 'WLC', 'WLC', 'he', '2CH', 24, 9, 'OT', 'וַיִּתְּנוּ ק֞וֹל בִּֽיהוּדָ֣ה וּבִֽירוּשָׁלִַ֗ם לְהָבִ֤יא לַֽיהוָה֙ מַשְׂאַ֞ת מֹשֶׁ֧ה עֶֽבֶד הָאֱלֹהִ֛ים עַל יִשְׂרָאֵ֖ל בַּמִּדְבָּֽר'),
(11688, 14, 'WLC', 'WLC', 'he', '2CH', 24, 10, 'OT', 'וַיִּשְׂמְח֥וּ כָל הַשָּׂרִ֖ים וְכָל הָעָ֑ם וַיָּבִ֛יאוּ וַיַּשְׁלִ֥יכוּ לָאָר֖וֹן עַד לְכַלֵּֽה'),
(11689, 14, 'WLC', 'WLC', 'he', '2CH', 24, 11, 'OT', 'וַיְהִ֡י בְּעֵת֩ יָבִ֨יא אֶת הָֽאָר֜וֹן אֶל פְּקֻדַּ֣ת הַמֶּלֶךְ֮ בְּיַ֣ד הַלְוִיִּם֒ וְכִרְאוֹתָ֞ם כִּי רַ֣ב הַכֶּ֗סֶף וּבָ֨א סוֹפֵ֤ר הַמֶּ֨לֶךְ֙ וּפְקִיד֙ כֹּהֵ֣ן הָרֹ֔אשׁ וִיעָ֨רוּ֙ אֶת הָ֣אָר֔וֹן וְיִשָּׂאֻ֖הוּ וִֽישִׁיבֻ֣הוּ אֶל מְקֹמ֑וֹ כֹּ֤ה עָשׂוּ֙ לְי֣וֹם בְּי֔וֹם וַיַּֽאַסְפוּ כֶ֖סֶף לָרֹֽב'),
(11690, 14, 'WLC', 'WLC', 'he', '2CH', 24, 12, 'OT', 'וַיִּתְּנֵ֨הוּ הַמֶּ֜לֶךְ וִֽיהוֹיָדָ֗ע אֶל עוֹשֵׂה֙ מְלֶ֨אכֶת֙ עֲבוֹדַ֣ת בֵּית יְהוָ֔ה וַיִּֽהְי֤וּ שֹׂכְרִים֙ חֹצְבִ֣ים וְחָרָשִׁ֔ים לְחַדֵּ֖שׁ בֵּ֣ית יְהוָ֑ה וְ֠גַם לְחָרָשֵׁ֤י בַרְזֶל֙ וּנְחֹ֔שֶׁת לְחַזֵּ֖ק אֶת בֵּ֥ית יְהוָֽה'),
(11691, 14, 'WLC', 'WLC', 'he', '2CH', 24, 13, 'OT', 'וַֽיַּעֲשׂוּ֙ עֹשֵׂ֣י הַמְּלָאכָ֔ה וַתַּ֧עַל אֲרוּכָ֛ה לַמְּלָאכָ֖ה בְּיָדָ֑ם וַֽיַּעֲמִ֜ידוּ אֶת בֵּ֧ית הָֽאֱלֹהִ֛ים עַל מַתְכֻּנְתּ֖וֹ וַֽיְאַמְּצֻֽהוּ'),
(11692, 14, 'WLC', 'WLC', 'he', '2CH', 24, 14, 'OT', 'וּֽכְכַלּוֹתָ֡ם הֵבִ֣יאוּ לִפְנֵי֩ הַמֶּ֨לֶךְ וִֽיהוֹיָדָ֜ע אֶת שְׁאָ֣ר הַכֶּ֗סֶף וַיַּעֲשֵׂ֨הוּ כֵלִ֤ים לְבֵית יְהוָה֙ כְּלֵ֣י שָׁרֵ֔ת וְהַעֲל֣וֹת וְכַפּ֔וֹת וּכְלֵ֥י זָהָ֖ב וָכָ֑סֶף וַ֠יִּֽהְיוּ מַעֲלִ֨ים עֹל֤וֹת בְּבֵית יְהוָה֙ תָּמִ֔יד כֹּ֖ל יְמֵ֥י יְהוֹיָדָֽע'),
(11693, 14, 'WLC', 'WLC', 'he', '2CH', 24, 15, 'OT', 'וַיִּזְקַ֧ן יְהוֹיָדָ֛ע וַיִּשְׂבַּ֥ע יָמִ֖ים וַיָּמֹ֑ת בֶּן מֵאָ֧ה וּשְׁלֹשִׁ֛ים שָׁנָ֖ה בְּמוֹתֽוֹ'),
(11694, 14, 'WLC', 'WLC', 'he', '2CH', 24, 16, 'OT', 'וַיִּקְבְּרֻ֥הוּ בְעִיר דָּוִ֖יד עִם הַמְּלָכִ֑ים כִּֽי עָשָׂ֤ה טוֹבָה֙ בְּיִשְׂרָאֵ֔ל וְעִ֥ם הָאֱלֹהִ֖ים וּבֵיתֽוֹ'),
(11695, 14, 'WLC', 'WLC', 'he', '2CH', 24, 17, 'OT', 'וְאַֽחֲרֵ֥י מוֹת֙ יְה֣וֹיָדָ֔ע בָּ֚אוּ שָׂרֵ֣י יְהוּדָ֔ה וַיִּֽשְׁתַּחֲו֖וּ לַמֶּ֑לֶךְ אָ֛ז שָׁמַ֥ע הַמֶּ֖לֶךְ אֲלֵיהֶֽם'),
(11696, 14, 'WLC', 'WLC', 'he', '2CH', 24, 18, 'OT', 'וַיַּֽעַזְב֗וּ אֶת בֵּ֤ית יְהוָה֙ אֱלֹהֵ֣י אֲבוֹתֵיהֶ֔ם וַיַּֽעַבְד֥וּ אֶת הָאֲשֵׁרִ֖ים וְאֶת הָֽעֲצַבִּ֑ים וַֽיְהִי קֶ֗צֶף עַל יְהוּדָה֙ וִיר֣וּשָׁלִַ֔ם בְּאַשְׁמָתָ֖ם זֹֽאת'),
(11697, 14, 'WLC', 'WLC', 'he', '2CH', 24, 19, 'OT', 'וַיִּשְׁלַ֤ח בָּהֶם֙ נְבִאִ֔ים לַהֲשִׁיבָ֖ם אֶל יְהוָ֑ה וַיָּעִ֥ידוּ בָ֖ם וְלֹ֥א הֶאֱזִֽינוּ'),
(11698, 14, 'WLC', 'WLC', 'he', '2CH', 24, 20, 'OT', 'וְר֣וּחַ אֱלֹהִ֗ים לָֽבְשָׁה֙ אֶת זְכַרְיָה֙ בֶּן יְהוֹיָדָ֣ע הַכֹּהֵ֔ן וַֽיַּעֲמֹ֖ד מֵעַ֣ל לָעָ֑ם וַיֹּ֨אמֶר לָהֶ֜ם כֹּ֣ה אָמַ֣ר הָאֱלֹהִ֗ים לָמָה֩ אַתֶּ֨ם עֹבְרִ֜ים אֶת מִצְוֺ֤ת יְהוָה֙ וְלֹ֣א תַצְלִ֔יחוּ כִּֽי עֲזַבְתֶּ֥ם אֶת יְהוָ֖ה וַיַּֽעֲזֹ֥ב אֶתְכֶֽם'),
(11699, 14, 'WLC', 'WLC', 'he', '2CH', 24, 21, 'OT', 'וַיִּקְשְׁר֣וּ עָלָ֔יו וַיִּרְגְּמֻ֥הוּ אֶ֖בֶן בְּמִצְוַ֣ת הַמֶּ֑לֶךְ בַּחֲצַ֖ר בֵּ֥ית יְהוָֽה'),
(11700, 14, 'WLC', 'WLC', 'he', '2CH', 24, 22, 'OT', 'וְלֹא זָכַ֞ר יוֹאָ֣שׁ הַמֶּ֗לֶךְ הַחֶ֨סֶד֙ אֲשֶׁ֨ר עָשָׂ֜ה יְהוֹיָדָ֤ע אָבִיו֙ עִמּ֔וֹ וַֽיַּהֲרֹ֖ג אֶת בְּנ֑וֹ וּכְמוֹת֣וֹ אָמַ֔ר יֵ֥רֶא יְהוָ֖ה וְיִדְרֹֽשׁ'),
(11701, 14, 'WLC', 'WLC', 'he', '2CH', 24, 23, 'OT', 'וַיְהִ֣י לִתְקוּפַ֣ת הַשָּׁנָ֗ה עָלָ֣ה עָלָיו֮ חֵ֣יל אֲרָם֒ וַיָּבֹ֗אוּ אֶל יְהוּדָה֙ וִיר֣וּשָׁלִַ֔ם וַיַּשְׁחִ֛יתוּ אֶת כָּל שָׂרֵ֥י הָעָ֖ם מֵעָ֑ם וְכָל שְׁלָלָ֥ם שִׁלְּח֖וּ לְמֶ֥לֶךְ דַּרְמָֽשֶׂק'),
(11702, 14, 'WLC', 'WLC', 'he', '2CH', 24, 24, 'OT', 'כִּי֩ בְמִצְעַ֨ר אֲנָשִׁ֜ים בָּ֣אוּ חֵ֣יל אֲרָ֗ם וַֽיהוָה֙ נָתַ֨ן בְּיָדָ֥ם חַ֨יִל֙ לָרֹ֣ב מְאֹ֔ד כִּ֣י עָֽזְב֔וּ אֶת יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵיהֶ֑ם וְאֶת יוֹאָ֖שׁ עָשׂ֥וּ שְׁפָטִֽים'),
(11703, 14, 'WLC', 'WLC', 'he', '2CH', 24, 25, 'OT', 'וּבְלֶכְתָּ֣ם מִמֶּ֗נּוּ כִּֽי עָזְב֣וּ אֹתוֹ֮ במחליים רַבִּים֒ הִתְקַשְּׁר֨וּ עָלָ֜יו עֲבָדָ֗יו בִּדְמֵי֙ בְּנֵי֙ יְהוֹיָדָ֣ע הַכֹּהֵ֔ן וַיַּֽהַרְגֻ֥הוּ עַל מִטָּת֖וֹ וַיָּמֹ֑ת וַֽיִּקְבְּרֻ֨הוּ֙ בְּעִ֣יר דָּוִ֔יד וְלֹ֥א קְבָרֻ֖הוּ בְּקִבְר֥וֹת הַמְּלָכִֽים'),
(11704, 14, 'WLC', 'WLC', 'he', '2CH', 24, 26, 'OT', 'וְאֵ֖לֶּה הַמִּתְקַשְּׁרִ֣ים עָלָ֑יו זָבָ֗ד בֶּן שִׁמְעָת֙ הָֽעַמּוֹנִ֔ית וִיה֣וֹזָבָ֔ד בֶּן שִׁמְרִ֖ית הַמּוֹאָבִֽית'),
(11705, 14, 'WLC', 'WLC', 'he', '2CH', 24, 27, 'OT', 'וּבָנָ֞יו ורב הַמַּשָּׂ֣א עָלָ֗יו וִיסוֹד֙ בֵּ֣ית הָאֱלֹהִ֔ים הִנָּ֣ם כְּתוּבִ֔ים עַל מִדְרַ֖שׁ סֵ֣פֶר הַמְּלָכִ֑ים וַיִּמְלֹ֛ךְ אֲמַצְיָ֥הוּ בְנ֖וֹ תַּחְתָּֽיו'),
(11706, 14, 'WLC', 'WLC', 'he', '2CH', 25, 1, 'OT', 'בֶּן עֶשְׂרִ֨ים וְחָמֵ֤שׁ שָׁנָה֙ מָלַ֣ךְ אֲמַצְיָ֔הוּ וְעֶשְׂרִ֣ים וָתֵ֨שַׁע֙ שָׁנָ֔ה מָלַ֖ךְ בִּירוּשָׁלִָ֑ם וְשֵׁ֣ם אִמּ֔וֹ יְהוֹעַדָּ֖ן מִירוּשָׁלָֽיִם'),
(11707, 14, 'WLC', 'WLC', 'he', '2CH', 25, 2, 'OT', 'וַיַּ֥עַשׂ הַיָּשָׁ֖ר בְּעֵינֵ֣י יְהוָ֑ה רַ֕ק לֹ֖א בְּלֵבָ֥ב שָׁלֵֽם'),
(11708, 14, 'WLC', 'WLC', 'he', '2CH', 25, 3, 'OT', 'וַיְהִ֕י כַּאֲשֶׁ֛ר חָזְקָ֥ה הַמַּמְלָכָ֖ה עָלָ֑יו וַֽיַּהֲרֹג֙ אֶת עֲבָדָ֔יו הַמַּכִּ֖ים אֶת הַמֶּ֥לֶךְ אָבִֽיו'),
(11709, 14, 'WLC', 'WLC', 'he', '2CH', 25, 4, 'OT', 'וְאֶת בְּנֵיהֶ֖ם לֹ֣א הֵמִ֑ית כִּ֣י כַכָּת֣וּב בַּתּוֹרָ֡ה בְּסֵ֣פֶר מֹשֶׁה֩ אֲשֶׁר צִוָּ֨ה יְהוָ֜ה לֵאמֹ֗ר לֹא יָמ֨וּתוּ אָב֤וֹת עַל בָּנִים֙ וּבָנִים֙ לֹא יָמ֣וּתוּ עַל אָב֔וֹת כִּ֛י אִ֥ישׁ בְּחֶטְא֖וֹ יָמֽוּתוּ'),
(11710, 14, 'WLC', 'WLC', 'he', '2CH', 25, 5, 'OT', 'וַיִּקְבֹּ֤ץ אֲמַצְיָ֨הוּ֙ אֶת יְהוּדָ֔ה וַיַּֽעֲמִידֵ֣ם לְבֵית אָב֗וֹת לְשָׂרֵ֤י הָאֲלָפִים֙ וּלְשָׂרֵ֣י הַמֵּא֔וֹת לְכָל יְהוּדָ֖ה וּבִנְיָמִ֑ן וַֽיִּפְקְדֵ֗ם לְמִבֶּ֨ן עֶשְׂרִ֤ים שָׁנָה֙ וָמַ֔עְלָה וַיִּמְצָאֵ֗ם שְׁלֹשׁ מֵא֨וֹת אֶ֤לֶף בָּחוּר֙ יוֹצֵ֣א צָבָ֔א אֹחֵ֖ז רֹ֥מַח וְצִנָּֽה'),
(11711, 14, 'WLC', 'WLC', 'he', '2CH', 25, 6, 'OT', 'וַיִּשְׂכֹּ֣ר מִיִּשְׂרָאֵ֗ל מֵ֥אָה אֶ֛לֶף גִּבּ֥וֹר חָ֖יִל בְּמֵאָ֥ה כִכַּר כָּֽסֶף'),
(11712, 14, 'WLC', 'WLC', 'he', '2CH', 25, 7, 'OT', 'וְאִ֣ישׁ הָאֱלֹהִ֗ים בָּ֤א אֵלָיו֙ לֵאמֹ֔ר הַמֶּ֕לֶךְ אַל יָבֹ֥א עִמְּךָ֖ צְבָ֣א יִשְׂרָאֵ֑ל כִּ֣י אֵ֤ין יְהוָה֙ עִם יִשְׂרָאֵ֔ל כֹּ֖ל בְּנֵ֥י אֶפְרָֽיִם'),
(11713, 14, 'WLC', 'WLC', 'he', '2CH', 25, 8, 'OT', 'כִּ֚י אִם בֹּ֣א אַתָּ֔ה עֲשֵׂ֖ה חֲזַ֣ק לַמִּלְחָמָ֑ה יַכְשִֽׁילְךָ֤ הָֽאֱלֹהִים֙ לִפְנֵ֣י אוֹיֵ֔ב כִּ֥י יֶשׁ כֹּ֛חַ בֵּאלֹהִ֖ים לַעְז֥וֹר וּלְהַכְשִֽׁיל'),
(11714, 14, 'WLC', 'WLC', 'he', '2CH', 25, 9, 'OT', 'וַיֹּ֤אמֶר אֲמַצְיָ֨הוּ֙ לְאִ֣ישׁ הָאֱלֹהִ֔ים וּמַֽה לַּעֲשׂוֹת֙ לִמְאַ֣ת הַכִּכָּ֔ר אֲשֶׁ֥ר נָתַ֖תִּי לִגְד֣וּד יִשְׂרָאֵ֑ל וַיֹּ֨אמֶר֙ אִ֣ישׁ הָֽאֱלֹהִ֔ים יֵ֚שׁ לַֽיהוָ֔ה לָ֥תֶת לְךָ֖ הַרְבֵּ֥ה מִזֶּֽה'),
(11715, 14, 'WLC', 'WLC', 'he', '2CH', 25, 10, 'OT', 'וַיַּבְדִּילֵ֣ם אֲמַצְיָ֗הוּ לְהַגְּדוּד֙ אֲשֶׁר בָּ֤א אֵלָיו֙ מֵֽאֶפְרַ֔יִם לָלֶ֖כֶת לִמְקוֹמָ֑ם וַיִּ֨חַר אַפָּ֤ם מְאֹד֙ בִּֽיהוּדָ֔ה וַיָּשׁ֥וּבוּ לִמְקוֹמָ֖ם בָּחֳרִי אָֽף'),
(11716, 14, 'WLC', 'WLC', 'he', '2CH', 25, 11, 'OT', 'וַאֲמַצְיָ֨הוּ֙ הִתְחַזַּ֔ק וַיִּנְהַג֙ אֶת עַמּ֔וֹ וַיֵּ֖לֶךְ גֵּ֣יא הַמֶּ֑לַח וַיַּ֥ךְ אֶת בְּנֵי שֵׂעִ֖יר עֲשֶׂ֥רֶת אֲלָפִֽים'),
(11717, 14, 'WLC', 'WLC', 'he', '2CH', 25, 12, 'OT', 'וַעֲשֶׂ֨רֶת אֲלָפִ֜ים חַיִּ֗ים שָׁבוּ֙ בְּנֵ֣י יְהוּדָ֔ה וַיְבִיא֖וּם לְרֹ֣אשׁ הַסָּ֑לַע וַיַּשְׁלִיכ֛וּם מֵֽרֹאשׁ הַסֶּ֖לַע וְכֻלָּ֥ם נִבְקָֽעוּ'),
(11718, 14, 'WLC', 'WLC', 'he', '2CH', 25, 13, 'OT', 'וּבְנֵ֣י הַגְּד֗וּד אֲשֶׁ֨ר הֵשִׁ֤יב אֲמַצְיָ֨הוּ֙ מִלֶּ֤כֶת עִמּוֹ֙ לַמִּלְחָמָ֔ה וַֽיִּפְשְׁטוּ֙ בְּעָרֵ֣י יְהוּדָ֔ה מִשֹּׁמְר֖וֹן וְעַד בֵּ֣ית חוֹר֑וֹן וַיַּכּ֤וּ מֵהֶם֙ שְׁלֹ֣שֶׁת אֲלָפִ֔ים וַיָּבֹ֖זּוּ בִּזָּ֥ה רַבָּֽה'),
(11719, 14, 'WLC', 'WLC', 'he', '2CH', 25, 14, 'OT', 'וַיְהִ֗י אַחֲרֵ֨י ב֤וֹא אֲמַצְיָ֨הוּ֙ מֵֽהַכּ֣וֹת אֶת אֲדוֹמִ֔ים וַיָּבֵ֗א אֶת אֱלֹהֵי֙ בְּנֵ֣י שֵׂעִ֔יר וַיַּֽעֲמִידֵ֥ם ל֖וֹ לֵאלֹהִ֑ים וְלִפְנֵיהֶ֥ם יִֽשְׁתַּחֲוֶ֖ה וְלָהֶ֥ם יְקַטֵּֽר'),
(11720, 14, 'WLC', 'WLC', 'he', '2CH', 25, 15, 'OT', 'וַיִּֽחַר אַ֥ף יְהוָ֖ה בַּאֲמַצְיָ֑הוּ וַיִּשְׁלַ֤ח אֵלָיו֙ נָבִ֔יא וַיֹּ֣אמֶר ל֗וֹ לָ֤מָּה דָרַ֨שְׁתָּ֙ אֶת אֱלֹהֵ֣י הָעָ֔ם אֲשֶׁ֛ר לֹא הִצִּ֥ילוּ אֶת עַמָּ֖ם מִיָּדֶֽךָ'),
(11721, 14, 'WLC', 'WLC', 'he', '2CH', 25, 16, 'OT', 'וַיְהִ֣י בְּדַבְּר֣וֹ אֵלָ֗יו וַיֹּ֤אמֶר לוֹ֙ הַלְיוֹעֵ֤ץ לַמֶּ֨לֶךְ֙ נְתַנּ֔וּךָ חֲדַל לְךָ֖ לָ֣מָּה יַכּ֑וּךָ וַיֶּחְדַּ֣ל הַנָּבִ֗יא וַיֹּ֨אמֶר֙ יָדַ֗עְתִּי כִּֽי יָעַ֤ץ אֱלֹהִים֙ לְהַשְׁחִיתֶ֔ךָ כִּֽי עָשִׂ֣יתָ זֹּ֔את וְלֹ֥א שָׁמַ֖עְתָּ לַעֲצָתִֽי'),
(11722, 14, 'WLC', 'WLC', 'he', '2CH', 25, 17, 'OT', 'וַיִּוָּעַ֗ץ אֲמַצְיָ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה וַ֠יִּשְׁלַח אֶל יוֹאָ֨שׁ בֶּן יְהוֹאָחָ֧ז בֶּן יֵה֛וּא מֶ֥לֶךְ יִשְׂרָאֵ֖ל לֵאמֹ֑ר לך נִתְרָאֶ֥ה פָנִֽים'),
(11723, 14, 'WLC', 'WLC', 'he', '2CH', 25, 18, 'OT', 'וַיִּשְׁלַ֞ח יוֹאָ֣שׁ מֶֽלֶךְ יִשְׂרָאֵ֗ל אֶל אֲמַצְיָ֣הוּ מֶֽלֶךְ יְהוּדָה֮ לֵאמֹר֒ הַח֜וֹחַ אֲשֶׁ֣ר בַּלְּבָנ֗וֹן שָׁ֠לַח אֶל הָאֶ֜רֶז אֲשֶׁ֤ר בַּלְּבָנוֹן֙ לֵאמֹ֔ר תְּנָֽה אֶת בִּתְּךָ֥ לִבְנִ֖י לְאִשָּׁ֑ה וַֽתַּעֲבֹ֞ר חַיַּ֤ת הַשָּׂדֶה֙ אֲשֶׁ֣ר בַּלְּבָנ֔וֹן וַתִּרְמֹ֖ס אֶת הַחֽוֹחַ'),
(11724, 14, 'WLC', 'WLC', 'he', '2CH', 25, 19, 'OT', 'אָמַ֗רְתָּ הִנֵּ֤ה הִכִּ֨יתָ֙ אֶת אֱד֔וֹם וּנְשָׂאֲךָ֥ לִבְּךָ֖ לְהַכְבִּ֑יד עַתָּה֙ שְׁבָ֣ה בְּבֵיתֶ֔ךָ לָ֤מָּה תִתְגָּרֶה֙ בְּרָעָ֔ה וְנָ֣פַלְתָּ֔ אַתָּ֖ה וִיהוּדָ֥ה עִמָּֽךְ'),
(11725, 14, 'WLC', 'WLC', 'he', '2CH', 25, 20, 'OT', 'וְלֹא שָׁמַ֣ע אֲמַצְיָ֔הוּ כִּ֤י מֵהָֽאֱלֹהִים֙ הִ֔יא לְמַ֖עַן תִּתָּ֣ם בְּיָ֑ד כִּ֣י דָֽרְשׁ֔וּ אֵ֖ת אֱלֹהֵ֥י אֱדֽוֹם'),
(11726, 14, 'WLC', 'WLC', 'he', '2CH', 25, 21, 'OT', 'וַיַּ֨עַל יוֹאָ֤שׁ מֶֽלֶךְ יִשְׂרָאֵל֙ וַיִּתְרָא֣וּ פָנִ֔ים ה֖וּא וַאֲמַצְיָ֣הוּ מֶֽלֶךְ יְהוּדָ֑ה בְּבֵ֥ית שֶׁ֖מֶשׁ אֲשֶׁ֥ר לִיהוּדָֽה'),
(11727, 14, 'WLC', 'WLC', 'he', '2CH', 25, 22, 'OT', 'וַיִּנָּ֥גֶף יְהוּדָ֖ה לִפְנֵ֣י יִשְׂרָאֵ֑ל וַיָּנֻ֖סוּ אִ֥ישׁ לְאֹהָלָֽיו'),
(11728, 14, 'WLC', 'WLC', 'he', '2CH', 25, 23, 'OT', 'וְאֵת֩ אֲמַצְיָ֨הוּ מֶֽלֶךְ יְהוּדָ֜ה בֶּן יוֹאָ֣שׁ בֶּן יְהוֹאָחָ֗ז תָּפַ֛שׂ יוֹאָ֥שׁ מֶֽלֶךְ יִשְׂרָאֵ֖ל בְּבֵ֣ית שָׁ֑מֶשׁ וַיְבִיאֵ֨הוּ֙ יְר֣וּשָׁלִַ֔ם וַיִּפְרֹ֞ץ בְּחוֹמַ֣ת יְרוּשָׁלִַ֗ם מִשַּׁ֤עַר אֶפְרַ֨יִם֙ עַד שַׁ֣עַר הַפּוֹנֶ֔ה אַרְבַּ֥ע מֵא֖וֹת אַמָּֽה'),
(11729, 14, 'WLC', 'WLC', 'he', '2CH', 25, 24, 'OT', 'וְכָֽל הַזָּהָ֣ב וְהַכֶּ֡סֶף וְאֵ֣ת כָּל הַ֠כֵּלִים הַנִּמְצְאִ֨ים בְּבֵית הָאֱלֹהִ֜ים עִם עֹבֵ֣ד אֱד֗וֹם וְאֶת אֹצְרוֹת֙ בֵּ֣ית הַמֶּ֔לֶךְ וְאֵ֖ת בְּנֵ֣י הַתַּֽעֲרֻב֑וֹת וַיָּ֖שָׁב שֹׁמְרֽוֹן'),
(11730, 14, 'WLC', 'WLC', 'he', '2CH', 25, 25, 'OT', 'וַיְחִ֨י אֲמַצְיָ֤הוּ בֶן יוֹאָשׁ֙ מֶ֣לֶךְ יְהוּדָ֔ה אַחֲרֵ֣י מ֔וֹת יוֹאָ֥שׁ בֶּן יְהוֹאָחָ֖ז מֶ֣לֶךְ יִשְׂרָאֵ֑ל חֲמֵ֥שׁ עֶשְׂרֵ֖ה שָׁנָֽה'),
(11731, 14, 'WLC', 'WLC', 'he', '2CH', 25, 26, 'OT', 'וְיֶ֨תֶר֙ דִּבְרֵ֣י אֲמַצְיָ֔הוּ הָרִאשֹׁנִ֖ים וְהָאַחֲרוֹנִ֑ים הֲלֹא֙ הִנָּ֣ם כְּתוּבִ֔ים עַל סֵ֥פֶר מַלְכֵי יְהוּדָ֖ה וְיִשְׂרָאֵֽל'),
(11732, 14, 'WLC', 'WLC', 'he', '2CH', 25, 27, 'OT', 'וּמֵעֵ֗ת אֲשֶׁר סָ֤ר אֲמַצְיָ֨הוּ֙ מֵאַחֲרֵ֣י יְהוָ֔ה וַיִּקְשְׁר֨וּ עָלָ֥יו קֶ֛שֶׁר בִּירוּשָׁלִַ֖ם וַיָּ֣נָס לָכִ֑ישָׁה וַיִּשְׁלְח֤וּ אַחֲרָיו֙ לָכִ֔ישָׁה וַיְמִיתֻ֖הוּ שָֽׁם'),
