(11795, 14, 'WLC', 'WLC', 'he', '2CH', 29, 3, 'OT', 'ה֣וּא בַשָּׁנָה֩ הָרִאשׁוֹנָ֨ה לְמָלְכ֜וֹ בַּחֹ֣דֶשׁ הָרִאשׁ֗וֹן פָּתַ֛ח אֶת דַּלְת֥וֹת בֵּית יְהוָ֖ה וַֽיְחַזְּקֵֽם'),
(11796, 14, 'WLC', 'WLC', 'he', '2CH', 29, 4, 'OT', 'וַיָּבֵ֥א אֶת הַכֹּהֲנִ֖ים וְאֶת הַלְוִיִּ֑ם וַיַּֽאַסְפֵ֖ם לִרְח֥וֹב הַמִּזְרָֽח'),
(11797, 14, 'WLC', 'WLC', 'he', '2CH', 29, 5, 'OT', 'וַיֹּ֥אמֶר לָהֶ֖ם שְׁמָע֣וּנִי הַלְוִיִּ֑ם עַתָּ֣ה הִֽתְקַדְּשׁ֗וּ וְקַדְּשׁוּ֙ אֶת בֵּ֤ית יְהוָה֙ אֱלֹהֵ֣י אֲבֹתֵיכֶ֔ם וְהוֹצִ֥יאוּ אֶת הַנִּדָּ֖ה מִן הַקֹּֽדֶשׁ'),
(11798, 14, 'WLC', 'WLC', 'he', '2CH', 29, 6, 'OT', 'כִּֽי מָעֲל֣וּ אֲבֹתֵ֗ינוּ וְעָשׂ֥וּ הָרַ֛ע בְּעֵינֵ֥י יְהוָֽה אֱלֹהֵ֖ינוּ וַיַּֽעַזְבֻ֑הוּ וַיַּסֵּ֧בּוּ פְנֵיהֶ֛ם מִמִּשְׁכַּ֥ן יְהוָ֖ה וַיִּתְּנוּ עֹֽרֶף'),
(11799, 14, 'WLC', 'WLC', 'he', '2CH', 29, 7, 'OT', 'גַּ֣ם סָֽגְר֞וּ דַּלְת֣וֹת הָאוּלָ֗ם וַיְכַבּוּ֙ אֶת הַנֵּר֔וֹת וּקְטֹ֖רֶת לֹ֣א הִקְטִ֑ירוּ וְעֹלָה֙ לֹא הֶעֱל֣וּ בַקֹּ֔דֶשׁ לֵאלֹהֵ֖י יִשְׂרָאֵֽל'),
(11800, 14, 'WLC', 'WLC', 'he', '2CH', 29, 8, 'OT', 'וַיְהִי֙ קֶ֣צֶף יְהוָ֔ה עַל יְהוּדָ֖ה וִירוּשָׁלִָ֑ם וַיִּתְּנֵ֤ם לזועה לְשַׁמָּ֣ה וְלִשְׁרֵקָ֔ה כַּאֲשֶׁ֛ר אַתֶּ֥ם רֹאִ֖ים בְּעֵינֵיכֶֽם'),
(11801, 14, 'WLC', 'WLC', 'he', '2CH', 29, 9, 'OT', 'וְהִנֵּ֛ה נָפְל֥וּ אֲבוֹתֵ֖ינוּ בֶּחָ֑רֶב וּבָנֵ֨ינוּ וּבְנוֹתֵ֧ינוּ וְנָשֵׁ֛ינוּ בַּשְּׁבִ֖י עַל זֹֽאת'),
(11802, 14, 'WLC', 'WLC', 'he', '2CH', 29, 10, 'OT', 'עַתָּה֙ עִם לְבָבִ֔י לִכְר֣וֹת בְּרִ֔ית לַיהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְיָשֹׁ֥ב מִמֶּ֖נּוּ חֲר֥וֹן אַפּֽוֹ'),
(11803, 14, 'WLC', 'WLC', 'he', '2CH', 29, 11, 'OT', 'בָּנַ֕י עַתָּ֖ה אַל תִּשָּׁל֑וּ כִּֽי בָכֶ֞ם בָּחַ֣ר יְהוָ֗ה לַעֲמֹ֤ד לְפָנָיו֙ לְשָׁ֣רְת֔וֹ וְלִהְי֥וֹת ל֖וֹ מְשָׁרְתִ֥ים וּמַקְטִרִֽים'),
(11804, 14, 'WLC', 'WLC', 'he', '2CH', 29, 12, 'OT', 'וַיָּקֻ֣מוּ הַ֠לְוִיִּם מַ֣חַת בֶּן עֲמָשַׂ֞י וְיוֹאֵ֣ל בֶּן עֲזַרְיָהוּ֮ מִן בְּנֵ֣י הַקְּהָתִי֒ וּמִן בְּנֵ֣י מְרָרִ֔י קִ֚ישׁ בֶּן עַבְדִּ֔י וַעֲזַרְיָ֖הוּ בֶּן יְהַלֶּלְאֵ֑ל וּמִן הַגֵּ֣רְשֻׁנִּ֔י יוֹאָח֙ בֶּן זִמָּ֔ה וְעֵ֖דֶן בֶּן יוֹאָֽח'),
(11805, 14, 'WLC', 'WLC', 'he', '2CH', 29, 13, 'OT', 'וּמִן בְּנֵי֙ אֱלִ֣יצָפָ֔ן שִׁמְרִ֖י ויעואל וּמִן בְּנֵ֣י אָסָ֔ף זְכַרְיָ֖הוּ וּמַתַּנְיָֽהוּ'),
(11806, 14, 'WLC', 'WLC', 'he', '2CH', 29, 14, 'OT', 'וּמִן בְּנֵ֥י הֵימָ֖ן יחואל וְשִׁמְעִ֑י וּמִן בְּנֵ֣י יְדוּת֔וּן שְׁמַֽעְיָ֖ה וְעֻזִּיאֵֽל'),
(11807, 14, 'WLC', 'WLC', 'he', '2CH', 29, 15, 'OT', 'וַיַּֽאַסְפ֤וּ אֶת אֲחֵיהֶם֙ וַיִּֽתְקַדְּשׁ֔וּ וַיָּבֹ֥אוּ כְמִצְוַת הַמֶּ֖לֶךְ בְּדִבְרֵ֣י יְהוָ֑ה לְטַהֵ֖ר בֵּ֥ית יְהוָֽה'),
(11808, 14, 'WLC', 'WLC', 'he', '2CH', 29, 16, 'OT', 'וַיָּבֹ֣אוּ הַ֠כֹּהֲנִים לִפְנִ֣ימָה בֵית יְהוָה֮ לְטַהֵר֒ וַיּוֹצִ֗יאוּ אֵ֤ת כָּל הַטֻּמְאָה֙ אֲשֶׁ֤ר מָֽצְאוּ֙ בְּהֵיכַ֣ל יְהוָ֔ה לַחֲצַ֖ר בֵּ֣ית יְהוָ֑ה וַֽיְקַבְּלוּ֙ הַלְוִיִּ֔ם לְהוֹצִ֥יא לְנַֽחַל קִדְר֖וֹן חֽוּצָה'),
(11809, 14, 'WLC', 'WLC', 'he', '2CH', 29, 17, 'OT', 'וַ֠יָּחֵלּוּ בְּאֶחָ֞ד לַחֹ֣דֶשׁ הָרִאשׁוֹן֮ לְקַדֵּשׁ֒ וּבְי֧וֹם שְׁמוֹנָ֣ה לַחֹ֗דֶשׁ בָּ֚אוּ לְאוּלָ֣ם יְהוָ֔ה וַיְקַדְּשׁ֥וּ אֶת בֵּית יְהוָ֖ה לְיָמִ֣ים שְׁמוֹנָ֑ה וּבְי֨וֹם שִׁשָּׁ֥ה עָשָׂ֛ר לַחֹ֥דֶשׁ הָרִאשׁ֖וֹן כִּלּֽוּ'),
(11810, 14, 'WLC', 'WLC', 'he', '2CH', 29, 18, 'OT', 'וַיָּב֤וֹאוּ פְנִ֨ימָה֙ אֶל חִזְקִיָּ֣הוּ הַמֶּ֔לֶךְ וַיֹּ֣אמְר֔וּ טִהַ֖רְנוּ אֶת כָּל בֵּ֣ית יְהוָ֑ה אֶת מִזְבַּ֤ח הָעוֹלָה֙ וְאֶת כָּל כֵּלָ֔יו וְאֶת שֻׁלְחַ֥ן הַֽמַּעֲרֶ֖כֶת וְאֶת כָּל כֵּלָֽיו'),
(11811, 14, 'WLC', 'WLC', 'he', '2CH', 29, 19, 'OT', 'וְאֵ֣ת כָּל הַכֵּלִ֗ים אֲשֶׁ֣ר הִזְנִיחַ֩ הַמֶּ֨לֶךְ אָחָ֧ז בְּמַלְכוּת֛וֹ בְּמַעֲל֖וֹ הֵכַ֣נּוּ וְהִקְדָּ֑שְׁנוּ וְהִנָּ֕ם לִפְנֵ֖י מִזְבַּ֥ח יְהוָֽה'),
(11812, 14, 'WLC', 'WLC', 'he', '2CH', 29, 20, 'OT', 'וַיַּשְׁכֵּם֙ יְחִזְקִיָּ֣הוּ הַמֶּ֔לֶךְ וַיֶּאֱסֹ֕ף אֵ֖ת שָׂרֵ֣י הָעִ֑יר וַיַּ֖עַל בֵּ֥ית יְהוָֽה'),
(11813, 14, 'WLC', 'WLC', 'he', '2CH', 29, 21, 'OT', 'וַיָּבִ֣יאוּ פָרִים שִׁבְעָה֩ וְאֵילִ֨ים שִׁבְעָ֜ה וּכְבָשִׂ֣ים שִׁבְעָ֗ה וּצְפִירֵ֨י עִזִּ֤ים שִׁבְעָה֙ לְחַטָּ֔את עַל הַמַּמְלָכָ֥ה וְעַל הַמִּקְדָּ֖שׁ וְעַל יְהוּדָ֑ה וַיֹּ֗אמֶר לִבְנֵ֤י אַהֲרֹן֙ הַכֹּ֣הֲנִ֔ים לְהַעֲל֖וֹת עַל מִזְבַּ֥ח יְהוָֽה'),
(11814, 14, 'WLC', 'WLC', 'he', '2CH', 29, 22, 'OT', 'וַֽיִּשְׁחֲטוּ֙ הַבָּקָ֔ר וַיְקַבְּל֤וּ הַכֹּֽהֲנִים֙ אֶת הַדָּ֔ם וַֽיִּזְרְק֖וּ הַמִּזְבֵּ֑חָה וַיִּשְׁחֲט֣וּ הָאֵלִ֗ים וַיִּזְרְק֤וּ הַדָּם֙ הַמִּזְבֵּ֔חָה וַֽיִּשְׁחֲטוּ֙ הַכְּבָשִׂ֔ים וַיִּזְרְק֥וּ הַדָּ֖ם הַמִּזְבֵּֽחָה'),
(11815, 14, 'WLC', 'WLC', 'he', '2CH', 29, 23, 'OT', 'וַיַּגִּ֨ישׁוּ֙ אֶת שְׂעִירֵ֣י הַֽחַטָּ֔את לִפְנֵ֥י הַמֶּ֖לֶךְ וְהַקָּהָ֑ל וַיִּסְמְכ֥וּ יְדֵיהֶ֖ם עֲלֵיהֶֽם'),
(11816, 14, 'WLC', 'WLC', 'he', '2CH', 29, 24, 'OT', 'וַיִּשְׁחָטוּם֙ הַכֹּ֣הֲנִ֔ים וַֽיְחַטְּא֤וּ אֶת דָּמָם֙ הַמִּזְבֵּ֔חָה לְכַפֵּ֖ר עַל כָּל יִשְׂרָאֵ֑ל כִּ֤י לְכָל יִשְׂרָאֵל֙ אָמַ֣ר הַמֶּ֔לֶךְ הָעוֹלָ֖ה וְהַחַטָּֽאת'),
(11817, 14, 'WLC', 'WLC', 'he', '2CH', 29, 25, 'OT', 'וַיַּֽעֲמֵ֨ד אֶת הַלְוִיִּ֜ם בֵּ֣ית יְהוָ֗ה בִּמְצִלְתַּ֨יִם֙ בִּנְבָלִ֣ים וּבְכִנֹּר֔וֹת בְּמִצְוַ֥ת דָּוִ֛יד וְגָ֥ד חֹזֵֽה הַמֶּ֖לֶךְ וְנָתָ֣ן הַנָּבִ֑יא כִּ֧י בְיַד יְהוָ֛ה הַמִּצְוָ֖ה בְּיַד נְבִיאָֽיו'),
(11818, 14, 'WLC', 'WLC', 'he', '2CH', 29, 26, 'OT', 'וַיַּֽעַמְד֤וּ הַלְוִיִּם֙ בִּכְלֵ֣י דָוִ֔יד וְהַכֹּהֲנִ֖ים בַּחֲצֹצְרֽוֹת'),
(11819, 14, 'WLC', 'WLC', 'he', '2CH', 29, 27, 'OT', 'וַיֹּ֨אמֶר֙ חִזְקִיָּ֔הוּ לְהַעֲל֥וֹת הָעֹלָ֖ה לְהַמִּזְבֵּ֑חַ וּבְעֵ֞ת הֵחֵ֣ל הָֽעוֹלָ֗ה הֵחֵ֤ל שִׁיר יְהוָה֙ וְהַחֲצֹ֣צְר֔וֹת וְעַ֨ל יְדֵ֔י כְּלֵ֖י דָּוִ֥יד מֶֽלֶךְ יִשְׂרָאֵֽל'),
(11820, 14, 'WLC', 'WLC', 'he', '2CH', 29, 28, 'OT', 'וְכָל הַקָּהָל֙ מִֽשְׁתַּחֲוִ֔ים וְהַשִּׁ֣יר מְשׁוֹרֵ֔ר וְהַחֲצֹצְר֖וֹת מחצצרים הַכֹּ֕ל עַ֖ד לִכְל֥וֹת הָעֹלָֽה'),
(11821, 14, 'WLC', 'WLC', 'he', '2CH', 29, 29, 'OT', 'וּכְכַלּ֖וֹת לְהַעֲל֑וֹת כָּרְע֗וּ הַמֶּ֛לֶךְ וְכָֽל הַנִּמְצְאִ֥ים אִתּ֖וֹ וַיִּֽשְׁתַּחֲוֽוּ'),
(11822, 14, 'WLC', 'WLC', 'he', '2CH', 29, 30, 'OT', 'וַ֠יֹּאמֶר יְחִזְקִיָּ֨הוּ הַמֶּ֤לֶךְ וְהַשָּׂרִים֙ לַלְוִיִּ֔ם לְהַלֵּל֙ לַֽיהוָ֔ה בְּדִבְרֵ֥י דָוִ֖יד וְאָסָ֣ף הַחֹזֶ֑ה וַֽיְהַלְלוּ֙ עַד לְשִׂמְחָ֔ה וַֽיִּקְּד֖וּ וַיִּֽשְׁתַּחֲוֽוּ'),
(11823, 14, 'WLC', 'WLC', 'he', '2CH', 29, 31, 'OT', 'וַיַּ֨עַן יְחִזְקִיָּ֜הוּ וַיֹּ֗אמֶר עַתָּ֨ה מִלֵּאתֶ֤ם יֶדְכֶם֙ לַיהוָ֔ה גֹּ֧שׁוּ וְהָבִ֛יאוּ זְבָחִ֥ים וְתוֹד֖וֹת לְבֵ֣ית יְהוָ֑ה וַיָּבִ֤יאוּ הַקָּהָל֙ זְבָחִ֣ים וְתוֹד֔וֹת וְכָל נְדִ֥יב לֵ֖ב עֹלֽוֹת'),
(11824, 14, 'WLC', 'WLC', 'he', '2CH', 29, 32, 'OT', 'וַיְהִ֞י מִסְפַּ֣ר הָעֹלָה֮ אֲשֶׁ֣ר הֵבִ֣יאוּ הַקָּהָל֒ בָּקָ֣ר שִׁבְעִ֔ים אֵילִ֥ים מֵאָ֖ה כְּבָשִׂ֣ים מָאתָ֑יִם לְעֹלָ֥ה לַיהוָ֖ה כָּל אֵֽלֶּה'),
(11825, 14, 'WLC', 'WLC', 'he', '2CH', 29, 33, 'OT', 'וְֽהַקֳּדָשִׁ֑ים בָּקָר֙ שֵׁ֣שׁ מֵא֔וֹת וְצֹ֖אן שְׁלֹ֥שֶׁת אֲלָפִֽים'),
(11826, 14, 'WLC', 'WLC', 'he', '2CH', 29, 34, 'OT', 'רַ֤ק הַכֹּֽהֲנִים֙ הָי֣וּ לִמְעָ֔ט וְלֹ֣א יָֽכְל֔וּ לְהַפְשִׁ֖יט אֶת כָּל הָעֹל֑וֹת וַֽיְּחַזְּק֞וּם אֲחֵיהֶ֣ם הַלְוִיִּ֗ם עַד כְּל֤וֹת הַמְּלָאכָה֙ וְעַ֣ד יִתְקַדְּשׁ֣וּ הַכֹּֽהֲנִ֔ים כִּ֤י הַלְוִיִּם֙ יִשְׁרֵ֣י לֵבָ֔ב לְהִתְקַדֵּ֖שׁ מֵֽהַכֹּהֲנִֽים'),
(11827, 14, 'WLC', 'WLC', 'he', '2CH', 29, 35, 'OT', 'וְגַם עֹלָ֨ה לָרֹ֜ב בְּחֶלְבֵ֧י הַשְּׁלָמִ֛ים וּבַנְּסָכִ֖ים לָעֹלָ֑ה וַתִּכּ֖וֹן עֲבוֹדַ֥ת בֵּית יְהוָֽה'),
(11828, 14, 'WLC', 'WLC', 'he', '2CH', 29, 36, 'OT', 'וַיִּשְׂמַ֤ח יְחִזְקִיָּ֨הוּ֙ וְכָל הָעָ֔ם עַ֛ל הַהֵכִ֥ין הָאֱלֹהִ֖ים לָעָ֑ם כִּ֥י בְּפִתְאֹ֖ם הָיָ֥ה הַדָּבָֽר'),
(11829, 14, 'WLC', 'WLC', 'he', '2CH', 30, 1, 'OT', 'וַיִּשְׁלַ֨ח יְחִזְקִיָּ֜הוּ עַל כָּל יִשְׂרָאֵ֣ל וִֽיהוּדָ֗ה וְגַֽם אִגְּרוֹת֙ כָּתַב֙ עַל אֶפְרַ֣יִם וּמְנַשֶּׁ֔ה לָב֥וֹא לְבֵית יְהוָ֖ה בִּֽירוּשָׁלִָ֑ם לַעֲשׂ֣וֹת פֶּ֔סַח לַיהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל'),
(11830, 14, 'WLC', 'WLC', 'he', '2CH', 30, 2, 'OT', 'וַיִּוָּעַ֨ץ הַמֶּ֧לֶךְ וְשָׂרָ֛יו וְכָל הַקָּהָ֖ל בִּירוּשָׁלִָ֑ם לַעֲשׂ֥וֹת הַפֶּ֖סַח בַּחֹ֥דֶשׁ הַשֵּׁנִֽי'),
(11831, 14, 'WLC', 'WLC', 'he', '2CH', 30, 3, 'OT', 'כִּ֣י לֹ֧א יָכְל֛וּ לַעֲשֹׂת֖וֹ בָּעֵ֣ת הַהִ֑יא כִּ֤י הַכֹּהֲנִים֙ לֹֽא הִתְקַדְּשׁ֣וּ לְמַ דַּ֔י וְהָעָ֖ם לֹא נֶאֶסְפ֥וּ לִֽירוּשָׁלִָֽם'),
(11832, 14, 'WLC', 'WLC', 'he', '2CH', 30, 4, 'OT', 'וַיִּישַׁ֥ר הַדָּבָ֖ר בְּעֵינֵ֣י הַמֶּ֑לֶךְ וּבְעֵינֵ֖י כָּל הַקָּהָֽל'),
(11833, 14, 'WLC', 'WLC', 'he', '2CH', 30, 5, 'OT', 'וַיַּֽעֲמִ֣ידוּ דָבָ֗ר לְהַעֲבִ֨יר ק֤וֹל בְּכָל יִשְׂרָאֵל֙ מִבְּאֵֽר שֶׁ֣בַע וְעַד דָּ֔ן לָב֞וֹא לַעֲשׂ֥וֹת פֶּ֛סַח לַיהוָ֥ה אֱלֹהֵֽי יִשְׂרָאֵ֖ל בִּירוּשָׁלִָ֑ם כִּ֣י לֹ֥א לָרֹ֛ב עָשׂ֖וּ כַּכָּתֽוּב'),
(11834, 14, 'WLC', 'WLC', 'he', '2CH', 30, 6, 'OT', 'וַיֵּלְכוּ֩ הָרָצִ֨ים בָּֽאִגְּר֜וֹת מִיַּ֧ד הַמֶּ֣לֶךְ וְשָׂרָ֗יו בְּכָל יִשְׂרָאֵל֙ וִֽיהוּדָ֔ה וּכְמִצְוַ֥ת הַמֶּ֖לֶךְ לֵאמֹ֑ר בְּנֵ֣י יִשְׂרָאֵ֗ל שׁ֚וּבוּ אֶל יְהוָ֗ה אֱלֹהֵי֙ אַבְרָהָם֙ יִצְחָ֣ק וְיִשְׂרָאֵ֔ל וְיָשֹׁב֙ אֶל הַפְּלֵיטָ֔ה הַנִּשְׁאֶ֣רֶת לָכֶ֔ם מִכַּ֖ף מַלְכֵ֥י אַשּֽׁוּר'),
(11835, 14, 'WLC', 'WLC', 'he', '2CH', 30, 7, 'OT', 'וְאַל תִּֽהְי֗וּ כַּאֲבֽוֹתֵיכֶם֙ וְכַ֣אֲחֵיכֶ֔ם אֲשֶׁ֣ר מָעֲל֔וּ בַּיהוָ֖ה אֱלֹהֵ֣י אֲבוֹתֵיהֶ֑ם וַיִּתְּנֵ֣ם לְשַׁמָּ֔ה כַּאֲשֶׁ֖ר אַתֶּ֥ם רֹאִֽים'),
(11836, 14, 'WLC', 'WLC', 'he', '2CH', 30, 8, 'OT', 'עַתָּ֕ה אַל תַּקְשׁ֥וּ עָרְפְּכֶ֖ם כַּאֲבוֹתֵיכֶ֑ם תְּנוּ יָ֣ד לַיהוָ֗ה וּבֹ֤אוּ לְמִקְדָּשׁוֹ֙ אֲשֶׁ֣ר הִקְדִּ֣ישׁ לְעוֹלָ֔ם וְעִבְדוּ֙ אֶת יְהוָ֣ה אֱלֹהֵיכֶ֔ם וְיָשֹׁ֥ב מִכֶּ֖ם חֲר֥וֹן אַפּֽוֹ'),
(11837, 14, 'WLC', 'WLC', 'he', '2CH', 30, 9, 'OT', 'כִּ֣י בְשׁוּבְכֶ֞ם עַל יְהוָ֗ה אֲחֵיכֶ֨ם וּבְנֵיכֶ֤ם לְרַחֲמִים֙ לִפְנֵ֣י שֽׁוֹבֵיהֶ֔ם וְלָשׁ֖וּב לָאָ֣רֶץ הַזֹּ֑את כִּֽי חַנּ֤וּן וְרַחוּם֙ יְהוָ֣ה אֱלֹהֵיכֶ֔ם וְלֹא יָסִ֤יר פָּנִים֙ מִכֶּ֔ם אִם תָּשׁ֖וּבוּ אֵלָֽיו'),
(11838, 14, 'WLC', 'WLC', 'he', '2CH', 30, 10, 'OT', 'וַיִּֽהְי֨וּ הָרָצִ֜ים עֹבְרִ֨ים מֵעִ֧יר לָעִ֛יר בְּאֶֽרֶץ אֶפְרַ֥יִם וּמְנַשֶּׁ֖ה וְעַד זְבֻל֑וּן וַיִּֽהְיוּ֙ מַשְׂחִיקִ֣ים עֲלֵיהֶ֔ם וּמַלְעִגִ֖ים בָּֽם'),
(11839, 14, 'WLC', 'WLC', 'he', '2CH', 30, 11, 'OT', 'אַךְ אֲנָשִׁ֛ים מֵאָשֵׁ֥ר וּמְנַשֶּׁ֖ה וּמִזְּבֻל֑וּן נִֽכְנְע֔וּ וַיָּבֹ֖אוּ לִירוּשָׁלִָֽם'),
(11840, 14, 'WLC', 'WLC', 'he', '2CH', 30, 12, 'OT', 'גַּ֣ם בִּיהוּדָ֗ה הָֽיְתָה֙ יַ֣ד הָאֱלֹהִ֔ים לָתֵ֥ת לָהֶ֖ם לֵ֣ב אֶחָ֑ד לַעֲשׂ֞וֹת מִצְוַ֥ת הַמֶּ֛לֶךְ וְהַשָּׂרִ֖ים בִּדְבַ֥ר יְהוָֽה'),
(11841, 14, 'WLC', 'WLC', 'he', '2CH', 30, 13, 'OT', 'וַיֵּֽאָסְפ֤וּ יְרוּשָׁלִַ֨ם֙ עַם רָ֔ב לַעֲשׂ֛וֹת אֶת חַ֥ג הַמַּצּ֖וֹת בַּחֹ֣דֶשׁ הַשֵּׁנִ֑י קָהָ֖ל לָרֹ֥ב מְאֹֽד'),
(11842, 14, 'WLC', 'WLC', 'he', '2CH', 30, 14, 'OT', 'וַיָּקֻ֕מוּ וַיָּסִ֨ירוּ֙ אֶת הַֽמִּזְבְּח֔וֹת אֲשֶׁ֖ר בִּירוּשָׁלִָ֑ם וְאֵ֤ת כָּל הַֽמְקַטְּרוֹת֙ הֵסִ֔ירוּ וַיַּשְׁלִ֖יכוּ לְנַ֥חַל קִדְרֽוֹן'),
(11843, 14, 'WLC', 'WLC', 'he', '2CH', 30, 15, 'OT', 'וַיִּשְׁחֲט֣וּ הַפֶּ֔סַח בְּאַרְבָּעָ֥ה עָשָׂ֖ר לַחֹ֣דֶשׁ הַשֵּׁנִ֑י וְהַכֹּהֲנִ֨ים וְהַלְוִיִּ֤ם נִכְלְמוּ֙ וַיִּֽתְקַדְּשׁ֔וּ וַיָּבִ֥יאוּ עֹל֖וֹת בֵּ֥ית יְהוָֽה'),
(11844, 14, 'WLC', 'WLC', 'he', '2CH', 30, 16, 'OT', 'וַיַּֽעַמְד֤וּ עַל עָמְדָם֙ כְּמִשְׁפָּטָ֔ם כְּתוֹרַ֖ת מֹשֶׁ֣ה אִישׁ הָאֱלֹהִ֑ים הַכֹּֽהֲנִים֙ זֹרְקִ֣ים אֶת הַדָּ֔ם מִיַּ֖ד הַלְוִיִּֽם'),
(11845, 14, 'WLC', 'WLC', 'he', '2CH', 30, 17, 'OT', 'כִּי רַבַּ֥ת בַּקָּהָ֖ל אֲשֶׁ֣ר לֹא הִתְקַדָּ֑שׁוּ וְהַלְוִיִּ֞ם עַל שְׁחִיטַ֣ת הַפְּסָחִ֗ים לְכֹל֙ לֹ֣א טָה֔וֹר לְהַקְדִּ֖ישׁ לַיהוָֽה'),
(11846, 14, 'WLC', 'WLC', 'he', '2CH', 30, 18, 'OT', 'כִּ֣י מַרְבִּ֣ית הָעָ֡ם רַ֠בַּת מֵֽאֶפְרַ֨יִם וּמְנַשֶּׁ֜ה יִשָּׂשכָ֤ר וּזְבֻלוּן֙ לֹ֣א הִטֶּהָ֔רוּ כִּֽי אָכְל֥וּ אֶת הַפֶּ֖סַח בְּלֹ֣א כַכָּת֑וּב כִּי֩ הִתְפַּלֵּ֨ל יְחִזְקִיָּ֤הוּ עֲלֵיהֶם֙ לֵאמֹ֔ר יְהוָ֥ה הַטּ֖וֹב יְכַפֵּ֥ר בְּעַֽד'),
(11847, 14, 'WLC', 'WLC', 'he', '2CH', 30, 19, 'OT', 'כָּל לְבָב֣וֹ הֵכִ֔ין לִדְר֛וֹשׁ הָאֱלֹהִ֥ים יְהוָ֖ה אֱלֹהֵ֣י אֲבוֹתָ֑יו וְלֹ֖א כְּטָהֳרַ֥ת הַקֹּֽדֶשׁ'),
(11848, 14, 'WLC', 'WLC', 'he', '2CH', 30, 20, 'OT', 'וַיִּשְׁמַ֤ע יְהוָה֙ אֶל יְחִזְקִיָּ֔הוּ וַיִּרְפָּ֖א אֶת הָעָֽם'),
(11849, 14, 'WLC', 'WLC', 'he', '2CH', 30, 21, 'OT', 'וַיַּעֲשׂ֣וּ בְנֵֽי יִ֠שְׂרָאֵל הַנִּמְצְאִ֨ים בִּירוּשָׁלִַ֜ם אֶת חַ֧ג הַמַּצּ֛וֹת שִׁבְעַ֥ת יָמִ֖ים בְּשִׂמְחָ֣ה גְדוֹלָ֑ה וּֽמְהַלְלִ֣ים לַ֠יהוָה י֣וֹם בְּי֞וֹם הַלְוִיִּ֧ם וְהַכֹּהֲנִ֛ים בִּכְלֵי עֹ֖ז לַיהוָֽה'),
(11850, 14, 'WLC', 'WLC', 'he', '2CH', 30, 22, 'OT', 'וַיְדַבֵּ֣ר יְחִזְקִיָּ֗הוּ עַל לֵב֙ כָּל הַלְוִיִּ֔ם הַמַּשְׂכִּילִ֥ים שֵֽׂכֶל ט֖וֹב לַיהוָ֑ה וַיֹּאכְל֤וּ אֶת הַמּוֹעֵד֙ שִׁבְעַ֣ת הַיָּמִ֔ים מְזַבְּחִים֙ זִבְחֵ֣י שְׁלָמִ֔ים וּמִ֨תְוַדִּ֔ים לַיהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵיהֶֽם'),
(11851, 14, 'WLC', 'WLC', 'he', '2CH', 30, 23, 'OT', 'וַיִּוָּֽעֲצוּ֙ כָּל הַקָּהָ֔ל לַעֲשׂ֕וֹת שִׁבְעַ֥ת יָמִ֖ים אֲחֵרִ֑ים וַיַּֽעֲשׂ֥וּ שִׁבְעַת יָמִ֖ים שִׂמְחָֽה'),
(11852, 14, 'WLC', 'WLC', 'he', '2CH', 30, 24, 'OT', 'כִּ֣י חִזְקִיָּ֣הוּ מֶֽלֶךְ יְ֠הוּדָה הֵרִ֨ים לַקָּהָ֜ל אֶ֣לֶף פָּרִים֮ וְשִׁבְעַ֣ת אֲלָפִ֣ים צֹאן֒ וְהַשָּׂרִ֞ים הֵרִ֤ימוּ לַקָּהָל֙ פָּרִ֣ים אֶ֔לֶף וְצֹ֖אן עֲשֶׂ֣רֶת אֲלָפִ֑ים וַיִּֽתְקַדְּשׁ֥וּ כֹהֲנִ֖ים לָרֹֽב'),
(11853, 14, 'WLC', 'WLC', 'he', '2CH', 30, 25, 'OT', 'וַֽיִּשְׂמְח֣וּ כָּל קְהַ֣ל יְהוּדָ֗ה וְהַכֹּהֲנִים֙ וְהַלְוִיִּ֔ם וְכָל הַקָּהָ֖ל הַבָּאִ֣ים מִיִּשְׂרָאֵ֑ל וְהַגֵּרִ֗ים הַבָּאִים֙ מֵאֶ֣רֶץ יִשְׂרָאֵ֔ל וְהַיּוֹשְׁבִ֖ים בִּיהוּדָֽה'),
(11854, 14, 'WLC', 'WLC', 'he', '2CH', 30, 26, 'OT', 'וַתְּהִ֥י שִׂמְחָֽה גְדוֹלָ֖ה בִּֽירוּשָׁלִָ֑ם כִּ֠י מִימֵ֞י שְׁלֹמֹ֤ה בֶן דָּוִיד֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל לֹ֥א כָזֹ֖את בִּירוּשָׁלִָֽם'),
(11855, 14, 'WLC', 'WLC', 'he', '2CH', 30, 27, 'OT', 'וַיָּקֻ֜מוּ הַכֹּהֲנִ֤ים הַלְוִיִּם֙ וַיְבָרֲכ֣וּ אֶת הָעָ֔ם וַיִּשָּׁמַ֖ע בְּקוֹלָ֑ם וַתָּב֧וֹא תְפִלָּתָ֛ם לִמְע֥וֹן קָדְשׁ֖וֹ לַשָּׁמָֽיִם'),
(11856, 14, 'WLC', 'WLC', 'he', '2CH', 31, 1, 'OT', 'וּכְכַלּ֣וֹת כָּל זֹ֗את יָצְא֨וּ כָּל יִשְׂרָאֵ֥ל הַֽנִּמְצְאִים֮ לְעָרֵ֣י יְהוּדָה֒ וַיְשַׁבְּר֣וּ הַמַּצֵּב֣וֹת וַיְגַדְּע֣וּ הָאֲשֵׁרִ֡ים וַיְנַתְּצ֣וּ אֶת הַ֠בָּמוֹת וְאֶת הַֽמִּזְבְּחֹ֞ת מִכָּל יְהוּדָ֧ה וּבִנְיָמִ֛ן וּבְאֶפְרַ֥יִם וּמְנַשֶּׁ֖ה עַד לְכַלֵּ֑ה וַיָּשׁ֜וּבוּ כָּל בְּנֵ֧י יִשְׂרָאֵ֛ל אִ֥ישׁ לַאֲחֻזָּת֖וֹ לְעָרֵיהֶֽם'),
(11857, 14, 'WLC', 'WLC', 'he', '2CH', 31, 2, 'OT', 'וַיַּעֲמֵ֣ד יְחִזְקִיָּ֡הוּ אֶת מַחְלְק֣וֹת הַכֹּהֲנִ֣ים וְ֠הַלְוִיִּם עַֽל מַחְלְקוֹתָ֞ם אִ֣ישׁ כְּפִ֣י עֲבֹדָת֗וֹ לַכֹּהֲנִים֙ וְלַלְוִיִּ֔ם לְעֹלָ֖ה וְלִשְׁלָמִ֑ים לְשָׁרֵת֙ וּלְהֹד֣וֹת וּלְהַלֵּ֔ל בְּשַׁעֲרֵ֖י מַחֲנ֥וֹת יְהוָֽה'),
(11858, 14, 'WLC', 'WLC', 'he', '2CH', 31, 3, 'OT', 'וּמְנָת֩ הַמֶּ֨לֶךְ מִן רְכוּשׁ֜וֹ לָעֹל֗וֹת לְעֹלוֹת֙ הַבֹּ֣קֶר וְהָעֶ֔רֶב וְהָ֣עֹל֔וֹת לַשַּׁבָּת֖וֹת וְלֶחֳדָשִׁ֣ים וְלַמֹּעֲדִ֑ים כַּכָּת֖וּב בְּתוֹרַ֥ת יְהוָֽה'),
(11859, 14, 'WLC', 'WLC', 'he', '2CH', 31, 4, 'OT', 'וַיֹּ֤אמֶר לָעָם֙ לְיוֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם לָתֵ֕ת מְנָ֥ת הַכֹּהֲנִ֖ים וְהַלְוִיִּ֑ם לְמַ֥עַן יֶחֶזְק֖וּ בְּתוֹרַ֥ת יְהוָֽה'),
(11860, 14, 'WLC', 'WLC', 'he', '2CH', 31, 5, 'OT', 'וְכִפְרֹ֣ץ הַדָּבָ֗ר הִרְבּ֤וּ בְנֵֽי יִשְׂרָאֵל֙ רֵאשִׁ֣ית דָּגָ֗ן תִּיר֤וֹשׁ וְיִצְהָר֙ וּדְבַ֔שׁ וְכֹ֖ל תְּבוּאַ֣ת שָׂדֶ֑ה וּמַעְשַׂ֥ר הַכֹּ֛ל לָרֹ֖ב הֵבִֽיאוּ'),
(11861, 14, 'WLC', 'WLC', 'he', '2CH', 31, 6, 'OT', 'וּבְנֵ֧י יִשְׂרָאֵ֣ל וִֽיהוּדָ֗ה הַיּֽוֹשְׁבִים֮ בְּעָרֵ֣י יְהוּדָה֒ גַּם הֵ֗ם מַעְשַׂ֤ר בָּקָר֙ וָצֹ֔אן וּמַעְשַׂ֣ר קָֽדָשִׁ֔ים הַמְקֻדָּשִׁ֖ים לַיהוָ֣ה אֱלֹהֵיהֶ֑ם הֵבִ֕יאוּ וַֽיִּתְּנ֖וּ עֲרֵמ֥וֹת עֲרֵמֽוֹת'),
(11862, 14, 'WLC', 'WLC', 'he', '2CH', 31, 7, 'OT', 'בַּחֹ֨דֶשׁ֙ הַשְּׁלִשִׁ֔י הֵחֵ֥לּוּ הָעֲרֵמ֖וֹת לְיִסּ֑וֹד וּבַחֹ֥דֶשׁ הַשְּׁבִיעִ֖י כִּלּֽוּ'),
(11863, 14, 'WLC', 'WLC', 'he', '2CH', 31, 8, 'OT', 'וַיָּבֹ֨אוּ֙ יְחִזְקִיָּ֣הוּ וְהַשָּׂרִ֔ים וַיִּרְא֖וּ אֶת הָעֲרֵמ֑וֹת וַֽיְבָרֲכוּ֙ אֶת יְהוָ֔ה וְאֵ֖ת עַמּ֥וֹ יִשְׂרָאֵֽל'),
(11864, 14, 'WLC', 'WLC', 'he', '2CH', 31, 9, 'OT', 'וַיִּדְרֹ֣שׁ יְחִזְקִיָּ֗הוּ עַל הַכֹּֽהֲנִ֛ים וְהַלְוִיִּ֖ם עַל הָעֲרֵמֽוֹת'),
(11865, 14, 'WLC', 'WLC', 'he', '2CH', 31, 10, 'OT', 'וַיֹּ֣אמֶר אֵלָ֗יו עֲזַרְיָ֧הוּ הַכֹּהֵ֛ן הָרֹ֖אשׁ לְבֵ֣ית צָד֑וֹק וַ֠יֹּאמֶר מֵהָחֵ֨ל הַתְּרוּמָ֜ה לָבִ֣יא בֵית יְהוָ֗ה אָכ֨וֹל וְשָׂב֤וֹעַ וְהוֹתֵר֙ עַד לָר֔וֹב כִּ֤י יְהוָה֙ בֵּרַ֣ךְ אֶת עַמּ֔וֹ וְהַנּוֹתָ֖ר אֶת הֶהָמ֥וֹן הַזֶּֽה'),
(11866, 14, 'WLC', 'WLC', 'he', '2CH', 31, 11, 'OT', 'וַיֹּ֣אמֶר יְחִזְקִיָּ֗הוּ לְהָכִ֧ין לְשָׁכ֛וֹת בְּבֵ֥ית יְהוָ֖ה וַיָּכִֽינוּ'),
(11867, 14, 'WLC', 'WLC', 'he', '2CH', 31, 12, 'OT', 'וַיָּבִ֨יאוּ אֶת הַתְּרוּמָ֧ה וְהַֽמַּעֲשֵׂ֛ר וְהַקֳּדָשִׁ֖ים בֶּאֱמוּנָ֑ה וַעֲלֵיהֶ֤ם נָגִיד֙ כונניהו הַלֵּוִ֔י וְשִׁמְעִ֥י אָחִ֖יהוּ מִשְׁנֶֽה'),
(11868, 14, 'WLC', 'WLC', 'he', '2CH', 31, 13, 'OT', 'וִֽיחִיאֵ֡ל וַ֠עֲזַזְיָהוּ וְנַ֨חַת וַעֲשָׂהאֵ֜ל וִֽירִימ֤וֹת וְיוֹזָבָד֙ וֶאֱלִיאֵ֣ל וְיִסְמַכְיָ֔הוּ וּמַ֖חַת וּבְנָיָ֑הוּ פְּקִידִ֗ים מִיַּ֤ד כונניהו וְשִׁמְעִ֣י אָחִ֔יו בְּמִפְקַד֙ יְחִזְקִיָּ֣הוּ הַמֶּ֔לֶךְ וַעֲזַרְיָ֖הוּ נְגִ֥יד בֵּית הָאֱלֹהִֽים'),
(11869, 14, 'WLC', 'WLC', 'he', '2CH', 31, 14, 'OT', 'וְקוֹרֵ֨א בֶן יִמְנָ֤ה הַלֵּוִי֙ הַשּׁוֹעֵ֣ר לַמִּזְרָ֔חָה עַ֖ל נִדְב֣וֹת הָאֱלֹהִ֑ים לָתֵת֙ תְּרוּמַ֣ת יְהוָ֔ה וְקָדְשֵׁ֖י הַקֳּדָשִֽׁים'),
(11870, 14, 'WLC', 'WLC', 'he', '2CH', 31, 15, 'OT', 'וְעַל יָד֡וֹ עֵ֣דֶן וּ֠מִנְיָמִן וְיֵשׁ֨וּעַ וּֽשְׁמַֽעְיָ֜הוּ אֲמַרְיָ֧הוּ וּשְׁכַנְיָ֛הוּ בְּעָרֵ֥י הַכֹּהֲנִ֖ים בֶּאֱמוּנָ֑ה לָתֵ֤ת לַאֲחֵיהֶם֙ בְּמַחְלְק֔וֹת כַּגָּד֖וֹל כַּקָּטָֽן'),
(11871, 14, 'WLC', 'WLC', 'he', '2CH', 31, 16, 'OT', 'מִלְּבַ֞ד הִתְיַחְשָׂ֣ם לִזְכָרִ֗ים מִבֶּ֨ן שָׁל֤וֹשׁ שָׁנִים֙ וּלְמַ֔עְלָה לְכָל הַבָּ֥א לְבֵית יְהוָ֖ה לִדְבַר י֣וֹם בְּיוֹמ֑וֹ לַעֲב֣וֹדָתָ֔ם בְּמִשְׁמְרוֹתָ֖ם כְּמַחְלְקוֹתֵיהֶֽם'),
(11872, 14, 'WLC', 'WLC', 'he', '2CH', 31, 17, 'OT', 'וְאֵ֨ת הִתְיַחֵ֤שׂ הַכֹּהֲנִים֙ לְבֵ֣ית אֲבוֹתֵיהֶ֔ם וְהַ֨לְוִיִּ֔ם מִבֶּ֛ן עֶשְׂרִ֥ים שָׁנָ֖ה וּלְמָ֑עְלָה בְּמִשְׁמְרוֹתֵיהֶ֖ם בְּמַחְלְקוֹתֵיהֶֽם'),
(11873, 14, 'WLC', 'WLC', 'he', '2CH', 31, 18, 'OT', 'וּלְהִתְיַחֵ֗שׂ בְּכָל טַפָּ֧ם נְשֵׁיהֶ֛ם וּבְנֵיהֶ֥ם וּבְנוֹתֵיהֶ֖ם לְכָל קָהָ֑ל כִּ֥י בֶאֱמוּנָתָ֖ם יִתְקַדְּשׁוּ קֹֽדֶשׁ'),
(11874, 14, 'WLC', 'WLC', 'he', '2CH', 31, 19, 'OT', 'וְלִבְנֵי֩ אַהֲרֹ֨ן הַכֹּהֲנִ֜ים בִּשְׂדֵ֨י מִגְרַ֤שׁ עָרֵיהֶם֙ בְּכָל עִ֣יר וָעִ֔יר אֲנָשִׁ֕ים אֲשֶׁ֥ר נִקְּב֖וּ בְּשֵׁמ֑וֹת לָתֵ֣ת מָנ֗וֹת לְכָל זָכָר֙ בַּכֹּ֣הֲנִ֔ים וּלְכָל הִתְיַחֵ֖שׂ בַּלְוִיִּֽם'),
(11875, 14, 'WLC', 'WLC', 'he', '2CH', 31, 20, 'OT', 'וַיַּ֧עַשׂ כָּזֹ֛את יְחִזְקִיָּ֖הוּ בְּכָל יְהוּדָ֑ה וַיַּ֨עַשׂ הַטּ֤וֹב וְהַיָּשָׁר֙ וְהָ֣אֱמֶ֔ת לִפְנֵ֖י יְהוָ֥ה אֱלֹהָֽיו'),
(11876, 14, 'WLC', 'WLC', 'he', '2CH', 31, 21, 'OT', 'וּבְכָֽל מַעֲשֶׂ֞ה אֲשֶׁר הֵחֵ֣ל בַּעֲבוֹדַ֣ת בֵּית הָאֱלֹהִ֗ים וּבַתּוֹרָה֙ וּבַמִּצְוָ֔ה לִדְרֹ֖שׁ לֵֽאלֹהָ֑יו בְּכָל לְבָב֥וֹ עָשָׂ֖ה וְהִצְלִֽיחַ'),
(11877, 14, 'WLC', 'WLC', 'he', '2CH', 32, 1, 'OT', 'אַחֲרֵ֨י הַדְּבָרִ֤ים וְהָאֱמֶת֙ הָאֵ֔לֶּה בָּ֖א סַנְחֵרִ֣יב מֶֽלֶךְ אַשּׁ֑וּר וַיָּבֹ֣א בִֽיהוּדָ֗ה וַיִּ֨חַן֙ עַל הֶעָרִ֣ים הַבְּצֻר֔וֹת וַיֹּ֖אמֶר לְבִקְעָ֥ם אֵלָֽיו'),
(11878, 14, 'WLC', 'WLC', 'he', '2CH', 32, 2, 'OT', 'וַיַּרְא֙ יְחִזְקִיָּ֔הוּ כִּי בָ֖א סַנְחֵרִ֑יב וּפָנָ֕יו לַמִּלְחָמָ֖ה עַל יְרוּשָׁלִָֽם'),
(11879, 14, 'WLC', 'WLC', 'he', '2CH', 32, 3, 'OT', 'וַיִּוָּעַ֗ץ עִם שָׂרָיו֙ וְגִבֹּרָ֔יו לִסְתּוֹם֙ אֶת מֵימֵ֣י הָעֲיָנ֔וֹת אֲשֶׁ֖ר מִח֣וּץ לָעִ֑יר וַֽיַּעְזְרֽוּהוּ'),
(11880, 14, 'WLC', 'WLC', 'he', '2CH', 32, 4, 'OT', 'וַיִּקָּבְצ֣וּ עַם רָ֔ב וַֽיִּסְתְּמוּ֙ אֶת כָּל הַמַּעְיָנ֔וֹת וְאֶת הַנַּ֛חַל הַשּׁוֹטֵ֥ף בְּתוֹךְ הָאָ֖רֶץ לֵאמֹ֑ר לָ֤מָּה יָב֨וֹאוּ֙ מַלְכֵ֣י אַשּׁ֔וּר וּמָצְא֖וּ מַ֥יִם רַבִּֽים'),
(11881, 14, 'WLC', 'WLC', 'he', '2CH', 32, 5, 'OT', 'וַיִּתְחַזַּ֡ק וַיִּבֶן֩ אֶת כָּל הַחוֹמָ֨ה הַפְּרוּצָ֜ה וַיַּ֣עַל עַל הַמִּגְדָּל֗וֹת וְלַח֨וּצָה֙ הַחוֹמָ֣ה אַחֶ֔רֶת וַיְחַזֵּ֥ק אֶת הַמִּלּ֖וֹא עִ֣יר דָּוִ֑יד וַיַּ֥עַשׂ שֶׁ֛לַח לָרֹ֖ב וּמָגִנִּֽים'),
(11882, 14, 'WLC', 'WLC', 'he', '2CH', 32, 6, 'OT', 'וַיִּתֵּ֛ן שָׂרֵ֥י מִלְחָמ֖וֹת עַל הָעָ֑ם וַיִּקְבְּצֵ֣ם אֵלָ֗יו אֶל רְחוֹב֙ שַׁ֣עַר הָעִ֔יר וַיְדַבֵּ֥ר עַל לְבָבָ֖ם לֵאמֹֽר'),
(11883, 14, 'WLC', 'WLC', 'he', '2CH', 32, 7, 'OT', 'חִזְק֣וּ וְאִמְצ֔וּ אַל תִּֽירְא֣וּ וְאַל תֵּחַ֗תּוּ מִפְּנֵי֙ מֶ֣לֶךְ אַשּׁ֔וּר וּמִלִּפְנֵ֖י כָּל הֶהָמ֣וֹן אֲשֶׁר עִמּ֑וֹ כִּֽי עִמָּ֥נוּ רַ֖ב מֵעִמּֽוֹ'),
(11884, 14, 'WLC', 'WLC', 'he', '2CH', 32, 8, 'OT', 'עִמּוֹ֙ זְר֣וֹעַ בָּשָׂ֔ר וְעִמָּ֜נוּ יְהוָ֤ה אֱלֹהֵ֨ינוּ֙ לְעָזְרֵ֔נוּ וּלְהִלָּחֵ֖ם מִלְחֲמֹתֵ֑נוּ וַיִּסָּמְכ֣וּ הָעָ֔ם עַל דִּבְרֵ֖י יְחִזְקִיָּ֥הוּ מֶֽלֶךְ יְהוּדָֽה'),
(11885, 14, 'WLC', 'WLC', 'he', '2CH', 32, 9, 'OT', 'אַ֣חַר זֶ֗ה שָׁ֠לַח סַנְחֵרִ֨יב מֶֽלֶךְ אַשּׁ֤וּר עֲבָדָיו֙ יְר֣וּשָׁלַ֔יְמָה וְהוּא֙ עַל לָכִ֔ישׁ וְכָל מֶמְשַׁלְתּ֖וֹ עִמּ֑וֹ עַל יְחִזְקִיָּ֨הוּ֙ מֶ֣לֶךְ יְהוּדָ֔ה וְעַל כָּל יְהוּדָ֛ה אֲשֶׁ֥ר בִּירוּשָׁלִַ֖ם לֵאמֹֽר'),
(11886, 14, 'WLC', 'WLC', 'he', '2CH', 32, 10, 'OT', 'כֹּ֣ה אָמַ֔ר סַנְחֵרִ֖יב מֶ֣לֶךְ אַשּׁ֑וּר עַל מָה֙ אַתֶּ֣ם בֹּטְחִ֔ים וְיֹשְׁבִ֥ים בְּמָצ֖וֹר בִּירוּשָׁלִָֽם'),
(11887, 14, 'WLC', 'WLC', 'he', '2CH', 32, 11, 'OT', 'הֲלֹ֤א יְחִזְקִיָּ֨הוּ֙ מַסִּ֣ית אֶתְכֶ֔ם לָתֵ֣ת אֶתְכֶ֔ם לָמ֛וּת בְּרָעָ֥ב וּבְצָמָ֖א לֵאמֹ֑ר יְהוָ֣ה אֱלֹהֵ֔ינוּ יַצִּילֵ֕נוּ מִכַּ֖ף מֶ֥לֶךְ אַשּֽׁוּר'),
(11888, 14, 'WLC', 'WLC', 'he', '2CH', 32, 12, 'OT', 'הֲלֹא הוּא֙ יְחִזְקִיָּ֔הוּ הֵסִ֥יר אֶת בָּמֹתָ֖יו וְאֶת מִזְבְּחֹתָ֑יו וַיֹּ֨אמֶר לִֽיהוּדָ֤ה וְלִֽירוּשָׁלִַ֨ם֙ לֵאמֹ֔ר לִפְנֵ֨י מִזְבֵּ֧חַ אֶחָ֛ד תִּֽשְׁתַּחֲו֖וּ וְעָלָ֥יו תַּקְטִֽירוּ'),
(11889, 14, 'WLC', 'WLC', 'he', '2CH', 32, 13, 'OT', 'הֲלֹ֣א תֵדְע֗וּ מֶ֤ה עָשִׂ֨יתִי֙ אֲנִ֣י וַאֲבוֹתַ֔י לְכֹ֖ל עַמֵּ֣י הָאֲרָצ֑וֹת הֲיָכ֣וֹל יָֽכְל֗וּ אֱלֹהֵי֙ גּוֹיֵ֣ הָאֲרָצ֔וֹת לְהַצִּ֥יל אֶת אַרְצָ֖ם מִיָּדִֽי'),
(11890, 14, 'WLC', 'WLC', 'he', '2CH', 32, 14, 'OT', 'מִ֠י בְּֽכָל אֱלֹהֵ֞י הַגּוֹיִ֤ם הָאֵ֨לֶּה֙ אֲשֶׁ֣ר הֶחֱרִ֣ימוּ אֲבוֹתַ֔י אֲשֶׁ֣ר יָכ֔וֹל לְהַצִּ֥יל אֶת עַמּ֖וֹ מִיָּדִ֑י כִּ֤י יוּכַל֙ אֱלֹ֣הֵיכֶ֔ם לְהַצִּ֥יל אֶתְכֶ֖ם מִיָּדִֽי'),
(11891, 14, 'WLC', 'WLC', 'he', '2CH', 32, 15, 'OT', 'וְעַתָּ֡ה אַל יַשִּׁיא֩ אֶתְכֶ֨ם חִזְקִיָּ֜הוּ וְאַל יַסִּ֨ית אֶתְכֶ֣ם כָּזֹאת֮ וְאַל תַּאֲמִ֣ינוּ לוֹ֒ כִּי לֹ֣א יוּכַ֗ל כָּל אֱל֨וֹהַ֙ כָּל גּ֣וֹי וּמַמְלָכָ֔ה לְהַצִּ֥יל עַמּ֛וֹ מִיָּדִ֖י וּמִיַּ֣ד אֲבוֹתָ֑י אַ֚ף כִּ֣י אֱֽלֹהֵיכֶ֔ם לֹא יַצִּ֥ילוּ אֶתְכֶ֖ם מִיָּדִֽי'),
(11892, 14, 'WLC', 'WLC', 'he', '2CH', 32, 16, 'OT', 'וְעוֹד֙ דִּבְּר֣וּ עֲבָדָ֔יו עַל יְהוָ֖ה הָאֱלֹהִ֑ים וְעַ֖ל יְחִזְקִיָּ֥הוּ עַבְדּֽוֹ'),
(11893, 14, 'WLC', 'WLC', 'he', '2CH', 32, 17, 'OT', 'וּסְפָרִ֣ים כָּתַ֔ב לְחָרֵ֕ף לַיהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל וְלֵֽאמֹ֨ר עָלָ֜יו לֵאמֹ֗ר כֵּֽאלֹהֵ֞י גּוֹיֵ֤ הָאֲרָצוֹת֙ אֲשֶׁ֨ר לֹא הִצִּ֤ילוּ עַמָּם֙ מִיָּדִ֔י כֵּ֣ן לֹֽא יַצִּ֞יל אֱלֹהֵ֧י יְחִזְקִיָּ֛הוּ עַמּ֖וֹ מִיָּדִֽי'),
(11894, 14, 'WLC', 'WLC', 'he', '2CH', 32, 18, 'OT', 'וַיִּקְרְא֨וּ בְקוֹל גָּד֜וֹל יְהוּדִ֗ית עַל עַ֤ם יְרוּשָׁלִַ֨ם֙ אֲשֶׁ֣ר עַל הַֽחוֹמָ֔ה לְיָֽרְאָ֖ם וּֽלְבַהֲלָ֑ם לְמַ֖עַן יִלְכְּד֥וּ אֶת הָעִֽיר'),
(11895, 14, 'WLC', 'WLC', 'he', '2CH', 32, 19, 'OT', 'וַֽיְדַבְּר֔וּ אֶל אֱלֹהֵ֖י יְרוּשָׁלִָ֑ם כְּעַ֗ל אֱלֹהֵי֙ עַמֵּ֣י הָאָ֔רֶץ מַעֲשֵׂ֖ה יְדֵ֥י הָאָדָֽם'),
(11896, 14, 'WLC', 'WLC', 'he', '2CH', 32, 20, 'OT', 'וַיִּתְפַּלֵּ֞ל יְחִזְקִיָּ֣הוּ הַמֶּ֗לֶךְ וִֽישַֽׁעְיָ֧הוּ בֶן אָמ֛וֹץ הַנָּבִ֖יא עַל זֹ֑את וַֽיִּזְעֲק֖וּ הַשָּׁמָֽיִם'),
(11897, 14, 'WLC', 'WLC', 'he', '2CH', 32, 21, 'OT', 'וַיִּשְׁלַ֤ח יְהוָה֙ מַלְאָ֔ךְ וַיַּכְחֵ֞ד כָּל גִּבּ֥וֹר חַ֨יִל֙ וְנָגִ֣יד וְשָׂ֔ר בְּמַחֲנֵ֖ה מֶ֣לֶךְ אַשּׁ֑וּר וַיָּשָׁב֩ בְּבֹ֨שֶׁת פָּנִ֜ים לְאַרְצ֗וֹ וַיָּבֹא֙ בֵּ֣ית אֱלֹהָ֔יו ומיציאו מֵעָ֔יו שָׁ֖ם הִפִּילֻ֥הוּ בֶחָֽרֶב'),
(11898, 14, 'WLC', 'WLC', 'he', '2CH', 32, 22, 'OT', 'וַיּוֹשַׁע֩ יְהוָ֨ה אֶת יְחִזְקִיָּ֜הוּ וְאֵ֣ת יֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם מִיַּ֛ד סַנְחֵרִ֥יב מֶֽלֶךְ אַשּׁ֖וּר וּמִיַּד כֹּ֑ל וַֽיְנַהֲלֵ֖ם מִסָּבִֽיב'),
(11899, 14, 'WLC', 'WLC', 'he', '2CH', 32, 23, 'OT', 'וְ֠רַבִּים מְבִיאִ֨ים מִנְחָ֤ה לַיהוָה֙ לִיר֣וּשָׁלִַ֔ם וּמִ֨גְדָּנ֔וֹת לִֽיחִזְקִיָּ֖הוּ מֶ֣לֶךְ יְהוּדָ֑ה וַיִּנַּשֵּׂ֛א לְעֵינֵ֥י כָל הַגּוֹיִ֖ם מֵאַֽחֲרֵי כֵֽן'),
(11900, 14, 'WLC', 'WLC', 'he', '2CH', 32, 24, 'OT', 'בַּיָּמִ֣ים הָהֵ֔ם חָלָ֥ה יְחִזְקִיָּ֖הוּ עַד לָמ֑וּת וַיִּתְפַּלֵּל֙ אֶל יְהוָ֔ה וַיֹּ֣אמֶר ל֔וֹ וּמוֹפֵ֖ת נָ֥תַן לֽוֹ'),
(11901, 14, 'WLC', 'WLC', 'he', '2CH', 32, 25, 'OT', 'וְלֹא כִגְמֻ֤ל עָלָיו֙ הֵשִׁ֣יב יְחִזְקִיָּ֔הוּ כִּ֥י גָבַ֖הּ לִבּ֑וֹ וַיְהִ֤י עָלָיו֙ קֶ֔צֶף וְעַל יְהוּדָ֖ה וִירוּשָׁלִָֽם'),
(11902, 14, 'WLC', 'WLC', 'he', '2CH', 32, 26, 'OT', 'וַיִּכָּנַ֤ע יְחִזְקִיָּ֨הוּ֙ בְּגֹ֣בַהּ לִבּ֔וֹ ה֖וּא וְיֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם וְלֹא בָ֤א עֲלֵיהֶם֙ קֶ֣צֶף יְהוָ֔ה בִּימֵ֖י יְחִזְקִיָּֽהוּ'),
(11903, 14, 'WLC', 'WLC', 'he', '2CH', 32, 27, 'OT', 'וַיְהִ֧י לִֽיחִזְקִיָּ֛הוּ עֹ֥שֶׁר וְכָב֖וֹד הַרְבֵּ֣ה מְאֹ֑ד וְאֹֽצָר֣וֹת עָֽשָׂה ל֠וֹ לְכֶ֨סֶף וּלְזָהָ֜ב וּלְאֶ֣בֶן יְקָרָ֗ה וְלִבְשָׂמִים֙ וּלְמָ֣גִנִּ֔ים וּלְכֹ֖ל כְּלֵ֥י חֶמְדָּֽה'),
(11904, 14, 'WLC', 'WLC', 'he', '2CH', 32, 28, 'OT', 'וּמִ֨סְכְּנ֔וֹת לִתְבוּאַ֥ת דָּגָ֖ן וְתִיר֣וֹשׁ וְיִצְהָ֑ר וְאֻֽרָוֺת֙ לְכָל בְּהֵמָ֣ה וּבְהֵמָ֔ה וַעֲדָרִ֖ים לָאֲוֵרֽוֹת'),
(11905, 14, 'WLC', 'WLC', 'he', '2CH', 32, 29, 'OT', 'וְעָרִים֙ עָ֣שָׂה ל֔וֹ וּמִקְנֵה צֹ֥אן וּבָקָ֖ר לָרֹ֑ב כִּ֤י נָֽתַן לוֹ֙ אֱלֹהִ֔ים רְכ֖וּשׁ רַ֥ב מְאֹֽד'),
(11906, 14, 'WLC', 'WLC', 'he', '2CH', 32, 30, 'OT', 'וְה֣וּא יְחִזְקִיָּ֗הוּ סָתַם֙ אֶת מוֹצָ֞א מֵימֵ֤י גִיחוֹן֙ הָֽעֶלְי֔וֹן וַֽיַּישְּׁרֵ֥ם לְמַֽטָּה מַּעְרָ֖בָה לְעִ֣יר דָּוִ֑יד וַיַּצְלַ֥ח יְחִזְקִיָּ֖הוּ בְּכָֽל מַעֲשֵֽׂהוּ'),
(11907, 14, 'WLC', 'WLC', 'he', '2CH', 32, 31, 'OT', 'וְכֵ֞ן בִּמְלִיצֵ֣י שָׂרֵ֣י בָּבֶ֗ל הַֽמְשַׁלְּחִ֤ים עָלָיו֙ לִדְרֹ֗שׁ הַמּוֹפֵת֙ אֲשֶׁ֣ר הָיָ֣ה בָאָ֔רֶץ עֲזָב֖וֹ הָֽאֱלֹהִ֑ים לְנַ֨סּוֹת֔וֹ לָדַ֖עַת כָּל בִּלְבָבֽוֹ'),
(11908, 14, 'WLC', 'WLC', 'he', '2CH', 32, 32, 'OT', 'וְיֶ֛תֶר דִּבְרֵ֥י יְחִזְקִיָּ֖הוּ וַחֲסָדָ֑יו הִנָּ֣ם כְּתוּבִ֗ים בַּחֲז֞וֹן יְשַֽׁעְיָ֤הוּ בֶן אָמוֹץ֙ הַנָּבִ֔יא עַל סֵ֥פֶר מַלְכֵי יְהוּדָ֖ה וְיִשְׂרָאֵֽל'),
(11909, 14, 'WLC', 'WLC', 'he', '2CH', 32, 33, 'OT', 'וַיִּשְׁכַּ֨ב יְחִזְקִיָּ֜הוּ עִם אֲבֹתָ֗יו וַֽיִּקְבְּרֻהוּ֮ בְּֽמַעֲלֵה֮ קִבְרֵ֣י בְנֵי דָוִיד֒ וְכָבוֹד֙ עָֽשׂוּ ל֣וֹ בְמוֹת֔וֹ כָּל יְהוּדָ֖ה וְיֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם וַיִּמְלֹ֛ךְ מְנַשֶּׁ֥ה בְנ֖וֹ תַּחְתָּֽיו'),
(11910, 14, 'WLC', 'WLC', 'he', '2CH', 33, 1, 'OT', 'בֶּן שְׁתֵּ֥ים עֶשְׂרֵ֛ה שָׁנָ֖ה מְנַשֶּׁ֣ה בְמָלְכ֑וֹ וַחֲמִשִּׁ֤ים וְחָמֵשׁ֙ שָׁנָ֔ה מָלַ֖ךְ בִּירוּשָׁלִָֽם'),
(11911, 14, 'WLC', 'WLC', 'he', '2CH', 33, 2, 'OT', 'וַיַּ֥עַשׂ הָרַ֖ע בְּעֵינֵ֣י יְהוָ֑ה כְּתֽוֹעֲבוֹת֙ הַגּוֹיִ֔ם אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִפְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל'),
(11912, 14, 'WLC', 'WLC', 'he', '2CH', 33, 3, 'OT', 'וַיָּ֗שָׁב וַיִּ֨בֶן֙ אֶת הַבָּמ֔וֹת אֲשֶׁ֥ר נִתַּ֖ץ יְחִזְקִיָּ֣הוּ אָבִ֑יו וַיָּ֨קֶם מִזְבְּח֤וֹת לַבְּעָלִים֙ וַיַּ֣עַשׂ אֲשֵׁר֔וֹת וַיִּשְׁתַּ֨חוּ֙ לְכָל צְבָ֣א הַשָּׁמַ֔יִם וַֽיַּעֲבֹ֖ד אֹתָֽם'),
(11913, 14, 'WLC', 'WLC', 'he', '2CH', 33, 4, 'OT', 'וּבָנָ֥ה מִזְבְּח֖וֹת בְּבֵ֣ית יְהוָ֑ה אֲשֶׁר֙ אָמַ֣ר יְהוָ֔ה בִּירוּשָׁלִַ֥ם יִֽהְיֶה שְּׁמִ֖י לְעוֹלָֽם'),
(11914, 14, 'WLC', 'WLC', 'he', '2CH', 33, 5, 'OT', 'וַיִּ֥בֶן מִזְבְּח֖וֹת לְכָל צְבָ֣א הַשָּׁמָ֑יִם בִּשְׁתֵּ֖י חַצְר֥וֹת בֵּית יְהוָֽה'),
(11915, 14, 'WLC', 'WLC', 'he', '2CH', 33, 6, 'OT', 'וְהוּא֩ הֶעֱבִ֨יר אֶת בָּנָ֤יו בָּאֵשׁ֙ בְּגֵ֣י בֶן הִנֹּ֔ם וְעוֹנֵ֤ן וְנִחֵשׁ֙ וְֽכִשֵּׁ֔ף וְעָ֥שָׂה א֖וֹב וְיִדְּעוֹנִ֑י הִרְבָּ֗ה לַעֲשׂ֥וֹת הָרַ֛ע בְּעֵינֵ֥י יְהוָ֖ה לְהַכְעִיסֽוֹ'),
(11916, 14, 'WLC', 'WLC', 'he', '2CH', 33, 7, 'OT', 'וַיָּ֕שֶׂם אֶת פֶּ֥סֶל הַסֶּ֖מֶל אֲשֶׁ֣ר עָשָׂ֑ה בְּבֵ֣ית הָאֱלֹהִ֗ים אֲשֶׁ֨ר אָמַ֤ר אֱלֹהִים֙ אֶל דָּוִיד֙ וְאֶל שְׁלֹמֹ֣ה בְנ֔וֹ בַּבַּ֨יִת הַזֶּ֜ה וּבִֽירוּשָׁלִַ֗ם אֲשֶׁ֤ר בָּחַ֨רְתִּי֙ מִכֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל אָשִׂ֥ים אֶת שְׁמִ֖י לְעֵילֽוֹם'),
(11917, 14, 'WLC', 'WLC', 'he', '2CH', 33, 8, 'OT', 'וְלֹ֣א אוֹסִ֗יף לְהָסִיר֙ אֶת רֶ֣גֶל יִשְׂרָאֵ֔ל מֵעַל֙ הָֽאֲדָמָ֔ה אֲשֶׁ֥ר הֶֽעֱמַ֖דְתִּי לַאֲבֹֽתֵיכֶ֑ם רַ֣ק אִם יִשְׁמְר֣וּ לַעֲשׂ֗וֹת אֵ֚ת כָּל אֲשֶׁ֣ר צִוִּיתִ֔ים לְכָל הַתּוֹרָ֛ה וְהַֽחֻקִּ֥ים וְהַמִּשְׁפָּטִ֖ים בְּיַד מֹשֶֽׁה'),
(11918, 14, 'WLC', 'WLC', 'he', '2CH', 33, 9, 'OT', 'וַיֶּ֣תַע מְנַשֶּׁ֔ה אֶת יְהוּדָ֖ה וְיֹשְׁבֵ֣י יְרוּשָׁלִָ֑ם לַעֲשׂ֣וֹת רָ֔ע מִן הַ֨גּוֹיִ֔ם אֲשֶׁר֙ הִשְׁמִ֣יד יְהוָ֔ה מִפְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל'),
(11919, 14, 'WLC', 'WLC', 'he', '2CH', 33, 10, 'OT', 'וַיְדַבֵּ֧ר יְהוָ֛ה אֶל מְנַשֶּׁ֥ה וְאֶל עַמּ֖וֹ וְלֹ֥א הִקְשִֽׁיבוּ'),
(11920, 14, 'WLC', 'WLC', 'he', '2CH', 33, 11, 'OT', 'וַיָּבֵ֨א יְהוָ֜ה עֲלֵיהֶ֗ם אֶת שָׂרֵ֤י הַצָּבָא֙ אֲשֶׁר֙ לְמֶ֣לֶךְ אַשּׁ֔וּר וַיִּלְכְּד֥וּ אֶת מְנַשֶּׁ֖ה בַּחֹחִ֑ים וַיַּֽאַסְרֻ֨הוּ֙ בַּֽנְחֻשְׁתַּ֔יִם וַיּוֹלִיכֻ֖הוּ בָּבֶֽלָה'),
(11921, 14, 'WLC', 'WLC', 'he', '2CH', 33, 12, 'OT', 'וּכְהָצֵ֣ר ל֔וֹ חִלָּ֕ה אֶת פְּנֵ֖י יְהוָ֣ה אֱלֹהָ֑יו וַיִּכָּנַ֣ע מְאֹ֔ד מִלִּפְנֵ֖י אֱלֹהֵ֥י אֲבֹתָֽיו'),
(11922, 14, 'WLC', 'WLC', 'he', '2CH', 33, 13, 'OT', 'וַיִּתְפַּלֵּ֣ל אֵלָ֗יו וַיֵּעָ֤תֶר לוֹ֙ וַיִּשְׁמַ֣ע תְּחִנָּת֔וֹ וַיְשִׁיבֵ֥הוּ יְרוּשָׁלִַ֖ם לְמַלְכוּת֑וֹ וַיֵּ֣דַע מְנַשֶּׁ֔ה כִּ֥י יְהוָ֖ה ה֥וּא הָֽאֱלֹהִֽים'),
(11923, 14, 'WLC', 'WLC', 'he', '2CH', 33, 14, 'OT', 'וְאַחֲרֵי כֵ֡ן בָּנָ֣ה חוֹמָ֣ה חִֽיצוֹנָ֣ה לְעִיר דָּוִ֡יד מַעְרָבָה֩ לְגִיח֨וֹן בַּנַּ֜חַל וְלָב֨וֹא בְשַׁ֤עַר הַדָּגִים֙ וְסָבַ֣ב לָעֹ֔פֶל וַיַּגְבִּיהֶ֖הָ מְאֹ֑ד וַיָּ֧שֶׂם שָֽׂרֵי חַ֛יִל בְּכָל הֶעָרִ֥ים הַבְּצֻר֖וֹת בִּיהוּדָֽה'),
(11924, 14, 'WLC', 'WLC', 'he', '2CH', 33, 15, 'OT', 'וַ֠יָּסַר אֶת אֱלֹהֵ֨י הַנֵּכָ֤ר וְאֶת הַסֶּ֨מֶל֙ מִבֵּ֣ית יְהוָ֔ה וְכָל הַֽמִּזְבְּח֗וֹת אֲשֶׁ֥ר בָּנָ֛ה בְּהַ֥ר בֵּית יְהוָ֖ה וּבִירוּשָׁלִָ֑ם וַיַּשְׁלֵ֖ךְ ח֥וּצָה לָעִֽיר'),
(11925, 14, 'WLC', 'WLC', 'he', '2CH', 33, 16, 'OT', 'ויכן אֶת מִזְבַּ֣ח יְהוָ֔ה וַיִּזְבַּ֣ח עָלָ֔יו זִבְחֵ֥י שְׁלָמִ֖ים וְתוֹדָ֑ה וַיֹּ֨אמֶר֙ לִֽיהוּדָ֔ה לַעֲב֕וֹד אֶת יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל'),
(11926, 14, 'WLC', 'WLC', 'he', '2CH', 33, 17, 'OT', 'אֲבָל֙ ע֣וֹד הָעָ֔ם זֹבְחִ֖ים בַּבָּמ֑וֹת רַ֖ק לַיהוָ֥ה אֱלֹהֵיהֶֽם'),
(11927, 14, 'WLC', 'WLC', 'he', '2CH', 33, 18, 'OT', 'וְיֶ֨תֶר דִּבְרֵ֣י מְנַשֶּׁה֮ וּתְפִלָּת֣וֹ אֶל אֱלֹהָיו֒ וְדִבְרֵי֙ הַֽחֹזִ֔ים הַֽמְדַבְּרִ֣ים אֵלָ֔יו בְּשֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל הִנָּ֕ם עַל דִּבְרֵ֖י מַלְכֵ֥י יִשְׂרָאֵֽל'),
(11928, 14, 'WLC', 'WLC', 'he', '2CH', 33, 19, 'OT', 'וּתְפִלָּת֣וֹ וְהֵֽעָתֶר לוֹ֮ וְכָל חַטָּאת֣וֹ וּמַעְלוֹ֒ וְהַמְּקֹמ֗וֹת אֲשֶׁר֩ בָּנָ֨ה בָהֶ֤ם בָּמוֹת֙ וְהֶעֱמִיד֙ הָאֲשֵׁרִ֣ים וְהַפְּסִלִ֔ים לִפְנֵ֖י הִכָּנְע֑וֹ הִנָּ֣ם כְּתוּבִ֔ים עַ֖ל דִּבְרֵ֥י חוֹזָֽי'),
