(11937, 14, 'WLC', 'WLC', 'he', '2CH', 34, 3, 'OT', 'וּבִשְׁמוֹנֶ֨ה שָׁנִ֜ים לְמָלְכ֗וֹ וְהוּא֙ עוֹדֶ֣נּוּ נַ֔עַר הֵחֵ֕ל לִדְר֕וֹשׁ לֵאלֹהֵ֖י דָּוִ֣יד אָבִ֑יו וּבִשְׁתֵּ֧ים עֶשְׂרֵ֣ה שָׁנָ֗ה הֵחֵל֙ לְטַהֵ֔ר אֶת יְהוּדָה֙ וִיר֣וּשָׁלִַ֔ם מִן הַבָּמוֹת֙ וְהָ֣אֲשֵׁרִ֔ים וְהַפְּסִלִ֖ים וְהַמַּסֵּכֽוֹת'),
(11938, 14, 'WLC', 'WLC', 'he', '2CH', 34, 4, 'OT', 'וַיְנַתְּצ֣וּ לְפָנָ֗יו אֵ֚ת מִזְבְּח֣וֹת הַבְּעָלִ֔ים וְהַֽחַמָּנִ֛ים אֲשֶׁר לְמַ֥עְלָה מֵעֲלֵיהֶ֖ם גִּדֵּ֑עַ וְ֠הָאֲשֵׁרִים וְהַפְּסִלִ֤ים וְהַמַּסֵּכוֹת֙ שִׁבַּ֣ר וְהֵדַ֔ק וַיִּזְרֹק֙ עַל פְּנֵ֣י הַקְּבָרִ֔ים הַזֹּבְחִ֖ים לָהֶֽם'),
(11939, 14, 'WLC', 'WLC', 'he', '2CH', 34, 5, 'OT', 'וְעַצְמוֹת֙ כֹּֽהֲנִ֔ים שָׂרַ֖ף עַל מזבחותים וַיְטַהֵ֥ר אֶת יְהוּדָ֖ה וְאֶת יְרוּשָׁלִָֽם'),
(11940, 14, 'WLC', 'WLC', 'he', '2CH', 34, 6, 'OT', 'וּבְעָרֵ֨י מְנַשֶּׁ֧ה וְאֶפְרַ֛יִם וְשִׁמְע֖וֹן וְעַד נַפְתָּלִ֑י בהר בתיהם סָבִֽיב'),
(11941, 14, 'WLC', 'WLC', 'he', '2CH', 34, 7, 'OT', 'וַיְנַתֵּ֣ץ אֶת הַֽמִּזְבְּח֗וֹת וְאֶת הָאֲשֵׁרִ֤ים וְהַפְּסִלִים֙ כִּתַּ֣ת לְהֵדַ֔ק וְכָל הַֽחַמָּנִ֥ים גִּדַּ֖ע בְּכָל אֶ֣רֶץ יִשְׂרָאֵ֑ל וַיָּ֖שָׁב לִירוּשָׁלִָֽם'),
(11942, 14, 'WLC', 'WLC', 'he', '2CH', 34, 8, 'OT', 'וּבִשְׁנַ֨ת שְׁמוֹנֶ֤ה עֶשְׂרֵה֙ לְמָלְכ֔וֹ לְטַהֵ֥ר הָאָ֖רֶץ וְהַבָּ֑יִת שָׁ֠לַח אֶת שָׁפָ֨ן בֶּן אֲצַלְיָ֜הוּ וְאֶת מַעֲשֵׂיָ֣הוּ שַׂר הָעִ֗יר וְ֠אֵת יוֹאָ֤ח בֶּן יֽוֹאָחָז֙ הַמַּזְכִּ֔יר לְחַזֵּ֕ק אֶת בֵּ֖ית יְהוָ֥ה אֱלֹהָֽיו'),
(11943, 14, 'WLC', 'WLC', 'he', '2CH', 34, 9, 'OT', 'וַיָּבֹ֜אוּ אֶל חִלְקִיָּ֣הוּ הַכֹּהֵ֣ן הַגָּד֗וֹל וַֽיִּתְּנוּ֮ אֶת הַכֶּסֶף֮ הַמּוּבָ֣א בֵית אֱלֹהִים֒ אֲשֶׁ֣ר אָסְפֽוּ הַלְוִיִּם֩ שֹׁמְרֵ֨י הַסַּ֜ף מִיַּ֧ד מְנַשֶּׁ֣ה וְאֶפְרַ֗יִם וּמִכֹּל֙ שְׁאֵרִ֣ית יִשְׂרָאֵ֔ל וּמִכָּל יְהוּדָ֖ה וּבִנְיָמִ֑ן וישבי יְרֽוּשָׁלִָֽם'),
(11944, 14, 'WLC', 'WLC', 'he', '2CH', 34, 10, 'OT', 'וַֽיִּתְּנ֗וּ עַל יַד֙ עֹשֵׂ֣ה הַמְּלָאכָ֔ה הַמֻּפְקָדִ֖ים בְּבֵ֣ית יְהוָ֑ה וַיִּתְּנ֨וּ אֹת֜וֹ עוֹשֵׂ֣י הַמְּלָאכָ֗ה אֲשֶׁ֤ר עֹשִׂים֙ בְּבֵ֣ית יְהוָ֔ה לִבְדּ֥וֹק וּלְחַזֵּ֖ק הַבָּֽיִת'),
(11945, 14, 'WLC', 'WLC', 'he', '2CH', 34, 11, 'OT', 'וַֽיִּתְּנ֗וּ לֶחָֽרָשִׁים֙ וְלַבֹּנִ֔ים לִקְנוֹת֙ אַבְנֵ֣י מַחְצֵ֔ב וְעֵצִ֖ים לַֽמְחַבְּר֑וֹת וּלְקָרוֹת֙ אֶת הַבָּ֣תִּ֔ים אֲשֶׁ֥ר הִשְׁחִ֖יתוּ מַלְכֵ֥י יְהוּדָֽה'),
(11946, 14, 'WLC', 'WLC', 'he', '2CH', 34, 12, 'OT', 'וְהָאֲנָשִׁים֩ עֹשִׂ֨ים בֶּאֱמוּנָ֜ה בַּמְּלָאכָ֗ה וַעֲלֵיהֶ֣ם מֻ֠פְקָדִים יַ֣חַת וְעֹבַדְיָ֤הוּ הַלְוִיִּם֙ מִן בְּנֵ֣י מְרָרִ֔י וּזְכַרְיָ֧ה וּמְשֻׁלָּ֛ם מִן בְּנֵ֥י הַקְּהָתִ֖ים לְנַצֵּ֑חַ וְהַ֨לְוִיִּ֔ם כָּל מֵבִ֖ין בִּכְלֵי שִֽׁיר'),
(11947, 14, 'WLC', 'WLC', 'he', '2CH', 34, 13, 'OT', 'וְעַ֣ל הַסַּבָּלִ֗ים וּֽמְנַצְּחִים֙ לְכֹל֙ עֹשֵׂ֣ה מְלָאכָ֔ה לַעֲבוֹדָ֖ה וַעֲבוֹדָ֑ה וּמֵֽהַלְוִיִּ֔ם סוֹפְרִ֥ים וְשֹׁטְרִ֖ים וְשׁוֹעֲרִֽים'),
(11948, 14, 'WLC', 'WLC', 'he', '2CH', 34, 14, 'OT', 'וּבְהוֹצִיאָ֣ם אֶת הַכֶּ֔סֶף הַמּוּבָ֖א בֵּ֣ית יְהוָ֑ה מָצָא֙ חִלְקִיָּ֣הוּ הַכֹּהֵ֔ן אֶת סֵ֥פֶר תּֽוֹרַת יְהוָ֖ה בְּיַד מֹשֶֽׁה'),
(11949, 14, 'WLC', 'WLC', 'he', '2CH', 34, 15, 'OT', 'וַיַּ֣עַן חִלְקִיָּ֗הוּ וַיֹּ֨אמֶר֙ אֶל שָׁפָ֣ן הַסּוֹפֵ֔ר סֵ֧פֶר הַתּוֹרָ֛ה מָצָ֖אתִי בְּבֵ֣ית יְהוָ֑ה וַיִּתֵּ֧ן חִלְקִיָּ֛הוּ אֶת הַסֵּ֖פֶר אֶל שָׁפָֽן'),
(11950, 14, 'WLC', 'WLC', 'he', '2CH', 34, 16, 'OT', 'וַיָּבֵ֨א שָׁפָ֤ן אֶת הַסֵּ֨פֶר֙ אֶל הַמֶּ֔לֶךְ וַיָּ֨שֶׁב ע֧וֹד אֶת הַמֶּ֛לֶךְ דָּבָ֖ר לֵאמֹ֑ר כֹּ֛ל אֲשֶׁר נִתַּ֥ן בְּיַד עֲבָדֶ֖יךָ הֵ֥ם עֹשִֽׂים'),
(11951, 14, 'WLC', 'WLC', 'he', '2CH', 34, 17, 'OT', 'וַיַּתִּ֕יכוּ אֶת הַכֶּ֖סֶף הַנִּמְצָ֣א בְּבֵית יְהוָ֑ה וַֽיִּתְּנ֗וּהוּ עַל יַד֙ הַמֻּפְקָדִ֔ים וְעַל יַ֖ד עוֹשֵׂ֥י הַמְּלָאכָֽה'),
(11952, 14, 'WLC', 'WLC', 'he', '2CH', 34, 18, 'OT', 'וַיַּגֵּ֞ד שָׁפָ֤ן הַסּוֹפֵר֙ לַמֶּ֣לֶךְ לֵאמֹ֔ר סֵ֚פֶר נָ֣תַן לִ֔י חִלְקִיָּ֖הוּ הַכֹּהֵ֑ן וַיִּקְרָא ב֥וֹ שָׁפָ֖ן לִפְנֵ֥י הַמֶּֽלֶךְ'),
(11953, 14, 'WLC', 'WLC', 'he', '2CH', 34, 19, 'OT', 'וַיְהִי֙ כִּשְׁמֹ֣עַ הַמֶּ֔לֶךְ אֵ֖ת דִּבְרֵ֣י הַתּוֹרָ֑ה וַיִּקְרַ֖ע אֶת בְּגָדָֽיו'),
(11954, 14, 'WLC', 'WLC', 'he', '2CH', 34, 20, 'OT', 'וַיְצַ֣ו הַמֶּ֡לֶךְ אֶת חִלְקִיָּ֡הוּ וְאֶת אֲחִיקָ֣ם בֶּן שָׁ֠פָן וְאֶת עַבְדּ֨וֹן בֶּן מִיכָ֜ה וְאֵ֣ת שָׁפָ֣ן הַסּוֹפֵ֗ר וְאֵ֛ת עֲשָׂיָ֥ה עֶֽבֶד הַמֶּ֖לֶךְ לֵאמֹֽר'),
(11955, 14, 'WLC', 'WLC', 'he', '2CH', 34, 21, 'OT', 'לְכוּ֩ דִרְשׁ֨וּ אֶת יְהוָ֜ה בַּעֲדִ֗י וּבְעַד֙ הַנִּשְׁאָר֙ בְּיִשְׂרָאֵ֣ל וּבִֽיהוּדָ֔ה עַל דִּבְרֵ֥י הַסֵּ֖פֶר אֲשֶׁ֣ר נִמְצָ֑א כִּֽי גְדוֹלָ֤ה חֲמַת יְהוָה֙ אֲשֶׁ֣ר נִתְּכָ֣ה בָ֔נוּ עַל֩ אֲשֶׁ֨ר לֹא שָׁמְר֤וּ אֲבוֹתֵ֨ינוּ֙ אֶת דְּבַ֣ר יְהוָ֔ה לַעֲשׂ֕וֹת כְּכָל הַכָּת֖וּב עַל הַסֵּ֥פֶר הַזֶּֽה'),
(11956, 14, 'WLC', 'WLC', 'he', '2CH', 34, 22, 'OT', 'וַיֵּ֨לֶךְ חִלְקִיָּ֜הוּ וַאֲשֶׁ֣ר הַמֶּ֗לֶךְ אֶל חֻלְדָּ֨ה הַנְּבִיאָ֜ה אֵ֣שֶׁת שַׁלֻּ֣ם בֶּן תוקהת בֶּן חַסְרָה֙ שׁוֹמֵ֣ר הַבְּגָדִ֔ים וְהִ֛יא יוֹשֶׁ֥בֶת בִּירוּשָׁלִַ֖ם בַּמִּשְׁנֶ֑ה וַיְדַבְּר֥וּ אֵלֶ֖יהָ כָּזֹֽאת'),
(11957, 14, 'WLC', 'WLC', 'he', '2CH', 34, 23, 'OT', 'וַתֹּ֣אמֶר לָהֶ֔ם כֹּה אָמַ֥ר יְהוָ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל אִמְר֣וּ לָאִ֔ישׁ אֲשֶׁר שָׁלַ֥ח אֶתְכֶ֖ם אֵלָֽי'),
(11958, 14, 'WLC', 'WLC', 'he', '2CH', 34, 24, 'OT', 'כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְנִ֨י מֵבִ֥יא רָעָ֛ה עַל הַמָּק֥וֹם הַזֶּ֖ה וְעַל יוֹשְׁבָ֑יו אֵ֤ת כָּל הָאָלוֹת֙ הַכְּתוּב֣וֹת עַל הַסֵּ֔פֶר אֲשֶׁ֣ר קָֽרְא֔וּ לִפְנֵ֖י מֶ֥לֶךְ יְהוּדָֽה'),
(11959, 14, 'WLC', 'WLC', 'he', '2CH', 34, 25, 'OT', 'תַּ֣חַת אֲשֶׁ֣ר עֲזָב֗וּנִי ויקטירו לֵֽאלֹהִ֣ים אֲחֵרִ֔ים לְמַ֨עַן֙ הַכְעִיסֵ֔נִי בְּכֹ֖ל מַעֲשֵׂ֣י יְדֵיהֶ֑ם וְתִתַּ֧ךְ חֲמָתִ֛י בַּמָּק֥וֹם הַזֶּ֖ה וְלֹ֥א תִכְבֶּֽה'),
(11960, 14, 'WLC', 'WLC', 'he', '2CH', 34, 26, 'OT', 'וְאֶל מֶ֣לֶךְ יְהוּדָ֗ה הַשֹּׁלֵ֤חַ אֶתְכֶם֙ לִדְר֣וֹשׁ בַּֽיהוָ֔ה כֹּ֥ה תֹאמְר֖וּ אֵלָ֑יו כֹּֽה אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הַדְּבָרִ֖ים אֲשֶׁ֥ר שָׁמָֽעְתָּ'),
(11961, 14, 'WLC', 'WLC', 'he', '2CH', 34, 27, 'OT', 'יַ֠עַן רַךְ לְבָ֨בְךָ֜ וַתִּכָּנַ֣ע מִלִּפְנֵ֣י אֱלֹהִ֗ים בְּשָׁמְעֲךָ֤ אֶת דְּבָרָיו֙ עַל הַמָּק֤וֹם הַזֶּה֙ וְעַל יֹ֣שְׁבָ֔יו וַתִּכָּנַ֣ע לְפָנַ֔י וַתִּקְרַ֥ע אֶת בְּגָדֶ֖יךָ וַתֵּ֣בְךְּ לְפָנָ֑י וְגַם אֲנִ֥י שָׁמַ֖עְתִּי נְאֻם יְהוָֽה'),
(11962, 14, 'WLC', 'WLC', 'he', '2CH', 34, 28, 'OT', 'הִנְנִ֨י אֹֽסִפְךָ֜ אֶל אֲבֹתֶ֗יךָ וְנֶאֱסַפְתָּ֣ אֶל קִבְרֹתֶיךָ֮ בְּשָׁלוֹם֒ וְלֹא תִרְאֶ֣ינָה עֵינֶ֔יךָ בְּכֹל֙ הָֽרָעָ֔ה אֲשֶׁ֨ר אֲנִ֥י מֵבִ֛יא עַל הַמָּק֥וֹם הַזֶּ֖ה וְעַל יֹשְׁבָ֑יו וַיָּשִׁ֥יבוּ אֶת הַמֶּ֖לֶךְ דָּבָֽר'),
(11963, 14, 'WLC', 'WLC', 'he', '2CH', 34, 29, 'OT', 'וַיִּשְׁלַ֖ח הַמֶּ֑לֶךְ וַיֶּאֱסֹ֕ף אֶת כָּל זִקְנֵ֥י יְהוּדָ֖ה וִירוּשָׁלִָֽם'),
(11964, 14, 'WLC', 'WLC', 'he', '2CH', 34, 30, 'OT', 'וַיַּ֣עַל הַמֶּ֣לֶךְ בֵּית יְ֠הוָה וְכָל אִ֨ישׁ יְהוּדָ֜ה וְיֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם וְהַכֹּֽהֲנִים֙ וְהַלְוִיִּ֔ם וְכָל הָעָ֖ם מִגָּד֣וֹל וְעַד קָטָ֑ן וַיִּקְרָ֣א בְאָזְנֵיהֶ֗ם אֶת כָּל דִּבְרֵי֙ סֵ֣פֶר הַבְּרִ֔ית הַנִּמְצָ֖א בֵּ֥ית יְהוָֽה'),
(11965, 14, 'WLC', 'WLC', 'he', '2CH', 34, 31, 'OT', 'וַיַּעֲמֹ֨ד הַמֶּ֜לֶךְ עַל עָמְד֗וֹ וַיִּכְרֹ֣ת אֶֽת הַבְּרִית֮ לִפְנֵ֣י יְהוָה֒ לָלֶ֜כֶת אַחֲרֵ֣י יְהוָ֗ה וְלִשְׁמ֤וֹר אֶת מִצְוֺתָיו֙ וְעֵֽדְוֺתָ֣יו וְחֻקָּ֔יו בְּכָל לְבָב֖וֹ וּבְכָל נַפְשׁ֑וֹ לַעֲשׂוֹת֙ אֶת דִּבְרֵ֣י הַבְּרִ֔ית הַכְּתוּבִ֖ים עַל הַסֵּ֥פֶר הַזֶּֽה'),
(11966, 14, 'WLC', 'WLC', 'he', '2CH', 34, 32, 'OT', 'וַיַּעֲמֵ֕ד אֵ֛ת כָּל הַנִּמְצָ֥א בִירוּשָׁלִַ֖ם וּבִנְיָמִ֑ן וַֽיַּעֲשׂוּ֙ יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם כִּבְרִ֥ית אֱלֹהִ֖ים אֱלֹהֵ֥י אֲבוֹתֵיהֶֽם'),
(11967, 14, 'WLC', 'WLC', 'he', '2CH', 34, 33, 'OT', 'וַיָּ֨סַר יֹֽאשִׁיָּ֜הוּ אֶת כָּל הַתּוֹעֵב֗וֹת מִֽכָּל הָאֲרָצוֹת֮ אֲשֶׁ֣ר לִבְנֵ֣י יִשְׂרָאֵל֒ וַֽיַּעֲבֵ֗ד אֵ֤ת כָּל הַנִּמְצָא֙ בְּיִשְׂרָאֵ֔ל לַעֲב֖וֹד אֶת יְהוָ֣ה אֱלֹהֵיהֶ֑ם כָּל יָמָ֕יו לֹ֣א סָ֔רוּ מֵֽאַחֲרֵ֕י יְהוָ֖ה אֱלֹהֵ֥י אֲבוֹתֵיהֶֽם'),
(11968, 14, 'WLC', 'WLC', 'he', '2CH', 35, 1, 'OT', 'וַיַּ֨עַשׂ יֹאשִׁיָּ֧הוּ בִֽירוּשָׁלִַ֛ם פֶּ֖סַח לַיהוָ֑ה וַיִּשְׁחֲט֣וּ הַפֶּ֔סַח בְּאַרְבָּעָ֥ה עָשָׂ֖ר לַחֹ֥דֶשׁ הָרִאשֽׁוֹן'),
(11969, 14, 'WLC', 'WLC', 'he', '2CH', 35, 2, 'OT', 'וַיַּעֲמֵ֥ד הַכֹּהֲנִ֖ים עַל מִשְׁמְרוֹתָ֑ם וַֽיְחַזְּקֵ֔ם לַעֲבוֹדַ֖ת בֵּ֥ית יְהוָֽה'),
(11970, 14, 'WLC', 'WLC', 'he', '2CH', 35, 3, 'OT', 'וַיֹּ֣אמֶר לַ֠לְוִיִּם המבונים לְכָל יִשְׂרָאֵ֜ל הַקְּדוֹשִׁ֣ים לַיהוָ֗ה תְּנ֤וּ אֶת אֲרוֹן הַקֹּ֨דֶשׁ֙ בַּ֠בַּיִת אֲשֶׁ֨ר בָּנָ֜ה שְׁלֹמֹ֤ה בֶן דָּוִיד֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל אֵין לָכֶ֥ם מַשָּׂ֖א בַּכָּתֵ֑ף עַתָּ֗ה עִבְדוּ֙ אֶת יְהוָ֣ה אֱלֹֽהֵיכֶ֔ם וְאֵ֖ת עַמּ֥וֹ יִשְׂרָאֵֽל'),
(11971, 14, 'WLC', 'WLC', 'he', '2CH', 35, 4, 'OT', 'וְהָכִ֥ונוּ לְבֵית אֲבוֹתֵיכֶ֖ם כְּמַחְלְקוֹתֵיכֶ֑ם בִּכְתָ֗ב דָּוִיד֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וּבְמִכְתַּ֖ב שְׁלֹמֹ֥ה בְנֽוֹ'),
(11972, 14, 'WLC', 'WLC', 'he', '2CH', 35, 5, 'OT', 'וְעִמְד֣וּ בַקֹּ֗דֶשׁ לִפְלֻגּוֹת֙ בֵּ֣ית הָֽאָב֔וֹת לַאֲחֵיכֶ֖ם בְּנֵ֣י הָעָ֑ם וַחֲלֻקַּ֥ת בֵּֽית אָ֖ב לַלְוִיִּֽם'),
(11973, 14, 'WLC', 'WLC', 'he', '2CH', 35, 6, 'OT', 'וְשַׁחֲט֖וּ הַפָּ֑סַח וְהִתְקַדְּשׁוּ֙ וְהָכִ֣ינוּ לַאֲחֵיכֶ֔ם לַעֲשׂ֥וֹת כִּדְבַר יְהוָ֖ה בְּיַד מֹשֶֽׁה'),
