(12215, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 13, 'OT', 'וּמִבְּנֵ֣י אֲדֹנִיקָם֮ אַחֲרֹנִים֒ וְאֵ֣לֶּה שְׁמוֹתָ֔ם אֱלִיפֶ֖לֶט יְעִיאֵ֣ל וּֽשְׁמַעְיָ֑ה וְעִמָּהֶ֖ם שִׁשִּׁ֥ים הַזְּכָרִֽים'),
(12216, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 14, 'OT', 'וּמִבְּנֵ֥י בִגְוַ֖י עוּתַ֣י וזבוד וְעִמּ֖וֹ שִׁבְעִ֥ים הַזְּכָרִֽים'),
(12217, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 15, 'OT', 'וָֽאֶקְבְּצֵ֗ם אֶל הַנָּהָר֙ הַבָּ֣א אֶֽל אַהֲוָ֔א וַנַּחֲנֶ֥ה שָׁ֖ם יָמִ֣ים שְׁלֹשָׁ֑ה וָאָבִ֤ינָה בָעָם֙ וּבַכֹּ֣הֲנִ֔ים וּמִבְּנֵ֥י לֵוִ֖י לֹא מָצָ֥אתִי שָֽׁם'),
(12218, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 16, 'OT', 'וָאֶשְׁלְחָ֡ה לֶאֱלִיעֶ֡זֶר לַאֲרִיאֵ֡ל לִֽ֠שְׁמַעְיָה וּלְאֶלְנָתָ֨ן וּלְיָרִ֜יב וּלְאֶלְנָתָ֧ן וּלְנָתָ֛ן וְלִזְכַרְיָ֥ה וְלִמְשֻׁלָּ֖ם רָאשִׁ֑ים וּלְיוֹיָרִ֥יב וּלְאֶלְנָתָ֖ן מְבִינִֽים'),
(12219, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 17, 'OT', 'ואוצאה אוֹתָם֙ עַל אִדּ֣וֹ הָרֹ֔אשׁ בְּכָסִפְיָ֖א הַמָּק֑וֹם וָאָשִׂימָה֩ בְּפִיהֶ֨ם דְּבָרִ֜ים לְ֠דַבֵּר אֶל אִדּ֨וֹ אָחִ֤יו הנתונים בְּכָסִפְיָ֣א הַמָּק֔וֹם לְהָֽבִיא לָ֥נוּ מְשָׁרְתִ֖ים לְבֵ֥ית אֱלֹהֵֽינוּ'),
(12220, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 18, 'OT', 'וַיָּבִ֨יאּוּ לָ֜נוּ כְּיַד אֱלֹהֵ֨ינוּ הַטּוֹבָ֤ה עָלֵ֨ינוּ֙ אִ֣ישׁ שֶׂ֔כֶל מִבְּנֵ֣י מַחְלִ֔י בֶּן לֵוִ֖י בֶּן יִשְׂרָאֵ֑ל וְשֵׁרֵֽבְיָ֛ה וּבָנָ֥יו וְאֶחָ֖יו שְׁמֹנָ֥ה עָשָֽׂר'),
(12221, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 19, 'OT', 'וְאֶת חֲשַׁבְיָ֔ה וְאִתּ֥וֹ יְשַֽׁעְיָ֖ה מִבְּנֵ֣י מְרָרִ֑י אֶחָ֥יו וּבְנֵיהֶ֖ם עֶשְׂרִֽים'),
(12222, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 20, 'OT', 'וּמִן הַנְּתִינִ֗ים שֶׁנָּתַ֨ן דָּוִ֤יד וְהַשָּׂרִים֙ לַעֲבֹדַ֣ת הַלְוִיִּ֔ם נְתִינִ֖ים מָאתַ֣יִם וְעֶשְׂרִ֑ים כֻּלָּ֖ם נִקְּב֥וּ בְשֵׁמֽוֹת'),
(12223, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 21, 'OT', 'וָאֶקְרָ֨א שָׁ֥ם צוֹם֙ עַל הַנָּהָ֣ר אַהֲוָ֔א לְהִתְעַנּ֖וֹת לִפְנֵ֣י אֱלֹהֵ֑ינוּ לְבַקֵּ֤שׁ מִמֶּ֨נּוּ֙ דֶּ֣רֶךְ יְשָׁרָ֔ה לָ֥נוּ וּלְטַפֵּ֖נוּ וּלְכָל רְכוּשֵֽׁנוּ'),
(12224, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 22, 'OT', 'כִּ֣י בֹ֗שְׁתִּי לִשְׁא֤וֹל מִן הַמֶּ֨לֶךְ֙ חַ֣יִל וּפָרָשִׁ֔ים לְעָזְרֵ֥נוּ מֵאוֹיֵ֖ב בַּדָּ֑רֶךְ כִּֽי אָמַ֨רְנוּ לַמֶּ֜לֶךְ לֵאמֹ֗ר יַד אֱלֹהֵ֤ינוּ עַל כָּל מְבַקְשָׁיו֙ לְטוֹבָ֔ה וְעֻזּ֣וֹ וְאַפּ֔וֹ עַ֖ל כָּל עֹזְבָֽיו'),
(12225, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 23, 'OT', 'וַנָּצ֛וּמָה וַנְּבַקְשָׁ֥ה מֵאֱלֹהֵ֖ינוּ עַל זֹ֑את וַיֵּעָתֵ֖ר לָֽנוּ'),
(12226, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 24, 'OT', 'וָאַבְדִּ֛ילָה מִשָּׂרֵ֥י הַכֹּהֲנִ֖ים שְׁנֵ֣ים עָשָׂ֑ר לְשֵׁרֵֽבְיָ֣ה חֲשַׁבְיָ֔ה וְעִמָּהֶ֥ם מֵאֲחֵיהֶ֖ם עֲשָׂרָֽה'),
(12227, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 25, 'OT', 'ואשקולה לָהֶ֔ם אֶת הַכֶּ֥סֶף וְאֶת הַזָּהָ֖ב וְאֶת הַכֵּלִ֑ים תְּרוּמַ֣ת בֵּית אֱלֹהֵ֗ינוּ הַהֵרִ֨ימוּ֙ הַמֶּ֨לֶךְ֙ וְיֹעֲצָ֣יו וְשָׂרָ֔יו וְכָל יִשְׂרָאֵ֖ל הַנִּמְצָאִֽים'),
(12228, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 26, 'OT', 'וָאֶשְׁקֲלָ֨ה עַל יָדָ֜ם כֶּ֗סֶף כִּכָּרִים֙ שֵֽׁשׁ מֵא֣וֹת וַחֲמִשִּׁ֔ים וּכְלֵי כֶ֥סֶף מֵאָ֖ה לְכִכָּרִ֑ים זָהָ֖ב מֵאָ֥ה כִכָּֽר'),
(12229, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 27, 'OT', 'וּכְפֹרֵ֤י זָהָב֙ עֶשְׂרִ֔ים לַאֲדַרְכֹנִ֖ים אָ֑לֶף וּכְלֵ֨י נְחֹ֜שֶׁת מֻצְהָ֤ב טוֹבָה֙ שְׁנַ֔יִם חֲמוּדֹ֖ת כַּזָּהָֽב'),
(12230, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 28, 'OT', 'וָאֹמְרָ֣ה אֲלֵהֶ֗ם אַתֶּ֥ם קֹ֨דֶשׁ֙ לַיהוָ֔ה וְהַכֵּלִ֖ים קֹ֑דֶשׁ וְהַכֶּ֤סֶף וְהַזָּהָב֙ נְדָבָ֔ה לַיהוָ֖ה אֱלֹהֵ֥י אֲבֹתֵיכֶֽם'),
(12231, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 29, 'OT', 'שִׁקְד֣וּ וְשִׁמְר֗וּ עַֽד תִּשְׁקְל֡וּ לִפְנֵי֩ שָׂרֵ֨י הַכֹּהֲנִ֧ים וְהַלְוִיִּ֛ם וְשָׂרֵֽי הָאָב֥וֹת לְיִשְׂרָאֵ֖ל בִּירוּשָׁלִָ֑ם הַלִּשְׁכ֖וֹת בֵּ֥ית יְהוָֽה'),
(12232, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 30, 'OT', 'וְקִבְּלוּ֙ הַכֹּהֲנִ֣ים וְהַלְוִיִּ֔ם מִשְׁקַ֛ל הַכֶּ֥סֶף וְהַזָּהָ֖ב וְהַכֵּלִ֑ים לְהָבִ֥יא לִירוּשָׁלִַ֖ם לְבֵ֥ית אֱלֹהֵֽינוּ'),
(12233, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 31, 'OT', 'וַֽנִּסְעָ֞ה מִנְּהַ֣ר אַֽהֲוָ֗א בִּשְׁנֵ֤ים עָשָׂר֙ לַחֹ֣דֶשׁ הָרִאשׁ֔וֹן לָלֶ֖כֶת יְרוּשָׁלִָ֑ם וְיַד אֱלֹהֵ֨ינוּ֙ הָיְתָ֣ה עָלֵ֔ינוּ וַיַּ֨צִּילֵ֔נוּ מִכַּ֥ף אוֹיֵ֛ב וְאוֹרֵ֖ב עַל הַדָּֽרֶךְ'),
(12234, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 32, 'OT', 'וַנָּב֖וֹא יְרוּשָׁלִָ֑ם וַנֵּ֥שֶׁב שָׁ֖ם יָמִ֥ים שְׁלֹשָֽׁה'),
(12235, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 33, 'OT', 'וּבַיּ֣וֹם הָרְבִיעִ֡י נִשְׁקַ֣ל הַכֶּסֶף֩ וְהַזָּהָ֨ב וְהַכֵּלִ֜ים בְּבֵ֣ית אֱלֹהֵ֗ינוּ עַ֠ל יַד מְרֵמ֤וֹת בֶּן אֽוּרִיָּה֙ הַכֹּהֵ֔ן וְעִמּ֖וֹ אֶלְעָזָ֣ר בֶּן פִּֽינְחָ֑ס וְעִמָּהֶ֞ם יוֹזָבָ֧ד בֶּן יֵשׁ֛וּעַ וְנֽוֹעַדְיָ֥ה בֶן בִּנּ֖וּי הַלְוִיִּֽם'),
(12236, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 34, 'OT', 'בְּמִסְפָּ֥ר בְּמִשְׁקָ֖ל לַכֹּ֑ל וַיִּכָּתֵ֥ב כָּֽל הַמִּשְׁקָ֖ל בָּעֵ֥ת הַהִֽיא'),
(12237, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 35, 'OT', 'הַ֠בָּאִים מֵֽהַשְּׁבִ֨י בְנֵֽי הַגּוֹלָ֜ה הִקְרִ֥יבוּ עֹל֣וֹת לֵאלֹהֵ֣י יִשְׂרָאֵ֗ל פָּרִ֨ים שְׁנֵים עָשָׂ֤ר עַל כָּל יִשְׂרָאֵל֙ אֵילִ֣ים תִּשְׁעִ֣ים וְשִׁשָּׁ֗ה כְּבָשִׂים֙ שִׁבְעִ֣ים וְשִׁבְעָ֔ה צְפִירֵ֥י חַטָּ֖את שְׁנֵ֣ים עָשָׂ֑ר הַכֹּ֖ל עוֹלָ֥ה לַיהוָֽה'),
(12238, 15, 'WLC', 'WLC', 'he', 'EZR', 8, 36, 'OT', 'וַֽיִּתְּנ֣וּ אֶת דָּתֵ֣י הַמֶּ֗לֶךְ לַאֲחַשְׁדַּרְפְּנֵי֙ הַמֶּ֔לֶךְ וּפַחֲו֖וֹת עֵ֣בֶר הַנָּהָ֑ר וְנִשְּׂא֥וּ אֶת הָעָ֖ם וְאֶת בֵּֽית הָאֱלֹהִֽים'),
(12239, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 1, 'OT', 'וּכְכַלּ֣וֹת אֵ֗לֶּה נִגְּשׁ֨וּ אֵלַ֤י הַשָּׂרִים֙ לֵאמֹ֔ר לֹֽא נִבְדְּל֞וּ הָעָ֤ם יִשְׂרָאֵל֙ וְהַכֹּהֲנִ֣ים וְהַלְוִיִּ֔ם מֵעַמֵּ֖י הָאֲרָצ֑וֹת כְּ֠תוֹעֲבֹֽתֵיהֶם לַכְּנַעֲנִ֨י הַחִתִּ֜י הַפְּרִזִּ֣י הַיְבוּסִ֗י הָֽעַמֹּנִי֙ הַמֹּ֣אָבִ֔י הַמִּצְרִ֖י וְהָאֱמֹרִֽי'),
(12240, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 2, 'OT', 'כִּֽי נָשְׂא֣וּ מִבְּנֹֽתֵיהֶ֗ם לָהֶם֙ וְלִבְנֵיהֶ֔ם וְהִתְעָֽרְבוּ֙ זֶ֣רַע הַקֹּ֔דֶשׁ בְּעַמֵּ֖י הָאֲרָצ֑וֹת וְיַ֧ד הַשָּׂרִ֣ים וְהַסְּגָנִ֗ים הָֽיְתָ֛ה בַּמַּ֥עַל הַזֶּ֖ה רִאשׁוֹנָֽה'),
(12241, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 3, 'OT', 'וּכְשָׁמְעִי֙ אֶת הַדָּבָ֣ר הַזֶּ֔ה קָרַ֥עְתִּי אֶת בִּגְדִ֖י וּמְעִילִ֑י וָאֶמְרְטָ֞ה מִשְּׂעַ֤ר רֹאשִׁי֙ וּזְקָנִ֔י וָאֵשְׁבָ֖ה מְשׁוֹמֵֽם'),
(12242, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 4, 'OT', 'וְאֵלַ֣י יֵאָסְפ֗וּ כֹּ֤ל חָרֵד֙ בְּדִבְרֵ֣י אֱלֹהֵֽי יִשְׂרָאֵ֔ל עַ֖ל מַ֣עַל הַגּוֹלָ֑ה וַאֲנִי֙ יֹשֵׁ֣ב מְשׁוֹמֵ֔ם עַ֖ד לְמִנְחַ֥ת הָעָֽרֶב'),
(12243, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 5, 'OT', 'וּבְמִנְחַ֣ת הָעֶ֗רֶב קַ֚מְתִּי מִתַּֽעֲנִיתִ֔י וּבְקָרְעִ֥י בִגְדִ֖י וּמְעִילִ֑י וָֽאֶכְרְעָה֙ עַל בִּרְכַּ֔י וָאֶפְרְשָׂ֥ה כַפַּ֖י אֶל יְהוָ֥ה אֱלֹהָֽי'),
(12244, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 6, 'OT', 'וָאֹמְרָ֗ה אֱלֹהַי֙ בֹּ֣שְׁתִּי וְנִכְלַ֔מְתִּי לְהָרִ֧ים אֱלֹהַ֛י פָּנַ֖י אֵלֶ֑יךָ כִּ֣י עֲוֺנֹתֵ֤ינוּ רָבוּ֙ לְמַ֣עְלָה רֹּ֔אשׁ וְאַשְׁמָתֵ֥נוּ גָדְלָ֖ה עַ֥ד לַשָּׁמָֽיִם'),
(12245, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 7, 'OT', 'מִימֵ֣י אֲבֹתֵ֗ינוּ אֲנַ֨חְנוּ֙ בְּאַשְׁמָ֣ה גְדֹלָ֔ה עַ֖ד הַיּ֣וֹם הַזֶּ֑ה וּבַעֲוֺנֹתֵ֡ינוּ נִתַּ֡נּוּ אֲנַחְנוּ֩ מְלָכֵ֨ינוּ כֹהֲנֵ֜ינוּ בְּיַ֣ד מַלְכֵ֣י הָאֲרָצ֗וֹת בַּחֶ֜רֶב בַּשְּׁבִ֧י וּבַבִּזָּ֛ה וּבְבֹ֥שֶׁת פָּנִ֖ים כְּהַיּ֥וֹם הַזֶּֽה'),
(12246, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 8, 'OT', 'וְעַתָּ֡ה כִּמְעַט רֶגַע֩ הָיְתָ֨ה תְחִנָּ֜ה מֵאֵ֣ת יְהוָ֣ה אֱלֹהֵ֗ינוּ לְהַשְׁאִ֥יר לָ֨נוּ֙ פְּלֵיטָ֔ה וְלָתֶת לָ֥נוּ יָתֵ֖ד בִּמְק֣וֹם קָדְשׁ֑וֹ לְהָאִ֤יר עֵינֵ֨ינוּ֙ אֱלֹהֵ֔ינוּ וּלְתִתֵּ֛נוּ מִֽחְיָ֥ה מְעַ֖ט בְּעַבְדֻתֵֽנוּ'),
(12247, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 9, 'OT', 'כִּֽי עֲבָדִ֣ים אֲנַ֔חְנוּ וּבְעַבְדֻ֔תֵנוּ לֹ֥א עֲזָבָ֖נוּ אֱלֹהֵ֑ינוּ וַֽיַּט עָלֵ֣ינוּ חֶ֡סֶד לִפְנֵי֩ מַלְכֵ֨י פָרַ֜ס לָֽתֶת לָ֣נוּ מִֽחְיָ֗ה לְרוֹמֵ֞ם אֶת בֵּ֤ית אֱלֹהֵ֨ינוּ֙ וּלְהַעֲמִ֣יד אֶת חָרְבֹתָ֔יו וְלָֽתֶת לָ֣נוּ גָדֵ֔ר בִּֽיהוּדָ֖ה וּבִירוּשָׁלִָֽם'),
(12248, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 10, 'OT', 'וְעַתָּ֛ה מַה נֹּאמַ֥ר אֱלֹהֵ֖ינוּ אַֽחֲרֵי זֹ֑את כִּ֥י עָזַ֖בְנוּ מִצְוֺתֶֽיךָ'),
(12249, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 11, 'OT', 'אֲשֶׁ֣ר צִוִּ֗יתָ בְּיַ֨ד עֲבָדֶ֣יךָ הַנְּבִיאִים֮ לֵאמֹר֒ הָאָ֗רֶץ אֲשֶׁ֨ר אַתֶּ֤ם בָּאִים֙ לְרִשְׁתָּ֔הּ אֶ֤רֶץ נִדָּה֙ הִ֔יא בְּנִדַּ֖ת עַמֵּ֣י הָאֲרָצ֑וֹת בְּתוֹעֲבֹֽתֵיהֶ֗ם אֲשֶׁ֥ר מִלְא֛וּהָ מִפֶּ֥ה אֶל פֶּ֖ה בְּטֻמְאָתָֽם'),
(12250, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 12, 'OT', 'וְ֠עַתָּה בְּֽנוֹתֵיכֶ֞ם אַל תִּתְּנ֣וּ לִבְנֵיהֶ֗ם וּבְנֹֽתֵיהֶם֙ אַל תִּשְׂא֣וּ לִבְנֵיכֶ֔ם וְלֹֽא תִדְרְשׁ֧וּ שְׁלֹמָ֛ם וְטוֹבָתָ֖ם עַד עוֹלָ֑ם לְמַ֣עַן תֶּחֶזְק֗וּ וַאֲכַלְתֶּם֙ אֶת ט֣וּב הָאָ֔רֶץ וְהוֹרַשְׁתֶּ֥ם לִבְנֵיכֶ֖ם עַד עוֹלָֽם'),
(12251, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 13, 'OT', 'וְאַֽחֲרֵי֙ כָּל הַבָּ֣א עָלֵ֔ינוּ בְּמַעֲשֵׂ֨ינוּ֙ הָרָעִ֔ים וּבְאַשְׁמָתֵ֖נוּ הַגְּדֹלָ֑ה כִּ֣י אַתָּ֣ה אֱלֹהֵ֗ינוּ חָשַׂ֤כְתָּֽ לְמַ֨טָּה֙ מֵֽעֲוֺנֵ֔נוּ וְנָתַ֥תָּה לָּ֛נוּ פְּלֵיטָ֖ה כָּזֹֽאת'),
(12252, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 14, 'OT', 'הֲנָשׁוּב֙ לְהָפֵ֣ר מִצְוֺתֶ֔יךָ וּ֨לְהִתְחַתֵּ֔ן בְּעַמֵּ֥י הַתֹּעֵב֖וֹת הָאֵ֑לֶּה הֲל֤וֹא תֶֽאֱנַף בָּ֨נוּ֙ עַד כַּלֵּ֔ה לְאֵ֥ין שְׁאֵרִ֖ית וּפְלֵיטָֽה'),
(12253, 15, 'WLC', 'WLC', 'he', 'EZR', 9, 15, 'OT', 'יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ צַדִּ֣יק אַ֔תָּה כִּֽי נִשְׁאַ֥רְנוּ פְלֵיטָ֖ה כְּהַיּ֣וֹם הַזֶּ֑ה הִנְנ֤וּ לְפָנֶ֨יךָ֙ בְּאַשְׁמָתֵ֔ינוּ כִּ֣י אֵ֥ין לַעֲמ֛וֹד לְפָנֶ֖יךָ עַל זֹֽאת'),
(12254, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 1, 'OT', 'וּכְהִתְפַּלֵּ֤ל עֶזְרָא֙ וּכְ֨הִתְוַדֹּת֔וֹ בֹּכֶה֙ וּמִתְנַפֵּ֔ל לִפְנֵ֖י בֵּ֣ית הָאֱלֹהִ֑ים נִקְבְּצוּ֩ אֵלָ֨יו מִיִּשְׂרָאֵ֜ל קָהָ֣ל רַב מְאֹ֗ד אֲנָשִׁ֤ים וְנָשִׁים֙ וִֽילָדִ֔ים כִּֽי בָכ֥וּ הָעָ֖ם הַרְבֵּה בֶֽכֶה'),
(12255, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 2, 'OT', 'וַיַּעַן֩ שְׁכַנְיָ֨ה בֶן יְחִיאֵ֜ל מִבְּנֵ֤י עולם וַיֹּ֣אמֶר לְעֶזְרָ֔א אֲנַ֨חְנוּ֙ מָעַ֣לְנוּ בֵאלֹהֵ֔ינוּ וַנֹּ֛שֶׁב נָשִׁ֥ים נָכְרִיּ֖וֹת מֵעַמֵּ֣י הָאָ֑רֶץ וְעַתָּ֛ה יֵשׁ מִקְוֶ֥ה לְיִשְׂרָאֵ֖ל עַל זֹֽאת'),
(12256, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 3, 'OT', 'וְעַתָּ֣ה נִֽכְרָת בְּרִ֣ית לֵ֠אלֹהֵינוּ לְהוֹצִ֨יא כָל נָשִׁ֜ים וְהַנּוֹלָ֤ד מֵהֶם֙ בַּעֲצַ֣ת אֲדֹנָ֔י וְהַחֲרֵדִ֖ים בְּמִצְוַ֣ת אֱלֹהֵ֑ינוּ וְכַתּוֹרָ֖ה יֵעָשֶֽׂה'),
(12257, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 4, 'OT', 'ק֛וּם כִּֽי עָלֶ֥יךָ הַדָּבָ֖ר וַאֲנַ֣חְנוּ עִמָּ֑ךְ חֲזַ֖ק וַעֲשֵֽׂה'),
(12258, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 5, 'OT', 'וַיָּ֣קָם עֶזְרָ֡א וַיַּשְׁבַּ֣ע אֶת שָׂרֵי֩ הַכֹּהֲנִ֨ים הַלְוִיִּ֜ם וְכָל יִשְׂרָאֵ֗ל לַעֲשׂ֛וֹת כַּדָּבָ֥ר הַזֶּ֖ה וַיִּשָּׁבֵֽעוּ'),
(12259, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 6, 'OT', 'וַיָּ֣קָם עֶזְרָ֗א מִלִּפְנֵי֙ בֵּ֣ית הָֽאֱלֹהִ֔ים וַיֵּ֕לֶךְ אֶל לִשְׁכַּ֖ת יְהוֹחָנָ֣ן בֶּן אֶלְיָשִׁ֑יב וַיֵּ֣לֶךְ שָׁ֗ם לֶ֤חֶם לֹֽא אָכַל֙ וּמַ֣יִם לֹֽא שָׁתָ֔ה כִּ֥י מִתְאַבֵּ֖ל עַל מַ֥עַל הַגּוֹלָֽה'),
(12260, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 7, 'OT', 'וַיַּעֲבִ֨ירוּ ק֜וֹל בִּיהוּדָ֣ה וִירֽוּשָׁלִַ֗ם לְכֹל֙ בְּנֵ֣י הַגּוֹלָ֔ה לְהִקָּבֵ֖ץ יְרוּשָׁלִָֽם'),
(12261, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 8, 'OT', 'וְכֹל֩ אֲשֶׁ֨ר לֹֽא יָב֜וֹא לִשְׁלֹ֣שֶׁת הַיָּמִ֗ים כַּעֲצַ֤ת הַשָּׂרִים֙ וְהַזְּקֵנִ֔ים יָחֳרַ֖ם כָּל רְכוּשׁ֑וֹ וְה֥וּא יִבָּדֵ֖ל מִקְּהַ֥ל הַגּוֹלָֽה'),
(12262, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 9, 'OT', 'וַיִּקָּבְצ֣וּ כָל אַנְשֵֽׁי יְהוּדָה֩ וּבִנְיָמִ֨ן יְרוּשָׁלִַ֜ם לִשְׁלֹ֣שֶׁת הַיָּמִ֗ים ה֛וּא חֹ֥דֶשׁ הַתְּשִׁיעִ֖י בְּעֶשְׂרִ֣ים בַּחֹ֑דֶשׁ וַיֵּשְׁב֣וּ כָל הָעָ֗ם בִּרְחוֹב֙ בֵּ֣ית הָאֱלֹהִ֔ים מַרְעִידִ֥ים עַל הַדָּבָ֖ר וּמֵהַגְּשָׁמִֽים'),
(12263, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 10, 'OT', 'וַיָּ֨קָם עֶזְרָ֤א הַכֹּהֵן֙ וַיֹּ֣אמֶר אֲלֵהֶ֔ם אַתֶּ֣ם מְעַלְתֶּ֔ם וַתֹּשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת לְהוֹסִ֖יף עַל אַשְׁמַ֥ת יִשְׂרָאֵֽל'),
(12264, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 11, 'OT', 'וְעַתָּ֗ה תְּנ֥וּ תוֹדָ֛ה לַיהוָ֥ה אֱלֹהֵֽי אֲבֹתֵיכֶ֖ם וַעֲשׂ֣וּ רְצוֹנ֑וֹ וְהִבָּֽדְלוּ֙ מֵעַמֵּ֣י הָאָ֔רֶץ וּמִן הַנָּשִׁ֖ים הַנָּכְרִיּֽוֹת'),
(12265, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 12, 'OT', 'וַיַּֽעְנ֧וּ כָֽל הַקָּהָ֛ל וַיֹּאמְר֖וּ ק֣וֹל גָּד֑וֹל כֵּ֛ן כדבריך עָלֵ֖ינוּ לַעֲשֽׂוֹת'),
(12266, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 13, 'OT', 'אֲבָ֞ל הָעָ֥ם רָב֙ וְהָעֵ֣ת גְּשָׁמִ֔ים וְאֵ֥ין כֹּ֖חַ לַעֲמ֣וֹד בַּח֑וּץ וְהַמְּלָאכָ֗ה לֹֽא לְי֤וֹם אֶחָד֙ וְלֹ֣א לִשְׁנַ֔יִם כִּֽי הִרְבִּ֥ינוּ לִפְשֹׁ֖עַ בַּדָּבָ֥ר הַזֶּֽה'),
(12267, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 14, 'OT', 'יַֽעֲמְדוּ נָ֣א שָׂ֠רֵינוּ לְֽכָל הַקָּהָ֞ל וְכֹ֣ל אֲשֶׁ֣ר בֶּעָרֵ֗ינוּ הַהֹשִׁ֞יב נָשִׁ֤ים נָכְרִיּוֹת֙ יָבֹא֙ לְעִתִּ֣ים מְזֻמָּנִ֔ים וְעִמָּהֶ֛ם זִקְנֵי עִ֥יר וָעִ֖יר וְשֹׁפְטֶ֑יהָ עַ֠ד לְהָשִׁ֞יב חֲר֤וֹן אַף אֱלֹהֵ֨ינוּ֙ מִמֶּ֔נּוּ עַ֖ד לַדָּבָ֥ר הַזֶּֽה'),
(12268, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 15, 'OT', 'אַ֣ךְ יוֹנָתָ֧ן בֶּן עֲשָׂהאֵ֛ל וְיַחְזְיָ֥ה בֶן תִּקְוָ֖ה עָמְד֣וּ עַל זֹ֑את וּמְשֻׁלָּ֛ם וְשַׁבְּתַ֥י הַלֵּוִ֖י עֲזָרֻֽם'),
(12269, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 16, 'OT', 'וַיַּֽעֲשׂוּ כֵן֮ בְּנֵ֣י הַגּוֹלָה֒ וַיִּבָּדְלוּ֩ עֶזְרָ֨א הַכֹּהֵ֜ן אֲנָשִׁ֨ים רָאשֵׁ֧י הָאָב֛וֹת לְבֵ֥ית אֲבֹתָ֖ם וְכֻלָּ֣ם בְּשֵׁמ֑וֹת וַיֵּשְׁב֗וּ בְּי֤וֹם אֶחָד֙ לַחֹ֣דֶשׁ הָעֲשִׂירִ֔י לְדַרְי֖וֹשׁ הַדָּבָֽר'),
(12270, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 17, 'OT', 'וַיְכַלּ֣וּ בַכֹּ֔ל אֲנָשִׁ֕ים הַהֹשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת עַ֛ד י֥וֹם אֶחָ֖ד לַחֹ֥דֶשׁ הָרִאשֽׁוֹן'),
(12271, 15, 'WLC', 'WLC', 'he', 'EZR', 10, 18, 'OT', 'וַיִּמָּצֵא֙ מִבְּנֵ֣י הַכֹּהֲנִ֔ים אֲשֶׁ֥ר הֹשִׁ֖יבוּ נָשִׁ֣ים נָכְרִיּ֑וֹת מִבְּנֵ֨י יֵשׁ֤וּעַ בֶּן יֽוֹצָדָק֙ וְאֶחָ֔יו מַֽעֲשֵׂיָה֙ וֶֽאֱלִיעֶ֔זֶר וְיָרִ֖יב וּגְדַלְיָֽה'),
