(12314, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 6, 'OT', 'וַיֹּאמֶר֩ לִ֨י הַמֶּ֜לֶךְ וְהַשֵּׁגַ֣ל יוֹשֶׁ֣בֶת אֶצְל֗וֹ עַד מָתַ֛י יִהְיֶ֥ה מַֽהֲלָכֲךָ֖ וּמָתַ֣י תָּשׁ֑וּב וַיִּיטַ֤ב לִפְנֵֽי הַמֶּ֨לֶךְ֙ וַיִּשְׁלָחֵ֔נִי וָֽאֶתְּנָ֥ה ל֖וֹ זְמָֽן'),
(12315, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 7, 'OT', 'וָאוֹמַר֮ לַמֶּלֶךְ֒ אִם עַל הַמֶּ֣לֶךְ ט֔וֹב אִגְּרוֹת֙ יִתְּנוּ לִ֔י עַֽל פַּחֲו֖וֹת עֵ֣בֶר הַנָּהָ֑ר אֲשֶׁר֙ יַעֲבִיר֔וּנִי עַ֥ד אֲשֶׁר אָב֖וֹא אֶל יְהוּדָֽה'),
(12316, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 8, 'OT', 'וְאִגֶּ֡רֶת אֶל אָסָף֩ שֹׁמֵ֨ר הַפַּרְדֵּ֜ס אֲשֶׁ֣ר לַמֶּ֗לֶךְ אֲשֶׁ֣ר יִתֶּן לִ֣י עֵצִ֡ים לְ֠קָרוֹת אֶת שַׁעֲרֵ֨י הַבִּירָ֤ה אֲשֶׁר לַבַּ֨יִת֙ וּלְחוֹמַ֣ת הָעִ֔יר וְלַבַּ֖יִת אֲשֶׁר אָב֣וֹא אֵלָ֑יו וַיִּתֶּן לִ֣י הַמֶּ֔לֶךְ כְּיַד אֱלֹהַ֖י הַטּוֹבָ֥ה עָלָֽי'),
(12317, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 9, 'OT', 'וָֽאָב֗וֹא אֶֽל פַּֽחֲווֹת֙ עֵ֣בֶר הַנָּהָ֔ר וָאֶתְּנָ֣ה לָהֶ֔ם אֵ֖ת אִגְּר֣וֹת הַמֶּ֑לֶךְ וַיִּשְׁלַ֤ח עִמִּי֙ הַמֶּ֔לֶךְ שָׂ֥רֵי חַ֖יִל וּפָרָשִֽׁים'),
(12318, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 10, 'OT', 'וַיִּשְׁמַ֞ע סַנְבַלַּ֣ט הַחֹרֹנִ֗י וְטֽוֹבִיָּה֙ הָעֶ֣בֶד הָֽעַמֹּנִ֔י וַיֵּ֥רַע לָהֶ֖ם רָעָ֣ה גְדֹלָ֑ה אֲשֶׁר בָּ֥א אָדָ֔ם לְבַקֵּ֥שׁ טוֹבָ֖ה לִבְנֵ֥י יִשְׂרָאֵֽל'),
(12319, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 11, 'OT', 'וָאָב֖וֹא אֶל יְרוּשָׁלִָ֑ם וָאֱהִי שָׁ֖ם יָמִ֥ים שְׁלֹשָֽׁה'),
(12320, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 12, 'OT', 'וָאָק֣וּם לַ֗יְלָה אֲנִי֮ וַאֲנָשִׁ֣ים מְעַט֮ עִמִּי֒ וְלֹא הִגַּ֣דְתִּי לְאָדָ֔ם מָ֗ה אֱלֹהַי֙ נֹתֵ֣ן אֶל לִבִּ֔י לַעֲשׂ֖וֹת לִירוּשָׁלִָ֑ם וּבְהֵמָה֙ אֵ֣ין עִמִּ֔י כִּ֚י אִם הַבְּהֵמָ֔ה אֲשֶׁ֥ר אֲנִ֖י רֹכֵ֥ב בָּֽהּ'),
(12321, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 13, 'OT', 'וָאֵצְאָ֨ה בְשַֽׁעַר הַגַּ֜יא לַ֗יְלָה וְאֶל פְּנֵי֙ עֵ֣ין הַתַּנִּ֔ין וְאֶל שַׁ֖עַר הָאַשְׁפֹּ֑ת וָאֱהִ֨י שֹׂבֵ֜ר בְּחוֹמֹ֤ת יְרוּשָׁלִַ֨ם֙ אֲשֶׁר המפרוצים וּשְׁעָרֶ֖יהָ אֻכְּל֥וּ בָאֵֽשׁ'),
(12322, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 14, 'OT', 'וָאֶֽעֱבֹר֙ אֶל שַׁ֣עַר הָעַ֔יִן וְאֶל בְּרֵכַ֖ת הַמֶּ֑לֶךְ וְאֵין מָק֥וֹם לַבְּהֵמָ֖ה לַעֲבֹ֥ר תַּחְתָּֽי'),
(12323, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 15, 'OT', 'וָאֱהִ֨י עֹלֶ֤ה בַנַּ֨חַל֙ לַ֔יְלָה וָאֱהִ֥י שֹׂבֵ֖ר בַּחוֹמָ֑ה וָאָשׁ֗וּב וָאָב֛וֹא בְּשַׁ֥עַר הַגַּ֖יְא וָאָשֽׁוּב'),
(12324, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 16, 'OT', 'וְהַסְּגָנִ֗ים לֹ֤א יָדְעוּ֙ אָ֣נָה הָלַ֔כְתִּי וּמָ֖ה אֲנִ֣י עֹשֶׂ֑ה וְלַיְּהוּדִ֨ים וְלַכֹּהֲנִ֜ים וְלַחֹרִ֣ים וְלַסְּגָנִ֗ים וּלְיֶ֨תֶר֙ עֹשֵׂ֣ה הַמְּלָאכָ֔ה עַד כֵּ֖ן לֹ֥א הִגַּֽדְתִּי'),
(12325, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 17, 'OT', 'וָאוֹמַ֣ר אֲלֵהֶ֗ם אַתֶּ֤ם רֹאִים֙ הָרָעָה֙ אֲשֶׁ֣ר אֲנַ֣חְנוּ בָ֔הּ אֲשֶׁ֤ר יְרוּשָׁלִַ֨ם֙ חֲרֵבָ֔ה וּשְׁעָרֶ֖יהָ נִצְּת֣וּ בָאֵ֑שׁ לְכ֗וּ וְנִבְנֶה֙ אֶת חוֹמַ֣ת יְרוּשָׁלִַ֔ם וְלֹא נִהְיֶ֥ה ע֖וֹד חֶרְפָּֽה'),
(12326, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 18, 'OT', 'וָאַגִּ֨יד לָהֶ֜ם אֶת יַ֣ד אֱלֹהַ֗י אֲשֶׁר הִיא֙ טוֹבָ֣ה עָלַ֔י וְאַף דִּבְרֵ֥י הַמֶּ֖לֶךְ אֲשֶׁ֣ר אָֽמַר לִ֑י וַיֹּֽאמְרוּ֙ נָק֣וּם וּבָנִ֔ינוּ וַיְחַזְּק֥וּ יְדֵיהֶ֖ם לַטּוֹבָֽה'),
(12327, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 19, 'OT', 'וַיִּשְׁמַע֩ סַנְבַלַּ֨ט הַחֹרֹנִ֜י וְטֹבִיָּ֣ה הָעֶ֣בֶד הָֽעַמּוֹנִ֗י וְגֶ֨שֶׁם֙ הָֽעַרְבִ֔י וַיַּלְעִ֣גוּ לָ֔נוּ וַיִּבְז֖וּ עָלֵ֑ינוּ וַיֹּאמְר֗וּ מָֽה הַדָּבָ֤ר הַזֶּה֙ אֲשֶׁ֣ר אַתֶּ֣ם עֹשִׂ֔ים הַעַ֥ל הַמֶּ֖לֶךְ אַתֶּ֥ם מֹרְדִֽים'),
(12328, 16, 'WLC', 'WLC', 'he', 'NEH', 2, 20, 'OT', 'וָאָשִׁ֨יב אוֹתָ֜ם דָּבָ֗ר וָאוֹמַ֤ר לָהֶם֙ אֱלֹהֵ֣י הַשָּׁמַ֔יִם ה֚וּא יַצְלִ֣יחַֽ לָ֔נוּ וַאֲנַ֥חְנוּ עֲבָדָ֖יו נָק֣וּם וּבָנִ֑ינוּ וְלָכֶ֗ם אֵֽין חֵ֧לֶק וּצְדָקָ֛ה וְזִכָּר֖וֹן בִּירוּשָׁלִָֽם'),
(12329, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 1, 'OT', 'וַיָּ֡קָם אֶלְיָשִׁיב֩ הַכֹּהֵ֨ן הַגָּד֜וֹל וְאֶחָ֣יו הַכֹּהֲנִ֗ים וַיִּבְנוּ֙ אֶת שַׁ֣עַר הַצֹּ֔אן הֵ֣מָּה קִדְּשׁ֔וּהוּ וַֽיַּעֲמִ֖ידוּ דַּלְתֹתָ֑יו וְעַד מִגְדַּ֤ל הַמֵּאָה֙ קִדְּשׁ֔וּהוּ עַ֖ד מִגְדַּ֥ל חֲנַנְאֵֽל'),
(12330, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 2, 'OT', 'וְעַל יָד֥וֹ בָנ֖וּ אַנְשֵׁ֣י יְרֵח֑וֹ וְעַל יָד֣וֹ בָנָ֔ה זַכּ֖וּר בֶּן אִמְרִֽי'),
(12331, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 3, 'OT', 'וְאֵת֙ שַׁ֣עַר הַדָּגִ֔ים בָּנ֖וּ בְּנֵ֣י הַסְּנָאָ֑ה הֵ֣מָּה קֵר֔וּהוּ וַֽיַּעֲמִ֨ידוּ֙ דַּלְתֹתָ֔יו מַנְעוּלָ֖יו וּבְרִיחָֽיו'),
(12332, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 4, 'OT', 'וְעַל יָדָ֣ם הֶחֱזִ֗יק מְרֵמ֤וֹת בֶּן אוּרִיָּה֙ בֶּן הַקּ֔וֹץ וְעַל יָדָ֣ם הֶחֱזִ֔יק מְשֻׁלָּ֥ם בֶּן בֶּרֶכְיָ֖ה בֶּן מְשֵׁיזַבְאֵ֑ל וְעַל יָדָ֣ם הֶֽחֱזִ֔יק צָד֖וֹק בֶּֽן בַּעֲנָֽא'),
(12333, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 5, 'OT', 'וְעַל יָדָ֖ם הֶחֱזִ֣יקוּ הַתְּקוֹעִ֑ים וְאַדִּֽירֵיהֶם֙ לֹא הֵבִ֣יאוּ צַוָּרָ֔ם בַּעֲבֹדַ֖ת אֲדֹנֵיהֶֽם'),
(12334, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 6, 'OT', 'וְאֵת֩ שַׁ֨עַר הַיְשָׁנָ֜ה הֶחֱזִ֗יקוּ יֽוֹיָדָע֙ בֶּן פָּסֵ֔חַ וּמְשֻׁלָּ֖ם בֶּן בְּסֽוֹדְיָ֑ה הֵ֣מָּה קֵר֔וּהוּ וַֽיַּעֲמִ֨ידוּ֙ דַּלְתֹתָ֔יו וּמַנְעֻלָ֖יו וּבְרִיחָֽיו'),
(12335, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 7, 'OT', 'וְעַל יָדָ֨ם הֶחֱזִ֜יק מְלַטְיָ֣ה הַגִּבְעֹנִ֗י וְיָדוֹן֙ הַמֵּרֹ֣נֹתִ֔י אַנְשֵׁ֥י גִבְע֖וֹן וְהַמִּצְפָּ֑ה לְכִסֵּ֕א פַּחַ֖ת עֵ֥בֶר הַנָּהָֽר'),
(12336, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 8, 'OT', 'עַל יָד֣וֹ הֶחֱזִ֗יק עֻזִּיאֵ֤ל בֶּֽן חַרְהֲיָה֙ צֽוֹרְפִ֔ים וְעַל יָד֣וֹ הֶחֱזִ֔יק חֲנַנְיָ֖ה בֶּן הָרַקָּחִ֑ים וַיַּֽעַזְבוּ֙ יְר֣וּשָׁלִַ֔ם עַ֖ד הַחוֹמָ֥ה הָרְחָבָֽה'),
(12337, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 9, 'OT', 'וְעַל יָדָ֤ם הֶחֱזִיק֙ רְפָיָ֣ה בֶן ח֔וּר שַׂ֕ר חֲצִ֖י פֶּ֥לֶךְ יְרוּשָׁלִָֽם'),
(12338, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 10, 'OT', 'וְעַל יָדָ֧ם הֶחֱזִ֛יק יְדָיָ֥ה בֶן חֲרוּמַ֖ף וְנֶ֣גֶד בֵּית֑וֹ וְעַל יָד֣וֹ הֶחֱזִ֔יק חַטּ֖וּשׁ בֶּן חֲשַׁבְנְיָֽה'),
(12339, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 11, 'OT', 'מִדָּ֣ה שֵׁנִ֗ית הֶחֱזִיק֙ מַלְכִּיָּ֣ה בֶן חָרִ֔ם וְחַשּׁ֖וּב בֶּן פַּחַ֣ת מוֹאָ֑ב וְאֵ֖ת מִגְדַּ֥ל הַתַּנּוּרִֽים'),
(12340, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 12, 'OT', 'וְעַל יָד֣וֹ הֶחֱזִ֗יק שַׁלּוּם֙ בֶּן הַלּוֹחֵ֔שׁ שַׂ֕ר חֲצִ֖י פֶּ֣לֶךְ יְרוּשָׁלִָ֑ם ה֖וּא וּבְנוֹתָֽיו'),
(12341, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 13, 'OT', 'אֵת֩ שַׁ֨עַר הַגַּ֜יְא הֶחֱזִ֣יק חָנוּן֮ וְיֹשְׁבֵ֣י זָנוֹחַ֒ הֵ֣מָּה בָנ֔וּהוּ וַֽיַּעֲמִ֨ידוּ֙ דַּלְתֹתָ֔יו מַנְעֻלָ֖יו וּבְרִיחָ֑יו וְאֶ֤לֶף אַמָּה֙ בַּחוֹמָ֔ה עַ֖ד שַׁ֥עַר הָשֲׁפֽוֹת'),
(12342, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 14, 'OT', 'וְאֵ֣ת שַׁ֣עַר הָאַשְׁפּ֗וֹת הֶחֱזִיק֙ מַלְכִּיָּ֣ה בֶן רֵכָ֔ב שַׂ֖ר פֶּ֣לֶךְ בֵּית הַכָּ֑רֶם ה֣וּא יִבְנֶ֔נּוּ וְיַעֲמִיד֙ דַּלְתֹתָ֔יו מַנְעֻלָ֖יו וּבְרִיחָֽיו'),
(12343, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 15, 'OT', 'וְאֵת֩ שַׁ֨עַר הָעַ֜יִן הֶ֠חֱזִיק שַׁלּ֣וּן בֶּן כָּל חֹזֶה֮ שַׂ֣ר פֶּ֣לֶךְ הַמִּצְפָּה֒ ה֤וּא יִבְנֶ֨נּוּ֙ וִיטַֽלְלֶ֔נּוּ ויעמידו דַּלְתֹתָ֔יו מַנְעֻלָ֖יו וּבְרִיחָ֑יו וְ֠אֵת חוֹמַ֞ת בְּרֵכַ֤ת הַשֶּׁ֨לַח֙ לְגַן הַמֶּ֔לֶךְ וְעַד הַֽמַּעֲל֔וֹת הַיּוֹרְד֖וֹת מֵעִ֥יר דָּוִֽיד'),
(12344, 16, 'WLC', 'WLC', 'he', 'NEH', 3, 16, 'OT', 'אַחֲרָ֤יו הֶחֱזִיק֙ נְחֶמְיָ֣ה בֶן עַזְבּ֔וּק שַׂ֕ר חֲצִ֖י פֶּ֣לֶךְ בֵּֽית צ֑וּר עַד נֶ֨גֶד֙ קִבְרֵ֣י דָוִ֔יד וְעַד הַבְּרֵכָה֙ הָעֲשׂוּיָ֔ה וְעַ֖ד בֵּ֥ית הַגִּבֹּרִֽים'),
