(12379, 16, 'WLC', 'WLC', 'he', 'NEH', 4, 19, 'OT', 'וָאֹמַ֞ר אֶל הַחֹרִ֤ים וְאֶל הַסְּגָנִים֙ וְאֶל יֶ֣תֶר הָעָ֔ם הַמְּלָאכָ֥ה הַרְבֵּ֖ה וּרְחָבָ֑ה וַאֲנַ֗חְנוּ נִפְרָדִים֙ עַל הַ֣חוֹמָ֔ה רְחוֹקִ֖ים אִ֥ישׁ מֵאָחִֽיו'),
(12380, 16, 'WLC', 'WLC', 'he', 'NEH', 4, 20, 'OT', 'בִּמְק֗וֹם אֲשֶׁ֤ר תִּשְׁמְעוּ֙ אֶת ק֣וֹל הַשּׁוֹפָ֔ר שָׁ֖מָּה תִּקָּבְצ֣וּ אֵלֵ֑ינוּ אֱלֹהֵ֖ינוּ יִלָּ֥חֶם לָֽנוּ'),
(12381, 16, 'WLC', 'WLC', 'he', 'NEH', 4, 21, 'OT', 'וַאֲנַ֖חְנוּ עֹשִׂ֣ים בַּמְּלָאכָ֑ה וְחֶצְיָ֗ם מַחֲזִיקִים֙ בָּֽרְמָחִ֔ים מֵעֲל֣וֹת הַשַּׁ֔חַר עַ֖ד צֵ֥את הַכּוֹכָבִֽים'),
(12382, 16, 'WLC', 'WLC', 'he', 'NEH', 4, 22, 'OT', 'גַּ֣ם בָּעֵ֤ת הַהִיא֙ אָמַ֣רְתִּי לָעָ֔ם אִ֣ישׁ וְנַעֲר֔וֹ יָלִ֖ינוּ בְּת֣וֹךְ יְרוּשָׁלִָ֑ם וְהָֽיוּ לָ֧נוּ הַלַּ֛יְלָה מִשְׁמָ֖ר וְהַיּ֥וֹם מְלָאכָֽה'),
(12383, 16, 'WLC', 'WLC', 'he', 'NEH', 4, 23, 'OT', 'וְאֵ֨ין אֲנִ֜י וְאַחַ֣י וּנְעָרַ֗י וְאַנְשֵׁ֤י הַמִּשְׁמָר֙ אֲשֶׁ֣ר אַחֲרַ֔י אֵין אֲנַ֥חְנוּ פֹשְׁטִ֖ים בְּגָדֵ֑ינוּ אִ֖ישׁ שִׁלְח֥וֹ הַמָּֽיִם'),
(12384, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 1, 'OT', 'וַתְּהִ֨י צַעֲקַ֥ת הָעָ֛ם וּנְשֵׁיהֶ֖ם גְּדוֹלָ֑ה אֶל אֲחֵיהֶ֖ם הַיְּהוּדִֽים'),
(12385, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 2, 'OT', 'וְיֵשׁ֙ אֲשֶׁ֣ר אֹמְרִ֔ים בָּנֵ֥ינוּ וּבְנֹתֵ֖ינוּ אֲנַ֣חְנוּ רַבִּ֑ים וְנִקְחָ֥ה דָגָ֖ן וְנֹאכְלָ֥ה וְנִחְיֶֽה'),
(12386, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 3, 'OT', 'וְיֵשׁ֙ אֲשֶׁ֣ר אֹמְרִ֔ים שְׂדֹתֵ֛ינוּ וּכְרָמֵ֥ינוּ וּבָתֵּ֖ינוּ אֲנַ֣חְנוּ עֹרְבִ֑ים וְנִקְחָ֥ה דָגָ֖ן בָּרָעָֽב'),
(12387, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 4, 'OT', 'וְיֵשׁ֙ אֲשֶׁ֣ר אֹמְרִ֔ים לָוִ֥ינוּ כֶ֖סֶף לְמִדַּ֣ת הַמֶּ֑לֶךְ שְׂדֹתֵ֖ינוּ וּכְרָמֵֽינוּ'),
(12388, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 5, 'OT', 'וְעַתָּ֗ה כִּבְשַׂ֤ר אַחֵ֨ינוּ֙ בְּשָׂרֵ֔נוּ כִּבְנֵיהֶ֖ם בָּנֵ֑ינוּ וְהִנֵּ֣ה אֲנַ֣חְנוּ כֹ֠בְשִׁים אֶת בָּנֵ֨ינוּ וְאֶת בְּנֹתֵ֜ינוּ לַעֲבָדִ֗ים וְיֵ֨שׁ מִבְּנֹתֵ֤ינוּ נִכְבָּשׁוֹת֙ וְאֵ֣ין לְאֵ֣ל יָדֵ֔נוּ וּשְׂדֹתֵ֥ינוּ וּכְרָמֵ֖ינוּ לַאֲחֵרִֽים'),
(12389, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 6, 'OT', 'וַיִּ֥חַר לִ֖י מְאֹ֑ד כַּאֲשֶׁ֤ר שָׁמַ֨עְתִּי֙ אֶת זַֽעֲקָתָ֔ם וְאֵ֖ת הַדְּבָרִ֥ים הָאֵֽלֶּה'),
(12390, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 7, 'OT', 'וַיִּמָּלֵ֨ךְ לִבִּ֜י עָלַ֗י וָאָרִ֨יבָה֙ אֶת הַחֹרִ֣ים וְאֶת הַסְּגָנִ֔ים וָאֹמְרָ֣ה לָהֶ֔ם מַשָּׁ֥א אִישׁ בְּאָחִ֖יו אַתֶּ֣ם נשאים וָאֶתֵּ֥ן עֲלֵיהֶ֖ם קְהִלָּ֥ה גְדוֹלָֽה'),
(12391, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 8, 'OT', 'וָאֹמְרָ֣ה לָהֶ֗ם אֲנַ֣חְנוּ קָ֠נִינוּ אֶת אַחֵ֨ינוּ הַיְּהוּדִ֜ים הַנִּמְכָּרִ֤ים לַגּוֹיִם֙ כְּדֵ֣י בָ֔נוּ וְגַם אַתֶּ֛ם תִּמְכְּר֥וּ אֶת אֲחֵיכֶ֖ם וְנִמְכְּרוּ לָ֑נוּ וַֽיַּחֲרִ֔ישׁוּ וְלֹ֥א מָצְא֖וּ דָּבָֽר'),
(12392, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 9, 'OT', 'ויאמר לֹא ט֥וֹב הַדָּבָ֖ר אֲשֶׁר אַתֶּ֣ם עֹשִׂ֑ים הֲל֞וֹא בְּיִרְאַ֤ת אֱלֹהֵ֨ינוּ֙ תֵּלֵ֔כוּ מֵחֶרְפַּ֖ת הַגּוֹיִ֥ם אוֹיְבֵֽינוּ'),
(12393, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 10, 'OT', 'וְגַם אֲנִי֙ אַחַ֣י וּנְעָרַ֔י נֹשִׁ֥ים בָּהֶ֖ם כֶּ֣סֶף וְדָגָ֑ן נַֽעַזְבָה נָּ֖א אֶת הַמַּשָּׁ֥א הַזֶּֽה'),
(12394, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 11, 'OT', 'הָשִׁיבוּ֩ נָ֨א לָהֶ֜ם כְּהַיּ֗וֹם שְׂדֹתֵיהֶ֛ם כַּרְמֵיהֶ֥ם זֵיתֵיהֶ֖ם וּבָתֵּיהֶ֑ם וּמְאַ֨ת הַכֶּ֤סֶף וְהַדָּגָן֙ הַתִּיר֣וֹשׁ וְהַיִּצְהָ֔ר אֲשֶׁ֥ר אַתֶּ֖ם נֹשִׁ֥ים בָּהֶֽם'),
(12395, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 12, 'OT', 'וַיֹּאמְר֣וּ נָשִׁ֗יב וּמֵהֶם֙ לֹ֣א נְבַקֵּ֔שׁ כֵּ֣ן נַעֲשֶׂ֔ה כַּאֲשֶׁ֖ר אַתָּ֣ה אוֹמֵ֑ר וָאֶקְרָא֙ אֶת הַכֹּ֣הֲנִ֔ים וָֽאַשְׁבִּיעֵ֔ם לַעֲשׂ֖וֹת כַּדָּבָ֥ר הַזֶּֽה'),
(12396, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 13, 'OT', 'גַּם חָצְנִ֣י נָעַ֗רְתִּי וָֽאֹמְרָ֡ה כָּ֣כָה יְנַעֵ֪ר הָֽאֱלֹהִ֟ים אֶת כָּל הָאִישׁ֩ אֲשֶׁ֨ר לֹֽא יָקִ֜ים אֶת הַדָּבָ֣ר הַזֶּ֗ה מִבֵּיתוֹ֙ וּמִ֣יגִיע֔וֹ וְכָ֛כָה יִהְיֶ֥ה נָע֖וּר וָרֵ֑ק וַיֹּאמְר֨וּ כָֽל הַקָּהָ֜ל אָמֵ֗ן וַֽיְהַלְלוּ֙ אֶת יְהוָ֔ה וַיַּ֥עַשׂ הָעָ֖ם כַּדָּבָ֥ר הַזֶּֽה'),
(12397, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 14, 'OT', 'גַּ֞ם מִיּ֣וֹם אֲשֶׁר צִוָּ֣ה אֹתִ֗י לִהְי֣וֹת פֶּחָם֮ בְּאֶ֣רֶץ יְהוּדָה֒ מִשְּׁנַ֣ת עֶשְׂרִ֗ים וְ֠עַד שְׁנַ֨ת שְׁלֹשִׁ֤ים וּשְׁתַּ֨יִם֙ לְאַרְתַּחְשַׁ֣סְתְּא הַמֶּ֔לֶךְ שָׁנִ֖ים שְׁתֵּ֣ים עֶשְׂרֵ֑ה אֲנִ֣י וְאַחַ֔י לֶ֥חֶם הַפֶּ֖חָה לֹ֥א אָכַֽלְתִּי'),
(12398, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 15, 'OT', 'וְהַפַּחוֹת֩ הָרִאשֹׁנִ֨ים אֲשֶׁר לְפָנַ֜י הִכְבִּ֣ידוּ עַל הָעָ֗ם וַיִּקְח֨וּ מֵהֶ֜ם בְּלֶ֤חֶם וָיַ֨יִן֙ אַחַר֙ כֶּֽסֶף שְׁקָלִ֣ים אַרְבָּעִ֔ים גַּ֥ם נַעֲרֵיהֶ֖ם שָׁלְט֣וּ עַל הָעָ֑ם וַאֲנִי֙ לֹא עָשִׂ֣יתִי כֵ֔ן מִפְּנֵ֖י יִרְאַ֥ת אֱלֹהִֽים'),
(12399, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 16, 'OT', 'וְ֠גַם בִּמְלֶ֜אכֶת הַחוֹמָ֤ה הַזֹּאת֙ הֶחֱזַ֔קְתִּי וְשָׂדֶ֖ה לֹ֣א קָנִ֑ינוּ וְכָל נְעָרַ֔י קְבוּצִ֥ים שָׁ֖ם עַל הַמְּלָאכָֽה'),
(12400, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 17, 'OT', 'וְהַיְּהוּדִ֨ים וְהַסְּגָנִ֜ים מֵאָ֧ה וַחֲמִשִּׁ֣ים אִ֗ישׁ וְהַבָּאִ֥ים אֵלֵ֛ינוּ מִן הַגּוֹיִ֥ם אֲשֶׁר סְבִיבֹתֵ֖ינוּ עַל שֻׁלְחָנִֽי'),
(12401, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 18, 'OT', 'וַאֲשֶׁר֩ הָיָ֨ה נַעֲשֶׂ֜ה לְי֣וֹם אֶחָ֗ד שׁ֣וֹר אֶחָ֞ד צֹ֠אן שֵׁשׁ בְּרֻר֤וֹת וְצִפֳּרִים֙ נַֽעֲשׂוּ לִ֔י וּבֵ֨ין עֲשֶׂ֧רֶת יָמִ֛ים בְּכָל יַ֖יִן לְהַרְבֵּ֑ה וְעִם זֶ֗ה לֶ֤חֶם הַפֶּחָה֙ לֹ֣א בִקַּ֔שְׁתִּי כִּֽי כָֽבְדָ֥ה הָעֲבֹדָ֖ה עַל הָעָ֥ם הַזֶּֽה'),
(12402, 16, 'WLC', 'WLC', 'he', 'NEH', 5, 19, 'OT', 'זָכְרָה לִּ֥י אֱלֹהַ֖י לְטוֹבָ֑ה כֹּ֥ל אֲשֶׁר עָשִׂ֖יתִי עַל הָעָ֥ם הַזֶּֽה'),
(12403, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 1, 'OT', 'וַיְהִ֣י כַאֲשֶׁ֣ר נִשְׁמַ֣ע לְסַנְבַלַּ֣ט וְ֠טוֹבִיָּה וּלְגֶ֨שֶׁם הָֽעַרְבִ֜י וּלְיֶ֣תֶר אֹֽיְבֵ֗ינוּ כִּ֤י בָנִ֨יתִי֙ אֶת הַ֣חוֹמָ֔ה וְלֹא נ֥וֹתַר בָּ֖הּ פָּ֑רֶץ גַּ֚ם עַד הָעֵ֣ת הַהִ֔יא דְּלָת֖וֹת לֹא הֶעֱמַ֥דְתִּי בַשְּׁעָרִֽים'),
(12404, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 2, 'OT', 'וַיִּשְׁלַ֨ח סַנְבַלַּ֤ט וְגֶ֨שֶׁם֙ אֵלַ֣י לֵאמֹ֔ר לְכָ֞ה וְנִֽוָּעֲדָ֥ה יַחְדָּ֛ו בַּכְּפִירִ֖ים בְּבִקְעַ֣ת אוֹנ֑וֹ וְהֵ֨מָּה֙ חֹֽשְׁבִ֔ים לַעֲשׂ֥וֹת לִ֖י רָעָֽה'),
(12405, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 3, 'OT', 'וָאֶשְׁלְחָ֨ה עֲלֵיהֶ֤ם מַלְאָכִים֙ לֵאמֹ֔ר מְלָאכָ֤ה גְדוֹלָה֙ אֲנִ֣י עֹשֶׂ֔ה וְלֹ֥א אוּכַ֖ל לָרֶ֑דֶת לָ֣מָּה תִשְׁבַּ֤ת הַמְּלָאכָה֙ כַּאֲשֶׁ֣ר אַרְפֶּ֔הָ וְיָרַדְתִּ֖י אֲלֵיכֶֽם'),
(12406, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 4, 'OT', 'וַיִּשְׁלְח֥וּ אֵלַ֛י כַּדָּבָ֥ר הַזֶּ֖ה אַרְבַּ֣ע פְּעָמִ֑ים וָאָשִׁ֥יב אוֹתָ֖ם כַּדָּבָ֥ר הַזֶּֽה'),
(12407, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 5, 'OT', 'וַיִּשְׁלַח֩ אֵלַ֨י סַנְבַלַּ֜ט כַּדָּבָ֥ר הַזֶּ֛ה פַּ֥עַם חֲמִישִׁ֖ית אֶֽת נַעֲר֑וֹ וְאִגֶּ֥רֶת פְּתוּחָ֖ה בְּיָדֽוֹ'),
(12408, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 6, 'OT', 'כָּת֣וּב בָּ֗הּ בַּגּוֹיִ֤ם נִשְׁמָע֙ וְגַשְׁמ֣וּ אֹמֵ֔ר אַתָּ֤ה וְהַיְּהוּדִים֙ חֹשְׁבִ֣ים לִמְר֔וֹד עַל כֵּ֛ן אַתָּ֥ה בוֹנֶ֖ה הַחוֹמָ֑ה וְאַתָּ֗ה הֹוֶ֤ה לָהֶם֙ לְמֶ֔לֶךְ כַּדְּבָרִ֖ים הָאֵֽלֶּה'),
(12409, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 7, 'OT', 'וְגַם נְבִיאִ֡ים הֶעֱמַ֣דְתָּ לִקְרֹא֩ עָלֶ֨יךָ בִֽירוּשָׁלִַ֜ם לֵאמֹ֗ר מֶ֚לֶךְ בִּֽיהוּדָ֔ה וְעַתָּה֙ יִשָּׁמַ֣ע לַמֶּ֔לֶךְ כַּדְּבָרִ֣ים הָאֵ֑לֶּה וְעַתָּ֣ה לְכָ֔ה וְנִֽוָּעֲצָ֖ה יַחְדָּֽו'),
(12410, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 8, 'OT', 'וָאֶשְׁלְחָ֤ה אֵלָיו֙ לֵאמֹ֔ר לֹ֤א נִֽהְיָה֙ כַּדְּבָרִ֣ים הָאֵ֔לֶּה אֲשֶׁ֖ר אַתָּ֣ה אוֹמֵ֑ר כִּ֥י מִֽלִּבְּךָ֖ אַתָּ֥ה בוֹדָֽאם'),
(12411, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 9, 'OT', 'כִּ֣י כֻלָּ֗ם מְיָֽרְאִ֤ים אוֹתָ֨נוּ֙ לֵאמֹ֔ר יִרְפּ֧וּ יְדֵיהֶ֛ם מִן הַמְּלָאכָ֖ה וְלֹ֣א תֵעָשֶׂ֑ה וְעַתָּ֖ה חַזֵּ֥ק אֶת יָדָֽי'),
(12412, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 10, 'OT', 'וַאֲנִי בָ֗אתִי בֵּ֣ית שְֽׁמַֽעְיָ֧ה בֶן דְּלָיָ֛ה בֶּן מְהֵֽיטַבְאֵ֖ל וְה֣וּא עָצ֑וּר וַיֹּ֡אמֶר נִוָּעֵד֩ אֶל בֵּ֨ית הָאֱלֹהִ֜ים אֶל תּ֣וֹךְ הַֽהֵיכָ֗ל וְנִסְגְּרָה֙ דַּלְת֣וֹת הַהֵיכָ֔ל כִּ֚י בָּאִ֣ים לְהָרְגֶ֔ךָ וְלַ֖יְלָה בָּאִ֥ים לְהָרְגֶֽךָ'),
(12413, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 11, 'OT', 'וָאֹמְרָ֗ה הַאִ֤ישׁ כָּמ֨וֹנִי֙ יִבְרָ֔ח וּמִ֥י כָמ֛וֹנִי אֲשֶׁר יָב֥וֹא אֶל הַהֵיכָ֖ל וָחָ֑י לֹ֖א אָבֽוֹא'),
(12414, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 12, 'OT', 'וָאַכִּ֕ירָה וְהִנֵּ֥ה לֹֽא אֱלֹהִ֖ים שְׁלָח֑וֹ כִּ֤י הַנְּבוּאָה֙ דִּבֶּ֣ר עָלַ֔י וְטוֹבִיָּ֥ה וְסַנְבַלַּ֖ט שְׂכָרֽוֹ'),
(12415, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 13, 'OT', 'לְמַ֤עַן שָׂכוּר֙ ה֔וּא לְמַֽעַן אִירָ֥א וְאֶֽעֱשֶׂה כֵּ֖ן וְחָטָ֑אתִי וְהָיָ֤ה לָהֶם֙ לְשֵׁ֣ם רָ֔ע לְמַ֖עַן יְחָֽרְפֽוּנִי'),
(12416, 16, 'WLC', 'WLC', 'he', 'NEH', 6, 14, 'OT', 'זָכְרָ֧ה אֱלֹהַ֛י לְטוֹבִיָּ֥ה וּלְסַנְבַלַּ֖ט כְּמַעֲשָׂ֣יו אֵ֑לֶּה וְגַ֨ם לְנוֹעַדְיָ֤ה הַנְּבִיאָה֙ וּלְיֶ֣תֶר הַנְּבִיאִ֔ים אֲשֶׁ֥ר הָי֖וּ מְיָֽרְאִ֥ים אוֹתִֽי'),
