(12498, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 4, 'OT', 'וַֽיַּעֲמֹ֞ד עֶזְרָ֣א הַסֹּפֵ֗ר עַֽל מִגְדַּל עֵץ֮ אֲשֶׁ֣ר עָשׂ֣וּ לַדָּבָר֒ וַיַּֽעֲמֹ֣ד אֶצְל֡וֹ מַתִּתְיָ֡ה וְשֶׁ֡מַע וַ֠עֲנָיָה וְאוּרִיָּ֧ה וְחִלְקִיָּ֛ה וּמַעֲשֵׂיָ֖ה עַל יְמִינ֑וֹ וּמִשְּׂמֹאל֗וֹ פְּ֠דָיָה וּמִֽישָׁאֵ֧ל וּמַלְכִּיָּ֛ה וְחָשֻׁ֥ם וְחַשְׁבַּדָּ֖נָה זְכַרְיָ֥ה מְשֻׁלָּֽם'),
(12499, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 5, 'OT', 'וַיִּפְתַּ֨ח עֶזְרָ֤א הַסֵּ֨פֶר֙ לְעֵינֵ֣י כָל הָעָ֔ם כִּֽי מֵעַ֥ל כָּל הָעָ֖ם הָיָ֑ה וּכְפִתְח֖וֹ עָֽמְד֥וּ כָל הָעָֽם'),
(12500, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 6, 'OT', 'וַיְבָ֣רֶךְ עֶזְרָ֔א אֶת יְהוָ֥ה הָאֱלֹהִ֖ים הַגָּד֑וֹל וַיַּֽעֲנ֨וּ כָל הָעָ֜ם אָמֵ֤ן אָמֵן֙ בְּמֹ֣עַל יְדֵיהֶ֔ם וַיִּקְּד֧וּ וַיִּשְׁתַּחֲוֻּ֛ לַיהוָ֖ה אַפַּ֥יִם אָֽרְצָה'),
(12501, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 7, 'OT', 'וְיֵשׁ֡וּעַ וּבָנִ֡י וְשֵׁרֵ֥בְיָ֣ה יָמִ֡ין עַקּ֡וּב שַׁבְּתַ֣י הֽוֹדִיָּ֡ה מַעֲשֵׂיָ֡ה קְלִיטָ֣א עֲזַרְיָה֩ יוֹזָבָ֨ד חָנָ֤ן פְּלָאיָה֙ וְהַלְוִיִּ֔ם מְבִינִ֥ים אֶת הָעָ֖ם לַתּוֹרָ֑ה וְהָעָ֖ם עַל עָמְדָֽם'),
(12502, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 8, 'OT', 'וַֽיִּקְרְא֥וּ בַסֵּ֛פֶר בְּתוֹרַ֥ת הָאֱלֹהִ֖ים מְפֹרָ֑שׁ וְשׂ֣וֹם שֶׂ֔כֶל וַיָּבִ֖ינוּ בַּמִּקְרָֽא'),
(12503, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 9, 'OT', 'וַיֹּ֣אמֶר נְחֶמְיָ֣ה ה֣וּא הַתִּרְשָׁ֡תָא וְעֶזְרָ֣א הַכֹּהֵ֣ן הַסֹּפֵ֡ר וְהַלְוִיִּם֩ הַמְּבִינִ֨ים אֶת הָעָ֜ם לְכָל הָעָ֗ם הַיּ֤וֹם קָדֹֽשׁ הוּא֙ לַיהוָ֣ה אֱלֹהֵיכֶ֔ם אַל תִּֽתְאַבְּל֖וּ וְאַל תִּבְכּ֑וּ כִּ֤י בוֹכִים֙ כָּל הָעָ֔ם כְּשָׁמְעָ֖ם אֶת דִּבְרֵ֥י הַתּוֹרָֽה'),
(12504, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 10, 'OT', 'וַיֹּ֣אמֶר לָהֶ֡ם לְכוּ֩ אִכְל֨וּ מַשְׁמַנִּ֜ים וּשְׁת֣וּ מַֽמְתַקִּ֗ים וְשִׁלְח֤וּ מָנוֹת֙ לְאֵ֣ין נָכ֣וֹן ל֔וֹ כִּֽי קָד֥וֹשׁ הַיּ֖וֹם לַאֲדֹנֵ֑ינוּ וְאַל תֵּ֣עָצֵ֔בוּ כִּֽי חֶדְוַ֥ת יְהוָ֖ה הִ֥יא מָֽעֻזְּכֶֽם'),
(12505, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 11, 'OT', 'וְהַלְוִיִּ֞ם מַחְשִׁ֤ים לְכָל הָעָם֙ לֵאמֹ֣ר הַ֔סּוּ כִּ֥י הַיּ֖וֹם קָדֹ֑שׁ וְאַל תֵּעָצֵֽבוּ'),
(12506, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 12, 'OT', 'וַיֵּלְכ֨וּ כָל הָעָ֜ם לֶאֱכֹ֤ל וְלִשְׁתּוֹת֙ וּלְשַׁלַּ֣ח מָנ֔וֹת וְלַעֲשׂ֖וֹת שִׂמְחָ֣ה גְדוֹלָ֑ה כִּ֤י הֵבִ֨ינוּ֙ בַּדְּבָרִ֔ים אֲשֶׁ֥ר הוֹדִ֖יעוּ לָהֶֽם'),
(12507, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 13, 'OT', 'וּבַיּ֣וֹם הַשֵּׁנִ֡י נֶאֶסְפוּ֩ רָאשֵׁ֨י הָאָב֜וֹת לְכָל הָעָ֗ם הַכֹּֽהֲנִים֙ וְהַלְוִיִּ֔ם אֶל עֶזְרָ֖א הַסֹּפֵ֑ר וּלְהַשְׂכִּ֖יל אֶל דִּבְרֵ֥י הַתּוֹרָֽה'),
(12508, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 14, 'OT', 'וַֽיִּמְצְא֖וּ כָּת֣וּב בַּתּוֹרָ֑ה אֲשֶׁ֨ר צִוָּ֤ה יְהוָה֙ בְּיַד מֹשֶׁ֔ה אֲשֶׁר֩ יֵשְׁב֨וּ בְנֵֽי יִשְׂרָאֵ֧ל בַּסֻּכּ֛וֹת בֶּחָ֖ג בַּחֹ֥דֶשׁ הַשְּׁבִיעִֽי'),
(12509, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 15, 'OT', 'וַאֲשֶׁ֣ר יַשְׁמִ֗יעוּ וְיַעֲבִ֨ירוּ ק֥וֹל בְּכָל עָרֵיהֶם֮ וּבִירוּשָׁלִַ֣ם לֵאמֹר֒ צְא֣וּ הָהָ֗ר וְהָבִ֨יאוּ֙ עֲלֵי זַ֨יִת֙ וַעֲלֵי עֵ֣ץ שֶׁ֔מֶן וַעֲלֵ֤י הֲדַס֙ וַעֲלֵ֣י תְמָרִ֔ים וַעֲלֵ֖י עֵ֣ץ עָבֹ֑ת לַעֲשֹׂ֥ת סֻכֹּ֖ת כַּכָּתֽוּב'),
(12510, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 16, 'OT', 'וַיֵּצְא֣וּ הָעָם֮ וַיָּבִיאוּ֒ וַיַּעֲשׂוּ֩ לָהֶ֨ם סֻכּ֜וֹת אִ֤ישׁ עַל גַּגּוֹ֙ וּבְחַצְרֹ֣תֵיהֶ֔ם וּבְחַצְר֖וֹת בֵּ֣ית הָאֱלֹהִ֑ים וּבִרְחוֹב֙ שַׁ֣עַר הַמַּ֔יִם וּבִרְח֖וֹב שַׁ֥עַר אֶפְרָֽיִם'),
(12511, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 17, 'OT', 'וַיַּֽעֲשׂ֣וּ כָֽל הַ֠קָּהָל הַשָּׁבִ֨ים מִן הַשְּׁבִ֥י סֻכּוֹת֮ וַיֵּשְׁב֣וּ בַסֻּכּוֹת֒ כִּ֣י לֹֽא עָשׂ֡וּ מִימֵי֩ יֵשׁ֨וּעַ בִּן נ֥וּן כֵּן֙ בְּנֵ֣י יִשְׂרָאֵ֔ל עַ֖ד הַיּ֣וֹם הַה֑וּא וַתְּהִ֥י שִׂמְחָ֖ה גְּדוֹלָ֥ה מְאֹֽד'),
(12512, 16, 'WLC', 'WLC', 'he', 'NEH', 8, 18, 'OT', 'וַ֠יִּקְרָא בְּסֵ֨פֶר תּוֹרַ֤ת הָאֱלֹהִים֙ י֣וֹם בְּי֔וֹם מִן הַיּוֹם֙ הָֽרִאשׁ֔וֹן עַ֖ד הַיּ֣וֹם הָאַחֲר֑וֹן וַיַּֽעֲשׂוּ חָג֙ שִׁבְעַ֣ת יָמִ֔ים וּבַיּ֧וֹם הַשְּׁמִינִ֛י עֲצֶ֖רֶת כַּמִּשְׁפָּֽט'),
(12513, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 1, 'OT', 'וּבְיוֹם֩ עֶשְׂרִ֨ים וְאַרְבָּעָ֜ה לַחֹ֣דֶשׁ הַזֶּ֗ה נֶאֶסְפ֤וּ בְנֵֽי יִשְׂרָאֵל֙ בְּצ֣וֹם וּבְשַׂקִּ֔ים וַאֲדָמָ֖ה עֲלֵיהֶֽם'),
(12514, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 2, 'OT', 'וַיִּבָּֽדְלוּ֙ זֶ֣רַע יִשְׂרָאֵ֔ל מִכֹּ֖ל בְּנֵ֣י נֵכָ֑ר וַיַּעַמְד֗וּ וַיִּתְוַדּוּ֙ עַל חַטֹּ֣אתֵיהֶ֔ם וַעֲוֺנ֖וֹת אֲבֹתֵיהֶֽם'),
(12515, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 3, 'OT', 'וַיָּק֨וּמוּ֙ עַל עָמְדָ֔ם וַֽיִּקְרְא֗וּ בְּסֵ֨פֶר תּוֹרַ֧ת יְהוָ֛ה אֱלֹהֵיהֶ֖ם רְבִעִ֣ית הַיּ֑וֹם וּרְבִעִית֙ מִתְוַדִּ֣ים וּמִֽשְׁתַּחֲוִ֔ים לַיהוָ֖ה אֱלֹהֵיהֶֽם'),
(12516, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 4, 'OT', 'וַיָּ֜קָם עַֽל מַֽעֲלֵ֣ה הַלְוִיִּ֗ם יֵשׁ֨וּעַ וּבָנִ֜י קַדְמִיאֵ֧ל שְׁבַנְיָ֛ה בֻּנִּ֥י שֵׁרֵבְיָ֖ה בָּנִ֣י כְנָ֑נִי וַֽיִּזְעֲקוּ֙ בְּק֣וֹל גָּד֔וֹל אֶל יְהוָ֖ה אֱלֹהֵיהֶֽם'),
(12517, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 5, 'OT', 'וַיֹּאמְר֣וּ הַלְוִיִּ֡ם יֵשׁ֣וּעַ וְ֠קַדְמִיאֵל בָּנִ֨י חֲשַׁבְנְיָ֜ה שֵׁרֵֽבְיָ֤ה הֽוֹדִיָּה֙ שְׁבַנְיָ֣ה פְתַֽחְיָ֔ה ק֗וּמוּ בָּרֲכוּ֙ אֶת יְהוָ֣ה אֱלֹֽהֵיכֶ֔ם מִן הָעוֹלָ֖ם עַד הָעוֹלָ֑ם וִיבָֽרְכוּ֙ שֵׁ֣ם כְּבוֹדֶ֔ךָ וּמְרוֹמַ֥ם עַל כָּל בְּרָכָ֖ה וּתְהִלָּֽה'),
(12518, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 6, 'OT', 'אַתָּה ה֣וּא יְהוָה֮ לְבַדֶּךָ֒ את עָשִׂ֡יתָ אֶֽת הַשָּׁמַיִם֩ שְׁמֵ֨י הַשָּׁמַ֜יִם וְכָל צְבָאָ֗ם הָאָ֜רֶץ וְכָל אֲשֶׁ֤ר עָלֶ֨יהָ֙ הַיַּמִּים֙ וְכָל אֲשֶׁ֣ר בָּהֶ֔ם וְאַתָּ֖ה מְחַיֶּ֣ה אֶת כֻּלָּ֑ם וּצְבָ֥א הַשָּׁמַ֖יִם לְךָ֥ מִשְׁתַּחֲוִֽים'),
(12519, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 7, 'OT', 'אַתָּה הוּא֙ יְהוָ֣ה הָאֱלֹהִ֔ים אֲשֶׁ֤ר בָּחַ֨רְתָּ֙ בְּאַבְרָ֔ם וְהוֹצֵאת֖וֹ מֵא֣וּר כַּשְׂדִּ֑ים וְשַׂ֥מְתָּ שְּׁמ֖וֹ אַבְרָהָֽם'),
(12520, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 8, 'OT', 'וּמָצָ֣אתָ אֶת לְבָבוֹ֮ נֶאֱמָ֣ן לְפָנֶיךָ֒ וְכָר֨וֹת עִמּ֜וֹ הַבְּרִ֗ית לָתֵ֡ת אֶת אֶרֶץ֩ הַכְּנַעֲנִ֨י הַחִתִּ֜י הָאֱמֹרִ֧י וְהַפְּרִזִּ֛י וְהַיְבוּסִ֥י וְהַגִּרְגָּשִׁ֖י לָתֵ֣ת לְזַרְע֑וֹ וַתָּ֨קֶם֙ אֶת דְּבָרֶ֔יךָ כִּ֥י צַדִּ֖יק אָֽתָּה'),
(12521, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 9, 'OT', 'וַתֵּ֛רֶא אֶת עֳנִ֥י אֲבֹתֵ֖ינוּ בְּמִצְרָ֑יִם וְאֶת זַעֲקָתָ֥ם שָׁמַ֖עְתָּ עַל יַם סֽוּף'),
(12522, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 10, 'OT', 'וַ֠תִּתֵּן אֹתֹ֨ת וּמֹֽפְתִ֜ים בְּפַרְעֹ֤ה וּבְכָל עֲבָדָיו֙ וּבְכָל עַ֣ם אַרְצ֔וֹ כִּ֣י יָדַ֔עְתָּ כִּ֥י הֵזִ֖ידוּ עֲלֵיהֶ֑ם וַתַּֽעַשׂ לְךָ֥ שֵׁ֖ם כְּהַיּ֥וֹם הַזֶּֽה'),
(12523, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 11, 'OT', 'וְהַיָּם֙ בָּקַ֣עְתָּ לִפְנֵיהֶ֔ם וַיַּֽעַבְר֥וּ בְתוֹךְ הַיָּ֖ם בַּיַּבָּשָׁ֑ה וְֽאֶת רֹ֨דְפֵיהֶ֜ם הִשְׁלַ֧כְתָּ בִמְצוֹלֹ֛ת כְּמוֹ אֶ֖בֶן בְּמַ֥יִם עַזִּֽים'),
(12524, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 12, 'OT', 'וּבְעַמּ֣וּד עָנָ֔ן הִנְחִיתָ֖ם יוֹמָ֑ם וּבְעַמּ֥וּד אֵשׁ֙ לַ֔יְלָה לְהָאִ֣יר לָהֶ֔ם אֶת הַדֶּ֖רֶךְ אֲשֶׁ֥ר יֵֽלְכוּ בָֽהּ'),
(12525, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 13, 'OT', 'וְעַ֤ל הַר סִינַי֙ יָרַ֔דְתָּ וְדַבֵּ֥ר עִמָּהֶ֖ם מִשָּׁמָ֑יִם וַתִּתֵּ֨ן לָהֶ֜ם מִשְׁפָּטִ֤ים יְשָׁרִים֙ וְתוֹר֣וֹת אֱמֶ֔ת חֻקִּ֥ים וּמִצְוֺ֖ת טוֹבִֽים'),
(12526, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 14, 'OT', 'וְאֶת שַׁבַּ֥ת קָדְשְׁךָ֖ הוֹדַ֣עַתָ לָהֶ֑ם וּמִצְו֤וֹת וְחֻקִּים֙ וְתוֹרָ֔ה צִוִּ֣יתָ לָהֶ֔ם בְּיַ֖ד מֹשֶׁ֥ה עַבְדֶּֽךָ'),
(12527, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 15, 'OT', 'וְ֠לֶחֶם מִשָּׁמַ֜יִם נָתַ֤תָּה לָהֶם֙ לִרְעָבָ֔ם וּמַ֗יִם מִסֶּ֛לַע הוֹצֵ֥אתָ לָהֶ֖ם לִצְמָאָ֑ם וַתֹּ֣אמֶר לָהֶ֗ם לָבוֹא֙ לָרֶ֣שֶׁת אֶת הָאָ֔רֶץ אֲשֶׁר נָשָׂ֥אתָ אֶת יָדְךָ֖ לָתֵ֥ת לָהֶֽם'),
(12528, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 16, 'OT', 'וְהֵ֥ם וַאֲבֹתֵ֖ינוּ הֵזִ֑ידוּ וַיַּקְשׁוּ֙ אֶת עָרְפָּ֔ם וְלֹ֥א שָׁמְע֖וּ אֶל מִצְוֺתֶֽיךָ'),
(12529, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 17, 'OT', 'וַיְמָאֲנ֣וּ לִשְׁמֹ֗עַ וְלֹא זָכְר֤וּ נִפְלְאֹתֶ֨יךָ֙ אֲשֶׁ֣ר עָשִׂ֣יתָ עִמָּהֶ֔ם וַיַּקְשׁוּ֙ אֶת עָרְפָּ֔ם וַיִּתְּנוּ רֹ֛אשׁ לָשׁ֥וּב לְעַבְדֻתָ֖ם בְּמִרְיָ֑ם וְאַתָּה֩ אֱל֨וֹהַּ סְלִיח֜וֹת חַנּ֧וּן וְרַח֛וּם אֶֽרֶךְ אַפַּ֥יִם וְרַב וחסד וְלֹ֥א עֲזַבְתָּֽם'),
(12530, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 18, 'OT', 'אַ֗ף כִּֽי עָשׂ֤וּ לָהֶם֙ עֵ֣גֶל מַסֵּכָ֔ה וַיֹּ֣אמְר֔וּ זֶ֣ה אֱלֹהֶ֔יךָ אֲשֶׁ֥ר הֶעֶלְךָ֖ מִמִּצְרָ֑יִם וַֽיַּעֲשׂ֔וּ נֶאָצ֖וֹת גְּדֹלֽוֹת'),
(12531, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 19, 'OT', 'וְאַתָּה֙ בְּרַחֲמֶ֣יךָ הָֽרַבִּ֔ים לֹ֥א עֲזַבְתָּ֖ם בַּמִּדְבָּ֑ר אֶת עַמּ֣וּד הֶ֠עָנָן לֹא סָ֨ר מֵעֲלֵיהֶ֤ם בְּיוֹמָם֙ לְהַנְחֹתָ֣ם בְּהַדֶּ֔רֶךְ וְאֶת עַמּ֨וּד הָאֵ֤שׁ בְּלַ֨יְלָה֙ לְהָאִ֣יר לָהֶ֔ם וְאֶת הַדֶּ֖רֶךְ אֲשֶׁ֥ר יֵֽלְכוּ בָֽהּ'),
(12532, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 20, 'OT', 'וְרוּחֲךָ֨ הַטּוֹבָ֔ה נָתַ֖תָּ לְהַשְׂכִּילָ֑ם וּמַנְךָ֙ לֹא מָנַ֣עְתָּ מִפִּיהֶ֔ם וּמַ֛יִם נָתַ֥תָּה לָהֶ֖ם לִצְמָאָֽם'),
(12533, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 21, 'OT', 'וְאַרְבָּעִ֥ים שָׁנָ֛ה כִּלְכַּלְתָּ֥ם בַּמִּדְבָּ֖ר לֹ֣א חָסֵ֑רוּ שַׂלְמֹֽתֵיהֶם֙ לֹ֣א בָל֔וּ וְרַגְלֵיהֶ֖ם לֹ֥א בָצֵֽקוּ'),
(12534, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 22, 'OT', 'וַתִּתֵּ֨ן לָהֶ֤ם מַמְלָכוֹת֙ וַעֲמָמִ֔ים וַֽתַּחְלְקֵ֖ם לְפֵאָ֑ה וַיִּֽירְשׁ֞וּ אֶת אֶ֣רֶץ סִיח֗וֹן וְאֶת אֶ֨רֶץ֙ מֶ֣לֶךְ חֶשְׁבּ֔וֹן וְאֶת אֶ֖רֶץ ע֥וֹג מֶֽלֶךְ הַבָּשָֽׁן'),
(12535, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 23, 'OT', 'וּבְנֵיהֶ֣ם הִרְבִּ֔יתָ כְּכֹכְבֵ֖י הַשָּׁמָ֑יִם וַתְּבִיאֵם֙ אֶל הָאָ֔רֶץ אֲשֶׁר אָמַ֥רְתָּ לַאֲבֹתֵיהֶ֖ם לָב֥וֹא לָרָֽשֶׁת'),
(12536, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 24, 'OT', 'וַיָּבֹ֤אוּ הַבָּנִים֙ וַיִּֽירְשׁ֣וּ אֶת הָאָ֔רֶץ וַתַּכְנַ֨ע לִפְנֵיהֶ֜ם אֶת יֹשְׁבֵ֤י הָאָ֨רֶץ֙ הַכְּנַ֣עֲנִ֔ים וַֽתִּתְּנֵ֖ם בְּיָדָ֑ם וְאֶת מַלְכֵיהֶם֙ וְאֶת עַֽמְמֵ֣י הָאָ֔רֶץ לַעֲשׂ֥וֹת בָּהֶ֖ם כִּרְצוֹנָֽם'),
(12537, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 25, 'OT', 'וַֽיִּלְכְּד֞וּ עָרִ֣ים בְּצֻרוֹת֮ וַאֲדָמָ֣ה שְׁמֵנָה֒ וַיִּֽירְשׁ֡וּ בָּתִּ֣ים מְלֵֽאִים כָּל ט֠וּב בֹּר֨וֹת חֲצוּבִ֜ים כְּרָמִ֧ים וְזֵיתִ֛ים וְעֵ֥ץ מַאֲכָ֖ל לָרֹ֑ב וַיֹּאכְל֤וּ וַֽיִּשְׂבְּעוּ֙ וַיַּשְׁמִ֔ינוּ וַיִּֽתְעַדְּנ֖וּ בְּטוּבְךָ֥ הַגָּדֽוֹל'),
(12538, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 26, 'OT', 'וַיַּמְר֨וּ וַֽיִּמְרְד֜וּ בָּ֗ךְ וַיַּשְׁלִ֤כוּ אֶת תּוֹרָֽתְךָ֙ אַחֲרֵ֣י גַוָּ֔ם וְאֶת נְבִיאֶ֣יךָ הָרָ֔גוּ אֲשֶׁר הֵעִ֥ידוּ בָ֖ם לַהֲשִׁיבָ֣ם אֵלֶ֑יךָ וַֽיַּעֲשׂ֔וּ נֶאָצ֖וֹת גְּדוֹלֹֽת'),
(12539, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 27, 'OT', 'וַֽתִּתְּנֵם֙ בְּיַ֣ד צָֽרֵיהֶ֔ם וַיָּצֵ֖רוּ לָהֶ֑ם וּבְעֵ֤ת צָֽרָתָם֙ יִצְעֲק֣וּ אֵלֶ֔יךָ וְאַתָּה֙ מִשָּׁמַ֣יִם תִּשְׁמָ֔ע וּֽכְרַחֲמֶ֣יךָ הָֽרַבִּ֗ים תִּתֵּ֤ן לָהֶם֙ מֽוֹשִׁיעִ֔ים וְיוֹשִׁיע֖וּם מִיַּ֥ד צָרֵיהֶֽם'),
(12540, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 28, 'OT', 'וּכְנ֣וֹחַ לָהֶ֔ם יָשׁ֕וּבוּ לַעֲשׂ֥וֹת רַ֖ע לְפָנֶ֑יךָ וַתַּֽעַזְבֵ֞ם בְּיַ֤ד אֹֽיְבֵיהֶם֙ וַיִּרְדּ֣וּ בָהֶ֔ם וַיָּשׁ֨וּבוּ֙ וַיִּזְעָק֔וּךָ וְאַתָּ֞ה מִשָּׁמַ֧יִם תִּשְׁמַ֛ע וְתַצִּילֵ֥ם כְּֽרַחֲמֶ֖יךָ רַבּ֥וֹת עִתִּֽים'),
(12541, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 29, 'OT', 'וַתָּ֨עַד בָּהֶ֜ם לַהֲשִׁיבָ֣ם אֶל תּוֹרָתֶ֗ךָ וְהֵ֨מָּה הֵזִ֜ידוּ וְלֹא שָׁמְע֤וּ לְמִצְוֺתֶ֨יךָ֙ וּבְמִשְׁפָּטֶ֣יךָ חָֽטְאוּ בָ֔ם אֲשֶׁר יַעֲשֶׂ֥ה אָדָ֖ם וְחָיָ֣ה בָהֶ֑ם וַיִּתְּנ֤וּ כָתֵף֙ סוֹרֶ֔רֶת וְעָרְפָּ֥ם הִקְשׁ֖וּ וְלֹ֥א שָׁמֵֽעוּ'),
(12542, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 30, 'OT', 'וַתִּמְשֹׁ֤ךְ עֲלֵיהֶם֙ שָׁנִ֣ים רַבּ֔וֹת וַתָּ֨עַד בָּ֧ם בְּרוּחֲךָ֛ בְּיַד נְבִיאֶ֖יךָ וְלֹ֣א הֶאֱזִ֑ינוּ וַֽתִּתְּנֵ֔ם בְּיַ֖ד עַמֵּ֥י הָאֲרָצֹֽת'),
(12543, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 31, 'OT', 'וּֽבְרַחֲמֶ֧יךָ הָרַבִּ֛ים לֹֽא עֲשִׂיתָ֥ם כָּלָ֖ה וְלֹ֣א עֲזַבְתָּ֑ם כִּ֛י אֵֽל חַנּ֥וּן וְרַח֖וּם אָֽתָּה'),
(12544, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 32, 'OT', 'וְעַתָּ֣ה אֱ֠לֹהֵינוּ הָאֵ֨ל הַגָּד֜וֹל הַגִּבּ֣וֹר וְהַנּוֹרָא֮ שׁוֹמֵ֣ר הַבְּרִ֣ית וְהַחֶסֶד֒ אַל יִמְעַ֣ט לְפָנֶ֡יךָ אֵ֣ת כָּל הַתְּלָאָ֣ה אֲֽשֶׁר מְ֠צָאַתְנוּ לִמְלָכֵ֨ינוּ לְשָׂרֵ֧ינוּ וּלְכֹהֲנֵ֛ינוּ וְלִנְבִיאֵ֥נוּ וְלַאֲבֹתֵ֖ינוּ וּלְכָל עַמֶּ֑ךָ מִימֵי֙ מַלְכֵ֣י אַשּׁ֔וּר עַ֖ד הַיּ֥וֹם הַזֶּֽה'),
(12545, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 33, 'OT', 'וְאַתָּ֣ה צַדִּ֔יק עַ֖ל כָּל הַבָּ֣א עָלֵ֑ינוּ כִּֽי אֱמֶ֥ת עָשִׂ֖יתָ וַאֲנַ֥חְנוּ הִרְשָֽׁעְנוּ'),
(12546, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 34, 'OT', 'וְאֶת מְלָכֵ֤ינוּ שָׂרֵ֨ינוּ֙ כֹּהֲנֵ֣ינוּ וַאֲבֹתֵ֔ינוּ לֹ֥א עָשׂ֖וּ תּוֹרָתֶ֑ךָ וְלֹ֤א הִקְשִׁ֨יבוּ֙ אֶל מִצְוֺתֶ֔יךָ וּלְעֵ֣דְוֺתֶ֔יךָ אֲשֶׁ֥ר הַעִידֹ֖תָ בָּהֶֽם'),
(12547, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 35, 'OT', 'וְהֵ֣ם בְּמַלְכוּתָם֩ וּבְטוּבְךָ֨ הָרָ֜ב אֲשֶׁר נָתַ֣תָּ לָהֶ֗ם וּבְאֶ֨רֶץ הָרְחָבָ֧ה וְהַשְּׁמֵנָ֛ה אֲשֶׁר נָתַ֥תָּ לִפְנֵיהֶ֖ם לֹ֣א עֲבָד֑וּךָ וְֽלֹא שָׁ֔בוּ מִמַּֽעַלְלֵיהֶ֖ם הָרָעִֽים'),
(12548, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 36, 'OT', 'הִנֵּ֛ה אֲנַ֥חְנוּ הַיּ֖וֹם עֲבָדִ֑ים וְהָאָ֜רֶץ אֲשֶׁר נָתַ֣תָּה לַאֲבֹתֵ֗ינוּ לֶאֱכֹ֤ל אֶת פִּרְיָהּ֙ וְאֶת טוּבָ֔הּ הִנֵּ֛ה אֲנַ֥חְנוּ עֲבָדִ֖ים עָלֶֽיהָ'),
(12549, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 37, 'OT', 'וּתְבוּאָתָ֣הּ מַרְבָּ֗ה לַמְּלָכִ֛ים אֲשֶׁר נָתַ֥תָּה עָלֵ֖ינוּ בְּחַטֹּאותֵ֑ינוּ וְעַ֣ל גְּ֠וִיֹּתֵינוּ מֹשְׁלִ֤ים וּבִבְהֶמְתֵּ֨נוּ֙ כִּרְצוֹנָ֔ם וּבְצָרָ֥ה גְדוֹלָ֖ה אֲנָֽחְנוּ'),
(12550, 16, 'WLC', 'WLC', 'he', 'NEH', 9, 38, 'OT', 'וּבְכָל זֹ֕את אֲנַ֛חְנוּ כֹּרְתִ֥ים אֲמָנָ֖ה וְכֹתְבִ֑ים וְעַל֙ הֶֽחָת֔וּם שָׂרֵ֥ינוּ לְוִיֵּ֖נוּ כֹּהֲנֵֽינוּ'),
(12551, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 1, 'OT', 'וְעַ֖ל הַחֲתוּמִ֑ים נְחֶמְיָ֧ה הַתִּרְשָׁ֛תָא בֶּן חֲכַלְיָ֖ה וְצִדְקִיָּֽה'),
(12552, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 2, 'OT', 'שְׂרָיָ֥ה עֲזַרְיָ֖ה יִרְמְיָֽה'),
(12553, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 3, 'OT', 'פַּשְׁח֥וּר אֲמַרְיָ֖ה מַלְכִּיָּֽה'),
(12554, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 4, 'OT', 'חַטּ֥וּשׁ שְׁבַנְיָ֖ה מַלּֽוּךְ'),
(12555, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 5, 'OT', 'חָרִ֥ם מְרֵמ֖וֹת עֹֽבַדְיָֽה'),
(12556, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 6, 'OT', 'דָּנִיֵּ֥אל גִּנְּת֖וֹן בָּרֽוּךְ'),
(12557, 16, 'WLC', 'WLC', 'he', 'NEH', 10, 7, 'OT', 'מְשֻׁלָּ֥ם אֲבִיָּ֖ה מִיָּמִֽן'),
