(22020, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 4, 'OT', 'וּבְי֛וֹם עֶשְׂרִ֥ים וְאַרְבָּעָ֖ה לַחֹ֣דֶשׁ הָרִאשׁ֑וֹן וַאֲנִ֗י הָיִ֛יתִי עַ֣ל יַ֧ד הַנָּהָ֛ר הַגָּד֖וֹל ה֥וּא חִדָּֽקֶל'),
(22021, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 5, 'OT', 'וָאֶשָּׂ֤א אֶת עֵינַי֙ וָאֵ֔רֶא וְהִנֵּ֥ה אִישׁ אֶחָ֖ד לָב֣וּשׁ בַּדִּ֑ים וּמָתְנָ֥יו חֲגֻרִ֖ים בְּכֶ֥תֶם אוּפָֽז'),
(22022, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 6, 'OT', 'וּגְוִיָּת֣וֹ כְתַרְשִׁ֗ישׁ וּפָנָ֞יו כְּמַרְאֵ֤ה בָרָק֙ וְעֵינָיו֙ כְּלַפִּ֣ידֵי אֵ֔שׁ וּזְרֹֽעֹתָיו֙ וּמַרְגְּלֹתָ֔יו כְּעֵ֖ין נְחֹ֣שֶׁת קָלָ֑ל וְק֥וֹל דְּבָרָ֖יו כְּק֥וֹל הָמֽוֹן'),
(22023, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 7, 'OT', 'וְרָאִיתִי֩ אֲנִ֨י דָנִיֵּ֤אל לְבַדִּי֙ אֶת הַמַּרְאָ֔ה וְהָאֲנָשִׁים֙ אֲשֶׁ֣ר הָי֣וּ עִמִּ֔י לֹ֥א רָא֖וּ אֶת הַמַּרְאָ֑ה אֲבָ֗ל חֲרָדָ֤ה גְדֹלָה֙ נָפְלָ֣ה עֲלֵיהֶ֔ם וַֽיִּבְרְח֖וּ בְּהֵחָבֵֽא'),
(22024, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 8, 'OT', 'וַאֲנִי֙ נִשְׁאַ֣רְתִּי לְבַדִּ֔י וָֽאֶרְאֶ֗ה אֶת הַמַּרְאָ֤ה הַגְּדֹלָה֙ הַזֹּ֔את וְלֹ֥א נִשְׁאַר בִּ֖י כֹּ֑ח וְהוֹדִ֗י נֶהְפַּ֤ךְ עָלַי֙ לְמַשְׁחִ֔ית וְלֹ֥א עָצַ֖רְתִּי כֹּֽחַ'),
(22025, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 9, 'OT', 'וָאֶשְׁמַ֖ע אֶת ק֣וֹל דְּבָרָ֑יו וּכְשָׁמְעִי֙ אֶת ק֣וֹל דְּבָרָ֔יו וַאֲנִ֗י הָיִ֛יתִי נִרְדָּ֥ם עַל פָּנַ֖י וּפָנַ֥י אָֽרְצָה'),
(22026, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 10, 'OT', 'וְהִנֵּה יָ֖ד נָ֣גְעָה בִּ֑י וַתְּנִיעֵ֥נִי עַל בִּרְכַּ֖י וְכַפּ֥וֹת יָדָֽי'),
(22027, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 11, 'OT', 'וַיֹּ֣אמֶר אֵלַ֡י דָּנִיֵּ֣אל אִישׁ חֲ֠מֻדוֹת הָבֵ֨ן בַּדְּבָרִ֜ים אֲשֶׁר֩ אָנֹכִ֨י דֹבֵ֤ר אֵלֶ֨יךָ֙ וַעֲמֹ֣ד עַל עָמְדֶ֔ךָ כִּ֥י עַתָּ֖ה שֻׁלַּ֣חְתִּי אֵלֶ֑יךָ וּבְדַבְּר֥וֹ עִמִּ֛י אֶת הַדָּבָ֥ר הַזֶּ֖ה עָמַ֥דְתִּי מַרְעִֽיד'),
(22028, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 12, 'OT', 'וַיֹּ֣אמֶר אֵלַי֮ אַל תִּירָ֣א דָנִיֵּאל֒ כִּ֣י מִן הַיּ֣וֹם הָרִאשׁ֗וֹן אֲשֶׁ֨ר נָתַ֧תָּ אֶֽת לִבְּךָ֛ לְהָבִ֧ין וּלְהִתְעַנּ֛וֹת לִפְנֵ֥י אֱלֹהֶ֖יךָ נִשְׁמְע֣וּ דְבָרֶ֑יךָ וַאֲנִי בָ֖אתִי בִּדְבָרֶֽיךָ'),
(22029, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 13, 'OT', 'וְשַׂ֣ר מַלְכ֣וּת פָּרַ֗ס עֹמֵ֤ד לְנֶגְדִּי֙ עֶשְׂרִ֣ים וְאֶחָ֣ד י֔וֹם וְהִנֵּ֣ה מִֽיכָאֵ֗ל אַחַ֛ד הַשָּׂרִ֥ים הָרִאשֹׁנִ֖ים בָּ֣א לְעָזְרֵ֑נִי וַאֲנִי֙ נוֹתַ֣רְתִּי שָׁ֔ם אֵ֖צֶל מַלְכֵ֥י פָרָֽס'),
(22030, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 14, 'OT', 'וּבָ֨אתִי֙ לַהֲבִ֣ינְךָ֔ אֵ֛ת אֲשֶׁר יִקְרָ֥ה לְעַמְּךָ֖ בְּאַחֲרִ֣ית הַיָּמִ֑ים כִּי ע֥וֹד חָז֖וֹן לַיָּמִֽים'),
(22031, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 15, 'OT', 'וּבְדַבְּר֣וֹ עִמִּ֔י כַּדְּבָרִ֖ים הָאֵ֑לֶּה נָתַ֧תִּי פָנַ֛י אַ֖רְצָה וְנֶאֱלָֽמְתִּי'),
(22032, 27, 'WLC', 'WLC', 'he', 'DAN', 10, 16, 'OT', 'וְהִנֵּ֗ה כִּדְמוּת֙ בְּנֵ֣י אָדָ֔ם נֹגֵ֖עַ עַל שְׂפָתָ֑י וָאֶפְתַּח פִּ֗י וָאֲדַבְּרָה֙ וָאֹֽמְרָה֙ אֶל הָעֹמֵ֣ד לְנֶגְדִּ֔י אֲדֹנִ֗י בַּמַּרְאָה֙ נֶהֶפְכ֤וּ צִירַי֙ עָלַ֔י וְלֹ֥א עָצַ֖רְתִּי כֹּֽחַ'),
